export const ERP_APPS_ROUTES = [{"path":"/erp/apps","publishedAt":"2026-09-27","title":"NDT ERP Apps: Reports, Certificates, eLearning & More | Atlantis NDT","description":"All 28 apps in the Atlantis NDT ERP, from NDT Reports and technician Certificates to Team Assignments, Quotations and eLearning. Book a demo or request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Every app in the Atlantis NDT ERP</h1>\n<p>One system for an NDT company: 28 apps covering inspection reports, technician certifications, crews, quotes, invoicing and training. Start with the apps you need and add the rest when you're ready. <a href=\"/contact?service=erp&amp;subject=ERP%20demo%20(all%20apps)\">Request a demo</a>.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Inspection &amp; Quality</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<h2>Training</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning</a>: Courses, quizzes and certificates for technician training and refreshers.</li><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<h2>Field Operations</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<h2>Sales &amp; Growth</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<h2>Finance &amp; Supply</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing</a>: Invoices from timesheets and completed jobs, with payments and reminders.</li><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<h2>People &amp; Collaboration</h2><ul><li><a href=\"/erp/apps/employees\">Employees</a>: Technician records, levels, documents and contracts.</li><li><a href=\"/erp/apps/time-off\">Time Off</a>: Leave requests and allocations, visible to crew planners.</li><li><a href=\"/erp/apps/discuss\">Discuss</a>: Team chat and channels, threaded onto jobs and records.</li></ul>\n<h2>Not sure which apps you need?</h2><p>Tell us how your NDT business runs today and we'll suggest where to start. <a href=\"/contact?service=erp&amp;subject=Which%20ERP%20apps%20do%20we%20need%3F\">Talk to us</a>.</p>\n</main>"},{"path":"/erp/apps/asset-management","publishedAt":"2026-09-27","title":"NDT Equipment & Calibration Tracking Software | Atlantis NDT","description":"Track every NDT instrument, probe and calibration certificate by serial, with issue/return, reservations and expiry alerts. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Equipment and Calibration Management Software</h1>\n<p>NDT equipment by serial number: issue and return, reservations, calibration and maintenance history. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>What the Asset Management app does for an NDT company</h2><p>Every inspection company has the same drawer of problems. A flaw detector that was definitely returned is still in a technician's truck two hundred miles away. A phased array probe went out with a crew and came back with a cracked wedge, and nobody can say which job it was on. The calibration certificate for a UV-A meter is buried in an email thread, and the client's QA auditor wants it now. The Asset Management app in Atlantis NDT ERP exists to close that drawer.</p><p>It is an equipment and instrument register built for NDT work: ultrasonic flaw detectors, thickness gauges, phased array and TOFD units, eddy current instruments, probes and wedges, yokes and UV lamps, light meters, densitometers, radiography exposure devices and survey meters, calibration blocks and step wedges. Each item is tracked by serial number from the day it arrives to the day it is retired or disposed of, with its calibration, maintenance, issue history and current holder in one place.</p><p>It is worth being precise about what it is not. This app manages the tools your company owns or rents. It is not plant integrity software: it does not model your client's vessels, piping circuits or tanks, store wall-thickness history for their equipment or plan their inspection intervals. Those belong to the asset owner's own systems. The Asset Management app answers a narrower and very practical question that every NDT manager asks each morning: what kit do we have, where is it, who has it, and is it fit to use today?</p><p>It is one of the apps in <a href=\"/erp\">Atlantis NDT ERP</a>, our pre-configured and customised Odoo system for inspection companies, and it works alongside the other NDT apps rather than as a stand-alone spreadsheet replacement.</p><h2>One record per serial number</h2><p>The foundation is a single record for every serialised item. Each record carries the equipment type, serial number, asset tag, firmware version, the accessories supplied with it, the person it is assigned to, its current condition and its lifecycle stage. Lifecycle stages follow what really happens to NDT kit: new, active, in calibration, in repair, rented out, retired and disposed. At a glance you can see that the second phased array unit is away for calibration, the spare thickness gauge is in repair and three yokes are rented out to another contractor.</p><p>Firmware matters more than most registers admit. When a manufacturer releases an update that changes a setup file format or a sizing feature, you need to know which units run which version before a crew loads a procedure setup on site. Recording firmware on the serial record, and logging firmware updates in the maintenance history, gives you that answer without phoning every technician.</p><p>Accessories are the other quiet source of losses. A flaw detector rarely travels alone: it goes out with cables, a battery pack, a charger, a carry case, perhaps a set of probes and a calibration block. Listing the accessories on the record means the storeman checks the same list at issue and at return, and a missing charger is noticed at the counter rather than at the next job.</p><p>Each item also carries its calibration frequency and a calibration status, so the register never presents an instrument as ready for work when its certificate has lapsed. If you hire equipment out, rental rates can be recorded against the item, which keeps the commercial side of a rented-out flaw detector next to its technical history.</p><h2>Issue and return with approvals</h2><p>Most equipment losses in inspection companies are not theft. They are handovers nobody wrote down: one technician passes a gauge to another on site, a crew leader takes an extra probe just in case, kit sits in a hotel room after demobilisation. The issue and return workflow puts a record on every one of those moments.</p><p>When a technician needs equipment, an issue request is raised against specific serial numbers. It goes to a supervisor and then a manager for approval, which matters most for high-value or controlled items such as phased array units, radiography exposure devices and survey meters. The condition of each item is recorded at issue. When the item comes back, condition is recorded again at return. If a wedge left in good order and came back worn through, the record shows exactly who had it and for which period.</p><p>That condition trail does two jobs. It lets you have a fair, fact-based conversation with a technician or a client about damage instead of an argument. And it tells the equipment coordinator what needs attention before the item goes out again: a return marked as damaged should go to repair, not back on the shelf.</p><p>Because every issue has a holder and dates, overdue returns become visible. The NDT dashboards in the ERP include issued equipment overdue as a KPI alongside calibration due and overdue, so the operations manager sees late returns in the same view as expiring certificates instead of finding them at the next stock count.</p><p>For field teams, the ERP's REST API for field devices includes an equipment-issued-to-me call, so a technician's device can show what they are currently signed out for. That small detail removes a lot of end-of-job confusion.</p><h2>Reservations and movements</h2><p>Double-booking equipment is the scheduling problem that follows double-booking technicians. Two project managers both plan to use the only TOFD unit next Tuesday, and one of them finds out when the crate is empty. Reservations deal with this. An item can be reserved for a period, and the app prevents a clashing reservation for the same serial over overlapping dates. The second planner sees the clash at the moment of booking, while there is still time to rent, borrow or reschedule.</p><p>Reservations sit alongside inbound and outbound movement records. Every time an item leaves the base or comes back, whether to site, to a calibration lab, to the manufacturer for repair or to a company that rented it, a movement is logged. Over a year that builds a clean movement history for each serial. It helps when an insurer asks where an item was, when a client asks which instrument was used on their shutdown, or when you are deciding whether a unit that spends half its life in repair is worth keeping.</p><p>Reservations also line up with the <a href=\"/erp/apps/team-assignments\">Team Assignments</a> app, which handles crew dispatch. When a job is planned there, assigning an equipment serial that is already committed to another job is blocked, just as double-booking a technician is. And if an assigned instrument is out of calibration, the planner gets a warning before the crew mobilises, not after the client's inspector has checked the certificate at the gate.</p><h2>Calibration records and the certificate register</h2><p>Calibration is where equipment records are audited most often and are most often weak. Clients, third-party inspectors and certification auditors all ask the same thing: show me that this instrument, with this serial, was within calibration on the date of this report, and show me who calibrated it.</p><p>Each calibration event is recorded against the serial with the calibration provider, certificate number, the standard used, the range calibrated, the uncertainty stated on the certificate, whether the lab is accredited, the result (pass, fail or conditional) and the next due date. A conditional result is worth capturing properly: an instrument that passed with a limitation on range should not be issued for work outside that range, and the record makes the limitation visible to whoever issues it.</p><p>Alongside the event history there is a calibration certificate register. Each certificate is stored with its PDF, the lab's accreditation number and a status that moves between valid, expiring and expired. Expiry alerts go out before the due date, and the ERP's daily email alerts for calibration certificates can be configured with recipients, how many days ahead to look and how often to resend. Nobody should discover an expired certificate when a client auditor asks for it.</p><p>Calibration labs themselves are handled in Purchase. Vendors can be typed as OEM, dealer or calibration lab, with an accredited-lab flag, accreditation number and accreditation expiry, and purchase order lines can be linked to the specific equipment serial being sent. The calibration spend, the lab's accreditation status and the resulting certificate all tie back to the same instrument.</p><h2>Maintenance log: what happened to this instrument</h2><p>Calibration tells you an instrument measured correctly on the day it was checked. The maintenance log tells you what happened in between. Every entry is typed as preventive, corrective, repair, cleaning, firmware update or probe replacement, and records the condition before and after the work.</p><p>In practice that covers the daily reality of an NDT equipment room: a yoke with a frayed cable repaired, a UT cable replaced, a phased array unit back from the manufacturer after a connector fault, a probe replaced after wear-face damage, an instrument cleaned and dried after a job in heavy rain or a dusty yard. Each entry sits in the serial's history, so when an instrument starts giving intermittent trouble you can see the pattern instead of guessing.</p><p>Probe replacement entries are especially useful for ultrasonic work. Probes wear, delaminate and get dropped, and the probe named on a report needs to be the one that was checked. On the reporting side, the ERP's NDT Reports app carries a probe calibration table on UT reports, so the report and the equipment history tell the same story.</p><p>For wider planned maintenance, the standard Odoo Maintenance app is set up for NDT companies to raise preventive and corrective requests on instruments, vehicles and site equipment, so a recurring check can be scheduled and a breakdown can be reported from the field without a phone call to the office.</p><h2>Consumables: couplant, chemicals, PPE and stationery</h2><p>Consumables are unglamorous and constantly short. A PT crew arrives on site with two cans of developer for a job that needs ten. The magnetic particle ink ran out last week and nobody reordered. Couplant, cleaners, penetrant, developer, contrast paint, PPE and even stationery such as report pads and paint markers are what keep a crew productive.</p><p>The app tracks consumables with a reorder level for each item and a low-stock flag when stock falls below it. A movement ledger records every issue and receipt, so you can see which jobs use what and spot a site that consumes far more penetrant than its scope suggests. With the ERP's Inventory app, which holds stock of equipment by serial and of consumables, the store has one view instead of a shelf count and a guess.</p><p>Consumables matter commercially too. The Invoicing app has separate subtotals for labour, equipment and consumables on each invoice, so materials used on a job can be billed where your contract allows rather than quietly absorbed.</p><p>Batch tracking for penetrant and magnetic particle materials, or shelf-life checks on particular chemicals, can be configured during implementation if your procedures or clients require them. That is part of the customisation scope agreed with you, not something to assume out of the box.</p><h2>How it connects to the rest of the ERP</h2><ul><li><strong>Team Assignments:</strong> blocks double-booking of equipment serials and warns when assigned equipment is out of calibration.</li><li><strong>Project and Timesheets:</strong> projects list the assigned equipment, and timesheet lines can carry the equipment serial used, which gives you real usage evidence per instrument.</li><li><strong>Invoicing:</strong> invoice lines can carry the equipment serial, method and technician, with an equipment subtotal, so equipment charges are based on what was actually used.</li><li><strong>Purchase:</strong> calibration labs, OEMs and dealers as typed vendors with accreditation details, and order lines linked to serials.</li><li><strong>Fleet:</strong> vehicles record whether they can carry radioactive sources, with the transport licence number and expiry, and are assigned to projects and drivers.</li><li><strong>Certificates:</strong> the same daily alert engine that warns about technician certifications covers calibration certificates.</li><li><strong>Dashboards:</strong> calibration due and overdue, and issued equipment overdue, as NDT KPIs.</li><li><strong>NDT Reports:</strong> field devices can pull the equipment issued to a technician, and in marine mode the report PDF merges the calibration certificate.</li></ul><p>Inspection results live on the reporting side. If your clients want to see those results placed on a 3D model of their asset, that is our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP's NDT Reports app. The Asset Management app stays focused on your own instruments.</p><h2>Who uses it day to day</h2><p><strong>Equipment coordinators and storemen</strong> live in the app: issuing and receiving kit, recording condition, logging movements, reordering consumables and chasing calibrations.</p><p><strong>Supervisors and managers</strong> approve issue requests, especially for high-value or controlled items, and review damage reports and overdue returns.</p><p><strong>Operations managers and planners</strong> use reservations and the Team Assignments link to plan jobs around real availability, and see calibration and overdue-return KPIs on their dashboard.</p><p><strong>QA/QC managers and the Level III</strong> use calibration records and the certificate register to answer audits, confirm that equipment named on a report was in calibration, and agree the calibration frequencies set for each equipment type.</p><p><strong>Radiation safety officers</strong> can see who holds each exposure device and survey meter and where it has moved, with source-carrying vehicles in Fleet. Records specific to your radioactive material licence, such as source inventories or leak test logs in the format your regulator expects, are scoped during implementation rather than assumed.</p><p><strong>Technicians</strong> see what they are signed out for and return it with a recorded condition. <strong>Finance</strong> sees equipment on invoices and rental rates where you hire kit out.</p><h2>Implementation: getting your equipment into the system</h2><p>Atlantis NDT sets the app up with you rather than handing over an empty database. A typical implementation runs like this:</p><ol><li><strong>Equipment import.</strong> Your existing register, usually a spreadsheet, is cleaned and imported: serials, types, asset tags, firmware, accessories, current holder and lifecycle stage.</li><li><strong>Calibration history.</strong> Current certificates are loaded with PDFs, lab details and due dates, so alerts work from day one.</li><li><strong>Frequencies and rules.</strong> Calibration frequencies per equipment type are agreed with your Level III and QA manager, and approval steps for issue requests are set to match your procedures.</li><li><strong>Consumables.</strong> Items, units and reorder levels are set up for each store or base.</li><li><strong>Alerts and dashboards.</strong> Recipients, look-ahead days and resend intervals for calibration alerts are configured, and the NDT KPI dashboard is set up for managers.</li><li><strong>Customisation.</strong> Anything specific to your company, such as extra fields for regulator records, a custom issue form or client-specific checks, is agreed as part of the customisation scope.</li><li><strong>Training.</strong> Storemen, planners and technicians are shown the workflows they will actually use.</li></ol><p>Cost is quoted on request based on your scope. The aim is affordable, accessible and fully customisable: you pay for the setup you need. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo\">Book an Asset Management demo</a> and bring your current equipment spreadsheet; we will show you how it maps.</p><h2>Frequently asked questions</h2><h3>Is this asset integrity or inspection data management software?</h3><p>No. It manages your company's own NDT equipment and instruments: serial register, issue and return, reservations, calibration, maintenance and consumables. Your clients' plant equipment, its inspection history and integrity assessments are not part of this app.</p><h3>Can it track calibration blocks and reference standards as well as instruments?</h3><p>Yes. Any serialised item can have a record, calibration frequency and certificate history, including calibration blocks, step wedges, reference standards, light meters, UV-A meters and densitometers.</p><h3>Does it stop a technician using an out-of-calibration instrument?</h3><p>It makes it very hard to happen by accident. Calibration status sits on each record, expiry alerts go out ahead of time, and Team Assignments warns the planner when assigned equipment is out of calibration. The final check still belongs to your procedures and your people.</p><h3>Can we track equipment we hire out?</h3><p>Yes. Items can be set to the rented-out lifecycle stage, rental rates can be recorded, and outbound and inbound movements show when the item left and came back.</p><h3>Does it handle radiography equipment?</h3><p>Exposure devices, source containers, survey meters and related items can be tracked by serial with issue and return, approvals, movements, maintenance and calibration. Source activity calculations and regulator-specific logbooks are not built in; if you need them in the ERP, they are scoped during implementation.</p><h3>How long does setup take?</h3><p>It depends mostly on the state of your current register and how many sites you run. After a demo we look at your data and agree a realistic plan with you.</p><h2>See it with your own equipment list</h2><p>The quickest way to judge the app is to see your own kit in it: your flaw detectors, your probes, your calibration certificates and your consumables. Browse the other <a href=\"/erp/apps\">ERP apps</a> to see how the pieces fit, then <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20quote\">request an Asset Management quote</a> for your company.</p>\n<h2>Asset Management by region</h2><ul><li><a href=\"/erp/apps/asset-management/usa\">Asset Management in United States</a></li><li><a href=\"/erp/apps/asset-management/canada\">Asset Management in Canada</a></li><li><a href=\"/erp/apps/asset-management/europe\">Asset Management in UK &amp; Europe</a></li><li><a href=\"/erp/apps/asset-management/middle-east\">Asset Management in Middle East</a></li><li><a href=\"/erp/apps/asset-management/india\">Asset Management in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo\">Send an enquiry about Asset Management</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/asset-management/usa","publishedAt":"2026-09-27","title":"NDT Equipment Calibration Tracking, USA | Atlantis NDT","description":"NDT equipment and calibration tracking for US inspection companies: serial register, issue/return, accredited-lab certificates, alerts. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Equipment and Calibration Management in the USA</h1>\n<p>NDT equipment by serial number: issue and return, reservations, calibration and maintenance history. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Equipment control for US inspection companies</h2><p>If you run an NDT company in the United States, your equipment works hard and travels far. A flaw detector might spend spring on a turnaround in Pasadena or Deer Park, summer on a pipeline spread in West Texas, and autumn in a fabrication shop in Louisiana. Crews move between Houston, Baton Rouge, Lake Charles, Beaumont and Port Arthur and Corpus Christi, often in company trucks packed with kit that was signed out by one person and used by three. Somewhere along the way, a probe goes missing, a certificate lapses and a client auditor asks a question nobody can answer quickly.</p><p>The Asset Management app in Atlantis NDT ERP is the register that keeps up with that. Every instrument, probe, calibration block, exposure device and survey meter is tracked by serial number, with its holder, condition, lifecycle stage, calibration status and history. It is built for your equipment, not your clients' plant. It does not hold refinery piping circuits, wall-thickness history or inspection intervals for the owner's vessels. It answers the questions that land on an NDT operations manager's desk: what do we own, where is it, who has it, and can it legally and technically go to work tomorrow?</p><p>The app is part of <a href=\"/erp\">Atlantis NDT ERP</a>, a pre-configured and customised Odoo system for inspection companies, set up for you by Atlantis NDT.</p><h2>What the app tracks</h2><p>Each serialised item carries equipment type, serial number, asset tag, firmware version, accessories, assigned person, condition and a lifecycle stage: new, active, in calibration, in repair, rented out, retired or disposed. Calibration frequency and status sit on the same record, and rental rates can be recorded where you hire kit out.</p><p>Around that record the app adds the workflows a US inspection company runs every week:</p><ul><li><strong>Issue and return</strong> against specific serials, with supervisor and manager approval and condition recorded at both ends.</li><li><strong>Reservations</strong> with clash prevention, so two project managers cannot book the same phased array unit for overlapping dates.</li><li><strong>Inbound and outbound movements</strong> to site, to calibration labs, to the manufacturer and to rental customers.</li><li><strong>Maintenance log</strong> entries typed as preventive, corrective, repair, cleaning, firmware update or probe replacement, with condition before and after.</li><li><strong>Calibration records</strong> with provider, certificate number, standard, range, stated uncertainty, accredited-lab flag, pass, fail or conditional result and next due date.</li><li><strong>Calibration certificate register</strong> with lab accreditation number, PDF, valid, expiring or expired status and expiry alerts.</li><li><strong>Consumables</strong> such as couplant, penetrant, developer, cleaner, MT ink and PPE, with reorder levels, low-stock flags and a movement ledger.</li></ul><h2>Calibration evidence US clients and auditors ask for</h2><p>In US refining, petrochemical and fabrication work, equipment calibration is checked by more people than most companies expect. The owner's inspection group, the API 510, 570 or 653 inspector on the job, the authorized inspector on code fabrication and your own QA auditor all want proof that the instrument used for a report was in calibration on that date.</p><p>ASME Section V sets much of the expectation. For ultrasonic examination, Article 4 calls for periodic instrument linearity checks, screen height and amplitude control, alongside calibration against the specified blocks, and many written practices and client specifications add their own calibration intervals on top. The calibration record in the app captures what those audits look for: the lab or provider, the certificate number, the standard used, the range, the result and the next due date. Your Level III sets the frequency per equipment type, and the register shows status without anyone doing date arithmetic.</p><p>Accreditation is the second question. Most US NDT companies send instruments to labs accredited to ISO/IEC 17025 by A2LA or ANAB, and some reference NVLAP-accredited labs, with traceability to NIST stated on the certificate. The app records the accredited-lab flag on each calibration and the lab's accreditation number on the certificate register. In Purchase, calibration labs are typed vendors with the accreditation number and accreditation expiry, so you notice if a lab's scope lapses before you send it another UT set.</p><p>When the auditor asks, you open the serial and show the certificate PDF, not a folder search.</p><h2>Aerospace shops: NAS 410 and equipment checks</h2><p>US aerospace NDT shops live with a different rhythm. Personnel are qualified to NAS 410, work is done to prime contractor specifications, and Nadcap auditors look closely at equipment control. Magnetic particle work to ASTM E1444 and penetrant work to ASTM E1417 depend on a lot of small instruments being right: UV-A meters, visible light meters, ammeters on wet horizontal benches, shot timers, magnetic field indicators and the like.</p><p>Each of those can have its own serial record, calibration frequency and certificate history in the app, so the black light meter used at the start of the shift is provably in calibration. Periodic equipment performance checks that your procedures require can be recorded against the item, and the results sit in the same history the auditor sees. If your shop needs a particular daily check sheet laid out the way a prime or Nadcap checklist expects, that layout is configured during implementation as part of the agreed customisation scope.</p><p>The certificate register's expiry alerts are what make the difference in an aerospace shop. A UV-A meter drifting out of calibration unnoticed can put a whole batch of fluorescent penetrant inspections in question. Alerts sent ahead of the due date, to the people you choose and repeated at the interval you choose, keep that from happening quietly.</p><h2>Radiography: NRC, Agreement States and DOT transport</h2><p>Industrial radiography in the US runs under 10 CFR Part 34, administered by the NRC directly or by Agreement State programmes such as the Texas Department of State Health Services and the Louisiana Department of Environmental Quality. Among other things, the rules expect survey instruments to be calibrated at intervals not exceeding six months and exposure devices, associated equipment and transport containers to be inspected and maintained at intervals not exceeding three months. Transport of sources falls under DOT hazardous materials rules in 49 CFR.</p><p>The Asset Management app gives your radiation safety officer a clean equipment side of that picture. Exposure devices, guide tubes, collimators, survey meters, alarm ratemeters and source containers each get a serial record. Survey meter calibrations go in as calibration records with certificate, result and due date, and the register flags them before they expire. Quarterly inspection and maintenance of exposure devices can be logged in the maintenance history with condition before and after. Issue requests for cameras and survey meters go through supervisor and manager approval, and movements show where each item has been.</p><p>Source-carrying vehicles sit in the Fleet app, which records whether a vehicle can carry radioactive sources, its transport licence number and expiry, and which project and driver it is assigned to.</p><p>What is not built in: licence-format utilization logs, quarterly source inventories and leak test records as your regulator prescribes them, or source activity calculations. If you want those in the ERP, they are scoped with your RSO during implementation.</p><h2>Pipeline spreads and travelling crews</h2><p>Pipeline construction and integrity work, whether welds shot to API 1104 on a new spread or excavation inspections for an operator's PHMSA-driven programme, spreads kit across hundreds of miles. Crews rotate, trucks swap, and equipment changes hands in motel parking lots.</p><p>Issue and return is designed for exactly this. When kit moves from one technician to another, it is returned and re-issued on the record, with condition at each step and approval where you require it. Reservations stop the spread superintendent and the shop manager from promising the same crawler or the same UT set to two jobs. The dashboard KPI for issued equipment overdue shows kit that should have come back when a job closed and has not.</p><p>Many US companies also rent in equipment from rental houses for peak periods and rent out their own spares. Rented-in kit can be recorded with its serial and calibration certificate like any other item, and your own rented-out units carry the rented-out stage and rental rates so the equipment manager and finance see the same picture. On the planning side, <a href=\"/erp/apps/team-assignments\">Team Assignments</a> blocks double-booking of an equipment serial and warns when an assigned instrument is out of calibration before the crew leaves the yard.</p><h2>Consumables, OSHA and the equipment room</h2><p>Consumables are where margins leak on US jobs. Aerosol penetrant, developer, cleaner, MT prep and ink, couplant, film-room stock and PPE all get used faster than planned when a job grows. The app gives each consumable a reorder level and a low-stock flag, and the movement ledger shows which jobs drew what.</p><p>OSHA's Hazard Communication Standard means your chemicals come with safety data sheets that must be available to workers. Keeping the SDS alongside each consumable record, or tying PPE issues to a technician, can be set up during implementation if you want it; it is part of the customisation scope rather than an assumed feature.</p><p>The maintenance log earns its keep in Gulf Coast conditions. Heat, humidity, salt air near the coast and hurricane-season downpours are hard on connectors, battery packs and screens. Cleaning and drying entries, cable replacements and firmware updates each go against the serial, so a recurring fault shows up as a pattern and not as a surprise on the next turnaround.</p><h2>Billing, dashboards and reporting</h2><p>Equipment is a real line item on many US inspection invoices, whether it is a day rate for a phased array unit or a charge for a crawler on a pipeline job. Invoice lines in the ERP can carry the equipment serial, method, technician, rate type and days or hours, with separate subtotals for labour, equipment and consumables. Timesheet lines can carry the equipment serial too, so what you bill matches what was actually on site. Sales tax is configured for the states you work in during implementation.</p><p>Managers get NDT KPIs on their dashboard: calibration due and overdue, certificates expiring, issued equipment overdue. The same daily alert engine that warns about technician certifications also covers calibration certificates.</p><p>Inspection results live in the NDT Reports app, where UT reports carry a probe calibration table. If your clients want those results on a 3D model of their unit or tank, that is Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP. Want to see it with your own register? <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20-%20USA\">Book an Asset Management demo</a>.</p><h2>Setting it up for a US company</h2><p>Implementation starts with the spreadsheet you already have. We clean and import your serials, equipment types, asset tags, firmware, accessories and current holders, then load current calibration certificates with PDFs, lab accreditation numbers and due dates. Your Level III agrees calibration frequencies per equipment type, and your managers agree who approves issue requests for controlled and high-value items.</p><p>If you run more than one yard, say a Houston base and a Louisiana branch, stores and consumable reorder levels are set per location. Alert recipients, look-ahead days and resend intervals are configured for your QA manager, RSO and equipment coordinator. Anything regulator- or client-specific is agreed as customisation scope before work starts, so there are no surprises.</p><p>Cost is quoted on request. The approach is affordable, accessible and fully customisable.</p><h2>Frequently asked questions</h2><h3>Will this help us pass a client or Nadcap equipment audit?</h3><p>It gives you the evidence quickly: each serial's calibration certificates, results, due dates and maintenance history in one place. Passing the audit still depends on your procedures and practice, but the paperwork hunt goes away.</p><h3>Can it record A2LA or ANAB accreditation details?</h3><p>Yes. Each calibration record has an accredited-lab flag, the certificate register stores the lab accreditation number, and calibration lab vendors in Purchase carry accreditation number and expiry.</p><h3>Does it replace our NRC or Agreement State radiography records?</h3><p>No. It manages the equipment side: serials, issue and return, survey meter calibrations and device maintenance. Licence-specific logs are scoped during implementation if you want them in the ERP.</p><h3>Is it plant integrity software for our refinery clients?</h3><p>No. It manages your company's NDT instruments and consumables, not the owner's process equipment or its inspection plans.</p><h3>Can we track rental equipment?</h3><p>Yes, both kit you rent in and kit you rent out, with lifecycle stage, rental rates and movements.</p><h3>Does it work for a small shop?</h3><p>Yes. A shop with one base and a few dozen instruments can run the same register, alerts and issue workflow as a multi-branch company.</p><h2>Talk to us</h2><p>Send us a rough list of your equipment and bases and we will show you how it fits. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20quote%20-%20USA\">Request an Asset Management quote</a> for your US operation.</p>\n<h2>Asset Management by region</h2><ul><li><a href=\"/erp/apps/asset-management\">Asset Management global overview</a></li><li><a href=\"/erp/apps/asset-management/canada\">Asset Management in Canada</a></li><li><a href=\"/erp/apps/asset-management/europe\">Asset Management in UK &amp; Europe</a></li><li><a href=\"/erp/apps/asset-management/middle-east\">Asset Management in Middle East</a></li><li><a href=\"/erp/apps/asset-management/india\">Asset Management in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(United%20States)\">Send an enquiry about Asset Management</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/asset-management/canada","publishedAt":"2026-09-27","title":"NDT Equipment Calibration Tracking, Canada | Atlantis NDT","description":"Track NDT instruments, probes, exposure devices and calibration certificates for Canadian inspection work, with issue/return and alerts. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Equipment and Calibration Management in Canada</h1>\n<p>NDT equipment by serial number: issue and return, reservations, calibration and maintenance history. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Equipment control for Canadian NDT companies</h2><p>Canadian inspection companies manage equipment across distances and conditions that break most spreadsheets. A crew mobilises from Edmonton to an oil sands site north of Fort McMurray for a long rotation. Another works an upgrader turnaround in Alberta's Industrial Heartland. A third is on a pipeline integrity dig in northern British Columbia, and a fourth supports an outage at an Ontario nuclear station. Meanwhile the shop in Sarnia or Calgary is inspecting pressure vessels for a fabricator. Equipment moves between all of them, often by air, road and camp shuttle, and each move is a chance for a serial to go missing from the record.</p><p>The Asset Management app in Atlantis NDT ERP is a register for your NDT equipment: flaw detectors, phased array and TOFD units, eddy current instruments, probes, wedges, scanners, yokes, UV lamps, light meters, calibration blocks, exposure devices and survey meters. Each is tracked by serial with its holder, condition, lifecycle, calibration and maintenance history.</p><p>To be clear about scope: this is not plant integrity software. It does not hold your client's pressure equipment, pipeline segments or their inspection history. It manages the tools your company owns or rents, so you know what you have, where it is, who has it and whether it is fit to use. It is part of <a href=\"/erp\">Atlantis NDT ERP</a>, a pre-configured and customised Odoo system set up for you by Atlantis NDT.</p><h2>What the app tracks</h2><p>Every serialised item has an equipment type, serial number, asset tag, firmware version, accessories list, assigned person, condition and lifecycle stage: new, active, in calibration, in repair, rented out, retired or disposed. Calibration frequency and status are on the same record, and rental rates can be recorded for kit you hire out.</p><ul><li><strong>Issue and return</strong> against serials, with supervisor and manager approval and condition recorded at issue and return.</li><li><strong>Reservations</strong> that block clashing bookings of the same serial.</li><li><strong>Inbound and outbound movements</strong> to camps, sites, calibration labs and manufacturers.</li><li><strong>Maintenance log</strong>: preventive, corrective, repair, cleaning, firmware update and probe replacement, with condition before and after.</li><li><strong>Calibration records</strong>: provider, certificate number, standard, range, stated uncertainty, accredited-lab flag, pass, fail or conditional, next due date.</li><li><strong>Certificate register</strong>: lab accreditation number, PDF, valid, expiring or expired status and expiry alerts.</li><li><strong>Consumables</strong> with reorder levels, low-stock flags and a movement ledger.</li></ul><h2>Calibration labs, accreditation and cross-border service</h2><p>In Canada, calibration laboratories are typically accredited to ISO/IEC 17025 by the Standards Council of Canada, and a good share of NDT instruments also go south of the border to manufacturer service centres or to labs accredited by A2LA. Either way, the questions from auditors are the same: who calibrated this serial, under which accreditation, with what result, and when is it next due?</p><p>Each calibration record captures the provider, certificate number, standard, range, uncertainty stated on the certificate, the accredited-lab flag, the result and the next due date. The certificate register stores the lab accreditation number and the PDF, and its status moves between valid, expiring and expired so nobody has to calculate dates. In Purchase, calibration labs are typed vendors with accreditation number and accreditation expiry, and purchase order lines can be tied to the exact serial being sent.</p><p>Cross-border shipping is where equipment gets lost in time rather than space. A phased array unit sent to a US service centre can be away for weeks once shipping and customs are counted. Outbound and inbound movement records, together with the in-calibration or in-repair lifecycle stage, show exactly which units are away and since when. Reservations stop a planner committing a unit that is still in a courier depot.</p><h2>Radiography under the CNSC</h2><p>Industrial radiography in Canada is licensed by the Canadian Nuclear Safety Commission under the Nuclear Substances and Radiation Devices Regulations, exposure devices are operated by CNSC-certified exposure device operators, and transport of sources falls under the Packaging and Transport of Nuclear Substances Regulations alongside Transport Canada's dangerous goods rules. Licensees are expected to keep radiation survey meters calibrated, to keep exposure devices maintained and to know where every device is.</p><p>The Asset Management app covers the equipment side of that obligation. Exposure devices, source containers, survey meters, personal alarming dosimeters, collimators and guide tubes each have a serial record. Survey meter calibrations are recorded with certificate, result and due date, and alerts go out before they lapse. Device servicing and inspections go into the maintenance log. Issuing a camera or a survey meter can require supervisor and manager approval, and every movement between base, site and service provider is logged.</p><p>Vehicles that carry sources are held in Fleet, which records whether a vehicle can carry radioactive sources, its transport licence number and expiry, and its assignment to a project and driver.</p><p>What the app does not do out of the box is keep your CNSC licence-format records, source inventories or leak test logs, or calculate source activity. If you want those in the ERP, they are scoped with your radiation safety officer during implementation. Operator certifications themselves are recorded in the ERP's Certificates app alongside technicians' other qualifications.</p><h2>Cold weather, camps and long rotations</h2><p>Winter work in Alberta and the north is hard on equipment. Batteries lose charge quickly, screens slow down, cables stiffen and crack, and condensation forms when a cold instrument comes into a warm trailer. Coupling is its own challenge, with low-temperature couplants and penetrant systems that need to suit the conditions.</p><p>Condition recorded at issue and return means cold-weather damage is noticed and attributed properly rather than discovered at the next job. Maintenance log entries for cleaning and drying, cable replacement, battery replacement or repairs build a history per serial, so you can see which units stand up to winter work and which do not.</p><p>Camp-based rotations change how kit moves. A technician on a long rotation keeps equipment for weeks, then hands over to a back-to-back partner. Issue and return records that handover properly instead of leaving it to a note in the trailer. The dashboard KPI for issued equipment overdue flags kit that stayed on site after the rotation ended, and reservations make sure the next rotation's equipment is actually available on the date the charter leaves.</p><p>Consumables for remote sites are worth planning, not guessing. Reorder levels and low-stock flags on couplant, cleaners, penetrant, developer, MT consumables and PPE, with a movement ledger per job, help the store send enough on the first shipment.</p><h2>Nuclear outages and pressure equipment work</h2><p>Ontario's nuclear stations run outage inspection campaigns under CSA N285.4 periodic inspection requirements, where equipment and technique qualification are taken seriously and client auditors expect tight control of which instrument, probe and firmware version were used. Recording firmware on each serial and logging firmware updates in the maintenance history answers the question which version was used on the day. Accessories lists make sure a qualified probe and cable set stays together. If a client requires a specific equipment list per work package, that report is configured during implementation.</p><p>Pressure equipment work in Alberta sits under ABSA oversight, and many shops operate quality control programmes that reference equipment calibration. ABSA and owner-user audits, and fabricators working to CSA and ASME codes, expect you to show that the UT set, the yoke or the densitometer used for an examination was in calibration. Opening the serial record and showing the certificate PDF is quicker than searching a shared drive.</p><p>Structural steel shops inspecting to CSA W59 and pipeline contractors working to CSA Z662 face the same basic question from their clients, and the certificate register answers it the same way.</p><h2>How it connects to the rest of the ERP</h2><p>The app links to planning, billing and people records:</p><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a> blocks double-booking of equipment serials and warns when assigned equipment is out of calibration before a crew flies out.</li><li>Projects list assigned equipment, and timesheet lines can carry the equipment serial used.</li><li>Invoice lines can carry the equipment serial, method and technician, with separate labour, equipment and consumables subtotals. GST, HST and provincial sales tax are configured for the provinces you work in during implementation.</li><li>The Certificates app records technicians' CGSB or NRCan ISO 9712 certifications and other schemes, and its daily alert engine also covers calibration certificates.</li><li>Dashboards show calibration due and overdue, and issued equipment overdue.</li></ul><p>Inspection results live in the NDT Reports app. If a client wants results on a 3D model of a vessel or piping system, that is Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP.</p><h2>People data, language and access</h2><p>Issue records, approvals and condition notes contain technicians' names and, in the Certificates app, their qualifications. Canadian privacy law, PIPEDA and in Alberta and British Columbia the provincial personal information protection acts, expects that personal information is used for stated purposes and protected. Odoo's access rights let you decide who can see what: storemen see the equipment and holders, managers see approvals, and technicians see what is issued to them. Retention and access policies are agreed during implementation.</p><p>If you operate in Quebec or have French-speaking crews, French is a standard Odoo language, and the interface language is set per user. Any French-language document layouts you need are part of the implementation scope.</p><h2>Setting it up for a Canadian company</h2><p>We start with your current register, usually a spreadsheet per base, and import serials, types, asset tags, firmware, accessories, holders and lifecycle stages. Current calibration certificates are loaded with PDFs, lab accreditation numbers and due dates so alerts work from day one. Your Level III agrees calibration frequencies per equipment type, and managers agree the approval steps for issuing radiography equipment and high-value units.</p><p>Stores and consumable reorder levels are set per base, for example Edmonton, Calgary and a site store at a camp. Alert recipients, look-ahead days and resend intervals are configured for your QA manager, radiation safety officer and equipment coordinator. Anything client-specific is agreed as customisation scope up front. Cost is quoted on request: affordable, accessible and fully customisable. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20-%20Canada\">Book an Asset Management demo</a> with your own equipment list.</p><h2>Oil sands turnarounds and mine-site work</h2><p>Spring and autumn turnarounds at Alberta upgraders and oil sands processing plants pull in more NDT equipment than most companies own. For a few weeks, every phased array unit, every TOFD set and every spare thickness gauge is spoken for, and contractors rent kit from each other and from rental houses to cover the peak. That is exactly when double-booking happens and when rented-in instruments arrive with certificates nobody has checked.</p><p>Reservations with clash prevention make the turnaround plan honest. When a unit is booked for the upgrader job from one date to another, nobody else can book the same serial for overlapping dates, and the conflict shows up at the moment of booking instead of on the first morning of the turnaround. Rented-in kit is recorded like any other item, with its serial, accessories and calibration certificate loaded into the register before it goes to site, so the client's inspector sees the same evidence for a rented UT set as for one you own.</p><p>Mine-site work brings its own mix. Magnetic particle and ultrasonic inspection of heavy mining equipment, shovels, crushers and structural components means a lot of yokes, probes and consumables going to sites where the store is a sea container and the nearest resupply is hours away. Consumable reorder levels and the movement ledger per job tell your store what a mine-site job actually uses, so the next shipment is sized from data rather than memory.</p><p>After the peak, the issued equipment overdue KPI shows what did not come back when the job closed. Condition recorded at return separates normal wear from damage, and damaged kit moves to the in-repair stage before it can be issued again. Your own units hired out during the turnaround carry the rented-out stage and rental rates, so finance and operations are looking at the same list when the job is billed.</p><h2>Repair, replacement and knowing when to retire kit</h2><p>Every Canadian NDT manager has a unit that is always either in repair or about to be. Without a history, the decision to keep fixing it or replace it is made on gut feel. The Asset Management app turns that into a record you can read.</p><p>Each serial's maintenance log shows every corrective job, repair, cable replacement, probe replacement and firmware update, with condition before and after. Movement records show how many weeks the unit spent away at a service centre, often across the border, and the lifecycle stage shows how long it sat in repair instead of working. In Purchase, repair and calibration orders are linked to the same serial, so the spend on that one instrument is visible in one place rather than spread across a year of supplier invoices.</p><p>With that picture, retiring a unit becomes a straightforward decision. Set it to retired, and it drops out of the available pool for reservations and issue while its full history stays on record for any audit that asks about work it did in the past. When it finally leaves the company, the disposed stage closes the record. The same logic applies to calibration blocks that have been damaged or worn, probes that no longer meet your verification checks and survey meters that keep failing calibration.</p><p>For radiography equipment, retirement and disposal of devices and source containers also have regulatory steps under your CNSC licence. The app records the equipment side, while the licence steps stay with your radiation safety officer, supported by any extra fields agreed during implementation.</p><h2>Frequently asked questions</h2><h3>Can it record Standards Council of Canada accreditation details?</h3><p>Yes. The certificate register stores the lab accreditation number, each calibration has an accredited-lab flag, and lab vendors in Purchase carry accreditation number and expiry.</p><h3>Does it keep our CNSC licence records?</h3><p>It manages the equipment side: device and survey meter serials, calibrations, maintenance, issue and return, movements. Licence-format records are scoped during implementation if you want them in the ERP.</p><h3>Does Atlantis NDT train technicians for CGSB certification?</h3><p>No. Atlantis's training is based on ASNT SNT-TC-1A. The ERP simply records ISO 9712 certifications held by your technicians.</p><h3>Is this software for managing our clients' plant?</h3><p>No. It manages your company's own NDT instruments, probes, calibration blocks and consumables.</p><h3>Can it handle multiple bases and site stores?</h3><p>Yes. Stores, consumables and reorder levels are set per location, and movements show kit going between them.</p><h2>Talk to us</h2><p>Tell us how many bases you run and roughly what equipment you hold. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20quote%20-%20Canada\">Request an Asset Management quote</a> and we will show you a setup that fits.</p>\n<h2>Asset Management by region</h2><ul><li><a href=\"/erp/apps/asset-management\">Asset Management global overview</a></li><li><a href=\"/erp/apps/asset-management/usa\">Asset Management in United States</a></li><li><a href=\"/erp/apps/asset-management/europe\">Asset Management in UK &amp; Europe</a></li><li><a href=\"/erp/apps/asset-management/middle-east\">Asset Management in Middle East</a></li><li><a href=\"/erp/apps/asset-management/india\">Asset Management in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(Canada)\">Send an enquiry about Asset Management</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/asset-management/europe","publishedAt":"2026-09-27","title":"NDT Equipment Calibration Tracking, UK & EU | Atlantis NDT","description":"Serial-level control of NDT instruments, probes and calibration certificates for UK and European inspection firms, with lab accreditation data. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Equipment and Calibration Management in the UK and Europe</h1>\n<p>NDT equipment by serial number: issue and return, reservations, calibration and maintenance history. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Equipment control for UK and European NDT companies</h2><p>European inspection companies tend to work to more equipment standards than anyone else, and to be audited on them more often. A UK firm might send a crew offshore from Aberdeen on Monday, support a power station outage in the Midlands on Wednesday and inspect pressure equipment for a fabricator working under the Pressure Equipment Directive on Friday. A Dutch or German company might split its week between a Rotterdam or Ludwigshafen chemical site, a rail workshop and an aerospace customer. Every one of those clients expects to see that the instrument used was verified, calibrated and in good condition.</p><p>The Asset Management app in Atlantis NDT ERP is the register behind that evidence. Flaw detectors, phased array and TOFD units, eddy current sets, probes and wedges, scanners, yokes, UV-A sources, light meters, densitometers, reference blocks, exposure devices and dose rate meters are each tracked by serial, with holder, condition, lifecycle stage, calibration and maintenance history.</p><p>It is not plant integrity software. It does not hold your clients' vessels, pipework or offshore structures, their inspection history or their inspection plans. It manages the equipment your company owns or rents. It is part of <a href=\"/erp\">Atlantis NDT ERP</a>, a pre-configured and customised Odoo system that Atlantis NDT sets up with you.</p><h2>What the app tracks</h2><p>Every serialised item records equipment type, serial number, asset tag, firmware version, accessories, assigned person, condition and lifecycle stage: new, active, in calibration, in repair, rented out, retired or disposed. Calibration frequency and status sit on the record, and rental rates can be recorded for kit you hire to other firms.</p><ul><li><strong>Issue and return</strong> with supervisor and manager approval, condition recorded at issue and return.</li><li><strong>Reservations</strong> with clash prevention on each serial.</li><li><strong>Inbound and outbound movements</strong> to site, supply base, calibration lab and manufacturer.</li><li><strong>Maintenance log</strong>: preventive, corrective, repair, cleaning, firmware update and probe replacement, with condition before and after.</li><li><strong>Calibration records</strong>: provider, certificate number, standard, range, stated uncertainty, accredited-lab flag, pass, fail or conditional, next due date.</li><li><strong>Certificate register</strong>: lab accreditation number, PDF, valid, expiring or expired status and expiry alerts.</li><li><strong>Consumables</strong>: reorder levels, low-stock flags and a movement ledger.</li></ul><h2>Equipment standards: characterisation, verification and daily checks</h2><p>European NDT equipment standards separate what a lab does from what the operator does. For ultrasonics, EN ISO 22232 parts 1 to 3 cover characterisation and verification of instruments, probes and combined equipment, with periodic verification by the user between full characterisations. Magnetic particle equipment falls under EN ISO 9934-3, penetrant equipment under EN ISO 3452-4, and viewing conditions under EN ISO 3059, which is why UV-A and visible light meters appear on so many audit checklists. Technique standards such as EN ISO 17640 for weld ultrasonics and EN ISO 17636 for weld radiography then refer back to properly verified equipment.</p><p>The app gives each of these a place. A full characterisation by an external lab goes in as a calibration record with provider, certificate number, the standard referenced, range, result and next due date. Periodic user verification can be recorded against the same serial with its result, so an auditor sees both layers in one history. Your Level III sets frequencies per equipment type, and the register shows status without manual date checks.</p><p>A conditional result deserves attention in European work, where a verification might pass with a restriction on frequency range or probe type. Recording it as conditional keeps that restriction visible to whoever issues the kit next.</p><p>If your procedures need a particular daily or weekly check sheet laid out for a specific standard, that layout is configured during implementation.</p><h2>Accredited calibration across the UK and EU</h2><p>In the UK, calibration labs are accredited to ISO/IEC 17025 by UKAS. On the continent the national bodies include DAkkS in Germany, COFRAC in France, RvA in the Netherlands, ACCREDIA in Italy and ENAC in Spain, with mutual recognition through the European co-operation for Accreditation. Firms working across borders often use more than one lab, and some send instruments back to manufacturer service centres elsewhere in Europe.</p><p>The certificate register records the lab accreditation number for each certificate, and each calibration carries an accredited-lab flag. In Purchase, calibration labs are typed vendors with accreditation number and accreditation expiry, so a lab whose accreditation lapses is noticed before your next shipment. Purchase order lines link to the exact serial being sent, which keeps calibration spend per instrument visible.</p><p>Daily email alerts for calibration certificates are configured with recipients, look-ahead days and a resend interval. Alerts go to the people who can act, typically the equipment coordinator and QA manager, well before a certificate expires and an offshore mobilisation stalls on the quayside.</p><h2>Radiography in the UK: IRR17, permits and transport</h2><p>Industrial radiography in Great Britain works under the Ionising Radiations Regulations 2017, with HSE registration or consent, a Radiation Protection Adviser, and radiation monitoring equipment that must be properly maintained and tested by a qualified person at suitable intervals. Holding sealed sources also needs environmental permits from the Environment Agency, Natural Resources Wales or, in Scotland, SEPA, with high-activity sealed source controls where they apply. Road transport falls under the Carriage of Dangerous Goods regulations implementing ADR. Across the EU, member states apply the Basic Safety Standards Directive 2013/59/Euratom through their own national rules.</p><p>The app covers the equipment side. Exposure devices, source containers, dose rate meters, electronic personal dosimeters, collimators and guide tubes each have a serial record. Monitor tests and calibrations go in as calibration records with due dates and alerts. Device inspection and servicing sit in the maintenance log. Issuing radiography equipment can require supervisor and manager approval, and movements show every trip between store, site and service provider. Source-carrying vehicles sit in Fleet, which records whether a vehicle can carry sources, the transport licence number and expiry, and its assignment to a project and driver.</p><p>Permit-format source records, HASS records, leak test logs and source activity calculations are not built in. If you want them in the ERP, they are scoped with your RPA and radiation protection supervisor during implementation.</p><h2>Offshore work and the North Sea</h2><p>Offshore work adds a layer of logistics. Equipment for a North Sea platform leaves an Aberdeen or Stavanger base, goes through a supply base or heliport, sits offshore for a trip and comes back weeks later, sometimes with a different technician. Hazardous-area instruments may need ATEX documentation, and operators expect the calibration certificate to travel with the kit.</p><p>Outbound and inbound movements record each leg. Reservations make sure the phased array set promised for a platform campaign is not also promised to an onshore job. Issue and return handles crew changes: the returning technician returns the kit with its condition, and the incoming technician is issued it, rather than it simply staying on the rig without a named holder. The issued equipment overdue KPI shows kit that should have come back after a trip.</p><p>ATEX certificate details and hazardous-area markings can be captured as additional fields or attachments configured during implementation. For marine and offshore reporting, the ERP's NDT Reports app has a marine mode that merges the class society certificate, the inspector's certificate and the calibration certificate into the report PDF, so the calibration evidence reaches the client with the report.</p><h2>GDPR and technician data</h2><p>Equipment records are not only about equipment. Issue records, approvals, condition notes and holders all name individual technicians, and under UK GDPR and the EU GDPR that is personal data. You need a clear purpose for holding it, sensible access control and a retention approach.</p><p>Odoo's access rights let you limit who sees what: storemen see equipment and holders, managers see approvals and damage notes, technicians see their own issued kit. Retention rules for issue history and where the system is hosted are agreed during implementation, so the setup fits your data protection policies. The same applies to technician qualification records held in the Certificates app, where PCN and EN ISO 9712 certificates are recorded alongside other schemes.</p><h2>How it connects to the rest of the ERP</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a> blocks double-booking of equipment serials and warns when assigned equipment is out of calibration.</li><li>Projects list assigned equipment, and timesheets can carry the equipment serial used.</li><li>Invoice lines can carry equipment serial, method and technician, with labour, equipment and consumables subtotals. VAT is configured for the UK and each EU country you invoice in during implementation.</li><li>Dashboards show calibration due and overdue, certificates expiring, and issued equipment overdue.</li></ul><p>If your clients want inspection results on a 3D model of their asset, that is Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP's NDT Reports app.</p><h2>Setting it up for a UK or European company</h2><p>We import your current register, including serials, types, asset tags, firmware, accessories, holders and lifecycle stages, and load current certificates with PDFs, lab accreditation numbers and due dates. Your Level III agrees frequencies for external calibration and user verification per equipment type. Managers agree approval steps for radiography and high-value equipment.</p><p>Multi-country firms can run separate companies or bases with their own stores and consumable reorder levels. Languages are set per user from Odoo's standard language packs. Alert recipients and intervals are configured, and anything client- or regulator-specific is agreed as customisation scope before work starts. Cost is quoted on request: affordable, accessible and fully customisable. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20-%20Europe\">Book an Asset Management demo</a>.</p><h2>Rail, aerospace and power: different audits, one register</h2><p>Many European NDT companies serve sectors that audit equipment in very different ways. Rail maintenance depots expect ultrasonic inspection of wheelsets and axles with dedicated probes and reference blocks. Aerospace customers work to prime contractor specifications, with personnel qualified under EN 4179 and equipment control examined closely by customer and Nadcap auditors. Power generation outages, conventional and nuclear, bring client-specific equipment lists and firm expectations about which instrument and firmware version were used.</p><p>Running all of that from separate spreadsheets per sector is how a probe qualified for one client ends up on another client's job, or how a reference block is sent to a rail depot while the aerospace team is waiting for it. A single register avoids that. Each serial carries its accessories, so a probe, cable and wedge qualified together stay together. Firmware is recorded on the item and every update is logged, so you can say which version was used on a given date. Reservations stop two sector teams booking the same set for overlapping dates.</p><p>Calibration records and user verification results sit against the same serial, so whichever auditor arrives, the evidence looks the same. If one sector needs a particular equipment list or check sheet layout, for example a rail client's equipment schedule or an aerospace customer's daily check format, that is configured during implementation as part of the agreed customisation scope rather than assumed to be built in.</p><p>The Certificates app completes the picture on the people side, recording PCN, EN ISO 9712 and other certificates your technicians hold, so equipment and personnel evidence can be shown to the same auditor from the same system.</p><h2>Moving kit between the UK and the EU</h2><p>Since the UK left the EU, moving NDT equipment across the Channel or the North Sea is paperwork again. Instruments going to a job in the Netherlands, Norway or Germany, or coming back to the UK for calibration, pass through customs. Many companies use ATA carnets or other temporary export arrangements for professional equipment, and each one lists serials that must come back.</p><p>Outbound and inbound movement records give you the trail: which serials left, when, to which site or lab, and when they returned. If your team wants the carnet or customs reference stored on each movement, that field is added during implementation. The in-calibration and in-repair lifecycle stages show units away at a continental lab or manufacturer, and reservations stop planners committing them while they are still in transit.</p><p>Radiography equipment is a separate matter. Moving exposure devices and sources between countries needs its own authorisations and transport arrangements, handled by your radiation protection adviser and specialist carriers. The app records the equipment side of those trips, while the regulatory steps stay with the people responsible for them.</p><p>Group companies with entities in more than one country can run them as separate companies in the ERP, each with its own stores, consumables and VAT setup, while equipment moves between them with a movement record rather than an email.</p><h2>Frequently asked questions</h2><h3>Can we record both lab characterisation and user verification?</h3><p>Yes. Both go against the same serial with their own dates, results and references, so the full picture is in one history.</p><h3>Does it record UKAS or other national accreditation numbers?</h3><p>Yes. The certificate register stores the lab accreditation number, and lab vendors carry accreditation number and expiry.</p><h3>Does it replace our IRR17 or permit records?</h3><p>No. It manages radiography equipment, monitor calibrations and movements. Permit-format records are scoped during implementation if needed.</p><h3>Can the ERP record PCN and ISO 9712 certificates?</h3><p>Yes. The Certificates app records PCN and EN ISO 9712 certificates your technicians already hold. Atlantis NDT does not offer PCN or ISO 9712 training; its training is based on ASNT SNT-TC-1A only.</p><h3>Is it for managing our clients' offshore assets?</h3><p>No. It manages your company's NDT instruments, probes, blocks and consumables only.</p><h2>Talk to us</h2><p>Send us your equipment list and the countries you work in. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20quote%20-%20Europe\">Request an Asset Management quote</a> and we will show you how it fits.</p>\n<h2>Asset Management by region</h2><ul><li><a href=\"/erp/apps/asset-management\">Asset Management global overview</a></li><li><a href=\"/erp/apps/asset-management/usa\">Asset Management in United States</a></li><li><a href=\"/erp/apps/asset-management/canada\">Asset Management in Canada</a></li><li><a href=\"/erp/apps/asset-management/middle-east\">Asset Management in Middle East</a></li><li><a href=\"/erp/apps/asset-management/india\">Asset Management in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(UK%20%26%20Europe)\">Send an enquiry about Asset Management</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/asset-management/middle-east","publishedAt":"2026-09-27","title":"NDT Equipment Tracking Software, Middle East | Atlantis NDT","description":"Control NDT instruments, probes, radiography equipment and calibration certificates across GCC sites and shutdowns. Request a quote or book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Equipment and Calibration Management in the Middle East</h1>\n<p>NDT equipment by serial number: issue and return, reservations, calibration and maintenance history. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Equipment control for NDT companies in the Gulf</h2><p>NDT companies in Saudi Arabia, the UAE, Qatar, Kuwait, Oman and Bahrain run equipment at a scale and pace that exposes every gap in a spreadsheet. A single contractor can have crews in Jubail, Ras Tanura and Yanbu at the same time, another team in Ruwais or Das Island, and a shutdown crew mobilising for Ras Laffan or Mina Al Ahmadi. Equipment travels hundreds of kilometres between yards and camps, changes hands between technicians on different rotations, and has to pass a client's equipment check at the gate before it can be used.</p><p>The Asset Management app in Atlantis NDT ERP is a register for all of that equipment: flaw detectors, thickness gauges, phased array and TOFD units, eddy current and tube inspection sets, probes, wedges, scanners, yokes, UV lamps, light meters, calibration blocks, exposure devices, survey meters and dosimeters. Each is tracked by serial with holder, condition, lifecycle stage, calibration and maintenance history.</p><p>It is not plant integrity software and it does not hold the operator's plant equipment or inspection history. It manages the tools your company owns or rents, so you know what you have, where it is, who has it and whether it will pass inspection at the gate. It is part of <a href=\"/erp\">Atlantis NDT ERP</a>, a pre-configured and customised Odoo system that Atlantis NDT sets up for you.</p><h2>What the app tracks</h2><p>Every item records equipment type, serial number, asset tag, firmware version, accessories, assigned person, condition and lifecycle stage: new, active, in calibration, in repair, rented out, retired or disposed. Calibration frequency and status sit on the same record. Rental rates can be recorded for kit you hire to other contractors, which is common during the shutdown season.</p><ul><li><strong>Issue and return</strong> with supervisor and manager approval and condition recorded at issue and return.</li><li><strong>Reservations</strong> with clash prevention on each serial.</li><li><strong>Inbound and outbound movements</strong> between yards, camps, sites, calibration labs and OEM service centres.</li><li><strong>Maintenance log</strong>: preventive, corrective, repair, cleaning, firmware update, probe replacement, with condition before and after.</li><li><strong>Calibration records</strong>: provider, certificate number, standard, range, stated uncertainty, accredited-lab flag, pass, fail or conditional, next due date.</li><li><strong>Certificate register</strong>: lab accreditation number, PDF, valid, expiring or expired status, expiry alerts.</li><li><strong>Consumables</strong> with reorder levels, low-stock flags and a movement ledger.</li></ul><h2>Client equipment checks: Aramco, ADNOC, QatarEnergy and KNPC work</h2><p>Working for the major national operators means your equipment is inspected as closely as your people. Saudi Aramco contractors work to Saudi Aramco engineering standards and inspection requirements, go through contractor approval, and routinely have instruments and calibration certificates checked by the client's inspectors before and during a job. ADNOC group companies, QatarEnergy and KNPC have their own approval processes and inspection representatives who ask the same questions: show me the calibration certificate for this serial, show me it is in date, show me the lab.</p><p>The app is built to answer those questions at the gate rather than from the office. Open the serial, and the current certificate PDF, the calibration result, the due date and the lab accreditation number are there. The certificate register shows valid, expiring or expired status, and daily email alerts for calibration certificates go to the people you choose, looking ahead as many days as you set and resending at the interval you choose. The aim is simple: no instrument reaches a client site with a certificate that expired last week.</p><p>If a client requires a specific equipment list or submittal format for contractor approval or a work package, that report is configured during implementation as part of the agreed customisation scope. The <a href=\"/erp/apps/team-assignments\">Team Assignments</a> app also warns the planner when assigned equipment is out of calibration, before the crew is sent.</p><h2>Calibration labs and OEM service in the region</h2><p>Calibration in the Gulf comes from a mix of sources. Local labs are accredited to ISO/IEC 17025 by bodies such as the Saudi Accreditation Center, ENAS in the UAE and the Dubai Accreditation Center, while many NDT instruments go to manufacturer service centres in Dubai, Europe or the US for calibration and repair. Clients may accept either, but they expect to see the accreditation.</p><p>Each calibration record carries the provider, certificate number, standard, range, uncertainty stated on the certificate, accredited-lab flag and result. The certificate register stores the lab's accreditation number with the PDF. In Purchase, calibration labs, OEMs and dealers are typed vendors, labs carry an accredited-lab flag with accreditation number and expiry, and purchase order lines link to the serial being sent.</p><p>International shipping for calibration can take a unit out of service for weeks. The in-calibration and in-repair lifecycle stages, with outbound and inbound movement records, show exactly which units are away and since when. Reservations stop a planner from committing a phased array unit to a shutdown while it is still sitting in a freight forwarder's warehouse.</p><h2>Radiography: NRRC, FANR and source movement</h2><p>Industrial radiography is licensed by national regulators across the region, including the Nuclear and Radiological Regulatory Commission in Saudi Arabia and the Federal Authority for Nuclear Regulation in the UAE, with comparable authorities in Qatar, Kuwait and Oman. Licensees must control who holds exposure devices, keep radiation monitors calibrated and move sources only with the right vehicle and permits. Operators' own site rules add their own checks.</p><p>The Asset Management app handles the equipment side. Exposure devices, source containers, survey meters, alarming dosimeters, collimators and guide tubes each have a serial record. Survey meter calibrations are recorded with certificate, due date and alerts. Device inspection and servicing go into the maintenance log. Issuing radiography equipment can require supervisor and manager approval, and movements show every trip between the licensed store and site.</p><p>Vehicles cleared to carry sources sit in the Fleet app, which records whether a vehicle can carry radioactive sources, its transport licence number and expiry, and its assignment to a project and driver. In a region where source vehicles cover long desert routes between sites, knowing which vehicle and driver are licensed and in date matters.</p><p>Regulator-format source inventories, transport permit records and source activity calculations are not built in. If you want them in the ERP, they are scoped with your radiation protection officer during implementation.</p><h2>Large expatriate crews and rotation handovers</h2><p>Most Gulf NDT companies run large expatriate workforces on rotation. Technicians go on annual leave, finish contracts, transfer between projects or move between sister companies in different countries. Every one of those moments is an equipment handover, and informal handovers are how a yard ends up with a list of instruments nobody can find.</p><p>Issue and return turns each handover into a record. A technician leaving on vacation returns his UT set and probes with condition noted; the relief technician is issued them. When someone exits the company, the list of equipment issued to him is a single view, which makes the final clearance check simple. The dashboard KPI for issued equipment overdue shows kit that has not come back at the end of a job.</p><p>Technician documents such as certifications, vision tests and medical fitness sit in the ERP's Certificates app, where ASNT and ISO 9712 certifications are both common and both recorded. Residency, iqama and visa documents can be added to employee records as part of the implementation scope, so the people who hold your equipment are tracked with the same discipline as the equipment itself.</p><h2>Shutdown season, heat and dust</h2><p>The spring and autumn turnaround seasons concentrate demand. Everyone needs phased array, TOFD, IRIS and eddy current equipment at the same time, contractors rent kit to each other, and a double-booked unit can cost a shift. Reservations with clash prevention make availability real, and the rented-out lifecycle stage with rental rates keeps hired-out kit visible to both operations and finance.</p><p>Heat and dust are the other seasonal enemy. Screens, batteries, connectors and probe faces suffer in summer temperatures and sandy yards. Condition recorded at issue and return catches damage early, and maintenance log entries for cleaning, repair, cable replacement and firmware updates build a history per serial. Consumables such as couplant, penetrant, developer, cleaners, MT consumables and PPE are tracked with reorder levels and low-stock flags, so a remote camp store does not run dry mid-shutdown.</p><h2>Billing, VAT and dashboards</h2><p>Equipment is often billed separately on shutdown contracts. Invoice lines in the ERP can carry the equipment serial, method, technician, rate type and days or hours, with labour, equipment and consumables subtotals. VAT for Saudi Arabia, the UAE, Oman and Bahrain is configured locally during implementation; no certification claims are made for e-invoicing. Timesheet lines can carry the equipment serial, so billing matches what was on site. Arabic is a standard Odoo language and can be enabled per user.</p><p>Managers see calibration due and overdue, certificates expiring and issued equipment overdue on their dashboard. If your clients want inspection results on a 3D model of their plant, that is Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP's NDT Reports app.</p><h2>Setting it up in the region</h2><p>We import your register, including serials, types, asset tags, firmware, accessories, holders and lifecycle stages, and load current certificates with PDFs and accreditation numbers. Your Level III agrees calibration frequencies per equipment type, and managers agree approval steps for radiography and high-value kit. Multi-country groups can run separate companies with their own yards, stores and tax setup. Cost is quoted on request: affordable, accessible and fully customisable. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20-%20Middle%20East\">Book an Asset Management demo</a>.</p><h2>Moving equipment across GCC borders</h2><p>Many NDT groups in the Gulf operate entities in more than one country, for example a Saudi company working for Aramco and SABIC affiliates alongside a UAE company serving ADNOC and a Qatar branch supporting Ras Laffan. Equipment moves between them as work shifts, and every crossing involves customs paperwork, temporary import or re-export documents and sometimes weeks of waiting at a border or in a freight yard.</p><p>Outbound and inbound movement records give you the trail for each serial: when it left, where it went and when it arrived. If you want customs or temporary import references stored on each movement, those fields are added during implementation. Reservations stop the UAE team booking a phased array unit that is still sitting at a border crossing on its way back from a Saudi job.</p><p>Groups can run each country entity as a separate company in the ERP, with its own yards, stores, consumables and tax setup, while still seeing equipment across the group. When a unit moves permanently from one entity to another, the move is recorded rather than handled in an email, and its calibration and maintenance history travels with the serial.</p><p>Radiography equipment is a special case. Exposure devices and sources generally cannot cross borders without separate regulatory approvals in both countries and specialist transport. The app records the equipment side of any such move, while licensing and transport approvals stay with your radiation protection officer. In practice, most groups keep radiography equipment licensed and based in each country, and the register makes that separation clear.</p><p>Calibration certificates issued in one country and accepted by clients in another sit in the same register, with the lab accreditation number, so a client inspector in Abu Dhabi can see the same evidence as one in Jubail.</p><h2>Running a large yard and site stores</h2><p>A busy Gulf NDT contractor often runs a central yard in Dammam, Al Khobar, Jubail, Abu Dhabi or Musaffah, plus site stores in containers or cabins at each major project. The central yard holds the calibrated stock and sends it out; site stores hold what the crew needs for the job. Without a register, stock drifts from the yard to site and never comes back.</p><p>The Asset Management app lets each location work to the same rules. Equipment issued from the yard to a site supervisor is recorded against serials with condition, and site supervisors can issue onward to technicians through the same issue and return workflow, with supervisor and manager approval where you require it. When a job ends, returns go back to the yard with condition noted, and anything damaged goes to repair before it is issued again.</p><p>Consumables work the same way. The yard and each site store can have their own reorder levels for couplant, penetrant, developer, cleaners, MT consumables and PPE, and the movement ledger shows what each job drew. A site that consumes far more than its scope suggests stands out quickly.</p><p>Retired and disposed lifecycle stages keep old kit from cluttering the active list without losing its history. That matters when a client audits work done years ago and asks which instrument was used. The full serial record, calibration history and maintenance log remain available long after the unit has left the yard.</p><h2>Frequently asked questions</h2><h3>Can we show calibration evidence to client inspectors on site?</h3><p>Yes. Each serial shows its current certificate PDF, result, due date and lab accreditation number, so evidence is one click away.</p><h3>Does it record SAC, ENAS or OEM calibration details?</h3><p>Yes. Every calibration has provider, certificate number, accredited-lab flag and result, and the register stores the accreditation number.</p><h3>Does it manage our NRRC or FANR licence records?</h3><p>It manages radiography equipment, monitor calibrations, issue and movements. Licence-format records are scoped during implementation if you want them.</p><h3>Is it for managing the operator's plant assets?</h3><p>No. It manages your company's NDT instruments, probes, blocks and consumables only.</p><h3>Can it handle equipment we rent in or out during shutdowns?</h3><p>Yes. Rented kit can be recorded with serials and certificates, and your own hired-out units carry the rented-out stage and rental rates.</p><h2>Talk to us</h2><p>Tell us your yards, countries and rough equipment count. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20quote%20-%20Middle%20East\">Request an Asset Management quote</a> and we will show you a setup that fits.</p>\n<h2>Asset Management by region</h2><ul><li><a href=\"/erp/apps/asset-management\">Asset Management global overview</a></li><li><a href=\"/erp/apps/asset-management/usa\">Asset Management in United States</a></li><li><a href=\"/erp/apps/asset-management/canada\">Asset Management in Canada</a></li><li><a href=\"/erp/apps/asset-management/europe\">Asset Management in UK &amp; Europe</a></li><li><a href=\"/erp/apps/asset-management/india\">Asset Management in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(Middle%20East)\">Send an enquiry about Asset Management</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/asset-management/india","publishedAt":"2026-09-27","title":"NDT Equipment Calibration Tracking, India | Atlantis NDT","description":"Track NDT instruments, probes, radiography devices and NABL calibration certificates by serial, with issue/return and expiry alerts. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Equipment and Calibration Management in India</h1>\n<p>NDT equipment by serial number: issue and return, reservations, calibration and maintenance history. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Equipment control for Indian NDT companies</h2><p>Indian inspection companies juggle equipment across some of the busiest industrial corridors in the world. A crew may be on a refinery shutdown at Jamnagar while another works at Paradip, Kochi or Panipat, a third handles boiler inspections under IBR for a power utility, and the Vadodara or Chennai workshop inspects pressure vessels for fabricators. Equipment moves between branches by road, rail and courier, is shared between jobs, and is sometimes rented from or to other NDT firms. Every move is a chance for a serial number to fall off the record.</p><p>The Asset Management app in Atlantis NDT ERP is a register for all of that equipment: ultrasonic flaw detectors, thickness gauges, phased array and TOFD units, eddy current sets, probes and wedges, yokes, UV lamps, light meters, densitometers, calibration blocks, radiography exposure devices, survey meters and dosimeters. Each item is tracked by serial with its holder, condition, lifecycle, calibration and maintenance history.</p><p>It is not plant integrity software. It does not hold the refinery's or utility's own equipment or inspection history. It manages the tools your company owns or rents, so you know what you have, where it is, who has it and whether it is fit for the next job. It is part of <a href=\"/erp\">Atlantis NDT ERP</a>, a pre-configured and customised Odoo system that Atlantis NDT sets up with you.</p><h2>What the app tracks</h2><p>Every serialised item records equipment type, serial number, asset tag, firmware version, accessories, assigned person, condition and lifecycle stage: new, active, in calibration, in repair, rented out, retired or disposed. Calibration frequency and status sit on the same record, and rental rates can be recorded for kit you hire out.</p><ul><li><strong>Issue and return</strong> with supervisor and manager approval, condition recorded at issue and at return.</li><li><strong>Reservations</strong> that block a clashing booking of the same serial.</li><li><strong>Inbound and outbound movements</strong> between branches, sites, calibration labs and service centres.</li><li><strong>Maintenance log</strong>: preventive, corrective, repair, cleaning, firmware update and probe replacement, with condition before and after.</li><li><strong>Calibration records</strong>: provider, certificate number, standard, range, stated uncertainty, accredited-lab flag, pass, fail or conditional, next due date.</li><li><strong>Certificate register</strong>: lab accreditation number, PDF, valid, expiring or expired status and expiry alerts.</li><li><strong>Consumables</strong>: reorder levels, low-stock flags and a movement ledger.</li></ul><h2>NABL calibration and traceability</h2><p>In India, calibration laboratories are accredited to ISO/IEC 17025 by NABL, and clients generally expect NABL-accredited calibration certificates with traceability to national standards maintained by CSIR-NPL. Some instruments, especially phased array units and specialised probes, still go to manufacturer service centres in India or abroad, and their certificates carry a foreign accreditation. Either way, the auditor's question is the same: which lab, which certificate, what result, when is it due?</p><p>Each calibration record captures provider, certificate number, standard, range, stated uncertainty, accredited-lab flag, result and next due date. The certificate register stores the NABL or other accreditation number with the certificate PDF, and its status moves between valid, expiring and expired automatically. In Purchase, calibration labs are typed vendors with accreditation number and accreditation expiry, so you notice when a lab's NABL accreditation is about to lapse. Purchase order lines link to the serial being sent, so calibration cost per instrument is visible.</p><p>Daily email alerts for calibration certificates go to the people you choose, looking ahead as many days as you set and resending at the interval you set, so the QA manager hears about an expiring certificate weeks before a client inspector does.</p><h2>PSU tenders and client audits</h2><p>Tenders from public sector refiners and producers such as IOCL, BPCL, HPCL and ONGC routinely ask bidders to list their NDT equipment with valid calibration certificates, and client inspectors check the same documents again at mobilisation. Private refiners and large EPC contractors do much the same. Pulling that list together from folders and email is where bid teams lose days.</p><p>With every serial, its lifecycle stage and its current certificate in one register, the equipment list for a bid starts from real data: what you own, what is active and what is in calibration. If a tender needs a specific equipment schedule format, that report is configured during implementation as part of the agreed customisation scope. At mobilisation, the client's inspector can be shown the certificate PDF for each serial directly.</p><p>The <a href=\"/erp/apps/team-assignments\">Team Assignments</a> app adds a check at the planning stage: assigning an equipment serial already committed to another job is blocked, and the planner is warned when assigned equipment is out of calibration before the crew travels.</p><h2>Radiography under AERB</h2><p>Industrial radiography in India is regulated by the Atomic Energy Regulatory Board. Licences and approvals are handled through AERB's e-LORA system, each institution must have an approved Radiological Safety Officer, sources are procured from authorised suppliers such as BRIT, and transport of radioactive material follows AERB's transport requirements. Survey meters must be kept calibrated and exposure devices properly maintained, and the RSO must know where every device is.</p><p>The Asset Management app handles the equipment side. Exposure devices, source containers, survey meters, pocket dosimeters, collimators and guide tubes each get a serial record. Survey meter calibrations are recorded with certificate, result and due date, with alerts before they lapse. Device servicing and inspection go into the maintenance log. Issuing a camera can require supervisor and manager approval, and movements show every trip between the approved storage and site.</p><p>Vehicles that carry sources sit in the Fleet app, which records whether a vehicle can carry radioactive sources, its transport licence number and expiry, and its assignment to a project and driver.</p><p>e-LORA submissions, source inventories in AERB's format, and source activity calculations are not built in. If you want related records in the ERP, they are scoped with your RSO during implementation.</p><h2>IBR, PESO and fabrication work</h2><p>Boiler work under the Indian Boiler Regulations, and pressure vessel and gas cylinder work touching PESO requirements, puts NDT results in front of inspecting authorities and third-party inspectors who want evidence that the equipment was calibrated. The same applies to fabricators building to ASME codes for export and to EPC contractors on refinery and petrochemical expansions.</p><p>For UT work, each serial's calibration record and the probe replacement entries in the maintenance log make it clear which instrument and probe were in use. On the reporting side, the ERP's NDT Reports app carries a probe calibration table on UT reports, so the report and the equipment history agree. For densitometers and step wedges used in film radiography, calibration certificates sit in the same register as everything else.</p><p>If your clients want inspection results placed on a 3D model of a boiler, vessel or piping system, that is Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP's NDT Reports app.</p><h2>Branches, rentals, monsoon and consumables</h2><p>Many Indian NDT firms run several branches, for example in Mumbai, Vadodara, Chennai and Visakhapatnam, and move equipment between them as work shifts. Outbound and inbound movements record each transfer, and reservations stop two branch managers promising the same TOFD unit for the same week. Renting equipment to and from other NDT companies is also common; rented-out units carry the lifecycle stage and rental rates, and rented-in units can be recorded with their serials and certificates.</p><p>Climate is hard on kit. Monsoon humidity, coastal salt air and summer heat damage connectors, screens, batteries and probe faces. Condition recorded at issue and return catches damage when it happens, and maintenance log entries for cleaning and drying, repairs, cable replacements and firmware updates build a history for each serial.</p><p>Consumables such as couplant, penetrant, developer, cleaner, MT consumables, film-room supplies and PPE are tracked with reorder levels, low-stock flags and a movement ledger by job, so site stores are restocked before a shutdown runs short rather than after.</p><h2>GST, data protection and connections</h2><p>Equipment is billed on many Indian contracts. Invoice lines can carry the equipment serial, method, technician, rate type and days or hours, with labour, equipment and consumables subtotals. GST is configured locally during implementation; no certification claims are made for e-invoicing. Timesheet lines can also carry the equipment serial used.</p><p>Issue records and holders name individual technicians, which makes them personal data under the Digital Personal Data Protection Act, 2023. Odoo's access rights let you limit who sees what, and retention and access rules are agreed during implementation. Technician qualifications, where both ASNT and ISO 9712 certifications are common in India, are recorded in the ERP's Certificates app, whose daily alert engine also covers calibration certificates. Managers see calibration due and overdue and issued equipment overdue on their dashboard.</p><h2>Setting it up for an Indian company</h2><p>We import your current register, including serials, types, asset tags, firmware, accessories, holders and lifecycle stages, and load current certificates with PDFs, NABL or other accreditation numbers and due dates. Your Level III agrees calibration frequencies per equipment type, and managers agree approval steps for radiography and high-value equipment. Stores and consumable reorder levels are set per branch. Cost is quoted on request: affordable, accessible and fully customisable. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20-%20India\">Book an Asset Management demo</a>.</p><h2>Power plant overhauls and boiler tube inspection</h2><p>Thermal power stations run by NTPC, state generation companies and private producers schedule annual and capital overhauls that bring a burst of NDT work: ultrasonic thickness surveys on boiler tubes, weld inspection on replaced tube sections, magnetic particle and penetrant testing on rotating equipment and structural parts, and radiography of new welds. A single overhaul can need many thickness gauges, probes and calibration blocks at once, spread across several crews working inside the boiler and around the unit.</p><p>This is where equipment control usually slips. Gauges are passed between technicians inside the boiler, probes wear out quickly on scaled tube surfaces, and at the end of the overhaul nobody is sure which gauge was used on which elevation or whether every unit came back. The issue and return workflow puts each gauge against a named technician with condition at issue and return. Probe replacement entries in the maintenance log show how quickly probes are consumed on boiler work, which helps you plan the next overhaul's stock.</p><p>Calibration matters as much here as anywhere. Utility engineers and third-party inspectors reviewing tube thickness results expect to see the gauge's calibration certificate and the reference block used. With both in the register, and the NDT Reports app recording UT thickness readings on its own report type, the evidence for a boiler survey can be shown from one system.</p><p>Reservations let the planner book a fleet of gauges for the overhaul window well in advance, and the issued equipment overdue KPI shows which units are still at the power station after the unit has returned to service.</p><h2>From register book to ERP: starting small</h2><p>Many Indian NDT companies still manage equipment in a physical register book or an Excel file kept by one person in the office. It works until that person is on leave, a branch opens, or a major client asks for an equipment list with certificates by tomorrow. Moving to an ERP does not need to happen all at once.</p><p>A common approach is to start with the equipment register and calibration certificates alone. Serials, types, asset tags, holders and current certificates go in first, so the certificate register and expiry alerts start working immediately. Issue and return and reservations follow once the storeman is comfortable, then consumables with reorder levels, and finally links to projects, timesheets and invoicing. Each step is agreed with you, and the pace is set by how quickly your team adopts it.</p><p>Odoo runs in a web browser, so branch storemen and site supervisors can use it from a laptop or phone without installing anything special. Access rights mean a site supervisor sees the kit issued to his site, while the head office sees everything.</p><p>Implementation includes hands-on training for storemen, planners and the QA team, using your own equipment data. The goal is a register that people actually keep up to date, because it saves them time, rather than one that is updated only before audits.</p><h2>Frequently asked questions</h2><h3>Can it store NABL accreditation numbers?</h3><p>Yes. The certificate register stores the lab accreditation number with each certificate, and lab vendors in Purchase carry accreditation number and expiry.</p><h3>Can it produce the equipment list a PSU tender asks for?</h3><p>The data is all in the register. A tender-specific equipment schedule layout is configured during implementation.</p><h3>Does it handle AERB e-LORA submissions?</h3><p>No. It manages radiography equipment, survey meter calibrations, issue and movements. Related records can be scoped during implementation.</p><h3>Is it software for our clients' plant assets?</h3><p>No. It manages your company's NDT instruments, probes, blocks and consumables.</p><h3>Does Atlantis NDT train technicians for ISO 9712?</h3><p>No. Atlantis's training is based on ASNT SNT-TC-1A. The ERP records ISO 9712 certificates your technicians already hold.</p><h2>Talk to us</h2><p>Tell us your branches and roughly how much equipment you hold. <a href=\"/contact?service=erp&amp;subject=Asset%20Management%20quote%20-%20India\">Request an Asset Management quote</a> and we will show you a setup that fits.</p>\n<h2>Asset Management by region</h2><ul><li><a href=\"/erp/apps/asset-management\">Asset Management global overview</a></li><li><a href=\"/erp/apps/asset-management/usa\">Asset Management in United States</a></li><li><a href=\"/erp/apps/asset-management/canada\">Asset Management in Canada</a></li><li><a href=\"/erp/apps/asset-management/europe\">Asset Management in UK &amp; Europe</a></li><li><a href=\"/erp/apps/asset-management/middle-east\">Asset Management in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Asset%20Management%20demo%20(India)\">Send an enquiry about Asset Management</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/certificates","publishedAt":"2026-09-27","title":"NDT Technician Certification Tracking Software | Atlantis NDT","description":"Track NDT technician certs, vision tests and company accreditations in one ERP app with 90-day expiry alerts. Book a demo of Atlantis NDT Certificates.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Certification Tracking Software</h1>\n<p>Technician certifications, eye tests and expiry tracking against your written practice. <a href=\"/contact?service=erp&amp;subject=Certificates%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>The expired certificate nobody noticed until the client did</h2><p>Every NDT company has a version of this story. A Level II UT technician is two days into a shutdown when the client’s QA reviewer asks for his certification and eye test. The certificate is on file, but the vision test lapsed last month. He comes off the job, the crew is short, and someone spends the evening explaining to the client why the paperwork missed it.</p><p>It rarely happens because people don’t care. It happens because certification data lives in too many places: a spreadsheet the QA manager updates when she remembers, scanned PDFs in a shared drive, paper eye-test cards in a technician’s wallet, and the Level III’s own memory of who sat which exam. Each piece is correct on its own. Nobody sees the whole picture on the day it matters.</p><p>The Certificates app in Atlantis NDT ERP puts that whole picture in one place. Each technician’s certifications, vision tests, exam results and radiation-safety details sit on their employee record. The system works out each certificate’s status every day, warns you 90 days before anything runs out, and emails the right people on a schedule you set. Your company’s own certifications, such as ISO registrations and API-type accreditations, are tracked the same way.</p><p>It is built on Odoo and set up by Atlantis NDT for inspection companies, so the fields match how NDT people actually talk about qualifications: scheme, level, method, certifying body, OJT hours. Affordable, accessible and fully customizable, with a demo and a quote on request.</p><h2>What the app records for each technician certification</h2><p>A certification record is more than a name and an expiry date. The app captures the details an auditor or client reviewer actually asks for:</p><ul><li><strong>Scheme</strong>: SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP, or other for anything that doesn’t fit those categories, such as an aerospace or client-specific qualification.</li><li><strong>Level</strong>: trainee, Level I, Level II or Level III.</li><li><strong>Method</strong>: one record per method, so a technician qualified in UT, MT and PT at different levels has three clear entries instead of one confusing line.</li><li><strong>Certifying body</strong>: your own company under an employer-based written practice, or an external certification body.</li><li><strong>Dates</strong>: issue, expiry and renewal dates.</li><li><strong>Industry sector</strong>: useful where a qualification is sector-specific.</li><li><strong>Experience and training</strong>: on-the-job training hours, formal training hours, and whether the exam was passed.</li><li><strong>Attachments</strong>: the scanned certificate, exam papers, training records or anything else you need to produce on request.</li></ul><p>Because every record is structured, you can filter and group it. Which Level IIs in PAUT do we have? Who is certified to ISO 9712 and who under an in-house SNT-TC-1A practice? Which trainees are close to their OJT hours? Those answers come from a list view and a filter instead of an afternoon of opening PDFs.</p><p>The attachments matter too. When a client asks for a technician’s qualification pack before mobilisation, the certificate, exam evidence and vision test are already on the record, ready to send.</p><h2>Status that keeps itself current</h2><p>The app computes every certificate’s status automatically. You don’t tick a box to say something has expired; the dates do the work.</p><ul><li><strong>Active</strong>: valid, with more than 90 days to run.</li><li><strong>Expiring soon</strong>: within 90 days of expiry.</li><li><strong>Expired</strong>: past the expiry date.</li><li><strong>Revoked</strong>: withdrawn, for example after a failed practical, a disciplinary matter or a Level III decision under your written practice.</li></ul><p>Two menus, Expiring Soon and Expired, give the QA manager a working list every morning. No one has to build a report or remember to sort a spreadsheet by date.</p><p>Behind the menus, a daily check runs through technician certificates and vision tests and creates a warning task 90 days before each expiry. The task lands with the person responsible, so renewals turn into planned work: book the recertification exam, schedule the eye test, collect the evidence, update the record.</p><p>On top of the tasks, you can set up daily email alerts. You choose who receives them, how many days ahead to look, and how often an alert is resent if nothing changes. One alert can go to the QA manager and the operations manager for technician certificates; another to the equipment coordinator for calibration certificates; a third can cover the company’s own certifications. The resend interval stops a slipping renewal from quietly disappearing after one ignored email.</p><p>Ninety days is long enough to book an exam slot, arrange a vision test between jobs, or plan a recertification around a turnaround. That is the point: problems surface while there is still time to fix them.</p><h2>Vision tests on the record, not in a wallet</h2><p>Most certification schemes require technicians to pass a vision examination at regular intervals, and client auditors check it as closely as the certificate itself. A technician with a valid Level II certificate and an expired eye test should not be signing reports.</p><p>The app keeps vision tests as their own records, linked to the technician:</p><ul><li>Near vision, recorded against the Jaeger chart (J1 or J2).</li><li>Far vision.</li><li>Colour perception.</li><li>Contrast.</li><li>The examiner and the clinic that carried out the test.</li><li>The certificate file itself.</li><li>The expiry date.</li></ul><p>Vision tests get the same daily check and 90-day warning task as certifications. So the reminder to book an eye test arrives weeks before it lapses, not when a client’s reviewer points it out.</p><p>Keeping vision tests separate from certifications also reflects how the requirements work in practice. The eye test usually runs on a shorter cycle than the certificate, and a single test covers every method a technician holds. One vision record, many certifications, and the status of each visible on its own.</p><p>Colour perception deserves a mention. It matters for methods where the technician judges colour contrast, such as dye penetrant and colour-contrast magnetic particle work. Recording the result means a Level III can see at a glance whether any restriction applies before a technician is put on that kind of job.</p><h2>Examination sheets and certificate templates</h2><p>If your company certifies its own people under an employer-based written practice, the exam is part of the evidence. The app records examination sheets with the general, specific and practical scores, the passing score (70% by default, adjustable to match your written practice or scheme), and the exam files themselves. When an auditor asks how a technician reached Level II in MT, the answer is on one screen: scores, papers and date.</p><p>Certificate templates set the rules for each scheme you work with. For each template you define:</p><ul><li>Validity in months.</li><li>Whether a vision test is required.</li><li>Whether an exam is required.</li><li>Minimum OJT hours.</li><li>Minimum training hours.</li></ul><p>Templates mean the rules live in the system rather than in one person’s head. When a new certificate is created against a template, the validity period and requirements come with it. If your written practice differs from a scheme’s usual rules, or a client asks for tighter conditions, you set that in the template once.</p><p>This is especially useful for companies that hold several schemes side by side: an in-house SNT-TC-1A practice for most work, ISO 9712 certificates held by technicians who came from other employers, and CSWIP or PCN certificates for specific contracts. Each scheme has its own template and validity rules, and the technician’s record shows all of them together.</p><p>Training towards SNT-TC-1A certification is something Atlantis NDT also delivers through its <a href=\"/training\">NDT training programmes</a>; the hours your people complete can then be recorded against their certificate records.</p><h2>The employee NDT profile</h2><p>Certificates hang off a technician’s employee record, and that record gains an NDT profile:</p><ul><li>A technician flag, so NDT staff can be filtered from office and admin staff.</li><li>Highest level held.</li><li>Methods certified.</li><li>Radiation safety training.</li><li>Radiation badge (dosimeter) number.</li><li>Medical fitness expiry.</li></ul><p>For a planner, this is the quick view: who is a Level II in UT, who has current radiation safety training and a badge number for an RT job, whose medical is still valid for a site that insists on one. For HR, it keeps the NDT-specific information alongside the rest of the employee record instead of in a separate file.</p><p>The radiation fields matter for any company running radiography. Clients and regulators expect to see that a radiographer has completed radiation safety training and is monitored with a personal dosimeter. Having the badge number on the profile keeps the link between a person and their dose monitoring one click away.</p><p>Medical fitness is increasingly a site entry requirement, particularly for confined space, offshore and some plant work. Recording the expiry date means it can be checked before mobilisation, not at the gate.</p><p>Everything on the profile is employee data in the ERP, so access rights apply. You decide who can see medical and personal details and who only sees certification status. That separation is set up during implementation to match your company’s privacy obligations.</p><h2>Company certifications and calibration certificate alerts</h2><p>Your company holds certificates too, and a lapsed one can cost more than a lapsed technician certificate. An expired ISO 9001 registration, or an accreditation a major client requires, can take you off an approved vendor list.</p><p>The Certificates app tracks company certifications, including ISO registrations and API-type accreditations, with their own alert days. The same daily email alerts that cover technicians can cover these, so the managing director and the quality manager both hear about a surveillance audit or renewal well before the deadline.</p><p>Calibration certificates are the third leg. The daily alert settings in the app include calibration certificates, with their own recipients, look-ahead days and resend interval. The calibration records themselves live in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>, where each instrument and probe is tracked by serial number with its calibration history, lab accreditation number and certificate PDF. The Certificates alerts make sure the equipment coordinator hears about an expiring calibration certificate on the same rhythm as everything else.</p><p>Put together, the three alert types cover the documents a client’s QA reviewer asks for before a job: is the technician qualified, is the instrument calibrated, is the company approved. One set of daily emails, sent to the people who can act on them.</p><h2>How Certificates connects to the rest of the ERP</h2><p>Certification data is only useful if it shows up where decisions are made. In Atlantis NDT ERP it does.</p><p><strong>Timesheets.</strong> When hours are logged for a technician whose certificate is not valid, the timesheet shows a warning. It is a last line of defence: if someone was sent to site with a lapsed certificate, the problem surfaces when the hours come in, before the invoice goes out and before the report reaches the client.</p><p><strong>Team Assignments.</strong> Planners dispatch crews in the <a href=\"/erp/apps/team-assignments\">Team Assignments app</a>, which blocks double-booking of technicians and equipment and warns when assigned equipment is out of calibration. The technician’s NDT profile and the Expiring Soon list give the planner the certification side of the picture. If you want a certificate check built directly into the dispatch step, that can be part of the customization scope agreed with you.</p><p><strong>Dashboards.</strong> The NDT KPI dashboards include certificates expiring and expired alongside calibration due and overdue and issued equipment overdue. Managers get one screen instead of three spreadsheets.</p><p><strong>Employees and Time Off.</strong> Certificates sit on the employee record. Time Off feeds the technician availability used for scheduling, so a technician away for a recertification exam shows as unavailable rather than being booked on a job.</p><p><strong>Reporting.</strong> Reports are signed by the inspector, reviewer and approver in the NDT Reports app, and many companies pair it with <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, Atlantis’s separate product that places inspection results on a 3D model of the asset. Accurate certification records sit behind every signature on those reports.</p><h2>Who uses it, and what they do with it</h2><ul><li><strong>QA/QC manager</strong>: works the Expiring Soon and Expired lists, keeps attachments complete, and prepares qualification packs for client pre-qualification and audits.</li><li><strong>NDT Level III</strong>: records exam sheets, approves certifications under the written practice, revokes a certificate when needed, and sets the templates for each scheme.</li><li><strong>Operations manager or planner</strong>: checks who is qualified and current before building a crew, and plans renewals around the job calendar.</li><li><strong>HR and admin</strong>: maintains vision tests, medical fitness dates and radiation badge numbers, and chases technicians for renewed documents.</li><li><strong>Owner or managing director</strong>: watches the dashboard and the company certification alerts, and knows the business can prove its people are qualified.</li><li><strong>Technicians</strong>: get reminders in time, rather than finding out from a client.</li></ul><p>The common thread is that nobody has to maintain a separate tracker. The data is entered once, on the technician’s record, and everyone who needs it sees the same version. When the QA manager is on leave, the alerts still go out and the lists still update.</p><h2>What implementation looks like</h2><p>Atlantis NDT deploys and configures the ERP for you. For the Certificates app, a typical setup covers:</p><ol><li><strong>Scheme review.</strong> We go through the schemes you work with, your written practice if you certify in-house, and any client-specific requirements, then build certificate templates with the right validity, vision test, exam and hours rules.</li><li><strong>Data migration.</strong> Your existing spreadsheet or document register is imported: technicians, certificates, levels, methods, dates and vision tests. Scanned certificates are attached to the right records.</li><li><strong>Alerts.</strong> We set up the daily email alerts for technician certificates, calibration certificates and company certifications, with the recipients, look-ahead days and resend intervals you choose.</li><li><strong>Access rights.</strong> We agree who sees what, especially for medical and vision data.</li><li><strong>Connections.</strong> We link Certificates with Timesheets, Team Assignments, Dashboards and the other apps you use, and agree any customization such as extra fields or checks.</li><li><strong>Handover.</strong> Your QA team is walked through the daily routine: work the lists, close the tasks, update the records.</li></ol><p>You can start with Certificates on its own and add other apps later, or roll it out as part of the full <a href=\"/erp\">Atlantis NDT ERP</a>. The system is fully customizable, so fields, templates and alerts follow your process rather than the other way round. If you’d like to see it with your own schemes, <a href=\"/contact?service=erp&amp;subject=Certificates%20demo\">book a Certificates demo</a>.</p><h2>Frequently asked questions</h2><h3>Can the app track certifications from different schemes for the same technician?</h3><p>Yes. Each certification is its own record with its own scheme, level, method, certifying body and dates. A technician can hold an in-house SNT-TC-1A certificate, an ISO 9712 certificate and a CSWIP certificate side by side, and each shows its own status.</p><h3>How far ahead does it warn about expiring certificates?</h3><p>The status changes to expiring soon 90 days before expiry, and the daily check creates a warning task at the same point for certificates and vision tests. Email alerts use look-ahead days you configure, with a resend interval so reminders repeat until something is done.</p><h3>Does Atlantis NDT issue ISO 9712 or PCN certificates?</h3><p>No. The app records certificates your technicians already hold from any scheme. Atlantis NDT’s own training is based on ASNT SNT-TC-1A. ISO 9712, PCN and CSWIP certificates are issued by their own certification bodies; the app simply keeps track of them.</p><h3>Can we store scanned certificates and exam papers?</h3><p>Yes. Certification records accept attachments, examination sheets hold exam files, and vision tests hold the certificate file from the clinic.</p><h3>What happens if a technician with an expired certificate logs hours?</h3><p>The timesheet shows a warning that the technician’s certificate is not valid, so it can be caught before the hours are approved and billed.</p><h3>Can it track our company’s ISO and accreditation certificates?</h3><p>Yes. Company certifications are recorded with their own alert days and can be included in the daily email alerts.</p><h3>Do we need the full ERP to use Certificates?</h3><p>No. Many companies start with Certificates and add apps such as Team Assignments, Asset Management and Timesheets later. The connections described above apply as each app is added.</p><h2>See your own certification register in the app</h2><p>Send us a list of the schemes and methods your technicians hold and we’ll show you how they look in the Certificates app, with expiry lists, vision tests and alerts set up the way your QA team works. The cost is quoted on request, based on the apps and customization you need. <a href=\"/contact?service=erp&amp;subject=Certificates%20quote\">Request a quote for the Certificates app</a> and tell us how your team tracks certificates today.</p>\n<h2>Certificates by region</h2><ul><li><a href=\"/erp/apps/certificates/usa\">Certificates in United States</a></li><li><a href=\"/erp/apps/certificates/canada\">Certificates in Canada</a></li><li><a href=\"/erp/apps/certificates/europe\">Certificates in UK &amp; Europe</a></li><li><a href=\"/erp/apps/certificates/middle-east\">Certificates in Middle East</a></li><li><a href=\"/erp/apps/certificates/india\">Certificates in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Certificates%20demo\">Send an enquiry about Certificates</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/certificates/usa","publishedAt":"2026-09-27","title":"NDT Certification Tracking Software USA | Atlantis NDT","description":"Track SNT-TC-1A, CP-189 and NAS 410 technician certs, annual vision tests and radiographer records in one ERP app. Book a demo for your US NDT company.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Certification Tracking in the USA</h1>\n<p>Technician certifications, eye tests and expiry tracking against your written practice. <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>US certification is employer-based, and that is what auditors test</h2><p>In the United States, most NDT technicians are certified by their employer. Under ASNT’s Recommended Practice SNT-TC-1A, your company writes its own written practice, your Level III administers the exams, and the certificate carries your company’s name. ANSI/ASNT CP-189 works the same way but as a standard with firmer requirements, and some clients specify it by name. A smaller number of technicians hold central certification such as ASNT’s ACCP, and your Level III may hold an ASNT NDT Level III certificate.</p><p>That model gives US companies flexibility, but it puts the burden of proof on you. When a refinery QA reviewer, an Authorized Inspector or an aerospace customer’s auditor looks at a technician’s qualification, they are really auditing your records. Does the certificate match the written practice? Are the training and experience hours documented? Were the exams graded correctly? Is the eye test current?</p><p>Most US inspection companies still answer those questions from a mix of spreadsheets, scanned PDFs and the Level III’s filing cabinet. It works until the Level III is on vacation, a client asks for twelve qualification packs before Monday, or a technician’s eye test quietly lapses in the middle of a turnaround.</p><p>The Certificates app in Atlantis NDT ERP holds all of it on the technician’s record: certifications by scheme, level and method, OJT and training hours, exam sheets, vision tests, radiation safety details and medical fitness. Status is worked out daily, warning tasks appear 90 days before anything expires, and email alerts go to the people you choose. Atlantis NDT is based in Houston, so the setup reflects how Gulf Coast inspection companies actually work.</p><h2>Recording SNT-TC-1A and CP-189 certifications the way your written practice defines them</h2><p>Each certification is its own record: scheme (SNT-TC-1A or CP-189, with ISO 9712, PCN, CSWIP and other also available), level from trainee to Level III, method, certifying body, issue, expiry and renewal dates, industry sector, OJT hours, training hours, whether the exam was passed, and attachments.</p><p>That structure matches what SNT-TC-1A asks you to document. The recommended practice sets out training and experience hours by method and level, and your written practice adopts them or sets its own. With OJT and training hours on each record, a Level III can see whether a trainee has the hours to sit a Level I or Level II exam without digging through timesheets and course rosters.</p><p>Certificate templates hold the rules. For each scheme you define validity in months, whether a vision test and an exam are required, and minimum OJT and training hours. A company might set one template for its SNT-TC-1A practice, a second for CP-189 work where a client demands it, and other-scheme templates for aerospace or client-specific qualifications. Recertification intervals vary by written practice; the template carries whatever yours says.</p><p>Because the certifying body is a field, you can separate certificates issued under your own practice from those a new hire brought from a previous employer. Under SNT-TC-1A, certification does not transfer between employers automatically; a technician joining you needs to be certified under your written practice. Recording both makes that transition visible, and a certificate that no longer applies can be marked revoked rather than deleted, so the history stays intact.</p><h2>Exams, grading and the evidence behind each certificate</h2><p>SNT-TC-1A certification rests on general, specific and practical examinations, and US auditors routinely ask to see them. The app’s examination sheets record the general, specific and practical scores, the passing score and the exam files.</p><p>The default passing score is 70%, which lines up with the minimum SNT-TC-1A sets for each individual exam. Your written practice may also require a minimum composite grade. The passing score is adjustable, and how composite grading is shown on the sheet can be configured during implementation to mirror your written practice.</p><p>With exam files attached, a technician’s certification history is complete in one place: when the exams were taken, the scores and the papers. When a client auditor samples three technicians from your roster, your QA manager opens three records instead of three binders.</p><p>This matters most at the moments US companies feel audit pressure: ASME certificate holder reviews, owner-user audits of contract inspection companies, and aerospace customer audits. In each case, the question is the same. Can you prove this person was qualified, under your written practice, when they did the work? Records built this way answer it.</p><p>Atlantis NDT also delivers <a href=\"/training\">NDT training based on ASNT SNT-TC-1A</a> for Level I, II and III candidates, and those training hours can then be entered against each technician’s certificate record.</p><h2>Annual vision tests: Jaeger J2, J1 and colour</h2><p>SNT-TC-1A calls for a near-vision test at least annually, with the technician able to read Jaeger J2 or equivalent at not less than 12 inches, plus a colour contrast check defined by your written practice. Some aerospace and client specifications ask for the stricter J1. Whatever the requirement, a lapsed eye test makes an otherwise valid certificate useless on site.</p><p>Vision tests are separate records in the app, linked to the technician: near vision against J1 or J2, far vision, colour perception, contrast, the examiner, the clinic, the certificate file and the expiry. The daily check creates a warning task 90 days before a vision test expires, the same as for certifications.</p><p>US companies handle eye tests in different ways. Some send technicians to an occupational health clinic; others have a qualified examiner in-house. Recording the examiner and the clinic keeps each test traceable, which auditors look for.</p><p>Colour perception results matter for PT and colour-contrast MT, and for reading some digital displays. Having the result on record lets your Level III see immediately whether any restriction applies before a technician is scheduled on that type of work.</p><p>Because one vision test covers every method a technician holds, a single lapsed test can take a multi-method Level II off the schedule. Warning tasks for vision tests and certificates come from the same daily check, so renewals can be planned together.</p><h2>Radiography: NRC, Agreement States and radiographer records</h2><p>If you shoot RT, your people carry two sets of qualifications. The NDT certificate says they can interpret a film or digital image. The radiation safety side says they can legally work with a source. Under NRC rules in 10 CFR Part 34, and the equivalent rules in Agreement States such as Texas and Louisiana, a radiographer must complete radiation safety training and hold a radiographer certification, and radiographer’s assistants work under supervision. Everyone working with the source wears personal dosimetry.</p><p>The employee NDT profile in the Certificates app includes radiation safety training, radiation badge number and medical fitness expiry, alongside the highest NDT level and methods certified. A radiographer’s state or independent certification card can be recorded as an other-scheme certificate with its own expiry, template and attachments, so it gets the same 90-day warnings as an NDT certificate.</p><p>That gives the radiation safety officer and the operations manager one place to check before an RT crew leaves the yard: NDT level, radiographer certification, safety training, badge number. The badge number on the profile keeps the link between a person and their dosimetry reports clear when a dose query comes up.</p><p>Source transport is handled elsewhere in the ERP. The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry, so the truck is checked with the same discipline as the crew. The Certificates app does not replace your radioactive materials licence records or your regulator’s requirements; it keeps your people’s qualifications current and visible.</p><h2>Refinery, petrochemical and API inspection work on the Gulf Coast</h2><p>From Corpus Christi through Houston and Beaumont to Lake Charles and Baton Rouge, much NDT work is done for refineries, chemical plants and midstream operators running API 510, API 570 and API 653 inspection programmes. The owner-user’s API-certified inspectors decide what gets inspected; your technicians do the UT thickness, PAUT, RT and surface work that feeds those programmes. Code work runs under ASME Section V for methods, with Section VIII and B31.3 for construction and repair.</p><p>These clients expect documented qualification before a technician sets foot on site. Typical requests include current certifications by method and level, a copy of the written practice, a current vision test and site-specific safety training. Many plants also screen contractors through platforms such as ISNetworld or Avetta, and turnarounds often come with their own badging and orientation requirements.</p><p>The Certificates app helps you respond fast. Each technician’s certificates, vision test and attachments are already on the record, so a qualification pack is a matter of gathering files, not reconstructing them. Site credentials such as safety council orientation or a TWIC card for port and marine terminal access can be tracked as other-scheme certificates with their own expiry dates, or added as dedicated fields as part of the customization scope agreed with you.</p><p>Spring and fall turnarounds are where tracking breaks down. You bring in extra technicians, some from other companies, and everyone needs checking at once. Because warning tasks are generated 90 days ahead, renewals for your core crew can be pulled forward before turnaround season rather than discovered in the middle of it.</p><h2>Pipelines and PHMSA operator qualification</h2><p>Pipeline work adds another layer. Operators regulated by PHMSA under 49 CFR Parts 192 and 195 must make sure people performing covered tasks are operator qualified, and NDT of pipeline girth welds is commonly done to API 1104. A technician on a pipeline spread may need a current NDT certificate, an OQ record for the relevant covered tasks, and the operator’s own site requirements.</p><p>The app doesn’t manage OQ programmes, but it can hold OQ qualifications as other-scheme certificates with their evaluation date, expiry and evidence attached. That puts them on the same record, with the same warning tasks and email alerts, as the technician’s NDT certificates. Many pipeline NDT companies also employ AWS Certified Welding Inspectors; a CWI can be recorded the same way.</p><p>The benefit is a single view of whether a technician can go on a particular spread. Before, that answer often needed a call to the OQ administrator, a look at the NDT tracker and a search for the latest eye test. Now it is one employee record.</p><h2>Aerospace shops working to NAS 410</h2><p>Aerospace NDT personnel are qualified under NAS 410, with prime contractors often adding their own requirements, and Nadcap audits look closely at personnel records. NAS 410 differs from SNT-TC-1A in areas such as examination requirements, vision testing and the role of the responsible Level 3, and it is not something you want to track in the same spreadsheet as your refinery work.</p><p>In the Certificates app, NAS 410 certifications are recorded under the other scheme, with a template that carries your validity period, vision test and exam requirements, and minimum hours. The industry sector field lets you separate aerospace certificates from industrial ones, so an auditor sees exactly the population they are sampling.</p><p>Examination sheets record general, specific and practical scores and files, and the passing score can be set to what your NAS 410 written practice requires. Vision tests record J1 or J2, colour and contrast with examiner and clinic. For shops that do both aerospace and industrial work, the same technician can hold both kinds of certificate side by side, each with its own status.</p><h2>How Certificates fits into your day-to-day operations</h2><p>The Certificates app doesn’t live on its own. In Atlantis NDT ERP, it connects to the parts of the business where a lapsed certificate would cause real trouble.</p><ul><li><strong>Timesheets</strong> warn when a technician whose certificate is not valid logs hours, so the issue is caught before hours are approved and billed to the client.</li><li><strong>Dashboards</strong> show certificates expiring and expired next to calibration due and overdue, so the operations manager sees people and equipment risk on one screen.</li><li><strong>Daily email alerts</strong> cover technician certificates, calibration certificates and company certifications, with your choice of recipients, look-ahead days and resend interval.</li><li><strong>Company certifications</strong>, such as ISO 9001 registration or an accreditation a client requires, are tracked with their own alert days.</li><li><strong><a href=\"/erp/apps/team-assignments\">Team Assignments</a></strong> blocks double-booking of technicians and equipment and flags out-of-calibration equipment; planners use the certification lists and NDT profiles to pick a qualified crew, and a certificate check at dispatch can be added as part of your customization scope.</li></ul><p>Inspection reports signed in the NDT Reports app, or presented on a 3D asset model through Atlantis’s separate <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, carry more weight when the qualification behind every signature is documented and current.</p><h2>Setting it up for a US inspection company</h2><p>Atlantis NDT deploys and configures the ERP for you. For a US company, setup of Certificates usually covers:</p><ol><li>Reviewing your written practice (SNT-TC-1A or CP-189) and building certificate templates to match its validity, exam, vision and hours rules.</li><li>Adding other-scheme templates for NAS 410, radiographer cards, OQ qualifications, CWI or site credentials you need to track.</li><li>Importing your existing tracker: technicians, certificates, levels, methods, dates, hours and vision tests, with scanned certificates attached.</li><li>Setting up daily email alerts and warning tasks for the QA manager, radiation safety officer, operations and management.</li><li>Agreeing access rights so medical and vision details are visible only to the people who need them.</li><li>Connecting Certificates to Timesheets, Dashboards and the other apps you use in the full <a href=\"/erp\">Atlantis NDT ERP</a>.</li></ol><p>The system is affordable, accessible and fully customizable, and the quote depends on the apps and customization scope you choose. To see it with your own written practice loaded, <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20USA\">book a Certificates demo</a>.</p><h2>Frequently asked questions</h2><h3>Does the app replace our SNT-TC-1A written practice?</h3><p>No. Your written practice remains the controlling document, approved by your Level III. The app holds certificate templates that mirror its rules and records the certificates, exams, hours and vision tests that show you followed it.</p><h3>Can we track CP-189 and SNT-TC-1A certificates for the same technician?</h3><p>Yes. Each certificate is its own record with its own scheme, method, level and dates, so a technician can hold both, and each shows its own status.</p><h3>Will it stop an expired technician being put on a job?</h3><p>It warns rather than blocks by default. Certificates move to expiring soon 90 days out, warning tasks and email alerts go to the people you choose, and timesheets warn if hours are logged against an invalid certificate. A hard check at dispatch can be added as part of your customization scope.</p><h3>Can we track radiographer certification and dosimetry badges?</h3><p>Yes. The NDT profile records radiation safety training and radiation badge number. A radiographer certification card can be recorded as an other-scheme certificate with its expiry and a scanned copy.</p><h3>Does Atlantis NDT provide the training too?</h3><p>Atlantis NDT delivers training based on ASNT SNT-TC-1A. The app also records certificates your people hold from other schemes, such as ISO 9712, PCN or CSWIP, but Atlantis does not train or certify for those.</p><h3>Can we keep AWS CWI and OQ records in the same place?</h3><p>Yes, as other-scheme certificates with their own expiry dates, templates and attachments, so they get the same warnings as NDT certificates.</p><h2>Get your certification records audit-ready</h2><p>Send us an outline of your written practice and a sample of your current tracker, and we will show you how it looks in the Certificates app with templates, expiry lists and alerts set up for your team. <a href=\"/contact?service=erp&amp;subject=Certificates%20quote%20USA\">Request a quote for your US operation</a>, covering the apps and customization you need.</p>\n<h2>Certificates by region</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates global overview</a></li><li><a href=\"/erp/apps/certificates/canada\">Certificates in Canada</a></li><li><a href=\"/erp/apps/certificates/europe\">Certificates in UK &amp; Europe</a></li><li><a href=\"/erp/apps/certificates/middle-east\">Certificates in Middle East</a></li><li><a href=\"/erp/apps/certificates/india\">Certificates in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(United%20States)\">Send an enquiry about Certificates</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/certificates/canada","publishedAt":"2026-09-27","title":"NDT Certification Tracking Software Canada | Atlantis NDT","description":"Record ISO 9712 (NRCan) certs, CNSC exposure device operator cards and vision tests with expiry alerts. Request a quote for Atlantis NDT ERP in Canada.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Certification Tracking in Canada</h1>\n<p>Technician certifications, eye tests and expiry tracking against your written practice. <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Canada runs on central certification, and your records need to show it</h2><p>Canadian NDT differs from the US in one fundamental way. For most industrial work, technicians are certified centrally to CAN/CGSB-48.9712, Canada’s adoption of ISO 9712, through the Natural Resources Canada NDT Certifying Agency. The certificate belongs to the individual, not the employer, and it follows them from company to company. Employer-based ASNT certification still appears, especially in aerospace and for work with US parent companies or clients, but the NRCan certificate is what most Canadian owners and regulators expect to see.</p><p>That shifts what an inspection company has to track. You are not writing the certificate; you are verifying and monitoring someone else’s. You need the level, method and sector, the renewal date, and evidence that the technician’s vision test is current. On top of that sit radiation qualifications for RT crews, provincial pressure-equipment requirements, and site safety tickets that Alberta plants and nuclear stations won’t let you in without.</p><p>Many Canadian companies track all this in spreadsheets, and it shows during turnaround season in Fort McMurray or an outage in Ontario, when dozens of people need to be checked at once.</p><p>The Certificates app in Atlantis NDT ERP records every certification on the technician’s record, works out its status daily, creates a warning task 90 days before expiry, and sends daily email alerts to the people you choose. Atlantis NDT does not train or certify for CGSB or NRCan certification; the app records the certificates your technicians already hold, alongside any ASNT-based qualifications.</p><h2>Recording NRCan ISO 9712 certificates</h2><p>Each certification is its own record: scheme (ISO 9712 for NRCan certificates, with SNT-TC-1A, CP-189, PCN, CSWIP and other also available), level, method, certifying body, issue, expiry and renewal dates, industry sector, OJT hours, training hours, exam passed and attachments.</p><p>The fields line up with how ISO 9712 certification is structured. Certification is by method, level and sector, so a technician might hold UT Level 2 in one sector and MT Level 2 across several. The industry sector field keeps that clear. Certificates are typically valid for five years, followed by renewal on evidence of continued work activity and recertification at the ten-year point. Issue, expiry and renewal dates on each record, with a template per scheme carrying validity in months, show where each technician sits in that cycle.</p><p>For trainees, OJT and training hours matter. Candidates build up documented experience before they can be certified, and a record showing OJT and training hours against each method helps your Level 3 judge when someone is ready to apply for the exam.</p><p>Attach the scanned NRCan certificate, experience records and training certificates, and the evidence is ready when a client asks for it. Because the certifying body is a field, you can separate NRCan certificates from employer-based ASNT certificates held by the same person, each with its own status.</p><h2>Vision tests on the ISO 9712 cycle</h2><p>ISO 9712 requires near-vision testing at least annually, Jaeger J1 or equivalent at not less than 30 cm, plus colour vision adequate for the method. A technician with a valid NRCan certificate and an expired eye test should not be signing reports, and Canadian clients check this.</p><p>The app keeps vision tests as their own records: near vision (J1 or J2), far vision, colour perception, contrast, examiner, clinic, certificate file and expiry. The daily check creates a warning task 90 days before each vision test expires, so the next eye test is booked during a quiet week, not the morning a technician is due to fly north for a camp job.</p><p>Recording J1 or J2 also helps companies whose technicians hold both ISO 9712 and ASNT-based certificates. SNT-TC-1A accepts J2, while ISO 9712 calls for J1. The recorded result shows at a glance which requirement a test satisfies.</p><p>Many Canadian companies use occupational health clinics or optometrists for vision testing. Recording the examiner and the clinic keeps each test traceable, which auditors and client reviewers ask about. Colour perception results matter for PT and colour-contrast MT, so a Level 3 can spot any restriction before scheduling.</p><h2>Radiography crews: CNSC exposure device operators and dosimetry</h2><p>Industrial radiography in Canada is regulated by the Canadian Nuclear Safety Commission. People operating exposure devices must be certified by the CNSC as exposure device operators, trainees work under the direct supervision of a certified operator, and everyone in the work area is monitored with personal dosimetry. Your licence, radiation protection programme and radiation safety officer sit on top of that.</p><p>On the technician’s NDT profile, the Certificates app records radiation safety training, the radiation badge (dosimeter) number and medical fitness expiry, alongside the highest NDT level and methods certified. A CNSC exposure device operator certification can be recorded as an other-scheme certificate with its expiry date, template and scanned card, so it gets the same 90-day warning tasks and email alerts as an NRCan certificate.</p><p>That gives the RSO one place to confirm an RT crew is fully qualified: NRCan RT certificate for interpretation, CNSC certification for operating the device, current training and a badge number. Transport of radioactive sources needs its own discipline; the Fleet app records whether a vehicle can carry radioactive sources along with its transport licence number and expiry. A transportation of dangerous goods training certificate for the driver can be tracked as an other-scheme certificate.</p><p>The app does not replace your CNSC licence records or your radiation protection programme. It keeps your people’s radiation-related qualifications visible and current.</p><h2>Alberta: oil sands, upgraders and ABSA</h2><p>Alberta is where much of Canada’s NDT work happens: oil sands mining and in-situ operations around Fort McMurray and Cold Lake, upgraders and refineries in the Edmonton industrial heartland, and gas plants and pipelines across the province. Pressure equipment there is regulated by ABSA under the Pressure Equipment Safety Regulation, and owners run in-service inspection programmes that contract NDT companies depend on.</p><p>Alberta sites add their own requirements. Contractors are commonly expected to hold Energy Safety Canada tickets such as H2S Alive and CSTS, first aid and site orientations, and camp jobs on rotation make it easy for a ticket to lapse while someone is away. Owners’ contractor prequalification often asks for proof of technician certification and vision tests before mobilisation.</p><p>These tickets can be tracked in the Certificates app as other-scheme certificates with expiry dates and scans, so a lapsing H2S Alive ticket shows up in the same warning tasks and emails as an NRCan renewal. If you prefer dedicated fields for site tickets, that is set up as part of the customization scope agreed with you.</p><p>Spring and fall turnarounds are where tracking falls apart. Crews grow quickly, people join from other companies with their own NRCan certificates, and everyone needs checking at once. With warning tasks generated 90 days ahead, renewals for your core crew can be pulled forward before turnaround season starts, and new arrivals’ certificates can be entered and checked as they are hired.</p><h2>CSA standards, pipelines and welding inspection</h2><p>Canadian codes shape what qualifications a job calls for. CSA W59 governs welded steel construction, and welding inspection organisations and inspectors are certified under CSA W178.1 and W178.2 through the CWB. CSA Z662 covers oil and gas pipeline systems, and interprovincial pipelines fall under the Canada Energy Regulator. CSA B51 sets the boiler and pressure vessel code that the provincial safety authorities apply.</p><p>For an NDT company, that often means one technician carries several kinds of qualification: an NRCan certificate in UT or RT, a CSA W178.2 welding inspector certification, and client-specific pipeline requirements. Each can sit on the same employee record in the Certificates app, the ISO 9712 certificate under its own scheme and the others under other, each with its own template, dates and attachments.</p><p>Keeping them together makes crew planning simpler. The planner can see who holds the NDT method, who holds the welding inspection certificate, and whether both are current, without cross-checking two trackers.</p><p>Your inspection procedures themselves, written to CSA and ASME requirements and approved by your Level 3, can be controlled in the <a href=\"/erp/apps/procedures\">Procedures app</a>, which carries revision history and an approval workflow.</p><h2>Ontario nuclear and provincial regulators</h2><p>Ontario’s nuclear sector is one of the most demanding environments for NDT records. Periodic inspection of CANDU components is governed by CSA N285.4, and utilities running refurbishment and outage programmes at stations such as Bruce, Darlington and Pickering apply strict qualification, training and security requirements to contractor staff. Technicians often need client-specific qualifications on top of their NRCan certificates, plus site access and radiation worker requirements.</p><p>The Certificates app handles this layering: NRCan certificates under ISO 9712, client-specific qualifications as other-scheme certificates with their own templates, radiation safety training and badge number on the NDT profile, and medical fitness expiry where the site requires it. Every qualification has its expiry tracked and a warning task generated 90 days ahead.</p><p>Outside nuclear, provincial safety authorities differ: TSSA in Ontario, Technical Safety BC, the RBQ in Quebec and ABSA in Alberta. Their requirements affect which company certifications you hold and which your clients ask for. Company certifications, such as ISO 9001 registration or a quality programme a regulator or client requires, are tracked in the app with their own alert days.</p><p>For companies working in Quebec, the ERP interface can be set up in French as well as English during implementation.</p><h2>Privacy: medical and vision data under Canadian law</h2><p>Vision test results and medical fitness dates are health information. Private-sector employers are covered by PIPEDA federally and by provincial laws such as Alberta and BC PIPA and Quebec’s Law 25. The practical expectation is the same everywhere: collect what you need, limit who sees it, and protect it.</p><p>In Atlantis NDT ERP, certificates, vision tests and NDT profiles sit on the employee record, and access rights apply. During implementation we agree who sees full medical and vision details, typically HR and the QA manager, and who only sees certification status, such as planners. Hosting arrangements are agreed with you as part of the implementation. This supports your privacy obligations; it does not replace your own policies.</p><h2>Who uses it in a Canadian NDT company</h2><ul><li><strong>QA manager</strong>: works the Expiring Soon and Expired lists, collects renewed NRCan certificates and eye test results, and prepares qualification packs for owner prequalification.</li><li><strong>Level 3</strong>: reviews trainee OJT and training hours, maintains the templates for each scheme, records exam sheets for any employer-based certification, and revokes a certificate when needed.</li><li><strong>Radiation safety officer</strong>: checks CNSC certifications, radiation safety training and badge numbers before RT crews mobilise.</li><li><strong>Operations manager</strong>: checks tickets and certificates before building a rotation or turnaround crew.</li><li><strong>Owner</strong>: watches the dashboard and company certification alerts, including the ISO registration and quality programmes clients require.</li></ul><p>Everyone works from the same record, entered once. When the QA manager is away on a site audit, the alerts still go out and the lists still update.</p><h2>How it connects and what setup looks like</h2><p>Certificates connects to the rest of <a href=\"/erp\">Atlantis NDT ERP</a>. Timesheets warn when a technician with an invalid certificate logs hours. Dashboards show certificates expiring and expired next to calibration due and overdue. Daily email alerts cover technician certificates, calibration certificates and company certifications, with the recipients, look-ahead days and resend interval you set. The <a href=\"/erp/apps/team-assignments\">Team Assignments app</a> blocks double-booking of technicians and equipment and warns on out-of-calibration equipment, and a certificate check at dispatch can be added in your customization scope.</p><p>Setup for a Canadian company usually covers: templates for ISO 9712 (NRCan), any ASNT-based practice you run, CNSC operator cards, CSA W178.2, Energy Safety Canada tickets and client qualifications; import of your current tracker with scanned certificates attached; alerts for the QA manager, RSO and operations; access rights for health data; and links to the other apps you use. Report signatures in the NDT Reports app, and results shown on 3D asset models through Atlantis’s separate <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, rest on these records.</p><p>To see your NRCan roster in the app, <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20Canada\">book a Certificates demo</a>.</p><h2>Frequently asked questions</h2><h3>Can the app record NRCan certificates?</h3><p>Yes. NRCan certificates issued to CAN/CGSB-48.9712 are recorded under the ISO 9712 scheme with level, method, sector and issue, expiry and renewal dates, and the scanned certificate attached.</p><h3>Does Atlantis NDT train technicians for NRCan certification?</h3><p>No. Atlantis NDT’s training is based on ASNT SNT-TC-1A. The Certificates app records ISO 9712 certificates your technicians hold; it does not issue them.</p><h3>Can we track CNSC exposure device operator certification?</h3><p>Yes, as an other-scheme certificate with its own expiry, template and scanned card. Radiation safety training and badge number are on the technician’s NDT profile.</p><h3>What about H2S Alive, CSTS and other site tickets?</h3><p>They can be recorded as other-scheme certificates so they receive the same warning tasks and email alerts, or added as dedicated fields within your customization scope.</p><h3>How early are we warned about expiring certificates?</h3><p>Certificates show as expiring soon 90 days before expiry, and warning tasks are created at the same point for certificates and vision tests. Email alert look-ahead days and resend intervals are configurable.</p><h3>Can technicians hold both NRCan and ASNT certificates?</h3><p>Yes. Each certificate is its own record, so an NRCan ISO 9712 certificate and an employer-based SNT-TC-1A certificate sit side by side with separate status.</p><h2>Bring your NRCan roster into one place</h2><p>Send us a sample of your current certification tracker and the site requirements your crews face, and we will show you how it looks in the app. The system is affordable, accessible and fully customizable. <a href=\"/contact?service=erp&amp;subject=Certificates%20quote%20Canada\">Request a quote for Canada</a> and we will scope it with you.</p>\n<h2>Certificates by region</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates global overview</a></li><li><a href=\"/erp/apps/certificates/usa\">Certificates in United States</a></li><li><a href=\"/erp/apps/certificates/europe\">Certificates in UK &amp; Europe</a></li><li><a href=\"/erp/apps/certificates/middle-east\">Certificates in Middle East</a></li><li><a href=\"/erp/apps/certificates/india\">Certificates in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(Canada)\">Send an enquiry about Certificates</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/certificates/europe","publishedAt":"2026-09-27","title":"NDT Certification Tracking UK and Europe | Atlantis NDT","description":"Track EN ISO 9712, PCN and CSWIP certs, annual vision tests and company accreditations with expiry alerts for UK and EU NDT firms. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Certification Tracking in the UK and Europe</h1>\n<p>Technician certifications, eye tests and expiry tracking against your written practice. <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Certification under EN ISO 9712: the certificate is not the whole story</h2><p>Across the UK and Europe, NDT personnel are certified centrally under EN ISO 9712 by accredited certification bodies: PCN, run by BINDT, in the UK, and national schemes elsewhere, such as those operated through DGZfP in Germany and COFREND in France. The certificate belongs to the technician, is issued by method, level and sector, and moves with them between employers.</p><p>But ISO 9712 is clear that certification is a statement of general competence, not permission to work. The employer is responsible for authorising the individual to operate, for job-specific training, and for making sure the technician’s eyesight is checked every year. So a European NDT company has to track two things: the third-party certificate, and its own evidence that it has authorised that person for the work.</p><p>Add PED requirements for pressure equipment, radiation protection rules for radiographers, offshore certificates for North Sea crews, and GDPR on top of all the health data, and it is easy to see why spreadsheets break down.</p><p>The Certificates app in Atlantis NDT ERP keeps every certification, vision test and exam record on the technician’s employee record, computes status every day, raises a warning task 90 days before anything expires, and sends daily email alerts to the people you choose. Atlantis NDT does not train or certify for EN ISO 9712, PCN or CSWIP; the app records the certificates your people hold from those bodies.</p><h2>Recording EN ISO 9712 and PCN certificates</h2><p>Each certificate is its own record: scheme (ISO 9712, PCN or CSWIP, with SNT-TC-1A, CP-189 and other available), level, method, certifying body, issue, expiry and renewal dates, industry sector, OJT hours, training hours, exam passed and attachments.</p><p>The industry sector field matters under ISO 9712 and PCN, where certificates are issued for product or industry sectors, for example welds, castings, forgings, tubes or aerospace. A UT Level 2 on welds is not the same as a UT Level 2 on castings, and your records should say which.</p><p>The validity cycle is built around dates. An ISO 9712 certificate is typically valid for five years, renewed on evidence of continued satisfactory work activity without significant interruption, and recertified at ten years. PCN follows that structure, with recertification by examination or, where eligible, a structured credit system. Issue, expiry and renewal dates on each record, and a template per scheme holding validity in months, show where each technician sits in the cycle.</p><p>Continuity of work is worth watching. A technician who has been away from a method for a long stretch may struggle to renew, and a company that can show documented, continuous work in the method makes renewal simpler. Attach the evidence your certification body asks for to the certificate record as you go, rather than hunting for it in year five.</p><p>The certifying body field separates PCN certificates from those issued by other European bodies, or from ASNT-based certificates held by technicians who have worked for US or Middle East clients.</p><h2>CSWIP and weld inspection certificates</h2><p>Many UK and European NDT companies also employ welding inspectors certified under CSWIP, run by TWI, at grades such as 3.1 Welding Inspector and 3.2 Senior Welding Inspector, and some technicians hold CSWIP certificates in NDT methods. CSWIP has its own validity and renewal rules, which differ from PCN.</p><p>In the app, CSWIP is a scheme in its own right, so these certificates get their own template, dates and status alongside a technician’s PCN certificates. A planner looking for someone who can cover both visual weld inspection and UT on a fabrication job sees both qualifications on one record, with the status of each.</p><h2>Employer authorisation and internal assessments</h2><p>Because ISO 9712 places authorisation to operate with the employer, many European companies run internal checks before a newly hired technician works unsupervised: a practical on the company’s procedures, a review by the Level 3, and sometimes a written test on client specifications.</p><p>The app’s examination sheets fit this well. They record general, specific and practical scores, a passing score (70% by default, adjustable), and the exam files. Used for internal authorisation assessments, they give you a documented trail: which procedures the technician was assessed on, the scores and the date.</p><p>A written authorisation itself can be attached to the certificate record. If you want authorisation to be its own record type with dates and scope, that can be set up as part of the customization scope agreed with you.</p><p>Where a technician’s status changes, for example after a failed practical or a Level 3 decision, the certificate can be marked revoked. The history stays intact, which an auditor from your certification body or a client will want to see.</p><h2>Annual vision tests</h2><p>ISO 9712 requires near-vision testing at least every twelve months, Jaeger 1 or Times Roman N4.6 or equivalent at not less than 30 cm, and colour vision sufficient for the method. PCN and other schemes apply the same annual rhythm, and the employer is responsible for making sure it happens.</p><p>Vision tests are separate records in the app: near vision (J1 or J2), far vision, colour perception, contrast, examiner, clinic, certificate file and expiry. The daily check creates a warning task 90 days before each test expires. In the UK many companies use occupational health providers or optometrists, and recording the examiner and clinic keeps each test traceable.</p><p>Colour perception results matter for PT and colour-contrast MT. Contrast results can matter for screen-based interpretation in PAUT, TOFD and digital radiography. Having both on record means the Level 3 knows about any restriction before scheduling, and a technician who also holds an ASNT-based certificate can see which vision requirement each test satisfies.</p><h2>PED, UK PER and the codes behind the work</h2><p>For pressure equipment placed on the EU market, the Pressure Equipment Directive 2014/68/EU requires that NDT personnel on permanent joints of Category III and IV equipment are approved by a recognised third-party organisation or a user inspectorate. In Great Britain, the Pressure Equipment (Safety) Regulations 2016 carry the same requirement for UKCA-marked equipment. Notified and approved bodies check this, usually by looking at certificates and records.</p><p>The Certificates app lets you hold that approval evidence where it belongs. The EN ISO 9712 certificate sits on the record; the third-party approval can be attached, or recorded as an other-scheme certificate with its own expiry so it gets the same warnings.</p><p>Method and acceptance standards then shape the work: EN ISO 17640 for UT of welds, EN ISO 17636 for radiography, EN ISO 17638 for MT, EN ISO 3452 for PT and EN ISO 17637 for visual testing, with quality levels to EN ISO 5817. Your procedures, written to these standards and approved by your Level 3, can be controlled in the <a href=\"/erp/apps/procedures\">Procedures app</a> with revision history and an approval workflow. Aerospace work adds EN 4179 and customer requirements, and those certificates can be recorded under their own template.</p><h2>Radiography: IRR17 and radiation protection records</h2><p>In the UK, industrial radiography is regulated by the HSE under the Ionising Radiations Regulations 2017. Employers need HSE consent, a Radiation Protection Adviser and Radiation Protection Supervisors, and radiographers are typically designated classified persons, with dose records kept by an approved dosimetry service and medical surveillance by an appointed doctor. EU member states apply similar rules through their transposition of the Basic Safety Standards Directive 2013/59/Euratom.</p><p>The NDT profile in the Certificates app records radiation safety training, radiation badge number and medical fitness expiry, alongside highest level and methods certified. For classified radiographers, the medical fitness date can hold the review date from the appointed doctor, so it generates a warning before it lapses. RPS training certificates can be recorded as other-scheme certificates.</p><p>The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry, which helps where ADR rules govern road transport of sources. The app does not replace your RPA’s records or regulator submissions; it keeps your people’s qualifications and radiation-related dates visible.</p><h2>North Sea and offshore crews</h2><p>Aberdeen-based inspection companies supporting North Sea operators, and those working in the Norwegian, Dutch and Danish sectors, face an extra stack of documents. Offshore workers need current survival training, such as OPITO BOSIET or FOET, and a valid offshore medical. Rope access technicians hold IRATA or equivalent levels. Operators and duty holders check all of it before anyone is booked on a helicopter.</p><p>In the app, the offshore medical expiry sits on the NDT profile as medical fitness expiry. Survival and rope access certificates can be recorded as other-scheme certificates with expiry dates and scans, so they get the same 90-day warning tasks and daily email alerts as the PCN certificate. Alternatively, dedicated fields can be added in your customization scope.</p><p>Offshore rotations make tracking harder. A technician on a two-weeks-on, three-weeks-off pattern can easily let a certificate lapse mid-rotation, and there is no quick fix once they are on the platform. Warnings well ahead of expiry let renewals, eye tests and medicals be planned for off-rotation weeks.</p><p>Duty holders also audit their contractors’ competence systems. A register where each certificate carries its scheme, certifying body, dates, status and scanned evidence, with a trail of warning tasks showing renewals were planned, makes that audit a short conversation.</p><h2>GDPR and technician health data</h2><p>Vision test results and medical fitness are health data, a special category under the GDPR and UK GDPR. You need a lawful basis to process them, you should keep access to those who need it, and you should not keep them longer than necessary.</p><p>In Atlantis NDT ERP, certificates, vision tests and NDT profiles sit on the employee record, and access rights apply. During implementation we agree who sees full vision and medical details, typically HR and the quality manager, and who only sees certification status, such as planners. Where your data is hosted is agreed as part of implementation. This supports your GDPR obligations; it does not replace your own data protection policies.</p><h2>Who uses it day to day</h2><ul><li><strong>Quality manager</strong>: works the Expiring Soon and Expired lists, gathers renewal evidence for PCN and other certification bodies, and prepares qualification packs for notified bodies and clients.</li><li><strong>Level 3</strong>: maintains scheme templates, runs internal authorisation assessments on examination sheets, and revokes a certificate when needed.</li><li><strong>Radiation Protection Supervisor</strong>: checks radiation safety training, badge numbers and medical review dates before radiography work.</li><li><strong>Operations and offshore coordinators</strong>: check certificates, medicals and survival training before booking rotations.</li><li><strong>Managing director</strong>: follows the dashboard and company certification alerts.</li></ul><p>Everyone works from the same record, entered once, so the register does not depend on one person’s spreadsheet.</p><h2>How it connects and what setup looks like</h2><p>Certificates links to the rest of <a href=\"/erp\">Atlantis NDT ERP</a>. Timesheets warn when a technician with an invalid certificate logs hours. Dashboards show certificates expiring and expired next to calibration due and overdue. Daily email alerts cover technician certificates, calibration certificates and company certifications, including ISO 9001, ISO 45001 or other registrations your clients ask for, with look-ahead days and resend intervals you set. Calibration records themselves sit in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>.</p><p>A typical European setup includes templates for EN ISO 9712, PCN and CSWIP, plus other-scheme templates for PED approvals and offshore and rope access certificates; import of your current register with scanned certificates; access rights for health data; alerts for quality, RPS and operations; and links to the apps you use. Reports signed in the NDT Reports app, and results placed on 3D asset models through Atlantis’s separate <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, rest on these qualification records.</p><p>To see your PCN roster in the app, <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20Europe\">book a Certificates demo</a>.</p><h2>Frequently asked questions</h2><h3>Does the app issue or renew PCN certificates?</h3><p>No. PCN certificates are issued by BINDT, and other ISO 9712 certificates by their own certification bodies. The app records them and tracks their dates. Atlantis NDT’s own training is based on ASNT SNT-TC-1A and does not lead to ISO 9712, PCN or CSWIP certification.</p><h3>Can we record the industry sector on a certificate?</h3><p>Yes. Each certificate has an industry sector field, so a UT certificate on welds is distinguished from one on castings or forgings.</p><h3>How do we record employer authorisation to operate?</h3><p>Attach the authorisation to the certificate record and use examination sheets for internal assessments. A dedicated authorisation record can be added as part of your customization scope.</p><h3>Can we track offshore medicals and survival certificates?</h3><p>Yes. The medical fitness expiry is on the NDT profile. Survival and rope access certificates can be recorded as other-scheme certificates with expiry dates, so they get the same warnings.</p><h3>Is vision and medical data protected?</h3><p>Access rights limit who sees vision and medical details. They are agreed during implementation to fit your GDPR policies.</p><h3>How early are expiry warnings?</h3><p>Certificates show as expiring soon 90 days before expiry, and warning tasks are created at the same point for certificates and vision tests. Email alerts use look-ahead days and resend intervals you configure.</p><h2>Put your certificate register in one place</h2><p>Send us a sample of your current register and the schemes you work with, and we will show you how it looks in the Certificates app. Affordable, accessible and fully customizable. <a href=\"/contact?service=erp&amp;subject=Certificates%20quote%20Europe\">Request a quote for the UK or Europe</a> and we will scope it with you.</p>\n<h2>Certificates by region</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates global overview</a></li><li><a href=\"/erp/apps/certificates/usa\">Certificates in United States</a></li><li><a href=\"/erp/apps/certificates/canada\">Certificates in Canada</a></li><li><a href=\"/erp/apps/certificates/middle-east\">Certificates in Middle East</a></li><li><a href=\"/erp/apps/certificates/india\">Certificates in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(UK%20%26%20Europe)\">Send an enquiry about Certificates</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/certificates/middle-east","publishedAt":"2026-09-27","title":"NDT Certification Tracking Middle East | Atlantis NDT","description":"Track ASNT and ISO 9712 certs, vision tests and company approvals for expatriate NDT crews across Saudi Arabia, UAE, Qatar and Kuwait. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Certification Tracking in the Middle East</h1>\n<p>Technician certifications, eye tests and expiry tracking against your written practice. <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Many schemes, many nationalities, one register</h2><p>An NDT company in Saudi Arabia, the UAE, Qatar or Kuwait rarely has a uniform workforce. A single turnaround crew might include technicians from India, Pakistan, the Philippines, Egypt and further afield, holding ASNT-based certificates from previous employers, ACCP or ASNT Level III certificates, ISO 9712 certificates from PCN or other national bodies, and client approvals issued in the region. Each scheme has its own validity rules, and each client has its own view of which it accepts.</p><p>Then come the documents that have nothing to do with NDT but still stop a technician working: residency and work permits, site passes, medical fitness, H2S and safety training. When crews rotate in and out and dozens of people are hired for a shutdown, the tracker that worked for twenty permanent staff falls apart.</p><p>The Certificates app in Atlantis NDT ERP keeps every certificate, vision test and exam record on the technician’s employee record, computes status daily, creates a warning task 90 days before anything expires, and sends daily email alerts to the people you choose.</p><p>Atlantis NDT’s own training is based on ASNT SNT-TC-1A. The app records ISO 9712, PCN and CSWIP certificates your technicians hold, but Atlantis does not train or certify for those schemes.</p><h2>ASNT and ISO 9712 side by side</h2><p>Both major schemes are common in the Gulf. Many companies certify their technicians under an in-house SNT-TC-1A written practice, often because owners’ specifications reference ASNT, while technicians recruited from Europe or South Asia may hold ISO 9712 certificates from PCN or national bodies. Some hold both.</p><p>Each certification is its own record in the app: scheme (SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP or other), level, method, certifying body, issue, expiry and renewal dates, industry sector, OJT hours, training hours, exam passed and attachments. Certificate templates per scheme carry validity in months, vision test and exam requirements, and minimum OJT and training hours, so an ASNT certificate and an ISO 9712 certificate for the same person each follow their own rules.</p><p>The certifying body field matters here. Under SNT-TC-1A, certification is employer-based, so a technician who arrives holding a previous employer’s ASNT certificate normally needs to be certified under your written practice. Recording the previous certificate with its certifying body and adding your own makes that transition clear, and examination sheets record the general, specific and practical scores and exam files for your certification. The passing score defaults to 70% and can be set to match your written practice.</p><p>Verifying incoming certificates is part of the job too. Attaching the scanned certificate, together with any verification you receive from the issuing body, means a client reviewer can see not just the certificate but that you checked it.</p><h2>Saudi Aramco and client approvals</h2><p>In Saudi Arabia, working for Saudi Aramco means following its engineering standards and procedures (the SAES and SAEP series), its inspection requirements and its contractor approval processes. NDT personnel on Aramco work are typically expected to be qualified and approved under Aramco’s requirements, which can include client-administered examinations and approval cards with their own expiry, on top of their ASNT or ISO 9712 certificates. SABIC and other owners run their own vendor and personnel requirements.</p><p>In the Certificates app, a client approval can be recorded as an other-scheme certificate on the technician’s record, with its method, level, expiry, template and scanned card. It then appears in the same Expiring Soon and Expired lists, warning tasks and email alerts as the technician’s ASNT certificate. A planner can see immediately whether someone is both certified and client-approved for the method a job requires.</p><p>Requirements change, and the precise rules for a project come from the contract and the client’s current standards, so the templates are set up with you during implementation rather than assumed. What the app gives you is a place to hold whatever the client requires, with dates that are checked every day.</p><h2>ADNOC, QatarEnergy, KNPC and the wider Gulf</h2><p>In the UAE, ADNOC and its group companies run pre-qualification for contractors and review the qualifications of inspection personnel on their onshore and offshore sites. In Qatar, work at Ras Laffan and Mesaieed for QatarEnergy follows its own contractor and personnel requirements. In Kuwait, KNPC’s Mina Al-Ahmadi and Al-Zour refineries set theirs. Oman, Bahrain and the petrochemical complexes across the region add more.</p><p>Each owner has its own document checklist, and an NDT company working for several of them needs to produce different packs from the same people. Because each technician’s certificates, vision test, medical fitness and radiation details sit on one record with attachments, a pack for ADNOC and a pack for KNPC come from the same source instead of separate folders per client.</p><p>Third-party inspection agencies acting for these owners frequently audit NDT subcontractors’ personnel records. A register where every certificate carries a certifying body, dates, status and the scanned evidence stands up to that review.</p><p>Company approvals matter just as much. Registration as an approved vendor, ISO 9001 and ISO 45001 certificates and other accreditations your clients require can be tracked as company certifications with their own alert days, so a renewal or re-audit is planned before it can affect a tender.</p><h2>Residency, medicals and site documents</h2><p>For expatriate crews, NDT qualifications are only part of the picture. A technician with a valid Level II certificate still can’t work if their iqama or residence visa has lapsed, their medical is out of date, or their site pass or H2S training has expired.</p><p>The Certificates app’s NDT profile includes medical fitness expiry, alongside highest level, methods certified, radiation safety training and radiation badge number. Safety training such as H2S certificates can be tracked as other-scheme certificates with expiry dates and scans, so they receive the same warning tasks and email alerts as NDT certificates.</p><p>Residency and passport documents are not a built-in part of the Certificates app. If you want iqama, visa, passport and site pass expiries on the same record with the same kind of warnings, that is configured during implementation as part of the customization scope agreed with you, so HR and operations work from one list.</p><p>The payoff comes at mobilisation. When a client calls on a Thursday for twelve technicians on Sunday, the question is not only who is certified but who can legally travel to site and pass the gate. The fewer places that answer lives in, the faster you can respond.</p><h2>Vision tests for a rotating workforce</h2><p>Both ASNT-based and ISO 9712 schemes require regular near-vision tests, J2 under SNT-TC-1A and J1 under ISO 9712, and Gulf clients check them. Technicians often take their eye tests at local clinics or before arriving from their home country, so certificates arrive in different formats and languages.</p><p>Vision tests are separate records in the app: near vision (J1 or J2), far vision, colour perception, contrast, examiner, clinic, certificate file and expiry. The daily check creates a warning task 90 days before each test expires, which gives time to book a test before a technician leaves on annual leave or before the next shutdown, rather than after.</p><p>Recording J1 or J2 shows which scheme a test satisfies, which matters for technicians holding both ASNT and ISO 9712 certificates. Colour perception results matter for PT and colour-contrast MT. Recording the examiner and clinic also gives a client reviewer something to check when a test was done overseas.</p><h2>Radiography: NRRC, FANR and source crews</h2><p>Industrial radiography is licensed by national regulators, including the Nuclear and Radiological Regulatory Commission in Saudi Arabia and the Federal Authority for Nuclear Regulation in the UAE, with equivalent authorities elsewhere in the Gulf. Licensed companies must show that radiographers are trained in radiation safety, that personal dosimetry is in place and that a radiation protection officer oversees the work.</p><p>On the NDT profile, the Certificates app records radiation safety training and radiation badge number. Radiation worker or protection officer certificates can be recorded as other-scheme certificates with expiry and scans, so they are warned 90 days out. The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry.</p><p>The app does not replace your licence records or regulator submissions. It keeps your radiographers’ qualifications and radiation-related dates in one place for the radiation protection officer to check before a crew leaves the camp.</p><h2>Shutdown and turnaround season</h2><p>Turnarounds in the Gulf are concentrated in the cooler months, and they are where tracking breaks down. Crews expand quickly, short-term technicians join from other companies or from overseas, and every one of them needs checking before the client’s review.</p><p>The app helps in two ways. For your core crew, warning tasks generated 90 days ahead let renewals be pulled forward before the season starts, instead of being discovered mid-shutdown. For new arrivals, certificates, vision tests and client approvals are entered on hire with scans attached, so they appear in the same lists and alerts as everyone else.</p><p>Timesheets then act as a backstop: if hours are logged for a technician whose certificate is not valid, the timesheet shows a warning before the hours are approved and billed. Planners working in the <a href=\"/erp/apps/team-assignments\">Team Assignments app</a> see double-booking of technicians and equipment blocked and out-of-calibration equipment flagged; a certificate check at dispatch can be added in your customization scope.</p><p>When the shutdown ends, short-term technicians’ records stay in the system with their certificates and history. If you bring the same people back next season, you start from their existing record rather than a blank form.</p><h2>Who uses it in a Gulf NDT company</h2><ul><li><strong>QA/QC manager</strong>: works the Expiring Soon and Expired lists, verifies incoming certificates, and prepares personnel packs for client and third-party reviews.</li><li><strong>Level III</strong>: maintains templates, records exam sheets under the written practice, and revokes certificates where needed.</li><li><strong>HR and government relations staff</strong>: keep medicals, and any residency fields agreed in scope, up to date.</li><li><strong>Radiation protection officer</strong>: checks radiation training and badge numbers before RT work.</li><li><strong>Operations manager</strong>: checks the whole picture before mobilising a crew.</li><li><strong>General manager</strong>: follows the dashboard and the company certification alerts that protect vendor approvals.</li></ul><p>Everyone works from the same record, so the register survives staff rotation in the office as well as on site.</p><h2>How it connects and what setup looks like</h2><p>Certificates links to the rest of <a href=\"/erp\">Atlantis NDT ERP</a>. Dashboards show certificates expiring and expired next to calibration due and overdue. Daily email alerts cover technician certificates, calibration certificates and company certifications, with recipients, look-ahead days and resend intervals you set. VAT invoicing is configured locally during implementation in the Invoicing app, and the interface can be set up in Arabic and English.</p><p>A typical Gulf setup covers templates for your SNT-TC-1A written practice, ISO 9712 and PCN, client approvals, H2S and radiation worker certificates; import of your current tracker with scans; alerts for QA, the radiation protection officer, HR and operations; any extra fields for residency documents agreed in your customization scope; and access rights for medical data. Reports signed in the NDT Reports app, and results placed on 3D models of plant assets through Atlantis’s separate <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, rest on these records. For technicians working towards SNT-TC-1A certification, Atlantis also runs <a href=\"/training\">ASNT SNT-TC-1A-based training</a>.</p><p>To see your crew register in the app, <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20Middle%20East\">book a Certificates demo</a>.</p><h2>Frequently asked questions</h2><h3>Can we track ASNT and ISO 9712 certificates for the same technician?</h3><p>Yes. Each is its own record with its own scheme, method, level, certifying body and dates, and each shows its own status.</p><h3>Can the app record Aramco or other client approvals?</h3><p>Yes, as other-scheme certificates with method, level, expiry, template and scanned card, so they get the same warnings as NDT certificates. The exact client requirements are confirmed with you during implementation.</p><h3>Does it track iqama and visa expiry?</h3><p>Not as a built-in feature. Residency, passport and site pass expiries can be added during implementation as part of your customization scope. Medical fitness expiry is already on the NDT profile.</p><h3>Does Atlantis NDT provide ISO 9712 or PCN certification?</h3><p>No. Atlantis NDT’s training is based on ASNT SNT-TC-1A. The app records ISO 9712, PCN and CSWIP certificates issued by their own bodies.</p><h3>How early are we warned about expiring certificates?</h3><p>Certificates show as expiring soon 90 days before expiry, with warning tasks for certificates and vision tests at the same point. Email alert look-ahead days and resend intervals are configurable.</p><h3>Can we track company approvals and ISO certificates?</h3><p>Yes. Company certifications such as vendor approvals and ISO registrations are tracked with their own alert days.</p><h2>Get your crew register ready before the next shutdown</h2><p>Send us a sample of your current tracker and the client requirements your crews face, and we will show you how it looks in the app. Affordable, accessible and fully customizable. <a href=\"/contact?service=erp&amp;subject=Certificates%20quote%20Middle%20East\">Request a quote for the Middle East</a> and we will scope it with you.</p>\n<h2>Certificates by region</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates global overview</a></li><li><a href=\"/erp/apps/certificates/usa\">Certificates in United States</a></li><li><a href=\"/erp/apps/certificates/canada\">Certificates in Canada</a></li><li><a href=\"/erp/apps/certificates/europe\">Certificates in UK &amp; Europe</a></li><li><a href=\"/erp/apps/certificates/india\">Certificates in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(Middle%20East)\">Send an enquiry about Certificates</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/certificates/india","publishedAt":"2026-09-27","title":"NDT Certification Tracking Software India | Atlantis NDT","description":"Track ASNT, ISO 9712 and ISNT technician certs, vision tests, AERB radiography records and company approvals in one ERP app. Request a quote today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Certification Tracking in India</h1>\n<p>Technician certifications, eye tests and expiry tracking against your written practice. <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Two schemes, many clients, and a lot of paperwork</h2><p>Indian NDT companies work across an unusually wide range of requirements. A fabricator in Vadodara exporting pressure vessels to a US client works to ASME and wants ASNT-certified technicians. A service company at a refinery shutdown in Jamnagar or Panipat faces client and consultant checks on every technician. A manpower supplier in Chennai or Hyderabad sends crews to the Gulf, where each client has its own rules. A boiler job needs IBR paperwork, a radiography crew needs AERB approvals, and PSU tenders ask for technician CVs and certificates at the bid stage.</p><p>In most companies all of this lives in Excel sheets, phone photos of certificates and paper files. It works until a tender deadline, an audit by a third-party inspection agency, or a shutdown where fifty technicians need checking in a week.</p><p>The Certificates app in Atlantis NDT ERP keeps every certification, vision test and exam record on the technician’s employee record. It computes each certificate’s status daily, creates a warning task 90 days before anything expires, and sends daily email alerts to the people you choose. Atlantis NDT has a team in Hyderabad and sets up the ERP for Indian NDT companies.</p><p>Atlantis NDT’s own training is based on ASNT SNT-TC-1A. The app records ISO 9712 and other certificates your technicians hold, but Atlantis does not train or certify for those schemes.</p><h2>ASNT, ISO 9712 and IS 13805 certificates</h2><p>Both major schemes are common in India. Many companies certify their technicians under an in-house SNT-TC-1A written practice, which suits export fabrication, US clients and the Middle East market. Others rely on third-party certification to ISO 9712, or its Indian counterpart IS 13805, through Indian certification schemes such as ISNT’s, or through PCN and other international bodies. Many experienced technicians hold both.</p><p>Each certification is its own record: scheme (SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP or other), level, method, certifying body, issue, expiry and renewal dates, industry sector, OJT hours, training hours, exam passed and attachments. Certificate templates per scheme hold validity in months, whether a vision test and exam are required, and minimum OJT and training hours.</p><p>For companies running an SNT-TC-1A written practice, examination sheets record general, specific and practical scores, the passing score (70% by default, adjustable to your written practice) and the exam files. When a client’s QA engineer or a third-party inspector asks how a technician was certified, the answer is on one screen.</p><p>The certifying body field helps with a common Indian situation: technicians joining with a certificate from a previous employer or a training institute. Under SNT-TC-1A, an employer-based certificate does not automatically carry over to a new employer. Recording the earlier certificate with its issuer, alongside the one you issue under your own practice, makes the history clear and keeps the audit trail honest.</p><h2>Export fabricators and ASME code shops</h2><p>Fabrication hubs around Vadodara, Mumbai, Pune, Chennai and Hyderabad build pressure vessels, heat exchangers, piping spools and structural modules for export. Shops holding ASME certification work under the eye of an Authorized Inspector, and ASME Section V expects NDT personnel to be qualified to a written practice, typically one based on SNT-TC-1A. Overseas clients and their inspectors then sample personnel records during fabrication.</p><p>For these shops the written practice is the anchor. Certificate templates in the app carry its validity, vision, exam and hours rules. Examination sheets hold scores and papers. OJT and training hours on each record show how a trainee progressed to Level I and Level II. When the Authorized Inspector or a client auditor asks for records, they are in one place.</p><p>Atlantis NDT runs <a href=\"/training\">SNT-TC-1A-based NDT training</a> for Level I, II and III candidates, and the hours completed can be recorded on each certificate. Many shops also employ welding inspectors holding CSWIP or AWS certificates for client inspections; these can be recorded under the CSWIP scheme or as other-scheme certificates on the same employee record.</p><h2>IBR and boiler work</h2><p>Boilers and boiler components in India are governed by the Indian Boiler Regulations, with inspection and approval by state boiler inspectorates and recognised inspecting authorities. NDT of boiler welds, especially radiography, is reviewed as part of that process, and power plant, sugar mill, process industry and boiler manufacturer clients expect the NDT personnel on the job to be properly qualified and documented.</p><p>In the Certificates app, the technician’s NDT certificate sits alongside any approval or recognition that a client or inspecting authority asks for, recorded as an other-scheme certificate with its expiry and scan. When a boiler inspector or a client’s QA engineer asks for the radiographer’s credentials, your team pulls them from one record.</p><p>Your NDT procedures for IBR work, written to the applicable requirements and approved by your Level III, can be controlled in the <a href=\"/erp/apps/procedures\">Procedures app</a> with revision history and an approval workflow, so the procedure a technician worked to and the certificate they held are both traceable.</p><h2>PESO, pressure vessels and petroleum installations</h2><p>PESO, the Petroleum and Explosives Safety Organisation, regulates pressure vessels for compressed gases under the SMPV(U) Rules, gas cylinders, and petroleum storage and handling installations. Fabricators of LPG bullets, storage vessels and cryogenic tanks, and service companies inspecting depots and terminals, work within that framework, usually with a third-party inspection agency checking the NDT.</p><p>These jobs tend to come with document reviews before and during fabrication. TPI engineers and client inspectors want to see the technician’s certificate, level and method, and often a current vision test. With everything attached to the technician’s record, your QA team can answer those requests immediately instead of searching files and phones.</p><p>Company certifications matter here as well. ISO 9001, ISO 45001 and any approvals your clients require can be tracked as company certifications with their own alert days, so a lapse doesn’t surface in the middle of a tender or an inspection.</p><h2>Radiography: AERB licensing, RSOs and TLD badges</h2><p>Industrial radiography in India is regulated by the Atomic Energy Regulatory Board. Companies need AERB licences for their radiography sources and a Radiological Safety Officer approved by AERB, radiographers must hold the required radiography certification, and everyone working with sources is monitored with personal dosimeters, typically TLD badges from an accredited personnel monitoring service. Source movement, storage and transport all fall under AERB’s oversight.</p><p>On the technician’s NDT profile, the Certificates app records radiation safety training, radiation badge number and medical fitness expiry, alongside highest level and methods certified. Radiographer and RSO certifications can be recorded as other-scheme certificates with expiry dates and scans, so they are warned 90 days out like any NDT certificate. The badge number keeps the link between a person and their dose records clear.</p><p>The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry. The ERP does not replace your AERB licence records or regulatory submissions; it keeps your radiographers’ qualifications and radiation-related dates in one place for the RSO to check before a crew leaves for site.</p><h2>Refineries, PSUs and tender pre-qualification</h2><p>India’s large refineries and petrochemical complexes, from Jamnagar to Panipat, Paradip, Kochi, Mumbai and Visakhapatnam, run major shutdowns that rely on contract NDT crews. Public sector owners such as IOCL, BPCL, HPCL, ONGC and GAIL, often with consultants such as EIL acting as project management consultant, buy much of their inspection work through tenders.</p><p>Those tenders typically ask for technician CVs and qualification certificates at bid stage, and site teams check them again at mobilisation. Missing or expired documents can weaken a bid or delay a crew. With certificates, vision tests and attachments on each technician’s record, building a tender annexure becomes a matter of filtering the right people and collecting their files.</p><p>Shutdowns follow. Crews expand, short-term technicians join, and everyone needs checking. Warning tasks generated 90 days ahead let renewals for your core crew be pulled forward before the shutdown, and new arrivals’ certificates are entered on hire so they appear in the same lists and alerts. Timesheets act as a backstop: if hours are logged for a technician whose certificate is not valid, the timesheet shows a warning before the hours are approved and billed.</p><p>Planners using the <a href=\"/erp/apps/team-assignments\">Team Assignments app</a> get blocking of double-booked technicians and equipment and warnings on out-of-calibration equipment; a certificate check at dispatch can be added in your customization scope.</p><h2>Vision tests</h2><p>SNT-TC-1A calls for an annual near-vision test at J2, and ISO 9712 calls for J1, both with colour vision checks. In India these are usually done by an ophthalmologist or an optometry clinic, and the certificate format varies widely from one clinic to the next.</p><p>Vision tests are separate records in the app: near vision (J1 or J2), far vision, colour perception, contrast, examiner, clinic, certificate file and expiry. The daily check creates a warning task 90 days before each test expires. Recording J1 or J2 shows which scheme a test satisfies, which matters for technicians holding both ASNT and ISO 9712 certificates. Colour perception results matter for PT and colour-contrast MT.</p><p>For manpower suppliers sending technicians to Gulf clients, a current vision test and a complete certificate pack before departure avoids a technician being turned away at the client’s document review after a costly flight.</p><h2>Personal data under the DPDP Act</h2><p>Technician records include personal data, and vision and medical results are sensitive. The Digital Personal Data Protection Act, 2023 sets out duties for organisations handling personal data, including using it for a clear purpose, protecting it and limiting access.</p><p>In Atlantis NDT ERP, certificates, vision tests and NDT profiles sit on the employee record and access rights apply. During implementation we agree who sees full vision and medical details, typically HR and the QA manager, and who sees only certification status, such as planners and site supervisors. This supports your obligations; it does not replace your own data protection policies.</p><h2>Who uses it in an Indian NDT company</h2><ul><li><strong>QA/QC manager</strong>: works the Expiring Soon and Expired lists, prepares tender annexures and personnel packs for TPI and client audits.</li><li><strong>Level III</strong>: maintains scheme templates, records exam sheets under the written practice, and revokes certificates where needed.</li><li><strong>Radiological Safety Officer</strong>: checks radiographer certifications, radiation safety training and TLD badge numbers before RT work.</li><li><strong>Operations or project manager</strong>: checks who is qualified and current before building a shutdown crew or sending a team overseas.</li><li><strong>Proprietor or managing director</strong>: follows the dashboard and the company certification alerts that keep vendor registrations and ISO certificates current.</li></ul><p>Everyone works from the same record, entered once, instead of each person keeping their own Excel sheet.</p><h2>How it connects and what setup looks like</h2><p>Certificates links to the rest of <a href=\"/erp\">Atlantis NDT ERP</a>. Dashboards show certificates expiring and expired next to calibration due and overdue. Daily email alerts cover technician certificates, calibration certificates and company certifications, with recipients, look-ahead days and resend intervals you set. GST invoicing is configured locally during implementation in the Invoicing app.</p><p>A typical Indian setup covers templates for your SNT-TC-1A written practice, ISO 9712 and IS 13805 certificates, AERB radiographer and RSO certifications, and client-specific approvals; import of your current Excel tracker with scans attached; alerts for QA, the RSO and operations; access rights for health data; and links to the apps you use. Reports signed in the NDT Reports app, and results placed on 3D asset models through Atlantis’s separate <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, rest on these records.</p><p>To see your technician register in the app, <a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20India\">book a Certificates demo</a>.</p><h2>Frequently asked questions</h2><h3>Can the app track both ASNT and ISO 9712 certificates?</h3><p>Yes. Each certificate is its own record with its own scheme, level, method, certifying body and dates, so a technician can hold both with separate status.</p><h3>Can we record AERB radiographer and RSO certifications?</h3><p>Yes, as other-scheme certificates with expiry dates and scans. Radiation safety training and radiation badge number are on the technician’s NDT profile.</p><h3>Does Atlantis NDT train for ISO 9712 or ISNT certification?</h3><p>No. Atlantis NDT’s training is based on ASNT SNT-TC-1A. The app records ISO 9712 and other certificates issued by their own bodies.</p><h3>Will it help with PSU tender documentation?</h3><p>It keeps each technician’s certificates, vision tests and scans on one record, so you can filter the right people and collect their files for a tender annexure quickly.</p><h3>How early are we warned about expiring certificates?</h3><p>Certificates show as expiring soon 90 days before expiry, with warning tasks for certificates and vision tests at the same point. Email alert look-ahead days and resend intervals are configurable.</p><h3>Can we track our company’s ISO and vendor approvals?</h3><p>Yes. Company certifications are tracked with their own alert days and included in the daily email alerts.</p><h2>Replace the Excel tracker before the next shutdown</h2><p>Send us a sample of your current tracker and the clients and schemes you work with, and we will show you how it looks in the Certificates app. Affordable, accessible and fully customizable. <a href=\"/contact?service=erp&amp;subject=Certificates%20quote%20India\">Request a quote for India</a> and we will scope it with you.</p>\n<h2>Certificates by region</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates global overview</a></li><li><a href=\"/erp/apps/certificates/usa\">Certificates in United States</a></li><li><a href=\"/erp/apps/certificates/canada\">Certificates in Canada</a></li><li><a href=\"/erp/apps/certificates/europe\">Certificates in UK &amp; Europe</a></li><li><a href=\"/erp/apps/certificates/middle-east\">Certificates in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Certificates%20demo%20(India)\">Send an enquiry about Certificates</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/elearning","publishedAt":"2026-09-27","title":"NDT eLearning & Training LMS for NDT Companies | Atlantis NDT","description":"NDT eLearning portal in Atlantis NDT ERP: Level I-III courses, quizzes, training records and Practical NDT 3D practice. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT eLearning Portal for Technician Training and Records</h1>\n<p>Courses, quizzes and certificates for technician training and refreshers. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Why NDT companies need their own learning portal</h2><p>Most NDT companies already train their people. The problem is where that training lives. Lesson slides sit on a Level III's laptop. Quiz papers are photocopied and marked by hand. The proof that a technician finished a refresher is an email somewhere, or a signature on a sheet that went into a box file. Then an auditor, a client or your own written practice asks you to show it, and someone loses two days rebuilding a training history from scraps.</p><p>Field schedules make it worse. Technicians rotate between sites, shutdowns and night shifts. Classroom sessions get cancelled because half the crew is mobilised. New hires wait weeks for a trainer to be free. Refreshers slip, and nobody notices until a certificate is about to lapse.</p><p>The eLearning app in Atlantis NDT ERP puts that training in one place. Courses, videos, quizzes, learner accounts and completion records sit inside the same system you use for jobs, technicians, certificates and invoices. A technician can watch a lesson from a hotel room the night before mobilisation. Your Level III can see who has finished what without chasing anyone. And because the portal opens straight into Practical NDT, Atlantis's 3D practice platform, learners can move from theory to hands-on scanning practice without waiting for a free slot on a real calibration block.</p><p>This page explains what the app does, how a course runs day to day, who uses it, how it connects to the rest of the ERP and what setting it up looks like.</p><h2>What the eLearning app does</h2><p>The app is a course portal set up for NDT training rather than generic corporate learning. As configured by Atlantis, it gives you:</p><ul><li><strong>Level I, Level II and Level III sections.</strong> Courses are grouped by level, so a trainee sees what applies to them and a Level II candidate isn't wading through Level III procedure-writing material.</li><li><strong>Video lessons from OneDrive or SharePoint.</strong> Your existing training videos stay in your Microsoft storage and play inside the portal, with download protection so a lesson isn't simply saved and passed around.</li><li><strong>Quizzes, including questions imported from Word files.</strong> If your Level III already keeps question banks in Word documents, they can be imported rather than typed in again.</li><li><strong>Certificates of completion.</strong> Learners who complete a course receive a completion certificate generated by the system.</li><li><strong>Admin-controlled learner accounts.</strong> Admins create learner accounts and grant or revoke course access. When someone leaves the company, their access goes with them.</li><li><strong>A learner dashboard.</strong> Each learner sees their courses, their progress and what's left to finish.</li><li><strong>Auto-join for invited members.</strong> Invite a technician to a course and they are enrolled when they accept, with no separate sign-up step to get wrong.</li><li><strong>Online course sales.</strong> If you train outside candidates as well as your own staff, courses can be sold through the portal.</li><li><strong>A Practical NDT section.</strong> Enrolled learners get a link into Practical NDT, the 3D practice platform described below.</li></ul><p>Everything else, such as how your courses are structured, what your completion rules are and how records flow into technician files, is set up with you during implementation.</p><h2>Practical NDT: hands-on 3D practice inside the portal</h2><p>Reading about skip distance is not the same as finding a lack of fusion. That gap between theory and hands-on skill is where most NDT training struggles, because practice time needs instruments, probes, reference blocks, flawed specimens and a trainer, and all of those are usually busy on paying work.</p><p><a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive 3D, game-like NDT practice platform. Learners work through scenarios for UT, PAUT, RT, MT, PT, VT, ET and TOFD on virtual welds, pipes, pressure vessels and castings. They set up, scan, look for indications and make calls on what they've found, in a space where a mistake costs nothing and the specimen is always available.</p><p>Inside the eLearning portal, every enrolled learner gets a Practical NDT section that opens the platform. Access is granted automatically when the learner is enrolled, or an admin can grant it manually, for example to a supervisor who isn't taking a course but wants to try the scenarios. There's no separate account list to maintain in a second system.</p><p>How you use it depends on your training programme. Some companies pair each Level I video module with a matching Practical NDT scenario. Others use it as a warm-up before a practical exam on real specimens, or as a refresher for technicians coming back to a method they haven't used for months. It does not replace the hands-on practical examination your written practice requires on real parts. It gives learners far more practice time before they get there.</p><p>Want to see it? <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20and%20Practical%20NDT%20demo\">Book a demo of eLearning with Practical NDT</a> and we'll walk you through a learner's view.</p><h2>How a course runs day to day</h2><p>Here is a typical flow for a new Level I trainee in ultrasonic testing.</p><ol><li><strong>Account and invitation.</strong> An admin creates the learner account and invites the trainee to the UT Level I course. The trainee accepts and is enrolled automatically.</li><li><strong>Practical NDT access.</strong> On enrolment the trainee's Practical NDT access is switched on, so the practice section appears for them.</li><li><strong>Lessons.</strong> The trainee works through video lessons at their own pace, from the office, the workshop or a site cabin with a decent connection.</li><li><strong>Quizzes.</strong> Each module ends with a quiz drawn from your own question bank. Results show where a learner is weak before it matters on a job.</li><li><strong>Practice.</strong> Between modules, the trainee runs UT scenarios in Practical NDT on virtual welds and plate.</li><li><strong>Completion.</strong> When the course is done, the system issues a certificate of completion.</li><li><strong>Oversight.</strong> The Level III or training coordinator checks progress in the backend rather than asking around.</li></ol><p>Refreshers work the same way, just shorter. When a procedure changes, or a technician returns to a method after a long gap, assign a short course, let them complete it between jobs and keep the completion record.</p><p>What the portal doesn't do is certify anyone. Under ASNT SNT-TC-1A, your company's written practice defines training, experience, examinations and certification, and your Level III remains responsible for it. The portal gives you a clean, provable record of the classroom part of the journey and the practice around it.</p><h2>Building courses from material you already have</h2><p>Most NDT companies don't need to create a training library from nothing. They already have one, scattered: recorded toolbox talks, method videos made by a senior technician, slide decks, question banks typed up years ago for the last audit. The eLearning app is set up to use that material rather than make you start over.</p><h3>Videos stay in OneDrive or SharePoint</h3><p>If your videos already sit in Microsoft 365, they stay there. The portal plays them from OneDrive or SharePoint inside the lesson, with download protection turned on. You don't have to re-upload large files to a new platform, and your document control stays where it is.</p><h3>Quiz questions imported from Word</h3><p>Question banks written in Word can be imported into quizzes. That matters in NDT because a single method at a single level can mean a long list of general and specific questions, and nobody wants to paste them in one at a time. After import, your Level III reviews and adjusts them in the portal.</p><h3>Structure by level and method</h3><p>Courses sit in Level I, II and III sections. Within those, a common structure is one course per method per level, plus short cross-method courses such as radiation safety awareness, how to read a procedure or reporting basics. The exact structure is agreed with you.</p><h3>Atlantis course content</h3><p>If you'd rather not build everything yourself, Atlantis runs NDT <a href=\"/training\">training</a> based on ASNT SNT-TC-1A. Where it fits your programme, that content can be discussed as part of your implementation scope.</p><h2>Training records and the rest of the ERP</h2><p>A learning portal on its own is just another silo. The value of running it inside Atlantis NDT ERP is that the training record sits next to everything else you know about the technician.</p><p>The <a href=\"/erp/apps/certificates\">Certificates app</a> holds each technician's certifications: scheme, level, method, issue and expiry dates, OJT hours, training hours, exam results and vision tests. It marks certificates as expiring soon 90 days before expiry and creates warning tasks. When that warning appears, the refresher or re-training can be assigned in eLearning straight away, in the same system.</p><p>How course completions relate to a technician's training hours in Certificates is agreed during implementation. Some companies want a completion recorded against the technician file; others want the Level III to confirm hours by hand before anything counts. Both are handled as part of the customization scope agreed with you.</p><p>Other connections worth knowing about:</p><ul><li><strong>Employees.</strong> The learner is the same person as the technician record, with their NDT profile, highest level and methods certified.</li><li><strong>Surveys.</strong> Standard Surveys can run competency questionnaires or course feedback forms alongside the portal.</li><li><strong>Team Assignments.</strong> The technician availability calendar has a training status, so a technician booked for a training day isn't dispatched to site by mistake.</li></ul><p>The result: when a client asks for a technician's training evidence, the certification, the completion record and the job history are in one place, not three.</p><h2>Who uses the eLearning portal</h2><h3>NDT Level III and training coordinators</h3><p>They own course content, question banks and completion rules. They see who has finished, who is stuck on a quiz and who hasn't logged in. They use the portal to deliver the organised training their written practice calls for and to keep evidence ready for audits.</p><h3>Technicians and trainees</h3><p>They log in, see their courses on the dashboard, watch lessons, take quizzes and open Practical NDT to practise. No paper, and no waiting for the next classroom slot.</p><h3>QA/QC and operations managers</h3><p>They care that the right people are trained before they go to site. Seeing training status next to certificate status and availability makes that check quick.</p><h3>HR and admin staff</h3><p>They create learner accounts and revoke access when someone leaves. Because access is admin-controlled, a former employee doesn't walk away with your course library.</p><h3>Owners</h3><p>They want training to stop being a hidden cost that's hard to prove. A portal with records, plus the option to sell courses to outside learners, makes it visible.</p><h3>External learners</h3><p>If you sell courses, outside candidates buy and take them through the same portal, with their own dashboard, without seeing anything else in your ERP.</p><h2>Selling courses to outside learners</h2><p>Plenty of NDT service companies already train outsiders informally: a client's QC staff, fresh graduates hoping to join the industry, technicians from a partner company. The eLearning app supports online course sales, so that training can be offered through the portal instead of being arranged over email and chased for payment.</p><p>You decide which courses are for sale and which are internal only. An internal UT Level II refresher built around your own procedures probably stays private. A general introduction to NDT methods, a Level I theory course or a radiation safety awareness module might be worth offering publicly.</p><p>Sales run through the standard sales and accounting side of the ERP, so orders and invoices land in the same books as the rest of your business. Taxes are set up for your country during implementation.</p><p>Pairing a course with Practical NDT access can make a strong offer, because most outside learners have no access to equipment at all. For them, a 3D scenario on a virtual weld is often the first time they see what a real scan looks like.</p><p>One caution: be clear in course descriptions about what a learner is getting. A course completion certificate is not NDT certification. Certification is issued by an employer under its written practice, or by a certification body under a central scheme. Honest descriptions protect your reputation and the learner.</p><h2>What implementation looks like</h2><p>Atlantis sets up the eLearning app as part of Atlantis NDT ERP, the same way it sets up the other apps. A typical rollout runs like this:</p><ol><li><strong>Discovery call.</strong> We look at your written practice, your current training material, who needs training and whether you want to sell courses.</li><li><strong>Structure.</strong> We agree the Level I, II and III sections, the course list and naming, so the portal matches how your Level III thinks about training.</li><li><strong>Content connection.</strong> We connect your OneDrive or SharePoint video library and import quiz questions from your Word files.</li><li><strong>Accounts and access.</strong> We set up admin roles, create the first learner accounts and set the Practical NDT access rule: automatic on enrolment, manual, or both.</li><li><strong>Links to the ERP.</strong> We agree how training relates to Certificates, Employees and availability, and configure it.</li><li><strong>Pilot.</strong> One course, a handful of learners, real feedback, then adjustments.</li><li><strong>Handover.</strong> Your admins learn to add courses, invite learners and manage access themselves.</li></ol><p>You can start with eLearning alone or as part of the full <a href=\"/erp\">Atlantis NDT ERP</a>. Cost is quote on request and depends on the scope you choose. The aim is simple: affordable, accessible and fully customizable, configured around the way your company already trains.</p><p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20implementation%20quote\">Request a quote for eLearning implementation</a>.</p><h2>Frequently asked questions</h2><h3>Is the eLearning app an LMS for NDT training?</h3><p>Yes. It is a learning management system inside Atlantis NDT ERP, set up for NDT: Level I, II and III sections, video lessons, quizzes, completion certificates, admin-controlled learner accounts and a link into the Practical NDT 3D practice platform.</p><h3>Does completing a course certify a technician?</h3><p>No. A certificate of completion shows a course was finished. Certification under ASNT SNT-TC-1A is the employer's decision under its written practice, based on training, experience and examinations, with Level III oversight.</p><h3>Can we use our own videos and question banks?</h3><p>Yes. Videos play from OneDrive or SharePoint with download protection, and quiz questions can be imported from Word files, then reviewed by your Level III.</p><h3>How do learners get into Practical NDT?</h3><p>Through the Practical NDT section in the portal. Access is granted automatically when a learner is enrolled, or manually by an admin.</p><h3>Can we remove access when a technician leaves?</h3><p>Yes. Admins create learner accounts and grant or revoke access, so a leaver's access can be removed on their last day.</p><h3>Does Atlantis provide training content?</h3><p>Atlantis offers NDT training based on ASNT SNT-TC-1A. Whether any of it becomes part of your portal is agreed in your implementation scope.</p><h3>What does it cost?</h3><p>It's quote on request. Scope drives it: eLearning alone or with the wider ERP, the number of courses to set up and the customization you need.</p><h2>See eLearning and Practical NDT working together</h2><p>If training at your company still lives on laptops, in box files and in inboxes, the fix doesn't have to be a big project. Start with one course, one group of learners and Practical NDT switched on, and see how it changes the way your Level III works. Explore the 3D scenarios on the <a href=\"/practical-ndt\">Practical NDT page</a>, then <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo\">book an eLearning demo</a> and we'll show you the portal from both sides: the learner's dashboard and the admin's view.</p>\n<h2>eLearning by region</h2><ul><li><a href=\"/erp/apps/elearning/usa\">eLearning in United States</a></li><li><a href=\"/erp/apps/elearning/canada\">eLearning in Canada</a></li><li><a href=\"/erp/apps/elearning/europe\">eLearning in UK &amp; Europe</a></li><li><a href=\"/erp/apps/elearning/middle-east\">eLearning in Middle East</a></li><li><a href=\"/erp/apps/elearning/india\">eLearning in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo\">Send an enquiry about eLearning</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/elearning/usa","publishedAt":"2026-09-27","title":"NDT Training LMS for US Inspection Companies | Atlantis NDT","description":"NDT training LMS for US inspection companies: SNT-TC-1A written practice records, refreshers and Practical NDT 3D practice. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT eLearning and Training Records for US Inspection Companies</h1>\n<p>Courses, quizzes and certificates for technician training and refreshers. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Training under an employer-based system</h2><p>In the United States, most NDT personnel are certified by their employer. Under ASNT SNT-TC-1A, your company writes a written practice that sets out how people are trained, how much experience they need, how they're examined and who signs off their certification. ANSI/ASNT CP-189 works on the same employer-based principle but as a standard with firmer requirements, and some clients and codes call for it specifically. ASME Section V points to SNT-TC-1A or CP-189 as the basis for personnel qualification on code work, so shops building to ASME Section VIII live with these documents every day.</p><p>That system puts a lot of weight on your own records. When an auditor from a client, an Authorized Inspection Agency or an aerospace prime comes in, they don't ask a central body for your technicians' training history. They ask you. They want to see that the organised training your written practice promises actually happened, who delivered it, what it covered and how the technician did in the exams.</p><p>For many US inspection companies, that evidence is a mix of sign-in sheets, old PowerPoints and a Level III's memory. It works until the Level III leaves, or until a busy turnaround season pushes training to the back of the queue.</p><p>The eLearning app in Atlantis NDT ERP gives you a single place to run that training and keep its record, next to the technician's certifications and job history. Atlantis's own courses follow ASNT SNT-TC-1A, which is the same basis most US written practices use.</p><h2>What the eLearning app gives a US NDT company</h2><p>The portal is a learning management system inside the ERP, configured for NDT work. Built in:</p><ul><li><strong>Level I, II and III course sections</strong>, so trainees, Level II technicians and Level III candidates each see the right material.</li><li><strong>Video lessons from OneDrive or SharePoint</strong>, played inside the portal with download protection. Your videos stay in your Microsoft 365 tenant.</li><li><strong>Quizzes</strong>, with questions importable from Word files, which suits Level IIIs who already keep question banks in Word.</li><li><strong>Certificates of completion</strong> issued when a learner completes a course.</li><li><strong>Learner accounts created by admins</strong>, with course access granted and revoked by admins.</li><li><strong>A learner dashboard</strong> showing courses, progress and what's outstanding.</li><li><strong>Auto-join for invited members</strong>, so an invited technician is enrolled when they accept.</li><li><strong>Online course sales</strong> for outside learners, if you train beyond your own staff.</li><li><strong>A Practical NDT section</strong> that opens Atlantis's 3D practice platform.</li></ul><p>Anything beyond that list, for example a specific way of mapping your written practice's training requirements, is configured during implementation as part of the scope agreed with you. We'd rather tell you that plainly than promise a feature that isn't there.</p><h2>Practical NDT for Gulf Coast crews and new hires</h2><p>Hands-on practice is the hardest part of training to schedule. Instruments, probes, reference blocks and flawed specimens are in the field earning money, and your Level III is on a unit in Baytown or Baton Rouge, not in the training room.</p><p><a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive 3D, game-like practice platform. Learners run scenarios for UT, PAUT, RT, MT, PT, VT, ET and TOFD on virtual welds, pipes, pressure vessels and castings. They set up, scan, find indications and make calls, without tying up a real instrument or a trainer.</p><p>Every learner enrolled in the eLearning portal gets a Practical NDT section. Access is granted automatically on enrolment, or an admin can grant it manually, say for a field supervisor who wants to try a PAUT scenario before signing up for a course.</p><p>For US companies, a few uses stand out:</p><ul><li><strong>New hires before a turnaround.</strong> A trainee who has run dozens of virtual MT and PT scenarios arrives on site with a better eye, even though real hands-on experience still counts only when logged on real work under your written practice.</li><li><strong>Cross-training into PAUT or TOFD.</strong> Experienced UT technicians can explore phased array and TOFD setups before their formal training on real equipment.</li><li><strong>Refreshers.</strong> A technician returning to ET after a year on UT can warm up before a job.</li></ul><p>Practical NDT does not replace the practical examination your written practice requires on real specimens. It adds practice time you couldn't otherwise schedule.</p><h2>Written practice evidence your auditors can follow</h2><p>SNT-TC-1A leaves the detail to your written practice, and that's exactly why audits focus on whether you follow it. A typical question from a client auditor runs something like: show me this technician's organised training for UT Level II, who taught it, and the exam results. The eLearning portal helps you answer that without a scramble.</p><h3>What the portal records</h3><p>Who was enrolled in which course, their progress, their quiz results and their certificate of completion. Because accounts are created by admins, there's no confusion about who a learner is. Because access is granted and revoked by admins, you can show who had access to what.</p><h3>What stays with your Level III</h3><p>Your Level III still owns the written practice, approves course content, sets exam content and signs certifications. The portal supports them; it doesn't make their decisions. Practical exams on real specimens stay a Level III job.</p><h3>Linking to technician certifications</h3><p>The <a href=\"/erp/apps/certificates\">Certificates app</a> records each technician's scheme, whether SNT-TC-1A or CP-189, plus level, method, OJT hours, training hours, exam scores and vision tests. How course completions relate to those training hours is agreed during implementation. Some Level IIIs want to confirm hours by hand; others want completions recorded directly. Both approaches fit.</p><p>The point is that the evidence chain, from course to exam to certification, lives in one system instead of three filing cabinets.</p><h2>Radiography crews, NRC rules and Agreement States</h2><p>Industrial radiography in the US carries its own training burden. Under NRC rules in 10 CFR Part 34, and the equivalent rules in Agreement States such as Texas and Louisiana, radiographers and radiographer's assistants need specific radiation safety training, instruction in the licensee's operating and emergency procedures and periodic refreshers, plus audits of their work. Your radiation safety officer is responsible for making sure that happens, and inspectors from the regulator will ask to see it.</p><p>The eLearning portal doesn't replace your licence conditions or your RSO's programme. It gives you a practical way to deliver the parts that suit online learning and to keep a clean record of completion. Common courses US radiography companies put in the portal include:</p><ul><li>Company operating and emergency procedures walkthroughs.</li><li>Radiation safety awareness for non-radiography staff who work around exposure areas.</li><li>Annual refresher content assigned by the RSO, with completion tracked per person.</li><li>Survey meter and pocket dosimeter use, as video lessons your RSO records.</li></ul><p>Alongside it, the Certificates app's employee NDT profile records radiation safety training, radiation badge number and medical fitness expiry. Practical NDT's RT scenarios let trainees practise technique choice, IQI placement and film or image interpretation in a virtual space where nobody receives a dose.</p><p>What content counts toward your regulatory training is your RSO's call, and should follow your licence. The portal simply makes that content easier to deliver and prove.</p><h2>Refinery, pipeline and plant work</h2><p>A large share of US NDT work is for refineries, petrochemical plants and pipelines, concentrated along the Gulf Coast from Corpus Christi through Houston and Beaumont to Lake Charles and Baton Rouge. Owner-operators run their inspection programmes to API 510, 570 and 653, with API-certified inspectors directing the work and NDT technicians performing it. Those owners often add their own requirements: site orientations, company-specific procedures and technician approvals before anyone touches their equipment.</p><p>That creates a steady stream of client-specific training that doesn't fit your general written practice courses. The eLearning portal is a good home for it. Typical examples:</p><ul><li><strong>Procedure familiarisation.</strong> Short courses on the client's UT thickness, PAUT or radiography procedures, with a quiz your Level III writes, assigned to every technician on that contract.</li><li><strong>Reporting requirements.</strong> What a particular owner expects in a report, and how that maps to your reporting templates.</li><li><strong>Pipeline work.</strong> Pipeline operators run operator qualification programmes under 49 CFR Parts 192 and 195, administered by PHMSA. The OQ programme belongs to the operator, but your company can prepare technicians on the knowledge side of the work they'll be doing.</li></ul><p>OSHA site safety training is usually delivered by the site or a third party, but your own safety briefings, such as confined space awareness for tank work or hot work rules, can live in the portal too.</p><p>The benefit is speed at mobilisation. When a new contract starts, invite the crew to the client's course, and the auto-join means they're enrolled as soon as they accept.</p><h2>Aerospace shops working to NAS 410</h2><p>Aerospace NDT in the US follows NAS 410, which, like SNT-TC-1A, is employer-based but far more prescriptive. It requires a written practice, formal training, documented experience and examinations, with Level 3 oversight, and primes audit it closely. Many aerospace suppliers also hold Nadcap accreditation, which adds another layer of scrutiny on personnel records.</p><p>Atlantis's training is based on SNT-TC-1A, and the eLearning app makes no claim of NAS 410 conformity on its own. What it does give an aerospace NDT shop is a structured place to run the organised training that its NAS 410 written practice defines, with completion records per person, quizzes and admin-controlled access.</p><p>Aerospace methods map well onto Practical NDT scenarios. Eddy current on components, penetrant inspection on castings and UT on bonded or machined parts can all be practised in 3D before a technician moves onto real hardware. For a small shop without spare parts to train on, that's valuable.</p><p>If your shop works under both NAS 410 and SNT-TC-1A, for example an aerospace supplier that also does industrial work, the portal's level-based sections can hold separate course tracks for each written practice. That structure is set up during implementation.</p><h2>How eLearning fits the rest of Atlantis NDT ERP</h2><p>US inspection companies usually buy the eLearning app to solve a training problem, then find the real benefit is having training in the same system as everything else.</p><ul><li><strong>Certificates.</strong> Technician certifications, vision tests and exam sheets. Certificates approaching expiry are flagged 90 days ahead with warning tasks, which is your cue to assign a refresher.</li><li><strong>Team Assignments.</strong> The availability calendar includes a training status, so a technician booked on a course day isn't dispatched to a unit in Pasadena that morning.</li><li><strong>Timesheets.</strong> They warn when a technician's certificate isn't valid, which catches problems that training alone can't.</li><li><strong>Surveys.</strong> Useful for competency questionnaires after a course or feedback from learners.</li><li><strong>Employees.</strong> One record per technician, with NDT profile, highest level and methods.</li></ul><p>You can adopt eLearning alone or as part of the full <a href=\"/erp\">Atlantis NDT ERP</a>. Many companies start with training and certificates together, because that's where audit pain is sharpest.</p><h2>Implementation for US companies</h2><p>Atlantis is based in Houston, and implementation is run with your team rather than handed over as a login and a manual. A typical project:</p><ol><li>Review your written practice, SNT-TC-1A or CP-189 based, and current training materials.</li><li>Agree course structure by level and method, plus client-specific and radiation safety courses.</li><li>Connect your OneDrive or SharePoint videos and import Word question banks.</li><li>Set up admin roles, learner accounts and Practical NDT access rules.</li><li>Configure the links to Certificates, Employees and availability.</li><li>Pilot with one crew, adjust and hand over.</li></ol><p>Cost is quote on request; the product is positioned as affordable, accessible and fully customizable. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20quote%20USA\">Request a quote for your US team</a>.</p><h2>Frequently asked questions</h2><h3>Does the portal satisfy SNT-TC-1A training requirements?</h3><p>It supports them. SNT-TC-1A leaves training content and hours to your written practice; the portal delivers and records the organised training you define. Your Level III still approves content and certifies personnel.</p><h3>Can we run CP-189 and SNT-TC-1A tracks side by side?</h3><p>Yes, as separate courses or course groups within the level sections. The Certificates app records both schemes against each technician.</p><h3>Will it cover our NRC or Agreement State radiation training?</h3><p>It can deliver and record radiation safety content your RSO chooses. Whether that content meets your licence conditions is decided by your RSO and regulator, not the software.</p><h3>Can crews do courses from site?</h3><p>Yes. Lessons stream from OneDrive or SharePoint, so a technician with a working connection can study from a hotel or site office.</p><h3>Does Practical NDT count as hands-on experience?</h3><p>No. Experience hours under SNT-TC-1A come from real work. Practical NDT adds practice before and between real jobs.</p><h3>Can we sell courses to outside candidates?</h3><p>Yes, the portal supports online course sales. Be clear that completion is not certification.</p><h2>See it before your next turnaround</h2><p>If your next audit or shutdown is on the calendar, now is the time to get training records in order. See the 3D scenarios on the <a href=\"/practical-ndt\">Practical NDT page</a>, then <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20USA\">book an eLearning demo</a> and we'll show you the learner and admin views with course examples built around US written practices.</p>\n<h2>eLearning by region</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning global overview</a></li><li><a href=\"/erp/apps/elearning/canada\">eLearning in Canada</a></li><li><a href=\"/erp/apps/elearning/europe\">eLearning in UK &amp; Europe</a></li><li><a href=\"/erp/apps/elearning/middle-east\">eLearning in Middle East</a></li><li><a href=\"/erp/apps/elearning/india\">eLearning in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(United%20States)\">Send an enquiry about eLearning</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/elearning/canada","publishedAt":"2026-09-27","title":"NDT eLearning LMS for Canadian NDT Companies | Atlantis NDT","description":"eLearning for Canadian NDT companies: internal training, radiation safety refreshers and Practical NDT 3D practice. Request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT eLearning for Canadian Inspection Companies</h1>\n<p>Courses, quizzes and certificates for technician training and refreshers. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Where company training fits in Canada's certification system</h2><p>Canada certifies most NDT technicians centrally. The CGSB scheme, run by the NDT Certification Body at Natural Resources Canada under CAN/CGSB-48.9712, which is based on ISO 9712, means technicians sit exams set by a third party rather than by their employer. That's different from the US employer-based model, and it changes what your company's training is for.</p><p>A Canadian NDT company still carries a lot of training responsibility. New hires need grounding before they sit anything. Certified technicians need to learn your procedures, your clients' specifications and your reporting standards. Radiography crews need company radiation safety instruction. Client sites in the oil sands or at nuclear stations add their own orientation requirements. And plenty of Canadian companies also hold ASNT SNT-TC-1A written practices for US client work, cross-border projects or sectors where employer-based certification is expected.</p><p>The eLearning app in Atlantis NDT ERP is built for that internal training. It is not a route to CGSB certification, and Atlantis doesn't present it as one. Atlantis's own training courses follow ASNT SNT-TC-1A only. What the portal does is give your company one place to deliver and record the training that sits around certification: onboarding, procedures, client requirements, safety and refreshers.</p><p>Because the portal lives inside the ERP, those records sit next to each technician's certificates, availability and job history, which is where your QA manager and your clients' auditors expect to find them.</p><h2>What the eLearning app includes</h2><p>As configured by Atlantis for NDT companies, the portal includes:</p><ul><li><strong>Level I, II and III sections</strong>, so material is grouped by the level a learner works at.</li><li><strong>Video lessons streamed from OneDrive or SharePoint</strong> with download protection, so your videos stay in your Microsoft 365 storage.</li><li><strong>Quizzes</strong>, with questions importable from Word files.</li><li><strong>Certificates of completion</strong> for finished courses.</li><li><strong>Learner accounts created by admins</strong>, with access granted and revoked by admins.</li><li><strong>A learner dashboard</strong> for each person's courses and progress.</li><li><strong>Auto-join for invited members.</strong></li><li><strong>Online course sales</strong>, if you train outside candidates.</li><li><strong>A Practical NDT section</strong> opening Atlantis's 3D practice platform.</li></ul><p>Where you need something beyond this list, such as a particular reporting view for a client audit, it is handled as configuration during implementation and agreed with you up front. No surprises about what's built in and what isn't.</p><h2>Practical NDT for camps, rotations and long winters</h2><p>A lot of Canadian NDT work happens far from a training room. Crews fly in and out of oil sands sites north of Fort McMurray, work long rotations at upgraders and plants, or travel between pipeline spreads in remote country. Hands-on practice on real equipment is hard to schedule when the equipment and the Level III are both hundreds of kilometres away.</p><p><a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive 3D, game-like NDT practice platform. Learners work through UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, pressure vessels and castings. They set up, scan, find indications and decide what they mean, on a laptop in a camp room if that's where they are.</p><p>Every learner enrolled in the eLearning portal gets a Practical NDT section. Access is switched on automatically at enrolment, or an admin can grant it manually.</p><p>Canadian companies tend to use it in three ways:</p><ul><li><strong>Between rotations.</strong> Technicians keep a method fresh during time off-site without needing access to your shop.</li><li><strong>Before exams.</strong> Trainees build familiarity with scanning and interpretation before practical sessions on real specimens. Practice on a platform doesn't count as the documented experience a certification scheme requires; it simply prepares people to make better use of real time.</li><li><strong>Cross-training.</strong> UT technicians exploring PAUT and TOFD, or MT technicians moving into ET, get a feel for setups before formal training.</li></ul><p><a href=\"/contact?service=practical-ndt&amp;subject=Practical%20NDT%20and%20eLearning%20demo%20Canada\">Book a demo of Practical NDT inside eLearning</a> to see a learner's view.</p><h2>Radiography crews: CNSC and moving sources</h2><p>Industrial radiography in Canada is licensed by the Canadian Nuclear Safety Commission. People who operate exposure devices must be CNSC-certified exposure device operators, and trainees work under direct supervision while they gain experience. Your company's licence comes with a radiation protection programme, and your radiation safety officer is responsible for training people in the licensee's procedures and keeping records the CNSC can inspect.</p><p>Moving sources adds another layer. Transport of Dangerous Goods rules require that people handling or transporting Class 7 radioactive material are trained and hold a training certificate from their employer, with periodic retraining.</p><p>The eLearning portal doesn't replace EDO certification, your licence or TDG compliance. It gives your RSO a practical way to deliver company-specific content and prove who completed it. Typical courses:</p><ul><li>Your operating and emergency procedures, recorded as short video lessons with a quiz.</li><li>Radiation safety awareness for assistants, helpers and non-radiography staff who work near controlled areas.</li><li>Refresher content your RSO assigns on a schedule, with completion per person.</li><li>Source transport briefings for vehicle crews, alongside the Fleet app's record of which vehicles can carry radioactive sources and their transport licence expiry.</li></ul><p>The Certificates app's employee NDT profile holds radiation safety training, radiation badge number and medical fitness expiry. Practical NDT's RT scenarios let trainees practise technique selection and image interpretation without anyone receiving a dose.</p><h2>Alberta oil sands, upgraders and ABSA-regulated work</h2><p>Alberta is the centre of Canadian NDT demand: oil sands mining and in-situ operations, upgraders, refineries and petrochemical plants around Edmonton's Industrial Heartland, and the pipelines that connect them. Pressure equipment in the province falls under ABSA, the pressure equipment safety authority, and owners run inspection programmes under their ABSA-accepted quality management systems. Fabrication follows CSA B51 alongside ASME codes, structural work often references CSA W59, and pipelines are built and maintained to CSA Z662.</p><p>For an NDT company, each of those clients and codes brings specific expectations: which procedures apply, what acceptance criteria look like, how reports are laid out and what site orientations technicians must complete. That's the training that fills a Canadian Level III's week, and it's a strong fit for the portal.</p><ul><li><strong>Client procedure courses.</strong> A short course per major client or contract, covering their procedures and your approved techniques, with a quiz written by your Level III.</li><li><strong>Code awareness courses.</strong> Introductions to the relevant sections of CSA Z662 or CSA W59 for technicians moving between pipeline and structural work. Your Level III decides the content; the portal delivers it.</li><li><strong>Turnaround onboarding.</strong> Spring and fall shutdowns bring extra hands. Invite the whole crew to the onboarding course, and auto-join enrols them as they accept.</li></ul><p>When the turnaround ends, admins revoke access for temporary staff, so your course library doesn't travel with them.</p><h2>Ontario nuclear and specialised inspection</h2><p>Ontario's nuclear sector is a different world. Refurbishment programmes at Darlington and Bruce, and routine outages across the fleet, involve demanding inspection work, much of it eddy current and ultrasonic testing of components under CSA N285.4 periodic inspection requirements. Nuclear operators impose extensive site training, security screening and procedure qualification on every contractor, and they expect records to be exact.</p><p>Most of that site-specific training is delivered by the operator. But the NDT company still has to prepare its people: company procedures for nuclear work, quality expectations, human performance tools, reporting discipline and the method knowledge behind specialised techniques.</p><p>The portal gives you a structured place for that preparation, with a clear record of who completed what before mobilisation. Practical NDT's ET and UT scenarios offer early familiarity with the methods, though qualification for nuclear inspection is always done on the operator's terms, on real equipment and mock-ups.</p><p>Nuclear work also rewards clean access control. Admins create every learner account and grant or revoke access, which keeps sensitive procedure material limited to the people who should see it.</p><h2>English, French and personal data</h2><p>Canadian NDT companies often run crews in both official languages, especially those working in Quebec or with crews from Quebec working in Alberta. The portal doesn't translate content automatically, but it handles bilingual training simply: build a French version of a course alongside the English one and invite each technician to the right version. Quiz questions imported from Word work the same way in either language.</p><p>Technician training records are personal information. Federal privacy law under PIPEDA, and provincial laws in Alberta, British Columbia and Quebec, shape how you collect and keep that information. The eLearning app gives you practical controls: admin-created accounts, admin-controlled access, and revocation when a person leaves. Decisions about hosting, retention and who in your company can see what are made with you during implementation. Atlantis does not claim the software makes you compliant with any privacy law; your policies do that, and the configuration supports them.</p><h2>Connecting training to certificates and dispatch</h2><p>The eLearning app earns its place when it's joined to the rest of Atlantis NDT ERP.</p><ul><li><strong><a href=\"/erp/apps/certificates\">Certificates</a></strong> records each technician's certifications, including CGSB (ISO 9712), SNT-TC-1A and others, with level, method, certifying body, issue and expiry dates, OJT and training hours, and vision tests. Certificates expiring within 90 days are flagged with warning tasks, which is your prompt to assign refresher training.</li><li><strong>Team Assignments</strong> uses an availability calendar with a training status, so nobody dispatches a technician to a site in Fort McMurray on the day they're booked for a course.</li><li><strong>Timesheets</strong> warn when a technician's certificate isn't valid.</li><li><strong>Surveys</strong> handle competency questionnaires and course feedback.</li></ul><p>How course completions relate to training hours on a technician's record is agreed during implementation.</p><h2>Who uses the portal in a Canadian NDT company</h2><h3>Level III and QA managers</h3><p>They write or approve course content, set quiz pass marks, decide which courses each crew needs for each client, and use completion records when an owner's quality management system audit or a nuclear operator's contractor review comes around.</p><h3>Radiation safety officers</h3><p>They assign radiation safety and source transport content, check that every operator, assistant and driver has completed it, and keep that evidence ready for a CNSC inspection.</p><h3>Technicians and trainees</h3><p>They see their courses on the dashboard, study between rotations, take quizzes and open Practical NDT when they want practice. A trainee waiting to sit a CGSB exam can keep building familiarity with a method in the meantime, even though the portal itself isn't exam preparation.</p><h3>Operations and dispatch</h3><p>They see training alongside certification status and availability, so a technician isn't sent to an oil sands site or a nuclear outage without the client's required course completed.</p><h3>HR and admin</h3><p>They create learner accounts for new hires and turnaround staff, and revoke access when people leave or a contract ends. That keeps client procedures and company material inside the company.</p><h2>Implementation</h2><p>Atlantis sets up eLearning as part of <a href=\"/erp\">Atlantis NDT ERP</a> or on its own. We start with your training material, certification mix and client requirements, then agree course structure, connect your OneDrive or SharePoint videos, import Word question banks, set admin roles and Practical NDT access, and pilot with one crew before handing over. Cost is quote on request; the product is affordable, accessible and fully customizable. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20quote%20Canada\">Request a quote for your Canadian team</a>.</p><h2>Frequently asked questions</h2><h3>Does the portal prepare technicians for CGSB exams?</h3><p>No. It is for your company's internal training: onboarding, procedures, client requirements, safety and refreshers. Atlantis's own courses follow ASNT SNT-TC-1A.</p><h3>Can the ERP record CGSB certifications?</h3><p>Yes. The Certificates app records ISO 9712-based certifications, including CGSB, alongside SNT-TC-1A and others, with expiry tracking.</p><h3>Can it deliver our CNSC or TDG training?</h3><p>It can deliver and record company content your RSO chooses. Whether that meets your licence and TDG obligations is your RSO's decision.</p><h3>Does it work in French?</h3><p>You can build French versions of courses and assign learners to the right language.</p><h3>Can crews study from camp?</h3><p>Yes, with a working internet connection, since lessons stream from OneDrive or SharePoint.</p><h3>What does it cost?</h3><p>Quote on request, based on scope and customization.</p><h2>Talk to us</h2><p>If your training records are spread across camps, laptops and inboxes, see how one portal changes that. Try the scenarios on the <a href=\"/practical-ndt\">Practical NDT page</a>, then <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20Canada\">book an eLearning demo</a> with course examples built around Canadian work.</p>\n<h2>eLearning by region</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning global overview</a></li><li><a href=\"/erp/apps/elearning/usa\">eLearning in United States</a></li><li><a href=\"/erp/apps/elearning/europe\">eLearning in UK &amp; Europe</a></li><li><a href=\"/erp/apps/elearning/middle-east\">eLearning in Middle East</a></li><li><a href=\"/erp/apps/elearning/india\">eLearning in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(Canada)\">Send an enquiry about eLearning</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/elearning/europe","publishedAt":"2026-09-27","title":"NDT eLearning LMS for UK & European NDT Firms | Atlantis NDT","description":"NDT eLearning for UK and European inspection firms: procedure training, offshore refreshers and Practical NDT 3D practice. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT eLearning for UK and European Inspection Companies</h1>\n<p>Courses, quizzes and certificates for technician training and refreshers. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Company training in a central-certification world</h2><p>Across the UK and Europe, most NDT technicians are certified under EN ISO 9712 through a third-party scheme. In the UK that usually means PCN, administered by BINDT. Elsewhere, national bodies such as DGZfP in Germany and COFREND in France run schemes of their own. Aerospace is the exception: EN 4179 keeps certification with the employer, under a written practice and a responsible Level 3.</p><p>Central certification settles who is qualified in a method. It doesn't settle whether a technician knows your procedures, your clients' specifications, your reporting templates or the safety rules at the next site. Those gaps are the employer's to close, and your ISO 9001 quality system, client audits and third-party inspectors will all want to see how you close them.</p><p>That is what the eLearning app in Atlantis NDT ERP is for: the company training around certification. Onboarding, procedure familiarisation, client-specific courses, radiation safety content, refreshers after a long gap in a method. The portal is not an exam route for PCN or any other certification scheme. Atlantis's own training follows ASNT SNT-TC-1A, which matters to European companies that work for US clients, on export fabrication or on projects specifying ASNT-certified personnel.</p><p>Running training inside the ERP means the record of who learned what sits beside the technician's certificates, vision tests, availability and jobs. When an auditor asks, you open one system.</p><h2>What the eLearning app includes</h2><p>Configured by Atlantis for NDT companies, the portal gives you:</p><ul><li><strong>Level I, II and III sections</strong>, so learners see material suited to their level.</li><li><strong>Video lessons played from OneDrive or SharePoint</strong> with download protection. Your videos stay in your Microsoft 365 storage, which helps if you've already decided where company data lives.</li><li><strong>Quizzes</strong>, with question banks importable from Word files.</li><li><strong>Certificates of completion</strong> for finished courses.</li><li><strong>Learner accounts created by admins</strong>, with access granted and revoked by admins.</li><li><strong>A learner dashboard</strong> showing courses and progress.</li><li><strong>Auto-join for invited members.</strong></li><li><strong>Online course sales</strong>, if you train outside candidates.</li><li><strong>A Practical NDT section</strong> opening Atlantis's 3D practice platform.</li></ul><p>Anything not on this list is configured during implementation as part of an agreed scope, not presented as a built-in feature.</p><h2>Practical NDT: practice time you can't otherwise schedule</h2><p>Whatever scheme your technicians hold, practice time is scarce. Flaw specimens, reference blocks, PAUT sets and TOFD kit are out on jobs, and the senior technician who could coach a trainee is offshore or on a refinery outage.</p><p><a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive 3D, game-like practice platform. Learners work through UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, pressure vessels and castings: setting up, scanning, finding indications and making calls, with no equipment tied up and no cost to a mistake.</p><p>Every learner enrolled in the eLearning portal gets a Practical NDT section. Access is granted automatically on enrolment, or an admin grants it manually.</p><p>European companies tend to use it for:</p><ul><li><strong>Trainees and apprentices</strong> building familiarity with methods before supervised work on real parts.</li><li><strong>Cross-skilling</strong> conventional UT technicians toward PAUT and TOFD, which are increasingly specified on weld inspection in place of radiography.</li><li><strong>Keeping skills warm</strong> for technicians who spend months on one method and then need another.</li></ul><p>Practical NDT is practice, not documented industrial experience, and it doesn't replace any practical examination. It helps people arrive at real specimens better prepared.</p><p><a href=\"/contact?service=practical-ndt&amp;subject=Practical%20NDT%20and%20eLearning%20demo%20Europe\">Book a demo of Practical NDT inside eLearning</a>.</p><h2>PED work and the EN ISO standards your technicians use</h2><p>If you inspect pressure equipment for European manufacturers, the Pressure Equipment Directive 2014/68/EU shapes your week. Annex I, section 3.1.3 requires that NDT personnel on pressure equipment in categories III and IV are approved by a third-party organisation recognised by a Member State, which in practice usually means EN ISO 9712 certification. In Great Britain, the Pressure Equipment (Safety) Regulations 2016 carry the same structure over.</p><p>Certification covers the method. The procedures your technicians follow on a job come from the standards the manufacturer and notified body specify: EN ISO 17640 for UT of welds, EN ISO 11666 for UT acceptance levels, EN ISO 17636 for radiography of welds, EN ISO 17638 for MT, EN ISO 3452-1 for PT and EN ISO 17637 for visual testing. Each client may add a layer, and your written procedures translate all of it into what a technician actually does.</p><p>The portal is a practical place for that translation. Examples:</p><ul><li>A short course on each of your written procedures, with a quiz, assigned whenever a procedure revision is issued.</li><li>An acceptance-level refresher for technicians moving between clients who specify different quality levels.</li><li>A course on your reporting templates, so reports reach the notified body in the format expected.</li></ul><p>Your Level 3 decides content and pass marks; the portal delivers it and keeps the record.</p><h2>North Sea offshore and Aberdeen-based crews</h2><p>Offshore work in the UK and Norwegian sectors brings its own training rhythm. Technicians rotate between platform trips and onshore time. Many are also rope access technicians under IRATA, combining NDT with access work on structures that are hard to reach. Offshore survival and induction, typically OPITO BOSIET and related courses, is delivered by accredited centres. Operator and duty holder inductions come on top.</p><p>The NDT company's own share of training is what the eLearning portal handles well:</p><ul><li><strong>Pre-trip briefings</strong> on the procedures and techniques for a specific campaign, such as corrosion mapping, weld inspection on topsides or subsea-related onshore work.</li><li><strong>Onshore refreshers</strong> completed between trips, so technicians don't lose method skills during long stints on one task.</li><li><strong>Reporting discipline</strong> for the duty holder's expectations.</li></ul><p>A practical note: lessons stream from OneDrive or SharePoint, so they need a reasonable connection. Most crews complete courses onshore or in accommodation with decent bandwidth rather than on the platform itself.</p><p>Offshore contracts also involve high staff turnover and contractor churn. Admin-controlled accounts and access revocation mean your course material doesn't leave with people who move to a competitor at the end of a campaign.</p><h2>UK HSE, IRR17 and radiography safety</h2><p>Industrial radiography in Great Britain falls under the Ionising Radiations Regulations 2017, enforced by the HSE. Employers must register or obtain consent for radiography work, appoint a radiation protection adviser, designate radiation protection supervisors, and make sure classified persons and others receive suitable information, instruction and training. Other European countries apply the Basic Safety Standards Directive through their own national rules.</p><p>The eLearning portal doesn't replace your RPA's advice or your local rules. It gives your RPS and management a straightforward way to deliver company content and prove completion:</p><ul><li>Local rules and contingency plans as short lessons with a quiz.</li><li>Awareness training for staff who work near radiography but don't perform it.</li><li>Periodic refresher content assigned to classified workers.</li></ul><p>The Certificates app's employee NDT profile holds radiation safety training, badge number and medical fitness expiry. Practical NDT's RT scenarios let trainees practise technique and interpretation without any dose. And because PAUT and TOFD increasingly replace radiography on welds, the same platform supports the switch.</p><p>What content satisfies your regulatory obligations remains your RPA's and RPS's judgment.</p><h2>GDPR and technician personal data</h2><p>Training records are personal data under the GDPR and, in the UK, the UK GDPR and Data Protection Act 2018. Quiz scores, completion history and learner account details identify individuals, and technicians have rights over that information.</p><p>The eLearning app gives you practical controls to support your data protection policies:</p><ul><li>Accounts are created by admins, so you know who holds one and why.</li><li>Access is granted and revoked by admins, so leavers lose access promptly.</li><li>Videos stay in your own OneDrive or SharePoint, where your existing data decisions already apply.</li></ul><p>Hosting location, retention periods and which roles can see training records are agreed with you during implementation. Atlantis does not claim the software makes you GDPR compliant. Your policies and your data protection lead do that; the configuration is set up to support them.</p><h2>Multilingual crews</h2><p>European NDT crews are often international. A single contract might include technicians from Poland, Portugal, Romania, Italy and the UK. The portal doesn't translate content automatically, but it handles this simply: build language versions of key courses, import quiz questions from Word files in each language and invite each technician to the version they understand best. For safety-critical content such as radiography local rules, that's worth the effort.</p><h2>Connecting training to the rest of the ERP</h2><ul><li><strong><a href=\"/erp/apps/certificates\">Certificates</a></strong> records EN ISO 9712, PCN, CSWIP, SNT-TC-1A and other certifications held by your technicians, with level, method, certifying body and expiry, plus vision tests including Jaeger near-vision results. Certificates expiring within 90 days are flagged, which prompts refresher assignments.</li><li><strong>Team Assignments</strong> treats training as an availability status, so nobody is dispatched on a course day.</li><li><strong>Procedures</strong> holds your controlled procedure revisions; when one is approved, a matching course update can be assigned.</li><li><strong>Surveys</strong> covers competency questionnaires and feedback.</li></ul><p>How completions relate to training hours on the technician record is agreed during implementation.</p><h2>Who uses the portal in a European NDT company</h2><h3>Level 3 and technical managers</h3><p>They own procedure courses and quizzes, decide what each client contract requires, and use completion records during ISO 9001 audits, client audits and notified body reviews. In aerospace shops working under EN 4179, the responsible Level 3 uses the portal to run the organised training the written practice defines.</p><h3>RPAs, RPSs and safety leads</h3><p>They assign local rules and radiation awareness content and check who has completed it before radiography work starts on a site.</p><h3>Technicians, trainees and apprentices</h3><p>They follow their courses on the dashboard, complete refreshers between offshore trips or outages, and open Practical NDT whenever they want practice time.</p><h3>Operations and resourcing</h3><p>They check training alongside certification and availability before putting a technician on a campaign, so nobody arrives at a fabrication yard or platform without the client course done.</p><h3>HR and data protection leads</h3><p>They manage learner accounts, remove access for leavers and contractors at the end of a campaign, and work with Atlantis during implementation on who can see training records.</p><h2>Implementation</h2><p>Atlantis sets up eLearning as part of <a href=\"/erp\">Atlantis NDT ERP</a> or on its own: review your training material and quality system requirements, agree course structure and languages, connect OneDrive or SharePoint, import question banks, configure admin roles and Practical NDT access, pilot and hand over. Cost is quote on request; affordable, accessible, fully customizable. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20quote%20Europe\">Request a quote for your UK or European team</a>.</p><h2>Keeping training in step with procedure revisions</h2><p>European clients and notified bodies care a great deal about document control. A technician working to revision C of your UT procedure when revision D was issued last month is exactly the finding nobody wants in an audit report. The fix isn't more paperwork. The fix is making sure every procedure change reaches the people who use it, and being able to prove it did.</p><p>Atlantis NDT ERP's Procedures app already holds your procedure register: document number, revision, method, scope, material, applicable standard and acceptance criteria. Procedures move from draft through review and approval to published, approved revisions are locked, and the full revision history keeps a snapshot of each one. That gives you a reliable answer to which revision is current.</p><p>The eLearning portal closes the loop on the people side. A practical routine many companies adopt:</p><ol><li>When a procedure revision is published, your Level 3 updates the matching short course: a video or document walkthrough of what changed and why, and a few quiz questions on the changes.</li><li>Every technician who works to that procedure is invited to the updated course. Auto-join enrols them as they accept.</li><li>The admin view shows who has completed it. Operations can hold back anyone who hasn't before they go to a job using that procedure.</li><li>The completion certificate becomes your evidence that the revision was briefed.</li></ol><p>How tightly this routine is tied into the ERP, for example who gets notified and which roles can see completion status, is configured during implementation as part of the scope agreed with you. The routine itself works from day one because both apps sit in the same system.</p><h2>Beyond oil and gas: wind, rail, power and shipbuilding</h2><p>European NDT isn't only refineries and offshore platforms. Offshore wind has created steady demand for weld inspection on monopiles, transition pieces and towers, with long runs of automated and manual UT. Rail maintenance relies on ultrasonic and eddy current inspection of axles, wheelsets and track components. Power generation, from gas turbines to conventional boilers, and shipbuilding and repair yards along the North Sea and Mediterranean coasts all bring their own methods, standards and client expectations. Petrochemical clusters around Rotterdam, Antwerp and Teesside keep radiography and PAUT crews busy through turnaround seasons.</p><p>Each sector has its own vocabulary and its own quality expectations, and technicians moving between them need to adjust quickly. A UT technician who has spent two years on monopile welds needs a refresher before a rail axle job, and vice versa.</p><p>The portal lets you organise training by sector as well as by level and method. Common course groups include sector introductions, client-specific procedure courses and short reporting courses for each sector's documentation style. Practical NDT's scenarios on welds, pipes, vessels and castings give technicians hands-on practice with the methods, even when the real components are on the other side of the country.</p><p>Your Level 3 decides the content for each sector. The portal keeps the courses in order and the records in one place, so when a rail or wind client audits your training, you open one system instead of three folders.</p><h2>Frequently asked questions</h2><h3>Is this a route to PCN or EN ISO 9712 certification?</h3><p>No. The portal is for company training around certification: procedures, clients, safety and refreshers. Atlantis's own courses follow ASNT SNT-TC-1A.</p><h3>Can the ERP record PCN and other EN ISO 9712 certificates?</h3><p>Yes. The Certificates app records them with expiry tracking, alongside ASNT-based certifications.</p><h3>Does it support EN 4179 aerospace written practices?</h3><p>It can host the organised training your written practice defines, with records per person. It makes no conformity claim on its own.</p><h3>Can offshore crews use it?</h3><p>Yes, where they have a reasonable connection. Most complete courses onshore between trips.</p><h3>Where is data held?</h3><p>Hosting and retention are agreed with you during implementation. Videos remain in your own Microsoft storage.</p><h3>What does it cost?</h3><p>Quote on request, based on scope.</p><h2>See it working</h2><p>Explore the scenarios on the <a href=\"/practical-ndt\">Practical NDT page</a>, then <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20Europe\">book an eLearning demo</a> with course examples built around European procedures and offshore work.</p>\n<h2>eLearning by region</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning global overview</a></li><li><a href=\"/erp/apps/elearning/usa\">eLearning in United States</a></li><li><a href=\"/erp/apps/elearning/canada\">eLearning in Canada</a></li><li><a href=\"/erp/apps/elearning/middle-east\">eLearning in Middle East</a></li><li><a href=\"/erp/apps/elearning/india\">eLearning in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(UK%20%26%20Europe)\">Send an enquiry about eLearning</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/elearning/middle-east","publishedAt":"2026-09-27","title":"NDT eLearning LMS for Middle East NDT Companies | Atlantis NDT","description":"NDT eLearning for Middle East crews: shutdown onboarding, client procedure refreshers and Practical NDT 3D practice. Request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT eLearning for Middle East Inspection Companies</h1>\n<p>Courses, quizzes and certificates for technician training and refreshers. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Training for the Gulf's national oil company work</h2><p>NDT in the Gulf is shaped by a handful of very large asset owners: Saudi Aramco and SABIC in Saudi Arabia, ADNOC in the UAE, QatarEnergy in Qatar, KNPC and KOC in Kuwait, and PDO in Oman. Each has its own engineering standards, contractor approval processes and expectations about the people who inspect their plant. Aramco's SAES and SAIS documents, for example, set out requirements that contractors and their NDT personnel must meet, and technician approvals and client practical demonstrations are common before anyone works on site.</p><p>That means an NDT company in the region trains constantly, and not only in methods. Technicians hold a mix of ASNT SNT-TC-1A certifications from their employer and ISO 9712 certifications from various schemes, often earned in different countries before they arrived. On top of that sit client procedures, site rules, reporting formats and safety requirements that change from one contract to the next.</p><p>Auditors from the operator, from EPC contractors and from third-party inspection agencies all ask the same question sooner or later: show me this technician's training for this work. If the answer lives in a site office filing cabinet in Jubail and the technician is now in Ruwais, you have a problem.</p><p>The eLearning app in Atlantis NDT ERP puts that training and its records in one portal, inside the same system that holds certificates, availability and job history. Atlantis's own training courses follow ASNT SNT-TC-1A, which suits the many Gulf companies whose written practices are ASNT-based.</p><h2>What the eLearning app includes</h2><p>As configured by Atlantis for NDT companies:</p><ul><li><strong>Level I, II and III course sections.</strong></li><li><strong>Video lessons played from OneDrive or SharePoint</strong> with download protection.</li><li><strong>Quizzes</strong>, with questions importable from Word files.</li><li><strong>Certificates of completion.</strong></li><li><strong>Learner accounts created by admins</strong>, with access granted and revoked by admins.</li><li><strong>A learner dashboard</strong> for courses and progress.</li><li><strong>Auto-join for invited members.</strong></li><li><strong>Online course sales</strong>, if you train outside candidates.</li><li><strong>A Practical NDT section</strong> opening Atlantis's 3D practice platform.</li></ul><p>Anything beyond this, such as a particular report for a client audit, is configured during implementation within an agreed scope rather than presented as built in.</p><h2>Practical NDT before client practical tests</h2><p>In the Gulf, a technician's certificate often isn't the last word. Many operators and EPCs want to see a technician perform before approving them for their plant, and a failed demonstration means a mobilised technician sitting idle in camp while you find a replacement.</p><p><a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive 3D, game-like practice platform. Learners work through UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, pressure vessels and castings: setting up, scanning, finding indications and making calls, without tying up an instrument or a calibration block.</p><p>Every learner enrolled in the eLearning portal gets a Practical NDT section, with access granted automatically on enrolment or manually by an admin.</p><p>Gulf companies find it useful for:</p><ul><li><strong>Warm-up before client demonstrations.</strong> Technicians who haven't touched a method for months can refresh their setup and scanning routine in camp the week before.</li><li><strong>Bringing new arrivals up to speed</strong> on your preferred techniques before their first job.</li><li><strong>PAUT and TOFD familiarity</strong>, as these methods are increasingly specified for weld inspection on major projects.</li></ul><p>Practical NDT doesn't replace any client test or practical examination on real specimens. It reduces the chance that a capable technician fails one for lack of recent practice.</p><p><a href=\"/contact?service=practical-ndt&amp;subject=Practical%20NDT%20and%20eLearning%20demo%20Middle%20East\">Book a demo of Practical NDT inside eLearning</a>.</p><h2>Shutdown and turnaround season</h2><p>The Gulf's turnaround seasons, clustered in the cooler months, are when NDT companies double their headcount overnight. Extra technicians arrive from India, Pakistan, the Philippines and elsewhere, often on short contracts, and every one of them needs to be ready for the client's rules on day one.</p><p>The portal is well suited to pre-mobilisation onboarding at that scale:</p><ol><li><strong>Build a shutdown onboarding course</strong> once per client: site rules, permit-to-work basics as they apply to your crews, the client's NDT procedures, your reporting requirements and who to call when something goes wrong.</li><li><strong>Invite the whole incoming crew.</strong> Auto-join means each person is enrolled as soon as they accept.</li><li><strong>Watch progress</strong> from the admin view and chase only the people who haven't finished.</li><li><strong>Issue completion certificates</strong> so site supervisors can confirm onboarding at the gate.</li><li><strong>Revoke access at demobilisation</strong>, so temporary staff don't keep your procedures and client material.</li></ol><p>Doing this online means technicians can complete onboarding while their visa and travel are being processed, not in a crowded induction room on the first morning. The Team Assignments app already handles mobilisation and demobilisation dates and blocks double-booking, so training and dispatch sit in the same system.</p><h2>Expatriate crews, languages and nationalisation</h2><p>Gulf NDT crews are among the most international anywhere. A single site team might include technicians whose first language is Hindi, Urdu, Malayalam, Tamil, Tagalog, Arabic or English. Safety-critical content only works if people understand it.</p><p>The portal doesn't translate automatically, but it handles multilingual training in a straightforward way. Record video lessons in the languages your crews need, import quiz questions from Word files in each language, and invite each technician to the right version. Many companies keep English as the base for technical content and add language versions for safety and site-rule courses.</p><p>Nationalisation programmes add a different kind of training demand. Saudization under Nitaqat, Emiratisation and similar policies in Qatar, Kuwait and Oman push companies to recruit and develop national trainees. Structured Level I courses with Practical NDT access give national trainees a clear path and give you evidence of development effort.</p><p>Expatriate employment also means a lot of personal documentation: passports, visas, iqamas and work permits. Those belong in the employee record managed during implementation, not in the learning portal. Keeping them together in one ERP, rather than in separate spreadsheets, is part of the point.</p><h2>Radiography and regional regulators</h2><p>Industrial radiography in the Gulf is regulated nationally. In Saudi Arabia, the Nuclear and Radiological Regulatory Commission licenses radiation practices; in the UAE, the Federal Authority for Nuclear Regulation does. Other states have their own authorities. All expect licensees to train radiography workers in radiation safety and the company's procedures, and to keep records.</p><p>The portal gives your radiation protection officer a clear way to deliver company content and prove completion: operating and emergency procedures, radiation awareness for helpers and nearby workers, and periodic refreshers. The Certificates app's employee NDT profile records radiation safety training, badge numbers and medical fitness expiry, while the Fleet app records which vehicles can carry radioactive sources and their transport licence expiry. Practical NDT's RT scenarios let trainees practise technique and interpretation without dose. What satisfies your licence conditions is decided by your RPO and regulator.</p><h2>Connecting training to certificates and dispatch</h2><ul><li><strong><a href=\"/erp/apps/certificates\">Certificates</a></strong> records ASNT SNT-TC-1A, ISO 9712 and other certifications against each technician, with level, method, certifying body and expiry, plus vision tests. Certificates expiring within 90 days are flagged with warning tasks, the cue to assign a refresher.</li><li><strong>Team Assignments</strong> uses training as an availability status and blocks overlapping bookings.</li><li><strong>Timesheets</strong> warn when a technician's certificate isn't valid.</li><li><strong>Surveys</strong> handle competency questionnaires and client-required feedback forms.</li></ul><p>How course completions relate to training hours on a technician's record is agreed during implementation.</p><h2>Selling courses in the region</h2><p>Many Gulf NDT companies also train outsiders: client inspection staff, national trainees sponsored by other employers, or technicians preparing for a move into the industry. The portal supports online course sales, with orders and invoices flowing into the ERP's accounting. VAT is configured for your country during implementation; Atlantis does not claim any certified e-invoicing status. Be clear in course descriptions that completion is not certification.</p><h2>Who uses the portal in a Gulf NDT company</h2><h3>Level III and QA/QC managers</h3><p>They build client procedure and onboarding courses, set quiz pass marks and pull completion records when an operator, EPC or third-party inspection agency audits your personnel files.</p><h3>Radiation protection officers</h3><p>They assign radiation safety content to radiography crews, helpers and drivers, and keep completion evidence ready for the national regulator's inspection.</p><h3>Technicians and trainees</h3><p>They complete onboarding before they fly, study in camp after shift, take quizzes and open Practical NDT to practise before a client demonstration.</p><h3>Project and operations managers</h3><p>They check that the full shutdown crew has finished the client's onboarding course before mobilisation, alongside certificate status and availability in the same system.</p><h3>HR and admin</h3><p>They create accounts for incoming crews, track national trainees' development, and revoke access when short-contract staff demobilise. For a company that may add and release many people in a single season, that control matters.</p><h2>Implementation</h2><p>Atlantis sets up eLearning as part of <a href=\"/erp\">Atlantis NDT ERP</a> or on its own. We review your written practice, client requirements and existing material, agree course structure and languages, connect OneDrive or SharePoint, import Word question banks, set admin roles and Practical NDT access, and pilot with one crew before the next shutdown. Cost is quote on request; the product is affordable, accessible and fully customizable. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20quote%20Middle%20East\">Request a quote for your Gulf team</a>.</p><h2>Major projects, EPC contractors and third-party inspection</h2><p>Alongside maintenance and turnarounds, the Gulf runs some of the largest construction programmes in the energy world: gas processing expansions, refinery upgrades, petrochemical complexes, pipelines, desalination and power plants. That work flows through EPC contractors from Korea, Japan, Italy, Spain, India, China and the region itself, and NDT companies usually work as their subcontractors.</p><p>Each layer brings its own expectations. The owner's standards set the baseline. The EPC contractor adds its project quality plan, inspection and test plans with hold and witness points, and its own reporting templates. A third-party inspection agency may witness work and review personnel files on the owner's behalf. A technician on a major project has to understand all three, and the NDT company has to show it prepared them.</p><p>That is a natural job for the eLearning portal. Practical examples:</p><ul><li><strong>Project induction courses</strong> for each major project: the owner's NDT requirements as they apply to your scope, the EPC's quality plan, and how hold and witness points affect when your crew can start or report.</li><li><strong>Reporting courses</strong> on the EPC's report format, so fewer reports bounce back and fewer days are lost to corrections.</li><li><strong>Method refreshers</strong> before high-volume phases, such as weld radiography or PAUT on pipe spools, with Practical NDT scenarios on virtual welds and pipes for practice.</li></ul><p>Because courses are grouped and access is controlled by admins, technicians only see the projects they are assigned to. When a project ends or a technician moves to a different contract, admins adjust access accordingly.</p><p>Completion records sit in the same ERP as technician certifications, so when a third-party inspector asks for personnel files, your QA team can show certificates and project training together rather than collecting them from different site offices.</p><h2>Heat, camps and learning after shift</h2><p>Gulf working life shapes when training can happen. Summer midday work restrictions in Saudi Arabia, the UAE, Qatar and neighbouring states push outdoor work into early mornings and evenings. Ramadan changes working hours for a month each year. Crews live in camps and accommodation blocks, often far from any training centre, and rotate home on long leave cycles.</p><p>Classroom training fights all of that. Getting a crew into one room at one time, with a trainer free, is hard even in a quiet month and close to impossible in shutdown season.</p><p>Self-paced online training fits the rhythm better. A technician can watch a lesson during the midday break in summer, complete a quiz in the evening in camp, or finish a refresher while on leave at home before flying back. The learner dashboard shows what's outstanding, so nobody needs a supervisor to remind them which course comes next.</p><p>A few practical points Gulf companies plan for:</p><ul><li><strong>Connectivity.</strong> Lessons stream from OneDrive or SharePoint, so camp Wi-Fi quality matters. Shorter videos work better than long lectures on shared connections.</li><li><strong>Devices.</strong> Most technicians use phones for lessons and quizzes. Practical NDT scenarios are best on a laptop, so some companies set up a shared laptop in camp for practice sessions.</li><li><strong>Deadlines.</strong> Set realistic completion expectations around shift patterns and Ramadan hours, and let the admin view show who needs a nudge.</li></ul><p>The result is training that keeps moving through the year instead of stopping whenever the site gets busy or the weather turns.</p><h2>Frequently asked questions</h2><h3>Does the portal get technicians approved by Aramco or ADNOC?</h3><p>No. Client approvals follow the client's own process. The portal helps you prepare technicians and keep a record of that preparation.</p><h3>Can we record both ASNT and ISO 9712 certificates?</h3><p>Yes. The Certificates app records both, with expiry tracking and alerts.</p><h3>Can we onboard a large turnaround crew quickly?</h3><p>Yes. Invite the crew to an onboarding course; auto-join enrols them on acceptance, and admins revoke access at demobilisation.</p><h3>Does it support Arabic, Hindi or other languages?</h3><p>You can build language versions of courses and assign technicians accordingly. Content isn't translated automatically.</p><h3>Is VAT handled?</h3><p>VAT for course sales is configured locally during implementation, with no certification claims.</p><h3>What does it cost?</h3><p>Quote on request, based on scope.</p><h2>Get ready before the next shutdown</h2><p>Try the scenarios on the <a href=\"/practical-ndt\">Practical NDT page</a>, then <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20Middle%20East\">book an eLearning demo</a> with an example shutdown onboarding course built around Gulf client work.</p>\n<h2>eLearning by region</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning global overview</a></li><li><a href=\"/erp/apps/elearning/usa\">eLearning in United States</a></li><li><a href=\"/erp/apps/elearning/canada\">eLearning in Canada</a></li><li><a href=\"/erp/apps/elearning/europe\">eLearning in UK &amp; Europe</a></li><li><a href=\"/erp/apps/elearning/india\">eLearning in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(Middle%20East)\">Send an enquiry about eLearning</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/elearning/india","publishedAt":"2026-09-27","title":"NDT eLearning LMS for Indian NDT Companies | Atlantis NDT","description":"NDT eLearning for Indian inspection companies and institutes: Level I-III courses, radiography safety refreshers, Practical NDT 3D practice. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT eLearning for Inspection Companies in India</h1>\n<p>Courses, quizzes and certificates for technician training and refreshers. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in eLearning:</strong> <a href=\"/practical-ndt\">Practical NDT (3D simulator)</a></p>\n<h2>Two certification routes, one training problem</h2><p>Indian NDT technicians commonly hold certifications from two directions. Many are certified under ISO 9712-based schemes, including ISNT's national certification. Many others, especially those working for export fabricators, EPC contractors on international projects or companies that send crews to the Gulf, are certified by their employer under an ASNT SNT-TC-1A written practice. Plenty of technicians hold both over a career.</p><p>Whichever route a technician followed, the employer still has training to deliver: grounding for freshers from diploma and engineering courses, company procedures, client specifications, radiography safety, reporting standards and refreshers. PSU clients, EPCs and third-party inspection agencies audit that training, and tender documents increasingly ask for evidence of personnel qualification and training.</p><p>For many Indian NDT companies, the evidence is a register in the office, a set of attendance sheets and a trainer's slides on a pen drive. That works until the trainer changes jobs or a site team needs proof in a hurry.</p><p>The eLearning app in Atlantis NDT ERP gives you one portal for that training, inside the same system that holds certificates, availability and job history. Atlantis's own training follows ASNT SNT-TC-1A, and Atlantis has a team in Hyderabad, so Indian companies working to ASNT-based written practices get content and support from people who know how Indian NDT teams work.</p><h2>What the eLearning app includes</h2><p>As configured by Atlantis for NDT companies:</p><ul><li><strong>Level I, II and III course sections.</strong></li><li><strong>Video lessons played from OneDrive or SharePoint</strong> with download protection, so your videos aren't simply downloaded and forwarded on messaging apps.</li><li><strong>Quizzes</strong>, with question banks importable from Word files. Most Indian trainers already keep questions in Word, so this saves real time.</li><li><strong>Certificates of completion.</strong></li><li><strong>Learner accounts created by admins</strong>, with access granted and revoked by admins.</li><li><strong>A learner dashboard</strong> for courses and progress.</li><li><strong>Auto-join for invited members.</strong></li><li><strong>Online course sales</strong> to outside learners.</li><li><strong>A Practical NDT section</strong> opening Atlantis's 3D practice platform.</li></ul><p>Anything beyond this list is configured during implementation within an agreed scope, not presented as a built-in feature.</p><h2>Practical NDT for freshers and trainees</h2><p>India produces a large number of young people who want to enter NDT: diploma holders in mechanical and metallurgy, engineering graduates, and ITI-trained welders moving into inspection. What most of them lack is hands-on time. Equipment is expensive, flawed specimens are scarce, and companies can't spare instruments from site work for practice.</p><p><a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive 3D, game-like practice platform. Learners work through UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, pressure vessels and castings. They set up, scan, find indications and make calls, on a laptop, without a real instrument.</p><p>Every learner enrolled in the eLearning portal gets a Practical NDT section, with access granted automatically on enrolment or manually by an admin.</p><p>Indian companies use it for:</p><ul><li><strong>Fresher onboarding.</strong> New trainees reach their first supervised site job with a sense of what scanning and interpretation look like.</li><li><strong>Moving into advanced methods.</strong> PAUT and TOFD are increasingly specified on refinery, power and pipeline projects. Practical NDT gives conventional UT technicians an early feel for them.</li><li><strong>Preparing Gulf-bound crews</strong> who will face client practical demonstrations after they arrive.</li></ul><p>Practical NDT is practice, not documented industrial experience, and it doesn't replace any practical examination on real specimens.</p><p><a href=\"/contact?service=practical-ndt&amp;subject=Practical%20NDT%20and%20eLearning%20demo%20India\">Book a demo of Practical NDT inside eLearning</a>.</p><h2>Boiler, pressure vessel and IBR work</h2><p>A great deal of Indian NDT work is on boilers and pressure equipment. Boilers fall under the Indian Boiler Regulations, with inspection by state boiler inspectorates and IBR-recognised inspecting authorities. Radiography and ultrasonic testing of boiler tube and header welds are routine on thermal power plants, process boilers and new fabrication. Pressure vessels, gas storage and cylinders bring PESO into the picture under rules such as the SMPV(U) Rules.</p><p>Each of these regimes, plus the client's specifications and the fabricator's code (often ASME alongside IBR), shapes what a technician must know. That is exactly the type of training a portal handles well:</p><ul><li><strong>Procedure courses</strong> on your RT and UT procedures for boiler tube welds, with quizzes set by your Level III.</li><li><strong>Code awareness</strong> for technicians moving between IBR boiler work and ASME pressure vessel work, so they understand which acceptance criteria apply where. Your Level III decides the content.</li><li><strong>Reporting courses</strong> on what an inspecting authority or client expects in the report, so fewer reports come back for correction.</li></ul><p>Power plant shutdowns, whether at NTPC stations, state utilities or captive plants, bring bursts of boiler tube inspection work. Onboarding a temporary crew through the portal, with auto-join and access revoked after the job, keeps preparation quick and records clean.</p><h2>Radiography and AERB requirements</h2><p>Industrial radiography in India is regulated by the Atomic Energy Regulatory Board. Radiography institutions need AERB licences, work must be carried out by suitably certified radiography personnel, and a radiological safety officer is responsible for safety at the institution. AERB's requirements cover source handling, storage, transport, personnel monitoring and emergency preparedness, and licensing and personnel matters are handled through its e-LORA system.</p><p>The eLearning portal doesn't replace AERB certification or your RSO's responsibilities. It gives your RSO a practical way to deliver company content and prove who completed it:</p><ul><li>Your operating and emergency procedures as short video lessons with a quiz.</li><li>Radiation awareness for helpers, drivers and workers who operate near exposure areas.</li><li>Periodic refresher content assigned to radiography crews.</li></ul><p>The Certificates app's employee NDT profile records radiation safety training, TLD badge number and medical fitness expiry. The Fleet app records which vehicles can carry radioactive sources, with transport licence number and expiry. Practical NDT's RT scenarios let trainees practise technique, IQI placement and interpretation without any dose. What content satisfies AERB is your RSO's decision.</p><h2>Refineries, PSU tenders and EPC projects</h2><p>India's refining and petrochemical base is huge: Jamnagar on the Gujarat coast, the PSU refineries of IOCL, BPCL and HPCL at Panipat, Mathura, Kochi, Mumbai, Paradip and elsewhere, plus ONGC's offshore and onshore assets and GAIL's pipeline network. Shutdowns at these sites and new project work through large EPC contractors drive much of the country's NDT demand.</p><p>PSU tenders and EPC subcontracts set clear expectations for personnel: certified technicians at specified levels, evidence of training, and compliance with the owner's inspection specifications. Pre-qualification questionnaires often ask how you train and how you keep records.</p><p>The portal helps in three practical ways:</p><ul><li><strong>Client-specific courses</strong> per refinery or EPC, covering their procedures and reporting format, assigned to every technician on that contract.</li><li><strong>Shutdown onboarding</strong> at scale, using auto-join, followed by access revocation at demobilisation.</li><li><strong>Evidence for tenders</strong>, drawn from one system that shows who was trained on what, next to their certifications in the Certificates app.</li></ul><p>These asset owners are named here only as context for the work Indian NDT companies do; none is presented as an Atlantis customer.</p><h2>Languages, mobile learners and connectivity</h2><p>Indian crews learn best in the language they think in. Technical content usually stays in English, but safety and site-rule courses land better in Hindi, Telugu, Tamil, Gujarati or Odia, depending on where your crews come from. The portal doesn't translate automatically; build language versions of the courses that matter and invite each technician to the right one. Quiz questions imported from Word work in any language you type them in.</p><p>Most Indian learners will use a phone. Lessons stream from OneDrive or SharePoint, so they need a data connection. For crews at remote sites, plan course completion for days in town or at the office rather than on the job.</p><h2>DPDP Act and learner data</h2><p>Training records, quiz scores and learner account details are personal data under the Digital Personal Data Protection Act, 2023. The portal gives you practical controls to support your data practices: accounts created by admins, access granted and revoked by admins, and videos kept in your own Microsoft storage. Hosting, retention and role-based visibility are agreed with you during implementation. Atlantis does not claim the software makes you compliant with the DPDP Act; your policies do that.</p><h2>Selling courses: institutes and outside learners</h2><p>India has a busy market for NDT training, and many inspection companies also run a training wing. The portal's online course sales let you sell courses to outside learners, with orders and invoices flowing into the ERP's accounting. GST is configured locally during implementation; Atlantis makes no claim of certified e-invoicing. Be honest in course descriptions: a completion certificate is not NDT certification. Pairing a course with Practical NDT access is a strong offer for learners with no equipment of their own.</p><h2>Who uses the portal in an Indian NDT company</h2><h3>Level III and QA/QC heads</h3><p>They build procedure, code awareness and client courses, set quiz pass marks and pull completion records for PSU pre-qualification, EPC audits and third-party inspection agency reviews.</p><h3>Radiological safety officers</h3><p>They assign radiation safety content to radiographers, helpers and drivers and keep evidence of completion ready for AERB inspections.</p><h3>Trainees and technicians</h3><p>They study on their phones between jobs, take quizzes and open Practical NDT whenever they want practice. For freshers, it is often the first time they see what a real scan looks like.</p><h3>Operations and site managers</h3><p>They check training alongside certification and availability before sending a crew to a refinery shutdown or a boiler job.</p><h3>Training wing managers</h3><p>They run outside courses, manage course sales and learner accounts, and keep paying learners separate from staff.</p><h2>Connecting training to the rest of the ERP</h2><ul><li><strong><a href=\"/erp/apps/certificates\">Certificates</a></strong> records ISO 9712-based certifications, including ISNT's, alongside SNT-TC-1A and others, with level, method, expiry and vision tests. Certificates expiring within 90 days are flagged with warning tasks.</li><li><strong>Team Assignments</strong> treats training as an availability status, so nobody is sent to site on a course day.</li><li><strong>Surveys</strong> run competency questionnaires and feedback.</li></ul><p>How completions relate to training hours on the technician record is agreed during implementation. You can adopt eLearning alone or as part of the full <a href=\"/erp\">Atlantis NDT ERP</a>. Cost is quote on request; affordable, accessible, fully customizable. <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20quote%20India\">Request a quote for your Indian team</a>.</p><h2>Fabrication shops, export work and Gulf deployments</h2><p>India's fabrication clusters, around Vadodara, Hazira, Pune, Chennai, Coimbatore and the Mumbai belt, build pressure vessels, heat exchangers, columns, piping spools and structural steel for domestic and export markets. Export orders often mean ASME code work with an authorized inspector, or fabrication to European standards with a notified body or third-party inspection agency reviewing records. Many of these shops certify their NDT staff under an ASNT SNT-TC-1A written practice because their overseas clients expect it.</p><p>Under SNT-TC-1A, the written practice sets out the organised training a technician must complete, and the employer must be able to show it. That is where the eLearning portal earns its keep in a fabrication shop: a clear record, per technician, of which courses were completed, with quiz results and completion certificates, next to their certifications in the Certificates app.</p><p>India is also one of the biggest sources of NDT technicians for the Gulf. Companies that deploy crews to Saudi Arabia, the UAE, Qatar, Kuwait and Oman, directly or through manpower arrangements, need those technicians ready for client practical demonstrations and site rules on arrival. Useful courses before deployment include:</p><ul><li>Method refreshers built around the procedures the crew will use abroad.</li><li>Reporting courses for the client's documentation style.</li><li>Practical NDT sessions on UT, PAUT, RT and MT scenarios, so technicians arrive with their setup and scanning routine fresh.</li></ul><p>Atlantis's own training is based on ASNT SNT-TC-1A, which fits this export-facing and Gulf-facing work. Whether any Atlantis course content becomes part of your portal is agreed as part of your implementation scope.</p><h2>Keeping trainer knowledge when people move on</h2><p>Indian NDT companies lose experienced people constantly. Senior Level II technicians and Level IIIs are recruited by Gulf contractors, larger EPCs and overseas inspection companies, often at short notice. When they go, years of practical know-how can go with them: how to set up on a difficult nozzle weld, which indications a particular client worries about, how your reports should read.</p><p>The eLearning portal gives you a way to hold on to some of that. While your senior people are still with you, record them. A short video on a tricky technique, a walkthrough of a client's procedure, a talk on common reporting mistakes. Store the videos in OneDrive or SharePoint, where download protection applies when they play in the portal, and turn them into lessons in the right Level I, II or III section.</p><p>Question banks are the other asset worth protecting. Many Indian Level IIIs keep their questions in Word files on a personal laptop. Importing those into portal quizzes keeps them in the company, where the next trainer can review and extend them rather than starting again.</p><p>A practical approach many companies take:</p><ol><li>Pick the methods and clients where you depend most on one or two people.</li><li>Schedule short recording sessions with them, a few minutes per topic.</li><li>Import their question banks and have a second reviewer check them.</li><li>Assign the resulting courses to juniors, with Practical NDT scenarios for practice.</li></ol><p>Nothing replaces an experienced trainer standing next to a trainee on real work. But a library built from your own people's experience means a resignation letter no longer resets your training programme to zero.</p><h2>Frequently asked questions</h2><h3>Does the portal lead to ISNT or other ISO 9712 certification?</h3><p>No. It hosts your company's training. Atlantis's own courses follow ASNT SNT-TC-1A.</p><h3>Can we record both ASNT and ISO 9712 certificates?</h3><p>Yes, in the Certificates app, with expiry tracking.</p><h3>Can it deliver AERB-related radiation training?</h3><p>It can deliver and record content your RSO chooses. Whether that satisfies AERB is your RSO's decision.</p><h3>Will it work on phones?</h3><p>Learners can use the portal on a phone with a data connection, since lessons stream online.</p><h3>Can training institutes use it to sell courses?</h3><p>Yes. Online course sales are supported, with GST configured locally.</p><h3>What does it cost?</h3><p>Quote on request, based on scope.</p><h2>See it working</h2><p>Explore the 3D scenarios on the <a href=\"/practical-ndt\">Practical NDT page</a>, then <a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20India\">book an eLearning demo</a> with course examples built for Indian refinery, power and fabrication work.</p>\n<h2>eLearning by region</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning global overview</a></li><li><a href=\"/erp/apps/elearning/usa\">eLearning in United States</a></li><li><a href=\"/erp/apps/elearning/canada\">eLearning in Canada</a></li><li><a href=\"/erp/apps/elearning/europe\">eLearning in UK &amp; Europe</a></li><li><a href=\"/erp/apps/elearning/middle-east\">eLearning in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/surveys\">Surveys</a>: Exams, competency checks and client feedback forms.</li></ul>\n<p><a href=\"/contact?service=practical-ndt&amp;subject=eLearning%20demo%20(India)\">Send an enquiry about eLearning</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/dashboards","publishedAt":"2026-09-27","title":"NDT KPI Dashboards for Inspection Companies | Atlantis NDT","description":"See calibration due, expiring technician certs, overdue equipment and gross margin in one NDT ERP dashboard. Book a demo with Atlantis NDT.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT KPI Dashboards for Inspection Companies</h1>\n<p>KPI dashboards across jobs, reports, certifications and revenue. <a href=\"/contact?service=erp&amp;subject=Dashboards%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>The questions an NDT manager asks every Monday</h2><p>Which technicians have certificates running out before the next shutdown? Which flaw detectors are overdue for calibration? Who still has a thickness gauge that should have come back from site last week? How much did we actually invoice last month, and what did it cost us to earn it?</p><p>In most inspection companies those answers live in four places: a certification spreadsheet kept by the QA manager, a calibration list on the equipment controller's laptop, a whiteboard in the workshop and the accounts package. Getting a straight answer means phone calls and half a day of cross-checking. By the time the picture is assembled, it is already out of date.</p><p>The Dashboards app in Atlantis NDT ERP pulls those answers onto one screen. Because the certificates, instruments, jobs, timesheets and invoices are all held in the same system, the dashboard is not a separate report somebody has to refresh. It reads the live records that your team already keeps as part of their daily work.</p><p>This page explains what the dashboards show for an NDT company, who uses them, where the numbers come from, and what setting them up looks like. Atlantis NDT ERP is built on Odoo, pre-configured for inspection service providers and in-house NDT departments, and deployed by our team. It is affordable, accessible and fully customizable, and pricing is quote on request.</p><h2>What the Dashboards app shows an NDT company</h2><p>The Dashboards app gives you spreadsheet-style KPI dashboards. For an NDT business, the starting point is the set of numbers that cause real trouble when nobody is watching them:</p><ul><li><strong>Equipment calibration due and overdue</strong> – instruments and probes whose calibration is coming up or has lapsed, taken from the calibration records in Asset Management.</li><li><strong>Technician certifications expiring and expired</strong> – drawn from the Certificates app, where each cert carries its scheme, level, method and expiry date.</li><li><strong>Issued equipment overdue</strong> – kit that was issued to a technician or site and has not come back when it should have.</li><li><strong>Financial performance</strong> – revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, bills and expenses, with a 12-month view.</li></ul><p>That split matters. An NDT company can be profitable and still lose a client because a Level II's PT cert lapsed the week before a job. It can also have a spotless compliance record and still be slowly bleeding cash on unbilled standby days. The dashboards put both sides in front of you together.</p><p>Because the dashboards are spreadsheet-style, they are not a fixed screen you are stuck with. Additional KPIs that suit your business, such as a view by service line, by client or by region, are configured during implementation as part of the customization scope agreed with you. We start with the NDT indicators above and extend from there once you have used them for a few weeks and know what you actually look at.</p><h2>The compliance view: certificates and calibration at a glance</h2><p>Compliance is where an NDT company's reputation is won or lost. Auditors, clients and third-party inspectors all ask the same two questions: was the technician qualified on the day, and was the instrument calibrated on the day? The dashboard is there so you know the answer before they ask.</p><p>On the certification side, every technician cert in the <a href=\"/erp/apps/certificates\">Certificates app</a> has a status that the system works out automatically: active, expiring soon (within 90 days), expired or revoked. The dashboard counts those statuses so the QA manager or Level III sees at a glance how many certs are heading for expiry and how many have already gone. The detailed lists sit behind the Expiring Soon and Expired menus in the Certificates app, so the person following up goes straight to the names.</p><p>Vision tests are handled the same way. Near vision, far vision and colour perception tests have expiry dates, and the daily checks in the ERP create warning tasks 90 days before either a cert or a vision test expires. A technician with a current UT Level II but a lapsed eye test is not someone you want signing a report, and the system treats it that way.</p><p>On the equipment side, calibration records in Asset Management hold the provider, certificate number, pass, fail or conditional result and next due date. The calibration certificate register tracks whether each certificate is valid, expiring or expired. The dashboard turns that into a count of instruments due and overdue.</p><p>The practical effect: the compliance meeting becomes a quick look at a screen instead of an afternoon of spreadsheet reconciliation, and nobody finds out on site that something they rely on has lapsed.</p><h2>The equipment view: finding kit before it goes missing</h2><p>Every NDT company knows the feeling. A client calls for a PAUT job next week, the scanner is booked out on paper, and nobody is sure where the encoder and the wedge set actually are. Or an ultrasonic flaw detector comes back from a remote site weeks late with a cracked screen and no record of who had it.</p><p>Atlantis NDT ERP handles equipment through the Asset Management app: every instrument, probe and accessory tracked by serial number, with an issue and return workflow that records the condition of the item going out and coming back, and supervisor and manager approval on the issue. The Dashboards app adds the overview: a count of issued equipment that is overdue for return.</p><p>That single number changes behaviour. The equipment controller sees it every morning and chases the item while the technician still remembers where it is. Operations managers see it too, so the conversation happens before the kit is needed for the next job rather than after.</p><p>Put it next to the calibration due and overdue counts and you get a realistic picture of what equipment is actually available: not just what you own, but what is in the building, out of calibration, and fit to go to site. Team Assignments already warns planners if they assign an out-of-calibration instrument to a job and blocks double-booking of the same serial number; the dashboard gives the manager the wider view across the whole instrument pool.</p><p>If you track rental kit or consumables such as couplant, MT inks and penetrant sets with reorder levels, those records live in Asset Management as well, and extra dashboard views on them can be added during implementation.</p><h2>The financial dashboard: margin, not just revenue</h2><p>Inspection is a labour-and-equipment business with little room for error. A job quoted on day rates can quietly lose money through standby, extra travel or kit that sat idle on site. Owners usually find out when the accountant closes the quarter.</p><p>The financial dashboard in Atlantis NDT ERP shows:</p><ul><li>Revenue and cost of sales</li><li>Gross margin</li><li>Operating expenses and EBITDA</li><li>Outstanding customer invoices</li><li>Supplier bills and employee expenses</li><li>A 12-month view, so you see the trend and not just the current month</li></ul><p>The numbers come from the <a href=\"/erp/apps/invoicing\">Invoicing app</a>, where NDT invoices already carry the project, job or PO number, site, invoice type and industry sector, and split subtotals for labour, equipment and consumables. Invoice lines can hold the cost centre, method, equipment serial, technician, rate type and days or hours. That structure is what makes the dashboard useful to an NDT business rather than a generic profit and loss statement.</p><p>Outstanding invoices deserve a special mention. Many inspection firms work for large operators and EPCs with long payment cycles and strict PO matching. An invoice rejected because the PO number was wrong can sit unnoticed for weeks. Seeing the outstanding total every week, next to revenue, keeps cash collection on the agenda.</p><p>The financial dashboard is for the owner and the finance lead, not for everyone. Who can see which dashboard is set up during implementation, so technicians and planners see the operational KPIs while commercial figures stay with the people who need them.</p><h2>Who uses the dashboards, and what each role looks for</h2><p>An NDT company is usually small enough that people wear several hats, but the questions each role asks are distinct.</p><h3>Owner or managing director</h3><p>Looks at the 12-month financial view, gross margin and outstanding invoices, then glances at the compliance counts. The owner wants to know two things: are we making money, and is anything about to embarrass us in front of a client?</p><h3>Operations manager</h3><p>Focuses on issued equipment overdue and calibration due, because those decide whether next week's jobs can be staffed and equipped. Works hand in hand with the planners who use Team Assignments.</p><h3>QA manager or NDT Level III</h3><p>Owns the certification and vision-test picture. Uses the expiring and expired counts to schedule renewals, eye tests and re-examinations well before they bite. Also keeps an eye on company certifications such as ISO or API-type accreditations, which the Certificates app tracks with their own alert days.</p><h3>Equipment controller or stores</h3><p>Uses the overdue-issue and calibration counts as a daily to-do list: chase returns, book calibrations, move instruments into the right lifecycle state.</p><h3>Finance</h3><p>Watches outstanding invoices, bills and expenses, and uses the financial dashboard for month-end review.</p><p>Each role gets the dashboard that answers its questions, rather than one crowded screen for everybody. Which KPIs appear for which group is decided with you during implementation.</p><h2>Where the numbers come from: the apps behind the dashboard</h2><p>A dashboard is only as honest as the data under it. The Atlantis NDT ERP dashboards are useful because nobody types numbers into them. They read records created as a by-product of normal work in the other apps.</p><table><thead><tr><th>Dashboard figure</th><th>Where it comes from</th><th>Who keeps it up to date</th></tr></thead><tbody><tr><td>Certs expiring or expired</td><td>Certificates app: scheme, level, method, expiry date, computed status</td><td>QA manager or Level III</td></tr><tr><td>Calibration due or overdue</td><td>Asset Management: calibration records and certificate register</td><td>Equipment controller</td></tr><tr><td>Issued equipment overdue</td><td>Asset Management: issue and return workflow</td><td>Stores and technicians</td></tr><tr><td>Revenue, margin, outstanding</td><td>Invoicing: NDT invoices, bills, expenses</td><td>Finance</td></tr></tbody></table><p>Behind those sit the operational apps. Timesheets capture billable hours by method, site and work type, which feed billing. Project holds each NDT job with its client PO, methods, codes and assigned crew. Team Assignments dispatches technicians and equipment and blocks double-booking. Quotations turn into sales orders and then invoices.</p><p>Inspection reports themselves are produced in the NDT Reports app. If you also want inspection results placed on a 3D model of the asset for your clients, that is our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which works alongside the ERP as a separate product.</p><p>The point is simple: if your team uses the apps for their daily jobs, the dashboard stays current on its own. There is no separate monthly exercise to update the KPIs.</p><h2>A week with the dashboards: how teams actually use them</h2><p>Software earns its keep when it slots into a routine. Here is how a typical NDT company might build the dashboards into its week.</p><ol><li><strong>Monday morning ops meeting.</strong> The operations manager puts the operational dashboard on the screen. Overdue issued equipment gets an owner and a return date. Calibration due items are booked with the lab. Anyone with a cert in the expiring window is flagged to the planners so they are not assigned to long jobs that run past their expiry.</li><li><strong>Daily, first thing.</strong> The equipment controller checks the overdue and calibration counts before the vans leave. The ERP's daily checks have already created warning tasks for certs and vision tests coming up in the next 90 days, and configurable email alerts go to the people you chose for technician certs, calibration certificates and company certifications.</li><li><strong>Mid-week, QA.</strong> The Level III works through the expiring list: vision tests to book, OJT and training hours to confirm, renewals to submit to the certifying body.</li><li><strong>Month end.</strong> The owner and finance review the financial dashboard: revenue against cost of sales, gross margin, operating expenses and EBITDA, and the outstanding invoice total. The 12-month view shows whether this month is a blip or a trend.</li><li><strong>Before an audit.</strong> The QA manager checks that the expired counts are zero or explained, and that the calibration certificates behind recent work are valid.</li></ol><p>None of that requires a new habit beyond looking at a screen. The records are already there because the team uses the ERP to issue kit, log hours, record certs and raise invoices.</p><h2>Setting up Dashboards: what implementation looks like</h2><p>Atlantis NDT deploys and sets up the ERP for you. For the Dashboards app, the work is less about the dashboard itself and more about getting clean data into the apps it reads from.</p><ol><li><strong>Discovery.</strong> We talk through how you run jobs, which methods you offer, which certification schemes your technicians hold (SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP or others), how you calibrate instruments and how you invoice.</li><li><strong>Data load.</strong> Technician certs, vision tests, instrument lists with serial numbers and calibration dates, and open customers and invoices are loaded from your spreadsheets. This is the step that makes the first dashboard meaningful.</li><li><strong>Dashboard configuration.</strong> We set up the NDT KPIs and the financial dashboard, decide who sees what, and add any extra views you ask for within the agreed customization scope.</li><li><strong>Alerts.</strong> Recipients, look-ahead days and resend intervals for cert, calibration and company-certification emails are set to match how your QA and stores teams work.</li><li><strong>Training and handover.</strong> Short sessions for each role, so the people who keep the records understand why it matters to the dashboard.</li></ol><p>You can start with Dashboards alongside Certificates and Asset Management and add Invoicing later, or roll out the whole ERP at once. See the full list of <a href=\"/erp/apps\">ERP apps</a> or the <a href=\"/erp\">Atlantis NDT ERP overview</a> to plan what fits your company.</p><p>If you want to see the dashboards with NDT-style sample data before deciding, <a href=\"/contact?service=erp&amp;subject=Dashboards%20demo\">book a Dashboards demo</a> and we will walk through it with your questions in mind.</p><h2>Frequently asked questions</h2><h3>What KPIs do the NDT dashboards show out of the box?</h3><p>Equipment calibration due and overdue, technician certifications expiring and expired, issued equipment overdue for return, and a financial dashboard with revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, bills, expenses and a 12-month view.</p><h3>Can we add our own KPIs?</h3><p>Yes. The dashboards are spreadsheet-style, and additional KPIs such as views by client, service line or region are configured during implementation as part of the customization scope agreed with you.</p><h3>Do we need to update the dashboard manually?</h3><p>No. The figures come from records your team already keeps in the Certificates, Asset Management, Timesheets and Invoicing apps. Keep those current and the dashboard stays current.</p><h3>How early does the system warn about expiring certificates?</h3><p>A cert is marked expiring soon 90 days before its expiry date, and daily checks create warning tasks at that point for certs and vision tests. Email alert recipients, look-ahead days and resend intervals are configurable.</p><h3>Can technicians see the financial figures?</h3><p>Only if you want them to. Access to each dashboard is set up by role during implementation, so commercial figures stay with owners and finance.</p><h3>Is this just a generic Odoo dashboard?</h3><p>It runs on Odoo, but the KPIs are built around NDT records: technician certs by scheme and method, instrument calibration, equipment issue and return, and invoices structured by project, site, method and technician.</p><h3>How is Atlantis NDT ERP priced?</h3><p>Pricing is quote on request, based on the apps you need and the customization scope. The aim is to be affordable and accessible for NDT companies of any size.</p><h2>See your NDT company on one screen</h2><p>If your compliance picture lives in one spreadsheet, your equipment in another and your margin in the accountant's head, the Dashboards app brings them together without adding work. Your team keeps doing its job in the ERP; the dashboard shows you what that work adds up to.</p><p>Tell us how your company runs and what you want to see on Monday morning. We will show you the NDT dashboards, explain what is built in and what we would configure for you, and give you a clear quote. <a href=\"/contact?service=erp&amp;subject=Dashboards%20quote\">Request a quote for Atlantis NDT ERP Dashboards</a> or <a href=\"/contact?service=erp&amp;subject=Dashboards%20demo\">book a demo</a>.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Dashboards%20demo\">Send an enquiry about Dashboards</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/surveys","publishedAt":"2026-09-27","title":"NDT Surveys: Competency Checks & Client Feedback | Atlantis NDT","description":"Run competency questionnaires, toolbox quizzes and client feedback surveys inside your NDT ERP. Affordable and customizable. Request a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Surveys for Competency Checks and Client Feedback</h1>\n<p>Exams, competency checks and client feedback forms. <a href=\"/contact?service=erp&amp;subject=Surveys%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Competence is more than a certificate card</h2><p>A current Level II card tells a client that a technician passed a qualification exam at some point and has the required experience. It does not tell you whether that technician has read the revised UT procedure you issued last month, understands the acceptance criteria in this client's specification, or remembers the permit-to-work rules for the site they are driving to tomorrow.</p><p>Most NDT companies handle those gaps informally. The Level III has a chat in the workshop, somebody signs a paper sheet saying they read the procedure, and the sheet goes into a folder that nobody opens until an auditor asks. Client feedback is even looser: a thank-you email if the job went well, a phone call if it did not, and nothing written down either way.</p><p>The Surveys app in Atlantis NDT ERP gives those checks a proper home. It is the standard Odoo Surveys app, set up for an NDT company: competency questionnaires for technicians, knowledge checks on procedures and client requirements, induction quizzes before mobilisation, and feedback forms for clients after a job. The answers are stored in the same ERP as your technicians, jobs and customers, so they are there when you need to show them.</p><p>This page covers what the app does, realistic ways NDT companies use it, how it sits next to the Certificates, Procedures and eLearning apps, and what setting it up involves. Atlantis NDT ERP is affordable, accessible and fully customizable, with pricing on a quote-on-request basis.</p><h2>What the Surveys app does</h2><p>Surveys is a questionnaire builder with scoring and results analysis. The standard features that matter most to an NDT company are:</p><ul><li><strong>Several question types</strong> – single choice, multiple choice, free text, numeric answers, dates and matrix questions, grouped into sections.</li><li><strong>Scoring</strong> – mark correct answers, give each a score and set a pass percentage, so a questionnaire can act as a quiz with a clear pass or fail.</li><li><strong>Time limits and attempt limits</strong> – useful when a knowledge check should be done in one sitting and not retaken endlessly.</li><li><strong>Randomised questions</strong> – draw a set number of questions per section from a larger pool, so two technicians sitting side by side do not get identical papers.</li><li><strong>Conditional questions</strong> – show a follow-up only when a certain answer is given, for example asking for details when a client rates a job as poor.</li><li><strong>Invitations and links</strong> – invite named people by email, or share a link for a client to answer without logging in.</li><li><strong>Results</strong> – see answers per participant and summarised results per question, and filter to find who passed, who failed and what they got wrong.</li></ul><p>A survey can also issue a certificate of completion when a participant passes. Be clear about what that is: a record that someone passed an internal quiz. It is not an NDT certification, and it does not replace qualification under your written practice. Formal qualification records, including examination sheets with general, specific and practical scores, live in the Certificates app.</p><p>How far each feature is used, and how surveys are laid out for your company, is agreed during implementation.</p><h2>Competency questionnaires for NDT technicians</h2><p>Under an employer-based scheme such as ASNT SNT-TC-1A, the employer is responsible for the technician's qualification and has to be able to show it. Many companies also want ongoing evidence that people stay competent between recertifications. Short, targeted questionnaires are a practical way to collect that evidence.</p><p>Typical uses in an NDT company:</p><ul><li><strong>Method refreshers.</strong> A PT quiz on dwell times, surface preparation and developer application; an MT quiz on field indicators and particle types; a UT quiz on reference blocks, DAC curves and scanning sensitivity. Your Level III writes the questions; the app handles the scoring.</li><li><strong>Technique checks before advanced work.</strong> Before a technician is put on TOFD or PAUT weld inspection for the first time with you, a questionnaire on your technique sheets and setup checks gives the Level III a documented starting point.</li><li><strong>Code and acceptance-criteria checks.</strong> Questions on the acceptance criteria in the code or client specification the technician will work to, so nobody finds out on the job that they have been using the wrong table.</li><li><strong>New-hire assessment.</strong> A technician joining with a certificate from another employer can answer a baseline questionnaire, which helps the Level III decide what extra OJT or training is needed before your company certifies them.</li></ul><p>Randomised question pools and time limits make these quizzes harder to game. Results per participant show exactly which questions each technician got wrong, so follow-up training is aimed at the real gaps rather than repeating a whole course.</p><p>Keep the boundary clear: these are supporting evidence and internal checks. The qualification exam records for certification, with their general, specific and practical scores and pass mark, belong in the <a href=\"/erp/apps/certificates\">Certificates app</a>.</p><h2>Procedure read-and-understood checks</h2><p>Every NDT company revises procedures. A new client specification arrives, a code edition changes, an audit finding needs closing, or the Level III simply tightens a technique. The hard part is not writing the revision; it is proving that the technicians who use it have actually read it.</p><p>In Atlantis NDT ERP, procedures are controlled in the <a href=\"/erp/apps/procedures\">Procedures app</a>: document number, revision, method, scope, applicable standard and acceptance criteria, with a draft, review, approval and publish workflow and a full revision history. When a revision is published, the Surveys app gives you the second half of the story.</p><p>A simple pattern works well:</p><ol><li>The Level III approves and publishes the new revision of, say, the MT procedure.</li><li>A short read-and-understood questionnaire is created for that revision: a confirmation that the technician has read it, plus a handful of questions on what changed.</li><li>Invitations go by email to every technician who works in that method.</li><li>Results show who has completed it, who passed and who still needs chasing.</li></ol><p>That gives you a record per technician, per revision, stored in the same system as the procedure itself. When an auditor asks how you communicated the change, you show the survey results instead of hunting for a signed sheet.</p><p>Out of the box this is a manual step: someone creates and sends the questionnaire. If you want invitations triggered automatically when a procedure is published, or the survey linked to the procedure record, that is configured during implementation as part of the agreed customization scope.</p><h2>Site induction and pre-mobilisation checks</h2><p>Refineries, petrochemical plants, power stations and fabrication yards all have their own site rules. Before a crew arrives they usually need to complete an induction, understand permit-to-work arrangements, and know the site's specific hazards. For radiography crews there is the added layer of radiation safety and barrier arrangements.</p><p>The Project app in Atlantis NDT ERP already records safety induction and work permit fields against each NDT job. The Surveys app can sit next to that as a knowledge check:</p><ul><li>A short quiz on the client's site rules, muster points, gas testing and permit requirements, sent to each technician assigned to the job.</li><li>A radiation safety refresher for radiographers before a campaign, with questions set by your radiation protection lead.</li><li>A pre-mobilisation checklist for the crew lead: PPE, documents, instruments, calibration certificates and procedures in the van.</li></ul><p>Surveys in this role are about catching gaps before the crew is standing at the gate. A technician who fails the site-rules quiz can be briefed properly the day before, rather than being turned away by the client's safety officer on the day.</p><p>Results are visible to the operations manager and the planner. Linking survey completion directly to a specific job or technician assignment, so the planner sees it inside the job record, is something we can configure during implementation if you want it.</p><p>These checks do not replace the client's own induction or your safety management system. They give you a documented, repeatable way to make sure your people arrive ready.</p><h2>Client feedback after every job</h2><p>Most NDT companies only hear from clients when something goes wrong. Good work goes unrecorded, and small irritations never get mentioned until the client quietly gives the next shutdown to a competitor.</p><p>A short feedback survey sent after each job fixes that. A realistic NDT client survey asks:</p><ul><li>Did the crew arrive on time and with the right equipment?</li><li>Were the technicians competent in the methods required?</li><li>Did they follow site safety rules and permits?</li><li>Were the reports clear, accurate and delivered when promised?</li><li>How easy were we to deal with on quoting, changes and invoicing?</li><li>Would you use us again, and is there anything we should change?</li></ul><p>Conditional questions let you ask for detail only when a low rating comes in, which keeps the survey short for the happy client and useful for the unhappy one. A shared link means the client's QA/QC inspector or site engineer can answer without an account.</p><p>Report quality is often what clients notice most. Inspection reports in Atlantis NDT ERP come from the NDT Reports app, with method-specific data, review and approval signatures and branded templates. If your clients want to see results placed on a 3D model of their asset, our companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> works alongside the ERP to do that. Feedback surveys will tell you whether your clients value that kind of reporting before you commit to it.</p><p>Collected over time, feedback also gives your sales team honest material for conversations with the same client, and gives your quality system the customer-satisfaction evidence that ISO 9001 audits ask about.</p><h2>Other internal uses: suppliers, onboarding and staff feedback</h2><p>Once the app is in place, NDT companies tend to find more uses for it. A few that fit the business well:</p><h3>Supplier and calibration lab evaluation</h3><p>Your quality system probably requires you to evaluate suppliers. A questionnaire for the stores lead or equipment controller, filled in after each calibration round, records turnaround, communication and certificate quality for each lab. The Purchase app already flags vendor types such as OEM, dealer and calibration lab, with accredited-lab details, so the evaluation sits alongside the supplier data.</p><h3>Technician onboarding</h3><p>A new technician's first week involves a lot of paperwork: personal details, certificates held, methods, emergency contacts, PPE sizes. A structured onboarding survey collects it in one go, so HR and the QA manager are not chasing the same person for different pieces.</p><h3>Staff and crew feedback</h3><p>Field technicians spend long stretches away on shutdowns and remote sites. A short, periodic survey on workload, travel, equipment condition and site conditions tells management where the pressure points are before people leave.</p><h3>Internal audit checklists</h3><p>A survey can be laid out as a checklist for an internal audit of a job file or the workshop: are calibration certificates present, are procedures the current revision, are reports signed by reviewer and approver? It is not a full audit management system, but it gives you a consistent record of what was checked.</p><p>All of these use standard Surveys features. The questions, scoring and who receives them are set up with you during implementation.</p><h2>How Surveys connects to training and the rest of the ERP</h2><p>Surveys is one piece of how an NDT company builds and proves competence. It works best next to the other apps:</p><ul><li><strong>Certificates</strong> holds the formal record: scheme, level, method, certifying body, OJT and training hours, exam sheets and vision tests, with automatic expiry status. Surveys adds ongoing evidence between recertifications.</li><li><strong>Procedures</strong> controls the documents; Surveys confirms people have read and understood them.</li><li><strong>Project</strong> holds job, induction and permit details; Surveys checks that the crew knows the site rules.</li><li><strong>eLearning</strong> runs courses with video lessons and quizzes for structured learning. Surveys is lighter and quicker for one-off checks and feedback.</li><li><strong>CRM and Contacts</strong> hold the client records that feedback surveys go to.</li></ul><p>For hands-on skills, a questionnaire only goes so far. Knowing the right answer about probe angle is not the same as finding the indication. That is why Atlantis offers <a href=\"/practical-ndt\">Practical NDT</a>, an immersive 3D, game-like practice platform with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings. Learners enrolled in the ERP's eLearning portal get a Practical NDT section that opens the platform, with access granted automatically on enrolment or manually by an admin.</p><p>If your survey results show gaps that need formal teaching, Atlantis also provides <a href=\"/training\">NDT training</a> based on ASNT SNT-TC-1A, along with consulting on written practices and procedures.</p><h2>Setting up Surveys for your NDT company</h2><p>Because Surveys is a standard app, the setup work is mostly about content and process, not software. Atlantis NDT handles it as part of the ERP deployment.</p><ol><li><strong>Agree the uses.</strong> We start with the surveys that give you the most value first, usually procedure read-and-understood checks and client feedback, then add competency questionnaires as your Level III writes them.</li><li><strong>Build templates.</strong> We set up template surveys for each use, with sensible sections, scoring and pass marks. Your Level III supplies or approves the technical questions; we do not put technical content in front of your technicians without your review.</li><li><strong>Branding and access.</strong> Client-facing surveys carry your company branding. Internal quizzes can require login so results tie to the right employee.</li><li><strong>Routine.</strong> We agree who sends what and when: feedback at job close, read-and-understood at each procedure publish, refreshers on a schedule your QA manager sets.</li><li><strong>Optional customization.</strong> Automatic triggers or links to job and procedure records are scoped and configured with you if you want them.</li></ol><p>You can run Surveys on its own from day one, or introduce it once Certificates and Procedures are in use. Either way it adds very little overhead for the people answering. <a href=\"/contact?service=erp&amp;subject=Surveys%20demo\">Book a Surveys demo</a> and we will show you sample NDT questionnaires and feedback forms.</p><h2>Frequently asked questions</h2><h3>Can the Surveys app replace our NDT qualification exams?</h3><p>No. Surveys is for internal knowledge checks, feedback and supporting evidence. Qualification exam records with general, specific and practical scores and a pass mark are kept in the Certificates app, under your written practice.</p><h3>Can we score quizzes and set a pass mark?</h3><p>Yes. You mark correct answers, give each a score and set a pass percentage. Results show each participant's score and which questions they got wrong.</p><h3>Can clients answer a feedback survey without an account?</h3><p>Yes. You can share a link that clients open and complete without logging in, or invite named contacts by email.</p><h3>Can we stop technicians sharing answers?</h3><p>You can randomise questions from a larger pool per section, set a time limit and limit attempts, which makes copying much harder.</p><h3>Are surveys linked automatically to procedures or jobs?</h3><p>Not out of the box. Surveys are created and sent from the Surveys app. Automatic triggers or links to procedure and job records can be configured during implementation as part of the agreed scope.</p><h3>Does Atlantis write our competency questions?</h3><p>We set up the templates and structure. Technical questions should come from, or be approved by, your Level III so they match your procedures and written practice. Our consulting team can help if you need support.</p><h3>How much does the Surveys app cost?</h3><p>Pricing for Atlantis NDT ERP is quote on request, based on the apps and customization you need. It is designed to be affordable for NDT companies of any size.</p><h2>Put competence and client feedback on record</h2><p>If your read-and-understood sheets live in a folder and client feedback lives in people's inboxes, the Surveys app gives both a place in the same system as your technicians, procedures and jobs. It is simple to run, light on your team's time and useful the next time an auditor or client asks how you know.</p><p><a href=\"/contact?service=erp&amp;subject=Surveys%20quote\">Request a quote for Atlantis NDT ERP</a> or tell us which surveys you would start with, and we will show you how they would look for your company.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/elearning\">eLearning</a>: Courses, quizzes and certificates for technician training and refreshers.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Surveys%20demo\">Send an enquiry about Surveys</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/project","publishedAt":"2026-09-27","title":"NDT Job & Project Management Software | Atlantis NDT","description":"Manage NDT jobs with client PO, methods, codes, acceptance criteria, crews and equipment in one place. Built on Odoo for inspection firms. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Project and Job Management Software</h1>\n<p>Inspection projects, tasks and milestones from award to final report. <a href=\"/contact?service=erp&amp;subject=Project%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>When the job file is a folder, an inbox and a whiteboard</h2><p>An NDT job looks simple from the outside: a client needs welds, vessels or pipework inspected, you send qualified people with calibrated equipment, and you deliver reports. Inside the company it is a tangle. The PO is in someone's email. The scope and acceptance criteria are in the client's specification PDF. The crew is on the planning whiteboard. The equipment is in the stores book. The results are scattered across report drafts, and the defect count the client asks for at the end of the week has to be totted up by hand.</p><p>When the operations manager is on leave, nobody else can piece the job together. When the client disputes an invoice, it takes a day to find the PO number and the agreed scope. When an auditor asks which procedure revision was used on a job six months ago, the answer depends on who remembers.</p><p>The Project app in Atlantis NDT ERP turns each NDT job into one record that holds all of that: client and PO, contract, site, methods, codes, scope, acceptance criteria, assigned technicians and equipment, safety induction and work permit details, and the job status. Tasks under the job carry the method, technician, component, result, indication and defect counts, and procedure and WPS references.</p><p>Atlantis NDT ERP is built on Odoo, pre-configured for NDT service providers and in-house inspection departments, and set up for you by our team. It is affordable, accessible and fully customizable, with pricing quote on request. This page explains how the Project app works for an NDT company, day to day.</p><h2>What an NDT job record holds</h2><p>Generic project software asks for a name, a deadline and a list of tasks. An NDT job needs more than that, and the Project app is set up with fields that match how inspection work is actually specified and delivered.</p><table><thead><tr><th>Field</th><th>Why it matters for NDT</th></tr></thead><tbody><tr><td>NDT job type</td><td>Separates, for example, shutdown support from fabrication QC or in-service inspection, so you can sort and report on them.</td></tr><tr><td>Site</td><td>Where the crew is going, which drives travel, induction and permit needs.</td></tr><tr><td>Client PO and contract</td><td>The references the client's accounts team will check your invoice against.</td></tr><tr><td>Methods</td><td>UT, RT, MT, PT, VT, PAUT, TOFD and others required on the job.</td></tr><tr><td>Codes</td><td>The code or specification the work is performed to.</td></tr><tr><td>Scope</td><td>What is included, and by implication what is not.</td></tr><tr><td>Acceptance criteria</td><td>What technicians accept or reject against.</td></tr><tr><td>Assigned technicians and equipment</td><td>Who and what is committed to the job.</td></tr><tr><td>Safety induction and work permit</td><td>Site access requirements recorded on the job.</td></tr><tr><td>Job status</td><td>Where the job stands at any moment.</td></tr></tbody></table><p>Filling these in once, at the start of the job, saves them being rediscovered again and again: by the planner choosing a crew, by the technician checking acceptance criteria on site, by the reviewer checking the report, and by the accounts team raising the invoice. Everyone reads the same record.</p><h2>Tasks: breaking a job into components, methods and results</h2><p>Most NDT jobs are made of many smaller pieces of work: a batch of butt welds on a spool, nozzles on a vessel, a run of pipe supports, a tank floor, a set of castings. The Project app handles those as tasks under the job, and each task carries NDT-specific information:</p><ul><li><strong>Method</strong> – the technique applied to that piece of work.</li><li><strong>Technician</strong> – who performed it.</li><li><strong>Component</strong> – the weld, item or area inspected.</li><li><strong>Result</strong> – the outcome for that task.</li><li><strong>Indication and defect counts</strong> – how many indications were recorded and how many were rejectable defects.</li><li><strong>Procedure and WPS references</strong> – the procedure used and, for weld inspection, the welding procedure specification the weld was made to.</li></ul><p>Structured this way, the job becomes something you can query. How many welds has RT covered on this spool package? How many defects have been found so far this week? Which technician inspected the nozzle the client is now asking about? The answer is in the task list rather than in a stack of paper.</p><p>How you split tasks is up to you. Some companies create a task per component, others per method per area, others per shift. We agree the approach that suits your work during implementation, so tasks are useful without turning into admin.</p><p>Tasks move through stages on a kanban board, which gives the crew lead and the operations manager a simple visual of what is waiting, in progress and complete. List views make it easy to filter by method, technician or result when the client asks for a summary.</p><h2>From quotation to job to invoice</h2><p>A job does not start in the Project app. It starts with an enquiry, turns into a quotation and becomes work only when the client accepts. Atlantis NDT ERP keeps that thread unbroken.</p><ol><li><strong>Quotation.</strong> In the <a href=\"/erp/apps/quotations\">Quotations app</a>, you build the quote with job type, site, project dates and applicable codes, using NDT service products flagged with method and category, and send a branded quotation PDF. The client can accept and sign online.</li><li><strong>Sales order.</strong> The accepted quote converts to a sales order. It can be set up so that confirming the order creates the NDT project for the job, so nobody has to re-type the client, site and scope.</li><li><strong>Job execution.</strong> The project holds the PO, methods, codes, acceptance criteria and crew. Tasks track the work and its results.</li><li><strong>Time capture.</strong> Technicians log hours in <a href=\"/erp/apps/timesheets\">Timesheets</a> against the job, with work type (inspection, travel, standby, setup), method, billable flag, rate multiplier, site and equipment serial.</li><li><strong>Invoice.</strong> Billable hours feed billing. NDT invoices carry the project, job or PO number, site and industry sector, with subtotals for labour, equipment and consumables.</li></ol><p>The benefit is not only speed. It is that the invoice matches what the client ordered and what the crew actually did, with the PO number the client expects. Fewer invoices bounce back from the client's accounts payable team, and fewer billable standby hours are forgotten.</p><p>The exact flow from sales order to project, and how service products map to jobs, is configured during implementation to match how you quote and bill.</p><h2>Crew and equipment: the right people and calibrated kit on every job</h2><p>The job record lists assigned technicians and equipment. Planning who goes where, and when, is done in the <a href=\"/erp/apps/team-assignments\">Team Assignments app</a>, which works hand in hand with Project.</p><p>Team Assignments runs a dispatch workflow from planned, to dispatched, to in field, to submitted and closed, with site coordinates and mobilisation and demobilisation dates. Its availability calendar tracks each technician as assigned, on leave, in training, sick or unavailable, and blocks overlaps. It also blocks double-booking of the same technician or the same equipment serial number, and warns when an instrument assigned to a job is out of calibration.</p><p>Put together with Project, that means:</p><ul><li>The planner sees which technicians are free for the job dates, not just who is certified.</li><li>The flaw detector or PAUT unit committed to one job cannot be promised to another at the same time.</li><li>An instrument with lapsed calibration is flagged before it goes to site, not after the report is questioned.</li></ul><p>Qualification is checked at the other end too. Technicians' certifications live in the Certificates app with scheme, level, method and expiry, and a status worked out automatically. When hours are logged in Timesheets, the system warns if the technician's certificate is not valid. That gives the QA manager a safety net against someone working outside their certification.</p><p>Equipment itself, with serial numbers, issue and return, calibration records and maintenance, is managed in Asset Management. Project shows what has been committed to this job, so everyone involved sees the same list.</p><h2>Codes, procedures and acceptance criteria on every job</h2><p>An inspection is only as good as the criteria it is performed to. A technician who applies the wrong acceptance table, or works to last year's procedure revision, can turn a clean job into a re-inspection and a disputed invoice.</p><p>The Project app keeps the technical basis of the job on the job record: the codes that apply, the scope and the acceptance criteria. Tasks carry procedure and WPS references, so each piece of work is tied to the document it was done to.</p><p>Procedures themselves are controlled in the Procedures app. Each has a document number, revision, method, scope, applicable standard and acceptance criteria, with a draft, review, approval and publish workflow and a full revision history. Approved revisions are locked. When a task references a procedure, the reviewer and any auditor can see which controlled document was meant.</p><p>For weld inspection, the WPS reference matters because it ties the inspected weld to the welding procedure and, through that, to the material and process details the client's QA/QC team cares about. Recording it on the task saves the reviewer from searching the client's documentation later.</p><p>This also helps with client and third-party audits. When someone asks which procedure and acceptance criteria were applied to a particular component, you open the job and the task instead of reassembling it from memory. The link from job to report is completed in the NDT Reports app, where each report captures its own work order, drawing, WPS, procedure and standard references.</p><p>If your clients issue their own specifications and technique sheets, how those are attached to jobs is agreed during implementation.</p><h2>Site safety: induction and work permits</h2><p>NDT crews work in some of the most controlled environments in industry: live refineries, petrochemical plants, power stations, offshore installations and busy fabrication yards. Getting a crew through the gate means inductions, permits and, for radiography, radiation safety arrangements. Missing one of those can cost a whole shift.</p><p>The Project app records safety induction and work permit fields against each job. That gives the planner and crew lead one place to check the site requirements before mobilising, rather than relying on the memory of the last person who went to that site.</p><p>In practice, NDT companies use these fields to answer questions like:</p><ul><li>Does this site require a client induction before arrival, and has the crew done it?</li><li>What permit arrangements apply, and who on the client side issues them?</li><li>Are there site-specific requirements the crew lead should brief on day one?</li></ul><p>Other apps support the same goal. The Fleet app records whether a vehicle can carry radioactive sources, with transport licence number and expiry. The Employees app holds each technician's NDT profile, including radiation safety training, radiation badge number and medical fitness expiry. Surveys can be used for short site-rules knowledge checks before mobilisation.</p><p>None of this replaces your safety management system or the client's own rules. It puts the practical details in the job record, so the crew that turns up at the gate is the crew that is ready to work.</p><h2>Who uses the Project app</h2><h3>Operations manager</h3><p>Owns the job from award to close. Sets up the job record, confirms scope, codes and acceptance criteria, and keeps an eye on status across all live jobs.</p><h3>Planner or dispatcher</h3><p>Assigns technicians and equipment, working with Team Assignments to avoid clashes and out-of-calibration kit.</p><h3>Crew lead and technicians</h3><p>Check the job for site, methods, acceptance criteria and procedure references. Update task results, indication and defect counts, and log hours against the job.</p><h3>NDT Level III and QA manager</h3><p>Review whether the right procedures and acceptance criteria are specified, and use task records when reviewing reports or answering audit questions.</p><h3>Accounts</h3><p>Use the client PO, contract and timesheet data to raise invoices that match what the client ordered.</p><h3>Owner</h3><p>Sees what is live, what is late and what is ready to invoice, without calling each manager.</p><p>Everyone works from the same job, which cuts down the back-and-forth that eats a planner's day. Access rights, so that technicians see what they need and commercial details stay with the office, are set up during implementation.</p><h2>Reports and results: from task to client deliverable</h2><p>A job ends with a deliverable, and in NDT that is a set of reports the client can rely on. The Project app tracks the work; the reports are produced in the NDT Reports app, which covers 17 report types including UT, RT, MT, PT, VT, PAUT, TOFD and UT thickness, with a draft, review, approval and send workflow and inspector, reviewer and approver signatures.</p><p>Reports capture their own references, such as work order, request, WPS, contract, drawing, procedure and standard, so the report and the job line up. Task results and defect counts in Project give the operations manager a running picture while the formal reports are being written and reviewed.</p><p>For clients who want more than a stack of PDFs, Atlantis offers a companion product: <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which places inspection results on a 3D model of the asset. It is a separate product that works alongside the ERP. It suits owners and operators who want to see where findings sit on a vessel, tank or piping system, and it gives service providers a way to stand out when bidding for inspection contracts.</p><p>Whether you deliver plain PDFs or 3D results, the principle is the same: the job, its tasks and its reports tell one consistent story, from the client's PO to the last signed report.</p><h2>Setting up the Project app</h2><p>Atlantis NDT deploys and configures the ERP for you. For Project, implementation usually covers:</p><ol><li><strong>Job types and stages.</strong> We agree your NDT job types and the stages a job and its tasks go through, so the kanban boards reflect how your company really works.</li><li><strong>Task structure.</strong> Per component, per method, per area or per shift: we pick the split that gives you useful data without burying technicians in admin.</li><li><strong>Quote-to-job link.</strong> How accepted quotations and sales orders create jobs, and how service products map to methods.</li><li><strong>Open jobs.</strong> Live jobs can be loaded so you start with a complete picture rather than running two systems side by side.</li><li><strong>Access and training.</strong> Short sessions for operations, planners, technicians, QA and accounts.</li></ol><p>Project works best alongside Team Assignments, Timesheets and Invoicing, and many companies start with those plus Certificates. See the <a href=\"/erp\">Atlantis NDT ERP overview</a> for the full picture. <a href=\"/contact?service=erp&amp;subject=Project%20demo\">Book a Project app demo</a> and bring one of your real jobs; we will show you how it would look.</p><h2>Frequently asked questions</h2><h3>Is this just the standard Odoo Project app?</h3><p>It is built on Odoo Project, configured for NDT. Jobs carry NDT job type, site, client PO, contract, methods, codes, scope, acceptance criteria, assigned technicians and equipment, job status and safety induction and work permit fields. Tasks carry method, technician, component, result, indication and defect counts, and procedure and WPS references.</p><h3>Can we see all live jobs at once?</h3><p>Yes. Jobs are shown in kanban and list views that can be grouped and filtered by status, client, site or job type. Technician scheduling is handled in Team Assignments, which has calendar, kanban and list views.</p><h3>Can a confirmed quote create the job automatically?</h3><p>It can be set up so that confirming the sales order creates the project. The exact mapping is configured during implementation.</p><h3>Can technicians update tasks from site?</h3><p>Technicians with access can update task results and counts in the ERP. Inspection reports themselves are captured in the NDT Reports offline field app, which works without signal and syncs later.</p><h3>Will it stop us sending an unqualified technician?</h3><p>It gives you several checks. Timesheets warns when a technician's certificate is not valid, the Certificates app flags certs as expiring soon or expired, and Team Assignments blocks double-booking and warns about out-of-calibration equipment.</p><h3>Does it work for in-house NDT departments, not just service companies?</h3><p>Yes. Owner-operators and fabricators with their own NDT teams can run internal work as jobs. How the client fields map to internal departments is configured during implementation.</p><h3>How is it priced?</h3><p>Atlantis NDT ERP is quote on request, based on the apps you choose and the customization scope. It is designed to be affordable and accessible.</p><h2>One record for every NDT job</h2><p>If your jobs live across an inbox, a whiteboard and a stack of paper, the Project app brings them into one record that planners, technicians, QA and accounts all share. Fewer lost POs, fewer wrong acceptance criteria on site, and invoices that match what was ordered.</p><p><a href=\"/contact?service=erp&amp;subject=Project%20quote\">Request a quote for Atlantis NDT ERP</a> or <a href=\"/contact?service=erp&amp;subject=Project%20demo\">book a demo</a> and we will walk through your job workflow with you.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Project%20demo\">Send an enquiry about Project</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/timesheets","publishedAt":"2026-09-27","title":"NDT Timesheets: Billable Hours by Method & Site | Atlantis NDT","description":"Log NDT hours by method, site and work type, flag billable time, and get warned when a technician's cert is invalid. Request a quote from Atlantis NDT.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Timesheets for Inspection Technicians</h1>\n<p>Technician hours per job, feeding payroll and client invoicing. <a href=\"/contact?service=erp&amp;subject=Timesheets%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why NDT timesheets are harder than they look</h2><p>For an office business, a timesheet is a record of hours. For an NDT company it is the basis of the invoice, the evidence of who did what on a client's site, and often the only record of the standby hours the client agreed to pay for. Get it wrong and you either under-bill or end up in an argument with the client's accounts team.</p><p>The usual setup is paper or spreadsheets. Technicians fill in sheets on site, sometimes countersigned by the client's representative, then photograph them and send them in at the end of the week or the end of the job. The office re-keys them into payroll and billing. Travel days get lumped in with inspection days. Standby while the client sorts out a permit is noted in the margin, if at all. Nobody records which flaw detector or crawler was on the job, so equipment charges are guessed. And nobody checks, at the moment the hours are logged, whether the technician's cert was actually valid.</p><p>The Timesheets app in Atlantis NDT ERP is set up for exactly this work. Each entry records the work type (inspection, travel, standby or setup), the method, whether it is billable, a rate multiplier, the site, the client, the equipment serial and an approval, and the system warns if the technician's certificate is not valid. Billable hours feed billing.</p><p>Atlantis NDT ERP is built on Odoo, pre-configured for inspection companies and deployed by our team. It is affordable, accessible and fully customizable, and pricing is quote on request.</p><h2>What an NDT timesheet entry holds</h2><p>Every line a technician or supervisor logs carries the detail an NDT business needs to bill and to prove the work:</p><table><thead><tr><th>Field</th><th>What it answers</th></tr></thead><tbody><tr><td>Job and task</td><td>Which NDT job and which piece of work the hours belong to.</td></tr><tr><td>Work type</td><td>Inspection, travel, standby or setup.</td></tr><tr><td>Method</td><td>UT, RT, MT, PT, PAUT, TOFD or whichever method was performed.</td></tr><tr><td>Billable flag</td><td>Whether the client is charged for this time.</td></tr><tr><td>Rate multiplier</td><td>Whether a different rate applies, for example overtime or night work under your contract terms.</td></tr><tr><td>Site and client</td><td>Where the work was done and for whom.</td></tr><tr><td>Equipment serial</td><td>Which instrument was used.</td></tr><tr><td>Approval</td><td>Whether a supervisor has checked and approved the entry.</td></tr></tbody></table><p>That is more than generic timesheet software asks for, but each field removes a question later. The accounts team no longer asks the crew lead which days were travel. The client's reviewer can see that standby was logged as standby, not hidden in inspection. The QA manager can see which method each technician worked on, on which site.</p><p>Hours are logged against the job in the <a href=\"/erp/apps/project\">Project app</a>, so the timesheet, the job's client PO and contract, and its scope all line up. When the invoice is raised, the hours are already tied to the right PO.</p><p>How entries are made in practice, whether by each technician, by the crew lead for the whole crew, or by the office from client-signed sheets during a transition period, is agreed during implementation.</p><h2>Work types: inspection, travel, standby and setup</h2><p>NDT contracts rarely pay one flat rate for every hour. Separating time by work type is what lets you bill each kind of hour correctly and see where the day actually went.</p><h3>Inspection</h3><p>Hands-on testing: scanning welds, shooting radiographs, applying penetrant, taking thickness readings. This is the core billable time and the hours clients expect to see.</p><h3>Travel</h3><p>Mobilising to site, driving between sites, flights to remote jobs. Many contracts treat travel differently from inspection time, and some do not pay for it at all. Logging it separately means you bill it where the contract allows and still see what it costs you where it does not.</p><h3>Standby</h3><p>The crew is on site and ready, but the permit has not been issued, the scaffolding is not up, or the client's operations team has not released the line. Standby is one of the easiest sources of revenue for an NDT company to lose, because it is easy to forget and awkward to raise at invoice time. Recording it as it happens, with the site and client, gives you the record you need to charge it where your contract allows.</p><h3>Setup</h3><p>Instrument checks on site, PAUT setup and focal law checks, film preparation, surface preparation. Setup is real work that is often under-reported because technicians see it as part of the job rather than as time.</p><p>With the four types separated, the operations manager can also see patterns: a client whose jobs always carry heavy standby, or a site where travel eats half the week. That is useful information when you next quote the same client.</p><h2>Billable flag and rate multiplier</h2><p>Not every hour is billable, and not every billable hour is billed at the same rate. Atlantis NDT ERP handles both on the timesheet line itself.</p><p>The <strong>billable flag</strong> says whether the client pays for this time. Internal training, workshop maintenance, a re-inspection caused by your own error, or travel the contract does not cover can all be logged but marked non-billable. The hours still count for payroll and for understanding cost; they just do not appear on the invoice.</p><p>The <strong>rate multiplier</strong> covers time that is billable at a different rate. Typical NDT examples, depending on your contract terms, are overtime beyond a standard day, weekend or public holiday work, and night shifts during a shutdown. The multiplier is recorded on the line, so billing applies it instead of an accounts clerk trying to work it out from a handwritten note.</p><p>This matters most during turnarounds and shutdowns. Crews work long, irregular hours; days blur together; and at the end the client receives a large invoice they will check line by line. If the hours, work types and multipliers are recorded as the work happens and approved by your supervisor, the invoice is easier to defend and quicker to get paid.</p><p>The actual multiplier values and the rules for when each applies come from your contracts and are set up with you during implementation. The ERP does not decide your commercial terms; it records them consistently so they are applied the same way every time.</p><h2>Certificate validity warnings: no unqualified hours slip through</h2><p>One of the most uncomfortable discoveries in NDT is finding, after the job, that a technician's certification for the method they were working on had expired. The work may need repeating, the reports may be questioned, and the client's trust takes a hit.</p><p>Atlantis NDT ERP connects Timesheets to the <a href=\"/erp/apps/certificates\">Certificates app</a>. When hours are logged, the system warns if the technician's certificate is not valid. The Certificates app holds each technician's scheme (SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP or other), level, method, certifying body and issue, expiry and renewal dates, and works out the status automatically: active, expiring soon within 90 days, expired or revoked.</p><p>The timesheet warning is the last line of defence. The earlier ones are:</p><ul><li>Daily checks that create warning tasks 90 days before a cert or vision test expires.</li><li>Configurable email alerts to the people you choose, with look-ahead days and resend intervals.</li><li>Expiring Soon and Expired menus for the QA manager or Level III.</li><li>Dashboard counts of certs expiring and expired.</li></ul><p>With those in place, a warning at the timesheet stage should be rare. When it does appear, it appears while the job is still live, which is when you can do something about it: swap the technician, reassign the method, or correct the cert record if it was simply out of date.</p><p>For the Level III, this is practical evidence that the company's written practice is being applied in the field, not only in the QA office.</p><h2>Equipment serial numbers on the timesheet</h2><p>NDT equipment is expensive and often billed to clients as a separate line: a PAUT set, a TOFD scanner, a crawler, an eddy current instrument. Yet many companies have no reliable record of which instrument was used on which job on which day.</p><p>The equipment serial field on each timesheet entry closes that gap. When a technician logs hours of UT on a site, the entry records the serial number of the flaw detector used. That does three useful things:</p><ol><li><strong>Billing.</strong> Equipment charges can be based on recorded use rather than a guess. NDT invoice lines in the Invoicing app can carry the equipment serial, technician, method, rate type and days or hours, with subtotals for labour, equipment and consumables.</li><li><strong>Traceability.</strong> If a calibration check later shows that an instrument was out of tolerance, you can filter timesheets by its serial to find the jobs it was used on and the reports that may need review.</li><li><strong>Usage history.</strong> Over time, you build a record of which instruments are used heavily and which sit in stores, which helps when deciding whether to buy, rent or retire kit.</li></ol><p>The equipment itself is managed in Asset Management: serial number, type, assigned person, condition, lifecycle state, calibration records and certificate register, and issue and return with approvals. Team Assignments blocks double-booking of the same serial and warns if an assigned instrument is out of calibration. The timesheet adds the day-by-day record of actual use.</p><h2>Approval before anything is billed</h2><p>Timesheets feed the invoice and payroll, so they need checking before they leave the building. Each entry in Atlantis NDT ERP carries an approval, so a supervisor or crew lead confirms the hours before they are used.</p><p>A typical approval routine in an NDT company looks like this:</p><ol><li>Technicians or the crew lead log hours daily against the job and task, with work type, method, site, equipment serial and billable flag.</li><li>The crew lead or site supervisor reviews the entries, checking work types and standby against the site diary and any client-signed sheet.</li><li>The operations manager approves, paying attention to rate multipliers and any cert warnings.</li><li>Approved billable hours go to billing; non-billable hours stay visible for cost and payroll.</li></ol><p>Approving daily or weekly, rather than at the end of a long job, catches mistakes while people still remember what happened. It also means the invoice is ready soon after the job closes, instead of waiting for a pile of paper sheets to be collected and typed.</p><p>Some clients require their own representative to sign timesheets on site. That remains your process with the client; the ERP holds your approved record, and the client-signed sheets can be attached to the job for reference. Who approves at each level is set during implementation to match your structure.</p><h2>From timesheet to invoice and dashboard</h2><p>The reason to capture all this detail is what happens next. In Atlantis NDT ERP, billable timesheet hours, with their billable flag and rate multiplier, feed billing in the <a href=\"/erp/apps/invoicing\">Invoicing app</a>.</p><p>NDT invoices carry the project, job or PO number, site, invoice type and industry sector, and split subtotals for labour, equipment and consumables. Lines can show cost centre, method, equipment serial, technician, rate type and days or hours. That is the level of detail large operators and EPCs tend to ask for, and it comes straight from the timesheet rather than being rebuilt by hand. Taxes are configured per country during implementation, and payments and reminders use standard Odoo features.</p><p>The same data flows into the financial dashboard: revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, bills and expenses, with a 12-month view. When timesheets are complete and approved on time, those figures are current rather than a month behind.</p><p>Timesheets also connect to the rest of the field picture. Team Assignments shows each technician's utilisation and next available date. Time Off feeds the availability calendar. Expenses captures per diems and field costs that can be re-billed to jobs. Reports themselves are produced in the NDT Reports app, and if your clients want results on a 3D model of their asset, our companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> works alongside the ERP.</p><p>The effect is one chain from the hour worked on site to the line on the client's invoice, without anybody re-typing it along the way.</p><h2>Who uses Timesheets</h2><ul><li><strong>Technicians</strong> log their hours, method, work type and equipment against the job, and see a warning if their cert is not valid.</li><li><strong>Crew leads and site supervisors</strong> check entries against the site diary and approve them.</li><li><strong>Operations managers</strong> review standby, travel and multipliers, and see which jobs are running over.</li><li><strong>QA manager or Level III</strong> watch for cert warnings and use method records as evidence of the written practice working in the field.</li><li><strong>Accounts</strong> invoice from approved hours instead of paper sheets, and use non-billable hours for cost and payroll.</li><li><strong>Owners</strong> see the result in the financial dashboard and in the balance of billable against non-billable time.</li></ul><p>Access rights, so that technicians see their own entries while supervisors see their crews, are set up during implementation.</p><h2>Setting up Timesheets</h2><p>Atlantis NDT deploys and configures the ERP. For Timesheets, the main work is:</p><ol><li><strong>Work types and methods.</strong> Confirm the work types and the methods your company offers.</li><li><strong>Rate multipliers.</strong> Map your contract terms for overtime, weekends and night work to multiplier values.</li><li><strong>Approval chain.</strong> Decide who logs hours, who checks them and who approves.</li><li><strong>Certificates and equipment.</strong> Load technician certs and instrument serial numbers so warnings and equipment fields work from day one.</li><li><strong>Billing link.</strong> Configure how approved hours flow into invoices, including taxes for your country.</li><li><strong>Training.</strong> Short sessions for technicians, supervisors and accounts.</li></ol><p>Timesheets usually goes live together with Project, Certificates and Invoicing. See all <a href=\"/erp/apps\">ERP apps</a> to plan your rollout, or <a href=\"/contact?service=erp&amp;subject=Timesheets%20demo\">book a Timesheets demo</a> to see NDT timesheet entries, warnings and billing in action.</p><h2>Frequently asked questions</h2><h3>What work types can technicians log?</h3><p>Inspection, travel, standby and setup. Each entry also records method, billable flag, rate multiplier, site, client, equipment serial and approval.</p><h3>Does the system stop a technician with an expired cert from logging hours?</h3><p>It warns when the technician's certificate is not valid, so the supervisor can act while the job is live. Earlier warnings come from daily expiry checks, email alerts and the Certificates app's Expiring Soon and Expired menus.</p><h3>Can we bill standby and overtime?</h3><p>Yes, where your contract allows. Standby is a work type of its own, and a rate multiplier on each line handles overtime, weekend or night rates as you define them.</p><h3>How do timesheet hours reach the invoice?</h3><p>Billable hours feed billing in the Invoicing app, where lines can show method, technician, equipment serial, rate type and days or hours.</p><h3>Can the crew lead log hours for the whole crew?</h3><p>Yes, if that suits your company. Who logs and who approves is agreed during implementation.</p><h3>Can we still use client-signed paper timesheets?</h3><p>Yes. Many clients require them. Your approved ERP record sits alongside, and the signed sheet can be attached to the job for reference.</p><h3>How is Timesheets priced?</h3><p>Atlantis NDT ERP is quote on request, based on the apps and customization you need, and designed to be affordable for NDT companies of any size.</p><h2>Bill every hour you worked, and prove who worked it</h2><p>If your timesheets arrive as photos of paper at the end of a job, if standby goes unbilled and if nobody checks certs when hours are logged, the Timesheets app fixes all three in the same step. Your technicians log once; billing, compliance and your dashboard all use the same record.</p><p><a href=\"/contact?service=erp&amp;subject=Timesheets%20quote\">Request a quote for Atlantis NDT ERP</a> or <a href=\"/contact?service=erp&amp;subject=Timesheets%20demo\">book a demo</a> and we will walk through your current timesheet process with you.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Timesheets%20demo\">Send an enquiry about Timesheets</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/maintenance","publishedAt":"2026-09-27","title":"Maintenance App for NDT Companies | Atlantis NDT","description":"Plan preventive and corrective maintenance for NDT instruments, vehicles and site kit in Atlantis NDT ERP. Book a demo or request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Maintenance App for NDT Companies: Instruments, Vehicles and Site Equipment</h1>\n<p>Preventive and corrective maintenance requests for instruments, vehicles and site equipment. <a href=\"/contact?service=erp&amp;subject=Maintenance%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>What the Maintenance app does for an NDT company</h2><p>An NDT company runs on kit. Flaw detectors, phased array units, eddy current instruments, MT yokes, UV lamps, film processors, crawlers, compressors, generators, lighting towers, site cabins and the vans that carry all of it from one job to the next. When any of that fails at the wrong moment, a crew stands idle on a client's site and the day's billing goes with it.</p><p>The Maintenance app in Atlantis NDT ERP is where your team raises, plans and closes maintenance work on that equipment. It is the standard Odoo Maintenance app, set up by Atlantis NDT for the way inspection companies actually work: equipment grouped into categories a technician recognises, maintenance teams that match your workshop and your outside contractors, and request stages your coordinator can read at a glance.</p><p>Two kinds of work live here. Preventive requests are the routine jobs you know are coming: a generator service after a shutdown, a crawler's cables and wheels checked between pipeline jobs, a van booked in for its service before the busy season. Corrective requests are the ones nobody planned: a cracked probe cable, a battery pack that no longer lasts a shift, a van with a warning light on the way to site.</p><p>Calibration is deliberately kept out of this app. Calibration certificates, due dates, labs and pass/fail results belong in <a href=\"/erp/apps/asset-management\">Asset Management</a>, where each instrument's serial number already carries its full history. The Maintenance app runs the request workflow; Asset Management holds the instrument record. That split is explained in more detail further down, because getting it right is what stops people entering the same thing twice.</p><h2>The problems it is meant to stop</h2><p>Most NDT companies don't lack good technicians. They lack a single place where equipment problems get written down. The usual pattern looks something like this:</p><ul><li>A technician comes back from a turnaround and mentions in passing that the UT set's battery barely lasts half a shift. Nobody writes it down. The same unit goes out again on Monday.</li><li>The crawler was due a service after the last pipeline spread, but the person who kept that in their head has left the company.</li><li>A generator on a remote site gets serviced by a local contractor, and the only record is a phone photo of a handwritten job card.</li><li>The workshop has three repairs queued, the operations manager thinks there is one, and a job gets promised with kit that is on the bench in pieces.</li><li>An auditor asks how you maintain site equipment, and the answer is a spreadsheet last touched before the previous audit.</li></ul><p>None of these are dramatic failures. They are small gaps that add up to idle crews, last-minute hire of replacement kit, awkward calls with clients and weak answers at audit time.</p><p>The Maintenance app closes those gaps by making every request visible to everyone who needs to see it. A technician, a stores person or a coordinator raises the request against the right piece of equipment. The request sits on a board where the workshop and operations both see it. It moves through stages until it is done, and when it is done it stays on the equipment's history for the next person who asks.</p><p>It is not complicated software, and that is the point. If raising a request takes longer than sending a message, people will keep sending messages.</p><h2>Setting up your equipment, categories and teams</h2><p>The app starts with a list of equipment. For an NDT company that list normally covers three groups:</p><ul><li><strong>Inspection instruments and accessories</strong>: UT flaw detectors and thickness gauges, phased array and TOFD units, eddy current instruments, MT yokes and benches, UV lamps and light meters, PMI analysers, hardness testers, holiday detectors.</li><li><strong>Vehicles and transport</strong>: site vans, pickups, trailers, and any vehicle set aside for carrying radiography equipment.</li><li><strong>Site and workshop equipment</strong>: generators, compressors, crawlers, film processors and viewers, darkroom units, site cabins, lighting towers and the access equipment you own.</li></ul><p>Each piece of equipment belongs to a category, and each category can be tied to a maintenance team. A team is simply the group of people who pick up that kind of work. Your instrument workshop might be one team. Vehicle work handled by an outside garage might sit with a second team, with your fleet coordinator as the responsible person. Site equipment could go to a small base team or to the base supervisor.</p><p>Equipment records carry a responsible person, where the item is used, the vendor, model and serial number, warranty information and free notes. For instruments that also live in Asset Management, the serial number is the common thread, so a technician looking at a maintenance request and a stores person looking at the instrument record are talking about the same box.</p><p>During implementation Atlantis NDT works through your equipment list with you, agrees categories that make sense to the people who will use them, and loads the initial data. It is also a good moment to find the kit nobody has seen in a while.</p><h2>Preventive maintenance: routine work that actually happens</h2><p>Preventive requests are where the app earns its place. A preventive request can be set to repeat on a fixed interval, so when one service is done the next one is already waiting with its date. Nobody has to remember that the compressor is due again in three months.</p><p>Typical preventive schedules for an NDT company include:</p><ul><li>Regular servicing of generators and compressors used on site.</li><li>Servicing crawlers and checking their cables between projects.</li><li>Routine work in the darkroom: processor cleaning, chemistry changes, viewer checks.</li><li>Routine inspection of MT yokes, prods and cables, and of UV lamps against what your procedures require.</li><li>Vehicle servicing on a set interval.</li><li>Checks on radiography equipment required by your radiation safety programme. Your programme and your regulator define what those checks are and how often; the app keeps them coming round on time and records that they were done.</li></ul><p>Each request has a scheduled date, an expected duration, a responsible person and a priority. The maintenance calendar view shows what is due and when, which matters most before a busy period. If a shutdown starts in three weeks, you can see what should be serviced before crews mobilise, and pull it forward instead of discovering the problem on day two of the outage.</p><p>Preventive work on inspection instruments has a nuance. Some of it is maintenance (cleaning, battery replacement, firmware updates, probe replacement) and some of it is calibration or verification. The Maintenance app is a good place to schedule the job. The detailed record of what was done to the instrument, including its condition before and after, belongs in the instrument's maintenance log in Asset Management, and calibration results belong in its calibration records. Your implementation agrees which team records what, so the same work is never keyed in two places.</p><h2>Corrective requests: when something breaks on a job</h2><p>Corrective maintenance is the unplanned kind, and in NDT it usually starts on a client's site. A probe cable gets crushed under a scaffold board. A yoke stops switching. A generator won't start on a cold morning. The technician's first job is to keep the inspection going with whatever spare is available. The second job, which is usually forgotten, is to tell someone.</p><p>The Maintenance app makes that second step short. Because Atlantis NDT ERP runs in a web browser, a technician or site supervisor can open a request from a phone: pick the equipment, describe the fault, add a photo if it helps, and submit. The request lands in the New stage on the workshop's board.</p><p>From there the flow is simple:</p><ol><li><strong>New request</strong>: the workshop or equipment coordinator sees it, sets the priority and assigns a person.</li><li><strong>In progress</strong>: the item is being looked at, repaired in-house or sent to the manufacturer or a repair vendor.</li><li><strong>Repaired</strong>: the work is done and the item can go back into service.</li><li><strong>Scrap</strong>: the item is beyond economic repair and is taken out of use.</li></ol><p>Stages can be renamed or extended during implementation if your workshop needs, for example, a separate stage for items waiting on parts or away at the manufacturer.</p><p>Every request stays on the equipment record. Over time that history answers the questions that matter: which instruments keep coming back, which vehicle is costing more time off the road than it is worth, whether a particular model of crawler is suited to your work at all. Those are conversations owners and operations managers usually have from memory. With the history in one place, they can have them from the record.</p><p>If an instrument is going to be out of service for a while, its lifecycle status in Asset Management (for example, in repair) tells operations it is not available for the next job.</p><h2>Maintenance and calibration: where each record lives</h2><p>The most common confusion when NDT companies set up an ERP is deciding where equipment information belongs. Atlantis NDT ERP keeps a clear split so each record has one home:</p><table><thead><tr><th>Record</th><th>Where it lives</th><th>Why</th></tr></thead><tbody><tr><td>Preventive and corrective maintenance requests</td><td>Maintenance app</td><td>Request workflow, teams, scheduling and the maintenance calendar</td></tr><tr><td>Instrument maintenance log: cleaning, repair, firmware update, probe replacement, condition before and after</td><td>Asset Management</td><td>Stays with the instrument's serial number and its full lifecycle</td></tr><tr><td>Calibration records: provider, certificate number, standard, range, uncertainty, accredited lab flag, result, next due date</td><td>Asset Management</td><td>Calibration certificate register with valid, expiring and expired status and expiry alerts</td></tr><tr><td>Instrument lifecycle status: active, in calibration, in repair, rented out, retired</td><td>Asset Management</td><td>Tells operations what is available to issue</td></tr><tr><td>Vehicle purpose, whether it can carry radioactive sources, transport licence number and expiry</td><td>Fleet</td><td>Vehicle-specific records and project assignments</td></tr><tr><td>Warning when assigned equipment is out of calibration</td><td>Team Assignments</td><td>Checked at the point of dispatch</td></tr></tbody></table><p>In practice this means the Maintenance app is the front door for anything that needs doing, while the specialist records stay where the specialist apps can use them. A workshop technician closes a request in Maintenance; the equipment controller updates the instrument's log and status in Asset Management. For vehicles and site equipment that are not inspection instruments, the Maintenance app's own history is usually enough.</p><p>If your company prefers a different split, for example keeping all instrument work only in Asset Management and using Maintenance purely for vehicles and site equipment, that is agreed during implementation. What matters is that everyone knows the rule.</p><h2>Who uses it day to day</h2><p>The Maintenance app is used by more people than most NDT companies expect, but each of them only needs a small part of it.</p><ul><li><strong>Field technicians</strong> raise corrective requests from site when something fails or starts behaving oddly. They don't need training beyond a few minutes on how to find the equipment and describe the fault.</li><li><strong>Workshop or equipment technicians</strong> work the board: pick up requests, update stages, record what was done and close them out.</li><li><strong>Equipment controllers and stores staff</strong> watch for requests on instruments that are due to be issued, and keep Asset Management status in line with what the workshop is doing.</li><li><strong>Operations managers and coordinators</strong> look at the maintenance calendar before committing kit to a job, and check open requests before a big mobilisation.</li><li><strong>Fleet coordinators</strong> handle vehicle servicing requests and bookings with outside garages.</li><li><strong>QA/QC managers and Level IIIs</strong> use the history when a client audit or internal audit asks how equipment is maintained, and when deciding whether a repeatedly failing item should stay in service.</li><li><strong>Owners and general managers</strong> look at the history when deciding whether to repair, replace or retire expensive kit.</li></ul><p>Access rights are set per role. A technician can raise and follow requests without seeing things they don't need, while the workshop and managers get the full view. Notifications go through the normal Odoo channels, so the person assigned to a request sees it in their inbox and activity list rather than having to go looking.</p><h2>How it connects to the rest of Atlantis NDT ERP</h2><p>The Maintenance app is not meant to stand alone. Its value comes from sitting next to the apps that decide where equipment goes and what it costs.</p><ul><li><strong>Asset Management</strong> holds every instrument by serial number, with its issue and return records, reservations, maintenance log and calibration certificates. Maintenance requests and instrument records share the same serial numbers.</li><li><strong><a href=\"/erp/apps/team-assignments\">Team Assignments</a></strong> blocks double-booking of equipment serial numbers across jobs and warns when assigned equipment is out of calibration. Keeping maintenance status current means dispatch decisions are made on real availability.</li><li><strong><a href=\"/erp/apps/fleet\">Fleet</a></strong> holds vehicle-specific data, including whether a vehicle can carry radioactive sources and its transport licence details. Maintenance requests for vehicles sit alongside that record.</li><li><strong>Purchase</strong> records vendors by type (OEM, dealer, calibration lab) and lets order lines be linked to a specific equipment serial, so the spare probe or repair bought for a unit is traceable to it.</li><li><strong>Calendar and To-do</strong> give managers one place to see scheduled maintenance next to meetings and their own follow-ups.</li><li><strong>Dashboards</strong> show NDT equipment KPIs such as calibration due and overdue, and issued equipment overdue for return.</li></ul><p>Atlantis NDT ERP as a whole is described on the <a href=\"/erp\">NDT ERP overview</a>. If you want to see how these apps fit together on your own equipment list, <a href=\"/contact?service=erp&amp;subject=Maintenance%20app%20demo\">book a Maintenance app demo</a> and bring a sample of your kit register.</p><h2>What implementation looks like</h2><p>Atlantis NDT sets up and deploys the ERP for you. For the Maintenance app, implementation usually runs through these steps:</p><ol><li><strong>Equipment review.</strong> We go through your current registers, spreadsheets and workshop notes and agree what goes into Maintenance, what goes into Asset Management and what goes into Fleet.</li><li><strong>Categories and teams.</strong> Categories are named in your technicians' language, and each is tied to the right maintenance team and responsible person.</li><li><strong>Preventive schedules.</strong> Recurring preventive requests are created for the equipment that needs them, with intervals taken from your manufacturers' guidance, your procedures and your radiation safety programme.</li><li><strong>Stages and rules.</strong> Request stages are confirmed or adjusted, and access rights are set for technicians, workshop, managers and stores.</li><li><strong>Data load.</strong> Your equipment list is imported, including serial numbers that match the instrument records in Asset Management.</li><li><strong>Training.</strong> Short sessions for each role: raising a request from a phone, working the board, reading the calendar.</li><li><strong>Go-live and support.</strong> We stay with you through the first weeks while the habit forms.</li></ol><p>Because the product is fully customizable, anything specific to your operation, such as extra fields on requests, a different set of stages or reports your QA manager wants for audits, is scoped and agreed with you before work starts. Pricing depends on that scope, so it is quote on request. <a href=\"/contact?service=erp&amp;subject=Maintenance%20app%20quote\">Request a quote for the Maintenance app</a> and tell us roughly how much equipment and how many locations you run.</p><h2>What the Maintenance app is not</h2><p>It helps to be clear about scope so nobody buys the wrong thing.</p><p>The Maintenance app is for your own company's equipment: the instruments, vehicles and site kit you own or rent and use to deliver inspections. It is not a system for managing your clients' plant assets, their inspection intervals or their integrity programmes. That work belongs to the asset owner and their own systems.</p><p>It is not a calibration laboratory system either. Calibration results, certificates and due dates are recorded in Asset Management, but the calibration itself is done by your provider or your own qualified staff according to your procedures.</p><p>It does not make decisions for you. It will not decide that an instrument is fit for use; your equipment controller and Level III do that. It records what was requested, what was done, by whom and when, so that decision is made on evidence rather than memory.</p><p>And it does not replace your radiation safety programme. Where your regulator requires specific checks on radiography equipment, the app can schedule and record them, but the programme itself, and the responsibility for it, stay with your Radiation Safety Officer.</p><p>Within that scope, it does one job well: making sure equipment problems get written down, picked up and closed, and that the history is there when someone needs it.</p><h2>Frequently asked questions</h2><h3>Is the Maintenance app the same as calibration tracking?</h3><p>No. The Maintenance app handles preventive and corrective requests. Calibration records, calibration certificates and due dates are held in Asset Management against each instrument's serial number, with expiry alerts. The two share serial numbers, so they work together without duplicate entry.</p><h3>Can technicians raise requests from site?</h3><p>Yes. Atlantis NDT ERP runs in a web browser, so a technician with a phone and a signal can open a request against the right equipment, describe the fault and attach a photo. The request appears straight away on the workshop's board.</p><h3>Can it handle vehicles as well as instruments?</h3><p>Yes. Vehicles can be set up as equipment with their own category and maintenance team, so servicing and repairs are requested and tracked in the same way. Vehicle-specific details, such as whether a vehicle can carry radioactive sources and its transport licence, are kept in the Fleet app.</p><h3>How are preventive schedules set?</h3><p>Preventive requests repeat on an interval you choose. During implementation the intervals are taken from your manufacturers' guidance, your procedures and your radiation safety programme, and loaded for each item that needs them.</p><h3>Will it stop out-of-service kit being sent to a job?</h3><p>It makes out-of-service kit visible. Instrument status in Asset Management (for example, in repair) shows what is not available, and Team Assignments warns when assigned equipment is out of calibration. Keeping requests and statuses current is what makes those checks useful.</p><h3>Can we add our own fields or stages?</h3><p>Yes. The ERP is fully customizable. Extra fields, stages or reports are agreed as part of the customization scope before implementation starts.</p><h3>How much does it cost?</h3><p>Atlantis NDT ERP is priced to be affordable for NDT companies of any size, but every setup is different, so pricing is quote on request after a short conversation about your equipment and locations.</p><h2>See it with your own equipment list</h2><p>The fastest way to judge the Maintenance app is to see your own kit in it: your yokes, your crawlers, your vans, your generators, with the requests your workshop actually deals with. Send us a sample of your equipment register and a few recent breakdowns, and we will walk you through how they would look in Atlantis NDT ERP, alongside Asset Management, Fleet and Team Assignments.</p><p>Affordable. Accessible. Fully customizable. <a href=\"/contact?service=erp&amp;subject=Maintenance%20app%20demo\">Book a demo of the Maintenance app</a>, or browse the other <a href=\"/erp/apps\">NDT ERP apps</a> first.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Maintenance%20demo\">Send an enquiry about Maintenance</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/fleet","publishedAt":"2026-09-27","title":"Fleet Management for NDT Companies | Atlantis NDT","description":"Track NDT vehicles, source-carrying vans, transport licences, drivers and mileage by project in Atlantis NDT ERP. Book a demo or request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Fleet Management for NDT Companies: Vehicles, Drivers and Source-Carrying Vans</h1>\n<p>Vehicles, drivers and service records for field crews. <a href=\"/contact?service=erp&amp;subject=Fleet%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why an NDT company needs proper fleet records</h2><p>For most inspection companies, the vehicle is part of the job. A UT crew's van carries the flaw detectors, probes, couplant and calibration blocks. A radiography truck may carry exposure devices, film, a darkroom and signage. A pipeline crew might live out of pickups for weeks. When a vehicle is off the road, unlicensed for the load it carries, or simply not where the coordinator thought it was, the inspection doesn't happen.</p><p>Yet vehicle records in many NDT companies are scattered: registration papers in a folder, insurance renewal in the accountant's email, mileage on a clipboard in the cab, and knowledge of which van is cleared for radiography work held by one or two senior people.</p><p>The Fleet app in Atlantis NDT ERP brings those records together. It is the standard Odoo Fleet app with fields added for NDT work: the vehicle's purpose, whether it can carry radioactive sources, its transport licence number and expiry, and assignments of the vehicle to a project and driver with dates and mileage.</p><p>That combination matters. A general-purpose fleet tool can tell you when a van's insurance is due. It can't tell your coordinator, at the moment of planning a radiography job, which vehicles are set up and licensed to carry the source. The Fleet app in Atlantis NDT ERP holds both kinds of information in one place, on the same system where you plan jobs, dispatch crews and invoice clients.</p><p>This page explains what the app records, how an NDT company uses it day to day, who works in it and how it is set up during implementation.</p><h2>The problems it is meant to stop</h2><p>Fleet problems in NDT rarely look like fleet problems. They show up as operations problems:</p><ul><li>A radiography crew is dispatched in a vehicle that isn't the one set up for source transport, because the usual truck was in the garage and nobody checked.</li><li>A transport licence or permit on a vehicle lapses, and it is noticed only when someone asks for the paperwork at a site gate.</li><li>Two coordinators promise the same pickup to two different crews for the same week.</li><li>A client queries mileage on an invoice, and the only evidence is a technician's recollection.</li><li>Insurance, registration or leasing contracts roll over quietly, or worse, don't roll over at all.</li><li>A vehicle has been used on four projects in a month, and nobody can say how many kilometres each project actually used.</li></ul><p>Each of these is an avoidable cost: a delayed start, a refused site entry, a disputed invoice line, a scramble for a hire vehicle. They happen because vehicle information lives in too many places and none of them are connected to the job plan.</p><p>The Fleet app doesn't solve this with anything clever. It solves it by giving every vehicle one record that everyone can see, with the NDT-specific facts on it, and by recording who had the vehicle, for which project, over which dates and for how many kilometres or miles.</p><h2>What each vehicle record holds</h2><p>Every vehicle in the Fleet app has a single record. The standard Odoo fields cover the basics:</p><ul><li>Make, model, registration plate and chassis number.</li><li>Current driver and future driver.</li><li>Odometer readings over time.</li><li>Contracts such as leasing, insurance or rental, with start and end dates.</li><li>Service history.</li><li>Tags and status so you can see which vehicles are active, in the garage or being returned.</li></ul><p>On top of that, Atlantis NDT ERP adds the fields an inspection company actually needs:</p><table><thead><tr><th>Field</th><th>What it is for</th></tr></thead><tbody><tr><td>Vehicle purpose</td><td>What the vehicle is used for, for example general crew transport, equipment transport or radiography work, so coordinators pick the right one.</td></tr><tr><td>Can carry radioactive sources</td><td>A clear yes or no on each vehicle, so nobody has to ask which truck is set up for source transport.</td></tr><tr><td>Transport licence number</td><td>The licence or permit reference that applies to that vehicle's use.</td></tr><tr><td>Transport licence expiry</td><td>The date the licence runs out, visible on the record and in list views.</td></tr><tr><td>Project and driver assignments</td><td>Which project and driver had the vehicle, between which dates, with mileage recorded.</td></tr></tbody></table><p>Because all of this sits on one record, list views can be filtered and grouped. A coordinator can pull up every vehicle that can carry sources, sorted by licence expiry, in a couple of clicks. A manager can see all vehicles assigned to a given project. An accountant can see contracts due to end in the next quarter.</p><h2>Vehicles that carry radioactive sources</h2><p>Radiography is the part of NDT where the vehicle carries real regulatory weight. Depending on the country, carrying an industrial radiography source involves radiation protection regulations, dangerous goods transport rules, licence conditions from the national regulator and your own radiation safety programme. The details differ from one jurisdiction to the next, and they are the responsibility of your Radiation Safety Officer and management.</p><p>What the Fleet app does is make the relevant facts about each vehicle impossible to miss:</p><ul><li>Every vehicle carries a flag saying whether it can carry radioactive sources.</li><li>The transport licence number and its expiry date are on the vehicle record, not in a separate folder.</li><li>Assignments show which driver had the vehicle, on which project, and over which dates.</li></ul><p>When a coordinator is planning a radiography job, they filter for vehicles that can carry sources and see at once which are available and whose licence is current. When an auditor or client asks which vehicle was used on a particular job and who drove it, the assignment history answers the question directly.</p><p>It is worth being clear about the limits. The app records these facts; it does not make a vehicle compliant, and it does not replace the checks your radiation safety programme requires before a source is moved. What it removes is the guesswork: the moment where someone assumes a vehicle is the right one because it usually is.</p><p>If you want alerts ahead of licence expiry, the way those are raised, for example as scheduled activities for the fleet coordinator or entries on a manager's To-do list, is configured during implementation to fit how your company works.</p><h2>Assigning vehicles to projects and drivers</h2><p>The assignment record is the part of the Fleet app that NDT companies tend to value most. Each assignment links a vehicle to a project and a driver, with start and end dates and mileage.</p><p>That sounds simple, and it is. But it changes a few things:</p><ul><li><strong>Planning.</strong> Before promising a vehicle to a crew, the coordinator can see what it is already assigned to and when that assignment ends.</li><li><strong>Accountability.</strong> If a vehicle comes back damaged, dirty or with a warning light, the record shows who had it and on which job.</li><li><strong>Project costing.</strong> Mileage per assignment shows how much vehicle use a project really consumed, which helps when you price the next similar job.</li><li><strong>Client queries.</strong> If a client asks about travel on an invoice, you have dated, project-specific mileage to point to.</li></ul><p>Vehicle assignments sit alongside crew and equipment planning in <a href=\"/erp/apps/team-assignments\">Team Assignments</a>, where jobs move from planned to dispatched, in field, submitted and closed, and where double-booking of technicians and equipment serial numbers is blocked. The Fleet app keeps the vehicle side of the same picture: the crew, the kit and the van that took them there.</p><p>For companies running long projects, such as pipeline spreads or extended shutdowns, assignments can run for weeks, with the driver changed as crews rotate. Each rotation is its own record, so the history stays clear even when several people have driven the same vehicle on the same project.</p><h2>Odometers, services and contracts</h2><p>The standard parts of the Fleet app do the routine work that keeps vehicles legal and on the road.</p><p><strong>Odometer readings</strong> are logged against the vehicle over time. Together with mileage on assignments, they give you a reliable picture of how hard each vehicle is working and when it is due its next service.</p><p><strong>Service records</strong> keep a history of servicing and repairs: what was done, when, and by which vendor. For planned servicing and requests raised from site, many NDT companies also use the <a href=\"/erp/apps/maintenance\">Maintenance app</a>, where vehicles can be set up with their own maintenance team and preventive schedule. The two work together: Maintenance runs the request workflow, and the Fleet record keeps the vehicle's history and NDT-specific details.</p><p><strong>Contracts</strong> cover leasing, insurance, rental and similar agreements with their start and end dates. Standard Odoo Fleet raises reminders to the responsible person as contracts approach their end, so renewals are a decision rather than a surprise.</p><p>Costs can be recorded against vehicles as well, so owners can see what each vehicle is costing to run and compare it with how much it is used. For a small fleet that is a sanity check. For a larger one, it is the information you need to decide whether to buy, lease or hire.</p><p>None of this is specific to NDT, and it doesn't need to be. What makes it useful to an inspection company is that it lives on the same system as the jobs, crews and invoices, so vehicle facts are there when operational decisions are made.</p><h2>Travel, mileage and billing</h2><p>Travel is a real part of NDT work, and clients are increasingly particular about how it is charged. Atlantis NDT ERP gives you several pieces that fit together here.</p><ul><li><strong>Fleet assignments</strong> record mileage per vehicle, per project and per driver over given dates.</li><li><strong>Timesheets</strong> let technicians log travel as a separate work type from inspection, standby and setup, with a billable flag and rate multiplier, against a site and client.</li><li><strong>Expenses</strong> capture field costs such as fuel, tolls and per diems, which can be re-billed to jobs.</li><li><strong>Invoicing</strong> carries NDT project, job or PO number and site on the invoice header, with lines by cost centre, method, technician, rate type and days or hours, and separate subtotals for labour, equipment and consumables.</li></ul><p>How vehicle mileage turns into invoice lines depends on your contracts. Some clients pay a mileage rate, some pay a fixed mobilisation charge, some absorb travel into day rates. The Fleet app provides the recorded mileage per project; how that figure reaches the invoice is configured during implementation to match the way you bill.</p><p>What you get either way is evidence. When a client asks why travel on an invoice looks higher than expected, your billing team can open the project, see which vehicles were assigned, over which dates and for what mileage, and answer with facts instead of estimates.</p><p>If you want to walk through this with your own contracts and billing rules, <a href=\"/contact?service=erp&amp;subject=Fleet%20app%20demo\">book a Fleet app demo</a> and bring a recent invoice with travel on it.</p><h2>Who uses the Fleet app</h2><ul><li><strong>Operations managers and coordinators</strong> check vehicle availability and suitability before promising a crew, and record assignments to projects and drivers.</li><li><strong>Radiation Safety Officers</strong> keep an eye on which vehicles are flagged to carry sources and whose transport licences are current.</li><li><strong>Fleet coordinators or office administrators</strong> keep registrations, contracts, insurance and service history up to date.</li><li><strong>Technicians and drivers</strong> can be asked to record odometer readings at the start and end of an assignment, depending on how your company wants to run it.</li><li><strong>Accounts and billing</strong> use assignment mileage and costs when preparing invoices and reviewing project profitability.</li><li><strong>Owners and general managers</strong> see which vehicles are earning their keep and which are candidates for replacement.</li></ul><p>Access rights are set per role during implementation, so drivers see what they need and managers see the whole fleet.</p><h2>What implementation looks like</h2><p>Atlantis NDT sets up and deploys the ERP for your company. For the Fleet app, implementation usually covers:</p><ol><li><strong>Vehicle review.</strong> We collect registrations, contracts, insurance details and licences for each vehicle, and agree how purposes are named.</li><li><strong>NDT fields.</strong> Each vehicle is marked for whether it can carry radioactive sources, and transport licence numbers and expiry dates are entered.</li><li><strong>Contracts and reminders.</strong> Leasing, insurance and rental contracts are loaded with their dates, and reminders are routed to the right person. Licence expiry follow-ups are configured to suit your process.</li><li><strong>Assignments.</strong> Current vehicle assignments to projects and drivers are recorded so history starts from day one.</li><li><strong>Links to other apps.</strong> Vehicles are set up in Maintenance where you want preventive servicing, and billing rules for travel are agreed with your accounts team.</li><li><strong>Training and go-live.</strong> Short sessions per role, then support through the first weeks.</li></ol><p>The product is fully customizable, so extra fields or views you need, for example additional documents your clients ask for at site gates, are scoped and agreed with you. Pricing depends on that scope and is quote on request. <a href=\"/contact?service=erp&amp;subject=Fleet%20app%20quote\">Request a quote for the Fleet app</a> with a rough count of vehicles and locations.</p><h2>Frequently asked questions</h2><h3>Can the Fleet app show which vehicles can carry radioactive sources?</h3><p>Yes. Every vehicle has a field recording whether it can carry radioactive sources, together with its transport licence number and expiry date. Coordinators can filter the fleet to see only those vehicles when planning radiography work.</p><h3>Does the app make our vehicles compliant with transport regulations?</h3><p>No software can do that. The app records the facts about each vehicle and who had it on which job. Compliance with radiation protection and dangerous goods transport rules remains the responsibility of your Radiation Safety Officer and management.</p><h3>Can we record which project a vehicle was used on?</h3><p>Yes. Vehicle assignments link a vehicle to a project and driver with dates and mileage, so you can see exactly how each vehicle was used across your jobs.</p><h3>Does it track vehicle location live?</h3><p>No. The Fleet app records assignments, drivers, dates, odometer readings and mileage. It is not a live vehicle tracking system.</p><h3>How does it work with the Maintenance app?</h3><p>Vehicles can be set up as equipment in Maintenance with their own team and preventive schedule. Maintenance handles requests and scheduling, while the Fleet record holds the vehicle's contracts, licences, assignments and service history.</p><h3>Can travel mileage go onto client invoices?</h3><p>Assignment mileage is recorded per project. How it appears on invoices depends on your contracts and is configured during implementation, alongside Timesheets travel entries and re-billed Expenses.</p><h3>What does it cost?</h3><p>Atlantis NDT ERP is affordable and fully customizable. Pricing depends on your scope, so it is quote on request.</p><h2>See your own fleet in it</h2><p>Bring a list of your vehicles, note which ones carry radiography equipment, and pick a recent job where travel was queried. We will show you how that job would look in Atlantis NDT ERP: the vehicle, the licence, the driver, the dates, the mileage and the invoice.</p><p>Affordable. Accessible. Fully customizable. Read more about the full <a href=\"/erp\">NDT ERP</a>, or <a href=\"/contact?service=erp&amp;subject=Fleet%20app%20demo\">book a demo of the Fleet app</a> today.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Fleet%20demo\">Send an enquiry about Fleet</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/calendar","publishedAt":"2026-09-27","title":"Calendar App for NDT Inspection Companies | Atlantis NDT","description":"Keep client meetings, audits, pre-job briefings and reminders for your NDT company in one shared calendar in Atlantis NDT ERP. Book a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Calendar App for NDT Inspection Companies</h1>\n<p>Shared schedules for jobs, audits and client meetings. <a href=\"/contact?service=erp&amp;subject=Calendar%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>What the Calendar app is for in an NDT company</h2><p>An inspection company's week is full of things that are not inspections but still decide whether inspections happen. The kick-off meeting with a refinery's QA team before a turnaround. The pre-job safety briefing with a fabrication shop's supervisor. The certification body's surveillance audit. The Level III's review session for a new procedure. The call with the calibration lab about a delayed certificate. The internal training session for trainees before their practical exam.</p><p>In many NDT companies those events are spread across personal phone calendars, email threads and a whiteboard in the office. People miss meetings because the invitation went to one person and was never passed on. Clients get double-booked. The Level III finds out about the audit the day before.</p><p>The Calendar app in Atlantis NDT ERP is the shared diary for that side of the business. It is the standard Odoo Calendar app, set up by Atlantis NDT for an NDT company: meetings with internal and external attendees, invitations and reminders, recurring events, and events linked to the records they concern, such as a CRM lead or a customer.</p><p>It is important to be clear about what it is not. The Calendar app is not where you dispatch technicians to jobs. Technician availability and job dispatch live in <a href=\"/erp/apps/team-assignments\">Team Assignments</a>, which has its own calendar view and its own rules for blocking double-bookings. The Calendar app is for meetings and events around the work. Keeping the two separate is what makes both of them readable.</p><h2>The problems it is meant to stop</h2><p>Scheduling problems in an NDT company are rarely about lack of effort. They come from information living in too many places:</p><ul><li>A client meeting is booked on the sales manager's personal calendar. The operations manager, who needs to be there to talk about crew availability, never hears about it.</li><li>The certification body confirms audit dates by email to the QA manager, who is on leave. The date is discovered a week later.</li><li>A pre-job meeting with a fabrication shop is agreed on the phone by a supervisor and never written down anywhere the office can see.</li><li>A recurring internal meeting, like a weekly operations review, lives in one person's head and quietly stops happening when they are busy.</li><li>A technician is booked into a training session on a day they are already committed to site, because the training was scheduled in one place and the job in another.</li></ul><p>Each one is small. Together, they make a company look disorganised to clients and auditors, and they waste the time of the people who are hardest to replace: Level IIIs, QA managers and senior supervisors.</p><p>The Calendar app fixes this by putting company meetings in one place that everyone with access can see, by sending proper invitations to internal and external attendees, and by tying meetings to the records they belong to. It doesn't require anyone to change how they think about their week. It just means the week is written down once, where the team can see it.</p><h2>Everyday events an NDT company puts in the calendar</h2><p>Every company will use the calendar slightly differently, but the events tend to fall into a few groups:</p><table><thead><tr><th>Event type</th><th>Typical attendees</th><th>Why it belongs in the shared calendar</th></tr></thead><tbody><tr><td>Client kick-off and scope meetings</td><td>Sales, operations manager, Level III, client QA/QC</td><td>Links to the CRM lead or customer so the history stays with the account</td></tr><tr><td>Pre-job and safety briefings</td><td>Supervisor, crew lead, client representative</td><td>Everyone in the office can see what is being agreed before mobilisation</td></tr><tr><td>Certification body and client audits</td><td>QA manager, Level III, management</td><td>Dates are visible well in advance, so preparation actually happens</td></tr><tr><td>Procedure review meetings</td><td>Level III, QA manager, senior technicians</td><td>Keeps approvals moving alongside the Procedures app workflow</td></tr><tr><td>Internal training sessions</td><td>Trainer, trainees, supervisor</td><td>Avoids booking technicians into training on days they are on site</td></tr><tr><td>Vendor and calibration lab meetings</td><td>Equipment controller, purchasing</td><td>Keeps drop-offs, collections and supplier calls visible</td></tr><tr><td>Weekly operations and management reviews</td><td>Owner, operations, finance, QA</td><td>Recurring events that keep happening without anyone rebooking them</td></tr></tbody></table><p>None of these need special fields. They need a place, a time, the right people and a link to whatever they are about. That is what the Calendar app provides.</p><h2>Invitations, attendees, reminders and recurring events</h2><p>The Calendar app handles the basics well, and for most NDT companies the basics are what was missing.</p><p><strong>Attendees and invitations.</strong> Each event can have internal attendees, who see it in their own Atlantis NDT ERP calendar, and external attendees such as client representatives or auditors, who receive an email invitation they can accept or decline. Responses are visible on the event, so you know who is actually coming.</p><p><strong>Reminders.</strong> Events can carry reminders by email or on-screen notification at intervals you choose, such as a day before and an hour before. For an audit or a client kick-off, that is often all it takes to make sure the right people turn up prepared.</p><p><strong>Recurring events.</strong> Weekly operations reviews, monthly QA meetings, quarterly management reviews and similar events can be set to repeat. They stay on the calendar without anyone having to rebook them, and a single occurrence can be moved without breaking the series.</p><p><strong>Views.</strong> Users can see their own calendar, colleagues' calendars or several people's at once, by day, week or month. An operations manager can check when the Level III and the client's QA lead are both free before proposing a meeting.</p><p><strong>Location and notes.</strong> Each event has a location, which might be a client site, your office or an online meeting link, and a description for the agenda or anything attendees need to bring, such as the latest revision of a procedure or the calibration certificates an auditor will ask for.</p><p>Simple as they are, these features replace a surprising amount of back-and-forth by email and phone.</p><h2>Connecting to Google or Outlook calendars</h2><p>Most people in an NDT company already live in Google Calendar or Outlook on their phone. Asking them to check a second calendar rarely works.</p><p>Odoo Calendar supports synchronisation with Google Calendar and Microsoft Outlook calendars. Where your company uses one of these, the connection is set up during implementation so events created in Atlantis NDT ERP appear in people's usual calendars, and events they create there can appear in the ERP. Each user connects their own account, and the details of what syncs are agreed with you as part of the setup.</p><p>This matters most for field staff and senior people. A supervisor on a shutdown is not going to log into an ERP to check tomorrow's pre-job briefing. They will look at their phone. If the briefing is there, the sync has done its job.</p><p>It also matters for people who work with clients' own calendars. A client QA lead who sends an invitation from their own system still reaches your team's usual calendar, and your office can bring the event into the ERP so it sits alongside everything else.</p><p>If your company uses a different setup, for example shared mailboxes or a mix of providers, that is discussed during implementation. We will tell you plainly what works well and what does not, rather than promising a sync that behaves badly in practice.</p><h2>Meetings linked to the records they belong to</h2><p>One of the most useful things about having the calendar inside the ERP is that meetings are not floating. They belong to something.</p><p>When someone schedules a meeting activity from a CRM lead, for example a scope call with a refinery's inspection manager, Odoo creates a calendar event linked to that lead. The meeting shows in the attendees' calendars, and it also shows on the lead's history. Anyone picking up the account later can see what meetings took place and when.</p><p>The same idea applies elsewhere in the system. Meetings can be scheduled as activities on records such as customers, projects or quotations, so the conversation about a job and the job itself stay together.</p><p>In the CRM, Atlantis NDT ERP adds NDT-specific fields such as service line, NDT service type, industry sector, site country and estimated technicians and days, along with an NDT lead score. A sales manager preparing for a meeting can open the lead from the calendar event and see all of that before walking in.</p><p>For operations, the link works the other way. A project in Atlantis NDT ERP holds the job type, site, client PO, methods, codes, scope, acceptance criteria and assigned technicians and equipment. When a pre-job meeting is linked to it, the supervisor has the job details one click from the invitation.</p><p>It is a small thing, but it is what separates a shared calendar from a company memory.</p><h2>Audits, renewals and the compliance calendar</h2><p>NDT companies live by dates: certificate expiries, calibration due dates, surveillance audits, licence renewals. Several of these are already handled by specialist apps in Atlantis NDT ERP, and the Calendar app works alongside them rather than replacing them.</p><ul><li><strong><a href=\"/erp/apps/certificates\">Certificates</a></strong> tracks technician certifications, vision tests and company certifications, with status computed automatically and warning tasks created 90 days before a technician's cert or vision test expires. Company certifications carry their own alert days, and configurable daily email alerts cover technician certs, calibration certificates and company certifications.</li><li><strong>Asset Management</strong> keeps calibration records and a calibration certificate register with valid, expiring and expired status and expiry alerts.</li><li><strong>Procedures</strong> sends notifications and reminders to approvers for pending procedure approvals.</li></ul><p>Those apps own the expiry logic. The Calendar app is where the resulting meetings and events go: the audit itself, the preparation session a week before, the meeting with the certification body, the review with the Level III once a procedure is ready to approve.</p><p>In practice, the QA manager sees an expiring company certification flagged by the Certificates app, agrees audit dates with the certification body, and puts the audit and its preparation meetings in the calendar with the right attendees and reminders. Nothing is duplicated; each piece lives where it works best.</p><h2>Who uses the Calendar app</h2><ul><li><strong>Owners and general managers</strong> run recurring management reviews and see the key client and audit meetings across the company.</li><li><strong>Sales and business development</strong> book client meetings from CRM leads so the history stays with the account.</li><li><strong>Operations managers and coordinators</strong> schedule pre-job meetings and client briefings, and check colleagues' availability before proposing times.</li><li><strong>QA/QC managers</strong> keep audit dates, preparation meetings and internal quality reviews visible to everyone involved.</li><li><strong>Level IIIs</strong> schedule procedure reviews, technician examinations and training sessions.</li><li><strong>Trainers</strong> run internal sessions and make sure trainees are not double-booked against site work checked in Team Assignments.</li><li><strong>Office administrators</strong> manage meeting rooms, vendor visits and general company events.</li></ul><p>Each user sees their own calendar by default and can add colleagues' calendars as needed. Access and visibility are set during implementation to suit your company, including what external attendees receive.</p><h2>What implementation looks like</h2><p>The Calendar app is one of the easiest parts of Atlantis NDT ERP to roll out, but a little thought at the start makes it far more useful.</p><ol><li><strong>Agree what goes where.</strong> We confirm with you that technician dispatch and availability belong in Team Assignments and Time Off, and meetings and events belong in Calendar, so staff know which one to check.</li><li><strong>Connect personal calendars.</strong> Where you use Google or Outlook, synchronisation is set up and each user is shown how to connect their account.</li><li><strong>Set up recurring events.</strong> Your regular operations reviews, QA meetings and management reviews are created as recurring events with the right attendees.</li><li><strong>Default reminders.</strong> Sensible default reminders are agreed for client meetings and audits.</li><li><strong>Link to CRM and projects.</strong> Sales and operations are shown how to schedule meetings from leads, customers and projects so the history stays connected.</li><li><strong>Training and support.</strong> Short sessions per role, then support through the first weeks.</li></ol><p>Atlantis NDT ERP is fully customizable, so anything specific to your company is scoped and agreed with you before work starts. Pricing is quote on request. <a href=\"/contact?service=erp&amp;subject=Calendar%20app%20quote\">Request a quote</a> and tell us which calendar tools your team already uses.</p><h2>Frequently asked questions</h2><h3>Is the Calendar app where we schedule technicians for jobs?</h3><p>No. Technician dispatch and availability live in Team Assignments, which has its own calendar view, blocks overlapping bookings and draws on Time Off for leave. The Calendar app is for meetings and events around the work, such as client meetings, audits and briefings.</p><h3>Can it sync with Google Calendar or Outlook?</h3><p>Yes. Odoo Calendar supports synchronisation with Google Calendar and Microsoft Outlook. It is set up during implementation, and each user connects their own account.</p><h3>Can clients and auditors be invited?</h3><p>Yes. External attendees receive an email invitation they can accept or decline, and their responses show on the event.</p><h3>Can meetings be linked to CRM leads and projects?</h3><p>Yes. Scheduling a meeting activity on a CRM lead creates a calendar event linked to that lead, so the meeting sits in both the calendar and the lead's history. The same approach works on other records such as customers and projects.</p><h3>Does it track certificate and calibration expiry dates?</h3><p>Expiry tracking belongs to the Certificates and Asset Management apps, which compute statuses and send alerts. The Calendar app holds the meetings and audits that follow from them.</p><h3>Can we set recurring meetings?</h3><p>Yes. Weekly, monthly or other recurring events can be created, and individual occurrences can be moved without breaking the series.</p><h3>What does it cost?</h3><p>Atlantis NDT ERP is affordable and fully customizable. Pricing depends on your scope and is quote on request.</p><h2>See how it fits your week</h2><p>Tell us what your typical week looks like: which client meetings, briefings, audits and internal reviews you run, and which calendar tools your people already use. We will show you how that week looks in Atlantis NDT ERP, alongside CRM, Team Assignments and Certificates.</p><p>Affordable. Accessible. Fully customizable. <a href=\"/contact?service=erp&amp;subject=Calendar%20app%20demo\">Book a demo of the Calendar app</a>, or explore the full <a href=\"/erp\">NDT ERP</a> first.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Calendar%20demo\">Send an enquiry about Calendar</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/to-do","publishedAt":"2026-09-27","title":"To-do App for NDT Inspection Teams | Atlantis NDT","description":"Give NDT managers, Level IIIs and coordinators one list for follow-ups, renewals and admin tasks in Atlantis NDT ERP. Book a demo or request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>To-do App for NDT Inspection Teams</h1>\n<p>Personal and team task lists linked to jobs and records. <a href=\"/contact?service=erp&amp;subject=To-do%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>What the To-do app does for an NDT company</h2><p>Every NDT company has a layer of work that doesn't fit anywhere neat. Chase the client for the signed-off scope. Ask the lab when the phased array unit is coming back. Remind a technician to send their updated vision test. Check whether the new trainee has booked their examination. Send the revised procedure to the client's Level III. Find the missing purchase order before the invoice goes out.</p><p>None of that is a project. None of it is an inspection. But when it slips, jobs start late, invoices sit unpaid and technicians turn up on site with paperwork that isn't ready.</p><p>In most companies that work lives on sticky notes, in notebooks, in email flags and in the heads of two or three overloaded people. The To-do app in Atlantis NDT ERP gives it a proper home. It is the standard Odoo To-do app, set up by Atlantis NDT for the way an inspection company works: a personal task list for each user, with tags, stages, assignees, deadlines and the ability to turn a to-do into a proper project task when it grows.</p><p>Because it sits inside the same system as your projects, certificates, equipment and invoices, the follow-ups are next to the records they relate to. A manager doesn't need a separate tool for their own list; they open the ERP they already use for everything else.</p><p>This page explains what goes on the list in an NDT company, how the app fits with the rest of Atlantis NDT ERP, who uses it and how it is set up.</p><h2>The problems it is meant to stop</h2><p>Small follow-ups going missing is one of the most common and least discussed problems in NDT companies. It looks like this:</p><ul><li>A Level III promises a client an updated procedure by Friday, writes it on a pad, and the pad goes into a bag that goes to site.</li><li>An operations manager is asked by a technician to arrange a replacement probe. They agree in the corridor, get pulled into a call, and forget.</li><li>A QA manager knows three technicians need updated medical fitness paperwork but has no single list of who, and by when.</li><li>An owner asks the office to chase an overdue invoice. Two people chase it. Or nobody does.</li><li>Someone leaves the company, and their unwritten follow-ups leave with them.</li></ul><p>These aren't failures of competence. They are failures of memory under pressure, and NDT companies are under a lot of pressure: turnarounds, shutdowns, rush jobs and short-notice mobilisations. The people carrying the most follow-ups, such as Level IIIs, operations managers and owners, are also the people most often pulled onto site or into client meetings.</p><p>The To-do app doesn't try to be clever about it. It gives each person one list that lives in the ERP, lets them hand items to colleagues, and keeps items visible until they are done. When the list is in the same place as the rest of the work, it gets checked.</p><h2>What goes on the list</h2><p>How people use To-do varies, but in an NDT company the list tends to fill with the same kinds of items. Here are typical examples by role:</p><table><thead><tr><th>Role</th><th>Typical to-dos</th></tr></thead><tbody><tr><td>Level III</td><td>Review a technician's practical exam results; send a revised procedure to a client; prepare questions for a trainee's specific exam; follow up on a technique query from site</td></tr><tr><td>QA/QC manager</td><td>Collect updated vision tests; prepare for a surveillance audit; chase a missing calibration certificate; close out an internal audit finding</td></tr><tr><td>Operations manager</td><td>Confirm site induction dates; chase a client for permit-to-work details; arrange a replacement probe; confirm crew rotation for a long job</td></tr><tr><td>Sales / business development</td><td>Send a revised quotation; follow up on a submitted bid; ask a client for next year's shutdown plan</td></tr><tr><td>Accounts</td><td>Chase a missing PO number; follow up an overdue invoice; collect expense receipts from a crew</td></tr><tr><td>Owner / general manager</td><td>Decide on a new instrument purchase; review a key client's account; approve a hire</td></tr></tbody></table><p>Some of these items relate directly to a record in the ERP, such as a quotation, a technician's certification, a project or an invoice. Others don't. The To-do app handles both: a free-standing reminder to yourself, or a task that points to the work it is about.</p><p>What they have in common is that each one is small, specific and easy to forget. Written down in one place, they stop being forgotten.</p><h2>Organising the list: stages, tags and priorities</h2><p>A to-do list only works if it stays readable. The To-do app gives each user a few simple ways to keep it in order.</p><p><strong>Personal stages.</strong> Each user arranges their tasks in stages that make sense to them, shown as columns on a kanban board. A common setup is something like Inbox, Today, This week, Waiting on others and Done, but people are free to organise their own board the way they think.</p><p><strong>Tags.</strong> Tags group tasks across stages. An NDT company might use tags such as Client, Audit, Certificates, Equipment, Procedures, Billing or the name of a major project. A QA manager can then filter their list to every open Audit item before a certification body visit.</p><p><strong>Priority and deadlines.</strong> Tasks can be starred as a priority and given a deadline, so the important items stand out and overdue ones are obvious.</p><p><strong>Notes and checklists.</strong> Each task has space for notes, so the context lives with it: the client contact, the reference numbers, what was already agreed.</p><p><strong>Assigning and sharing.</strong> A task can be assigned to one or more colleagues. The operations manager who promised a replacement probe can hand the task to the equipment controller, and it appears on their list rather than in a corridor conversation.</p><p>None of this needs heavy training. Most people pick it up after a short walkthrough, which is exactly what makes it likely to be used.</p><h2>From to-do to project task</h2><p>Some to-dos turn out to be bigger than they looked. A note to prepare for a client's new inspection scope becomes a proper piece of work with several people, dates and a deliverable. When that happens, the To-do app lets you convert the item into a task in a project, so it moves into the structured workflow without being retyped.</p><p>In Atlantis NDT ERP, projects are set up for NDT work. A project carries the NDT job type, site, client PO, contract, methods, codes, scope, acceptance criteria, assigned equipment and technicians, job status, and fields for safety induction and work permits. Tasks within a project carry the method, technician, component, result, indication and defect counts, and procedure and WPS references.</p><p>That gives a clear path:</p><ol><li>An idea or request starts as a quick to-do on someone's personal list.</li><li>If it stays small, it is done and ticked off.</li><li>If it grows, it becomes a project task, where it gets an owner, a place in a project and the NDT fields that matter to that job.</li></ol><p>The benefit is that nobody has to decide up front whether something is important enough to be a project task. They write it down in the quickest way possible, and promote it later if needed. That lowers the barrier to writing things down in the first place, which is where most follow-ups are lost.</p><p>It also keeps projects clean. Personal reminders and small admin items don't clutter the project's task list, and project tasks aren't buried among personal notes.</p><h2>Activities, reminders and warnings from other apps</h2><p>Atlantis NDT ERP uses Odoo activities throughout: a scheduled call, email or follow-up attached to a specific record, with a due date and an assignee. Activities appear in each user's activity menu, grouped by overdue, today and planned, so the day's follow-ups are visible at a glance.</p><p>The To-do app sits alongside these activities. A useful way to think about it:</p><ul><li><strong>Activities</strong> are follow-ups on a specific record: call the client on this CRM lead, review this quotation, approve this procedure.</li><li><strong>To-dos</strong> are your own working list: anything you need to do, whether or not it belongs to a specific record.</li></ul><p>Several NDT-specific apps create their own warnings that feed a manager's working day:</p><ul><li><strong><a href=\"/erp/apps/certificates\">Certificates</a></strong> runs daily checks and creates warning tasks 90 days before a technician's certification or vision test expires. Configurable daily email alerts cover technician certs, calibration certificates and company certifications, with recipients, look-ahead days and resend interval set by you.</li><li><strong>Procedures</strong> sends notifications and reminders to approvers for pending procedure approvals.</li><li><strong>Timesheets</strong> warns when a technician's certificate is not valid.</li></ul><p>These warnings tell you what is coming. The To-do list is where the QA manager or coordinator keeps the practical follow-up around them: contact the technician, book the vision test, arrange the renewal examination, confirm with the client that a replacement technician will cover the job.</p><h2>How To-do differs from Project and Team Assignments</h2><p>Atlantis NDT ERP has several places where work is tracked, and it helps to be clear which one is for what.</p><table><thead><tr><th>App</th><th>What it tracks</th><th>Example</th></tr></thead><tbody><tr><td>To-do</td><td>Personal and small shared follow-ups</td><td>Chase the client for the signed scope; send the revised procedure</td></tr><tr><td>Project</td><td>Structured NDT jobs and their tasks, with methods, codes, scope, acceptance criteria, technicians, equipment and results</td><td>Tank floor inspection project with tasks per component and method</td></tr><tr><td>Team Assignments</td><td>Dispatch of crews and equipment: planned, dispatched, in field, submitted, closed; availability and double-booking checks</td><td>Two UT technicians and a phased array unit mobilised to a site for ten days</td></tr><tr><td>Calendar</td><td>Meetings and events with attendees and reminders</td><td>Client kick-off; certification body audit</td></tr><tr><td>Maintenance</td><td>Preventive and corrective requests on equipment and vehicles</td><td>Crawler service; broken yoke repair</td></tr></tbody></table><p>Keeping those roles distinct avoids the most common ERP failure in small companies, where everything ends up in one list and nobody can find anything. The To-do app is deliberately the lightest of the set. It is the place for work that is too small or too personal for the others, and the entry point for items that may later be promoted into <a href=\"/erp/apps/team-assignments\">Team Assignments</a> or Project work.</p><h2>Who uses the To-do app</h2><ul><li><strong>Owners and general managers</strong> keep their own decision list and hand specific follow-ups to the people who should own them.</li><li><strong>Operations managers and coordinators</strong> track the stream of small commitments made to clients and crews during a busy week.</li><li><strong>Level IIIs</strong> keep technical follow-ups in one place: procedure revisions, technique queries, exam reviews and client technical questions.</li><li><strong>QA/QC managers</strong> manage audit preparation, certificate follow-ups and internal findings.</li><li><strong>Sales and business development</strong> track promised quotations, bid follow-ups and client questions.</li><li><strong>Accounts and office administrators</strong> chase POs, receipts, overdue invoices and supplier queries.</li><li><strong>Senior technicians and supervisors</strong> can use it for their own site follow-ups if your company chooses to give them access.</li></ul><p>Access is set per role during implementation. Each person sees their own tasks and those shared with them, while managers can be given wider visibility where it helps.</p><h2>What implementation looks like</h2><p>To-do is quick to roll out, but it only sticks if people see how it fits into their day. Atlantis NDT sets it up as part of your ERP deployment:</p><ol><li><strong>Agree the split.</strong> We confirm with your managers what belongs in To-do, what belongs in Project, Team Assignments, Calendar and Maintenance, so nobody is confused about where to look.</li><li><strong>Starter tags.</strong> A shared set of tags is agreed, such as Client, Audit, Certificates, Equipment, Procedures and Billing, so filters work across the team.</li><li><strong>Suggested stages.</strong> A simple starter board is suggested for each user, which they can change freely.</li><li><strong>Link to alerts.</strong> Recipients and look-ahead days for Certificates email alerts are set, so the right people get warnings they can turn into to-dos.</li><li><strong>Short training.</strong> A walkthrough per role, focused on capturing tasks quickly, handing them to colleagues and promoting them to project tasks.</li><li><strong>Go-live and support.</strong> We stay with you through the first weeks while the habit forms.</li></ol><p>Atlantis NDT ERP is fully customizable, and anything specific to your company is scoped and agreed with you before work begins. Pricing is quote on request. <a href=\"/contact?service=erp&amp;subject=To-do%20app%20quote\">Request a quote</a> and tell us how many people will be using the ERP.</p><h2>Frequently asked questions</h2><h3>Is To-do just a personal list?</h3><p>Mostly, yes, and that is its strength. Each user has their own list, but tasks can be assigned to or shared with colleagues, so follow-ups can be handed over properly instead of verbally.</p><h3>Can a to-do become a project task?</h3><p>Yes. A to-do can be converted into a task in a project, where it picks up the NDT fields set up for your projects, such as method, technician, component, result and procedure references.</p><h3>Does To-do warn us about expiring technician certificates?</h3><p>The warnings come from the Certificates app, which creates warning tasks 90 days before a certification or vision test expires and can send daily email alerts. To-do is where people keep the practical follow-up actions around those warnings.</p><h3>How is To-do different from activities?</h3><p>Activities are follow-ups attached to a specific record, such as a CRM lead or a quotation. To-dos are your own working list and don't have to belong to a record. Both are visible in the ERP so nothing is lost.</p><h3>Can technicians use it?</h3><p>If your company wants them to, yes. Access is set per role during implementation. Many companies start with managers and office staff and extend it later.</p><h3>Do we need training to use it?</h3><p>Very little. A short walkthrough per role is included in implementation, focused on capturing tasks, tagging them and handing them to colleagues.</p><h3>What does it cost?</h3><p>Atlantis NDT ERP is affordable and fully customizable. Pricing depends on your scope and is quote on request.</p><h2>Get the small things under control</h2><p>If your company's follow-ups live on sticky notes and in people's heads, the To-do app is one of the simplest improvements you can make, and it works best as part of the full <a href=\"/erp\">NDT ERP</a> where projects, certificates, equipment and invoices already live. You can also browse all <a href=\"/erp/apps\">NDT ERP apps</a> to see how the pieces fit.</p><p>Affordable. Accessible. Fully customizable. <a href=\"/contact?service=erp&amp;subject=To-do%20app%20demo\">Book a demo of the To-do app</a> and we will show you how a typical week of follow-ups looks inside Atlantis NDT ERP.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments</a>: Assign qualified technicians and crews to jobs by method, level and availability.</li><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=To-do%20demo\">Send an enquiry about To-do</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/crm","publishedAt":"2026-09-27","title":"NDT CRM Software for Inspection Companies | Atlantis NDT","description":"CRM built for NDT companies: track inspection, training and consulting leads by method, site and crew size, score them 0-100 and follow up. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT CRM: Win More Inspection, Training and Consulting Work</h1>\n<p>Leads and opportunities for inspection, training and consulting work. <a href=\"/contact?service=erp&amp;subject=CRM%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why a generic CRM falls short for an NDT company</h2><p>Most CRMs were built to sell software subscriptions or office furniture. They ask for a deal value and a close date, and that is about it. An NDT enquiry does not look like that. A refinery planner emails asking for two UT Level II technicians and a PAUT operator for a ten-day shutdown. A fabrication shop wants MT and PT on a batch of structural welds next week. An EPC needs someone to write and qualify a procedure before their contractor starts. A plant wants to send three people on a Level II course.</p><p>Each of those is a different kind of work, priced differently, staffed differently and won by different people in your company. When they all land in the same inbox, or the same generic pipeline, the important details get lost. Which method? Which site, in which country? How many technicians, for how many days? Is this a one-off or the first job on a framework contract?</p><p>The result is familiar to anyone who has run an inspection business. Enquiries get answered late because nobody knew who owned them. Quotes are built in a spreadsheet from a half-remembered phone call. A promising client goes quiet and nobody follows up, because the lead lived in one salesperson's head. And when the owner asks how much training work is in the pipeline for next quarter, the answer takes a day to assemble.</p><p>The CRM in the Atlantis NDT ERP is Odoo's CRM, pre-configured for NDT companies. It keeps the standard pipeline tools you would expect and adds the fields, scoring and follow-up tools that match how inspection, training and consulting work is actually sold. If you want to see it with your own kind of enquiries, <a href=\"/contact?service=erp&amp;subject=CRM%20demo\">book a CRM demo</a>.</p><h2>What the CRM records on every NDT lead</h2><p>Every lead and opportunity carries the details an estimator or operations manager needs before they can say yes or no to a job. These are proper fields, not notes buried in a comment box, so you can filter, group and report on them.</p><ul><li><strong>Service line</strong>: for example inspection, training or consulting, using the lines you define during setup, so each part of the business sees its own pipeline.</li><li><strong>NDT service type</strong>: the method or service requested, such as UT, RT, MT, PT, VT, ET, TOFD or phased array.</li><li><strong>Industry sector</strong>: oil and gas, petrochemical, power, fabrication, marine, aerospace and so on.</li><li><strong>Site country</strong>: where the work will actually happen, which is often not where the client's head office is.</li><li><strong>Estimated technicians and estimated days</strong>: the crew size and duration you need to plan for, captured at the enquiry stage.</li><li><strong>Lead source</strong>: website form, referral, trade show, imported list, business card, reply to an email campaign, and any other sources you track.</li></ul><p>Because crew size and duration sit on the lead, your operations manager can look at the pipeline and see a busy month coming weeks before the purchase orders arrive. A lead for eight technicians over three weeks in a country where you have no crew is a different conversation from a two-day MT job down the road, and the CRM makes that obvious at a glance.</p><p>The standard Odoo tools remain: pipeline stages, expected revenue, probability, scheduled activities, notes, email history, and a full log of every interaction on the record. Nothing has been taken away to make room for the NDT fields. Your salespeople get a pipeline that looks familiar, with the questions an inspection company actually needs answered built into the form.</p><h2>Lead scoring built for inspection work: hot, warm, nurture, cold</h2><p>Every lead gets an NDT lead score from 0 to 100, grouped into four bands: hot, warm, nurture and cold. The point is simple. Your sales team, which in many NDT companies is the owner plus one or two people, should spend its time on the enquiries most likely to turn into work.</p><p>A hot lead is one to call today. A warm lead deserves a tailored follow-up this week. A nurture lead is a real company with a real need, but not ready to buy yet, so it goes into an email sequence rather than a phone queue. A cold lead stays in the database but does not take anyone's afternoon.</p><p>The score sits on the lead record and can be used in list views, filters and kanban grouping. A typical morning routine is to open the pipeline filtered to hot leads, work through them, then check the warm leads that have no activity scheduled. How the bands line up with your priorities is reviewed with you during implementation, so the score reflects the work you actually want more of.</p><p>Scoring also helps with honest forecasting. When the owner asks what the pipeline looks like, you can separate the hot and warm opportunities from the long tail of nurture contacts, instead of adding everything up and hoping.</p><p>It helps new team members too. Someone who joined last month does not yet know which enquiries are serious. The score and band give them a starting point, and the history on each record tells them what has already been said.</p><h2>Getting leads in: website forms, CSV imports and business cards</h2><p>A CRM is only as useful as the leads inside it. The Atlantis NDT ERP gives you several ways to get them in without re-typing.</p><h3>Website enquiry forms</h3><p>Enquiry forms on your company website, built with the Website app, feed straight into the CRM as leads. A plant engineer who writes that they need RT on a set of butt welds at their site next month lands in the pipeline with their message attached, ready for someone to qualify.</p><h3>CSV import</h3><p>If you have years of contacts in spreadsheets, an old CRM export or a list built from an industry directory, the lead import takes a CSV file and creates leads in bulk. You map columns during the import, bring in the fields you have, and fill in the NDT-specific ones as you qualify each lead.</p><h3>Business cards</h3><p>Trade shows and site visits leave you with a pocket full of cards. With the Business Cards app you take a photo of a card, and AI/OCR extracts the name, company, job title, email, phone numbers and website. One click turns it into a CRM lead or adds the person to a mailing list. It works from a phone upload, so the card can be in the system before you leave the exhibition hall.</p><h3>Phone calls and direct enquiries</h3><p>Plenty of work still starts with a phone call. A salesperson can create a lead in seconds from the pipeline view, fill in the service type, site country and crew estimate, and assign it to the right person.</p><p>Whatever the route, the lead source is recorded. Over time you can see which channels bring you real inspection, training and consulting work, and which ones just bring noise.</p><h2>A day in the pipeline: from enquiry to signed quotation</h2><p>Here is how a typical inspection enquiry moves through the CRM.</p><ol><li><strong>Enquiry arrives.</strong> A maintenance planner at a petrochemical plant fills in your website form asking for UT thickness and visual inspection during a planned outage. A lead is created with the message attached.</li><li><strong>Qualification.</strong> Your sales coordinator opens it, sets the service line to inspection, picks the service type, industry sector and site country, and enters the estimate: four technicians, twelve days. The lead score shows where it sits.</li><li><strong>Check with operations.</strong> Before promising dates, the coordinator schedules an activity for the operations manager, who checks technician availability in Team Assignments and valid certifications in the Certificates app.</li><li><strong>Convert to opportunity.</strong> Once it is real, the lead becomes an opportunity in your inspection pipeline, owned by one person with a clear next action and date.</li><li><strong>Quotation.</strong> From the opportunity, a quotation is created with job type, site, project dates and applicable codes, using NDT service products flagged by method. A branded PDF goes to the client. The <a href=\"/erp/apps/quotations\">Quotations app</a> covers this step in detail.</li><li><strong>Acceptance.</strong> The client can accept and sign the quote online. It converts to a sales order and the opportunity is marked won.</li><li><strong>Lost reasons.</strong> If you lose, you record why: dates, crew availability, a competitor, a changed scope. Over a year, those reasons tell you a lot about where to improve.</li></ol><p>At every step the history is on the record. If the coordinator is on leave, anyone can open the opportunity and see exactly what was said, what was sent and what is due next. Nothing depends on one person's memory or inbox.</p><h2>Follow-up that actually happens: AI-personalised emails and drip sequences</h2><p>The most common way NDT companies lose work is not price. It is silence. A quote goes out, the client does not reply, and nobody chases it because the next job has already started and everyone is busy.</p><p>The CRM gives you two tools for this.</p><h3>AI-personalised email preview</h3><p>From a lead, you can generate a personalised email draft built from the details on the record: the company, the sector, the service they asked about, the site. You see a preview before anything is sent and you edit it like any other email. It is a starting point that removes the blank-page problem, not an autopilot. Where the AI runs is agreed during implementation; the AI Marketing app can use a model hosted on your own server, so lead details do not have to leave infrastructure you control.</p><h3>Drip email sequences</h3><p>For nurture leads, you can enrol the lead in a drip email sequence with one action. Sequences are organised by service line, so a fabrication shop interested in inspection gets inspection content, and a plant training coordinator gets training content. Sequences can be paused and resumed, and recipients can unsubscribe.</p><p>The practical effect is that leads who are not ready today still hear from you in a measured, relevant way, and your sales team picks up the phone when someone engages. More detail on building those sequences is on the <a href=\"/erp/apps/ai-marketing\">AI Marketing app page</a>.</p><p>A simple rule keeps this healthy: when a nurture lead replies or asks for a price, pause the sequence and move the lead to a person. Automation is for staying in touch, not for negotiating.</p><h2>Inspection, training and consulting: one CRM, separate pipelines</h2><p>Most NDT companies sell more than one thing, and each line has its own rhythm.</p><h3>Inspection services</h3><p>Short cycles, urgent requests, crew-driven. The questions are method, site, dates, crew size and whether your technicians hold the right certifications. Estimated technicians and days matter more than anything else here. Shutdown and turnaround enquiries often arrive months ahead, and the CRM lets you track them as opportunities long before the purchase order is issued.</p><h3>Training</h3><p>Training enquiries come from individuals wanting to move up a level and from employers sending groups. The CRM tracks who is interested in which method and level, when they want to start and whether their employer is paying. Once enrolled, learners move to the eLearning portal, where they also get a Practical NDT section that opens <a href=\"/practical-ndt\">Practical NDT</a>, Atlantis's immersive 3D practice platform with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings. That is a strong point to mention in training follow-ups.</p><h3>Consulting</h3><p>Consulting is slower and relationship-driven: procedure writing, Level III services, reviews of a client's NDT programme, supplier qualification. Deals can take months. The CRM keeps the conversation history, the documents exchanged and the next step in one place, so a consulting opportunity does not go cold between meetings.</p><p>Each line can have its own pipeline stages, its own sales team and its own reporting, while companies and contacts are shared. The refinery that buys inspection from you might also be the one sending three people to training next quarter, and the CRM shows both relationships on one client.</p><h2>Who uses the CRM day to day</h2><ul><li><strong>Owner or managing director</strong>: pipeline overview by service line, sector and country; which sources bring real work; which opportunities need their personal attention.</li><li><strong>Sales or business development</strong>: qualify leads, work the hot list, send quotes, chase replies, record lost reasons.</li><li><strong>Operations manager</strong>: sees estimated technicians and days on upcoming work, and flags crew or certification constraints before a quote promises dates you cannot meet.</li><li><strong>NDT Level III</strong>: pulled in on technical enquiries, such as whether a procedure exists for a method and material, or whether a consulting scope is realistic. Activities assigned from the CRM keep their input on the record.</li><li><strong>Training coordinator</strong>: manages training enquiries, group bookings from employers and follow-up with past learners.</li><li><strong>Marketing</strong>, often the same person as sales in a small firm: imports lists, runs drip sequences and campaigns, and checks which ones generate replies.</li></ul><p>Access rights are set per role during implementation. A salesperson sees their own pipeline, a manager sees the team, and the owner sees everything.</p><p>In a small NDT company, one person may wear three of these hats. That is exactly where a shared CRM earns its keep: the owner who is also the Level III can see a technical question waiting for them next to the sales pipeline, instead of finding it in an email a week late.</p><h2>How the CRM connects to the rest of the ERP</h2><p>The CRM is the front door. What makes it useful is what happens after the door opens.</p><ul><li><strong>Contacts</strong>: every lead links to a company and person in the shared address book, which quotations, invoices and projects also use.</li><li><strong>Quotations</strong>: an opportunity becomes a quotation with NDT service products, job type, site and codes, and an accepted quote becomes a sales order.</li><li><strong>Project and Team Assignments</strong>: won work becomes an NDT job with site, client PO, methods, scope and acceptance criteria, and technicians and equipment are dispatched with double-booking blocked.</li><li><strong>Certificates</strong>: before you promise a crew, you can check who holds a valid certification for the method.</li><li><strong>NDT Reports</strong>: the reports your inspectors produce are what the client is really paying for. Pair them with <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, Atlantis's companion product that places inspection results on a 3D model of the asset, and you have something few competitors can show in a sales meeting.</li><li><strong>Invoicing</strong>: timesheet hours, equipment and consumables flow into the invoice for the job.</li><li><strong>AI Marketing and Email Marketing</strong>: nurture sequences and campaigns go to the same contacts your sales team works with.</li><li><strong>Dashboards</strong>: pipeline figures sit alongside certification, calibration and financial KPIs.</li></ul><p>Because it is one database, there is no export-import step between sales and operations. The client name, site and scope typed at the enquiry stage are the same ones on the job, the report and the invoice. When a client disputes an invoice, you can trace it back to the quote and the original enquiry in a few clicks.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys and configures the ERP for you. For the CRM, implementation usually covers:</p><ol><li><strong>Pipelines and stages</strong> for each service line you sell, named the way your team talks.</li><li><strong>Field values</strong>: your service lines, NDT service types, sectors, countries and lead sources.</li><li><strong>Lead scoring review</strong>: we walk through the hot, warm, nurture and cold bands with you and agree how they match your priorities.</li><li><strong>Data import</strong>: existing leads and contacts from spreadsheets or your old system via CSV, cleaned and de-duplicated where possible.</li><li><strong>Website forms</strong> connected to the CRM so enquiries arrive as leads.</li><li><strong>Email and drip sequences</strong>: outgoing mail set up on your domain, and first sequences per service line drafted with you.</li><li><strong>Users and access rights</strong> for sales, operations, Level III and management.</li><li><strong>Training</strong> for your team on the daily routine: qualify, score, follow up, quote.</li></ol><p>Anything specific to your company, such as an extra field, a custom report or an approval step before a quote goes out, is part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, and pricing is by quote on request. You can see every app in the system on the <a href=\"/erp/apps\">ERP apps overview</a>.</p><h2>Frequently asked questions</h2><h3>Is this a separate CRM or part of the ERP?</h3><p>It is part of the ERP. The CRM is Odoo's CRM app, pre-configured with NDT fields, lead scoring and follow-up tools, and it shares one database with quotations, jobs, certificates, reports and invoicing. There is nothing to sync.</p><h3>Can I import my existing leads?</h3><p>Yes. Leads can be imported from a CSV file, and during implementation we help map your existing spreadsheet or old CRM export into the right fields. NDT-specific fields you never tracked before can be filled in as leads are qualified.</p><h3>How does the NDT lead score work?</h3><p>Each lead gets a score from 0 to 100 and a band: hot, warm, nurture or cold. Your team uses the bands to decide who to call today, who to follow up by email and who to place in a drip sequence. We review the bands with you during setup.</p><h3>Does the AI send emails on its own?</h3><p>No. The AI-personalised email in the CRM is a preview you read and edit before sending. Automated sending only happens when you deliberately enrol a lead in a drip sequence, and sequences can be paused or the recipient can unsubscribe.</p><h3>Can we track training and consulting enquiries as well as inspection jobs?</h3><p>Yes. The service line field separates them, and each line can have its own pipeline and stages. Contacts are shared, so a client who buys both inspection and training appears once.</p><h3>Can operations see what is coming before the PO arrives?</h3><p>Yes. Estimated technicians and estimated days are recorded on each lead, so the operations manager can filter the pipeline for expected work and plan crews and certifications ahead of time.</p><h3>What does it cost?</h3><p>Pricing depends on your users, the apps you need and the customization scope, so it is by quote on request. Tell us about your company and we will come back with a proposal.</p><h2>See the NDT CRM with your own pipeline</h2><p>The quickest way to judge whether this fits is to see it with your kind of work in it. In a demo we set up a few leads that look like yours, an inspection enquiry, a training group booking and a consulting request, and walk through qualification, scoring, follow-up and quotation.</p><p><a href=\"/contact?service=erp&amp;subject=CRM%20demo\">Book a CRM demo</a> or <a href=\"/contact?service=erp&amp;subject=CRM%20quote\">request a quote</a> for the Atlantis NDT ERP.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=CRM%20demo\">Send an enquiry about CRM</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/contacts","publishedAt":"2026-09-27","title":"NDT Contact Management Software for Clients | Atlantis NDT","description":"One address book for NDT clients, plant sites, calibration labs and learners, linked to quotes, jobs and invoices. Book a demo of Atlantis NDT ERP Contacts.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Client and Contact Management: One Address Book for Every Site</h1>\n<p>One address book for clients, sites, vendors and technicians. <a href=\"/contact?service=erp&amp;subject=Contacts%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>The contact problem in an NDT company</h2><p>Ask any NDT operations manager where a client's site contact details live, and the honest answer is often 'somewhere'. The purchasing contact is in the sales manager's phone. The site HSE coordinator who arranges your inductions is in last year's email thread. The invoice address is on a PDF from the client's accounts team. The plant's QA/QC manager, the person who actually signs off your reports, is known only to the technician who was on site last time.</p><p>That scatter costs real time and money. Technicians turn up at the wrong gate because the address on file was the head office. Invoices sit unpaid because they went to the engineer instead of accounts payable. A report goes to someone who left the client six months ago. A good client relationship walks out of the door when your salesperson does, because nobody else had the details.</p><p>NDT work makes this worse than most industries. One client can have a head office in one city, three plants in different regions, a separate accounts payable team, and different people approving work at each site. Add EPCs, fabrication shops, third-party inspection agencies, calibration labs, equipment dealers, subcontractors and individual learners booking training, and the address book of a mid-sized inspection company becomes large and messy fast.</p><p>The Contacts app in the Atlantis NDT ERP is Odoo's standard Contacts app, set up for an NDT company. It is the single address book every other app uses: CRM, quotations, projects, reports, invoicing, purchasing, email marketing and eLearning. Enter a client once, correctly, and every part of the business works from the same record.</p><h2>Companies, people and sites: how the address book is structured</h2><p>Odoo Contacts distinguishes between companies and individuals, and links people to the company they work for. That simple structure fits NDT work well.</p><ul><li><strong>The client company</strong> is one record: legal name, tax ID, main address, payment terms, and the salesperson who owns the relationship.</li><li><strong>People at the client</strong> are individual contacts linked to that company, each with their own job position, email and phone: the maintenance planner, the inspection engineer, the QA/QC manager, the buyer, the HSE coordinator.</li><li><strong>Addresses</strong> can be added under the company as separate records, typed as invoice addresses, delivery addresses or other addresses. For an NDT company, that means the head office, the accounts payable address and each plant or yard where your crews actually work can all sit under one parent.</li></ul><p>When you create a quotation or an invoice, you choose the right address for the right purpose. The quote goes to the buyer, the invoice goes to the invoice address, and the job carries the actual site. The client's history, everything you have quoted, done and invoiced, still rolls up to one company.</p><p>This matters for a question every owner asks eventually: how much work did we do for this client last year, across all their sites? With a proper company-and-people structure, the answer is on the company record rather than at the end of a week of spreadsheet work.</p><p>It also matters when people move on. When a client's inspection engineer changes jobs, you archive their contact, add the replacement under the same company, and the history stays with the company instead of disappearing with one person.</p><h2>Every kind of contact an NDT company deals with</h2><p>An inspection company's address book holds far more than clients. The Contacts app keeps them all in one place, and tags make it easy to tell them apart.</p><h3>Clients and end users</h3><p>Refineries, petrochemical plants, power stations, fabrication shops, shipyards and aerospace maintenance shops: the companies that pay for inspection, training and consulting.</p><h3>EPCs and main contractors</h3><p>Often your direct client on a project, with the asset owner standing behind them. You may need to track both, and be clear about which one you invoice.</p><h3>Vendors and calibration labs</h3><p>Equipment manufacturers, dealers and calibration laboratories are contacts too. In the Purchase app, a vendor can be classed as an OEM, a dealer or a calibration lab, with an accredited-lab flag, accreditation number and expiry date. Those details sit on the same vendor record your purchasing team already uses.</p><h3>Subcontractors and partner companies</h3><p>When you bring in another NDT company for a method you don't cover, or extra crew during a shutdown, their details belong in the same address book as everyone else.</p><h3>Learners and training sponsors</h3><p>People who enrol in your courses, and the employers who pay for them. Learners given access to the eLearning portal are contacts with portal accounts.</p><h3>Third-party inspection agencies</h3><p>The inspectors and agencies who witness your work on behalf of clients and whose names appear on your reports.</p><p>Keeping all of these in one place avoids the classic problem of the same company existing in three systems with three spellings and three different phone numbers.</p><h2>Tags and segments for inspection, training and consulting</h2><p>Tags are the simplest tool in the Contacts app, and one of the most useful. A contact can carry as many tags as you like, and you can filter, group and target campaigns by them.</p><p>A sensible tag scheme for an NDT company usually covers four things:</p><ul><li><strong>Relationship</strong>: client, prospect, past client, vendor, calibration lab, subcontractor, learner, training sponsor.</li><li><strong>Industry sector</strong>: oil and gas, petrochemical, power, fabrication, marine, aerospace, nuclear, structural.</li><li><strong>Interest</strong>: the methods and services they buy or have asked about, such as UT, PAUT, RT, MT, PT, TOFD, training, procedure writing or Level III services.</li><li><strong>Role</strong>: decision maker, technical approver, buyer, site contact, accounts.</li></ul><p>With that in place, useful lists take seconds to build. All technical approvers at petrochemical clients. All past learners who took Level I and might be ready for Level II. All fabrication shop buyers who asked about MT and PT in the last year. All calibration labs you use.</p><p>Those lists feed straight into the Email Marketing and AI Marketing apps. A training intake announcement goes to learners and training sponsors, not to your calibration lab. A note about your phased array capability goes to inspection engineers at plants, not to the accounts payable team.</p><p>We agree the tag scheme with you during implementation. It is better to start with a short, consistent list that everyone uses than a long one nobody remembers. Tags can always be added later as your business grows into new sectors or methods.</p><h2>Everything about a client on one screen</h2><p>Open a client's company record and the smart buttons along the top show what is linked to it: opportunities in the CRM, quotations and sales orders, invoices, and other records from the apps you use. One click takes you to the list.</p><p>Below that, the record's history holds the conversation: emails sent and received from inside the ERP, notes logged by your team, scheduled activities, and changes to key fields. When a client calls with a question, whoever answers can see what was last discussed, what was quoted and whether anything is overdue.</p><p>For an NDT company this pays off in everyday situations:</p><ul><li><strong>A repeat enquiry</strong>: the client asks for 'the same as last time'. You can see the previous quote, the sales order and the job it became.</li><li><strong>A payment chase</strong>: accounts can see outstanding invoices for the client and the right invoice contact without asking sales.</li><li><strong>A handover</strong>: a salesperson leaves, and their clients' history is still on the records, not locked in a personal inbox.</li><li><strong>A mobilisation</strong>: the operations manager checks the site address and site contact before sending a crew, instead of asking around the office.</li></ul><p>Commercial settings live on the contact too: payment terms, tax ID, fiscal position and bank details, which Odoo uses on quotations and invoices. Set them correctly once and every document for that client inherits them. Tax rules for each country you work in are configured during implementation.</p><h2>Keeping the data clean</h2><p>An address book is only useful if people trust it. A few habits and standard tools keep it clean.</p><h3>Import once, properly</h3><p>Most NDT companies start with contacts spread across spreadsheets, an old accounting package and email. Odoo imports contacts from CSV or Excel files, with column mapping. During implementation we help bring in your existing clients, sites and vendors, and place people under their companies.</p><h3>Deal with duplicates</h3><p>'Acme Refining', 'ACME Refinery Ltd' and 'Acme Ref.' are the same client. Odoo's standard tools let you find and merge duplicate contacts, so the history ends up on one record.</p><h3>Capture new people at the source</h3><p>New contacts should arrive through proper channels: website enquiry forms that create CRM leads, lead import, or the Business Cards app. With Business Cards, you photograph a card at a trade show or on a site visit, AI/OCR extracts the name, company, title, email, phones and website, and one click creates a CRM lead or adds the person to a mailing list. No re-typing, no typos in email addresses.</p><h3>Archive rather than delete</h3><p>When someone leaves a client, archive their contact. It disappears from everyday lists but stays attached to past quotes, jobs and invoices.</p><h3>Give it an owner</h3><p>Someone should own contact quality, usually a sales coordinator or office manager. A short weekly look at new records catches most problems before they spread into quotes and invoices.</p><h2>Contacts and marketing: reaching the right people</h2><p>Once your contacts are organised, marketing stops being guesswork. The Contacts app is the source of the people and companies that the marketing apps work with.</p><ul><li><strong>Email Marketing</strong> sends newsletters and campaigns to mailing lists or filtered contacts, and tracks opens and clicks. See the <a href=\"/erp/apps/email-marketing\">Email Marketing app</a>.</li><li><strong>AI Marketing</strong> drafts campaign emails with AI and runs drip sequences by service line.</li><li><strong>CRM</strong> scores leads and can enrol them in drip sequences.</li></ul><p>Opt-outs matter. When a contact unsubscribes from marketing email, Odoo records it and excludes them from further mass mailings. Respecting that is good manners and, in many countries, a legal requirement. Your obligations under local privacy and marketing laws are for you to decide with your advisers; the ERP gives you the tools to record and honour people's choices.</p><p>A good contacts structure also lets you say something relevant. A plant engineer who has hired you for UT thickness surveys might want to hear about a new phased array capability. A past learner might want to know about the next Level II intake, and that learners on your eLearning portal practise on <a href=\"/practical-ndt\">Practical NDT</a>, Atlantis's immersive 3D practice platform with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings. A QA/QC manager might want to see inspection results placed on a 3D model of their asset with <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, Atlantis's companion product to the ERP's NDT Reports app. Each of those messages depends on knowing who the person is and what they care about.</p><h2>Portal access for clients and learners</h2><p>Odoo lets you give a contact portal access: a login to a customer area on your company's site. For an NDT company that serves two groups well.</p><p><strong>Clients</strong> with portal access can see the quotations and invoices you have sent them, and accept and sign quotes online. That removes a lot of 'can you resend the PDF?' emails, and a signed quote converts to a sales order without anyone re-typing it.</p><p><strong>Learners</strong> in the eLearning portal are contacts with portal accounts. Admins create learner accounts and grant or revoke access to courses. Enrolled learners see their courses, video lessons and quizzes, plus a Practical NDT section that opens the 3D practice platform. Access to Practical NDT is granted automatically on enrolment or manually by an admin.</p><p>Because both groups are contacts, one record can show that a person is a learner, which employer sponsored them, and what they have been sent. When that learner later becomes a buyer or an inspection engineer at a client, which happens often in a small industry, the relationship is already in your system.</p><p>Portal access is optional. Many clients are happy with a PDF by email, and you can grant accounts only where they help. Portal users see only their own documents, and you decide during implementation who gets an account and what they can see.</p><h2>Who uses Contacts</h2><ul><li><strong>Sales and business development</strong>: create and qualify contacts, keep job titles and roles current, tag by interest.</li><li><strong>Operations and dispatch</strong>: look up site addresses and site contacts before a crew mobilises; check who at the client approves reports.</li><li><strong>Accounts</strong>: maintain invoice addresses, payment terms and tax IDs; see outstanding invoices per client.</li><li><strong>Purchasing</strong>: maintain vendors and calibration labs, including the accreditation details held in the Purchase app.</li><li><strong>Training coordinator</strong>: manage learners, sponsoring employers and portal access.</li><li><strong>NDT Level III and report reviewers</strong>: find the right technical contact at the client to receive reports and discuss procedures.</li><li><strong>Owner</strong>: see total activity per client across sites and service lines.</li></ul><p>Access rights decide who can edit what. It is common to let everyone view contacts, restrict who can create new companies, and limit changes to payment terms and tax details to the accounts team.</p><p>In a small NDT company, the same two or three people may cover all of these roles. That is exactly when one shared address book helps most, because nobody has time to keep three separate lists in step.</p><h2>How Contacts connects to the rest of the ERP</h2><p>Contacts is the shared backbone. Nearly every other app links to it.</p><table><thead><tr><th>App</th><th>How it uses contacts</th></tr></thead><tbody><tr><td>CRM</td><td>Leads and opportunities link to a company and person; see the <a href=\"/erp/apps/crm\">CRM app</a></td></tr><tr><td>Quotations</td><td>Quotes go to the client contact, with site, job type, dates and applicable codes</td></tr><tr><td>Project</td><td>NDT jobs record the client, site, client PO and contract</td></tr><tr><td>NDT Reports</td><td>Reports carry client references such as work order, request and contract numbers</td></tr><tr><td>Invoicing</td><td>Invoices go to the invoice address with job or PO number and site</td></tr><tr><td>Purchase</td><td>Vendors, dealers and calibration labs, with accreditation details</td></tr><tr><td>Email Marketing and AI Marketing</td><td>Mailing lists, campaigns and drip sequences</td></tr><tr><td>eLearning</td><td>Learner accounts and portal access</td></tr><tr><td>Business Cards</td><td>New people captured from photographed cards</td></tr></tbody></table><p>Because it is one database, a correction made once, such as a new invoice address, applies everywhere from then on. There is no separate CRM, accounting package and mailing tool to keep in step, and no export-import routine between them. See how all the apps fit together on the <a href=\"/erp\">Atlantis NDT ERP page</a>.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys and configures the ERP for you. For Contacts, the work typically includes:</p><ol><li>Agreeing the structure: how to represent clients with several plants, EPCs and asset owners, and training sponsors.</li><li>Agreeing a tag scheme for relationship, sector, interest and role.</li><li>Importing existing contacts from spreadsheets, your accounting package or an old CRM, and merging obvious duplicates.</li><li>Setting up payment terms, tax settings and fiscal positions for the countries you work in.</li><li>Creating vendor records for your equipment suppliers and calibration labs.</li><li>Connecting website enquiry forms, the Business Cards app and mailing lists.</li><li>Deciding who gets portal access and setting access rights for your team.</li><li>A short training session so everyone enters contacts the same way.</li></ol><p>Anything beyond standard Contacts, such as extra fields you want on a client record, is part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, and pricing is quote on request. <a href=\"/contact?service=erp&amp;subject=Contacts%20demo\">Book a Contacts demo</a> to see it with your own kind of clients and sites.</p><h2>Frequently asked questions</h2><h3>Is the Contacts app custom-built?</h3><p>No. It is Odoo's standard Contacts app, configured for an NDT company with a tag scheme, address structure, vendor records and access rights that suit inspection, training and consulting work. Extra fields are part of the customization scope if you need them.</p><h3>Can one client have several plants or sites?</h3><p>Yes. The client is one company record, and each plant, yard or office can be added underneath as an invoice, delivery or other address. Quotes, jobs and invoices use the right address while the history rolls up to the client.</p><h3>Can we import our existing client list?</h3><p>Yes. Contacts can be imported from CSV or Excel files with column mapping. During implementation we help structure people under their companies and clean up the obvious problems first.</p><h3>How do we avoid duplicate companies?</h3><p>Use Odoo's standard tools to find and merge duplicates, capture new people through website forms, lead import or the Business Cards app rather than free typing, and give one person responsibility for contact quality.</p><h3>Are vendors and calibration labs in the same address book?</h3><p>Yes. They are contacts like everyone else. The Purchase app adds vendor type (OEM, dealer or calibration lab), an accredited-lab flag, accreditation number and expiry.</p><h3>Can clients see their own quotes and invoices?</h3><p>Yes, if you give them portal access. They can view documents you have sent and accept and sign quotes online. Portal access is optional and controlled by you.</p><h3>What does it cost?</h3><p>It depends on your users, the apps you need and the customization scope, so pricing is by quote on request.</p><h2>Put your client list in order</h2><p>If your client details are spread across phones, spreadsheets and old email threads, a single address book is one of the quickest wins an ERP can give an NDT company. It is also the foundation for everything else: better quotes, correct invoices, crews at the right gate and marketing that reaches the right people.</p><p><a href=\"/contact?service=erp&amp;subject=Contacts%20demo\">Book a demo</a> or <a href=\"/contact?service=erp&amp;subject=Contacts%20quote\">request a quote</a> for the Atlantis NDT ERP.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Contacts%20demo\">Send an enquiry about Contacts</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ai-marketing","publishedAt":"2026-09-27","title":"AI Email Marketing for NDT Companies | Atlantis NDT","description":"Draft NDT newsletters, promotions and nurture emails with AI that can run on your own server, then run drip sequences by service line. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>AI Marketing for NDT Companies: Campaign Emails and Drip Sequences</h1>\n<p>AI-assisted outreach and campaign content for NDT buyers. <a href=\"/contact?service=erp&amp;subject=AI%20Marketing%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why marketing is hard for an NDT company</h2><p>Most NDT companies do not have a marketing department. They have an owner who is also a Level III, a business development person who spends half the week on site visits, and an office manager who does the newsletter when there is time. There rarely is.</p><p>The result is predictable. The last client newsletter went out so long ago nobody remembers it. The people who stopped at your stand at the last trade show never heard from you again. The fabrication shop that asked about MT and PT in the spring and went quiet was never contacted again. Your new phased array capability, the one you invested heavily in equipment and training for, was announced once and then forgotten.</p><p>It is not a lack of things to say. NDT companies know a lot that their clients would find useful: what changed in a code edition, when to use TOFD instead of RT, why a PAUT scan plan matters, what a technician's certification actually covers. The problem is time. Writing a good email takes an engineer an hour they do not have.</p><p>The AI Marketing app in the Atlantis NDT ERP is built to close that gap. It drafts campaign emails with AI from a short brief, runs drip sequences by service line, and schedules sends, so marketing happens steadily in the background instead of in rare bursts. You stay in control of what goes out. The AI writes the first draft; your expertise decides what is right.</p><p>If that sounds like the gap in your business, <a href=\"/contact?service=erp&amp;subject=AI%20Marketing%20demo\">book an AI Marketing demo</a> and we will show you a campaign drafted for an NDT audience.</p><h2>Four kinds of campaign email, drafted by AI</h2><p>AI Marketing generates campaign emails in four types. Each suits a different job in an NDT company's marketing.</p><h3>Newsletter</h3><p>A regular update to clients and prospects: a capability you have added, a short technical explainer, upcoming training intakes, a reminder of the services you offer. Newsletters keep your name in front of maintenance planners and inspection engineers between jobs, so you are the first call when a shutdown scope lands.</p><h3>Promotion</h3><p>A focused message about one service: phased array weld inspection for fabrication shops, tank floor inspection ahead of a planned outage, a training course with seats left. Promotions work best sent to a narrow, relevant list.</p><h3>Nurture</h3><p>Educational emails for people who are not ready to buy yet. A nurture email might explain how to write a clear inspection scope, what information an NDT company needs to quote accurately, or how Level I, II and III responsibilities differ. Nurture builds trust with the engineers who will specify the work.</p><h3>Announcement</h3><p>News that deserves its own email: a new method added to your services, a new region covered, a new accreditation for your company, a new training programme, or a new way of delivering reports.</p><p>For each type, you give the AI a brief: who it is for, which service line it concerns and the key points. It returns a draft with a subject line and body. You then edit it, check every technical statement, and schedule or send. The draft is yours to change completely; the AI saves you the blank page, not the judgement.</p><h2>How AI drafting works in practice</h2><p>Here is a realistic example. Your operations manager mentions that the crew calendar looks light in a few weeks' time, and you want to fill it with MT and PT work from local fabrication shops.</p><ol><li>You open AI Marketing and choose a promotion email.</li><li>You write a short brief: the audience is fabrication shop QA managers and production managers; the service is MT and PT on structural and pressure welds; the points are short-notice availability, qualified technicians, clear reports and a link to send a scope.</li><li>The AI drafts a subject line and body in plain language.</li><li>You read it. You remove a line that overstates your turnaround, add the procedure standard your clients usually ask about, and tighten the call to action.</li><li>You send a test to yourself, check it on your phone, then schedule it for your fabrication shop list on Tuesday morning.</li></ol><p>The job takes minutes instead of an afternoon, and the final email still says what you would have said yourself.</p><p>A few rules make AI drafting work in a technical industry:</p><ul><li><strong>Brief it with facts.</strong> The AI writes from what you give it. Give it your real methods, sectors and service areas.</li><li><strong>Check every technical claim.</strong> A Level III or senior technician should read anything that mentions codes, acceptance criteria or techniques.</li><li><strong>Never let it invent results.</strong> Remove any figures, percentages or client names that you cannot back up. Engineers notice.</li><li><strong>Keep your voice.</strong> Edit the draft until it sounds like your company, not like a brochure.</li><li><strong>Keep it short.</strong> Site engineers read email on their phones between jobs. Three tight paragraphs and one clear action beat a page of text.</li></ul><h2>AI that can run on your own server</h2><p>Many NDT companies are wary of sending client information to outside AI services, and with good reason. Your client list, the sites you work at and the scopes you quote are commercially sensitive. Some of your clients may have contract clauses about how their information is handled.</p><p>AI Marketing uses an AI model that can run on your own server. That means drafting can happen on infrastructure you control, with your campaign briefs and contact details staying inside it. Where the model runs and which model is used is agreed with you during implementation, based on your hardware, your privacy requirements and the quality of drafts you need.</p><p>Running a model on your own server has practical trade-offs worth discussing openly:</p><ul><li>It needs a machine with enough capacity to run the model at a usable speed.</li><li>Smaller models are faster but produce plainer drafts; larger models write better but need more hardware.</li><li>You are not dependent on an outside AI service being available, or on its terms changing.</li></ul><p>Whatever you choose, the principle stays the same. The AI produces drafts. People in your company decide what is sent. Nothing about the AI removes the need for someone who understands NDT to read an email before it reaches a client.</p><p>The same approach applies to the AI-personalised email preview in the <a href=\"/erp/apps/crm\">CRM app</a>, where a salesperson generates a tailored follow-up for a single lead, reads it and edits it before sending. Nothing leaves without a person pressing send or deliberately enrolling a lead in a sequence.</p><h2>Drip sequences by service line</h2><p>A drip sequence is a series of emails sent to a contact over time, on a schedule you set, until they reply, buy or opt out. It is the most reliable way to stay in touch with the many leads who are genuinely interested but not ready yet.</p><p>In AI Marketing, drip sequences are organised by service line. That matters because an NDT company's audiences want very different things.</p><h3>Inspection sequence</h3><p>For plant engineers, maintenance planners and fabrication QA managers. A typical sequence might introduce your methods and sectors, explain how to prepare a scope for a quick and accurate quote, show what your reports include, and close with an invitation to discuss an upcoming outage. You can also mention that results can be placed on a 3D model of the asset with <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, Atlantis's companion product to the ERP's NDT Reports app.</p><h3>Training sequence</h3><p>For individuals and training coordinators. It might cover course levels and methods, what practical time looks like, how learners prepare between sessions, and upcoming intake dates.</p><h3>Consulting sequence</h3><p>For QA/QC managers and engineering leads. It might cover procedure writing and review, Level III services, supplier audits and reviews of a written practice.</p><p>Leads can be enrolled from the CRM with one action, so a salesperson who qualifies a nurture lead can hand it to the right sequence in seconds. Each sequence is drafted once with the AI's help, reviewed by the right people, and then runs on its schedule while your team gets on with the work.</p><h2>Pause, resume and unsubscribe</h2><p>Automation without an off switch is how companies end up annoying their best prospects. AI Marketing gives you three controls on drip sequences.</p><ul><li><strong>Pause</strong>: stop the sequence without losing its place. Useful when a lead picks up the phone and becomes a live opportunity, or when a client is in the middle of a shutdown and does not need marketing email.</li><li><strong>Resume</strong>: carry on from where it stopped when the time is right.</li><li><strong>Unsubscribe</strong>: recipients can opt out, and they stop receiving the sequence.</li></ul><p>These controls reflect how NDT sales actually works. A nurture lead who replies 'we have an outage in the spring, call me in January' should not receive three more generic emails before January. Pause, schedule an activity in the CRM for January, and resume later with something relevant.</p><p>Respecting opt-outs is also part of your legal and reputational obligations. The industry is small; the inspection engineer irritated by your emails today may be the contractor's QA manager next year. Privacy and marketing rules differ by country, so what consent you need before adding someone to a sequence is a decision for you and your advisers. The ERP helps you record and honour those choices.</p><p>A good rule of thumb: every email in a sequence should be one the recipient would be glad to receive even if they never buy from you. If an email fails that test, rewrite it or cut it.</p><h2>Scheduling around the NDT calendar</h2><p>Timing matters in this industry more than most. Scheduling lets you prepare campaigns in advance and send them when they are most likely to be read and acted on.</p><ul><li><strong>Shutdown and turnaround season.</strong> Plants plan outages months ahead. Inspection promotions sent while scopes are being written are far more useful than ones sent after contracts are awarded.</li><li><strong>Training intakes.</strong> Announce course dates early enough for employers to approve budgets and release people from site.</li><li><strong>Trade shows and conferences.</strong> Send a 'meet us at the stand' email before the event, and a follow-up afterwards to the people you met, many of whom you can capture on the day with the Business Cards app.</li><li><strong>Quiet periods.</strong> If your crew calendar looks light, a scheduled promotion to the right list can help fill it.</li><li><strong>Working hours and time zones.</strong> If you work across several countries, schedule so emails land in the morning where the recipient is.</li></ul><p>A simple content calendar goes a long way. Plan a regular newsletter, a handful of promotions a year aligned with your busy and quiet seasons, announcements when you have genuine news, and drip sequences running continuously in the background. Draft a few weeks ahead with the AI, review in one sitting, and schedule.</p><p>That turns marketing from something that happens when there is time into a steady routine one person can manage alongside their other work.</p><h2>What to write about: topics NDT buyers actually read</h2><p>The AI can draft quickly, but it needs good subjects. These are topics that inspection engineers, QA/QC managers and plant planners tend to find useful, as long as you write them from real experience.</p><ul><li><strong>Method selection</strong>: when UT is a better choice than RT, what TOFD adds, where phased array saves access time, what ET is good at on tubing.</li><li><strong>Preparing a scope</strong>: the information an NDT company needs to quote accurately, such as drawings, material, thickness, weld count, access and applicable code.</li><li><strong>Reading a report</strong>: what an inspection report should contain, and what 'acceptable with remarks' means for the person receiving it.</li><li><strong>Technician qualification</strong>: what Level I, II and III can and cannot do, and why the certification scheme on a technician's card matters to the client.</li><li><strong>Procedures</strong>: why a written, approved procedure matters and what a Level III looks for when reviewing one.</li><li><strong>New ways of presenting results</strong>: how inspection results placed on a 3D model of an asset help plant teams see where findings cluster across a unit.</li><li><strong>Training</strong>: how learners build practical skill between classroom sessions. Learners enrolled in the ERP's eLearning portal get access to <a href=\"/practical-ndt\">Practical NDT</a>, Atlantis's immersive 3D practice platform with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings. That is worth an announcement of its own.</li></ul><p>Avoid the things that make technical readers stop reading: vague claims, invented statistics, and anything that sounds like it was written by someone who has never been on a scaffold. Specific, useful and short wins every time.</p><h2>Who uses AI Marketing</h2><ul><li><strong>Owner or managing director</strong>: sets the themes, approves the tone and reviews key announcements.</li><li><strong>Business development</strong>: writes briefs, reviews drafts, enrols leads into sequences and pauses them when leads go live.</li><li><strong>Office manager or marketing coordinator</strong>: runs the calendar, schedules sends and keeps lists in order.</li><li><strong>NDT Level III</strong>: technical review of anything that mentions methods, codes or acceptance criteria.</li><li><strong>Training coordinator</strong>: training sequences and intake announcements.</li></ul><p>In a small company these may be two or three people. The point of AI Marketing is that none of them needs to be a professional copywriter. They need to know the work, write a clear brief and read critically.</p><p>Access rights decide who can create campaigns, who can edit sequences and who can send. Many companies let several people draft but limit sending to one or two, so nothing reaches a client list without a second look.</p><p>A simple routine keeps it running: drafts are created through the week as ideas come up, reviewed together in one short session, then scheduled. Sequences are checked every few months to retire anything out of date, such as old course dates or a service you no longer offer.</p><h2>How AI Marketing connects to the rest of the ERP</h2><ul><li><strong>CRM</strong>: leads carry service line, sector, NDT service type and a lead score from 0 to 100 banded hot, warm, nurture or cold. Nurture leads are natural candidates for drip sequences and can be enrolled from the lead.</li><li><strong>Contacts</strong>: the shared address book of clients, prospects, learners and partners your campaigns reach.</li><li><strong>Email Marketing</strong>: Odoo's standard mass mailing app, with mailing lists, an email editor and open and click tracking. Both apps work from the same contacts. See the <a href=\"/erp/apps/email-marketing\">Email Marketing app</a>.</li><li><strong>Business Cards</strong>: cards photographed at a trade show become CRM leads or mailing list members, ready for the post-event follow-up.</li><li><strong>Website</strong>: enquiry forms create CRM leads, which can then be enrolled in the right sequence.</li><li><strong>Quotations</strong>: when a nurture lead finally asks for a price, the opportunity moves to a quotation in the same system.</li></ul><p>Because everything shares one database, the lead a salesperson qualifies, the sequence it enters and the quotation it becomes are all visible in the same place. Nobody has to export a list from one tool and import it into another, and nobody has to wonder whether the client already heard from you this week.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys and configures the ERP for you. For AI Marketing, the work usually covers:</p><ol><li><strong>Where the AI runs</strong>: on your own server or another option agreed with you, and which model suits your hardware and the quality of drafts you need.</li><li><strong>Outgoing email</strong>: sending from your own domain, set up with the authentication mail providers expect so campaigns are less likely to land in spam.</li><li><strong>Service lines</strong>: the inspection, training and consulting lines your sequences follow.</li><li><strong>First sequences</strong>: an initial drip sequence for each service line, drafted with you and reviewed by your Level III.</li><li><strong>Lists and segments</strong>: connecting Contacts, CRM fields and mailing lists.</li><li><strong>Training</strong>: writing good briefs, reviewing drafts, scheduling, pausing and resuming.</li></ol><p>Anything specific to your company, such as an approval step before sending, is part of the customization scope agreed with you. The Atlantis NDT ERP is affordable, accessible and fully customizable, and pricing is quote on request. See every app in the system on the <a href=\"/erp/apps\">ERP apps page</a>.</p><h2>Frequently asked questions</h2><h3>Does the AI send emails without anyone checking?</h3><p>No. The AI drafts; a person reviews, edits and schedules or sends. Automated sending only happens through drip sequences you have set up and deliberately enrolled leads into, and those can be paused at any time.</p><h3>Where does the AI model run?</h3><p>AI Marketing uses a model that can run on your own server, so briefs and contact details can stay on infrastructure you control. The exact setup is agreed during implementation.</p><h3>What types of email can it draft?</h3><p>Four campaign types: newsletter, promotion, nurture and announcement. You brief it on audience, service line and key points, and it returns a subject line and body for you to edit.</p><h3>Can we run different sequences for inspection, training and consulting?</h3><p>Yes. Drip sequences are organised by service line, so each audience gets content that fits what they asked about.</p><h3>What happens when a lead replies or becomes a live opportunity?</h3><p>Pause their sequence and hand the lead to a salesperson in the CRM. You can resume later if the timing is not right yet.</p><h3>Is the AI reliable on technical content?</h3><p>Treat every draft as a draft. The AI can phrase things well but can also get technical details wrong, so anything about methods, codes or acceptance criteria should be checked by a Level III or senior technician.</p><h3>What does it cost?</h3><p>Pricing depends on your users, apps and customization scope, so it is by quote on request.</p><h2>Start marketing steadily, without hiring a marketing team</h2><p>If your company has plenty of expertise but no time to write about it, AI Marketing lets the people who know the work produce useful, regular emails in minutes. In a demo we draft a real campaign for your kind of clients, set up a sample drip sequence and show pause, resume and scheduling.</p><p><a href=\"/contact?service=erp&amp;subject=AI%20Marketing%20demo\">Book an AI Marketing demo</a> or <a href=\"/contact?service=erp&amp;subject=AI%20Marketing%20quote\">request a quote</a> for the Atlantis NDT ERP.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=AI%20Marketing%20demo\">Send an enquiry about AI Marketing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/email-marketing","publishedAt":"2026-09-27","title":"Email Marketing Software for NDT Companies | Atlantis NDT","description":"Send NDT newsletters, training intake notices and service campaigns to segmented client lists, track opens and clicks, respect opt-outs. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Email Marketing for NDT Companies: Campaigns to Clients and Learners</h1>\n<p>Newsletters and campaigns to clients and prospects. <a href=\"/contact?service=erp&amp;subject=Email%20Marketing%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why email still wins work in NDT</h2><p>NDT buyers are not scrolling social media looking for an inspection company. Maintenance planners, inspection engineers, QA/QC managers and fabrication shop owners do most of their business by email. Scopes arrive by email. Quotes go out by email. Reports go back by email. When a planner needs a crew for next month, they search their inbox for the last company that was helpful.</p><p>That is why a regular, useful email to clients and prospects is one of the best-value things an NDT company can do. It keeps your name in the inbox where decisions happen. It reminds past clients what else you do: the plant that only buys UT from you may not know you also run MT and PT, offer procedure writing or train technicians. It gives prospects a reason to remember you when a shutdown scope finally lands.</p><p>For most NDT companies the problem is not the idea, it is the tooling. Sending a newsletter from a desktop mail client with a long list in BCC is how emails end up in spam, and how people who asked to be removed keep getting them. Standalone mailing tools fix that, but then the list lives outside your CRM and goes out of date the day you export it.</p><p>The Email Marketing app in the Atlantis NDT ERP is Odoo's standard email marketing app, set up for an NDT company. It sends campaigns to the same contacts and leads your sales team works with every day, handles opt-outs properly and shows who opened and clicked. If you want to see it with your own lists, <a href=\"/contact?service=erp&amp;subject=Email%20Marketing%20demo\">book an Email Marketing demo</a>.</p><h2>Mailing lists that reflect your market</h2><p>Mailing lists are the foundation. In Odoo you can keep as many lists as you need, and a contact can belong to several. For an NDT company, lists usually follow the way you sell:</p><ul><li><strong>Inspection clients and prospects</strong>, often split by sector: refining and petrochemical, power, fabrication, marine, aerospace.</li><li><strong>Training</strong>: past learners, current enquirers and the employers who sponsor them.</li><li><strong>Consulting</strong>: QA/QC managers and engineering leads interested in procedures, Level III services and audits.</li><li><strong>Trade show contacts</strong>: people you met at a specific event, ready for the follow-up.</li><li><strong>Partners and subcontractors</strong>: other NDT companies you work with, for updates that concern them.</li></ul><p>People get onto lists through several routes: imported from a CSV file, added from Contacts or the CRM, subscribed through a form on your website, or added with one click from the Business Cards app after you photograph their card at an event.</p><p>Subscribers can manage their subscriptions and opt out of a list. That keeps your lists honest: the people on them are the people who want to hear from you.</p><p>A practical tip: start with fewer, larger lists and use filters for fine targeting, rather than dozens of tiny lists nobody maintains. You can always split a list later when you see a real need, such as a new sector you have started to serve or a training programme with its own audience.</p><h2>Building a campaign: editor, templates and test sends</h2><p>Odoo Email Marketing has a drag-and-drop editor with building blocks for text, images, buttons and columns. You do not need to know HTML to produce a clean, readable email that works on a phone.</p><p>For an NDT company, a small set of saved templates covers most needs:</p><ul><li><strong>Newsletter</strong>: your logo, a short technical note, a capability or service update, upcoming training dates and a clear link to request a quote.</li><li><strong>Single-service promotion</strong>: one service, one audience, one call to action.</li><li><strong>Training intake notice</strong>: course, level, method, dates and how to enrol.</li><li><strong>Event invitation and follow-up</strong>: before and after a trade show.</li><li><strong>Announcement</strong>: a new method, a new region covered, a new accreditation for your company.</li></ul><p>Before sending, send a test to yourself and one colleague. Read it on a phone, because many site engineers read email on mobile between jobs. Click every link. Check that the subject line would make sense to someone who has never heard of you.</p><p>Keep technical content honest. If an email mentions a code, a technique or acceptance criteria, have your Level III read it first. Your readers are engineers, and one wrong statement costs more credibility than ten good emails earn.</p><p>If writing is the bottleneck, the <a href=\"/erp/apps/ai-marketing\">AI Marketing app</a> drafts newsletters, promotions, nurture emails and announcements from a short brief, using an AI model that can run on your own server. You edit the draft and use it in your campaign, so the writing takes minutes rather than an afternoon.</p><h2>Targeting from your CRM and contacts</h2><p>Because Email Marketing lives in the same database as your CRM and Contacts, you are not limited to mailing lists. A mailing can be aimed at contacts or CRM leads directly, filtered on the fields you already keep.</p><p>That makes precise campaigns straightforward:</p><ul><li>Leads in the nurture band of the NDT lead score, in the inspection service line, from the fabrication sector.</li><li>Contacts tagged as past Level I learners who might be ready for Level II.</li><li>Leads whose site country is in a region you have just started to cover.</li><li>Contacts tagged as technical approvers at plants, for a technical note about a method.</li></ul><p>Targeting well is the single biggest thing you can do to make email work. A message about PAUT weld inspection sent only to fabrication QA managers is far more likely to get replies than the same message sent to everyone, and far less likely to prompt unsubscribes.</p><p>It also protects your sender reputation. Mail providers notice when recipients ignore or delete your emails. Relevant, targeted campaigns help keep your email landing in inboxes, including the inbox your next purchase order will come from.</p><p>The filter is saved with the mailing, so when you review results later you can see exactly who a campaign was aimed at. Over time that builds a clear picture of which segments of your market respond to which messages, which is useful well beyond email: it tells your sales team where to spend their time.</p><h2>Testing what works with A/B testing</h2><p>Odoo Email Marketing includes A/B testing. You create two or more versions of a mailing, send each to a portion of the audience, and then send the better-performing version to the rest, either chosen by you or picked automatically on a measure such as opens or clicks.</p><p>For an NDT company, the most useful things to test are simple:</p><ul><li><strong>Subject lines</strong>: 'Phased array weld inspection for fabrication shops' against 'Need weld inspection results before your client's audit?'</li><li><strong>Call to action</strong>: 'Request a quote' against 'Send us your scope'.</li><li><strong>Length</strong>: a short three-paragraph note against a fuller technical explainer.</li><li><strong>Sender</strong>: your company name against a named person at your company.</li></ul><p>Test one thing at a time, and only when the list is big enough for the result to mean something. On a small list, a difference of a few opens is noise, not a lesson. For smaller companies it is often better to run the same kind of test across several campaigns over a few months and look for a consistent pattern.</p><p>The lessons build up. Over time you learn what your audience responds to: whether engineers prefer plain technical subject lines, whether training contacts respond to dates or to career progression, whether a named sender gets more replies. That knowledge makes every future campaign better, including the briefs you give the AI when it drafts for you.</p><h2>Tracking: opens, clicks, replies and bounces</h2><p>Every mailing has statistics: how many were sent, delivered, opened, clicked, replied to and bounced. You can drill into each figure to see the individual recipients.</p><p>What to do with each number in an NDT context:</p><ul><li><strong>Opens</strong>: a rough signal of subject line and sender strength. Treat it as a trend, not an exact figure, because some mail apps block or pre-load tracking images.</li><li><strong>Clicks</strong>: far more meaningful. Someone who clicks 'Request a quote' or opens your training dates page is showing real interest. Those names deserve a personal follow-up.</li><li><strong>Replies</strong>: the best signal of all. A reply from a planner saying they have an outage coming up is a lead.</li><li><strong>Bounces</strong>: addresses that no longer work. People in this industry change employers often; a bounce is a prompt to find out who replaced them.</li></ul><p>Links in mailings are tracked, so you can see which content people actually cared about. If your newsletter has three items, a technical note, a service update and a training intake, the clicks tell you which one mattered to your readers.</p><p>Then turn activity into action. After each campaign, the business development person should look at who clicked and replied, and create or update CRM leads with a clear next step. That is where email marketing becomes inspection, training and consulting work: not in the open rate, but in the follow-up call a day later.</p><h2>Opt-outs, blacklist and deliverability</h2><p>Good email marketing depends on respecting the people who receive it, and on getting your emails into inboxes rather than spam folders.</p><h3>Unsubscribes and the blacklist</h3><p>Every mailing includes an unsubscribe link. When someone opts out, Odoo records it, and blacklisted addresses are excluded from future mass mailings. Nobody on your team has to remember to remove them by hand.</p><h3>Consent and privacy</h3><p>Marketing and privacy rules differ by country, and by whether the recipient is a business contact or an individual learner. What consent you need, and how you record it, is a decision for you and your advisers. The ERP gives you list subscriptions, opt-outs and a history on each contact to support the approach you choose; it does not by itself satisfy any particular law.</p><h3>Sending from your own domain</h3><p>During implementation, outgoing mail is set up to send from your company's domain with the authentication records mail providers expect, such as SPF and DKIM. That helps your campaigns, and your everyday quotes and reports, reach inboxes.</p><h3>List hygiene</h3><p>Remove bounced addresses, avoid bought lists, and do not mail large batches of people who have never heard of you. A smaller list of people who know you will do far more for your business than a large list that marks you as spam.</p><p>These basics protect more than your newsletters. Your sales team, report reviewers and accounts staff send from the same domain, and a damaged sender reputation can push quotes, reports and invoices into spam folders too.</p><h2>Campaign ideas for inspection, training and consulting</h2><h3>Inspection</h3><ul><li>A pre-outage note to plant planners, sent while shutdown scopes are still being written.</li><li>A capability note for fabrication shops on MT, PT and UT for weld inspection, with a link to send a scope.</li><li>A short explainer on the information you need to quote accurately.</li><li>An announcement about how you present results. With <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, Atlantis's companion product to the ERP's NDT Reports app, inspection results are placed on a 3D model of the asset, which gives asset owners a clearer picture of where findings sit.</li></ul><h3>Training</h3><ul><li>Intake notices with levels, methods and dates, sent to past learners and training sponsors.</li><li>A note on how learners practise between sessions. Learners enrolled in the ERP's eLearning portal get access to <a href=\"/practical-ndt\">Practical NDT</a>, Atlantis's immersive, game-like 3D practice platform with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings.</li><li>A reminder to employers to plan the next round of Level I and Level II training before the busy season.</li></ul><h3>Consulting</h3><ul><li>A short guide to what a procedure or written practice review involves.</li><li>An offer of Level III support for clients writing or updating procedures.</li><li>A note on preparing for a client or third-party audit of an NDT programme.</li></ul><p>Each of these works best sent to a targeted list with one clear action: send a scope, request a quote, enrol, or book a call.</p><h2>Email Marketing and AI Marketing: how they work together</h2><p>The Atlantis NDT ERP includes two marketing apps, and it helps to be clear about the difference.</p><p><strong>Email Marketing</strong> is Odoo's standard mass mailing app: mailing lists, the email editor, A/B testing, scheduling, tracking and opt-out handling. It is where you build and send campaigns to lists and filtered audiences.</p><p><strong>AI Marketing</strong> drafts campaign emails with AI in four types, newsletter, promotion, nurture and announcement, using an AI model that can run on your own server. It also runs drip sequences by service line, with pause, resume and unsubscribe, and scheduling.</p><p>In practice, many NDT companies use both:</p><ul><li>AI Marketing drafts the newsletter from a short brief; someone edits it and uses it in an Email Marketing campaign to your lists.</li><li>Drip sequences in AI Marketing handle ongoing nurture of individual leads from the CRM.</li><li>Email Marketing handles larger one-off sends, A/B tests and detailed tracking.</li></ul><p>Both work from the same contacts and leads. Whether you use one or both, and how, is agreed during implementation based on how much marketing your team wants to take on. Some companies start with a simple newsletter and add sequences later once the routine is established.</p><h2>Who uses Email Marketing</h2><ul><li><strong>Marketing coordinator or office manager</strong>: builds and schedules campaigns, maintains lists and templates.</li><li><strong>Business development</strong>: chooses audiences, follows up clicks and replies, and creates CRM leads from them.</li><li><strong>Owner or managing director</strong>: approves key campaigns and reviews results every few months.</li><li><strong>NDT Level III</strong>: technical review of anything that mentions methods, codes or acceptance criteria.</li><li><strong>Training coordinator</strong>: intake notices and updates to learners and sponsors.</li></ul><p>Access rights decide who can create mailings and who can send them. A common setup lets several people draft while one or two people send, so every campaign gets a second read before it reaches a client list.</p><p>In a small company one person may do most of this. The value of having email marketing inside the ERP is that this person works from the same records as sales and operations, instead of maintaining a separate list in a separate tool.</p><h2>How it connects, and what setup looks like</h2><p>Email Marketing draws on the rest of the ERP:</p><ul><li><strong>Contacts</strong>: the shared address book of clients, sites, learners, vendors and partners.</li><li><strong>CRM</strong>: leads with service line, sector, service type and lead score for precise targeting; see the <a href=\"/erp/apps/crm\">CRM app</a>.</li><li><strong>Business Cards</strong>: trade show cards added to a mailing list with one click.</li><li><strong>Website</strong>: forms that let visitors subscribe or send an enquiry.</li><li><strong>Surveys</strong>: client feedback questionnaires you can invite contacts to complete.</li></ul><p>Atlantis NDT deploys and configures the ERP for you. For Email Marketing, implementation usually covers outgoing mail on your domain, your first mailing lists and a CSV import of existing subscribers, saved templates in your branding, subscription forms on your website, and a short training session on building, testing and reviewing campaigns. Anything beyond the standard app is part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, and pricing is quote on request. See every app on the <a href=\"/erp/apps\">ERP apps page</a>.</p><h2>Frequently asked questions</h2><h3>Is this a custom email tool?</h3><p>No. It is Odoo's standard Email Marketing app, configured for an NDT company with lists, templates and targeting that suit inspection, training and consulting work.</p><h3>Can we send to CRM leads as well as mailing lists?</h3><p>Yes. Because it shares a database with the CRM and Contacts, a mailing can target leads or contacts filtered on fields such as service line, sector or lead score, as well as mailing lists.</p><h3>How are unsubscribes handled?</h3><p>Every mailing includes an unsubscribe link. Opt-outs are recorded, and blacklisted addresses are excluded from future mass mailings automatically.</p><h3>Can we see who opened and clicked?</h3><p>Yes. Each mailing shows sent, delivered, opened, clicked, replied and bounced figures, and you can drill down to the recipients behind each number.</p><h3>Will our emails avoid spam folders?</h3><p>Nobody can promise that, but sending from your own authenticated domain, targeting relevant lists and removing bounced addresses all help. Outgoing mail is set up on your domain during implementation.</p><h3>Do we need AI Marketing as well?</h3><p>Not necessarily. Email Marketing works on its own. AI Marketing adds AI drafting and drip sequences by service line, which helps if writing time is your bottleneck.</p><h3>What does it cost?</h3><p>Pricing depends on your users, apps and customization scope, so it is by quote on request.</p><h2>Stay in the inbox where the work is decided</h2><p>Your next inspection job, training booking or consulting engagement will very likely start with an email. A steady, relevant campaign to the right people makes sure that email comes to you. In a demo we set up sample lists from your kind of contacts, build a campaign, and walk through targeting, testing and tracking.</p><p><a href=\"/contact?service=erp&amp;subject=Email%20Marketing%20demo\">Book an Email Marketing demo</a> or <a href=\"/contact?service=erp&amp;subject=Email%20Marketing%20quote\">request a quote</a> for the Atlantis NDT ERP.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Email%20Marketing%20demo\">Send an enquiry about Email Marketing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/business-cards","publishedAt":"2026-09-27","title":"Business Card Scanner to CRM for NDT Firms | Atlantis NDT","description":"Photograph a business card and turn it into a scored NDT lead or mailing-list contact in one click. Part of Atlantis NDT ERP. Book a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Business Card Scanner for NDT Companies, Straight into Your CRM</h1>\n<p>Scan business cards from site visits and trade shows straight into CRM. <a href=\"/contact?service=erp&amp;subject=Business%20Cards%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>The pile of business cards nobody enters</h2><p>Every NDT company knows the pattern. Your operations manager comes back from a turnaround planning meeting with eight cards. Your Level III spends two days at a trade show and returns with a rubber-banded stack. Your sales lead meets a new QA/QC manager at a fabrication shop and slips the card into a wallet. A week later the cards are sitting on a desk, half of them still not in any system, and the follow-up that should have gone out while the conversation was fresh never happens.</p><p>This matters more in inspection than in most trades. NDT work is won on relationships and timing. A refinery inspection coordinator who mentioned a shutdown in the spring, an EPC project engineer who needs a PAUT crew for a pipe rack, a fabrication shop owner whose current RT subcontractor keeps missing dates: these are live opportunities, and each one sits on a small piece of card stock until someone types it in.</p><p>Typing it in is the problem. Nobody enjoys copying names, titles, mobile numbers and email addresses into a CRM at the end of a long day. Typos creep in, emails bounce, phone numbers lose their country code, and the card ends up in a drawer. The Business Cards app in Atlantis NDT ERP removes that step. You take a photo, the details are read for you, and one click turns the card into a CRM lead or a mailing-list contact.</p><h2>What the Business Cards app does</h2><p>The app is built around a single job: turn a photo of a business card into a clean contact record inside your ERP. It is part of Atlantis NDT ERP, our Odoo-based system pre-configured for inspection companies, so the contact lands in the same database your quotes, jobs, technicians and invoices already live in.</p><ul><li><strong>Photo capture and mobile upload.</strong> Snap the card with a phone or upload an image from your desktop. Salespeople and managers can do it on the spot, in the car park after the meeting, or on the flight home.</li><li><strong>AI/OCR extraction.</strong> The app reads the card and pulls out the name, company, job title, email address, phone numbers and website.</li><li><strong>Review before saving.</strong> You see the extracted fields and correct anything the scan misread, such as an unusual spelling or a stylised logo.</li><li><strong>One click to CRM.</strong> Create a CRM lead directly from the card, ready for your NDT-specific lead fields.</li><li><strong>One click to a mailing list.</strong> Or add the person to a mailing list for newsletters and announcements instead of treating them as an active opportunity.</li></ul><p>That is deliberately simple. The app does not try to be a full sales tool on its own; it feeds the CRM, Email Marketing and AI Marketing apps that already sit in the ERP. The value is that the card stops being a to-do item and becomes a record your team can act on the same day.</p><h2>How it runs day to day</h2><p>Here is what the workflow looks like for a typical inspection company after a client visit or an industry event.</p><ol><li><strong>Capture.</strong> The person who met the contact photographs the card on their phone and uploads it. If they collected twenty cards at a conference booth, they work through the stack one photo at a time while waiting at the gate.</li><li><strong>Extract.</strong> The app reads the image and fills in name, company, title, email, phones and website.</li><li><strong>Check.</strong> A quick glance to fix anything odd. Cards with two numbers, a landline and a mobile, are common in plant and EPC roles; both are captured.</li><li><strong>Decide.</strong> Is this a live opportunity or a relationship to keep warm? A turnaround manager asking about a crew for next quarter becomes a CRM lead. A peer from another inspection company might go on a mailing list instead.</li><li><strong>Enrich.</strong> On the lead, the salesperson adds what they learned in the conversation: service line, NDT service type, industry sector, site country, and rough estimates of technicians and days.</li><li><strong>Follow up.</strong> The lead can be enrolled in a drip email sequence or contacted directly, starting from an AI-personalised email preview.</li></ol><p>Nothing here needs admin rights or more than a few minutes of training. That is the point: the easier capture is, the more cards actually make it into the system, and the fewer opportunities go cold in a drawer.</p><h2>Where business cards come from in NDT work</h2><p>Inspection companies meet prospects in places generic sales software was never designed for. The Business Cards app fits the way NDT business actually gets done.</p><ul><li><strong>Trade shows and conferences.</strong> NDT, corrosion, welding, pipeline and oil and gas events generate stacks of cards in a few days. Capturing them the same evening means follow-ups go out while people still remember your booth.</li><li><strong>Site visits and pre-job meetings.</strong> When a crew mobilises to a refinery or petrochemical plant, the site supervisor often meets the client's inspection engineer, the maintenance planner and sometimes a third-party inspector. Each is a future contact.</li><li><strong>Turnaround and shutdown planning.</strong> Planning meetings bring together contractors, EPC coordinators and owner representatives. The person who hands you a card today may be allocating inspection scope next season.</li><li><strong>Fabrication shops and EPC offices.</strong> Visits to fabrication yards, pressure-vessel shops and structural steel fabricators often start with a card exchanged at reception.</li><li><strong>Training and consulting contacts.</strong> Technicians and QA managers who ask about Level I, II or III training or procedure consulting are worth keeping in touch with, even if they are not buying inspection services today.</li><li><strong>Vendors and partners.</strong> Equipment dealers, calibration labs and subcontract inspectors hand out cards too. They can be captured as contacts without cluttering your sales pipeline.</li></ul><p>Because all of these land in one database, your team can see, before the next meeting, who else in the company has already met that client and what was discussed.</p><h2>From card to qualified NDT lead</h2><p>A name and an email address are only the start. The CRM app in Atlantis NDT ERP carries fields that matter for inspection sales, so a scanned card becomes a lead your team can prioritise properly.</p><ul><li><strong>Service line and NDT service type.</strong> Is this about field inspection, a training enquiry, consulting or software? Which methods: UT, RT, MT, PT, PAUT, TOFD, ET?</li><li><strong>Industry sector.</strong> Refining, petrochemical, power generation, pipelines, fabrication, maritime, aerospace. The sector shapes the codes, the crew profile and the paperwork you will need.</li><li><strong>Site country.</strong> Where the work would actually happen, which is not always where the contact's office is.</li><li><strong>Estimated technicians and days.</strong> A rough size of the job, recorded while the conversation is fresh.</li><li><strong>Lead source.</strong> Which event, visit or referral produced the card, so you can later see which shows and activities are worth the travel.</li></ul><p>The CRM then gives each lead an NDT lead score from 0 to 100, grouped as hot, warm, nurture or cold. That helps a small sales team decide where to spend the week: the hot turnaround enquiry gets a phone call today, the cold contact goes into a nurture sequence.</p><p>If you already hold contacts in spreadsheets from earlier events, the CRM also supports lead import from CSV, so the backlog and the newly scanned cards end up in the same place, scored the same way.</p><h2>Following up without spamming anyone</h2><p>Capturing a card is useless if the follow-up is missing or clumsy. The Business Cards app hands contacts to the parts of the ERP that handle outreach.</p><p><strong>Personal follow-up.</strong> From the CRM lead, a salesperson can generate an AI-personalised email preview and edit it before sending. It is a starting draft, not an auto-send: you stay in control of the tone and the facts, which matters when you are writing to a plant inspection manager who remembers exactly what you promised.</p><p><strong>Drip sequences.</strong> A lead can be enrolled in a drip email sequence for its service line. The AI Marketing app runs these sequences with pause, resume and unsubscribe controls, plus scheduling so emails do not land in the middle of the night in the contact's time zone.</p><p><strong>Mailing lists.</strong> Contacts added to a mailing list receive your newsletters and announcements through Email Marketing: a new method capability, an updated training calendar, an expansion into a new region.</p><p><strong>Your own AI server.</strong> The AI Marketing app can use a model running on your own server, so the text of your campaigns and the contact details behind them do not have to go to a third-party AI service. For companies with confidentiality clauses in client contracts, that is worth discussing during implementation.</p><p>The result is a steady, human-sounding follow-up process that starts the day the card is scanned, without anyone maintaining a separate spreadsheet of people they meant to email.</p><h2>Who uses it in an NDT company</h2><table><thead><tr><th>Role</th><th>How they use Business Cards</th></tr></thead><tbody><tr><td>Owner / managing director</td><td>Scans cards from senior client meetings and industry events, and can see that every contact they meet is followed up by the team.</td></tr><tr><td>Business development / sales</td><td>Captures cards daily, creates CRM leads, fills in the NDT fields and enrols contacts in sequences.</td></tr><tr><td>Operations manager</td><td>Captures contacts met during mobilisation and turnaround planning, and flags follow-on work spotted on site.</td></tr><tr><td>Level III / technical manager</td><td>Scans cards from technical committees, audits and conferences, and routes training and consulting enquiries.</td></tr><tr><td>Site supervisors and senior technicians</td><td>Upload a card from their phone when a client engineer asks about extra scope on site.</td></tr><tr><td>Marketing / admin</td><td>Maintains mailing lists, checks data quality and runs newsletters and campaigns.</td></tr></tbody></table><p>Access follows the normal ERP user rights. A site supervisor can be allowed to upload cards and create leads without seeing your financial dashboard or the figures on your quotes. Those permissions are set during implementation to match how your company is organised.</p><p>The field side matters most. In inspection, many of the best leads are met by people who are not in sales at all. The technician who hears a client's QA manager complain about a slow RT subcontractor is holding a lead. Giving that person a quick way to get the card into the system is often the difference between winning follow-on work and hearing about it after it has gone to a competitor.</p><h2>How Business Cards connects to the rest of the ERP</h2><p>A standalone card scanner produces a contact list. Inside Atlantis NDT ERP, the card is the first step of a chain that runs all the way to the invoice.</p><ol><li><strong>Business Cards</strong> creates the contact and the CRM lead.</li><li><strong>CRM</strong> scores the lead, holds the NDT scope and tracks the conversation.</li><li><strong>Quotations</strong> turns the opportunity into a branded quote with job type, site, project dates and applicable codes, which the client can accept and sign online.</li><li><strong>Project and Team Assignments</strong> plan the job, dispatch technicians and block double-booking of people and equipment.</li><li><strong>NDT Reports</strong> captures the inspection results and sends the approved report.</li><li><strong>Invoicing</strong> bills the job, with labour, equipment and consumables subtotals.</li></ol><p>Because the contact record is shared, the client engineer whose card was scanned at a conference is the same person who later receives the quote and the inspection report. No re-typing between systems, no second copy of an email address with a typo in it.</p><p>You can read about the other modules on the <a href=\"/erp/apps\">ERP apps overview</a>, or see how the whole system fits together on the <a href=\"/erp\">Atlantis NDT ERP page</a>. Contacts also arrive the other way: enquiries submitted through your company <a href=\"/erp/apps/website\">website</a> land in the same CRM as your scanned cards.</p><h2>Show new contacts something worth remembering</h2><p>A follow-up email is stronger when it gives the prospect something concrete to look at. Two Atlantis products tend to start good conversations with the people you meet.</p><p><strong><a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></strong> is our companion product to the ERP's NDT Reports app. It places inspection results on a 3D model of the asset, so a plant owner can see where readings and findings sit on the equipment instead of flipping through pages of tables. It is a separate product that works alongside the ERP. For asset owners and inspection engineers, a short demo often says more than a brochure.</p><p><strong><a href=\"/practical-ndt\">Practical NDT</a></strong> is an immersive, game-like 3D practice platform for UT, PAUT, RT, MT, PT, VT, ET and TOFD, with scenarios on virtual welds, pipes, vessels and castings. Learners enrolled in the ERP's eLearning portal get a Practical NDT section that opens the platform. For contacts who manage technicians or training budgets, it is a natural topic after a meeting.</p><p>Your follow-up sequences can reference either product, depending on the industry sector and service line recorded against the lead.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys and configures the ERP for you. For Business Cards the work is light, but a few decisions shape how useful it becomes.</p><ul><li><strong>Who can scan.</strong> We agree which users get the app on mobile and whether field staff can create leads or only contacts.</li><li><strong>Lead fields and sources.</strong> We set up your service lines, NDT service types, industry sectors and lead sources so scanned cards are categorised consistently.</li><li><strong>Mailing lists.</strong> We create the lists you actually use, for example clients, training prospects, partners and vendors.</li><li><strong>Sequences.</strong> We help you set up drip sequences per service line, written in your own voice.</li><li><strong>AI model choice.</strong> We discuss where the AI extraction and email drafting run, including the option of a model on your own server.</li><li><strong>Existing contacts.</strong> Spreadsheet contacts can be brought in through the CRM's CSV import so old and new records live together.</li></ul><p>Anything beyond this, such as extra fields specific to your market or an approval step before a lead is created, becomes part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, and the quote reflects what you actually need.</p><p>Want to watch a card go from photo to scored lead? <a href=\"/contact?service=erp&amp;subject=Business%20Cards%20demo\">Book a Business Cards demo</a>.</p><h2>Frequently asked questions</h2><h3>What details does the app read from a business card?</h3><p>Name, company, job title, email address, phone numbers and website. You can check and correct them before the record is saved.</p><h3>Can I scan cards from my phone?</h3><p>Yes. Mobile upload is supported, so you can photograph a card right after a meeting on site or at an event and create the lead straight away.</p><h3>Does every scanned card become a sales lead?</h3><p>No, you choose. One click creates a CRM lead; another adds the person to a mailing list. Vendors, peers and partners can stay as contacts without cluttering your pipeline.</p><h3>Can scanned leads go into an email sequence?</h3><p>Yes. A lead can be enrolled in a drip email sequence from the CRM. Sequences support pause, resume and unsubscribe, and you decide which sequence fits each service line.</p><h3>Where does the AI run?</h3><p>The AI Marketing features can use a model running on your own server. Where extraction and drafting run for your installation is agreed during implementation.</p><h3>Is Business Cards sold on its own?</h3><p>It is part of Atlantis NDT ERP, which is configured for your company. Pricing is quote on request, based on the apps and customization you need.</p><h3>Can we import the contacts we already have?</h3><p>Yes. The CRM supports lead import from CSV, so contacts from old spreadsheets and past events sit alongside newly scanned cards.</p><h2>Stop losing leads in a drawer</h2><p>The people you meet on site and at events are some of the most valuable contacts your NDT company has, and most of them never make it into a system. Business Cards fixes that first step so the rest of the ERP can do its job. <a href=\"/contact?service=erp&amp;subject=Business%20Cards%20quote\">Request a quote for Atlantis NDT ERP</a> and we will walk you through the full chain from card to invoice.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Business%20Cards%20demo\">Send an enquiry about Business Cards</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/website","publishedAt":"2026-09-27","title":"Website for NDT Companies, Linked to Your ERP | Atlantis NDT","description":"An NDT company website built on your ERP: enquiry forms feed the CRM, courses and quotes live online. Affordable and fully customizable. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Website for NDT Companies, Connected to Your ERP and CRM</h1>\n<p>Company website and enquiry forms connected to CRM. <a href=\"/contact?service=erp&amp;subject=Website%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why most NDT company websites work against the business</h2><p>Look at how enquiries reach a typical inspection company. A contact form on the website sends an email to a shared inbox. Someone forwards it to sales. Sales asks the prospect the same questions again: which method, which site, which code, how many welds, when. The enquiry is copied into a spreadsheet, maybe into a CRM, maybe not. If the right person is on leave or on a shutdown, the email sits unread while the client asks two other companies for a price.</p><p>Meanwhile the website itself is maintained by an outside agency, and every small change costs a request and a wait. A new method capability, a new accreditation, a revised training schedule: none of it reaches the site quickly, so the site slowly drifts away from what the company actually does.</p><p>The Website app in Atlantis NDT ERP takes a different approach. Your company website runs on the same Odoo-based system as your CRM, quotations, eLearning and invoicing. Enquiries submitted on the site become CRM records directly. Your own team can edit pages without calling anyone. And the online parts of your business, such as training courses and quote acceptance, sit on the same site your clients already know.</p><p>It is the standard Odoo website app, set up by Atlantis NDT for an inspection company. We do not pretend it is a custom web platform; its strength is that it is connected to everything else you run.</p><h2>What the Website app gives an NDT company</h2><p>Here is what you get once Atlantis NDT has set it up for you.</p><ul><li><strong>Your company site on your domain.</strong> Home page, services, industries, about, contact and any other pages you need, built with the Odoo website editor.</li><li><strong>Editing without a developer.</strong> Your office manager or marketing lead can change text, swap photos and add pages in the browser using drag-and-drop building blocks.</li><li><strong>Enquiry forms that feed CRM.</strong> Contact and quote-request forms create records in the CRM app, where they sit next to leads from business cards, email campaigns and imports.</li><li><strong>Page titles and descriptions.</strong> Each page has its own title and description settings, so search engines see sensible text for your service pages.</li><li><strong>A home for your training.</strong> The eLearning course portal is published on the same website, so learners find courses where they find the rest of your company.</li><li><strong>Online quote acceptance.</strong> Quotations sent from the ERP can be opened, accepted and signed online by the client, using the standard Odoo quote flow.</li></ul><p>Everything else, such as extra languages, particular page layouts or a specific look and feel, is set up during implementation as part of the scope agreed with you.</p><h2>Pages an inspection company site actually needs</h2><p>Clients who buy NDT are usually engineers. They scan a website for specifics, not slogans. During setup we help you structure the site around what they look for.</p><ul><li><strong>Services by method.</strong> Separate pages for UT, PAUT, TOFD, RT, MT, PT, VT, ET and whatever else you offer, saying what equipment and techniques you use and what kind of components you inspect.</li><li><strong>Industries.</strong> Refining and petrochemical, power, pipelines, fabrication, maritime, aerospace. A plant inspection engineer wants to see that you understand their work, their codes and their shutdown pressure.</li><li><strong>Company qualifications.</strong> Your quality system and company accreditations. These can be kept current in the ERP's Certificates app, which records company certifications with alert days, so the site is updated when something is renewed.</li><li><strong>Technician qualification approach.</strong> How your technicians are qualified and certified and how you track it, without publishing individual personal data.</li><li><strong>Training and consulting.</strong> If you train technicians or advise on procedures, give those services their own pages.</li><li><strong>Contact and request a quote.</strong> Clear forms, a phone number and an office address.</li></ul><p>You decide the content and the voice. We make sure the structure is sensible and each important page ends with a way to get in touch.</p><h2>Enquiry forms that arrive as CRM leads</h2><p>The most important thing a company website does is turn a visitor into a conversation. In Atlantis NDT ERP, a form submitted on your site does not go to an inbox and wait. It becomes a CRM record your sales team can see, assign and act on.</p><p>A generic contact form asks for a name, an email and a message. For NDT that is not enough to quote. During implementation we design your enquiry forms around the questions your estimators always ask, for example:</p><ul><li>Which inspection methods are needed</li><li>Where the site is, and in which country</li><li>Which industry the work is for</li><li>What kind of components or welds are involved</li><li>Which codes or client specifications apply</li><li>Rough dates and duration</li><li>Whether the enquiry is for inspection, training, consulting or software</li></ul><p>The exact fields and how they map to the CRM are part of the configuration we agree with you. Once in the CRM, the enquiry sits alongside the NDT-specific lead fields: service line, NDT service type, industry sector, site country, and estimated technicians and days. The CRM gives leads an NDT lead score from 0 to 100, grouped as hot, warm, nurture or cold, so a website enquiry about a turnaround next month does not get lost behind a general question.</p><p>The same CRM also receives leads from the <a href=\"/erp/apps/business-cards\">Business Cards app</a>, so everything your team collects, online or in person, lives in one pipeline.</p><h2>What happens after someone submits a form</h2><p>Here is how a typical website enquiry moves through the ERP.</p><ol><li><strong>Submission.</strong> A QA/QC manager at a fabrication shop fills in your request-a-quote form asking for RT and UT on a batch of pressure vessel welds.</li><li><strong>Lead created.</strong> The form creates a CRM record with the details entered. Sales sees it in the pipeline.</li><li><strong>Qualification.</strong> The salesperson reviews it, fills in any missing NDT fields and checks the lead score. If more detail is needed, they reply from the CRM, starting from an AI-personalised email preview they can edit.</li><li><strong>Quotation.</strong> The opportunity becomes a branded quote in the Quotations app, with job type, site, project dates and applicable codes, built from your NDT service products.</li><li><strong>Online acceptance.</strong> The client opens the quote online, accepts it and signs, and it converts to a sales order.</li><li><strong>Delivery and billing.</strong> The job moves into Project and Team Assignments, then NDT Reports and Invoicing.</li></ol><p>If the enquiry is not ready to buy, the lead can be enrolled in a drip email sequence for its service line instead, with pause, resume and unsubscribe controls, so the contact hears from you at a sensible pace rather than being chased or forgotten.</p><h2>Training courses and Practical NDT on your website</h2><p>If your company trains technicians, the website is where learners arrive. The ERP's eLearning app publishes a course portal on the same site, organised in Level I, Level II and Level III sections, with video lessons, quizzes and certificates of completion. Online course sales are supported, and admins create learner accounts and grant or revoke access. Learners get their own dashboard showing progress.</p><p>Enrolled learners also get a Practical NDT section inside the portal. <a href=\"/practical-ndt\">Practical NDT</a> is Atlantis's immersive, game-like 3D practice platform, with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings. Access is granted automatically on enrolment or manually by an admin. For a training provider, it gives learners hands-on practice between classroom sessions, and it gives your website something distinctive to show.</p><p>Because the course portal and the company site are the same system, a learner who enquires about a course through a website form becomes a CRM lead, and once enrolled, the same contact record carries through to the course. No separate learning platform with its own logins and its own contact list to reconcile.</p><p>If your company does not run training, the eLearning portal can stay unpublished, or it can be used internally for technician refresher material. That choice is made during implementation.</p><h2>Show clients what your reports look like</h2><p>Asset owners increasingly ask how inspection results will be delivered, not just what they will cost. Your website is a good place to answer that.</p><p>The ERP's NDT Reports app produces method-specific reports for 17 report types, with a draft, review, approval and sending workflow, and branded PDF output. For clients who want more than a PDF, Atlantis also offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model of the asset. A plant engineer can see where each finding sits on the equipment instead of cross-referencing drawings and tables.</p><p>Many NDT companies use their website to explain their reporting approach, show a sample report layout and invite asset owners to see a demo. When a prospect asks through your site to see how their inspection data would be presented, that request arrives in the CRM like any other enquiry, tagged with the right service line.</p><p>This is where a connected website pays off. The page that describes your reporting, the form the client fills in, the quote you send and the report you eventually deliver all come from the same system, under the same brand.</p><h2>Who works on the website</h2><table><thead><tr><th>Role</th><th>What they do on the Website app</th></tr></thead><tbody><tr><td>Owner / managing director</td><td>Approves the structure and messaging, and watches which enquiries the site brings in through the CRM pipeline.</td></tr><tr><td>Marketing or office manager</td><td>Edits pages, updates photos and news, keeps service and training pages current.</td></tr><tr><td>Business development / sales</td><td>Picks up website enquiries in the CRM, qualifies them and sends quotes.</td></tr><tr><td>Level III / technical manager</td><td>Reviews technical content on method and industry pages so it stays accurate.</td></tr><tr><td>Training coordinator</td><td>Maintains the course portal, learner access and course pages.</td></tr><tr><td>Finance</td><td>Sees accepted quotes flow through to sales orders and invoices.</td></tr></tbody></table><p>User rights keep these roles separate. The person who edits the website does not need access to invoices, and a technical reviewer does not need to see the sales pipeline. We set those rights up during implementation.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys the ERP and sets the website up for you. A typical website setup covers:</p><ul><li><strong>Domain and branding.</strong> Connecting your domain, applying your logo, colours and fonts to the site theme.</li><li><strong>Page structure.</strong> Agreeing the main pages: services by method, industries, company qualifications, training, consulting, contact.</li><li><strong>Content migration.</strong> Moving the useful content from your existing site, and rewriting what no longer reflects your services.</li><li><strong>Enquiry forms.</strong> Designing NDT-specific forms and mapping them to CRM fields.</li><li><strong>Page titles and descriptions.</strong> Setting sensible titles and descriptions for your main pages.</li><li><strong>eLearning portal.</strong> Publishing the course portal if you train, and deciding how course sales and learner access work.</li><li><strong>Quote acceptance.</strong> Setting up online quote acceptance and signature so clients can approve from the link in your email.</li><li><strong>Training your editors.</strong> Showing your team how to edit pages themselves.</li></ul><p>Extra languages, more complex page designs or additional integrations are scoped with you up front. The ERP is affordable, accessible and fully customizable, with pricing quote on request. To see the website, CRM and quote flow working together, <a href=\"/contact?service=erp&amp;subject=Website%20app%20demo\">book a Website app demo</a>.</p><h2>Frequently asked questions</h2><h3>Is the website a separate system from the ERP?</h3><p>No. It is the Odoo website app running inside Atlantis NDT ERP, so forms, the course portal and online quotes all use the same database as your CRM and invoicing.</p><h3>Can our own staff edit the website?</h3><p>Yes. Pages are edited in the browser with drag-and-drop building blocks. We train your editors during implementation.</p><h3>Do website enquiries go straight into the CRM?</h3><p>Yes. Enquiry forms create CRM records, where they get the NDT lead fields and lead score like any other lead.</p><h3>Can we keep our existing domain?</h3><p>Yes. Your domain is connected to the new site as part of setup, and useful content from the old site is carried over.</p><h3>Will the website guarantee search rankings?</h3><p>No website can guarantee rankings. The app lets you set page titles and descriptions and publish specific service pages, which gives search engines clear content to work with.</p><h3>Can we sell training courses online?</h3><p>Yes. The eLearning portal supports online course sales, and enrolled learners get access to Practical NDT from inside the portal.</p><h3>How much does it cost?</h3><p>Pricing is quote on request and depends on the apps, pages and customization you need.</p><h2>Make your website part of how you win work</h2><p>A website that sends enquiries into an inbox is a brochure. A website connected to your CRM, quotes, courses and reports is a working part of the business. See how the pieces fit on the <a href=\"/erp\">Atlantis NDT ERP page</a>, browse the other <a href=\"/erp/apps\">ERP apps</a>, or <a href=\"/contact?service=erp&amp;subject=Website%20app%20quote\">request a quote for your NDT company website</a>.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/quotations\">Quotations</a>: Inspection quotes built from rates, crews and scope, sent for e-signature.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Website%20demo\">Send an enquiry about Website</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/purchase","publishedAt":"2026-09-27","title":"NDT Purchase Order Software for Equipment | Atlantis NDT","description":"Buy NDT instruments, probes, consumables and calibration services with accredited-lab tracking and POs tied to equipment serials. Request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Purchasing Software for Equipment, Calibration and Consumables</h1>\n<p>Purchase orders for consumables, film, couplant and equipment. <a href=\"/contact?service=erp&amp;subject=Purchase%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Buying for an NDT company is not like buying office supplies</h2><p>Purchasing in an inspection company looks simple from the outside. In practice it is full of small, expensive traps. A flaw detector goes out for calibration, and three months later nobody can find the PO or the certificate that came back with it. A replacement PAUT probe is ordered, but the order says only \"probe\", so when the client's auditor asks which instrument it was bought for, someone has to dig through emails. A calibration lab's accreditation lapses and nobody notices until a client's QA department rejects a calibration certificate from that lab.</p><p>Consumables are their own headache. Couplant, magnetic particle inks, penetrant, developer, cleaner, PPE and site stationery get bought in a hurry when a crew is about to mobilise, usually from whichever supplier answers the phone first. Stock levels live in someone's head. The night shift discovers the last can of developer is empty.</p><p>The Purchase app in Atlantis NDT ERP is the standard Odoo purchasing app, extended for how NDT companies buy. It knows the difference between an equipment manufacturer, a dealer and a calibration lab. It records whether a lab is accredited, with the accreditation number and expiry. And it lets you tie a purchase order line to the specific equipment serial it is for. Those are small additions, but they are the ones that make purchasing records hold up in an audit.</p><h2>What the Purchase app does</h2><p>Out of the box you get the usual purchasing flow: requests for quotation, purchase orders, receipts into stock and vendor bills matched to orders. On top of that, Atlantis NDT ERP adds the fields that matter to an inspection company.</p><ul><li><strong>Vendor types.</strong> Suppliers are classified as OEM, dealer or calibration lab, so you can filter who makes your instruments, who sells them and who calibrates them.</li><li><strong>Accredited-lab flag.</strong> Calibration labs can be marked as accredited, with the accreditation number and its expiry date recorded against the vendor.</li><li><strong>NDT purchase type.</strong> Each purchase carries an NDT purchase type so equipment, services and consumables can be told apart in reports. The categories are set up during implementation to match how you buy.</li><li><strong>Order lines linked to an equipment serial.</strong> A line can point to a specific instrument or probe by serial number, so a calibration, repair or accessory purchase is attached to the item it was for.</li></ul><p>Because the app shares a database with Asset Management, Inventory and Invoicing, a purchase is not an isolated document. It connects to the equipment record, the stock level and the accounts.</p><h2>Knowing who you buy from: OEMs, dealers and calibration labs</h2><p>Most NDT companies deal with the same handful of supplier types over and over, and each one matters for a different reason.</p><p><strong>OEMs.</strong> Instrument manufacturers are where firmware, spare parts and factory repairs come from. When a flaw detector needs a board replaced or a PAUT unit needs a factory service, the OEM relationship is the one that counts. Tagging these vendors lets you see at a glance which manufacturers your fleet depends on.</p><p><strong>Dealers.</strong> Many companies buy instruments, probes, cables and accessories through regional dealers rather than directly. Dealers often handle rentals, loan units and quick replacements. Keeping them separate from OEMs makes it clear who to call for what.</p><p><strong>Calibration labs.</strong> This is where record-keeping carries the most weight. Clients, auditors and third-party inspectors ask who calibrated an instrument and whether that lab was accredited at the time. Being able to answer from the vendor record, with the accreditation number and expiry, is much better than hunting for a scanned certificate in a shared folder.</p><p>Suppliers of consumables, PPE and general services sit alongside these as normal vendors. The point is not to overcomplicate the supplier list. It is to make the few distinctions that come up in audits and client questions easy to see and easy to report on.</p><h2>Calibration purchasing that holds up in an audit</h2><p>Calibration is where purchasing and quality meet. In Atlantis NDT ERP, the purchase and the calibration record live in the same system.</p><p>When an instrument is due for calibration, you raise a purchase order to the lab, with the order line linked to that instrument's serial number. The vendor record shows whether the lab is flagged as accredited and when its accreditation expires. If the accreditation is out of date, you can see that before you send the instrument, not after the certificate comes back.</p><p>When the instrument returns, the calibration itself is recorded in Asset Management: provider, certificate number, standard used, range, stated uncertainty, whether the lab was accredited, the result (pass, fail or conditional) and the next due date. The calibration certificate register holds the lab's accreditation number, the certificate PDF and a valid, expiring or expired status, with expiry alerts. The Certificates app can send configurable daily email alerts for calibration certificates, so the next round of purchase orders is prompted in good time.</p><p>Put together, you can answer the questions auditors actually ask: which lab calibrated this unit, were they accredited, what did it cost the job, where is the certificate, and when is it due again. And Team Assignments warns when equipment assigned to a job is out of calibration, so a unit that missed its calibration run does not quietly go to site.</p><h2>Buying against a specific instrument</h2><p>Linking purchase order lines to an equipment serial sounds like a detail. Over the life of an instrument it builds a complete spending history.</p><p>Think about everything a single ultrasonic flaw detector or PAUT unit consumes over its life: the initial purchase, annual calibrations, a replacement battery pack, a damaged cable, a new wedge, a firmware update by the OEM, a repair after it was dropped on a scaffold. When each of those purchases points to the same serial number, you can open the instrument and see what it has actually cost to keep in service.</p><p>That helps with real decisions:</p><ul><li><strong>Repair or replace.</strong> An older unit that keeps coming back for repairs is easier to retire when the spend is visible in one place.</li><li><strong>Rental versus ownership.</strong> Asset Management can record rental rates, so you can compare owning and running an instrument with renting it for occasional scope.</li><li><strong>Maintenance cause and effect.</strong> The maintenance log in Asset Management records preventive and corrective work, repairs, cleaning, firmware updates and probe replacements with condition before and after. The purchase that paid for each one sits alongside it.</li><li><strong>Client questions.</strong> When a client asks about the history of an instrument used on their job, you have one record to show, not a folder of emails.</li></ul><p>Invoicing lines can also carry an equipment serial, so the same instrument can be traced from what you spent on it to what you billed for its use.</p><h2>Consumables without the last-minute scramble</h2><p>Consumables rarely get attention until they run out. The Purchase app works with Asset Management and Inventory to keep them under control.</p><p>In Asset Management, consumables such as chemicals, PPE, stationery and couplant have a reorder level and a low-stock flag, and every movement is written to a ledger. When a crew draws penetrant, developer and cleaner for a job, the stock goes down. When it falls to the reorder level, the item is flagged as low. That is the prompt for purchasing to raise an order before the next mobilisation, not during it.</p><p>A few practical habits make this work well for NDT companies:</p><ul><li><strong>Preferred suppliers per item.</strong> Record who you normally buy each consumable from, so a request for quotation goes to the right vendor quickly.</li><li><strong>Purchase type for consumables.</strong> Keeping consumables as their own NDT purchase type lets you see how much you spend on them compared with equipment and services.</li><li><strong>Receipts into stock.</strong> Receiving a delivery updates stock, so the low-stock flag clears when the order actually arrives.</li><li><strong>Job costing.</strong> Invoicing shows consumables as their own subtotal, so what you buy and what you bill can be compared job by job.</li></ul><p>The <a href=\"/erp/apps/inventory\">Inventory app</a> page explains how stock of equipment and consumables is held and moved.</p><h2>How purchasing runs day to day</h2><p>A typical week in an NDT company's purchasing looks like this once the ERP is in place.</p><ol><li><strong>Alerts arrive.</strong> Daily email alerts flag calibration certificates approaching expiry, and the consumables list shows which items are below their reorder level.</li><li><strong>Requests go out.</strong> The purchasing or operations lead raises requests for quotation to the right vendors: the accredited lab for calibrations, the dealer for probes and cables, the usual supplier for couplant and PPE.</li><li><strong>Orders are confirmed.</strong> Quotes are compared and converted to purchase orders. Calibration and repair lines are linked to the instrument serial numbers they cover.</li><li><strong>Goods and services come back.</strong> Consumables are received into stock. Instruments return from calibration, and the calibration record and certificate are entered in Asset Management.</li><li><strong>Bills are matched.</strong> Vendor bills are checked against the purchase orders before payment.</li><li><strong>Costs are visible.</strong> The financial dashboard shows cost of sales, operating expenses and bills alongside revenue.</li></ol><p>Nothing here relies on someone remembering. The system prompts, the records connect, and when an auditor or client asks, the answer is already filed.</p><h2>Who uses the Purchase app</h2><table><thead><tr><th>Role</th><th>How they use Purchase</th></tr></thead><tbody><tr><td>Owner / finance manager</td><td>Approves larger orders, reviews spend on equipment, calibration and consumables, and watches costs on the financial dashboard.</td></tr><tr><td>Operations manager</td><td>Makes sure equipment and consumables are ready before mobilisation and raises urgent orders.</td></tr><tr><td>Equipment / stores coordinator</td><td>Manages calibration and repair orders, links them to serial numbers and receives goods into stock.</td></tr><tr><td>QA/QC manager or Level III</td><td>Checks that calibration labs are accredited and that certificates are recorded before equipment is released.</td></tr><tr><td>Accounts</td><td>Matches vendor bills to purchase orders and handles payments.</td></tr></tbody></table><p>Approval steps and who can confirm orders above a certain size are set up during implementation according to how your company works.</p><h2>How Purchase connects to the rest of the ERP</h2><p>Purchasing is only useful when it feeds the rest of the business. In Atlantis NDT ERP it connects to:</p><ul><li><strong>Asset Management</strong> for calibration records, the calibration certificate register, maintenance logs and consumable reorder levels.</li><li><strong>Inventory</strong> for stock of equipment by serial number and of consumables.</li><li><strong>Certificates</strong> for daily email alerts on calibration certificates and company certifications.</li><li><strong>Team Assignments</strong> for warnings when assigned equipment is out of calibration.</li><li><strong>Invoicing</strong> for equipment and consumables subtotals on client invoices, and the financial dashboard.</li></ul><p>On the reporting side, method reports in the NDT Reports app reference the instruments used, and in marine mode the report PDF can merge the calibration certificate. For asset owners who want results on a 3D model of their plant, Atlantis also offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a companion product that works alongside the ERP. If you train technicians, the ERP's eLearning portal gives learners access to <a href=\"/practical-ndt\">Practical NDT</a>, our 3D practice platform with UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios.</p><p>The full list of modules is on the <a href=\"/erp/apps\">ERP apps overview</a>, and the <a href=\"/erp\">Atlantis NDT ERP page</a> explains the system as a whole.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys and configures the ERP for your company. For Purchase, setup usually includes:</p><ul><li><strong>Vendor import and classification.</strong> Bringing in your supplier list and tagging each vendor as OEM, dealer, calibration lab or general supplier.</li><li><strong>Lab accreditation details.</strong> Entering accreditation numbers and expiry dates for the labs you use.</li><li><strong>Purchase types.</strong> Agreeing the NDT purchase types you want to report on.</li><li><strong>Products.</strong> Setting up consumables, spares and service products, with reorder levels for consumables.</li><li><strong>Equipment link.</strong> Making sure your instrument register in Asset Management is loaded, so purchase lines can point to real serial numbers.</li><li><strong>Approvals and taxes.</strong> Setting approval rules and the taxes that apply in your country.</li></ul><p>Anything specific to your business, such as extra approval stages or particular purchase reports, becomes part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, with pricing on request. <a href=\"/contact?service=erp&amp;subject=Purchase%20app%20demo\">Book a Purchase app demo</a> to see calibration purchasing run end to end.</p><h2>Frequently asked questions</h2><h3>Can we record whether a calibration lab is accredited?</h3><p>Yes. Calibration lab vendors have an accredited-lab flag, with the accreditation number and expiry date recorded on the vendor.</p><h3>Can a purchase order be tied to a specific instrument?</h3><p>Yes. Order lines can be linked to a specific equipment serial, so calibrations, repairs and accessories are attached to the item they were bought for.</p><h3>Will the system remind us when calibrations are due?</h3><p>Yes. Calibration records carry a next due date, the certificate register shows expiring and expired status, and configurable daily email alerts cover calibration certificates.</p><h3>Does it handle consumables like couplant and penetrant?</h3><p>Yes. Consumables have reorder levels and a low-stock flag in Asset Management, and purchases received update stock.</p><h3>Can we match supplier bills to orders?</h3><p>Yes. Vendor bills are matched against purchase orders using the standard Odoo purchasing and accounting flow.</p><h3>Is the Purchase app priced separately?</h3><p>It is part of Atlantis NDT ERP, configured for your company. Pricing is quote on request.</p><h2>Put your purchasing records to work</h2><p>Every calibration, repair and can of couplant you buy says something about how your company runs. With purchases tied to vendors, labs and serial numbers, that information becomes useful instead of buried. <a href=\"/contact?service=erp&amp;subject=Purchase%20app%20quote\">Request a quote for Atlantis NDT ERP</a> and tell us how you buy today.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing</a>: Invoices from timesheets and completed jobs, with payments and reminders.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Purchase%20demo\">Send an enquiry about Purchase</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/inventory","publishedAt":"2026-09-27","title":"NDT Inventory: Equipment and Consumables Stock | Atlantis NDT","description":"Track NDT instruments by serial, issue and return kit with approvals, block double-booking and keep consumables above reorder level. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Inventory Management for Equipment and Consumables</h1>\n<p>Stock of consumables, sources and equipment across sites. <a href=\"/contact?service=erp&amp;subject=Inventory%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Where is the flaw detector?</h2><p>Ask that question in most NDT companies and you get a round of phone calls. Someone thinks it went to the refinery job. Someone else thinks it came back and is in the van. The technician who had it last is on leave. Meanwhile a crew is mobilising tomorrow and the job needs two UT sets, a PAUT unit and a yoke, and nobody is sure which of them are in calibration.</p><p>Equipment is one of the largest investments an inspection company makes, and it spends most of its life away from the office: on sites, in vehicles, at calibration labs, in repair, or lent to another crew. Consumables are scattered even more widely: couplant, penetrant, developer, cleaner, magnetic particle inks, PPE and stationery in the store, in site boxes and in vans.</p><p>Spreadsheets and whiteboards cannot keep up with that. They go stale the moment someone forgets to update them, and they cannot stop two supervisors promising the same instrument to two different jobs.</p><p>The Inventory app in Atlantis NDT ERP, working together with the Asset Management app, gives you one place where every instrument is tracked by serial number and every consumable has a stock level. It is built on the standard Odoo inventory app and configured for the way NDT companies actually move kit around.</p><h2>What the Inventory app does for an NDT company</h2><p>Inventory and Asset Management split the work between them. Inventory holds stock: what you have and where it is. Asset Management holds the detail and the rules around each piece of equipment.</p><ul><li><strong>Equipment by serial number.</strong> Every instrument, probe and related item is tracked individually, with equipment type, assigned person, condition, asset tag, firmware and accessories.</li><li><strong>Lifecycle status.</strong> Each item is new, active, in calibration, in repair, rented out, retired or disposed, so you can see at a glance what is available.</li><li><strong>Issue and return.</strong> Equipment goes out and comes back through a workflow with supervisor and manager approval, and its condition is recorded at both ends.</li><li><strong>Reservations.</strong> Kit can be reserved for upcoming jobs, with clash prevention so the same item cannot be promised twice.</li><li><strong>Movement records.</strong> Inbound and outbound movements are logged.</li><li><strong>Consumables.</strong> Chemicals, PPE, stationery, couplant and similar items have a reorder level, a low-stock flag and a movement ledger.</li><li><strong>Stock locations.</strong> Standard Odoo stock locations can represent your main store, branch offices, vans or site containers, set up during implementation.</li></ul><h2>Tracking instruments by serial through their whole life</h2><p>An ultrasonic flaw detector is not interchangeable with another one of the same model. It has its own calibration history, its own firmware, its own accessories and its own repair record. Clients and auditors care which specific unit was used. That is why Atlantis NDT ERP tracks equipment by serial number rather than as a quantity on a shelf.</p><p>For each item you can see:</p><ul><li><strong>What it is.</strong> Equipment type, asset tag, firmware version and the accessories that belong with it, such as cables, wedges and batteries.</li><li><strong>Who has it.</strong> The assigned person and its current condition.</li><li><strong>Where it is in its life.</strong> New, active, in calibration, in repair, rented out, retired or disposed.</li><li><strong>Calibration.</strong> Calibration frequency and status, with calibration records holding provider, certificate number, standard, range, uncertainty, accredited-lab flag, result and next due date.</li><li><strong>Maintenance.</strong> A log of preventive, corrective, repair, cleaning, firmware update and probe replacement work, with condition before and after.</li><li><strong>Rental.</strong> Rental rates can be recorded for items you rent out to other companies.</li></ul><p>When an instrument is in calibration or repair, it shows as such, so nobody plans a job around a unit that is sitting at a lab. When it is retired, it stays on record with its history rather than disappearing from a spreadsheet.</p><h2>Issuing and returning equipment with approvals</h2><p>Most equipment disputes come down to one question: what condition was it in when it left, and what condition was it in when it came back? The issue and return workflow answers that.</p><ol><li><strong>Request.</strong> A technician or site supervisor requests the equipment needed for a job.</li><li><strong>Approval.</strong> The request is approved by a supervisor and a manager, following the approval chain set for your company.</li><li><strong>Issue.</strong> The item is issued, its condition is recorded, and it is now assigned to that person.</li><li><strong>On site.</strong> The instrument is shown as issued. Dashboards can flag issued equipment that is overdue for return.</li><li><strong>Return.</strong> The item comes back, its condition is recorded again, and it is available for the next job.</li></ol><p>If a probe comes back with a damaged face or a cable is missing, the difference between the issue and return records shows it straight away. A maintenance entry can then be logged, and a repair or replacement can be bought through the Purchase app with the order line linked to that serial number.</p><p>For technicians in the field, the ERP's REST API for field devices includes a view of equipment issued to them, so they know exactly which serials they are responsible for. Over time, the record also shows patterns: which kit gets damaged most often, and on which kinds of work.</p><h2>No more double-booked equipment</h2><p>Double-booking is one of the most common and most avoidable problems in inspection operations. Two supervisors plan two jobs for the same week, both assume the PAUT unit is free, and one crew finds out at the store the morning they are due to leave.</p><p>Atlantis NDT ERP blocks this in two places.</p><p><strong>Reservations in Asset Management.</strong> Equipment can be reserved against an upcoming need, and clash prevention stops a second reservation for the same item over the same period.</p><p><strong>Team Assignments.</strong> When a job is planned as a team assignment, double-booking of equipment serial numbers is blocked, just as double-booking of technicians is. The assignment also warns when an item assigned to the job is out of calibration, so a unit that missed its calibration date does not go to site by accident.</p><p>Together, these mean the operations manager can plan the week knowing the kit on the plan actually exists, is free and is fit to use. When there really are not enough instruments to cover the work, you find out while there is still time to rent, borrow or reschedule, and the record of rentals helps you judge whether buying another unit makes sense.</p><p>Because Timesheets and Invoicing lines can also carry an equipment serial, the instrument that was reserved and issued is the same one that is booked to the job and billed to the client.</p><h2>Consumables that do not run out on the night shift</h2><p>Consumables are cheap individually and painful when missing. A crew on a night shift with no developer, no couplant or the wrong batch of MT ink loses hours. Inventory and Asset Management keep consumables under control without making anyone count cans every day.</p><ul><li><strong>Reorder level.</strong> Each consumable has a reorder level. When stock drops to that level, the item is flagged as low.</li><li><strong>Movement ledger.</strong> Every issue to a job and every receipt from a supplier is written to a ledger, so you can see where stock went.</li><li><strong>Locations.</strong> Stock held in the main store, a branch or a site container can be kept apart, so a shortage at one location is visible even when the total looks fine.</li><li><strong>Replenishment.</strong> Low-stock items become purchase requests in the Purchase app, and receipts update stock when goods arrive.</li><li><strong>Billing.</strong> Consumables have their own subtotal on invoices, so material used on a job can be recovered where the contract allows it.</li></ul><p>The detail you track is up to you. Some companies track every aerosol can; others track consumables by the box and only watch the fast movers closely. That level is agreed during implementation.</p><h2>How inventory runs day to day</h2><p>Here is a normal week for the stores or equipment coordinator once the system is in place.</p><ol><li><strong>Monday planning.</strong> Team Assignments shows the week's jobs, with equipment reserved against each one. Any calibration warnings on assigned kit are dealt with first.</li><li><strong>Kit preparation.</strong> Equipment for the next mobilisations is issued through the approval workflow, with condition recorded. Consumables for each job are issued from stock.</li><li><strong>Check the dashboards.</strong> The NDT KPI dashboard shows equipment calibration due and overdue, and issued equipment overdue for return.</li><li><strong>Replenish.</strong> Low-stock consumables are ordered through Purchase. Instruments due for calibration are sent to the lab, and their status changes to in calibration.</li><li><strong>Returns.</strong> Kit coming back from site is returned, condition is recorded, and any damage leads to a maintenance entry.</li><li><strong>Receipts.</strong> Supplier deliveries and returning calibrated instruments are booked in. Calibration records and certificates are added in Asset Management.</li></ol><p>The coordinator is no longer the only person who knows where everything is. The system knows, and anyone with access can check.</p><h2>Who uses Inventory</h2><table><thead><tr><th>Role</th><th>How they use Inventory and Asset Management</th></tr></thead><tbody><tr><td>Stores / equipment coordinator</td><td>Issues and receives equipment and consumables, records condition, manages locations and replenishment.</td></tr><tr><td>Operations manager</td><td>Reserves kit for jobs, approves issues, checks availability before accepting new work.</td></tr><tr><td>Site supervisor</td><td>Requests kit for the crew, returns it at demobilisation and reports damage.</td></tr><tr><td>Technicians</td><td>See the equipment issued to them and return it at the end of the job.</td></tr><tr><td>QA/QC manager or Level III</td><td>Checks calibration status and records before equipment is released to site.</td></tr><tr><td>Finance</td><td>Sees equipment and consumables charges on invoices and costs on the financial dashboard.</td></tr></tbody></table><p>User rights and the approval chain for issuing equipment are set up during implementation to match your organisation.</p><h2>How Inventory connects to the rest of the ERP</h2><p>Inventory is the physical side of the ERP. It links to:</p><ul><li><strong>Asset Management</strong> for serial-level equipment detail, calibration, maintenance, reservations and consumables rules.</li><li><strong><a href=\"/erp/apps/purchase\">Purchase</a></strong> for buying equipment, consumables and calibration services, with order lines tied to serial numbers and accredited-lab details on vendors.</li><li><strong>Team Assignments</strong> for blocking double-booking of equipment and warning about out-of-calibration items.</li><li><strong>Timesheets and Invoicing</strong> for equipment serials on time entries and invoice lines, and equipment subtotals on invoices.</li><li><strong>Fleet</strong> for vehicles used to carry kit, including whether a vehicle can carry radioactive sources and its transport licence number and expiry.</li><li><strong>NDT Reports</strong> for the instruments and calibration details referenced on method reports.</li></ul><p>For asset owners who want inspection results shown on a 3D model of their plant, Atlantis offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a companion product that works alongside the ERP's NDT Reports app. If you train technicians, enrolled learners in the ERP's eLearning portal can open <a href=\"/practical-ndt\">Practical NDT</a>, our 3D practice platform, and try UT, PAUT, RT, MT, PT, VT, ET and TOFD on virtual welds, pipes, vessels and castings before they handle your real instruments.</p><p>See every module on the <a href=\"/erp/apps\">ERP apps overview</a> or read about the full system on the <a href=\"/erp\">Atlantis NDT ERP page</a>.</p><h2>Setup and implementation</h2><p>Atlantis NDT deploys and configures the ERP for you. For Inventory, setup usually includes:</p><ul><li><strong>Equipment register.</strong> Loading your instruments, probes and accessories by serial number, with type, asset tag, firmware, lifecycle status and calibration frequency.</li><li><strong>Calibration history.</strong> Entering current calibration records and certificates so due dates and alerts are right from day one.</li><li><strong>Locations.</strong> Setting up stock locations for your store, branches, vans or site containers.</li><li><strong>Consumables.</strong> Creating consumable products with reorder levels.</li><li><strong>Approval chain.</strong> Configuring who approves equipment issues.</li><li><strong>Dashboards.</strong> Setting up the NDT KPI views your operations team will check each day.</li></ul><p>Anything beyond this becomes part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, with pricing quote on request. <a href=\"/contact?service=erp&amp;subject=Inventory%20app%20demo\">Book an Inventory demo</a> and bring your current equipment list; we will show you how it would look in the system.</p><h2>Frequently asked questions</h2><h3>Can we track each instrument individually?</h3><p>Yes. Equipment is tracked by serial number, with type, assigned person, condition, asset tag, firmware, accessories, lifecycle status and calibration status.</p><h3>Does the system stop two jobs booking the same instrument?</h3><p>Yes. Reservations have clash prevention, and Team Assignments blocks double-booking of equipment serial numbers.</p><h3>Will it warn us about equipment that is out of calibration?</h3><p>Yes. Team Assignments warns when assigned equipment is out of calibration, and dashboards show calibration due and overdue.</p><h3>How do we control equipment going to site?</h3><p>Through the issue and return workflow, with supervisor and manager approval and condition recorded at issue and return.</p><h3>Can we manage consumables like couplant and penetrant?</h3><p>Yes. Consumables have a reorder level, a low-stock flag and a movement ledger, and replenishment runs through the Purchase app.</p><h3>Can we see what an instrument has cost to keep in service?</h3><p>Yes. Purchase order lines can be linked to an equipment serial, and the maintenance log records repairs, firmware updates and probe replacements against the same item.</p><h3>How is it priced?</h3><p>Inventory is part of Atlantis NDT ERP, configured for your company. Pricing is quote on request.</p><h2>Know where your kit is, every day</h2><p>Your equipment earns money only when it is on site, calibrated and in the right hands. Inventory and Asset Management make sure you know where every serial is and what state it is in, and that consumables are there when the crew needs them. <a href=\"/contact?service=erp&amp;subject=Inventory%20app%20quote\">Request a quote for Atlantis NDT ERP</a> and stop running your equipment from a whiteboard.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing</a>: Invoices from timesheets and completed jobs, with payments and reminders.</li><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Inventory%20demo\">Send an enquiry about Inventory</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/expenses","publishedAt":"2026-09-27","title":"NDT Expense Management Software for Field Crews | Atlantis NDT","description":"Field expenses, per diems and receipts for NDT technicians, approved and re-billed to the right job. Book a demo of Expenses in Atlantis NDT ERP.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Expense Management for Field Technicians</h1>\n<p>Field expenses and per diems, approved and rebilled to jobs. <a href=\"/contact?service=erp&amp;subject=Expenses%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why field expenses are a headache for NDT companies</h2><p>An NDT company spends money in places the office never sees. A Level II technician drives four hours to a refinery shutdown, checks into a motel, buys couplant at the nearest hardware store because the drum on the truck ran dry, eats three meals a day on site and pays for parking at the contractor gate. A week later a crumpled envelope of receipts lands on someone’s desk. Half of them have faded, some are in a currency nobody expected, and none of them has the job number on it.</p><p>Then the questions start. Which job was this for? Was the motel covered by the client under the contract, or is it part of the day rate? Did the supervisor approve the extra night? Did the couplant purchase already go on the invoice that went out on Friday? By the time anyone works it out, the invoice has gone, the cost is buried in overheads and the job looks more profitable on paper than it really was.</p><p>Expenses in Atlantis NDT ERP is the standard Odoo Expenses app, set up for the way inspection crews actually spend money. Technicians record the expense when it happens, attach a photo of the receipt, pick the job it belongs to and submit it. Supervisors approve it and accounts reimburses it. Anything the client agreed to pay for can be pushed onto the job, so it ends up on the invoice and doesn’t get lost.</p><p>This page walks through how that works for a company with technicians in the field, what it connects to, and what we set up for you during implementation.</p><h2>What the Expenses app does</h2><p>At its core the app does five things, and none of them are exotic. It captures an expense with a date, amount, category, description and receipt. It links that expense to the employee who spent the money and, where you choose, to the project or sales order it belongs to. It groups expenses into a report that goes through an approval step. It posts approved expenses to accounting. And it either reimburses the employee or, for company-paid items, records the cost against the right account.</p><p>For an NDT company, the value is in how those five things are set up:</p><ul><li><strong>Expense categories that match field work.</strong> Mileage, fuel, lodging, meals and per diem, site parking, tolls, consumables bought on site, PPE, courier of film or reports, and whatever else your crews routinely spend on. Each category maps to the right account, so your accountant stops reclassifying.</li><li><strong>Fixed-amount categories for per diems.</strong> Where you pay a flat daily allowance, the category can carry a set unit cost. The technician enters the number of days instead of typing an amount.</li><li><strong>Job links.</strong> Every expense can carry the project or sales order it belongs to, so the cost follows the job.</li><li><strong>Re-billing.</strong> Categories can be set to re-invoice at cost or at an agreed sales price, so client-rechargeable items flow through to the invoice.</li><li><strong>Who paid.</strong> Each line records whether the employee paid (and needs paying back) or the company paid with a company card.</li></ul><p>None of this needs custom code. It is standard Odoo functionality, configured around NDT work during your implementation, and it sits in the same database as your jobs, timesheets, technicians and invoices.</p><h2>How it runs day to day for a field technician</h2><p>The technician side has to be quick, or it doesn’t happen. Nobody finishing a twelve-hour shift on a tank floor wants to fill in a form with fifteen fields.</p><ol><li><strong>Snap the receipt.</strong> From a phone browser, the technician opens Expenses, creates a new line and attaches a photo of the receipt. If you want it, we can also set up an expenses email alias, so forwarding a receipt creates the expense.</li><li><strong>Pick the category and job.</strong> Choose “Lodging” or “Per diem” and select the job from a short list. Default values can pre-fill the obvious fields.</li><li><strong>Add a note if it’s unusual.</strong> “Extra night, client delayed the permit to work” is the sentence that saves an argument two weeks later.</li><li><strong>Submit.</strong> At the end of the trip, or at the end of the week, the technician bundles the lines into an expense report and submits it for approval.</li></ol><p>That’s all the field side has to do. The technician can see where each report stands (submitted, approved, paid) without phoning the office to ask.</p><p>For crews on long rotations, like a six-week shutdown, we usually recommend weekly reports rather than one giant report at the end. It keeps approvals small and lets you re-bill as you go on jobs invoiced weekly. It also means a lost phone doesn’t cost you a month of receipts.</p><p>A note on connectivity. The ERP’s dedicated offline field app is built for inspection reports, not expenses. Expenses are entered through the normal ERP in a phone browser, so a technician in a dead zone photographs the receipt and logs the line once they have signal back at the hotel. In practice that’s when most people do it anyway.</p><h2>Approvals: supervisors, project managers and accounts</h2><p>Approvals are where expense control either works or turns into a pile of unread emails. In Odoo Expenses, each employee has an expense manager, usually their line manager or crew supervisor, who receives the submitted report and approves or refuses it. Refused reports go back to the technician with a reason, and the technician can fix and resubmit them.</p><p>For NDT companies we typically set up the chain like this:</p><ul><li><strong>Crew supervisor or lead technician</strong> confirms the expense actually happened on the job, checks the per diem days match the days on site, and approves.</li><li><strong>Operations or project manager</strong> can be the approver instead, if your supervisors don’t have system access or you prefer approval to sit with whoever owns the job margin.</li><li><strong>Accounts</strong> posts the approved report to the ledger and pays it, either as a bank payment or through payroll, depending on how you reimburse.</li></ul><p>The approval screen shows the receipt image beside the line, so the approver isn’t opening attachments one by one. Because each line carries the job, approvers can filter down to their own jobs.</p><p>Every approval, refusal and comment is logged in the record’s chatter with a name and timestamp. So when a client queries a recharged hotel bill six weeks after the invoice, you can show exactly who approved it, when, and what the note said. That audit trail is standard. For companies working under an ISO 9001 quality system, it’s the kind of record auditors like to see, even though expenses aren’t strictly in scope.</p><p>If you want a policy rule, for example that lodging above a set nightly limit needs a manager’s sign-off rather than a supervisor’s, we agree it during implementation and configure it as part of your customization scope.</p><h2>Re-billing field costs to the client</h2><p>This is where Expenses pays for itself. Most NDT contracts say something about travel, lodging and consumables. Some costs are included in the day rate, some are rechargeable at cost and some at cost plus handling. The contract is rarely the problem. The problem is that the recharge depends on a receipt reaching the person who raises the invoice, on time, with the job number on it.</p><p>In Odoo Expenses, each expense category has a re-invoicing policy:</p><ul><li><strong>No re-invoicing</strong> for costs you absorb, such as the technician’s commute or items built into the day rate.</li><li><strong>At cost</strong> for items the client pays as spent, such as lodging on a remote site or a courier of RT film.</li><li><strong>At sales price</strong> for items you recharge at an agreed rate, such as mileage per kilometre or mile, or a fixed daily subsistence allowance.</li></ul><p>When an approved expense linked to a sales order is posted, the rechargeable amount appears as a line on that sales order, ready for the next invoice. The person raising the invoice doesn’t have to chase receipts because they’re already there.</p><p>In Atlantis NDT ERP, invoices carry NDT-specific headers: NDT project, job or PO number, site, invoice type and industry sector, with subtotals for labour, equipment and consumables. Lines can carry cost centre, method, equipment serial, technician, rate type and days or hours. That means recharged expenses land on an invoice your client’s accounts department can actually match to their PO. You can read more on the <a href=\"/erp/apps/invoicing\">Invoicing app</a> page.</p><p>What you get in practice is fewer rechargeable costs quietly written off, and fewer awkward calls asking a client to add something to an invoice they’ve already paid.</p><h2>Per diems, mileage and rotation allowances</h2><p>In most inspection companies, per diems cause more expense noise than anything else. Technicians away from home for a shutdown, a pipeline spread or a fabrication yard audit get a daily allowance, and the rules differ by client, by country and sometimes by site.</p><p>Set up properly in Expenses, per diems become boring, which is what you want:</p><ul><li>A <strong>per diem category</strong> with a fixed unit cost. The technician enters the number of days and the amount works itself out.</li><li><strong>Separate categories</strong> where rates differ, for example domestic versus international, or a client-specified subsistence rate that you recharge at a sales price.</li><li>A <strong>mileage category</strong> with a unit cost per distance, used by technicians who drive personal vehicles to site.</li></ul><p>The supervisor’s check is simple: do the per diem days match the days the technician was actually on the job? Timesheets in the ERP record work type (inspection, travel, standby, setup), site and client for each day, so the approver has something to compare against instead of relying on memory. If a technician logged five days of site timesheets and claimed seven days of per diem, the gap is easy to spot.</p><p>Where company vehicles are used, the ERP’s Fleet app tracks vehicle assignments to projects and drivers, with dates and mileage. That makes it easy to spot a fuel claim for a vehicle that was assigned to someone else that week. We agree with you during setup which vehicle costs go through Expenses and which are paid centrally.</p><p>How you treat per diems for tax and payroll depends on your country, and your accountant sets that up with us during implementation. Expenses records and approves the claim. The accounting treatment follows your local rules.</p><h2>Who uses Expenses in an NDT company</h2><table><thead><tr><th>Role</th><th>What they do in Expenses</th></tr></thead><tbody><tr><td>Field technician (Level I, II or III)</td><td>Records expenses with receipts, links them to the job, submits reports, and tracks status and reimbursement.</td></tr><tr><td>Crew supervisor or lead technician</td><td>Approves or refuses team expenses, adds notes, checks per diem days against time on site.</td></tr><tr><td>Operations or project manager</td><td>Sees expense cost per job, approves exceptions, decides what is rechargeable on a given contract.</td></tr><tr><td>Accounts and finance</td><td>Posts approved reports, reimburses employees, reconciles company card spend, checks recharges reach invoices.</td></tr><tr><td>Owner or general manager</td><td>Sees expense totals in the financial dashboard alongside revenue, cost of sales and gross margin.</td></tr><tr><td>Office administrator</td><td>Enters expenses for technicians who still hand in paper receipts, if you allow it.</td></tr></tbody></table><p>Access rights are set per role. A technician sees their own expenses, a supervisor sees their team’s, and accounts sees everything. During setup you decide whether supervisors can see only the jobs they run or all jobs.</p><p>In smaller NDT companies it’s common for the owner to be the approver and the accountant as well. That’s fine. The app works the same with one approver as with fifty, and the job links still pay off when it’s time to invoice.</p><p>For larger companies with several branches or bases, expenses can be split by department or cost centre as well as by job. That way each base manager sees their own field spend and the owner still gets the full picture.</p><h2>How Expenses connects to the rest of Atlantis NDT ERP</h2><p>Expenses is useful on its own. Connected to the rest of the ERP, it answers the question every NDT owner asks at month end: did this job make money?</p><ul><li><strong>Project.</strong> NDT jobs in the Project app carry job type, site, client PO, methods, codes, and the assigned technicians and equipment. Expenses linked to the job sit alongside the labour and equipment costs.</li><li><strong>Timesheets.</strong> Hours by work type, method and site give approvers something to check per diem and travel claims against, and they feed billing.</li><li><strong>Team Assignments.</strong> Mobilisation and demobilisation dates on each assignment tell you when a technician should have been travelling or on site.</li><li><strong>Invoicing.</strong> Rechargeable expenses land on the sales order and then the invoice. The financial dashboard shows revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, bills and expenses over a 12-month view.</li><li><strong>Purchase and Inventory.</strong> Planned purchases of consumables and equipment go through Purchase, and Expenses covers the unplanned buy on site. Keeping the two separate stops your consumables stock from drifting.</li><li><strong>Employees.</strong> Every expense belongs to an employee record, the same record that holds the technician’s NDT profile. See the <a href=\"/erp/apps/employees\">Employees app</a>.</li><li><strong>NDT Reports.</strong> The inspection report for the job lives in the same database. If you also use Atlantis’s companion <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, the results can be placed on a 3D model of the asset, so the whole job, from travel costs to findings, is traceable.</li></ul><p>Because it’s one database, there’s nothing to export, nothing to re-key and no second system to reconcile. The job number the technician picks for a receipt is the same job number on the report, the timesheet and the invoice.</p><p>For the full list of what’s included, see the <a href=\"/erp/apps\">Atlantis NDT ERP apps overview</a> or the main <a href=\"/erp\">NDT ERP</a> page.</p><h2>What implementation looks like</h2><p>Expenses is one of the quicker apps to set up, but the setup decisions matter. Atlantis NDT deploys and configures the ERP for you. For Expenses we work through:</p><ol><li><strong>Your expense policy.</strong> What technicians can claim, the per diem rules, mileage, lodging limits and what needs a receipt. If you don’t have a written policy, we help you write down the one you already use informally.</li><li><strong>Categories and accounts.</strong> A category list that matches your field spend, each mapped to the right expense account, with taxes set up for your country.</li><li><strong>Re-invoicing rules.</strong> Which categories recharge at cost, which at a sales price and which never. Contract-specific exceptions are handled per job.</li><li><strong>Approvers.</strong> Who approves for whom, and what happens when a supervisor is on leave.</li><li><strong>Reimbursement method.</strong> Bank payment, payroll, or both, plus how company cards are handled if you issue them.</li><li><strong>Mobile setup.</strong> Getting technicians logged in on their phones and, if you want one, an email alias for forwarding receipts.</li><li><strong>Training.</strong> A short walkthrough for technicians (it takes minutes) and a longer one for approvers and accounts.</li></ol><p>Anything beyond standard Expenses, such as a specific approval rule or a report layout your client insists on, gets scoped with you and configured as part of the customization agreed at the start. The ERP is built to be affordable for NDT companies of any size, and pricing is quote on request.</p><p>Want to see it with your own expense categories? <a href=\"/contact?service=erp&amp;subject=Expenses%20demo\">Book an Expenses demo</a> and we’ll take a real field trip from receipt to invoice.</p><h2>Frequently asked questions</h2><h3>Can technicians submit expenses from their phones?</h3><p>Yes. Technicians use the ERP in a phone browser to create expense lines, attach receipt photos and submit reports. We can also set up a receipt email alias, so forwarding a receipt creates an expense.</p><h3>Can expenses be re-billed to the client automatically?</h3><p>Yes, if the expense is linked to a sales order. Each category is set to not re-invoice, to re-invoice at cost, or to re-invoice at a sales price. Approved rechargeable expenses appear on the sales order ready for invoicing.</p><h3>How do you handle per diems?</h3><p>With a fixed-cost expense category. The technician enters the number of days and the amount is calculated for them. Separate categories cover different rates, such as domestic, international or client-specific.</p><h3>Does Expenses work offline on remote sites?</h3><p>No, Expenses needs a connection. The offline field app in Atlantis NDT ERP is for inspection reports. Technicians photograph receipts on site and log them once they have signal, usually the same evening.</p><h3>Can we record expenses in other currencies?</h3><p>Yes. Odoo supports multiple currencies, so a technician working abroad can record an expense in the local currency and it converts for accounting. We set up currencies and rates during implementation.</p><h3>Who approves expenses?</h3><p>Whoever you set as the employee’s expense manager, usually the crew supervisor or project manager. Accounts then posts and pays. Every step is logged with a name and time.</p><h3>Is Expenses included in Atlantis NDT ERP?</h3><p>Yes. It’s one of the standard apps we set up for NDT companies. Pricing for the ERP is quote on request.</p><h2>Stop losing field costs between the site and the invoice</h2><p>If recharging costs depends on someone remembering to hand in an envelope, some of them are probably being written off. Expenses in Atlantis NDT ERP keeps the receipt, the job and the approval in one place, and moves the rechargeable part onto the invoice.</p><p>Tell us how your crews travel and spend today, and we’ll show you how it would run in your ERP. <a href=\"/contact?service=erp&amp;subject=Expenses%20quote\">Request a quote for Atlantis NDT ERP</a>, or ask for a demo that covers Timesheets and Invoicing too.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing</a>: Invoices from timesheets and completed jobs, with payments and reminders.</li><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Expenses%20demo\">Send an enquiry about Expenses</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/employees","publishedAt":"2026-09-27","title":"NDT Employee Management Software for Technicians | Atlantis NDT","description":"One record per NDT technician: certs, levels, methods, radiation badge, medical fitness and availability. Book a demo of Employees in Atlantis NDT ERP.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Employee and Technician Records Software</h1>\n<p>Technician records, levels, documents and contracts. <a href=\"/contact?service=erp&amp;subject=Employees%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>One record per technician, not five spreadsheets</h2><p>Ask most NDT companies where a technician’s information lives and the honest answer is: everywhere. Contact details are in the payroll system. Certificates are in a shared drive folder named after the technician, some scanned and some photographed on a phone. The vision test is in the QA manager’s email. The radiation badge number is on a spreadsheet the radiation safety officer keeps. Medical fitness expiry lives in somebody’s head, and availability is on a whiteboard in operations.</p><p>That works until a client wants a crew submission by tomorrow morning. Or an auditor asks for the qualification file of the Level II who signed last month’s RT reports. Or a technician leaves and nobody can find the originals.</p><p>The Employees app in Atlantis NDT ERP gives each person a single record. It’s the standard Odoo Employees app, extended with an NDT profile: whether the person is a technician, their highest NDT level, methods certified, radiation safety training, radiation badge number and medical fitness expiry. Certificates, vision tests and exam sheets link to the same record through the Certificates app, and the technician’s availability and utilisation come through from Team Assignments.</p><p>So when someone asks who this person is, what they’re qualified to do and whether they’re free next week, the answer is on one screen.</p><p>This page covers what the record holds, how it’s used day to day, who uses it and how we set it up for you.</p><h2>What the Employees app holds for an NDT company</h2><p>The standard Odoo Employees app covers the HR basics. That means name, job position, department, manager and coach, work contact details, work location and working hours. It also holds private information such as home address, emergency contact, nationality, identification and passport numbers, and work permit or visa details with expiry dates. You can record resume lines and skills, and the org chart builds itself from the manager field.</p><p>Atlantis NDT ERP adds an NDT profile to every employee:</p><ul><li><strong>Technician flag</strong>, so field staff can be separated from office staff in lists and reports.</li><li><strong>Highest NDT level</strong> held: trainee, Level I, II or III.</li><li><strong>Methods certified</strong>, taken from the technician’s certification records.</li><li><strong>Radiation safety training</strong> status.</li><li><strong>Radiation badge number</strong>, for technicians who work with radiography sources.</li><li><strong>Medical fitness expiry</strong> date.</li></ul><p>These are linked to the same record through the Certificates app:</p><ul><li>Every certification: scheme (SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP or other), level, method, certifying body, issue, expiry and renewal dates, industry sector, OJT hours, training hours, exam passed, and attachments.</li><li>Vision tests: near vision (Jaeger J1/J2), far vision, colour perception, contrast, examiner, clinic, certificate file and expiry.</li><li>Examination sheets with general, specific and practical scores and the exam files.</li></ul><p>Team Assignments adds the technician’s current status, current assignment, utilisation and next available date.</p><p>Nothing here forces you to change your written practice. The record simply holds the evidence your written practice already requires, in one place.</p><h2>How the record is used day to day</h2><p>Nobody admires an employee record. It gets used when a decision has to be made. Here is where it earns its place in an NDT company.</p><h3>Building a crew</h3><p>Operations needs two Level II UT technicians and a Level II RT technician with a current radiation badge for a job starting Monday. They filter employees by technician flag, level and method, check certification status, and look at the next available date. Ten phone calls become one list.</p><h3>Sending a crew submission to a client</h3><p>Many clients want qualification documents before anyone steps on site: certificates, vision tests and sometimes a reference to the employer’s written practice. With certificates and vision tests all linked to the employee record, the QA coordinator pulls the files from one place instead of hunting through folders.</p><h3>Answering an auditor</h3><p>An auditor picks a report and asks for the signing technician’s qualification file as of the report date. The record shows the certification with its issue and expiry dates, the vision test in force at the time and the exam sheet. Changes to records are tracked in the chatter, so you can see what was updated and by whom.</p><h3>Onboarding a new hire</h3><p>A new Level II joins. HR creates the employee and the QA manager enters their certifications and vision test. Once the certifications are in the system, operations can schedule them, with nothing re-entered in a separate scheduling tool.</p><h3>Offboarding</h3><p>When someone leaves, their record is archived, not deleted. Their history, the reports they signed and the certifications they held at the time stay on file for as long as your quality system requires.</p><h2>Expiry dates that don’t slip onto a job</h2><p>The expensive mistake in NDT staffing isn’t a typo in a phone number. It’s a technician arriving on site with an expired certificate or vision test and the client’s QA inspector finding it at the gate. Worse, it gets found after the reports are issued.</p><p>Because employee records are tied to the Certificates app, the ERP works out each certification’s status automatically: active, expiring soon (within 90 days), expired or revoked. Dedicated Expiring Soon and Expired menus give the QA manager a list to work through.</p><p>Daily checks create warning tasks 90 days before a certificate or vision test expires. Daily email alerts can go to the people who need them, and you set the recipients, look-ahead days and resend interval. The same alert system covers equipment calibration certificates and company certifications.</p><p>Two more safeguards sit where the work happens:</p><ul><li><strong>Timesheets warn</strong> when a technician’s certificate isn’t valid, so a supervisor approving hours sees the problem.</li><li><strong>Team Assignments</strong> shows the technician’s status and availability while you build a crew, and the NDT profile is on the same record.</li></ul><p>Medical fitness expiry is on the NDT profile as well. We agree during implementation how you want it monitored, for example which roles need it and who gets told.</p><p>What you should expect is qualitative but real: expired certs stop being a surprise. The QA manager works from a list instead of memory, and operations sees problems before a crew goes out. For more on the certification side, see the <a href=\"/erp/apps/certificates\">Certificates app</a>.</p><h2>Availability and utilisation from Team Assignments</h2><p>Knowing who someone is solves only half the problem. Operations also needs to know where they are and when they’re free.</p><p>Team Assignments in Atlantis NDT ERP runs jobs through a dispatch workflow (planned, dispatched, in field, submitted, closed), with site GPS coordinates and mobilisation and demobilisation dates. Each technician has an availability calendar with entries for assigned, leave, training, sick and unavailable, and overlapping entries are blocked. Double-booking of technicians and of equipment serial numbers is blocked as well.</p><p>That information shows up on the employee side as:</p><ul><li><strong>Technician status</strong>, such as available or on assignment.</li><li><strong>Current assignment</strong>, meaning the job they’re on now.</li><li><strong>Utilisation</strong>, shown as a percentage. It helps you decide whether you need to hire or whether work is spread unevenly.</li><li><strong>Next available date</strong>, the question an NDT operations office gets asked more than any other.</li></ul><p>Approved leave from the <a href=\"/erp/apps/time-off\">Time Off app</a> feeds the same availability, so a technician on approved holiday doesn’t show up as free.</p><p>Together, this turns the employee list into a working tool for the operations manager. Sort technicians by next available date, filter by method and level, and you have a shortlist for the next job. Open a record and qualifications, current job and upcoming leave are all on one screen.</p><p>Utilisation also helps with fairness. In most crews, a handful of people get sent on everything because they’re the ones the scheduler remembers. With utilisation side by side, it’s easier to spread the work and develop the technicians who’ve been sitting on the bench.</p><h2>Who uses the Employees app</h2><table><thead><tr><th>Role</th><th>What they do in Employees</th></tr></thead><tbody><tr><td>Owner or general manager</td><td>Reviews headcount by level and method and checks utilisation to decide where to hire next.</td></tr><tr><td>HR or office administrator</td><td>Creates records, maintains private information, work permits and visas, and handles onboarding and offboarding.</td></tr><tr><td>QA manager or Level III</td><td>Maintains certifications, vision tests and exam sheets, and prepares qualification files for audits and client submissions.</td></tr><tr><td>Operations manager or scheduler</td><td>Filters technicians by level, method, status and next available date to build crews.</td></tr><tr><td>Radiation safety officer</td><td>Keeps radiation badge numbers and radiation safety training status current.</td></tr><tr><td>Technician</td><td>Sees their own record, certifications and expiry dates, and gets a user account for timesheets, expenses and messaging.</td></tr></tbody></table><p>Access is controlled by role. Private information such as home address and identification numbers is visible only to HR and the people you choose. Technicians see their own record. Operations sees what it needs for scheduling without seeing personal details.</p><p>How strict this should be depends on your company and on the data-protection law where you operate. We set up the access groups with you during implementation, not after the fact.</p><h2>Training and development on the same record</h2><p>Technicians move up the levels through training hours, on-the-job experience and exams. The Certificates app records OJT hours and training hours against each certification, and each scheme’s certificate template can hold the minimum OJT and training hours required. Exam sheets record general, specific and practical scores against a passing score.</p><p>That gives the Level III responsible for your written practice a clear view, from the employee record, of where each trainee and Level I stands.</p><p>If you train your own people, Atlantis NDT ERP includes an eLearning app. It has a course portal organised into Level I, II and III sections, video lessons, quizzes and completion certificates. Learners enrolled in the portal also get a section that opens <a href=\"/practical-ndt\">Practical NDT</a>, Atlantis’s immersive 3D practice platform. There, technicians work through UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings. Access is granted automatically on enrolment or manually by an admin.</p><p>If you’d rather have outside help preparing technicians for their next level, Atlantis also runs <a href=\"/training\">NDT training</a> based on ASNT SNT-TC-1A. Whichever route you take, the hours and results end up in the same place: the technician’s record.</p><p>You can use skills in the standard Employees app for things that aren’t NDT certifications. Examples include rope access, confined space entry, a particular client’s site induction or a phased array instrument a technician knows well. We decide with you during setup what gets tracked as a skill and what gets tracked as a formal certification.</p><h2>How Employees connects to the rest of Atlantis NDT ERP</h2><p>The employee record is the hub. Almost every other app refers back to it:</p><ul><li><strong>Certificates.</strong> Certifications, vision tests, exam sheets and expiry alerts, all attached to the person.</li><li><strong>Team Assignments.</strong> Availability calendar, status, current assignment, utilisation and next available date.</li><li><strong>Time Off.</strong> Approved leave blocks out availability so nobody schedules a technician who is on holiday.</li><li><strong>Timesheets.</strong> Hours logged by work type, method, site, client and equipment serial, with a warning if the technician’s certificate isn’t valid.</li><li><strong>Expenses.</strong> Every field expense and per diem claim belongs to an employee.</li><li><strong>NDT Reports.</strong> Inspector, reviewer and approver on each report are users with signatures, so every report traces back to a person and their qualifications.</li><li><strong>Project.</strong> NDT jobs list the technicians assigned to them.</li><li><strong>Fleet.</strong> Vehicles are assigned to drivers with dates and mileage, including vehicles recorded as able to carry radioactive sources.</li><li><strong>Discuss.</strong> Every employee with a user account can message colleagues and follow the records they work on.</li></ul><p>Because it’s all one database, updating a technician’s certification in one place updates what operations sees when scheduling, what the supervisor sees when approving timesheets and what QA sees when preparing an audit. There’s no second copy to fall out of date.</p><p>For the full picture of what’s included, see the <a href=\"/erp/apps\">Atlantis NDT ERP apps</a> overview.</p><h2>Setting it up</h2><p>Atlantis NDT deploys and configures the ERP for you. For Employees, implementation usually runs like this:</p><ol><li><strong>Structure.</strong> We agree departments, job positions, bases or branches, and who reports to whom, so the org chart and approvals follow.</li><li><strong>Data import.</strong> Your existing technician list, usually a spreadsheet, is cleaned up and imported. Certifications and vision tests go into the Certificates app with their expiry dates, and scans of certificates are attached.</li><li><strong>NDT profile.</strong> Technician flags, highest levels, radiation badge numbers and medical fitness dates are filled in, and you confirm which alerts go to whom.</li><li><strong>Access groups.</strong> We decide who sees private information, who can edit certifications and what technicians see about themselves.</li><li><strong>User accounts.</strong> Technicians who will log timesheets, submit expenses or use the field reporting app get user accounts linked to their employee record.</li><li><strong>Training.</strong> Short sessions for HR, QA and operations on the parts they use.</li></ol><p>The biggest job is almost always the data clean-up: duplicate names, certificates with no expiry date, vision tests nobody can find. We work through it with you, because a clean start is what makes the alerts trustworthy.</p><p>Anything beyond the standard record and NDT profile, such as extra fields your clients ask for, is scoped and configured as part of your customization agreement. Pricing is quote on request. <a href=\"/contact?service=erp&amp;subject=Employees%20demo\">Book an Employees demo</a> to see it with sample technician data.</p><h2>Frequently asked questions</h2><h3>Can we store ASNT and ISO 9712 certifications on the same employee?</h3><p>Yes. Each certification records its scheme, including SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP or other, so one technician can hold several under different schemes.</p><h3>Will we be warned before a technician’s certificate expires?</h3><p>Yes. The ERP creates warning tasks 90 days before a certificate or vision test expires. You can also set daily email alerts with your own recipients, look-ahead days and resend interval.</p><h3>Can we see which technicians are available next week?</h3><p>Yes. Team Assignments gives each technician a status, current assignment, utilisation and next available date, and approved leave from Time Off is included in their availability.</p><h3>Can technicians see their own records?</h3><p>Yes, if you give them user accounts. Access rights are set so technicians see their own details and certifications but not other people’s private information.</p><h3>Can we record radiation badge numbers?</h3><p>Yes. The NDT profile on each employee includes radiation badge number and radiation safety training, alongside medical fitness expiry.</p><h3>Do we need to replace our payroll system?</h3><p>Not necessarily. Employees works as the master record for technicians whether or not you run payroll in the ERP. We agree during implementation how it fits with your existing payroll.</p><h2>Know your people before you send them</h2><p>An NDT company is only as good as the qualified people it puts on site. Atlantis NDT ERP keeps who they are, what they’re certified for, when those certs expire and when they’re free in one record that everyone can trust.</p><p>Tell us how many technicians you manage and where their records live today. <a href=\"/contact?service=erp&amp;subject=Employees%20quote\">Request a quote for Atlantis NDT ERP</a> and we’ll show you what your technician list looks like inside it.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/time-off\">Time Off</a>: Leave requests and allocations, visible to crew planners.</li><li><a href=\"/erp/apps/discuss\">Discuss</a>: Team chat and channels, threaded onto jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Employees%20demo\">Send an enquiry about Employees</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/time-off","publishedAt":"2026-09-27","title":"NDT Technician Leave & Time Off Management | Atlantis NDT","description":"Leave requests that update technician availability before anyone gets dispatched. Book a demo of Time Off in Atlantis NDT ERP for NDT field crews.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Technician Leave and Time Off Management</h1>\n<p>Leave requests and allocations, visible to crew planners. <a href=\"/contact?service=erp&amp;subject=Time%20Off%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why leave is an operations problem in NDT</h2><p>In an office business, leave is an HR matter. In an NDT company it’s an operations problem. When a Level II RT technician books two weeks off and nobody tells the scheduler, you find out on the Monday of a shutdown. Then the client’s crew list is wrong, a replacement has to be found at short notice, and someone ends up driving through the night.</p><p>The usual setup doesn’t help. Leave requests arrive by text message, email or a word in the yard. HR keeps a spreadsheet, operations keeps a whiteboard, and the two only agree by accident. Technicians coming off a long rotation want their days off straight away, just as the next job wants them back. Training courses, recertification exams and vision tests take people off the schedule too, and they rarely show up anywhere operations looks.</p><p>Time Off in Atlantis NDT ERP is the standard Odoo Time Off app, set up for an NDT company. Technicians request leave, managers approve it, and approved leave feeds the technician availability calendar that Team Assignments uses to dispatch crews. The person building next week’s crew sees the leave before they assign anyone, not after.</p><p>This page explains how Time Off works for a company with field technicians, the leave types NDT companies usually need, how it ties into scheduling, and what setup looks like.</p><h2>What the Time Off app does</h2><p>The standard Odoo Time Off app covers everything most companies need for leave, and none of it needs custom code:</p><ul><li><strong>Time off types.</strong> Paid leave, sick leave, unpaid leave, compensatory days, training leave and any other types you define, each with its own rules.</li><li><strong>Allocations.</strong> How many days each employee is entitled to per type, given manually or earned through accrual plans, for example a number of days per month worked.</li><li><strong>Requests.</strong> Employees request full days, half days or hours, depending on how each type is set up, and can add a reason.</li><li><strong>Approvals.</strong> Each type can be approved by the employee’s manager, by a time off officer, by both, or by nobody, for example for automatically accepted public holidays.</li><li><strong>Supporting documents.</strong> Types such as sick leave can be set to allow an attached document, like a medical note.</li><li><strong>Public holidays and mandatory days.</strong> Holidays are set per company or working schedule, and you can mark mandatory days when leave can’t be taken.</li><li><strong>Dashboard and calendar.</strong> Employees see their balances and past requests. Managers see a team calendar of who is off when.</li><li><strong>Reporting.</strong> Leave taken and remaining by employee, department and type.</li></ul><p>For an NDT company the value is less in any single feature and more in where the approved leave goes afterwards. Approved leave isn’t just a balance on an HR screen. It blocks the technician out of the schedule.</p><h2>Leave types that fit NDT work</h2><p>A generic leave setup has annual leave and sick leave. An NDT company usually needs a few more, because technicians are off the schedule for reasons that aren’t holidays. Here is a typical starting set we work through with you:</p><table><thead><tr><th>Leave type</th><th>How NDT companies use it</th></tr></thead><tbody><tr><td>Annual or paid leave</td><td>Standard entitlement, allocated yearly or earned through an accrual plan.</td></tr><tr><td>Sick leave</td><td>Requested after the fact where needed, with an optional medical note attached.</td></tr><tr><td>Rotation or field break</td><td>Days off after a long rotation or shutdown, where your contracts or policy grant them.</td></tr><tr><td>Compensatory days</td><td>Days given back for weekend or holiday work on a site.</td></tr><tr><td>Training and exam days</td><td>Time off the schedule for courses, recertification exams or vision tests, where you treat these as leave rather than assignments.</td></tr><tr><td>Unpaid leave</td><td>Requested and approved like any other type, without using a balance.</td></tr><tr><td>Public holidays</td><td>Set per country or working schedule, useful if you have crews in more than one country.</td></tr></tbody></table><p>You don’t need all of these, and you may need others. Some companies treat training as a Team Assignments entry rather than leave, since the availability calendar has its own training status. We agree the right split with you during implementation.</p><p>The aim is that every reason a technician can’t be dispatched shows up somewhere operations looks, so it never has to be remembered.</p><h2>How a leave request flows</h2><p>A request should take a technician less than a minute. Here is the typical flow:</p><ol><li><strong>Request.</strong> The technician opens Time Off in a phone browser, picks the leave type, the dates and, where allowed, half days or hours, and adds a short reason. Their remaining balance for that type is shown as they go.</li><li><strong>Notify.</strong> The approver gets a notification in the ERP and, depending on your settings, by email. The request also shows on the team calendar as pending.</li><li><strong>Check.</strong> Before approving, the supervisor or operations manager checks the dates against current and planned assignments. Is the technician on a job those days? Is anyone else with the same method and level off at the same time?</li><li><strong>Approve or refuse.</strong> The approver approves, or refuses with a reason. For types that need two approvals, such as manager plus time off officer, both have to sign off.</li><li><strong>Update availability.</strong> Approved leave updates the technician’s availability in Team Assignments, so they no longer show as free for those dates.</li></ol><p>Every step is logged with a name and time. If a technician later says their leave was approved and the scheduler says it wasn’t, the record settles it.</p><p>For sick leave, the flow usually runs the other way. The technician, or the office on their behalf, records the absence after it happens and attaches a note if your policy asks for one. Availability updates the same way.</p><h2>Time Off feeds technician availability</h2><p>This is the part that matters most to an NDT company, and it’s why Time Off belongs in the same system as your scheduling.</p><p>Team Assignments in Atlantis NDT ERP gives each technician an availability calendar with entries for assigned, leave, training, sick and unavailable. Overlaps are blocked, so a technician can’t be both assigned and on leave on the same day. Technicians and equipment serial numbers can’t be double-booked either.</p><p>Approved time off feeds that calendar. In practice, that means:</p><ul><li>When operations builds a crew, technicians on approved leave don’t appear as available for those dates.</li><li>A technician’s <strong>next available date</strong> takes their approved leave into account.</li><li><strong>Utilisation</strong> reflects the days they were actually available to work, which makes the number more honest.</li><li>If someone tries to assign a technician over approved leave, the overlap is blocked rather than discovered on site.</li></ul><p>The reverse matters too. When a technician requests leave, the approver can see what they’re already assigned to. If the request overlaps a dispatched job, the approver can refuse it, move the dates or arrange cover before approving. That saves a lot of last-minute scrambling.</p><p>For more on how dispatch works, see the <a href=\"/erp/apps/team-assignments\">Team Assignments app</a>. For the technician record that holds availability, certifications and the NDT profile, see the <a href=\"/erp/apps/employees\">Employees app</a>.</p><h2>Shutdown season, rotations and busy periods</h2><p>Most NDT companies have a rhythm. Turnaround and shutdown seasons pull every available technician onto site, and quieter months follow when people want their leave. Time Off can help you manage that rhythm instead of fighting it.</p><p><strong>Mandatory days.</strong> If you know a major shutdown will need everyone for a fixed period, you can mark those dates as mandatory days. Leave requests can’t be placed on them, which prevents the awkward conversation where a request gets approved months ago and then has to be withdrawn.</p><p><strong>The team calendar.</strong> Before approving leave for the quiet months, operations can see at a glance how many Level II UT or RT technicians are already off in the same week. Spreading leave out avoids a week where you have to turn down work.</p><p><strong>Rotation breaks.</strong> For companies running fixed rotations, such as a number of weeks on followed by weeks off, rotation break entries make the off period visible in the schedule. Whether that’s done through a leave type or through Team Assignments depends on how you run rotations, and we set it up the way that suits you.</p><p><strong>Compensatory days.</strong> Weekend and holiday work is normal on a shutdown. Allocating compensatory days as a separate type keeps them apart from annual leave, so both the technician and the office know what’s owed.</p><p><strong>Multiple countries.</strong> Public holidays can be set per working schedule. Crews working abroad can follow the local calendar while office staff follow the home one.</p><h2>Who uses Time Off</h2><table><thead><tr><th>Role</th><th>What they do in Time Off</th></tr></thead><tbody><tr><td>Field technician</td><td>Requests leave from a phone, checks balances, attaches sick notes, sees approval status.</td></tr><tr><td>Crew supervisor</td><td>Approves leave for their team and checks requests against current jobs.</td></tr><tr><td>Operations manager or scheduler</td><td>Watches the team calendar, approves or plans around leave in busy periods, sees availability in Team Assignments.</td></tr><tr><td>HR or time off officer</td><td>Sets up leave types and allocations, runs accrual plans, handles second-level approval, manages public holidays.</td></tr><tr><td>Accounts or payroll</td><td>Uses leave reports for payroll and for unpaid leave deductions, under your local rules.</td></tr><tr><td>Owner or general manager</td><td>Sees leave patterns across the company and checks that busy periods are covered.</td></tr></tbody></table><p>Access is controlled by role. Technicians see their own balances and requests. Supervisors see their team. HR sees everyone. Reasons attached to sick leave can be kept visible only to the approvers and HR.</p><p>For a small company, one person often does most of these jobs. The app works the same way, and the payoff is still the same: leave shows up in the schedule automatically.</p><h2>How Time Off connects to the rest of Atlantis NDT ERP</h2><ul><li><strong>Team Assignments.</strong> Approved leave feeds the technician availability calendar, and overlaps with assignments are blocked.</li><li><strong>Employees.</strong> Leave is recorded against the same employee record that holds the NDT profile, certifications, status and next available date.</li><li><strong>Certificates.</strong> Expiring certificates and vision tests raise warning tasks 90 days ahead. Planning recertification or a vision test around leave is easier when both are in the same system.</li><li><strong>Timesheets.</strong> Hours on site are logged against jobs, and days on leave are not. The two together give a full picture of each technician’s time.</li><li><strong>Calendar and Discuss.</strong> Approved leave can show on shared calendars, and approvers get notified in the ERP, so requests don’t sit unseen in an inbox.</li><li><strong>Training.</strong> If technicians study in the eLearning portal, including the <a href=\"/practical-ndt\">Practical NDT</a> 3D practice platform available to enrolled learners, you can plan study days into quiet periods and record them the way you prefer.</li></ul><p>The point of one database is that a leave approval doesn’t need to be copied anywhere. It’s approved once and every screen that cares about availability sees it.</p><p>For everything included in the ERP, see the <a href=\"/erp/apps\">Atlantis NDT ERP apps</a> overview.</p><h2>What implementation looks like</h2><p>Atlantis NDT deploys and configures the ERP for you. For Time Off we work through:</p><ol><li><strong>Your leave policy.</strong> Entitlements, how leave is earned, carry-over rules, sick leave rules, and how rotation breaks and compensatory days work. If your policy lives in employment contracts, we help you turn it into leave types and allocations.</li><li><strong>Leave types.</strong> A list that matches your company, with approval rules and whether half days, hours or supporting documents apply to each.</li><li><strong>Allocations and balances.</strong> Opening balances for every employee, so the first day on the new system starts from the right numbers.</li><li><strong>Accrual plans.</strong> If leave is earned over time, we set up the plan to match your policy.</li><li><strong>Public holidays and mandatory days.</strong> Per country or working schedule, plus any shutdown dates you want blocked.</li><li><strong>Approvers.</strong> Who approves for whom, with cover for when an approver is away.</li><li><strong>Link to scheduling.</strong> Confirming that approved leave shows up as expected in Team Assignments before you go live.</li><li><strong>Training.</strong> A few minutes for technicians, a short session for approvers and HR.</li></ol><p>Anything beyond standard Time Off, for example a specific rule your contracts require, is scoped and configured as part of the customization agreed with you. Pricing is quote on request, and the ERP is built to be affordable and accessible for NDT companies of any size.</p><p>To see it with your own leave types, <a href=\"/contact?service=erp&amp;subject=Time%20Off%20demo\">book a Time Off demo</a>.</p><h2>Frequently asked questions</h2><h3>Does approved leave stop a technician from being scheduled?</h3><p>Yes. Approved leave feeds the technician availability calendar in Team Assignments, where overlaps are blocked. A technician on approved leave doesn’t show as free and can’t be assigned over the leave.</p><h3>Can technicians request leave from their phones?</h3><p>Yes. Technicians use Time Off in a phone browser to request leave, check balances and see approval status. They need a connection to submit.</p><h3>Can we block leave during a shutdown?</h3><p>Yes. Mark the shutdown dates as mandatory days and leave requests can’t be placed on them. The team calendar also shows who is already off.</p><h3>Can leave need two approvals?</h3><p>Yes. Each leave type can be approved by the manager, a time off officer, both, or nobody. Two-step approval is common for long leave.</p><h3>Can we handle different public holidays for crews abroad?</h3><p>Yes. Public holidays are set per company or working schedule, so crews abroad can follow the local calendar.</p><h3>Can sick leave include a medical note?</h3><p>Yes. Leave types can be set to accept a supporting document, and access can be limited so only approvers and HR see it.</p><h2>Know who’s off before you build the crew</h2><p>Every NDT operations manager has a story about the technician who turned out to be on holiday the week of a big job. Time Off in Atlantis NDT ERP makes approved leave part of the schedule automatically, so that story stops happening.</p><p>Tell us how your crews rotate and how leave works today. <a href=\"/contact?service=erp&amp;subject=Time%20Off%20quote\">Request a quote for Atlantis NDT ERP</a>, or ask for a demo covering Time Off, Employees and Team Assignments together.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/employees\">Employees</a>: Technician records, levels, documents and contracts.</li><li><a href=\"/erp/apps/discuss\">Discuss</a>: Team chat and channels, threaded onto jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Time%20Off%20demo\">Send an enquiry about Time Off</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/discuss","publishedAt":"2026-09-27","title":"Team Chat for NDT Companies: Discuss App | Atlantis NDT","description":"Job channels, chatter on reports and procedures, and direct messages that keep NDT office and field crews aligned. Book a demo of Discuss in Atlantis NDT ERP.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>Team Messaging for NDT Companies: Discuss App</h1>\n<p>Team chat and channels, threaded onto jobs and records. <a href=\"/contact?service=erp&amp;subject=Discuss%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>The problem with running jobs on personal chat apps</h2><p>Most NDT companies run on personal chat groups. There’s one group per client, one per shutdown and one for the whole crew, plus private messages between the operations manager and every technician. Photos of indications, calibration block readings, “are you on site yet?”, client requests to add three more welds to the scope and a Level III’s answer on an acceptance question all end up in the same scrolling thread on someone’s phone.</p><p>It works in the moment, and it fails afterwards. Two weeks later, when the client disputes the extra welds, the message approving them is on a technician’s phone, and that technician has left the company. When an auditor asks why a report was revised, the reason is in a chat nobody can find. When a new supervisor joins, there’s no history to read.</p><p>Discuss in Atlantis NDT ERP is the standard Odoo Discuss app, set up for an NDT company. It gives you channels and direct messages like any team chat. The difference is that it sits inside the same system as your jobs, reports, procedures, equipment and technicians. Conversations about a record can live on that record, where they’ll be found later.</p><p>Discuss won’t replace every phone call, and it doesn’t need to. The aim is simpler: decisions that matter for a job, a report or a procedure get recorded where the work is, not on someone’s personal phone.</p><p>This page covers how Discuss works, how NDT companies use it day to day, how it connects to the other apps, and what setup looks like.</p><h2>What the Discuss app does</h2><p>Discuss has two halves, and both are standard Odoo features.</p><p><strong>Team messaging.</strong> Channels for groups and topics, direct messages between people, and small group chats. Messages support @mentions, file and photo attachments, reactions and search. Discuss also supports voice and video calls with screen sharing, which is handy when a Level III needs to see what a technician is looking at. Notifications arrive in the ERP inbox and in the browser, including on phones.</p><p><strong>Chatter on records.</strong> Almost every record in the ERP, whether it’s a job, a report, a procedure, an instrument, an employee, a quote or an invoice, has a chatter panel alongside it. There, people can:</p><ul><li><strong>Log a note</strong>, an internal comment visible only to your staff.</li><li><strong>Send a message</strong> to the record’s followers, which can include external contacts by email. Replies by email come back into the chatter.</li><li><strong>Schedule an activity</strong>, such as a call, a to-do or an upload, assigned to a person with a due date.</li><li><strong>Attach files</strong> that stay with the record.</li><li><strong>Follow</strong> the record, so they’re notified when it changes.</li></ul><p>The chatter also logs tracked changes automatically, such as a status moving from review to approved and who moved it. Put that next to the conversation and you have the history of a record in one place.</p><p>Teams usually get the most out of Discuss when channels handle quick coordination and the chatter holds anything that needs to be on the record.</p><h2>Channels for jobs, teams and bases</h2><p>Channels are where day-to-day coordination happens. For an NDT company, a sensible channel structure usually looks like this:</p><ul><li><strong>A channel per major job or shutdown.</strong> Everyone mobilised to a turnaround joins it: technicians, supervisors, the project manager and the Level III. Mobilisation updates, daily plans, permit delays and quick questions go here. When the job closes, the channel is archived, not deleted.</li><li><strong>A channel per method or discipline.</strong> For example UT and PAUT, RT and radiation safety, or surface methods. Technical questions go to the people who can answer them without flooding everyone else.</li><li><strong>A channel per base or branch</strong>, for companies with more than one location.</li><li><strong>An operations channel</strong> where schedulers, supervisors and the operations manager coordinate crews and equipment.</li><li><strong>A QA channel</strong> for the QA manager, Level IIIs and reviewers.</li></ul><p>Channels can be public inside the company or private and invitation only. Private channels work well for management or for sensitive client matters.</p><p>Direct messages cover the rest: a supervisor checking in with one technician, or accounts asking a project manager about a PO number.</p><p>A practical rule of thumb we suggest: if a message would matter to someone reading the job file in six months, it belongs in the chatter of the job or report, not in a channel. Channels are for coordination. Chatter is for the record.</p><h2>Chatter on reports, procedures, equipment and jobs</h2><p>This is where Discuss becomes more than a chat app for an NDT company. Here’s how the chatter gets used on the records that matter most.</p><h3>Inspection reports</h3><p>Reports in the NDT Reports app move through draft, in progress, review, approved and sent. When a reviewer sends a report back, the reason goes in the chatter, where the inspector sees it and the next reviewer can read it. When a client queries a result, the discussion sits on the report itself. If you also use Atlantis’s <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> to place results on a 3D model of the asset, the report record in the ERP is still where the review conversation lives.</p><h3>Procedures</h3><p>Procedures move through draft, submitted, reviewed, approved and published, with prepared, reviewed and approved by fields and full revision history. Reviewer comments and rejection reasons on a new revision sit in the chatter. When an auditor asks why revision 4 changed the scan plan, the answer is right there.</p><h3>Equipment</h3><p>An instrument that comes back from site with a cracked probe housing gets a note on its record, alongside its maintenance log and calibration records. The next person to issue it sees the history.</p><h3>Jobs and assignments</h3><p>Scope changes, client instructions, permit delays and demobilisation notes go on the job, where the project manager and accounts will find them at invoice time.</p><h2>Approvals and notifications that people actually see</h2><p>Much of the delay in an NDT company is waiting. Reports wait for review, procedures wait for Level III approval, and quotes and expense reports wait for sign-off. Often nobody is refusing to act. They just haven’t noticed.</p><p>Discuss helps in three ways.</p><p><strong>Inbox notifications.</strong> When you’re mentioned, assigned an activity or following a record that changes, it shows up in your Discuss inbox. It doesn’t get buried among supplier newsletters.</p><p><strong>Activities with due dates.</strong> A reviewer can be given a “Review report” activity due tomorrow. Overdue activities are highlighted, and managers can see who has what outstanding. The Certificates app uses warning tasks the same way, creating them 90 days before a certificate or vision test expires.</p><p><strong>Email where it belongs.</strong> The Procedures app sends email notifications and reminders to approvers for pending approvals. Messages sent from a record’s chatter reach followers by email, and replies come back into the chatter. People who live in their inbox still take part, and the conversation still ends up on the record.</p><p>We’d rather be honest about the limits. Discuss notifies people. It doesn’t make them act. What it does is make the waiting visible, so a supervisor can see that a report has sat in review for three days and ask why. How you set up activity types, and who follows what by default, is agreed with you during implementation.</p><p>The result you should look for is qualitative: fewer reports sitting unnoticed in review and fewer approvals chased by phone.</p><h2>Office to field: using Discuss on site</h2><p>Technicians in the field aren’t sitting at a desk, so Discuss has to work on a phone.</p><p>Discuss runs in the phone’s browser as part of the ERP, and notifications can reach the phone. A technician can read the day’s plan in the job channel, reply to a supervisor, attach a photo and answer a question on a report they submitted, all from the same login they use for timesheets and expenses.</p><p>Some practical points for field use:</p><ul><li><strong>Connectivity.</strong> Discuss needs a connection. The ERP’s offline field app is built for inspection reports and syncs drafts and photos later. Discuss isn’t offline. Technicians catch up on messages when they have signal.</li><li><strong>Photos.</strong> Photos that are part of the inspection record belong in the report, captured through the field app. Photos in Discuss are for coordination, such as “is this the right line?” or “the scaffold isn’t ready”.</li><li><strong>Calls.</strong> A quick video call lets a Level III look at a setup or indication through a technician’s camera, then note the outcome on the report.</li><li><strong>Keeping it tidy.</strong> Technicians only join the channels for their current jobs and their method, so their phone doesn’t buzz for every job in the company.</li></ul><p>You may still keep personal chat apps for emergencies or social chat. Many companies do. The point is that job decisions move into a place the company owns and can search.</p><h2>Who uses Discuss</h2><table><thead><tr><th>Role</th><th>How they use Discuss</th></tr></thead><tbody><tr><td>Field technician</td><td>Reads job channels, replies to supervisors, answers review comments on their reports, joins calls with a Level III.</td></tr><tr><td>Crew supervisor</td><td>Posts daily plans, coordinates the crew, logs site issues on the job record.</td></tr><tr><td>Level III or QA manager</td><td>Answers technical questions, reviews reports and procedures, records decisions in the chatter.</td></tr><tr><td>Operations manager or scheduler</td><td>Coordinates crews and equipment, flags conflicts, follows every active job.</td></tr><tr><td>Project manager</td><td>Records client instructions and scope changes on the job, messages clients by email from the chatter.</td></tr><tr><td>Accounts</td><td>Asks about PO numbers and recharges on the job or invoice record, not by phone.</td></tr><tr><td>Owner</td><td>Follows key jobs and sees the history of any decision.</td></tr></tbody></table><p>Everyone with a user account gets Discuss. Access to records, and so to their chatter, follows the same access rights as the rest of the ERP. A technician can’t read the chatter on an invoice they can’t open.</p><h2>How Discuss connects to the rest of Atlantis NDT ERP</h2><p>Discuss is built into every app, which is why it’s worth using over a separate chat tool:</p><ul><li><strong>NDT Reports.</strong> Review comments, send-backs and client queries on each report.</li><li><strong>Procedures.</strong> Reviewer comments, rejection reasons and approval reminders on each revision.</li><li><strong>Team Assignments and Project.</strong> Coordination, scope changes and site notes on each job.</li><li><strong>Asset Management.</strong> Notes on instruments alongside maintenance and calibration history.</li><li><strong>Certificates.</strong> Warning tasks before certificates and vision tests expire, as activities in the inbox.</li><li><strong>Quotations, CRM and Invoicing.</strong> Client correspondence by email, logged on the lead, quote or invoice.</li><li><strong>Employees and Time Off.</strong> Leave approvals and HR notes, with notifications to approvers. See the <a href=\"/erp/apps/time-off\">Time Off app</a>.</li><li><strong>eLearning.</strong> Admins can coordinate with learners, including those using <a href=\"/practical-ndt\">Practical NDT</a>, the 3D practice platform available to enrolled learners.</li></ul><p>Because it’s all one database, searching Discuss for a weld number or a client name finds messages on every record where it came up. A separate chat app can’t do that.</p><p>For the full list of apps, see the <a href=\"/erp/apps\">Atlantis NDT ERP apps</a> overview or the <a href=\"/erp\">NDT ERP</a> page.</p><h2>What setup looks like</h2><p>Discuss works out of the box. Most of the setup is about habits, not software. Atlantis NDT deploys and configures the ERP, and for Discuss we work through:</p><ol><li><strong>Channel structure.</strong> Which channels to create at go-live, such as operations, QA, each method group and each base, and a naming convention for job channels.</li><li><strong>Who follows what.</strong> Default followers on reports, procedures and jobs, so the right people are notified without everyone being notified of everything.</li><li><strong>Activity types.</strong> Review report, approve procedure, return equipment, send crew documents, and whatever else matches your workflow.</li><li><strong>Email settings.</strong> Making sure messages to clients go out from your domain and replies come back into the chatter.</li><li><strong>House rules.</strong> A one-page guide on what goes in channels, what goes in chatter, and what stays on the phone.</li><li><strong>Phone setup.</strong> Getting technicians logged in and receiving notifications.</li></ol><p>Anything beyond standard Discuss is scoped and configured as part of the customization agreed with you. Pricing is quote on request, and the ERP is built to be affordable and accessible for NDT companies of every size.</p><p>To see how it looks on a live report and job, <a href=\"/contact?service=erp&amp;subject=Discuss%20demo\">book a Discuss demo</a>.</p><h2>Frequently asked questions</h2><h3>Is Discuss a replacement for our chat groups?</h3><p>It can be for work conversations. Discuss has channels, direct messages, attachments and calls. Its main advantage is chatter on each record, so decisions stay with the job, report or procedure they relate to.</p><h3>Can technicians use Discuss on their phones?</h3><p>Yes. Discuss runs in the phone browser as part of the ERP, with notifications. It needs a connection, unlike the offline field app used for inspection reports.</p><h3>Can we message clients from Discuss?</h3><p>Yes, through the chatter. Sending a message from a record emails its followers, including external contacts, and their email replies come back into the chatter.</p><h3>Can a Level III see what a technician is looking at?</h3><p>Yes, with a video call in Discuss. The technician shares their camera, and the Level III records the outcome on the report afterwards.</p><h3>Who can read the chatter on a record?</h3><p>Anyone who can open that record under their access rights. Log notes are internal. Sent messages also go to followers.</p><h3>Is Discuss included in Atlantis NDT ERP?</h3><p>Yes. Every user gets it, and it’s built into every app. Pricing for the ERP is quote on request.</p><h2>Keep job decisions where the job lives</h2><p>The most important conversations in an NDT company are about scope, results, revisions and approvals. They belong on the record, not on somebody’s phone. Discuss in Atlantis NDT ERP keeps them there, and still gives your crews a quick way to talk.</p><p>Tell us how your office and field teams communicate today. <a href=\"/contact?service=erp&amp;subject=Discuss%20quote\">Request a quote for Atlantis NDT ERP</a> and we’ll show you a job, a report and its conversation in one place.</p>\n\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/employees\">Employees</a>: Technician records, levels, documents and contracts.</li><li><a href=\"/erp/apps/time-off\">Time Off</a>: Leave requests and allocations, visible to crew planners.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Discuss%20demo\">Send an enquiry about Discuss</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/invoicing","publishedAt":"2026-09-27","title":"NDT Invoicing Software for Inspection Companies | Atlantis NDT","description":"Invoice NDT jobs from approved timesheets, equipment serials and consumables, with PO, site and method on every line. Book a demo of the Atlantis NDT ERP.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Invoicing Software: Bill Timesheets, Equipment and Consumables</h1>\n<p>Invoices from timesheets and completed jobs, with payments and reminders. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why invoicing is where NDT companies quietly lose money</h2><p>Most NDT companies do not lose money on the inspection itself. They lose it after the job, in the week when someone sits down with a pile of field sheets, a spreadsheet of technician hours, a rate sheet from the client's contract and an email thread about which crew stayed an extra night on site. The invoice gets built by hand, it goes out late, and it usually goes out missing something.</p><p>The patterns are familiar to anyone who has run an inspection business. Standby hours agreed on site never reach the invoice because nobody recorded them in a way the office could read. A phased array unit sat on a job for nine days but was billed for five because the equipment log lived in a different file. Couplant, film, penetrant kits and PPE were consumed and never charged. The client rejects the invoice because the PO number is wrong, or because the lines do not match the cost codes their accounts payable team expects, and the payment clock starts again.</p><p>None of this is really an accounting problem. It is an operational data problem. The information that makes an NDT invoice correct — who worked, on which method, with which instrument, for how many hours, at which rate, against which PO — is created in the field. If it has to be re-typed into a separate billing tool, some of it will be lost on the way.</p><p>The Invoicing app in the Atlantis NDT ERP is built around that reality. It is part of our <a href=\"/erp\">NDT ERP built on Odoo</a>, pre-configured for inspection companies and deployed by our team, so the hours, equipment and consumables recorded during the job are the same records that end up on the invoice.</p><h2>What an NDT invoice carries in the Atlantis ERP</h2><p>A generic accounting package knows about customers, products and taxes. An NDT invoice needs more context than that, because your client's approver has to match it to a job they commissioned weeks ago. The invoice header in the Invoicing app holds:</p><ul><li><strong>NDT project</strong> — the job the invoice belongs to, so every invoice traces back to its scope, site and crew.</li><li><strong>Job or PO number</strong> — the reference your client's accounts payable team uses to approve payment.</li><li><strong>Site</strong> — the plant, yard, shop or location where the work was done.</li><li><strong>Invoice type</strong> — so you can separate an interim invoice from a final one, or a service invoice from a rental invoice, as configured for your business.</li><li><strong>Industry sector</strong> — oil and gas, power, fabrication, marine, aerospace and so on, which later tells you where your revenue really comes from.</li></ul><p>The invoice then shows <strong>separate subtotals for labour, equipment and consumables</strong>. That split matters. Many clients approve labour against one budget line and equipment against another, and a single lump sum invites questions and delays.</p><p>Each invoice line can carry a <strong>cost centre</strong>, the <strong>NDT method</strong> (UT, RT, MT, PT, PAUT, TOFD, ET and others), the <strong>equipment serial number</strong>, the <strong>technician</strong>, the <strong>rate type</strong> and the <strong>days or hours</strong> billed. When a client asks why they were charged for a TOFD setup on a Tuesday, you can show them the line, the technician, the instrument serial and the hours without opening another system.</p><p>The invoice PDF uses a <strong>custom invoice layout</strong> set up for your company during implementation, so the document your client receives looks like yours and presents the information in the order their approvers expect.</p><h2>From approved timesheet to invoice line</h2><p>The labour on an NDT invoice starts on the timesheet. In the Atlantis ERP, timesheets are set up for inspection work rather than office hours. Each entry records the work type — inspection, travel, standby or setup — along with the method, the site, the client and the equipment serial used. Every entry has a <strong>billable flag</strong> and a <strong>rate multiplier</strong>, so overtime, night shift or weekend work is distinguished from standard hours without a separate spreadsheet.</p><p>A typical week looks like this:</p><ol><li>Technicians log their hours against the project, split by work type. Travel to a remote site is recorded as travel, waiting for a permit is recorded as standby, and calibration and scanner setup is recorded as setup.</li><li>The supervisor or operations manager approves the timesheets. The ERP warns if a technician's certificate is not valid, so hours worked by someone whose cert has lapsed get noticed before they reach a client.</li><li>Billable hours flow into billing with their rate multipliers applied. Non-billable time — internal training, rework your company absorbs — stays off the invoice but remains visible in your costs.</li><li>The billing person reviews the draft invoice, checks the PO and site, and posts it.</li></ol><p>The important change is that nobody is re-typing hours. The office is reviewing and correcting, not rebuilding. If a client disputes a standby charge, the approved timesheet entry is the evidence, with the date, the technician and the work type recorded at the time.</p><p>How your rates map to work types, methods and multipliers is part of the setup we agree with you. Some companies bill a day rate per technician level, others bill hourly by method, and many do both depending on the client. The configuration follows your contracts, not the other way round.</p><h2>Billing equipment and consumables properly</h2><p>Equipment is often the most under-billed part of an NDT job. A phased array kit, a TOFD scanner, a crawler or an eddy current instrument is expensive to own and calibrate, and clients often expect to pay for it separately. Yet in many companies the equipment charge depends on someone remembering which units went to site and for how long.</p><p>In the Atlantis ERP, instruments are tracked by serial number in the Asset Management app, with issue and return records, reservations and movements in and out. Rental rates can be recorded against equipment. Because invoice lines can carry the <strong>equipment serial</strong>, the equipment subtotal can be tied to the specific instruments actually issued to the job, and you can answer the client who asks which unit they paid for.</p><p>Consumables work the same way. Couplant, penetrant and developer, magnetic particles, film and chemicals, PPE — these are tracked in Asset Management and Inventory with a movement ledger. When consumables are drawn for a job, that usage becomes the basis for the consumables subtotal instead of a guessed allowance.</p><p>Field expenses are the other leak. Per diems, accommodation, fuel and site access costs are recorded in the standard Expenses app and can be re-billed to the job. Whether you charge them at cost, with a handling margin or as a fixed per diem depends on your contracts, and that rule is set up during implementation.</p><p>The result is an invoice where labour, equipment and consumables each stand on their own records. You get paid for what you actually supplied, and your client gets an invoice that is easier to approve.</p><h2>Cost centres and the financial dashboard</h2><p>Invoicing is not only about getting paid. It is also the best source of truth about which parts of your business make money. Cost centres on invoice lines let you split revenue the way you manage the company — by branch, by service line (conventional NDT, advanced UT, training, consulting), by division or by major client account. The structure is defined with you during setup.</p><p>The Invoicing app includes a financial dashboard that shows:</p><ul><li>Revenue and cost of sales</li><li>Gross margin</li><li>Operating expenses</li><li>EBITDA</li><li>Outstanding invoices, vendor bills and expenses</li><li>A 12-month view, so trends are visible and not just this month's figure</li></ul><p>For an owner or general manager, this replaces the monthly wait for a margin figure that arrives weeks after the month closed. For an operations manager, the outstanding invoices view shows which clients are sitting on payments while you keep sending crews to their sites.</p><p>Because every invoice carries the industry sector, you can also see where revenue is concentrated. If most of your margin comes from one refinery client's shutdown season, that is a business risk worth knowing, and it shapes where your sales effort should go next year.</p><p>The dashboard reads from the same records as the invoices. There is no separate reporting export to maintain and no spreadsheet to reconcile at month end.</p><h2>Who uses the Invoicing app</h2><p>Different people touch an NDT invoice at different points, and the app is set up so each one sees what they need.</p><ul><li><strong>Accounts and billing staff</strong> build draft invoices from approved time, equipment and consumables, check PO numbers and post invoices. They also record payments and send reminders.</li><li><strong>Operations managers and supervisors</strong> approve timesheets and confirm equipment and consumable usage before it is billed. They are the people who know the crew waited two days for a permit.</li><li><strong>Project or contract managers</strong> check that invoices match the scope and rates agreed with the client, especially on long jobs with several interim invoices.</li><li><strong>Owners and general managers</strong> use the financial dashboard to watch margin, receivables and the split of revenue by sector and cost centre.</li><li><strong>Technicians</strong> do not invoice anything, but their timesheet entries are the raw material. Clear work types and a simple entry screen make their records usable by the office.</li></ul><p>Access rights follow the standard Odoo permission model and are set during implementation, so, for example, technicians see their own timesheets while only finance staff can post invoices.</p><p>In smaller companies one person often covers billing, accounts and half of operations. The workflow still helps, because it removes the step of rebuilding data from paper. In larger multi-branch companies, cost centres and approval steps give each branch its own view while the owner sees the whole picture.</p><h2>How Invoicing connects to the rest of the NDT ERP</h2><p>The Invoicing app is most useful at the end of a chain that starts with the enquiry. Here is how the pieces fit together:</p><ul><li><strong>CRM and Quotations.</strong> A lead becomes a quotation built with NDT service products flagged by method and category, the job type, the site and the applicable codes. The client can accept the quote online, and it converts to a sales order. The <a href=\"/erp/apps/quotations\">Quotations app</a> page explains how that works.</li><li><strong>Project.</strong> The job is set up with the client PO, contract, methods, codes, scope, site, assigned technicians and equipment. The PO recorded here is the same reference the invoice needs.</li><li><strong>Team Assignments.</strong> Crews and equipment are dispatched, with double-booking of technicians and equipment serials blocked.</li><li><strong>Timesheets.</strong> Hours are logged by work type and approved, with billable flags and rate multipliers.</li><li><strong>Asset Management and Inventory.</strong> Equipment issued to the job and consumables drawn are recorded.</li><li><strong>Certificates.</strong> Timesheets warn when a technician's cert is not valid.</li><li><strong>NDT Reports.</strong> Inspection reports are reviewed, approved and sent. Many clients will not approve an invoice until they have the report, so having both in one system shortens the gap between finishing the work and getting paid.</li></ul><p>If your clients want to see results on a 3D model of their asset, our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, works alongside the ERP's NDT Reports app. It is a separate product, and some inspection companies use it to stand out when bidding for asset-owner contracts: the invoice goes out with the report and a visual record of where each finding sits on the equipment.</p><h2>Taxes, payments and payment reminders</h2><p>The Atlantis ERP uses standard Odoo accounting for payments, reminders and taxes. You get a mature, widely used accounting engine rather than a home-grown billing tool.</p><p>Taxes and invoice formats are configured for your country during implementation. NDT companies work under very different regimes — state sales tax in the USA, GST and HST in Canada, VAT across Europe and parts of the Gulf, GST in India — and each has its own rules on what an invoice must show. We set up the tax rates, fiscal positions and invoice layout your accountant or tax adviser requires. We do not claim certification against any government e-invoicing scheme; where one applies to you, we discuss the requirement with you and your adviser during scoping.</p><p>Payments are recorded against invoices, so outstanding balances stay current. Standard payment reminders help you chase overdue invoices consistently rather than relying on someone remembering to call. The follow-up steps, wording and timing match how you want to treat your clients — a gentle nudge for a long-standing refinery client reads differently from a firm reminder to a new fabricator.</p><p>Payment terms vary widely in this industry. Asset owners often pay on long terms and sometimes only after the report is accepted, while fabrication shops may pay faster. Payment terms are set per client so the due dates on invoices reflect what you actually agreed. Retention, progress billing and client-specific invoice rules are handled as part of the customization scope agreed with you.</p><h2>What implementation looks like</h2><p>We deploy and set up the ERP for you. You do not buy a login and work it out alone. For the Invoicing app, implementation usually covers:</p><ol><li><strong>Rate structure.</strong> Your price lists and contract rates mapped to work types, technician levels, methods and rate multipliers.</li><li><strong>Chart of accounts and taxes.</strong> Taxes and fiscal settings configured for your country, with your accountant's input.</li><li><strong>Cost centres.</strong> Branches, service lines or divisions set up the way you want to report.</li><li><strong>Invoice layout.</strong> Your logo, header and footer, bank details and the fields your clients expect, such as PO, site and job number.</li><li><strong>Equipment and consumables.</strong> Instruments loaded by serial number and consumables set up, with rental rates where you bill them.</li><li><strong>Payment terms and reminders.</strong> Standard terms and follow-up steps agreed.</li><li><strong>Open invoices and balances.</strong> Migrated so receivables are correct from day one.</li><li><strong>Training.</strong> Short sessions for billing staff, supervisors and technicians on their part of the flow.</li></ol><p>The ERP is fully customizable. If a major client needs invoices split by work order, a specific cost code on every line or a particular attachment, that goes into the scope we agree. Pricing is quote on request; the ERP is designed to be affordable and accessible for NDT companies of different sizes. You can browse the other <a href=\"/erp/apps\">ERP apps</a> to see what else can be switched on.</p><h2>Frequently asked questions</h2><h3>Can the Atlantis ERP create invoices from technician timesheets?</h3><p>Yes. Timesheet hours marked billable feed billing, with the rate multiplier applied. Supervisors approve the hours first, and non-billable time stays off the invoice. How your rates map to work types and technician levels is set up during implementation.</p><h3>Can I bill equipment by serial number?</h3><p>Yes. Invoice lines can carry the equipment serial, and instruments are tracked by serial in Asset Management with issue and return records. Rental rates can be recorded against equipment, so the equipment subtotal reflects the units actually used on the job.</p><h3>Does the invoice show the client's PO number and site?</h3><p>Yes. The invoice header holds the NDT project, job or PO number, site, invoice type and industry sector — the references client accounts payable teams check before approving payment.</p><h3>Is the software certified for government e-invoicing?</h3><p>No certification is claimed. Taxes and invoice formats are configured for your country during implementation using standard Odoo accounting. If an e-invoicing requirement applies to your business, we review it with you and your tax adviser during scoping.</p><h3>Can it handle retention and interim invoices on long jobs?</h3><p>Interim and final invoices can be told apart with the invoice type field, and cost centres let you follow a long project separately. Retention and progress billing rules depend on your contracts and are configured as part of the customization scope agreed with you.</p><h3>Do I need every ERP app to use Invoicing?</h3><p>No, but it works best with Timesheets, Project and Asset Management feeding it. Many companies start with Quotations, Timesheets and Invoicing, then add Certificates, Team Assignments and NDT Reports.</p><h3>How much does it cost?</h3><p>Pricing is quote on request, based on the apps you need, the number of users and the customization involved. The ERP is designed to be affordable and accessible for NDT companies.</p><h2>See your own jobs invoiced in a demo</h2><p>The quickest way to judge the Invoicing app is to watch one of your typical jobs go through it: a crew, a few days of inspection and standby, a phased array unit, some consumables and a client PO. We will set up the demo around the way you bill today and show you where the re-keying disappears.</p><p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo\">Book an Invoicing demo</a> or <a href=\"/contact?service=erp&amp;subject=Invoicing%20quote\">request a quote for the NDT ERP</a>. Tell us how you bill now — day rates, hourly, by method, with or without equipment charges — and we will show you the configuration that fits.</p>\n<h2>Invoicing by region</h2><ul><li><a href=\"/erp/apps/invoicing/usa\">Invoicing in United States</a></li><li><a href=\"/erp/apps/invoicing/canada\">Invoicing in Canada</a></li><li><a href=\"/erp/apps/invoicing/europe\">Invoicing in UK &amp; Europe</a></li><li><a href=\"/erp/apps/invoicing/middle-east\">Invoicing in Middle East</a></li><li><a href=\"/erp/apps/invoicing/india\">Invoicing in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo\">Send an enquiry about Invoicing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/invoicing/usa","publishedAt":"2026-09-27","title":"NDT Invoicing Software in the USA | Atlantis NDT","description":"Invoice US NDT jobs from field tickets, approved timesheets, equipment serials and consumables, with PO and site on every line. Request a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Invoicing Software for Inspection Companies in the USA</h1>\n<p>Invoices from timesheets and completed jobs, with payments and reminders. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work actually gets billed in the USA</h2><p>If you run an NDT company on the Gulf Coast, in the Midwest refining belt or out of a pipeline yard in West Texas, you already know the invoice is only as good as the paperwork behind it. US clients — refiners, petrochemical plants, pipeline operators, EPC contractors, fabrication shops and aerospace manufacturers — rarely pay a number just because you sent it. They pay when the invoice matches the purchase order, the rate sheet in the master service agreement and the field tickets their own people signed on site.</p><p>That is where many inspection companies struggle. The field ticket is a carbon copy in a truck. The timesheet is a spreadsheet. The rate sheet is a PDF attached to an MSA that was renegotiated last year. Equipment charges depend on who remembers which crawler went to Baton Rouge. Then the invoice is rejected because the PO line is wrong, and payment slides by another month without anyone deciding it should.</p><p>The Invoicing app in the Atlantis NDT ERP was set up for this kind of billing. It is part of our <a href=\"/erp\">NDT ERP built on Odoo</a>, pre-configured for inspection companies and deployed by our team. Hours, equipment and consumables recorded on the job become the invoice lines, with the PO, site and method attached, so your billing team reviews and sends rather than rebuilds.</p><p>This page walks through how US NDT companies typically bill — field tickets, rate sheets, radiography crews, turnaround work, pipeline spreads, fabrication and aerospace shop work, sales tax and payment terms — and how the app handles each part.</p><h2>Field tickets, MSAs and the PO your client's AP team checks</h2><p>Most US industrial clients work under a master service agreement with an attached rate sheet, then issue a purchase order or work order per job, per unit or per month. On site, a client representative signs a daily field ticket or timesheet confirming the crew, hours and equipment. Accounts payable will compare your invoice with all three documents.</p><p>The Atlantis ERP keeps those pieces together. The Project app records the client PO, the contract, the site, the methods and the codes that apply. The invoice header carries the NDT project, the job or PO number, the site, the invoice type and the industry sector. Each invoice line can show the technician, the method, the equipment serial, the rate type and the days or hours — the same detail a field ticket shows.</p><p>How you capture the signed field ticket is agreed during implementation. Some companies attach a scan or photo of the signed ticket to the job record; others have the supervisor approve timesheets in the ERP after the client representative signs the paper copy. Either way, when a client disputes a line, you can point to the approved timesheet entry with the date, technician and work type recorded at the time.</p><p>Many large operators require invoices through their own supplier portals. The ERP does not claim a built-in connection to any portal. What it gives you is an invoice that already carries the references those portals ask for, so the upload is a copy job rather than a research project. Any export format a key client insists on can be part of the customization scope agreed with you.</p><h2>Rate sheets: technician levels, methods and overtime</h2><p>US NDT rate sheets are rarely simple. One MSA might list separate rates for Level I, Level II and Level III technicians, a higher rate for advanced UT such as phased array or TOFD, a rate for a radiography crew, a per diem, mileage and a truck charge. Overtime rules differ by client: some pay overtime after eight hours in a day, some after forty in a week, some only for Sundays and holidays.</p><p>Timesheets in the Atlantis ERP are built for this. Each entry records the work type — inspection, travel, standby or setup — plus the method, site, client and equipment serial. Every entry has a billable flag and a rate multiplier, so time-and-a-half or double time is recorded against the hour it applies to, not reconstructed at month end. Billable hours feed billing with the multiplier applied.</p><p>During implementation we map your rate sheets to work types, technician levels, methods and multipliers. If one refinery pays standby at the full rate and another at a reduced rate, that rule goes into the configuration. If you bill a Level III review hour separately from field inspection, it gets its own service line.</p><p>There is also a compliance angle. US clients audit your written practice under ASNT SNT-TC-1A, and some contracts call for ANSI/ASNT CP-189 qualification. Nobody wants to pay for inspection performed by a technician whose certification lapsed. The Certificates app records each technician's scheme, level, method and expiry, and the Timesheets app warns when a technician's certificate is not valid — so your supervisor sees it before the hours reach an invoice. The <a href=\"/erp/apps/certificates\">Certificates app</a> page covers certification tracking in detail.</p><h2>Radiography crews, sources and night shots</h2><p>Industrial radiography is billed differently from most other methods, and the reasons are regulatory. Under NRC rules, and the matching rules in Agreement States such as Texas and Louisiana, radiography at a temporary job site needs at least two qualified people present — a radiographer plus at least a radiographer's assistant. That is why US rate sheets usually price RT as a crew rather than as one technician.</p><p>Shooting also tends to happen at night or around shift changes, when a plant can clear the area. Those hours often carry a night or overtime premium, and there may be standby while a permit is issued or an area is barricaded.</p><p>In the ERP, both crew members log time against the job, and the rate multiplier and work type capture night and standby hours. The equipment serial on the invoice line ties the exposure device and related equipment to the job. The employee NDT profile records radiation safety training and radiation badge number, which helps you confirm the crew on the ticket is a crew you are allowed to send.</p><p>Film, chemicals and other radiography consumables are tracked in Asset Management and Inventory with a movement ledger, so the consumables subtotal is based on what was drawn for the job. The Fleet app records whether a vehicle can carry radioactive sources, its transport licence and expiry, and its assignment to projects with mileage. If you charge a truck or mileage to the client, how that charge reaches the invoice is set up during implementation.</p><p>The result is an RT invoice where the crew, the premium hours, the equipment and the film each stand on their own records — which is exactly what a refinery's contract administrator will ask to see.</p><h2>Turnarounds on the Gulf Coast</h2><p>Refinery and petrochemical turnarounds around Houston, Beaumont-Port Arthur, Lake Charles and Baton Rouge are where many US NDT companies earn a large share of their year, and where billing goes wrong fastest. One turnaround can put dozens of technicians on days and nights, across several units, against several POs or work orders, for weeks.</p><p>Clients usually want invoices weekly, sometimes split by unit or cost code, and they want them to reconcile with their own turnaround tracking. If your office builds those invoices by hand from paper tickets, they will be late, and late turnaround invoices tend to get argued.</p><p>The Invoicing app helps in three ways:</p><ul><li><strong>Cost centres on invoice lines</strong> let you split one turnaround by unit, work order or client cost code as the contract requires.</li><li><strong>Separate subtotals for labour, equipment and consumables</strong> match the way many turnaround budgets are structured.</li><li><strong>Approved timesheets feed billing</strong>, so the weekly invoice is a review of hours your supervisors already approved, not a new data entry exercise.</li></ul><p>Before the turnaround starts, the Team Assignments app blocks double-booking of technicians and equipment serials and warns when assigned equipment is out of calibration. That matters for billing too: a technician double-booked across two plants produces two sets of hours that one client will reject, and an instrument out of calibration can put a week of readings in doubt.</p><p>Afterwards, the financial dashboard shows what the event actually earned — revenue, cost of sales and gross margin — with outstanding invoices visible so you know which client is holding your cash.</p><h2>Pipeline spreads, fabrication shops and aerospace work</h2><p>Not every US job is a plant turnaround. Pipeline construction for operators regulated by PHMSA runs on spreads, with RT or AUT crews following the welders and daily weld counts reported to the operator or its inspection contractor. Some pipeline work is billed by the day per crew; some per weld or per joint. Fabrication shops building vessels to ASME Section VIII, with examinations to ASME Section V, often want shop inspections billed per job, per heat or per drawing.</p><p>Aerospace work is different again. Shops working to NAS 410 personnel qualification and customer specifications usually bill per part, per lot or per purchase order line, with the inspection report and certificate of conformance as the supporting evidence.</p><p>Each invoice line in the ERP carries the rate type and the days or hours, plus the method, technician and equipment serial. Day-rate and hourly billing work directly from timesheets. Unit-based billing, such as per weld, per film or per part, is set up as service products and rate rules during implementation, based on your contracts. One model does not fit every client, so the configuration follows how your clients buy.</p><p>For API 510, 570 and 653 inspection work on in-service equipment, clients often want the report before they approve the invoice. The ERP's NDT Reports app handles the report workflow through review, approval and sending. For clients who want more than a PDF, our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places inspection results on a 3D model of the asset. It is a separate product that works alongside the ERP, and it gives asset owners a clear visual record of what they paid for.</p><h2>Sales tax, payment terms and retainage</h2><p>Sales tax on services in the USA is set state by state, and in places by locality. Whether an NDT inspection is taxable can depend on the state, on what is being inspected and on whether the work sits inside a larger taxable contract. That is a question for your CPA. Our job is to configure the taxes and fiscal settings your accountant specifies, using standard Odoo accounting, so the right treatment applies per client and per location. No certification against any tax scheme is claimed.</p><p>Payment terms are the bigger cash problem for most US NDT companies. Large operators commonly ask for Net 45, Net 60 or longer, and some offer faster payment only through an early-payment discount programme. Construction and EPC work may hold retainage until project completion. When you pay technicians weekly and carry expensive equipment, those gaps add up quickly.</p><p>The ERP sets payment terms per client so invoice due dates reflect what you actually signed. Payments are recorded against invoices using standard Odoo payments, and standard payment reminders let you follow up consistently with wording and timing you choose. The outstanding invoices view on the dashboard shows exactly where the cash is sitting.</p><p>Retainage handling depends on the contract and is configured as part of the customization scope agreed with you. Out of the box, the invoice type on the header lets you tell interim invoices from final ones, and cost centres let a project with retainage be followed separately.</p><h2>The financial dashboard for US NDT owners</h2><p>Owners of US inspection companies usually know their revenue. Fewer know their margin by service line or by sector without waiting for the accountant. The Invoicing app includes a financial dashboard with revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, vendor bills and expenses, plus a 12-month view.</p><p>Because every invoice carries the industry sector and cost centre, you can see whether refining turnarounds, pipeline construction, fabrication shop work or aerospace inspection is carrying the business. If per diems and travel are eating the margin on out-of-state work, the Expenses app — where field expenses and per diems are recorded and re-billed to jobs — makes that visible.</p><p>For companies with branches in, say, Houston and Baton Rouge, cost centres give each branch manager their own numbers while the owner sees the combined picture.</p><h2>Implementation for a US NDT company</h2><p>We deploy and set up the ERP for you. For US companies, Invoicing implementation typically covers:</p><ol><li>Mapping your MSA rate sheets to work types, technician levels, methods and rate multipliers.</li><li>Setting up the taxes and fiscal settings your CPA specifies for the states you work in.</li><li>Cost centres for branches, service lines or major client accounts.</li><li>A custom invoice layout with your logo, remit-to details and the PO, site and job references your clients expect.</li><li>Equipment by serial number, rental rates where you charge them, and consumables such as film, penetrant and couplant.</li><li>Payment terms per client and a reminder sequence.</li><li>Open invoices and opening balances, so receivables are right from day one.</li><li>Short training for billing staff, supervisors and technicians.</li></ol><p>The ERP is fully customizable, affordable and accessible, and pricing is quote on request. Browse the other <a href=\"/erp/apps\">ERP apps</a> to see what connects to Invoicing.</p><h2>Frequently asked questions</h2><h3>Can the ERP bill a radiography crew correctly?</h3><p>Yes. Each crew member logs time against the job with work type and rate multiplier, and invoice lines carry the technician and equipment serial. Whether the invoice shows a single crew rate or individual lines is set up during implementation to match your rate sheet.</p><h3>Does it handle overtime and night premiums?</h3><p>Yes. Every timesheet entry has a rate multiplier, so premium hours are recorded when they are worked and carried into billing. Your client-specific overtime rules are mapped during setup.</p><h3>Can I keep signed field tickets with the job?</h3><p>Yes. How signed tickets are captured — attached to the job record or confirmed through supervisor timesheet approval — is agreed during implementation so disputes can be answered from one place.</p><h3>Will it calculate US sales tax?</h3><p>Taxes are configured during implementation using standard Odoo accounting, following your CPA's instructions for the states and clients involved. We do not decide taxability and claim no tax certification.</p><h3>Can it submit invoices to my client's supplier portal?</h3><p>No built-in portal connection is claimed. Invoices carry the PO, site and job references portals ask for, and any specific export a client requires can be scoped with you.</p><h3>Will it stop me billing hours from a technician with an expired cert?</h3><p>Timesheets warn when a technician's certificate is not valid, so the supervisor sees the problem at approval, before the hours are invoiced.</p><h2>Book a US-focused demo</h2><p>Bring a real job: a turnaround week, a pipeline spread or a shop order. We will show it moving from approved timesheets and equipment issues to a finished invoice with your PO and site on it.</p><p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20USA\">Book an Invoicing demo for your US operation</a> or <a href=\"/contact?service=erp&amp;subject=Invoicing%20quote%20USA\">request a quote</a> for the Atlantis NDT ERP.</p>\n<h2>Invoicing by region</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing global overview</a></li><li><a href=\"/erp/apps/invoicing/canada\">Invoicing in Canada</a></li><li><a href=\"/erp/apps/invoicing/europe\">Invoicing in UK &amp; Europe</a></li><li><a href=\"/erp/apps/invoicing/middle-east\">Invoicing in Middle East</a></li><li><a href=\"/erp/apps/invoicing/india\">Invoicing in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(United%20States)\">Send an enquiry about Invoicing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/invoicing/canada","publishedAt":"2026-09-27","title":"NDT Invoicing Software in Canada | Atlantis NDT","description":"Bill Canadian NDT jobs from approved timesheets, field tickets, equipment and consumables, with GST/HST set up for your provinces. Book a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Invoicing Software for Inspection Companies in Canada</h1>\n<p>Invoices from timesheets and completed jobs, with payments and reminders. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>What makes NDT billing in Canada different</h2><p>Canadian NDT companies bill into some of the most document-heavy client environments anywhere. An oil sands operator north of Fort McMurray, an upgrader near Edmonton, a pipeline construction spread in northern British Columbia, a pressure vessel shop in Calgary and a nuclear refurbishment project in Ontario all want different things on an invoice, and they all want it to match their own records exactly.</p><p>Add rotational work schedules, camp-based crews, winter conditions, spring and fall turnaround seasons and a tax system that changes with the province of supply, and it is easy to see why so many inspection companies still build invoices by hand in spreadsheets. It is also easy to see why those invoices get rejected.</p><p>The Invoicing app in the Atlantis NDT ERP is designed to take that re-keying out. It is part of our <a href=\"/erp\">NDT ERP built on Odoo</a>, pre-configured for inspection companies and set up by our team. Approved timesheets, equipment issued by serial number and consumables drawn from stock become invoice lines that carry the project, PO or work order, site, method and technician. The billing team checks and sends instead of rebuilding.</p><p>This page covers the parts of Canadian NDT billing that trip companies up — daily field tickets and client cost coding, rotational and camp work, radiography crews under CNSC licensing, certification evidence, provincial sales taxes, holdback and prompt payment rules, and cross-border work — and how the app handles each.</p><h2>Field tickets and client cost coding in Western Canada</h2><p>In Alberta and British Columbia, most industrial NDT work is authorized under a master service agreement and then a PO, work order or service order, with a daily field ticket signed by the client's representative. Many large operators require every line on the invoice to carry their own cost coding — area, unit, work order, cost element — and they reconcile invoices line by line against the signed tickets. Many now receive field tickets and invoices through digital ticketing or supplier platforms.</p><p>The Atlantis ERP holds the pieces a ticket reconciliation needs. The Project app records the client PO, contract, site, methods and codes. The invoice header carries the NDT project, job or PO number, site, invoice type and industry sector, and each line can carry a cost centre, method, equipment serial, technician, rate type and days or hours.</p><p>The ERP does not claim a built-in connection to any ticketing or supplier platform. What it does is produce invoice data that already carries the references those platforms ask for. How client cost codes are represented — as cost centres, as line references or on the invoice layout — is decided during implementation, client by client if needed. If a key operator needs a specific export, that goes into the customization scope agreed with you.</p><p>Signed tickets can be kept with the job record, and supervisor approval of timesheets gives you an internal sign-off that mirrors the client's. When a line is queried, you answer from one record rather than digging through a truck's glovebox.</p><h2>Rotations, camp work, travel days and standby</h2><p>Oil sands and remote pipeline work rarely looks like a normal work week. Technicians fly in on a rotation, live in the owner's camp or in hotel accommodation, and work long shifts for a stretch before flying out. Contracts differ on whether travel days are billable, whether a living-out allowance applies when camp is not provided, and how weather or permit standby is paid.</p><p>Timesheets in the ERP record the work type for each entry — inspection, travel, standby or setup — along with method, site, client and equipment serial. A billable flag and a rate multiplier on each entry mean a travel day can be billed at a travel rate, or not billed at all, and extended shifts or statutory holiday work can carry the right multiplier from the moment they are logged.</p><p>Per diems, living-out allowances, flights and vehicle costs are recorded in the standard Expenses app and can be re-billed to the job under whatever rule your contract sets. The Team Assignments app records mobilisation and demobilisation dates and blocks double-booking of technicians, so the rotation schedule on the invoice matches who was actually on site.</p><p>Standby is where many Canadian NDT companies leave money behind. A crew waiting for a confined space permit at minus thirty is still a cost to you. When standby is logged as its own work type and approved by your supervisor, it reaches the invoice with the date and reason visible, and the client's representative has already seen it on the ticket.</p><h2>Certification evidence clients will ask for</h2><p>Canadian clients commonly expect NDT technicians to hold certification from Natural Resources Canada's NDT Certification Body under CAN/CGSB-48.9712, which aligns with ISO 9712. Some contracts, particularly with US-linked owners, also accept or require ASNT SNT-TC-1A based certification. Either way, owners do not want to pay for inspection by someone whose certification has lapsed.</p><p>The Certificates app records each technician's scheme (ISO 9712, SNT-TC-1A and others), level, method, certifying body and expiry. It flags certificates expiring within ninety days and marks expired ones automatically, and the Timesheets app warns when a technician's certificate is not valid. That warning appears when hours are approved, before they are invoiced. See the <a href=\"/erp/apps/certificates\">Certificates app</a> for the full detail.</p><p>Atlantis does not provide NRCan certification training; the app simply records the certificates your technicians already hold. Our own training programmes are based on ASNT SNT-TC-1A.</p><p>Radiography adds another layer. Under CNSC licensing, exposure devices must be operated by a certified exposure device operator (CEDO), with trainees working under their supervision. That shapes how RT is priced — typically as a crew — and who can appear on an RT invoice line. The employee NDT profile records radiation safety training and dosimeter badge number, and the Fleet app records vehicles that can carry radioactive sources along with transport licence expiry, so the crew and truck on the ticket are ones you are permitted to send.</p><h2>Pipelines, pressure equipment and nuclear work</h2><p>Different Canadian sectors buy NDT in different ways, and the invoice needs to follow.</p><ul><li><strong>Pipelines.</strong> Construction to CSA Z662 often runs on spreads with RT or AUT crews following the welders. Billing may be per crew-day or per weld. Day-rate billing flows from timesheets; per-weld or per-film billing is set up as service products and rate rules during implementation.</li><li><strong>Pressure equipment.</strong> Shops fabricating boilers and pressure vessels under ABSA oversight in Alberta, or equivalent jurisdictions elsewhere, and structural fabricators working to CSA W59, usually want inspections billed per job, drawing or heat, with the report as evidence.</li><li><strong>Nuclear.</strong> Refurbishment and outage work at Ontario nuclear stations brings strict timesheet approval, security-cleared crews and billing split across many work packages. Cost centres on invoice lines let one contract be split by work package or area.</li></ul><p>Across all three, clients commonly hold the invoice until they have the report. The ERP's NDT Reports app manages review, approval and sending, so report and invoice come from the same job. For owners who want to see findings in context, our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places inspection results on a 3D model of the asset. It is a separate product that works alongside the ERP.</p><h2>GST, HST, PST and QST</h2><p>Canadian sales tax on NDT services depends on the place of supply. Work in Alberta attracts GST only. Ontario and the Atlantic provinces use HST. British Columbia, Saskatchewan and Manitoba have their own provincial sales taxes alongside GST, with their own rules on which services are taxable. Quebec applies QST alongside GST. A company with crews in three provinces can be issuing invoices under three tax treatments in the same week.</p><p>The ERP uses standard Odoo accounting for taxes. During implementation we configure the tax rates and fiscal positions your accountant specifies, so the right treatment applies by client and by place of supply, and your GST/HST registration number and any provincial registrations appear on the invoice layout. We follow your accountant's view on what is taxable; we do not decide it, and we claim no certification against any tax scheme.</p><p>For work in Quebec, the Charter of the French Language shapes business documents. French or bilingual invoice layouts can be configured during implementation, using the language support built into Odoo.</p><h2>Holdback, prompt payment and payment terms</h2><p>Canadian construction law affects how NDT companies get paid on project work. Ontario's Construction Act and Alberta's Prompt Payment and Construction Lien Act set timelines for paying proper invoices on construction projects and require holdback to be retained until conditions are met. Other provinces have their own lien and holdback rules. Whether a given NDT scope counts as construction work is a question for your adviser, but where it does, the format and timing of your invoice matter.</p><p>Outside construction, large operators commonly pay on extended terms, and some tie payment to acceptance of the report or the ticket reconciliation. The ERP sets payment terms per client, so due dates reflect your agreement. Payments are recorded against invoices using standard Odoo payments, and standard reminders help you follow up at the right time with the right tone.</p><p>Holdback tracking and progress billing are configured as part of the customization scope agreed with you. Out of the box, the invoice type field separates interim from final invoices, and cost centres keep a long project's billing visible on its own.</p><p>Cross-border work is common for Canadian inspection companies, particularly with US owners and EPCs. Invoicing in another currency and handling the related tax treatment are set up during implementation if you need them.</p><h2>Equipment, consumables and the quote behind the invoice</h2><p>Equipment is where Canadian NDT companies most often under-bill. A phased array kit, an AUT system, a crawler or a heated-enclosure setup for winter work is costly to own, calibrate and move, and most rate sheets allow it to be charged separately. But if the charge depends on someone remembering which unit went north and for how many days, it gets missed or understated.</p><p>In the Atlantis ERP, instruments are tracked by serial number in the Asset Management app, with issue and return records, reservations and movement history, and rental rates can be recorded against equipment. Invoice lines can carry the equipment serial, so the equipment subtotal ties back to the units actually issued to the job. Consumables — couplant, penetrant and developer, magnetic particles, film and chemicals, PPE — are tracked with reorder levels and a movement ledger, so the consumables subtotal reflects what was drawn rather than an allowance.</p><p>The invoice also depends on what was quoted. In the <a href=\"/erp/apps/quotations\">Quotations app</a>, NDT service products are flagged by method and category, with the job type, site, dates and applicable codes on the quote. The client can accept online, and the quote converts to a sales order. When the invoice is prepared, the rates and scope the client accepted are already in the system, rather than in an email chain from six months ago.</p><p>That chain — quote, project, dispatch, timesheets, equipment issue, report, invoice — is what lets a billing clerk in Edmonton produce an invoice for a crew that worked in Fort McMurray without phoning three people to confirm what happened.</p><h2>Who uses the Invoicing app</h2><ul><li><strong>Billing and accounts staff</strong> prepare draft invoices from approved time, equipment and consumables, check PO and cost coding, post invoices, record payments and send reminders.</li><li><strong>Field supervisors and operations managers</strong> approve timesheets, confirm standby and travel entries and check equipment issued to the job before it is billed.</li><li><strong>Project and contract managers</strong> check invoices against the MSA rates and the scope of each PO, especially on long turnarounds and nuclear outage packages.</li><li><strong>Owners and general managers</strong> watch margin, receivables and the split of revenue by sector, branch and service line on the financial dashboard.</li><li><strong>Technicians</strong> log hours by work type from the field; clear entries on their side mean fewer questions from the office.</li></ul><p>Access rights follow the standard Odoo permission model and are set during implementation, so each role sees what it needs and nothing it should not.</p><h2>The financial dashboard and cost centres</h2><p>The Invoicing app includes a financial dashboard with revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, vendor bills and expenses, and a 12-month view. For a Canadian NDT company with seasonal peaks around spring and fall turnarounds, the 12-month view is where you see whether a strong season really paid for the quiet months.</p><p>Every invoice carries the industry sector, and every line can carry a cost centre. Split by branch — Edmonton, Calgary, Fort McMurray, Sarnia — or by service line, and you can see which part of the business carries the margin and which one only looks busy.</p><h2>Implementation for a Canadian NDT company</h2><p>We deploy and set up the ERP for you. Typical Invoicing scope for Canadian companies includes:</p><ol><li>Mapping your MSA rates to work types, technician levels, methods and multipliers, including travel and standby rules.</li><li>GST, HST, PST and QST treatment configured with your accountant for the provinces you work in.</li><li>Client cost coding represented as cost centres or line references.</li><li>Custom invoice layout, in English, French or both.</li><li>Equipment by serial with rental rates, and consumables such as film, couplant and penetrant.</li><li>Payment terms per client and a reminder sequence.</li><li>Open invoices and opening balances migrated.</li><li>Training for billing staff, supervisors and technicians.</li></ol><p>The ERP is affordable, accessible and fully customizable; pricing is quote on request. See all the <a href=\"/erp/apps\">ERP apps</a> that feed Invoicing.</p><h2>Frequently asked questions</h2><h3>Can the invoice carry my client's cost codes?</h3><p>Yes. Lines can carry a cost centre, and the invoice header holds the project, PO or work order and site. How each client's coding is mapped is set during implementation.</p><h3>Does it integrate with digital field ticket platforms?</h3><p>No built-in integration is claimed. Invoices carry the references those platforms need, and any specific export can be scoped with you.</p><h3>Can travel days and standby be billed differently from inspection?</h3><p>Yes. Timesheet entries carry a work type — inspection, travel, standby or setup — plus a billable flag and rate multiplier, so each is billed according to your contract.</p><h3>Does it handle GST, HST and provincial taxes?</h3><p>Taxes are configured during implementation using standard Odoo accounting, following your accountant's instructions by province. No tax certification is claimed.</p><h3>Can it record NRCan ISO 9712 certifications?</h3><p>Yes. The Certificates app records ISO 9712, SNT-TC-1A and other schemes, and timesheets warn when a technician's certificate is not valid. Atlantis does not train for NRCan certification.</p><h3>Can it track holdback?</h3><p>Holdback and progress billing are configured as part of the customization scope agreed with you, based on your contracts and adviser's guidance.</p><h2>Book a demo built around a Canadian job</h2><p>Bring a real example — a rotation on an oil sands site, a pipeline spread or a shop order with ABSA involvement — and we will run it from timesheets to invoice with your tax setup.</p><p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20Canada\">Book an Invoicing demo for Canada</a> or <a href=\"/contact?service=erp&amp;subject=Invoicing%20quote%20Canada\">request a quote</a> for the Atlantis NDT ERP.</p>\n<h2>Invoicing by region</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing global overview</a></li><li><a href=\"/erp/apps/invoicing/usa\">Invoicing in United States</a></li><li><a href=\"/erp/apps/invoicing/europe\">Invoicing in UK &amp; Europe</a></li><li><a href=\"/erp/apps/invoicing/middle-east\">Invoicing in Middle East</a></li><li><a href=\"/erp/apps/invoicing/india\">Invoicing in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(Canada)\">Send an enquiry about Invoicing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/invoicing/europe","publishedAt":"2026-09-27","title":"NDT Invoicing Software in the UK and Europe | Atlantis NDT","description":"Invoice UK and European NDT work from approved timesheets, equipment serials and consumables, with VAT set up for your countries. Book a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Invoicing Software for Inspection Companies in the UK and Europe</h1>\n<p>Invoices from timesheets and completed jobs, with payments and reminders. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>NDT billing in the UK and Europe: purchase orders first</h2><p>If you run an inspection company in Aberdeen, Teesside, the Midlands, Rotterdam or the Ruhr, you know the first rule of getting paid: no PO, no pay. Most large UK and European clients run strict purchase-to-pay processes. An invoice without a valid purchase order or call-off number, or with lines that do not match what was ordered, goes back to you — and the payment clock starts again from zero.</p><p>European NDT work is often bought under framework agreements with a schedule of rates, then released through call-off orders per job, per shutdown or per month. Offshore work in the North Sea adds rotations, helicopter logistics and weather standby. Fabrication for pressure equipment brings notified body involvement and drawing-level traceability. Cross-border work within Europe brings different VAT treatments on the same day's invoices.</p><p>The Invoicing app in the Atlantis NDT ERP is set up for this. It is part of our <a href=\"/erp\">NDT ERP built on Odoo</a>, pre-configured for inspection companies and deployed by our team. Approved timesheets, equipment issued by serial number and consumables drawn from stock become invoice lines that carry the project, PO or call-off, site, method and technician.</p><p>This page covers how UK and European NDT companies typically bill — frameworks and call-offs, offshore rotations, pressure equipment fabrication, VAT and reverse charge, payment terms and retention, and GDPR — and how the app handles each.</p><h2>Frameworks, call-offs and what the invoice must show</h2><p>A typical UK or European client relationship runs like this: a framework or master agreement sets the schedule of rates; a call-off or PO authorizes a specific job or period; a client representative approves timesheets or a job sheet; and accounts payable matches your invoice to all three. Many clients also expect the invoice to reference their own work order or cost code.</p><p>In the Atlantis ERP, the Project app records the client PO, contract, site, methods, codes and scope. The invoice header carries the NDT project, the job or PO number, the site, the invoice type and the industry sector. Each line can carry a cost centre, method, equipment serial, technician, rate type and days or hours, with separate subtotals for labour, equipment and consumables.</p><p>Many large clients also require invoices through supplier portals or procurement networks. The ERP does not claim a built-in connection to any of these. It produces invoices that already carry the references those systems ask for, and any specific export format for a key client can be part of the customization scope agreed with you.</p><p>The invoice PDF uses a custom layout configured for your company, including your registered company details and VAT number, so it meets the presentation your clients and your accountant expect.</p><h2>North Sea offshore: rotations, travel and weather</h2><p>Offshore inspection out of Aberdeen and the wider North Sea is billed in its own way. Technicians work long shifts on a rotation, with mobilisation through a heliport and sometimes days lost to fog or high winds. Contracts differ on whether travel days, survival-training days and weather standby are billable, and at what rate. Rope access inspection teams add their own rate structures.</p><p>Timesheets in the ERP record a work type for each entry — inspection, travel, standby or setup — along with method, site, client and equipment serial. A billable flag and a rate multiplier on each entry let an offshore day, an onshore standby day and a travel day each be billed according to your contract. Waiting on weather logged as standby, and approved by your supervisor, reaches the invoice with its date and reason already visible.</p><p>The Team Assignments app records mobilisation and demobilisation dates and blocks double-booking of technicians and equipment serials, so the people and instruments on the invoice match the rotation that actually went offshore. It also warns when assigned equipment is out of calibration — an important check before a unit spends two weeks on an installation you cannot easily get back to.</p><p>Offshore expenses — hotels before flights, travel to the heliport, per diems — are recorded in the Expenses app and can be re-billed to the job under whichever rule your contract sets.</p><h2>Certification evidence: PCN and EN ISO 9712</h2><p>Clients in the UK and Europe usually expect NDT technicians to hold third-party certification to EN ISO 9712, commonly through PCN administered by BINDT in the UK or through national schemes elsewhere in Europe. Some operators with US links also accept ASNT-based certification. Every client expects the certificate to be valid on the day of the inspection.</p><p>The Certificates app records each technician's scheme (PCN, ISO 9712, CSWIP, SNT-TC-1A and others), level, method, certifying body and expiry, with automatic status for expiring soon and expired. The Timesheets app warns when a technician's certificate is not valid, so the supervisor sees it at approval — before the hours reach an invoice. See the <a href=\"/erp/apps/certificates\">Certificates app</a> for more.</p><p>To be clear: Atlantis does not provide PCN, ISO 9712 or CSWIP training or certification. The app records certificates your technicians already hold. Our own training programmes are based on ASNT SNT-TC-1A.</p><p>This matters for billing because an invoice line for a technician whose certification lapsed mid-job is exactly the line a careful client will refuse to pay, and possibly the job they will ask you to repeat at your cost.</p><h2>Pressure equipment and fabrication work</h2><p>Fabrication shops building to the Pressure Equipment Directive 2014/68/EU, and to harmonised standards such as EN 13445, often buy NDT per weld, per drawing or per job, with examinations carried out to standards such as EN ISO 17640 for ultrasonic testing or EN ISO 17636 for radiographic testing. A notified body may review the records, and the shop's client wants full traceability from weld map to report.</p><p>The ERP's invoice lines carry the method, technician and equipment serial, and day-rate or hourly billing flows directly from timesheets. Unit-based billing — per weld, per radiograph, per drawing — is set up as service products and rate rules during implementation, following your contracts.</p><p>Reports and invoices come from the same job. The ERP's NDT Reports app captures drawing, WPS and procedure references and runs the report through review and approval before it is sent, which is usually what the shop needs before approving your invoice.</p><p>For asset owners who want inspection results in context rather than a stack of PDFs, our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places findings on a 3D model of the asset. It is a separate product that works alongside the ERP, and it can make the difference when bidding for owner-side integrity contracts.</p><h2>VAT, reverse charge and e-invoicing</h2><p>European NDT companies often issue invoices under several VAT treatments in the same week. Domestic work is charged at the local rate. Many cross-border business-to-business services within the EU fall under the reverse charge, where the invoice shows no VAT and the customer accounts for it, with specific wording required. UK companies supplying services to EU clients, and EU companies supplying UK clients, face their own post-Brexit place-of-supply rules. Offshore work can raise further questions depending on the installation's location.</p><p>The ERP uses standard Odoo accounting for taxes. During implementation we configure the VAT rates, fiscal positions and invoice wording your accountant specifies, so the correct treatment applies per client and per supply. We follow your adviser's view on what applies; we do not decide it.</p><p>Several European countries have introduced or are phasing in mandatory business-to-business e-invoicing, and others are following. We claim no certification against any national e-invoicing scheme. Where a requirement applies to your business, we discuss it with you and your adviser during scoping and agree what is included.</p><p>Multi-currency work — sterling, euro, Norwegian krone and others — is set up during implementation if your contracts need it.</p><h2>Payment terms, late payment rules and retention</h2><p>The EU Late Payment Directive sets default business-to-business payment periods and gives suppliers a right to statutory interest and recovery costs when invoices are paid late. The UK has its own late payment legislation with similar rights. In practice many large clients still push for long terms, and the invoice date and receipt date become important evidence if you ever need to rely on those rights.</p><p>In UK construction, the Housing Grants, Construction and Regeneration Act sets a payment notice regime for construction operations, and retention is commonly held on construction contracts. Whether your NDT scope falls under those rules is a question for your adviser, but where it does, invoice timing and content matter.</p><p>The ERP sets payment terms per client, records payments against invoices using standard Odoo payments, and sends standard payment reminders with wording and timing you choose. The outstanding invoices view on the financial dashboard shows which clients are holding your cash.</p><p>Retention and application-for-payment style billing are configured as part of the customization scope agreed with you. Out of the box, the invoice type field distinguishes interim from final invoices, and cost centres let a long project be followed on its own.</p><h2>GDPR and technician data on invoices</h2><p>NDT invoices can carry personal data. A line showing a technician's name, the dates they were on a client site and their hours is personal data under GDPR and the UK GDPR, and some clients insist on names while others do not need them.</p><p>Because the invoice layout is custom, what appears on the client-facing document is decided during implementation. Some companies show full names; others show initials, an employee reference or only the technician level. The underlying records stay in the ERP, where access follows the standard Odoo permission model, so billing staff see what they need and technicians see their own timesheets.</p><p>Keeping technician certification, vision tests and radiation badge details inside the ERP rather than in email attachments and shared folders also makes it easier to answer the question of where personal data is held and who can see it.</p><h2>Equipment, consumables and the quote behind the invoice</h2><p>Advanced UT equipment, eddy current arrays, crawlers and rope access kit are expensive to own, calibrate and ship to an offshore installation or a refinery in another country. Most European schedules of rates let them be charged separately, but only if you can show which units were used and for how long.</p><p>In the Atlantis ERP, instruments are tracked by serial number in the Asset Management app, with issue and return records approved by supervisors, reservations with clash prevention and inbound and outbound movements. Rental rates can be recorded against equipment. Invoice lines can carry the equipment serial, so the equipment subtotal ties back to the instruments actually issued to the job. Calibration records and certificate expiry sit on the same equipment record, which helps when a client asks for evidence that the unit on the invoice was in calibration while it was used.</p><p>Consumables — couplant, penetrant and developer, magnetic ink, film and chemicals, PPE — are tracked with reorder levels and a movement ledger, so the consumables subtotal reflects what was drawn for the job.</p><p>The invoice also depends on what was quoted and accepted. In the <a href=\"/erp/apps/quotations\">Quotations app</a>, NDT service products are flagged by method and category, and each quote carries the job type, site, project dates and applicable codes. The client can accept the quote online, and it converts to a sales order. When invoicing time comes, the accepted rates and scope are already in the system, not buried in a framework PDF and an email thread.</p><h2>Who uses the Invoicing app</h2><ul><li><strong>Accounts and credit control staff</strong> prepare invoices from approved time, equipment and consumables, check PO and call-off references, apply the right VAT treatment, record payments and chase overdue accounts.</li><li><strong>Operations managers and offshore coordinators</strong> approve timesheets, confirm standby and travel days and check equipment issued to each rotation.</li><li><strong>Contract managers</strong> check invoices against framework rates and call-off scope, especially on long shutdowns and fabrication packages.</li><li><strong>Directors and owners</strong> watch margin, receivables and revenue by sector and country on the financial dashboard.</li><li><strong>Technicians</strong> log hours by work type; clear entries mean fewer queries from the office and faster invoices.</li></ul><p>Access follows the standard Odoo permission model and is set during implementation, which also supports GDPR principles of limiting who sees personal data.</p><h2>The financial dashboard</h2><p>The Invoicing app includes a financial dashboard with revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, vendor bills and expenses, and a 12-month view. With cost centres by country, branch or service line, and the industry sector on every invoice, you can see whether offshore oil and gas, renewables, power generation, fabrication or aerospace is carrying your margin. For companies operating both sides of the North Sea, or with offices in the UK and continental Europe, cost centres give each office its own numbers while directors see the combined picture.</p><h2>Refinery, power and petrochemical shutdowns in Europe</h2><p>Planned shutdowns at refineries and chemical plants in the Antwerp-Rotterdam cluster, on the Humber, at Grangemouth and along the Rhine, and outages at power stations across the UK and continental Europe, pack months of inspection into a few weeks. NDT contractors often work alongside mechanical and scaffolding contractors, on day and night shifts, under the client's permit-to-work system. Clients want daily progress and invoices that reconcile with their shutdown cost control, frequently split by unit, work package or equipment tag range.</p><p>Shutdown billing breaks down when the office tries to rebuild three weeks of paper timesheets in the week after demobilisation. Night-shift premiums get missed, standby while waiting for permits or scaffolding is argued, and the equipment charge for the eddy current and IRIS kit that spent the whole event on exchanger bundles is understated.</p><p>In the Atlantis ERP, timesheets are approved as the shutdown runs, with work type, method, equipment serial and rate multiplier recorded when the hours are worked. Cost centres on invoice lines let one shutdown be split by unit or package as the contract requires, and the separate labour, equipment and consumables subtotals match the way most shutdown budgets are structured. Before mobilisation, Team Assignments blocks double-booking of technicians and equipment serials and warns about out-of-calibration equipment, so the crew and kit on the invoice are the crew and kit that were actually available.</p><p>The result is a shutdown invoice that goes out while the client's cost engineers still remember the job, supported by approved records instead of recollection.</p><h2>Implementation for a UK or European NDT company</h2><p>We deploy and configure the ERP for you. For UK and European companies, Invoicing implementation typically covers:</p><ol><li>Mapping framework schedules of rates to work types, technician grades, methods and rate multipliers, including offshore, onshore, travel and weather standby rules.</li><li>VAT rates, fiscal positions and reverse-charge wording configured with your accountant for the countries you invoice from and into.</li><li>Legal entity and currency setup for companies trading in more than one country.</li><li>Cost centres by office, country, service line or major client.</li><li>A custom invoice layout with registered company details, VAT number, PO and call-off references, and technician details shown to the level your GDPR approach allows.</li><li>Equipment by serial with rental rates, and consumables such as couplant, magnetic ink, penetrant and film.</li><li>Payment terms per client and a reminder sequence that reflects your credit control policy.</li><li>Migration of open invoices and opening balances, and short training for billing staff, coordinators and technicians.</li></ol><p>Anything beyond that — a specific export for a client's procurement network, retention schedules on construction contracts, application-for-payment formats — is agreed as part of the customization scope, so you know in advance what is included.</p><h2>Frequently asked questions</h2><h3>Will invoices show the client's PO or call-off number?</h3><p>Yes. The invoice header holds the NDT project, job or PO number, site, invoice type and industry sector, and each line can carry a cost centre.</p><h3>Can it apply reverse charge VAT?</h3><p>VAT treatments, including reverse-charge wording, are configured during implementation using standard Odoo accounting, following your accountant's instructions. No certification is claimed.</p><h3>Is it certified for national e-invoicing mandates?</h3><p>No. Where a mandate applies to you, we review it with you and your adviser during scoping.</p><h3>Can offshore standby and travel be billed separately?</h3><p>Yes. Timesheet entries carry work types — inspection, travel, standby or setup — with a billable flag and rate multiplier.</p><h3>Does it record PCN and ISO 9712 certificates?</h3><p>Yes, the Certificates app records them and timesheets warn when a cert is not valid. Atlantis does not train or certify for PCN or ISO 9712.</p><h3>Can I hide technician names on invoices?</h3><p>Yes. The custom invoice layout is set during implementation to show names, references or levels as your clients and GDPR obligations require.</p><h2>Book a demo for your UK or European operation</h2><p>We deploy the ERP for you, map your framework rates and configure VAT with your accountant. The ERP is affordable, accessible and fully customizable, with pricing on request. See all <a href=\"/erp/apps\">ERP apps</a>, then <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20Europe\">book an Invoicing demo</a> or <a href=\"/contact?service=erp&amp;subject=Invoicing%20quote%20Europe\">request a quote</a>.</p>\n<h2>Invoicing by region</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing global overview</a></li><li><a href=\"/erp/apps/invoicing/usa\">Invoicing in United States</a></li><li><a href=\"/erp/apps/invoicing/canada\">Invoicing in Canada</a></li><li><a href=\"/erp/apps/invoicing/middle-east\">Invoicing in Middle East</a></li><li><a href=\"/erp/apps/invoicing/india\">Invoicing in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(UK%20%26%20Europe)\">Send an enquiry about Invoicing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/invoicing/middle-east","publishedAt":"2026-09-27","title":"NDT Invoicing Software in the Middle East | Atlantis NDT","description":"Invoice GCC NDT manpower, shutdown crews, equipment and consumables from approved timesheets, with VAT set up locally. Book a demo of the Atlantis ERP.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Invoicing Software for Inspection Companies in the Middle East</h1>\n<p>Invoices from timesheets and completed jobs, with payments and reminders. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work is billed across the Gulf</h2><p>NDT billing in Saudi Arabia, the UAE, Qatar, Kuwait, Oman and Bahrain looks very different from a small job-by-job invoice. Much of the work runs under long-term service contracts with national oil companies and their contractors — Saudi Aramco, ADNOC group companies, QatarEnergy, KNPC and others — and under EPC contracts on new plants, pipelines and offshore facilities. Crews are large, often expatriate, and mobilised for months. Shutdowns and turnarounds concentrate a huge amount of work into a few weeks.</p><p>Getting paid in that environment depends on paperwork matching exactly: the contract schedule of rates, the call-off or service order, the monthly timesheet signed by the client representative, the completion certificate or service entry the client raises, and your invoice. One mismatch and the invoice returns, often weeks later, and the payment cycle starts again.</p><p>The Invoicing app in the Atlantis NDT ERP is built to reduce those mismatches. It is part of our <a href=\"/erp\">NDT ERP built on Odoo</a>, pre-configured for inspection companies and deployed by our team. Approved timesheets, equipment by serial number and consumables drawn from stock become invoice lines carrying the project, PO or work order, site, method and technician.</p><p>This page covers manpower-based and job-based billing, shutdown invoicing, expatriate crew costs, technician approval, VAT across the GCC, retention and payment cycles — and how the app handles each.</p><h2>Manpower billing versus job-based billing</h2><p>Gulf NDT contracts usually fall into two shapes. Under manpower supply, the client pays a monthly or daily rate per technician by category — Level II UT, RT crew, PAUT operator, Level III — plus agreed overtime. Under job-based contracts, the client pays per scope, per weld, per film or per inspection package. Many companies run both at once, sometimes for the same client.</p><p>Timesheets in the ERP record the work type — inspection, travel, standby or setup — with method, site, client and equipment serial, a billable flag and a rate multiplier. For manpower contracts, the approved hours per technician, with overtime multipliers applied, flow straight into billing. Each invoice line can carry the technician, method, rate type and days or hours, so the client's representative can tick it off against the signed monthly timesheet.</p><p>For job-based contracts, unit rates such as per weld, per film or per package are set up as service products and rate rules during implementation, following your contract schedules. The Project app records the client PO, contract, site, methods, codes and scope, and the invoice header carries the NDT project, job or PO number, site, invoice type and industry sector.</p><p>Working patterns also shape the timesheet. Rest-day and public holiday work usually carries a premium, and reduced working hours during Ramadan under local labour rules change what a normal shift means. Recording these through the rate multiplier as hours are logged, rather than adjusting at month end, is what stops disputes.</p><h2>Shutdowns and turnarounds</h2><p>Plant shutdowns across the Eastern Province, Jubail, Yanbu, Ruwais, Ras Laffan and Kuwait's refineries bring together large NDT crews on day and night shifts, often from several subcontractors, for a tightly scheduled window. Clients want daily progress and usually invoices split by unit, work order or package.</p><p>The Invoicing app helps in several ways:</p><ul><li><strong>Cost centres on invoice lines</strong> let one shutdown be split by unit, package or client work order.</li><li><strong>Separate subtotals for labour, equipment and consumables</strong> match how most shutdown budgets are structured.</li><li><strong>Approved timesheets feed billing</strong>, so the post-shutdown invoice is a check of hours already approved, not weeks of rebuilding from paper.</li></ul><p>Before the shutdown, the Team Assignments app blocks double-booking of technicians and equipment serials, records mobilisation and demobilisation dates and warns when assigned equipment is out of calibration. An out-of-calibration UT set discovered after a shutdown can put a whole package of readings — and its invoice — in question.</p><p>The Team Assignments calendar also shows utilisation and next available date for each technician, which helps you decide whether to bring in additional manpower from another branch or country for the peak, and whether the rates on that contract cover it.</p><h2>Expatriate crews, mobilisation and documents</h2><p>Most Gulf NDT companies depend on expatriate technicians. That brings costs that do not exist elsewhere: visa and residence permit processing (such as iqama renewals in Saudi Arabia), medical checks, flights, accommodation and site transport. Some contracts include these costs in the manpower rate; others allow mobilisation and demobilisation to be billed separately; some let accommodation or transport be re-charged.</p><p>Mobilisation and demobilisation dates are recorded against assignments. Flights, accommodation and per diems are recorded in the standard Expenses app and can be re-billed to the job under whatever rule your contract sets. The Fleet app records vehicle assignment to projects and drivers with mileage, and whether a vehicle may carry radioactive sources, with its transport licence expiry. How mobilisation charges and re-billable costs appear on the invoice is set up during implementation.</p><p>Tracking visa or residence permit validity itself is not a built-in feature of the Invoicing app. If you need those documents tracked alongside technician records, that forms part of the customization scope agreed with you. Medical fitness expiry, however, is already part of the employee NDT profile.</p><h2>Technician approval and certification evidence</h2><p>Gulf clients commonly require NDT technicians to be approved before they work on site. Saudi Aramco, for example, sets its own requirements in its engineering and inspection standards (SAES and SAIS) and runs contractor and personnel approval processes. ADNOC group companies, QatarEnergy and KNPC have their own vendor and personnel requirements. ASNT SNT-TC-1A based certification and ISO 9712 certification are both widely seen on Gulf sites, often held by the same crew.</p><p>The Certificates app records each technician's scheme, level, method, certifying body and expiry, and marks certificates expiring within ninety days or expired. The Timesheets app warns when a technician's certificate is not valid, so the supervisor sees the problem before hours reach an invoice. On a manpower contract, a technician billed while uncertified is a likely deduction or dispute. See the <a href=\"/erp/apps/certificates\">Certificates app</a> for more detail.</p><p>Client-specific approvals can be recorded under the \"other\" scheme option where appropriate; any dedicated client approval register is part of the customization scope agreed with you. Atlantis's own training is based on ASNT SNT-TC-1A; we do not provide ISO 9712 training.</p><p>Radiography crews also need radiation safety evidence under national regulators. The employee NDT profile records radiation safety training and radiation badge number.</p><h2>VAT across the GCC</h2><p>Tax treatment differs across the region. Saudi Arabia, the UAE, Bahrain and Oman apply VAT, each with its own registration, invoice content and filing rules. Qatar and Kuwait had not introduced VAT at the time of writing, though that may change. Saudi Arabia also runs a national e-invoicing programme with its own technical requirements, and other GCC states have announced or are developing e-invoicing plans.</p><p>The ERP uses standard Odoo accounting. During implementation, taxes and invoice formats are configured locally for each country you invoice from, following your tax adviser's instructions — including the tax registration numbers, invoice wording and bilingual Arabic and English layouts clients commonly expect. We make no certification claim for any national e-invoicing programme; where a requirement applies to you, we review it with you and your adviser during scoping and agree what is included.</p><p>Companies with branches in several GCC countries often run separate legal entities. How entities, currencies — Saudi riyal, UAE dirham, Qatari riyal, Kuwaiti dinar and others — and inter-company charges are set up is decided during implementation.</p><h2>Retention, guarantees and payment cycles</h2><p>Payment cycles on Gulf NDT contracts can be long. Many clients pay only after the monthly timesheet is certified and a service entry or work completion certificate is raised on their side. Retention is commonly held on construction and EPC work, and contracts often require performance guarantees. For a mid-sized inspection company paying salaries and accommodation every month, the gap between work done and cash received is often the biggest business risk.</p><p>The ERP sets payment terms per client so invoice due dates reflect the contract. Payments are recorded against invoices using standard Odoo payments, and standard reminders help you follow up consistently. The outstanding invoices view on the financial dashboard shows exactly which contracts are holding cash.</p><p>Retention release tracking and progress billing are configured as part of the customization scope agreed with you. Out of the box, the invoice type separates interim from final invoices, and cost centres keep each contract visible on its own.</p><h2>Equipment rental and consumables on Gulf contracts</h2><p>Many Gulf contracts pay for equipment separately — sometimes as a monthly rental alongside manpower, sometimes per shift or per package. Phased array and TOFD sets, AUT systems for pipeline work, crawlers, eddy current and IRIS equipment for exchanger bundles are all high-value units, and they move constantly between sites, branches and sometimes countries.</p><p>In the Atlantis ERP, instruments are tracked by serial number in the Asset Management app, with issue and return workflows approved by supervisors and managers, condition recorded at issue and return, reservations with clash prevention and inbound and outbound movements. Rental rates can be recorded against equipment, and equipment can be marked as rented out. Invoice lines carry the equipment serial, so the equipment subtotal ties back to units actually issued to the contract.</p><p>Desert and coastal conditions are hard on equipment. The maintenance log records preventive and corrective work, repairs, cleaning, firmware updates and probe replacements, with condition before and after. Calibration records and the calibration certificate register show which units are valid, expiring or expired. When a client asks for proof that the UT set on your invoice was calibrated while it was used, it is on the same record.</p><p>Consumables — couplant, penetrant and developer, magnetic particles, film and chemicals, PPE — are tracked with reorder levels, low-stock flags and a movement ledger. During a shutdown, when film and penetrant go quickly, the consumables subtotal on the invoice comes from stock records rather than an estimate made after the event.</p><h2>From quotation to invoice</h2><p>Gulf contracts are often won on a detailed commercial offer, then executed over months or years. When the monthly invoice is prepared, the billing team needs the accepted rates, not a revised draft from an earlier negotiation round.</p><p>In the <a href=\"/erp/apps/quotations\">Quotations app</a>, NDT service products are flagged by method and category, and each quote carries the job type, site, project dates and applicable codes, with a custom branded PDF. The client can accept online, and the quote converts to a sales order. The project, crew assignments, timesheets, equipment issues and reports then build on that record, and the invoice pulls it together.</p><p>For owners and operations managers, that chain answers the questions that matter at month end: what did we quote, what did we deploy, what did the client certify, and what have we billed.</p><h2>Reports, digital twins and the financial dashboard</h2><p>Clients usually want the inspection report before they certify the work. The ERP's NDT Reports app runs reports through review, approval and sending, capturing work order, drawing, WPS and procedure references, so report and invoice come from the same job. For asset owners who want findings in context, our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places inspection results on a 3D model of the asset. It is a separate product that works alongside the ERP and is a strong differentiator in owner-side bids.</p><p>The financial dashboard shows revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, vendor bills and expenses, with a 12-month view. With cost centres by country or contract and industry sector on each invoice, you see whether manpower contracts, shutdowns or project work actually carry the margin.</p><h2>Implementation in the Gulf</h2><p>We deploy and configure the ERP for you. Typical scope includes rate schedules mapped to technician categories, methods and multipliers; VAT and invoice layouts configured locally per country; cost centres by contract and branch; equipment by serial with rental rates; consumables; payment terms; and training for billing, supervisors and technicians. The ERP is affordable, accessible and fully customizable, with pricing on request. See all <a href=\"/erp/apps\">ERP apps</a>.</p><h2>Offshore, pipeline and construction projects</h2><p>Beyond plant shutdowns, a large share of Gulf NDT work comes from projects: offshore platform and jacket fabrication in yards along the Arabian Gulf coast, offshore hook-up and maintenance campaigns, cross-country and in-plant pipelines, and new gas processing, petrochemical and power facilities built by EPC contractors. Each brings a different billing pattern.</p><p>Fabrication yard work is often billed per joint, per film or per package against the yard's weld tracking, with the inspection report as evidence. Offshore campaigns may be billed per technician-day with separate rates for offshore days, travel to and from the marine base and standby while waiting for a vessel or weather window. Pipeline projects typically run AUT or RT crews behind the welding spreads, billed per crew-day or per weld.</p><p>In the Atlantis ERP, day and shift work flows from approved timesheets, with work type — inspection, travel, standby or setup — and a rate multiplier on each entry. Unit-rate billing such as per joint or per film is set up as service products and rate rules during implementation, following your contract schedules. Cost centres split one EPC contract by area, package or subcontract, and the invoice header carries the project, PO or work order, site and sector.</p><p>EPC contractors in the region usually require subcontractor invoices to match their own progress measurement and are often paid late themselves. Having each invoice backed by approved timesheets, equipment issue records and approved reports puts you in the strongest position when payment is negotiated down the chain.</p><h2>Who uses the Invoicing app in a Gulf NDT company</h2><ul><li><strong>Accounts and billing staff</strong> prepare monthly manpower invoices and package invoices from approved records, apply the right VAT treatment for each country, record payments and follow up on overdue accounts.</li><li><strong>Site supervisors and camp or project coordinators</strong> approve daily timesheets, confirm overtime, rest-day and standby entries, and get the monthly timesheet signed by the client representative.</li><li><strong>Contract and commercial managers</strong> check invoices against the schedule of rates, call-off orders and client completion certificates, and track retention and outstanding amounts per contract.</li><li><strong>Branch managers</strong> in, for example, Dammam, Jubail, Abu Dhabi or Doha see their own cost centre figures on the financial dashboard.</li><li><strong>Owners and general managers</strong> watch margin, receivables and cash exposure across countries and contracts.</li><li><strong>Technicians</strong> log hours by work type from site; accurate entries reduce month-end disputes.</li></ul><p>Access rights follow the standard Odoo permission model and are set during implementation, so a branch accountant sees their entity's invoices, supervisors approve their own crews' hours, and the owner sees everything. For companies with many nationalities on the payroll, keeping technician records and timesheets in one controlled system is also a cleaner position when clients audit your manpower.</p><h2>Frequently asked questions</h2><h3>Can it bill monthly manpower rates with overtime?</h3><p>Yes. Approved timesheet hours with rate multipliers feed billing, and lines carry the technician, method and rate type.</p><h3>Is it certified for Saudi e-invoicing?</h3><p>No certification is claimed. Taxes and invoice formats are configured locally during implementation, and any e-invoicing requirement is reviewed with you and your adviser.</p><h3>Can invoices be in Arabic and English?</h3><p>Yes. Bilingual layouts are configured during implementation.</p><h3>Can mobilisation and accommodation be re-billed?</h3><p>Yes. Expenses can be re-billed to jobs, and the rule for mobilisation charges is set during implementation.</p><h3>Does it record both ASNT and ISO 9712 certificates?</h3><p>Yes, and timesheets warn when a technician's certificate is not valid.</p><h3>Can it track retention?</h3><p>Retention is configured as part of the agreed customization scope.</p><h2>Book a Gulf-focused demo</h2><p>Bring a real month of manpower billing or a shutdown package, and we will run it from approved timesheets to invoice. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20Middle%20East\">Book an Invoicing demo</a> or <a href=\"/contact?service=erp&amp;subject=Invoicing%20quote%20Middle%20East\">request a quote</a> for the Atlantis NDT ERP.</p>\n<h2>Invoicing by region</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing global overview</a></li><li><a href=\"/erp/apps/invoicing/usa\">Invoicing in United States</a></li><li><a href=\"/erp/apps/invoicing/canada\">Invoicing in Canada</a></li><li><a href=\"/erp/apps/invoicing/europe\">Invoicing in UK &amp; Europe</a></li><li><a href=\"/erp/apps/invoicing/india\">Invoicing in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(Middle%20East)\">Send an enquiry about Invoicing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/invoicing/india","publishedAt":"2026-09-27","title":"NDT Invoicing Software in India | Atlantis NDT","description":"Prepare RA bills and NDT invoices from approved timesheets, JMRs, equipment and consumables, with GST set up for your states. Book a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Invoicing Software for Inspection Companies in India</h1>\n<p>Invoices from timesheets and completed jobs, with payments and reminders. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work gets billed in India</h2><p>Billing in the Indian NDT business has its own vocabulary. Work for public sector undertakings such as IOCL, BPCL, HPCL, ONGC, GAIL and NTPC is usually won through tenders, then executed under a rate contract or work order with a schedule of rates. Progress is measured, joint measurement records are signed with the client's engineer-in-charge, and payment comes through running account bills followed by a final bill. Private refineries such as the Jamnagar complex, EPC contractors, fabrication shops, power plants and boiler manufacturers each have their own processes on top.</p><p>For many Indian inspection companies, that means billing lives in Excel: a sheet of measured quantities, a sheet of rates, a sheet of technician attendance and a GST invoice typed separately. Every RA bill is a fresh reconciliation. When a measurement is disputed or a rate is misread, the bill comes back and cash stays stuck for another cycle.</p><p>The Invoicing app in the Atlantis NDT ERP reduces that re-keying. It is part of our <a href=\"/erp\">NDT ERP built on Odoo</a>, pre-configured for inspection companies and deployed by our team, including from our Hyderabad office. Approved timesheets, equipment by serial number and consumables drawn from stock become invoice lines carrying the project, work order or PO, site, method and technician.</p><p>This page covers tender and rate-contract billing, RA bills and JMRs, per-film and per-joint radiography billing, IBR and PESO related work, GST, TDS and payment cycles, and the DPDP Act — and how the app handles each.</p><h2>Rate contracts, work orders and RA bills</h2><p>A typical PSU or large private job runs like this: the tender sets a schedule of rates with item numbers; the work order or PO authorizes the scope; site progress is recorded in measurement sheets or a JMR signed by the engineer-in-charge; and your RA bill claims the measured quantities at contract rates. The client's finance team checks the bill against the work order, the JMR and the cumulative quantities billed earlier.</p><p>In the Atlantis ERP, the Project app records the client PO or work order, contract, site, methods, codes and scope. The invoice header carries the NDT project, job or PO number, site, invoice type and industry sector. The invoice type field lets you distinguish RA bills from a final bill. Each line can carry a cost centre, method, equipment serial, technician, rate type and days or hours, with separate subtotals for labour, equipment and consumables.</p><p>Schedule-of-rates item numbers and cumulative quantity tracking across RA bills are set up during implementation, as part of the customization scope agreed with you, to match your tender formats. Signed JMRs and measurement sheets can be kept with the job record, so when a quantity is questioned the evidence is in one place.</p><p>Many PSUs also require bills and supporting documents through their own vendor portals, and much government procurement now runs through GeM. The ERP claims no built-in connection to any portal. It produces invoices that already carry the references those portals ask for.</p><h2>Radiography billed per film, per joint or per day</h2><p>Radiography in India is often billed per film or per joint rather than per day, especially on pipeline and piping fabrication work. Other contracts pay per crew-day, and shutdown work is frequently billed per shift. Ultrasonic, MPI and DPT may be billed per joint, per metre or per day depending on the tender.</p><p>Day and shift billing flows from timesheets. Each entry records a work type — inspection, travel, standby or setup — with method, site, client and equipment serial, a billable flag and a rate multiplier for night shifts, Sundays and holidays. Unit-rate billing such as per film, per joint or per metre is set up as service products and rate rules during implementation, following your schedule of rates.</p><p>Radiography also brings regulation. Under AERB, industrial radiography requires licensed sources, a Radiological Safety Officer and trained, monitored personnel. The employee NDT profile records radiation safety training and radiation badge number, and the Fleet app records whether a vehicle may carry radioactive sources along with its transport licence expiry. Film and chemicals are tracked as consumables in Asset Management and Inventory with a movement ledger, so film usage on the bill is backed by stock records rather than an estimate.</p><p>The Team Assignments app blocks double-booking of technicians and equipment serials and warns when assigned equipment is out of calibration, which matters when a source or UT set is moving between sites in different states in the same week.</p><h2>IBR, PESO and fabrication work</h2><p>A large share of Indian NDT work supports regulated equipment. Boilers and boiler components come under the Indian Boiler Regulations, with inspection authorities reviewing NDT records before approving work. Pressure vessels for storing compressed and liquefied gases involve PESO requirements. Fabrication shops building these items for power plants, refineries and process industries usually want NDT billed per job, per drawing or per joint, with the report as supporting evidence.</p><p>The ERP's NDT Reports app captures work order, drawing, WPS and procedure references and runs each report through review and approval, including third-party or authorized inspector names and signatures. Because reports and invoices come from the same job, you can send both together — which is often what a fabrication client's QA team needs before the bill moves to accounts.</p><p>For owners and EPCs who want findings in context rather than a folder of PDFs, our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places inspection results on a 3D model of the asset. It is a separate product that works alongside the ERP and can strengthen bids for owner-side inspection contracts.</p><h2>Certificates on the bill: ASNT and ISO 9712</h2><p>Indian clients see both ASNT SNT-TC-1A based certification and ISO 9712 certification on site, and many tenders specify minimum levels for each method. PSU and EPC clients increasingly check certificates at mobilisation and during audits, and a technician found with an expired certificate can put the bill for that work in dispute.</p><p>The Certificates app records each technician's scheme, level, method, certifying body and expiry, and automatically marks certificates expiring within ninety days or expired. The Timesheets app warns when a technician's certificate is not valid, so the supervisor sees it when approving hours — before they are billed. See the <a href=\"/erp/apps/certificates\">Certificates app</a> for more.</p><p>Atlantis's own training programmes are based on ASNT SNT-TC-1A. The app can record ISO 9712 certificates your technicians hold, but we do not provide ISO 9712 training.</p><h2>GST, place of supply and multiple registrations</h2><p>Every NDT invoice in India is a GST invoice. Intra-state supplies carry CGST and SGST; inter-state supplies carry IGST; the place of supply rules for services decide which applies, and they can depend on the client's registration and the site location. Companies with branches in several states usually hold a GSTIN in each, and invoices must carry the correct GSTIN, SAC code and tax split.</p><p>The ERP uses standard Odoo accounting. During implementation, taxes and invoice formats are configured for India following your chartered accountant's instructions — GST rates, fiscal positions, GSTIN on the invoice layout and SAC codes on service products. Multiple state registrations are handled through the company and branch structure agreed during setup.</p><p>Businesses above the notified turnover threshold must also follow GST e-invoicing rules. We make no certification claim for any e-invoicing or government reporting system; where a requirement applies to you, we review it with you and your CA during scoping and agree what is included.</p><h2>TDS, retention and payment cycles</h2><p>Indian clients commonly deduct TDS under the Income Tax Act from payments to contractors and professional service providers, so the amount received rarely equals the invoice total. PSUs and large EPCs also typically hold a security deposit or retention money from RA bills, and may require a performance bank guarantee. Payment cycles on PSU work can be long, with bills moving through several approval levels.</p><p>Payments are recorded against invoices using standard Odoo payments, and standard reminders help you follow up. How TDS deductions and retention are recorded in the payment reconciliation is configured with your CA during implementation, as part of the agreed scope, so your receivables reflect what is truly outstanding rather than a figure inflated by amounts you will never receive in cash.</p><p>If your company is a registered micro or small enterprise, the MSMED Act sets payment timelines for buyers and allows interest on delayed payments. Accurate invoice dates and receipt records become important evidence if you ever rely on those rights. Payment terms are set per client so due dates reflect your contract.</p><h2>DPDP Act and technician data</h2><p>Timesheets, certificates, vision tests and radiation badge records contain personal data about your technicians. The Digital Personal Data Protection Act, 2023 sets obligations for how organisations collect, use and protect personal data. Keeping these records in the ERP, with access controlled through the standard Odoo permission model, is a better position than scattering them across spreadsheets, WhatsApp photos and email attachments.</p><p>The custom invoice layout decides what the client sees — full technician names, employee references or only the technician level — so personal data on invoices is limited to what the contract needs.</p><h2>Equipment and consumables on Indian jobs</h2><p>Advanced methods are growing fast in India — phased array and TOFD replacing radiography on many piping and pressure vessel jobs, eddy current and IRIS on exchanger bundles in refinery shutdowns — and tenders increasingly price that equipment separately from manpower. Conventional equipment also moves constantly between sites, branches and clients.</p><p>In the Atlantis ERP, instruments are tracked by serial number in the Asset Management app, with issue and return approved by supervisors and managers, condition recorded both ways, reservations with clash prevention and inbound and outbound movements. Rental rates can be recorded against equipment, and invoice lines carry the equipment serial, so equipment charges tie back to the units actually issued to the job.</p><p>Calibration records and the calibration certificate register — with provider, certificate number, lab accreditation number and expiry — sit on the same equipment record. PSU and EPC clients frequently ask for calibration certificates with the bill or during audits, and having them against the serial number on the invoice saves a search through shared folders.</p><p>Consumables such as film, developer and fixer, penetrant kits, magnetic particles, couplant and PPE are tracked with reorder levels, low-stock flags and a movement ledger. On per-film or per-joint contracts, consumable usage is also a cost check: if film consumption per joint is rising, your margin on that rate contract is falling.</p><h2>From quotation to invoice</h2><p>Private clients and EPCs often buy on a commercial offer rather than a formal tender. In the <a href=\"/erp/apps/quotations\">Quotations app</a>, NDT service products are flagged by method and category, and each quote carries the job type, site, project dates and applicable codes, with a custom branded PDF and online acceptance that converts the quote to a sales order.</p><p>Whether the job started from a tender schedule of rates or a quotation, the project, crew assignments, timesheets, equipment issues and reports build on that record. When the billing team prepares the invoice or RA bill, the accepted rates and scope are already in the system — not in a revised Excel sheet someone emailed from site.</p><h2>Who uses the Invoicing app</h2><ul><li><strong>Billing and accounts staff</strong> prepare RA bills and invoices from approved records, apply GST correctly, record payments with TDS and retention, and follow up on overdue bills.</li><li><strong>Site in-charges and supervisors</strong> approve timesheets, confirm standby and night shifts, and collect signed JMRs.</li><li><strong>Project and contract managers</strong> check bills against the work order, schedule of rates and cumulative quantities.</li><li><strong>Owners and directors</strong> watch margin, receivables and branch performance on the financial dashboard.</li><li><strong>Technicians</strong> log hours by work type; accurate entries from site mean fewer corrections at billing time.</li></ul><p>Access follows the standard Odoo permission model, set during implementation, which also supports limiting who can see technicians' personal data.</p><h2>The financial dashboard and branch cost centres</h2><p>The Invoicing app includes a financial dashboard with revenue, cost of sales, gross margin, operating expenses, EBITDA, outstanding invoices, vendor bills and expenses, and a 12-month view. Cost centres by branch — for example Hyderabad, Mumbai, Vadodara or Chennai — or by service line, together with the industry sector on each invoice, show whether PSU rate contracts, private refinery shutdowns, fabrication shop work or power plant outages actually carry your margin. The outstanding invoices view shows exactly which RA bills are stuck.</p><h2>Implementation in India</h2><p>We deploy and configure the ERP for you. Typical scope includes schedule-of-rates items mapped to service products and rate rules; GST configured with your CA; GSTIN and branch structure; custom invoice layout; RA bill and final bill types; equipment by serial with rental rates; consumables such as film, chemicals and couplant; payment terms; and training for billing staff, site supervisors and technicians. The ERP is affordable, accessible and fully customizable, with pricing on request. See all the <a href=\"/erp/apps\">ERP apps</a>.</p><h2>Refinery and power plant shutdowns in India</h2><p>Annual turnarounds at refineries in Gujarat, Maharashtra, Andhra Pradesh, Tamil Nadu and Assam, and planned outages at thermal power stations, are where many Indian NDT companies earn a large part of their year. A shutdown can bring dozens of technicians onto day and night shifts for a few weeks, working on columns, exchangers, heaters, piping and boiler tubes, often alongside several other contractors under the client's permit system.</p><p>Shutdown billing usually goes wrong after the event. Attendance registers, shift logs and measurement sheets from site reach the office late; night-shift and Sunday work is not separated; standby while waiting for a permit or scaffolding is disputed; and the equipment charge for the IRIS or eddy current kit that spent the whole shutdown on exchanger bundles is understated. The bill then goes out weeks after demobilisation, when the client's engineers have moved on.</p><p>In the Atlantis ERP, timesheets are approved as the shutdown runs, with work type, method, equipment serial and rate multiplier captured when the hours are worked. Cost centres on invoice lines let one shutdown be split by unit or package, and the separate labour, equipment and consumables subtotals match the way most shutdown budgets and work orders are structured. Before mobilisation, Team Assignments blocks double-booking of technicians and equipment serials and warns about out-of-calibration equipment, so the crew and kit on the bill are the crew and kit that were really on site.</p><p>For boiler tube inspection during power plant outages, where thickness surveys and other methods may be billed per tube, per panel or per day, unit rates are set up as service products during implementation.</p><h2>Month-end close for a multi-branch NDT company</h2><p>Many Indian NDT companies run branches or site offices in several states, each with its own GSTIN, its own clients and its own crews. Month-end often means each branch emails a spreadsheet of bills raised, payments received and expenses to head office, where someone consolidates everything by hand before the owner sees a margin figure.</p><p>With the Atlantis ERP, each branch raises invoices in the same system under its own registration and cost centre. Field expenses, travel, lodging and daily allowances are recorded in the standard Expenses app and can be re-billed to jobs where the contract allows. Vendor bills for calibration labs, film suppliers and equipment dealers are recorded through Purchase, so the cost side of the dashboard is current.</p><p>The financial dashboard then shows revenue, cost of sales, gross margin, operating expenses, EBITDA and outstanding invoices, bills and expenses across all branches, with a 12-month view that makes seasonal patterns — the shutdown months, the monsoon slowdown on outdoor work — visible. Owners can see which branch is profitable and which is only busy, and which clients have RA bills stuck in approval.</p><p>How branches, registrations and cost centres are structured is agreed with you and your CA during implementation, so the setup reflects how your company is actually organised rather than a generic template.</p><h2>Frequently asked questions</h2><h3>Can the ERP prepare RA bills and a final bill?</h3><p>Yes. The invoice type distinguishes RA bills from the final bill. Cumulative quantity tracking in your tender format is configured as part of the agreed scope.</p><h3>Can radiography be billed per film or per joint?</h3><p>Yes. Unit rates are set up as service products and rate rules during implementation; day and shift work flows from timesheets.</p><h3>Is it certified for GST e-invoicing?</h3><p>No certification is claimed. GST and invoice formats are configured for India during implementation, and any e-invoicing requirement is reviewed with you and your CA.</p><h3>Can it handle multiple GSTINs?</h3><p>Yes, through the company and branch structure agreed during setup.</p><h3>How are TDS and retention handled?</h3><p>They are recorded in payment reconciliation as configured with your CA during implementation.</p><h3>Does it record ASNT and ISO 9712 certificates?</h3><p>Yes, and timesheets warn when a technician's certificate is not valid.</p><h2>Book a demo for your Indian operation</h2><p>Bring a real RA bill with its JMR and attendance, and we will show it built from ERP records. <a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20India\">Book an Invoicing demo</a> or <a href=\"/contact?service=erp&amp;subject=Invoicing%20quote%20India\">request a quote</a> for the Atlantis NDT ERP.</p>\n<h2>Invoicing by region</h2><ul><li><a href=\"/erp/apps/invoicing\">Invoicing global overview</a></li><li><a href=\"/erp/apps/invoicing/usa\">Invoicing in United States</a></li><li><a href=\"/erp/apps/invoicing/canada\">Invoicing in Canada</a></li><li><a href=\"/erp/apps/invoicing/europe\">Invoicing in UK &amp; Europe</a></li><li><a href=\"/erp/apps/invoicing/middle-east\">Invoicing in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/purchase\">Purchase</a>: Purchase orders for consumables, film, couplant and equipment.</li><li><a href=\"/erp/apps/inventory\">Inventory</a>: Stock of consumables, sources and equipment across sites.</li><li><a href=\"/erp/apps/expenses\">Expenses</a>: Field expenses and per diems, approved and rebilled to jobs.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Invoicing%20demo%20(India)\">Send an enquiry about Invoicing</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ndt-reports","publishedAt":"2026-09-27","title":"NDT Report Software for Inspection Companies | Atlantis NDT","description":"NDT report software for UT, RT, MT, PT, PAUT, TOFD and 11 more methods, with offline field capture and review sign-off. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Reports: NDT Report Software Built Into Atlantis NDT ERP</h1>\n<p>Method-specific NDT inspection reports, captured in the field and issued from the ERP. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<h2>Why NDT reports still eat your week</h2><p>Most NDT companies don't have a reporting problem on the job. The technician finds the indication, sizes it, and knows whether it passes. The problem starts after that. Readings go into a notebook or onto a wet clipboard. Someone in the office re-types them into a Word template that three different people have edited over the years. The Level II signs, the Level III reviews a printout, and the client gets a PDF three days after the scan.</p><p>Every hand-off is a place where a thickness reading gets transposed, a probe serial gets copied from last week's job, or the wrong acceptance standard is left in the header. Clients notice. Third-party inspectors notice. And when an auditor asks which calibration block was used on a weld inspected eight months ago, the answer is in a filing cabinet somewhere.</p><p>The NDT Reports app in Atlantis NDT ERP is built to close those gaps. It captures method-specific data at the source, routes each report through inspector, reviewer and approver sign-off, and produces the report in your company's own template. It sits inside the same ERP that runs your jobs, technicians, equipment and invoices, so the report stays connected to the work order that created it instead of floating in a shared drive.</p><p>It is affordable, accessible and fully customizable. Pricing is quote on request, based on the scope you need.</p><h2>17 report types, each with its own fields and numbering</h2><p>A UT report and an RT report are not the same document with a different title. They record different things, and a generic inspection form forces technicians to squeeze radiography details into free-text boxes. NDT Reports ships with 17 report types, each with its own data structure and its own numbering sequence.</p><table><thead><tr><th>Method</th><th>What the report captures</th></tr></thead><tbody><tr><td>Ultrasonic (UT)</td><td>Probe calibration table, weld and job lines with defect type and orientation, overall result</td></tr><tr><td>Radiography (RT) and Computed Radiography (CR)</td><td>Source, technique, IQI type and placement, weld lines and result</td></tr><tr><td>Magnetic particle (MT)</td><td>Technique and particle type</td></tr><tr><td>Penetrant (PT)</td><td>Method and developer</td></tr><tr><td>Phased array (PAUT)</td><td>Focal laws</td></tr><tr><td>Magnetic flux leakage (MFL)</td><td>Scan mode and item lines</td></tr><tr><td>UT thickness (UTT)</td><td>Readings recorded by direction</td></tr><tr><td>VT, ECT, IRIS, TOFD, PWHT, PMI, Hardness, Ferrite, Holiday/coating</td><td>Their own report type and numbering, with job lines and an overall result</td></tr></tbody></table><p>Every report ends with an overall result: acceptable, not acceptable, or acceptable with remarks. That three-way result matters more than it looks. Acceptable with remarks lets a Level II record a condition the client should know about without failing the item, and it shows clearly on the report instead of being buried in a comment.</p><p>Separate numbering per method means your UT and RT sequences never collide, and a client who asks for all the PT reports on one unit gets a clean sequence rather than a mixed list.</p><h2>How a report moves from the field to the client</h2><p>Every report follows the same five-stage workflow. The stages are simple on purpose. Anyone in the office can see where a report sits and who is holding it up.</p><ol><li><strong>Draft</strong>: the job exists and the report is opened against it, usually from the work order, with the job references already filled in.</li><li><strong>In progress</strong>: the technician is capturing readings, photos and weld lines, in the field app or on a laptop at the site office.</li><li><strong>Review</strong>: the inspector submits, and the reviewer, usually a Level II or Level III, checks technique, coverage, sizing and the acceptance standard.</li><li><strong>Approved</strong>: the approver signs. On client and code work, this is where the third-party or authorized inspector's name and signature are recorded as well.</li><li><strong>Sent</strong>: the report goes out in your template, and the record shows it has left the building.</li></ol><p>Signatures are captured for the inspector, reviewer and approver, so the PDF shows who did what. There is also a field for a third-party inspector or authorized inspector, with name and signature, for jobs where the client's inspector witnesses or verifies the work.</p><p>Because the stages are tracked, the questions that normally take a phone call get answered on screen: which reports from last week's shutdown are still in review, which are approved but not sent, and which technician has three drafts open.</p><h2>Capture in the field, even without signal</h2><p>Tank farms, pipe racks, ship holds and remote pipeline spreads have one thing in common: bad signal. A reporting tool that needs a live connection gets abandoned on day one, and the notebook comes back out.</p><p>The NDT Reports field app is an installable web app. You add it to a tablet or phone like any other app, and it works offline. Drafts and photos are stored on the device and sync when the connection returns. On the device the technician gets:</p><ul><li>A method picker, so the right report type and fields open for the job</li><li>Photo capture straight into the report</li><li>An on-screen signature</li><li>A PDF preview before submitting, so the technician sees what the reviewer and client will see</li></ul><p>Behind the field app is a REST API that serves the device the jobs assigned to that technician and the equipment issued to them, accepts report submissions, and handles sync. In practice, the technician opens the app in the morning and sees their jobs and their issued instrument and probes, not a blank form.</p><p>It also means the equipment on the report comes from what was actually issued to that technician, not from memory. That one detail removes a common audit finding, where the instrument named on the report was sitting in the calibration lab on the day of the inspection.</p><h2>References, templates and the report your client receives</h2><p>A report that cannot be traced back to the contract, drawing and procedure is a weak report. NDT Reports captures the references clients and auditors ask for:</p><ul><li>Work order and client request number</li><li>Contract and drawing numbers</li><li>WPS number for weld inspections</li><li>Procedure reference and the code or standard used for acceptance</li></ul><p>The output uses your templates, not ours. Company templates are versioned and can be Excel, Word, PDF or HTML, with your logo, header and footer. If your clients are used to an Excel-format report, the app fills Excel templates automatically by mapping report fields to cells, so the layout they recognise stays the same while the re-typing stops. Each method also has its own PDF output.</p><p>Versioning matters when a client changes its required format halfway through a contract. You add a new template version instead of overwriting the old one, so there is a record of which format was in use and when.</p><p>When a client queries a result a year later, the report tells them which procedure and standard were applied, without anyone opening an archive box.</p><h2>Marine mode for class surveys and ship repair</h2><p>Marine NDT has its own paperwork. A report for a hull or machinery survey usually needs a vessel cover page, the classification-society certificate, the inspector's qualification and the calibration certificate for the instrument, all in one pack.</p><p>NDT Reports has a marine mode for this. It adds a vessel cover page with the vessel photo, inspection location and dates. When the PDF is produced, it merges in:</p><ul><li>The classification-society certificate, chosen from a library that covers DNV, ABS, Lloyd's Register, Bureau Veritas, RINA, IRS and ClassNK</li><li>The inspector's Level II certificate</li><li>The calibration certificate of the instrument used</li></ul><p>Inspection photos are laid out in a two-up grid, so a thickness survey with dozens of photos stays readable instead of running to one photo per page.</p><p>For a ship repair yard or a marine inspection company, this removes the most tedious part of the job: hunting for the right certificate PDFs, printing them, and scanning the whole pack back together. The surveyor gets one document with everything attached, in a consistent order, every time.</p><p>Hull gauging uses the same UT thickness report type, with readings by direction, that your team uses onshore, so nobody has to learn a separate tool for marine work. If you work mostly onshore, marine mode simply stays out of the way.</p><h2>Featured companion: Digital Twin Reporting Software</h2><p>The NDT Reports app produces the formal, signed report. Some asset owners want more than that: they want to see where on the asset each finding sits, and how findings in one area relate to the rest of the plant.</p><p>That is what <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> is for. It is a separate Atlantis NDT product that places inspection results on a 3D model of the asset. It works alongside the ERP's NDT Reports app: the ERP handles the job, the technician, the equipment, the workflow and the signed report, and the digital twin reporting product gives the client a visual, spatial view of the results.</p><p>Why an NDT company would offer both:</p><ul><li>A plant manager can find the weld or nozzle on the model rather than reading grid references off a drawing</li><li>Repeat inspections on the same asset are easier to compare when results sit in the same place on the model</li><li>It sets your service apart in a tender where most competitors deliver PDFs only</li><li>Your team keeps working in the ERP they already use for reporting</li></ul><p>To be clear about the split: the ERP app does not build 3D models or digital twins. It is the reporting and workflow engine. The 3D view is the companion product, scoped separately. You can start with NDT Reports and add digital twin reporting later, or ask for both in one quote.</p><h2>Who uses it, day to day</h2><ul><li><strong>Field technicians (Level I and II)</strong>: open assigned jobs on a tablet, pick the method, record readings, weld lines and defects, take photos, sign and submit, online or offline.</li><li><strong>Level III and reviewers</strong>: work through the review queue, check technique and acceptance references, and approve or send back, with a clear record of who signed.</li><li><strong>Operations and QA/QC managers</strong>: see which reports are stuck in review, which are approved but unsent, and which jobs still have no report at all.</li><li><strong>Office and admin staff</strong>: stop re-typing. Maintain templates, send approved reports, and answer client queries from the record.</li><li><strong>Third-party and authorized inspectors</strong>: have their name and signature captured on the report when they witness or verify the work.</li><li><strong>Owners and directors</strong>: get a reporting process that holds up in audits and client prequalification, without buying a separate reporting system that doesn't talk to the rest of the business.</li></ul><p>Everyone works from the same record. The technician's readings, the reviewer's comments and the approver's signature all live on one report, not in three email threads.</p><p>Who can create, review and approve is set by role during implementation, in line with your written practice. If you are still defining who is allowed to sign what, our <a href=\"/consulting\">NDT consulting</a> team can help write that into your procedures before the software is configured.</p><h2>How NDT Reports connects to the rest of the ERP</h2><p>NDT Reports is one app in <a href=\"/erp\">Atlantis NDT ERP</a>, and its value grows when it is connected to the others. You can browse them all on the <a href=\"/erp/apps\">ERP apps</a> page.</p><ul><li><strong>Projects</strong>: the NDT job, with site, client PO, methods, codes, scope and acceptance criteria, is where the work order on the report comes from. Tasks carry method, technician, component, result, and procedure and WPS references.</li><li><strong>Certificates</strong>: technician certifications, levels and expiry dates are recorded on the employee's NDT profile, and timesheets warn when a technician's certificate is not valid.</li><li><strong>Asset Management</strong>: instruments and probes are tracked by serial number with calibration records, which is how the field app knows what equipment is issued to whom.</li><li><strong>Procedures</strong>: the register holds approved, revision-controlled procedures, the same ones referenced on the report.</li><li><strong>Team Assignments</strong>: jobs are dispatched to technicians, and double-booking of people and equipment serials is blocked.</li><li><strong>Invoicing</strong>: timesheet hours and job references feed billing, so an approved report and an invoice point to the same job.</li></ul><p>None of this is mandatory on day one. Some companies start with NDT Reports and Certificates and add the rest over time. Others move the whole business at once. Both work. Because the ERP is built on Odoo, standard modules for accounting, HR and purchasing sit in the same system rather than in separate subscriptions.</p><h2>What implementation looks like</h2><p>Atlantis NDT deploys and sets up the ERP for you. A typical NDT Reports rollout runs like this:</p><ol><li><strong>Discovery</strong>: we look at your current reports, method by method, and at the formats your main clients demand.</li><li><strong>Template build</strong>: your Word, Excel or PDF layouts are loaded as versioned templates, with Excel fields mapped to cells where you use Excel.</li><li><strong>Numbering and roles</strong>: report numbering per method is set to your convention, and inspector, reviewer and approver roles are assigned.</li><li><strong>Field app rollout</strong>: technicians install the field app on their tablets or phones, and we walk through an offline job with them.</li><li><strong>Connected apps</strong>: jobs, technicians and equipment are linked so the field app shows the right assignments and issued equipment.</li><li><strong>Go-live and adjustment</strong>: the first weeks of real reports usually surface small template changes. Those are part of the setup.</li></ol><p>Anything your company needs that is not in the standard app, such as an extra field your biggest client insists on or a layout for a client-specific form, is agreed as part of the customization scope. That is the point of a fully customizable system: it fits the way you work instead of forcing a new one.</p><p>Pricing depends on scope, number of users and how many apps you take, and it is quote on request. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20quote\">Request an NDT Reports quote</a> and tell us which methods you report most.</p><h2>Frequently asked questions</h2><h3>Which NDT methods does the report software cover?</h3><p>Seventeen report types: UT, RT, MT, PT, VT, ECT, IRIS, PAUT, MFL, TOFD, PWHT, PMI, hardness, UT thickness, ferrite, holiday/coating and computed radiography. Each has its own numbering sequence and method-specific fields, such as the probe calibration table for UT, IQI type and placement for RT, and focal laws for PAUT.</p><h3>Can technicians write reports without internet?</h3><p>Yes. The field app is an installable web app that works offline. Drafts and photos are stored on the device and sync when a connection is available. Technicians can pick the method, capture photos, sign on screen and preview the PDF before submitting.</p><h3>Can we keep our existing report formats?</h3><p>Yes. Company templates can be Excel, Word, PDF or HTML, with your logo, header and footer, and they are versioned. Excel templates are filled automatically by mapping report fields to cells, so clients keep receiving the layout they know.</p><h3>Does the NDT Reports app build digital twins?</h3><p>No. The ERP app handles report capture, workflow, sign-off and output. Digital Twin Reporting Software is a separate Atlantis NDT product that places inspection results on a 3D model of the asset and works alongside the ERP app. You can take either or both.</p><h3>Who signs the report?</h3><p>The inspector, reviewer and approver each sign within the workflow, and there is a field for a third-party or authorized inspector's name and signature. Which of your staff can hold each role is set during implementation to match your written practice.</p><h3>Can it handle class society reports for ships?</h3><p>Yes. Marine mode adds a vessel cover page and merges the classification-society certificate, the inspector's Level II certificate and the calibration certificate into the PDF, with inspection photos in a two-up grid.</p><h3>How much does it cost?</h3><p>There is no list price. Atlantis NDT ERP is affordable and quoted to your scope: the apps you take, the number of users and the customization you need.</p><h2>See it with your own reports</h2><p>The fastest way to judge reporting software is to see one of your own reports come out of it. Send us a sample UT or RT report you issue today, redacted if you like, and we will show you how it looks when built in NDT Reports, from the field app to the signed PDF.</p><p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo\">Book an NDT Reports demo</a>, and ask about pairing it with Digital Twin Reporting Software if your clients want to see results on a 3D model of their assets.</p>\n<h2>NDT Reports by region</h2><ul><li><a href=\"/erp/apps/ndt-reports/usa\">NDT Reports in United States</a></li><li><a href=\"/erp/apps/ndt-reports/canada\">NDT Reports in Canada</a></li><li><a href=\"/erp/apps/ndt-reports/europe\">NDT Reports in UK &amp; Europe</a></li><li><a href=\"/erp/apps/ndt-reports/middle-east\">NDT Reports in Middle East</a></li><li><a href=\"/erp/apps/ndt-reports/india\">NDT Reports in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo\">Send an enquiry about NDT Reports</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ndt-reports/usa","publishedAt":"2026-09-27","title":"NDT Report Software in the USA | Atlantis NDT","description":"NDT report software for US inspection companies: ASME Section V and API client work, SNT-TC-1A sign-offs, offline field capture. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Reports: NDT Report Software for US Inspection Companies</h1>\n<p>Method-specific NDT inspection reports, captured in the field and issued from the ERP. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<h2>What US clients expect from an NDT report</h2><p>In the US, an NDT report is not just a record of what you found. It is evidence that a qualified person, working to a written practice and an approved procedure, inspected a specific weld or component to a specific code, with a calibrated instrument, and that someone at the right level signed off the result. Refinery QA departments, EPC quality managers and insurers' inspectors read reports with that checklist in mind.</p><p>Most US inspection companies can produce that evidence. The trouble is that it lives in pieces: readings in a technician's notebook, cert cards in a binder, the calibration certificate in the equipment room, the procedure number in someone's head. Assembling it into a clean report after a twelve-hour shift at a Gulf Coast plant is where the errors creep in.</p><p>The NDT Reports app in <a href=\"/erp\">Atlantis NDT ERP</a> puts those pieces into one record. It covers 17 report types, including UT, RT, MT, PT, VT, PAUT, TOFD, MFL, PMI, hardness, UT thickness and computed radiography, each with its own fields and numbering. Reports move through draft, in progress, review, approved and sent, with inspector, reviewer and approver signatures, and come out in your company's own template.</p><p>This page looks at how that works for US inspection companies specifically: the codes, the client work and the regulators that shape what goes on the report.</p><h2>SNT-TC-1A, CP-189 and who is allowed to sign</h2><p>US NDT certification is mostly employer-based. Under ASNT SNT-TC-1A, your company writes a written practice, and your Level III and management certify technicians against it. Under ANSI/ASNT CP-189, which many owners and defense-related clients call for, the rules are tighter but the principle is the same: the employer certifies, and the employer answers for it.</p><p>That makes the signature block on a report more than a formality. The person signing as interpreter must hold the right level in the right method on the day of the inspection. If a Level II's certification lapsed last month and nobody noticed, every report they signed since is open to challenge.</p><p>NDT Reports records the inspector, reviewer and approver on every report, with signatures. The ERP's Certificates app records each technician's scheme, including SNT-TC-1A and CP-189, with level, method, issue and expiry dates, and flags certs as expiring soon or expired. Timesheets warn when a technician's certificate is not valid. The roles allowed to review and approve are set during implementation to mirror your written practice.</p><p>Atlantis NDT also runs <a href=\"/training\">SNT-TC-1A based training</a> for Level I, II and III, if you are building up the people to fill those signature blocks.</p><h2>Reports built around ASME Section V and construction codes</h2><p>For new construction and repairs, most US work points back to ASME Section V for the examination method and to a construction code for acceptance. The report has to show both. NDT Reports carries procedure and standard references on every report, alongside the work order, contract, drawing and WPS numbers, so the reviewer can check the chain from procedure to acceptance.</p><table><thead><tr><th>Typical US code context</th><th>What the report records in NDT Reports</th></tr></thead><tbody><tr><td>ASME Section V Article 2 radiography, with acceptance to Section VIII or B31.3</td><td>RT source, technique, IQI type and placement; weld lines with defect type and orientation; overall result</td></tr><tr><td>ASME Section V Article 4 ultrasonic examination of welds</td><td>UT probe calibration table; weld lines with defect type and orientation</td></tr><tr><td>ASME Section V Articles 6 and 7, penetrant and magnetic particle</td><td>PT method and developer; MT technique and particle type</td></tr><tr><td>AWS D1.1 structural steel fabrication</td><td>UT, MT and VT reports with WPS and drawing references</td></tr><tr><td>API 1104 pipeline girth welds</td><td>RT, UT or PAUT reports with weld lines, focal laws for PAUT, and the acceptance standard referenced</td></tr></tbody></table><p>The app does not decide acceptance for you. The technician and reviewer apply the code; the report records what they applied and what they found, and the result goes on as acceptable, not acceptable, or acceptable with remarks.</p><h2>API 510, 570 and 653 client work</h2><p>A large share of US inspection revenue comes from in-service work at refineries, chemical plants and terminals, where the owner runs an inspection program under API 510 for pressure vessels, API 570 for piping and API 653 for aboveground storage tanks. The NDT company supplies the data. The owner's authorized inspector and engineers make the fitness and interval decisions.</p><p>That split shapes what the report must do. It has to present clean, traceable readings in a format the owner's inspector can use without re-typing, and it often needs that inspector's name and signature on it. NDT Reports has a field for a third-party or authorized inspector, with name and signature, for exactly this.</p><p>Report types that do most of the work here:</p><ul><li><strong>UT thickness (UTT)</strong>, with readings recorded by direction, for vessel shells, heads and piping circuits</li><li><strong>MFL</strong>, with scan mode and item lines, for tank floor scanning during API 653 out-of-service inspections</li><li><strong>PMI</strong> and <strong>hardness</strong> for alloy verification and post-weld checks on repairs</li><li><strong>PWHT</strong> for heat treatment on repair welds</li><li><strong>IRIS</strong> and <strong>ECT</strong> for heat exchanger tube inspection during turnarounds</li></ul><p>Owners often insist on their own Excel layout. The app fills Excel templates automatically by mapping report fields to cells, so the owner's spreadsheet format stays intact and your office stops re-typing readings into it. Engineering assessment remains with the owner's inspector; the app records and presents the NDT data.</p><h2>Radiography: NRC, Agreement States and the RT report</h2><p>Industrial radiography in the US is licensed by the Nuclear Regulatory Commission or, in Agreement States such as Texas and Louisiana, by the state radiation control program. 10 CFR Part 34 and its state equivalents govern radiographer qualification, surveys and source control. Those obligations sit with your radiation safety officer and your license, not with reporting software.</p><p>What reporting software can do is make the technical record complete. The RT report in NDT Reports records the source, the technique, and the IQI type and placement, alongside weld lines with defect type and orientation and the overall result. Computed radiography has its own report type and numbering, so CR work is not forced onto a film template.</p><p>Around the report, the ERP holds related records you already have to keep somewhere:</p><ul><li>Each technician's NDT profile records radiation safety training, radiation badge number and medical fitness expiry</li><li>The Fleet app records whether a vehicle can carry radioactive sources, with its transport license number and expiry</li><li>Project records carry safety induction and work permit fields for plant sites</li></ul><p>Source logs, dosimetry reports and utilization records stay in whatever system your license requires. The goal here is that the RT report itself is complete and signed before it leaves the building, with the radiographer and reviewer clearly identified.</p><h2>Gulf Coast turnarounds: Houston, Baton Rouge, Lake Charles, Corpus Christi</h2><p>If you work the Houston Ship Channel, the Baton Rouge and Lake Charles corridors or the Corpus Christi refineries, you know turnaround reporting. Crews run day and night, several methods run in parallel, and the owner wants reports for yesterday's work at the morning meeting. The usual approach is a pile of paper forms and an office team re-typing through the night.</p><p>NDT Reports changes the rhythm:</p><ul><li>Technicians capture readings, weld lines and photos on a tablet in the offline field app inside the unit, where signal is often poor, and sync from the trailer</li><li>Each report opens against the job, with the work order and references already on it</li><li>Separate numbering per method keeps hundreds of UT, MT, PT and RT reports in clean sequences</li><li>Reviewers see a queue of reports in review, rather than a stack on a desk</li><li>Approved reports go out in the owner's template, and the record shows which are approved but not yet sent</li></ul><p>Turnarounds also stress scheduling. The Team Assignments app blocks double-booking of technicians and equipment serial numbers, and warns when assigned equipment is out of calibration. The field app's REST API shows each technician the jobs and equipment issued to them, so the probe on the report is the probe actually signed out.</p><p>OSHA rules, owner inductions and permits still govern the work itself. The project record carries the safety induction and work permit fields so they are on file with the job.</p><h2>Pipelines, PHMSA and remote spreads</h2><p>Gas and liquid pipeline operators regulated by PHMSA under 49 CFR Parts 192 and 195 need weld inspection records they can produce years later. For construction spreads, that usually means RT or ultrasonic reports on every girth weld, tied to the weld number, the WPS and the acceptance standard, typically API 1104.</p><p>Spreads run through places with no signal for days. The offline field app is built for that: drafts and photos stay on the device and sync when the crew reaches coverage. The method picker opens the right report type, the technician records each weld as a line with defect type and orientation, signs on screen and previews the PDF before submitting.</p><p>For in-service pipeline and station work, PAUT reports record focal laws, TOFD has its own report type, and UT thickness reports record readings by direction. Numbering per method keeps a long spread's weld records in order, and the work order and drawing references on each report make it straightforward to pull every report for a given section when the operator asks.</p><p>Operator-specific report layouts are handled as versioned company templates. If an operator asks for an extra field on the report, that is agreed as part of your customization scope.</p><h2>Aerospace, NAS 410 and marine work</h2><p>Aerospace NDT shops certify personnel to NAS 410 and work to customer and OEM specifications that are strict about who inspected what, with which procedure. The ERP's Certificates app records NAS 410 certifications under its 'other' scheme option, with level, method, dates and attachments. NDT Reports carries the procedure and standard references and captures inspector, reviewer and approver signatures on each report.</p><p>Eddy current, penetrant, magnetic particle and ultrasonic reports are the day-to-day types for this work. Customer-specific layouts, including prime contractor forms, are loaded as versioned company templates during implementation. Aerospace customers often have their own requirements for electronic records, so we talk through what your customers ask for before you commit.</p><p>On the marine side, Gulf shipyards and repair yards from Pascagoula to Galveston deal with class surveyors every week. Marine mode adds a vessel cover page with photo, location and dates, and merges into the PDF the classification-society certificate from a library covering ABS, DNV, Lloyd's Register, Bureau Veritas, RINA, IRS and ClassNK, plus the inspector's Level II cert and the instrument's calibration certificate. Photos sit in a two-up grid, so a hull gauging pack stays readable.</p><h2>Featured: Digital Twin Reporting Software for US asset owners</h2><p>Large US owners are asking more of their inspection contractors than a PDF. Many want to see findings located on the asset, compare inspections over time and share results with engineering teams who never visit the unit.</p><p><a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> is Atlantis NDT's companion product for that. It places inspection results on a 3D model of the asset. It is a separate product from the ERP: NDT Reports handles capture, workflow, sign-off and the formal signed report, while Digital Twin Reporting Software gives the owner the spatial, visual view.</p><p>For a Gulf Coast contractor bidding turnaround or in-service work, that pairing is a practical differentiator:</p><ul><li>The owner's inspector can find a flagged nozzle or weld on the model, not on a marked-up isometric</li><li>Repeat inspections of the same vessel or tank are easier to compare in place</li><li>Your formal reports still come out of the ERP in the owner's template, signed by your certified staff</li><li>You can offer it on the jobs where the owner values it, and keep standard PDFs elsewhere</li></ul><p>The ERP app itself does not build 3D models. If your clients want the 3D view, ask for both in one quote.</p><h2>Implementation for US inspection companies</h2><p>Atlantis NDT deploys and configures the ERP for you, and has a presence in Houston, so US working hours are covered. A typical NDT Reports rollout:</p><ol><li>Collect your current report forms by method, plus the formats your biggest owners and EPCs demand</li><li>Load them as versioned Excel, Word, PDF or HTML templates, mapping Excel fields to cells where owners want spreadsheets</li><li>Set report numbering per method and assign inspector, reviewer and approver roles to match your written practice</li><li>Connect jobs, technicians and equipment so the field app shows each technician their assigned work and issued instruments</li><li>Roll out the field app on tablets and run a real job offline before go-live</li></ol><p>Most US customers start with NDT Reports together with Certificates, because the report signature and the technician's certification status are the two things owners audit most. Asset Management, Team Assignments and Invoicing can follow once reports are flowing. See the full list of <a href=\"/erp/apps\">ERP apps</a> for how they connect.</p><p>Anything specific to your clients, such as an extra field an owner insists on, is agreed in the customization scope. The system is affordable, accessible and fully customizable, and pricing is quote on request. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20USA%20quote\">Request a quote for NDT Reports</a>.</p><h2>Frequently asked questions</h2><h3>Does the software support SNT-TC-1A and CP-189 sign-off?</h3><p>Yes, in the way that matters for reports. Each report records the inspector, reviewer and approver with signatures, and those roles are configured to follow your written practice. The Certificates app records SNT-TC-1A and CP-189 certifications with level, method and expiry, and timesheets warn when a technician's cert is not valid.</p><h3>Can we produce reports in an owner's Excel format?</h3><p>Yes. Excel templates are filled automatically by mapping report fields to cells. Word, PDF and HTML templates with your logo, header and footer are also supported, and all templates are versioned.</p><h3>Can an API authorized inspector sign the report?</h3><p>Yes. There is a third-party inspector or authorized inspector field with name and signature, in addition to your own inspector, reviewer and approver.</p><h3>Does it handle radiography licensing records?</h3><p>No. NRC or Agreement State licensing, dosimetry and source logs stay under your radiation safety program. The RT report records source, technique, and IQI type and placement, and employee profiles record radiation safety training and badge number.</p><h3>Will it work inside a refinery unit with no signal?</h3><p>Yes. The field app is an installable web app that works offline, stores drafts and photos on the device and syncs later.</p><h3>Is Digital Twin Reporting Software included?</h3><p>It is a separate companion product. It places inspection results on a 3D model and works alongside NDT Reports. You can get a quote for NDT Reports alone or for both together.</p><h2>See your own reports in it</h2><p>Send us a UT, RT or thickness report you issue today, and we will show you the same report built in NDT Reports, from the tablet to the signed PDF. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20USA%20demo\">Book an NDT Reports demo</a> and tell us which owners and codes you work to most, and whether your clients would value <a href=\"/digital-twin-reporting\">3D digital twin reporting</a> alongside it.</p>\n<h2>NDT Reports by region</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports global overview</a></li><li><a href=\"/erp/apps/ndt-reports/canada\">NDT Reports in Canada</a></li><li><a href=\"/erp/apps/ndt-reports/europe\">NDT Reports in UK &amp; Europe</a></li><li><a href=\"/erp/apps/ndt-reports/middle-east\">NDT Reports in Middle East</a></li><li><a href=\"/erp/apps/ndt-reports/india\">NDT Reports in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(United%20States)\">Send an enquiry about NDT Reports</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ndt-reports/canada","publishedAt":"2026-09-27","title":"NDT Report Software in Canada | Atlantis NDT","description":"NDT report software for Canadian inspection firms: CSA W59 and Z662 work, radiography source and IQI records, offline field app. Request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Reports: NDT Report Software for Inspection Companies in Canada</h1>\n<p>Method-specific NDT inspection reports, captured in the field and issued from the ERP. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<h2>Why NDT reporting in Canada has its own shape</h2><p>Canadian NDT companies sit between two worlds. Technicians are certified centrally by Natural Resources Canada under CAN/CGSB-48.9712, the Canadian adoption of ISO 9712, while many clients, especially in oil and gas, also work with American codes and ASNT-certified crews who cross the border for shutdowns. Construction work runs to CSA standards, pressure equipment falls under provincial safety authorities, and radiography is licensed federally.</p><p>Each of those shows up on a report. The certification of the technician. The CSA or ASME standard used for acceptance. The provincial or owner-user inspector who witnessed the work. The radiography technique and IQI. When reports are assembled by hand after a long shift at a site north of Fort McMurray, one of those details is usually the thing that goes missing.</p><p>The NDT Reports app in <a href=\"/erp\">Atlantis NDT ERP</a> captures them in one place. It covers 17 report types, each with its own numbering, method-specific fields and a workflow from draft to in progress, review, approved and sent. The inspector, reviewer and approver sign on the report, and a third-party or authorized inspector can sign too. Output uses your templates, in Excel, Word, PDF or HTML.</p><p>Below is how that fits the codes, regulators and industries Canadian inspection companies actually work with.</p><h2>Recording CGSB/NRCan certification on the report</h2><p>Under the NRCan program, certification is issued by a central body rather than by the employer. That is different from the US employer-based model, but it does not remove the employer's job. You still need to know, on the day of each inspection, that the technician's certification is valid for the method and level, and your client still wants to see it reflected on the report.</p><p>The ERP's Certificates app records each technician's scheme, which can be ISO 9712 for NRCan certification or SNT-TC-1A for ASNT-based certs held by cross-border crews, with the certifying body, level, method, issue and expiry dates, and attachments. It flags certs expiring within 90 days and those already expired, and timesheets warn when a technician's cert is not valid. Vision tests are recorded with their own expiry.</p><p>On the report itself, NDT Reports captures the inspector, reviewer and approver with signatures. In marine mode it goes further and merges the inspector's Level II certificate into the PDF.</p><p>One clarification: Atlantis NDT does not train or certify for the NRCan/CGSB scheme. Our <a href=\"/training\">training</a> is based on ASNT SNT-TC-1A. The ERP simply records whichever certifications your technicians hold.</p><h2>CSA W59 fabrication and structural steel</h2><p>Structural fabrication shops certified by the Canadian Welding Bureau under CSA W47.1 build to CSA W59 for welded steel construction. The NDT that goes with that work, mostly UT, MT and VT on welds, has to be traceable to the drawing, the welding procedure and the acceptance clauses of W59.</p><p>NDT Reports carries the references a fabrication QA manager needs on each report: work order, request number, contract, drawing numbers, WPS number, and the procedure and standard references. Each weld goes on as a line with defect type and orientation, and the report closes with an overall result of acceptable, not acceptable, or acceptable with remarks.</p><p>For a busy fab shop, the day-to-day benefits are practical:</p><ul><li>The shop inspector records weld lines on a tablet at the bay instead of on a clipboard</li><li>UT reports carry the probe calibration table, so the reviewer can see calibration without chasing a separate sheet</li><li>MT reports record technique and particle type, and VT has its own report type and numbering</li><li>Reports go to the engineer of record or client in your template, with drawing and WPS numbers already on them</li></ul><p>If your shop also fabricates to ASME for pressure work, the same app handles those reports; only the standard reference and the template change.</p><h2>CSA Z662 pipelines in Alberta and British Columbia</h2><p>Pipeline construction and maintenance in Canada works to CSA Z662, under the Canada Energy Regulator for federally regulated lines and provincial regulators such as the Alberta Energy Regulator and the BC Energy Regulator for provincial ones. Operators expect a complete weld inspection record for every girth weld, and they expect to find it years later.</p><p>On a spread, that means a long run of RT or ultrasonic reports tied to weld numbers, with the acceptance standard referenced. NDT Reports handles this with separate numbering per method, weld lines with defect type and orientation, and reference fields for work order, drawing and WPS. PAUT reports record focal laws, and TOFD has its own report type.</p><p>Pipeline work in northern Alberta and BC means long stretches with no signal. The offline field app is an installable web app: technicians pick the method, record readings, capture photos and sign on screen with no connection, and drafts sync when the crew returns to camp or reaches coverage. A PDF preview on the device lets them check the report before it goes to review.</p><p>The REST API behind the app gives each technician the jobs assigned to them and the equipment issued to them, so crews on rotation pick up where the last shift left off.</p><h2>ABSA, CSA B51 and pressure equipment</h2><p>Pressure equipment in Canada is regulated provincially, with CSA B51 as the common reference for boilers, pressure vessels and piping. In Alberta, ABSA administers pressure equipment safety and oversees owner-user inspection programs at plants and upgraders. Ontario has TSSA, and British Columbia has Technical Safety BC.</p><p>For an NDT company, that means reports often need to be accepted by an owner-user's inspector or a safety codes officer. NDT Reports has a third-party inspector or authorized inspector field with name and signature, so that sign-off lives on the report rather than in a separate letter.</p><p>Report types that come up regularly on pressure equipment work:</p><ul><li><strong>UT thickness</strong>, with readings by direction, for vessel and piping inspections</li><li><strong>PWHT</strong> for heat treatment on repair welds, with <strong>hardness</strong> reports alongside</li><li><strong>PMI</strong> for alloy verification on repairs and replacements</li><li><strong>Ferrite</strong> for duplex and austenitic stainless welds</li><li><strong>RT</strong> and <strong>UT</strong> for repair weld acceptance</li></ul><p>The app records the NDT data and the sign-offs. Decisions about fitness for service and inspection intervals stay with the owner-user's program and the regulator. Where a provincial client needs a specific report layout, it is added as a versioned company template.</p><h2>Radiography under CNSC licensing</h2><p>Industrial radiography in Canada is licensed federally by the Canadian Nuclear Safety Commission. Exposure devices must be used by certified exposure device operators, and licensees carry obligations for source control, dosimetry and transport. Those obligations belong to your licence and your radiation safety program.</p><p>NDT Reports makes sure the technical side of each RT job is complete. The RT report records the source, the technique and the IQI type and placement, alongside weld lines with defect type and orientation. Computed radiography has its own report type and numbering, so CR work is recorded on its own terms.</p><p>Related records in the ERP:</p><ul><li>The employee NDT profile records radiation safety training, radiation badge number and medical fitness expiry</li><li>The Fleet app records whether a vehicle can carry radioactive sources, with transport licence number and expiry</li><li>The Certificates app can hold exposure device operator certification under its 'other' scheme option, with its expiry, next to the technician's NDT certs</li></ul><p>Dosimetry results, source logs and leak tests stay in the systems your CNSC licence requires. What the ERP adds is that nobody has to dig through three binders to confirm the radiographer on a report was qualified that day.</p><h2>Oil sands, upgraders and winter shutdowns</h2><p>Alberta's oil sands operations around Fort McMurray, the upgraders and refineries in the Industrial Heartland near Edmonton, and refining and petrochemical sites such as Sarnia run large maintenance turnarounds with big NDT crews, often living in camps and often working through winter. Reports are produced in volume, under time pressure, and reviewed by owners with strict QA expectations.</p><p>The problems are familiar: paper forms that get wet or lost, technicians rotating out before their reports are typed, a Level III reviewing a stack of printouts at the end of a shift, and an owner asking which reports from last week are still outstanding. NDT Reports addresses each one:</p><ul><li>Offline capture on a tablet, so work is recorded in the unit, not reconstructed from notes later</li><li>A visible workflow, so reports still in review, or approved but unsent, are easy to find</li><li>Separate numbering per method, which keeps a turnaround's UT, MT, PT, RT, IRIS and PMI reports in order</li><li>Output in the owner's template, including Excel layouts filled automatically from mapped fields</li></ul><p>Heat exchanger bundles pulled during turnarounds are a steady source of IRIS and eddy current work. Both have their own report types, with numbering and an overall result, so tube inspection reports do not end up on a generic form. The Team Assignments app, meanwhile, blocks double-booking of technicians and equipment serials when the crew list changes daily.</p><h2>Ontario nuclear, power and marine work</h2><p>Ontario's nuclear stations at Bruce, Darlington and Pickering, and the supply chain around them, work to the CSA N285 series and demanding quality assurance programs. NDT on these sites is highly procedural: every report must reference the approved procedure and be reviewed and approved by the right people.</p><p>NDT Reports supports that discipline with procedure and standard references on every report, inspector, reviewer and approver signatures, and a clear status from draft to sent. Whether a nuclear client accepts a given electronic reporting process is a decision for their QA program, and we work through their requirements with you during implementation rather than assume.</p><p>On the coasts, shipyards and repair yards in Halifax, Vancouver and St. John's deal with classification societies on hull and machinery surveys. Marine mode adds a vessel cover page with photo, location and dates, and merges into the PDF the class certificate, chosen from a library including DNV, ABS, Lloyd's Register, Bureau Veritas, RINA, IRS and ClassNK, along with the inspector's Level II cert and the calibration certificate. Photos are laid out in a two-up grid, which keeps long thickness surveys readable.</p><h2>How NDT Reports links to the rest of your operation</h2><p>A report is only as good as the records behind it. In the ERP, those records sit in connected apps rather than separate spreadsheets:</p><ul><li><strong>Projects</strong> hold the NDT job with site, client PO, methods, codes, scope and acceptance criteria, which is where the report's work order comes from</li><li><strong>Certificates</strong> hold NRCan and ASNT-based certifications with expiry status and daily email alerts</li><li><strong>Asset Management</strong> tracks every instrument and probe by serial number, with calibration records and certificate expiry alerts</li><li><strong>Procedures</strong> hold approved, revision-controlled procedures that the report references</li><li><strong>Team Assignments</strong> dispatch crews and block double-booking</li><li><strong>Invoicing</strong> bills from timesheet hours against the same job</li></ul><p>You don't need all of them on day one. Many companies start with NDT Reports and Certificates and add the rest as reports start flowing.</p><h2>Featured: Digital Twin Reporting Software</h2><p>Oil sands operators, utilities and midstream companies manage very large asset bases. For them, a stack of PDFs is hard to use. They want to see where findings sit on the asset and how they change between inspections.</p><p><a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> is Atlantis NDT's companion product for that need. It places inspection results on a 3D model of the asset. It works alongside the NDT Reports app in the ERP: the ERP runs the job, captures the data, handles sign-off and produces the signed report, and Digital Twin Reporting Software gives the owner a spatial view of the results.</p><ul><li>A plant engineer in Calgary can review findings on a model of a unit in Fort McMurray without a site visit</li><li>Repeat inspections of the same equipment are easier to compare when results sit in place on the model</li><li>It gives your company a clear point of difference in owner prequalification and tenders</li></ul><p>The ERP app does not create 3D models or digital twins itself. It is the reporting and workflow engine, and the 3D product is scoped separately. You can start with NDT Reports and add digital twin reporting when a client asks for it.</p><h2>Implementation for Canadian inspection companies</h2><p>Atlantis NDT deploys and configures the ERP for you. For Canadian customers, setup usually covers:</p><ul><li>Templates in English and, for Quebec clients, French, loaded as versioned company templates</li><li>Report numbering per method, following your existing convention</li><li>Inspector, reviewer and approver roles set to match your quality manual</li><li>Certificates set up for NRCan ISO 9712 and ASNT-based certs side by side</li><li>Field app rollout on crew tablets, tested offline on a real job</li><li>Hosting arrangements and data location, discussed and agreed with you</li></ul><p>GST/HST and provincial taxes on invoices are configured during implementation in the Invoicing app, if you take it. Anything your clients require that the standard app doesn't have is agreed as customization scope. See the full list of <a href=\"/erp/apps\">ERP apps</a> for what else connects to reports.</p><p>Atlantis NDT ERP is affordable, accessible and fully customizable, and pricing is quote on request. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20Canada%20quote\">Request an NDT Reports quote</a> for your Canadian operation.</p><h2>Frequently asked questions</h2><h3>Can the software record NRCan CGSB certification?</h3><p>Yes. The Certificates app records ISO 9712 certifications, including NRCan certification under CAN/CGSB-48.9712, with certifying body, level, method and expiry. Atlantis NDT does not train for this scheme; our training is SNT-TC-1A based.</p><h3>Does it work at remote camps with no internet?</h3><p>Yes. The field app works offline, storing drafts and photos on the device and syncing when a connection is available.</p><h3>Can an ABSA owner-user or third-party inspector sign the report?</h3><p>Yes. There is a third-party or authorized inspector field with name and signature, alongside your own inspector, reviewer and approver.</p><h3>Can reports reference CSA W59 or Z662?</h3><p>Yes. Each report carries procedure and standard references, plus WPS, drawing, contract and work order numbers. The acceptance standard you apply is recorded; the app does not evaluate acceptance for you.</p><h3>Can we issue reports in French?</h3><p>Yes, by loading French-language templates as company templates during implementation.</p><h3>Is Digital Twin Reporting Software part of the ERP?</h3><p>No. It is a separate companion product that places inspection results on a 3D model of the asset and works alongside NDT Reports.</p><h2>Book a demo with your own report</h2><p>Send us a sample report from a recent pipeline, fabrication or turnaround job, and we will show it built in NDT Reports, from the tablet in the field to the signed PDF. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20Canada%20demo\">Book an NDT Reports demo</a>.</p>\n<h2>NDT Reports by region</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports global overview</a></li><li><a href=\"/erp/apps/ndt-reports/usa\">NDT Reports in United States</a></li><li><a href=\"/erp/apps/ndt-reports/europe\">NDT Reports in UK &amp; Europe</a></li><li><a href=\"/erp/apps/ndt-reports/middle-east\">NDT Reports in Middle East</a></li><li><a href=\"/erp/apps/ndt-reports/india\">NDT Reports in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(Canada)\">Send an enquiry about NDT Reports</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ndt-reports/europe","publishedAt":"2026-09-27","title":"NDT Report Software for UK & Europe | Atlantis NDT","description":"NDT report software for UK and European inspection firms: EN ISO method reports, PED and North Sea work, offline field capture. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Reports: NDT Report Software for UK and European Inspection Companies</h1>\n<p>Method-specific NDT inspection reports, captured in the field and issued from the ERP. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<h2>Reporting NDT to EN ISO standards</h2><p>Across the UK and Europe, NDT on welds is defined by a family of EN ISO standards: one for the testing technique, one for acceptance levels, and EN ISO 5817 for the weld quality levels behind them. A report that does not state which technique standard and which acceptance level were applied is incomplete, and clients, notified bodies and class surveyors will send it back.</p><table><thead><tr><th>Method</th><th>Typical technique standard</th><th>Typical acceptance standard</th><th>What NDT Reports records</th></tr></thead><tbody><tr><td>UT of welds</td><td>EN ISO 17640</td><td>EN ISO 11666</td><td>Probe calibration table, weld lines with defect type and orientation</td></tr><tr><td>RT of welds</td><td>EN ISO 17636-1 (film) and 17636-2 (digital)</td><td>EN ISO 10675-1</td><td>Source, technique, IQI type and placement; CR as its own report type</td></tr><tr><td>MT</td><td>EN ISO 17638</td><td>EN ISO 23278</td><td>Technique and particle type</td></tr><tr><td>PT</td><td>EN ISO 3452-1</td><td>EN ISO 23277</td><td>Method and developer</td></tr><tr><td>VT</td><td>EN ISO 17637</td><td>EN ISO 5817</td><td>VT report type with weld lines and result</td></tr><tr><td>PAUT</td><td>EN ISO 13588</td><td>EN ISO 19285</td><td>Focal laws</td></tr><tr><td>TOFD</td><td>EN ISO 10863</td><td>EN ISO 15626</td><td>TOFD report type with weld lines and result</td></tr></tbody></table><p>NDT Reports stores the procedure and standard references on every report, together with work order, request, contract, drawing and WPS numbers. The acceptance decision belongs to your Level 2; the app records it as acceptable, not acceptable, or acceptable with remarks, and signs it off through review and approval.</p><p>The app covers 17 report types in all, including ECT, IRIS, MFL, PWHT, PMI, hardness, UT thickness, ferrite and holiday/coating, each with its own numbering sequence.</p><h2>PCN, EN ISO 9712 and the employer's authorisation</h2><p>In Europe, personnel certification is third-party. Technicians hold EN ISO 9712 certificates issued by a certification body, most often PCN through BINDT in the UK, or national schemes elsewhere. CSWIP is common for welding inspectors and some NDT categories. But EN ISO 9712 is explicit that certification alone does not authorise someone to work: the employer must authorise them in writing for the tasks they perform.</p><p>That puts responsibility back on you. The ERP's Certificates app records each technician's scheme (ISO 9712, PCN, CSWIP and others), certifying body, level, method, industry sector, issue, expiry and renewal dates, plus vision tests with their own expiry. It flags certs expiring within 90 days, can send configurable daily email alerts, and timesheets warn when a technician's cert is not valid.</p><p>On the report, NDT Reports records inspector, reviewer and approver with signatures, and the reviewer and approver roles are set to match your written authorisations. In marine mode, the inspector's certificate is merged into the report PDF so the surveyor sees it without asking.</p><p>For clarity: Atlantis NDT does not deliver PCN, CSWIP or ISO 9712 training. Our <a href=\"/training\">training</a> is based on ASNT SNT-TC-1A. The ERP records whichever certifications your people hold.</p><h2>From Level 1 capture to Level 3 approval</h2><p>EN ISO 9712 draws clear lines between levels. A Level 1 carries out tests and records results under supervision but does not evaluate them alone. A Level 2 sets up equipment, performs and interprets tests and reports against the acceptance standard. A Level 3 takes responsibility for techniques and procedures. A good reporting workflow follows those lines instead of blurring them.</p><p>NDT Reports uses five stages:</p><ol><li><strong>Draft</strong>: the report is opened against the work order, with references already filled in</li><li><strong>In progress</strong>: readings, weld lines, photos and results are captured, often in the offline field app</li><li><strong>Review</strong>: the Level 2 or Level 3 reviewer checks technique, coverage, acceptance references and result</li><li><strong>Approved</strong>: the approver signs, and any third-party or notified body inspector's name and signature is recorded</li><li><strong>Sent</strong>: the report leaves in the client's template, and the record shows it has been issued</li></ol><p>Who is allowed to review and approve is configured during implementation to match your written authorisations. Procedure references on the report can point to procedures held in the ERP's Procedures app, where Level 3 approval and revision history are tracked. That link is what an auditor looks for when they pick one report at random and ask to see the procedure behind it.</p><h2>PED 2014/68/EU, notified bodies and UK pressure equipment</h2><p>Pressure equipment placed on the EU market falls under the Pressure Equipment Directive 2014/68/EU. For higher-category equipment, NDT personnel working on permanent joints must be approved by a notified body or a recognised third-party organisation. In Great Britain, the equivalent regime is the Pressure Equipment (Safety) Regulations 2016, with UK approved bodies and UKCA marking.</p><p>For an NDT company working for fabricators, that means the notified body's inspector often reviews or witnesses the NDT and wants their involvement recorded. NDT Reports has a third-party inspector field with name and signature on every report. References to the WPS, drawing, contract and procedure sit on the same record, which is what a notified body expects to see when it reviews the manufacturing dossier.</p><p>Fabricators' dossiers are usually compiled in a fixed format. Company templates in Excel, Word, PDF or HTML carry your logo, header and footer, and Excel templates are filled automatically by mapping fields to cells, so a fabricator's standard NDT summary sheet can be produced from report data without re-typing.</p><p>PMI, ferrite, hardness and PWHT report types cover the supporting records that often travel with a pressure equipment dossier for alloy and stainless work.</p><h2>UK in-service work: PSSR, competent persons and IRR17</h2><p>In service, UK pressure systems fall under the Pressure Systems Safety Regulations 2000. The user or owner must have a written scheme of examination, and a competent person, often an engineering surveyor from an insurer or inspection body, carries out the examinations. NDT companies supply the thickness surveys, weld inspections and surface crack detection that the competent person relies on.</p><p>The competent person usually wants the data in a clear, consistent format, and sometimes wants to sign or countersign. UT thickness reports record readings by direction; MT and PT reports record technique, particle type, method and developer; and the third-party inspector field captures the surveyor's name and signature where they witness the work.</p><p>Site radiography in Great Britain is governed by the Ionising Radiations Regulations 2017, enforced by HSE, with radiation protection advisers and supervisors appointed by the employer. Those duties stay with your radiation protection arrangements. On the technical record:</p><ul><li>The RT report records source, technique, and IQI type and placement</li><li>Computed radiography has its own report type and numbering</li><li>Each technician's NDT profile records radiation safety training, radiation badge number and medical fitness expiry</li><li>The Fleet app records whether a vehicle can carry radioactive sources, with transport licence details and expiry</li></ul><h2>North Sea offshore work from Aberdeen</h2><p>Offshore inspection on the UK and Norwegian continental shelf has its own rhythm: rotations, helicopter logistics, limited bandwidth on the installation and a client team onshore waiting for results. Rope access NDT technicians and inspection crews produce a lot of UT thickness, MT, PAUT and visual work, and the reports have to get from the platform to the client's integrity team in Aberdeen or Stavanger reliably.</p><p>The offline field app suits this. It installs on a tablet like any app, works without a connection, stores drafts and photos on the device and syncs when bandwidth allows, whether that is the platform's network overnight or back onshore. Technicians choose the method, record readings and weld lines, attach photos, sign on screen and preview the PDF before submitting.</p><p>Because the REST API gives each technician their assigned jobs and issued equipment, the instrument and probe on the report match what was actually sent offshore. With calibration records held in the ERP's Asset Management app, the reviewer onshore can check calibration status without asking the offshore team to photograph a certificate.</p><p>Onshore, the reviewer and approver work through the review queue, and approved reports go to the operator in the operator's template, with numbering per method keeping each campaign's reports in order.</p><h2>Shipyards, class and marine mode</h2><p>Europe has a dense network of shipyards and repair yards, from Rotterdam and Hamburg to Gdansk, Genoa and the Tyne. Class surveyors from Lloyd's Register, DNV, Bureau Veritas and RINA review NDT on hulls, machinery and repairs every day, and each wants a complete pack.</p><p>Marine mode in NDT Reports builds that pack. It adds a vessel cover page with the vessel photo, inspection location and dates, and when the PDF is produced it merges in the classification-society certificate from a library covering DNV, ABS, Lloyd's Register, Bureau Veritas, RINA, IRS and ClassNK, the inspector's Level II certificate and the calibration certificate for the instrument used. Inspection photos are laid out in a two-up grid.</p><p>For a marine inspection company, this removes the slowest part of the job: finding and attaching the right certificates for every report. Hull thickness gauging uses the UT thickness report type with readings by direction, and weld repairs use UT, MT or RT reports, all in the same app with separate numbering.</p><h2>GDPR and technician personal data</h2><p>NDT records contain personal data. Reports carry technicians' names and signatures. Certification records include scanned certificates with personal details, and vision test records relate to health, which GDPR and UK GDPR treat as special category data that needs extra care.</p><p>The ERP does not make you GDPR compliant on its own; that depends on your policies and processes. But it gives you far better control than scattered spreadsheets and email attachments:</p><ul><li>Access to reports, certificates and vision test records is set by role during implementation, so only the people who need health-related data can see it</li><li>Records sit in one system rather than being copied across shared drives and inboxes</li><li>Data location and hosting arrangements are agreed with you before go-live</li><li>Retention of old records is discussed and configured as part of the setup scope</li></ul><p>If you work across several EU countries, we talk through where your data is held and who at Atlantis NDT has access during support, so you can reflect it in your own records of processing.</p><h2>How NDT Reports connects to the rest of the ERP</h2><p>NDT Reports is one app in <a href=\"/erp\">Atlantis NDT ERP</a>. The report pulls its context from the other apps, which is why it stays consistent:</p><ul><li><strong>Projects</strong>: the job with site, client PO, contract, methods, codes, scope and acceptance criteria</li><li><strong>Certificates</strong>: PCN, ISO 9712 and CSWIP records with expiry status and alerts</li><li><strong>Asset Management</strong>: instruments and probes by serial number, with calibration records including provider, certificate number, accredited lab flag and next due date</li><li><strong>Procedures</strong>: revision-controlled procedures approved by your Level 3</li><li><strong>Team Assignments</strong>: crew dispatch with double-booking of technicians and equipment serials blocked</li><li><strong>Invoicing</strong>: billing from approved timesheet hours against the same job</li></ul><p>Start with what hurts most. For many European NDT companies that is reporting and certification tracking; the rest can follow.</p><h2>Featured: Digital Twin Reporting Software</h2><p>European operators, particularly offshore and in chemicals, are moving inspection data into visual, asset-based tools. Integrity engineers want to click on a vessel or pipe spool and see what was found there, not search a document management system.</p><p><a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> is Atlantis NDT's companion product for this. It places inspection results on a 3D model of the asset and works alongside the NDT Reports app in the ERP. The ERP captures the data, runs review and approval, and issues the signed report; the digital twin product shows the client where results sit on the asset.</p><ul><li>Onshore integrity teams can review offshore findings in context</li><li>Repeat surveys of the same structure are easier to compare in place</li><li>It helps an inspection company stand out in operator and EPC tenders</li></ul><p>The ERP app does not build 3D models itself. The companion product is scoped and quoted separately, or together with NDT Reports if you want both.</p><h2>Implementation in the UK and Europe</h2><p>Atlantis NDT deploys and configures the ERP remotely and works across time zones. A European rollout usually includes:</p><ol><li>Collecting your current report formats by method and the layouts your key clients, fabricators and class societies expect</li><li>Loading them as versioned templates, in the languages you report in, with Excel fields mapped to cells where needed</li><li>Setting numbering per method, and reviewer and approver roles in line with your written authorisations</li><li>Setting up Certificates for PCN, ISO 9712 and CSWIP records, with vision tests and alert recipients</li><li>Rolling out the field app and running a real job offline</li><li>Configuring VAT on invoices, if you take the Invoicing app</li></ol><p>Anything specific to your market that is not in the standard app is agreed as customization scope. See the full set of <a href=\"/erp/apps\">ERP apps</a>. The system is affordable, accessible and fully customizable, and pricing is quote on request: <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20Europe%20quote\">request a quote for NDT Reports</a>.</p><h2>Frequently asked questions</h2><h3>Does the software support EN ISO 17640 and other EN ISO method standards?</h3><p>Yes. Every report records the procedure and the technique and acceptance standards applied, such as EN ISO 17640 with EN ISO 11666 for UT of welds. The app records what your Level 2 applied; it does not evaluate acceptance itself.</p><h3>Can it record PCN and CSWIP certifications?</h3><p>Yes. The Certificates app records ISO 9712, PCN and CSWIP schemes with level, method, sector and expiry. Atlantis NDT does not train for these schemes; our training is SNT-TC-1A based.</p><h3>Can a notified body or competent person sign the report?</h3><p>Yes. The third-party inspector field records their name and signature alongside your inspector, reviewer and approver.</p><h3>Will it work offshore with limited bandwidth?</h3><p>Yes. The field app works offline, stores drafts and photos on the device and syncs when a connection is available.</p><h3>Is it GDPR compliant?</h3><p>Software alone cannot make you compliant. Role-based access, a single controlled system and an agreed hosting location help you meet your own GDPR obligations.</p><h3>Can reports be issued in other languages?</h3><p>Yes. Templates in the languages you report in are loaded as versioned company templates during implementation.</p><h3>Is Digital Twin Reporting Software part of the ERP?</h3><p>No. It is a separate companion product that places results on a 3D model and works alongside NDT Reports.</p><h2>See your own report built in it</h2><p>Send us a sample UT, RT or thickness report you issue today, and we will show you the same report produced in NDT Reports, from the field app to the signed PDF. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20Europe%20demo\">Book an NDT Reports demo</a>.</p>\n<h2>NDT Reports by region</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports global overview</a></li><li><a href=\"/erp/apps/ndt-reports/usa\">NDT Reports in United States</a></li><li><a href=\"/erp/apps/ndt-reports/canada\">NDT Reports in Canada</a></li><li><a href=\"/erp/apps/ndt-reports/middle-east\">NDT Reports in Middle East</a></li><li><a href=\"/erp/apps/ndt-reports/india\">NDT Reports in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(UK%20%26%20Europe)\">Send an enquiry about NDT Reports</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ndt-reports/middle-east","publishedAt":"2026-09-27","title":"NDT Report Software in the Middle East | Atlantis NDT","description":"NDT report software for Gulf inspection contractors: Aramco, ADNOC and QatarEnergy client work, shutdown crews, offline field reports. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Reports: NDT Report Software for Inspection Contractors in the Middle East</h1>\n<p>Method-specific NDT inspection reports, captured in the field and issued from the ERP. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<h2>What Gulf clients expect from an NDT report</h2><p>NDT reporting in the Gulf is shaped by a small number of very large asset owners. Saudi Aramco, SABIC, ADNOC and its group companies, QatarEnergy, KNPC and KIPIC in Kuwait, Bapco in Bahrain and PDO in Oman each have their own engineering standards, their own requirements for inspection contractors and, often, their own report formats. An NDT company working across the region may produce the same UT report in four different layouts in a single month.</p><p>Reports are also read by more people than in many markets. The contractor's Level II signs, the contractor's QC reviews, a third-party inspection agency may witness, and the owner's inspector accepts. Every one of those signatures has to be on the document, and every reference, from WPS number to drawing to procedure, has to match the approved project documents.</p><p>The NDT Reports app in <a href=\"/erp\">Atlantis NDT ERP</a> is built for that. It covers 17 report types, each with its own numbering and method-specific fields, a workflow from draft to in progress, review, approved and sent, signatures for inspector, reviewer and approver, and a separate third-party or authorized inspector field. Reports come out in your versioned company templates, one per client format if needed.</p><h2>Saudi Aramco projects and contractor requirements</h2><p>Working for Saudi Aramco means working to its engineering standards (SAES) and materials system specifications, with inspection on projects organised through Saudi Aramco Inspection Checklists (SAICs) and Saudi Aramco Typical Inspection Plans (SATIPs). NDT contractors go through approval, and owners commonly require technician qualification checks before anyone works on their facilities.</p><p>In practice that makes the report the place where many things are checked at once: that the technician is qualified and certified for the method, that the procedure is the approved revision, that the equipment was calibrated, and that the acceptance criteria match the applicable standard. NDT Reports records procedure and standard references, WPS, drawing, contract and work order numbers on every report. The UT report includes the probe calibration table; the RT report records source, technique, and IQI type and placement.</p><p>Around the report, the ERP holds the supporting evidence: technician certifications with expiry in the Certificates app, calibration certificates in Asset Management, and approved procedure revisions in the Procedures app. When an owner's inspector asks for proof, it is a lookup, not a search through a site container.</p><p>Owner-specific report layouts are loaded as templates during implementation. Nothing here implies approval by any owner; your contractor approval remains your own process.</p><h2>ADNOC, QatarEnergy, KNPC and other regional owners</h2><p>In the UAE, ADNOC's onshore, offshore, gas and refining companies, including the Ruwais complex, run large inspection programs with their own specifications. In Qatar, Ras Laffan and Mesaieed host LNG, refining and petrochemical assets. In Kuwait, the Mina Al-Ahmadi and Mina Abdullah refineries and the Al-Zour complex drive steady inspection demand.</p><p>Each owner, and often each project's EPC contractor, specifies its own documentation. NDT Reports handles this through versioned company templates in Excel, Word, PDF or HTML. You keep one set of report data and produce it in the layout each client expects. Where a client requires an Excel register, the app fills Excel templates automatically by mapping fields to cells, which removes one of the biggest sources of transcription errors on large projects.</p><p>Common report types on regional oil, gas and petrochemical work:</p><ul><li>RT and computed radiography for piping and pipeline welds</li><li>UT, PAUT and TOFD for thick-wall welds on vessels and heavy piping</li><li>UT thickness with readings by direction for in-service inspection</li><li>PMI, hardness, ferrite and PWHT on alloy and stainless piping</li><li>Holiday and coating inspection on pipelines and tanks</li><li>IRIS and eddy current on heat exchanger and air cooler tubes</li></ul><h2>How the workflow maps to an inspection and test plan</h2><p>Gulf projects run on inspection and test plans with hold, witness and review points for the contractor, the third-party inspection agency and the owner. The report workflow in NDT Reports lines up with that structure:</p><ol><li><strong>Draft</strong>: the report is opened against the work order, carrying the contract, drawing, WPS and procedure references from the start</li><li><strong>In progress</strong>: the technician, usually a Level II, records readings, weld lines with defect type and orientation, and photos</li><li><strong>Review</strong>: contractor QC or the Level III checks technique, procedure revision, coverage and acceptance criteria</li><li><strong>Approved</strong>: the approver signs, and the TPI or owner inspector's name and signature are recorded in the third-party inspector field</li><li><strong>Sent</strong>: the report is issued in the owner's template, and the record shows it has gone</li></ol><p>Because every report has a status, the question asked at every daily progress meeting, how many reports are pending and where, has a straight answer from the system instead of a round of phone calls.</p><p>Who can review and approve is set during implementation to match your QA plan and the owner's requirements. If a report is sent back, it returns to the technician with the reviewer's comments, rather than disappearing into an email chain.</p><h2>ASNT and ISO 9712 on the same crew</h2><p>Gulf NDT crews are international. A single shutdown team may include technicians from India, Pakistan, the Philippines, Egypt and the UK, holding ASNT SNT-TC-1A-based certifications from an employer, ISO 9712 certifications from a national body, PCN or CSWIP. Owners accept different schemes for different work, and the contractor has to know exactly what each person holds.</p><p>The ERP's Certificates app records all of these side by side: scheme, certifying body, level, method, issue, expiry and renewal dates, industry sector, OJT and training hours, vision tests and attachments. Status is computed automatically as active, expiring soon, expired or revoked, and daily email alerts can go to your QA and operations staff. Timesheets warn when a technician's certificate is not valid.</p><p>That feeds straight into reporting. The inspector on an NDT report is a technician whose certification you can see in the same system, and for marine reports the inspector's Level II certificate is merged into the PDF.</p><p>Expatriate crews also carry residency and visa-linked documents, such as the iqama in Saudi Arabia. Employee records can hold these documents; any expiry tracking you need for them is configured during implementation. Atlantis NDT's own <a href=\"/training\">training</a> is based on ASNT SNT-TC-1A only.</p><h2>Shutdown and turnaround season</h2><p>Most major shutdowns in the Gulf are scheduled for the cooler months, which concentrates a year's worth of reporting pressure into a few intense windows. Contractors mobilise large crews, run day and night shifts, and are expected to turn reports around daily so the owner can release equipment for box-up.</p><p>NDT Reports helps keep that manageable:</p><ul><li>Technicians record readings, weld lines and photos on tablets in the unit, instead of on paper that is typed up at night</li><li>Separate numbering per method keeps large volumes of UT, RT, MT, PT, PMI and hardness reports in clean sequences</li><li>The review queue shows the Level III or QC reviewer exactly what is waiting, and what is approved but not yet sent to the owner</li><li>The third-party or owner's inspector signs on the report itself</li><li>Each report is tied to the work order, so the owner's daily status request is answered from the system</li></ul><p>Shutdowns also stress people and equipment. The Team Assignments app blocks double-booking of technicians and equipment serial numbers and warns when equipment assigned to a job is out of calibration, while the field app's REST API shows each technician their assigned jobs and issued equipment.</p><h2>Offline reporting in the desert and offshore</h2><p>A lot of Gulf NDT happens far from reliable signal: remote gas plants, pipeline corridors crossing the desert, offshore fields in the Arabian Gulf, and new-build sites where the network is not yet installed. Some plants also restrict device connectivity inside process areas.</p><p>The field app is an installable web app that works offline. Drafts and photos are stored on the device and synced when a connection is available, at the site office, the camp or back onshore. Technicians use the method picker to open the right report type, capture photos, sign on screen and preview the PDF before submission.</p><p>That also protects against a common problem in hot climates: paper forms that are smudged or unreadable by the time they reach the office. Data captured on the device is exactly what the reviewer sees.</p><p>Where a client's site rules limit the use of personal devices or cameras, the field setup is agreed during implementation around those rules, for example company-issued tablets, or photo capture only where permits allow.</p><h2>Radiography and source controls</h2><p>Industrial radiography in the region is regulated nationally, for example by the Nuclear and Radiological Regulatory Commission in Saudi Arabia and the Federal Authority for Nuclear Regulation in the UAE. Licensing, source movement approvals, dosimetry and site radiation controls are the licence holder's responsibility and stay in the systems those regulators require.</p><p>NDT Reports covers the technical record. The RT report records the source, technique, and IQI type and placement, alongside weld lines with defect type and orientation. Computed radiography has its own report type and numbering, which matters as more projects accept CR.</p><ul><li>Technician NDT profiles record radiation safety training, radiation badge number and medical fitness expiry</li><li>The Fleet app records whether a vehicle can carry radioactive sources, with transport licence number and expiry</li><li>Project records carry safety induction and work permit fields, useful where owners require a permit for every radiography window</li></ul><p>Night-shift radiography during shutdowns generates many reports quickly; the workflow keeps them moving so they are ready for review the next morning.</p><h2>Marine, ship repair and offshore fabrication</h2><p>Ship repair yards and offshore fabrication yards in Dubai, Sharjah, Bahrain, Ras Al-Khair and Jubail work with classification societies on every repair and new-build. Reports must reach the surveyor with the class certificate, the inspector's qualification and the equipment calibration certificate attached.</p><p>Marine mode in NDT Reports handles this. It adds a vessel cover page with photo, inspection location and dates, and merges into the PDF the classification-society certificate from a library covering DNV, ABS, Lloyd's Register, Bureau Veritas, RINA, IRS and ClassNK, the inspector's Level II certificate and the calibration certificate. Photos are arranged in a two-up grid for readability.</p><p>Hull thickness gauging uses the UT thickness report with readings by direction, and repair welds use UT, MT or RT reports, all in one system with separate numbering. For offshore jacket and topside fabrication, PAUT and TOFD reports sit alongside the rest, so one yard's whole NDT record lives in one place.</p><h2>Connected to the rest of the ERP</h2><p>A Gulf contractor's reporting problems are rarely only about the report. They are about crews, certificates, equipment and billing that sit in different spreadsheets. The ERP connects them:</p><ul><li><strong>Projects</strong> carry the job, site, client PO, contract, methods, codes, scope, acceptance criteria, and safety induction and work permit fields</li><li><strong>Certificates</strong> track every technician's schemes and expiries across mixed crews</li><li><strong>Asset Management</strong> tracks instruments and probes by serial, with issue and return approvals and calibration certificate expiry alerts</li><li><strong>Team Assignments</strong> handle mobilisation and demobilisation dates and block double-booking</li><li><strong>Invoicing</strong> links invoices to the NDT project, job or PO number and site, with labour, equipment and consumable subtotals</li></ul><p>With the report tied to the same job as the timesheet and the invoice, disputes over what was inspected and billed are settled from one record.</p><h2>Featured: Digital Twin Reporting Software</h2><p>Many Gulf owners are running large digital transformation programs, and they increasingly expect contractors to deliver inspection data they can use visually, not only as PDFs.</p><p><a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> is Atlantis NDT's companion product for this. It places inspection results on a 3D model of the asset and works alongside the ERP's NDT Reports app. The ERP handles the job, the data capture, review and approval and the signed report; the digital twin product gives the owner a spatial view of where findings sit.</p><ul><li>Owner inspectors and engineers can locate findings on the model instead of cross-referencing isometrics</li><li>Results from successive shutdowns are easier to compare in place</li><li>It gives a contractor a clear differentiator in technical bid evaluations</li><li>Formal signed reports still come from the ERP, in the owner's template</li></ul><p>The ERP app itself does not build digital twins. The 3D product is scoped separately, and you can request both together.</p><h2>Implementation for Gulf contractors</h2><p>Atlantis NDT deploys and configures the ERP for you. For Middle East customers, setup usually covers:</p><ul><li>Separate versioned templates for each major owner or EPC format you report to</li><li>English and Arabic report layouts where your clients require them</li><li>Numbering per method, and reviewer and approver roles matching your QA plan</li><li>Certificates configured for ASNT, ISO 9712, PCN and CSWIP records, with alert recipients</li><li>VAT on invoices configured for your country, if you take the Invoicing app</li><li>Field app rollout to crew tablets, tested offline before the next shutdown</li></ul><p>Anything owner-specific that is not in the standard app is agreed as customization scope. Explore the other <a href=\"/erp/apps\">ERP apps</a> that connect to reporting. Atlantis NDT ERP is affordable, accessible and fully customizable, and pricing is quote on request: <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20Middle%20East%20quote\">request an NDT Reports quote</a>.</p><h2>Frequently asked questions</h2><h3>Can the software produce reports in Saudi Aramco or ADNOC formats?</h3><p>Yes, by loading those layouts as versioned company templates during implementation. This does not mean any owner has approved or endorsed the software; acceptance of your reports remains between you and your client.</p><h3>Can we track ASNT and ISO 9712 certifications on the same crew?</h3><p>Yes. The Certificates app records SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP and other schemes side by side, with automatic expiry status and alerts.</p><h3>Does it work without signal on remote sites?</h3><p>Yes. The field app works offline, stores drafts and photos on the device and syncs later.</p><h3>Can TPI and owner inspectors sign the report?</h3><p>Yes. The third-party or authorized inspector field records their name and signature, in addition to your inspector, reviewer and approver.</p><h3>Can reports be issued in Arabic?</h3><p>Yes. Arabic or bilingual layouts are loaded as company templates during implementation.</p><h3>Does it handle VAT invoicing?</h3><p>If you take the Invoicing app, VAT is configured locally during implementation using standard Odoo tax settings. We make no certification claims for any e-invoicing regime.</p><h3>Is Digital Twin Reporting Software part of the ERP?</h3><p>No. It is a separate companion product that places inspection results on a 3D model and works alongside NDT Reports.</p><h2>See it before your next shutdown</h2><p>Send us a sample report in the format your main owner requires, and we will show you the same report produced in NDT Reports, from the tablet to the signed PDF. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20Middle%20East%20demo\">Book an NDT Reports demo</a>.</p>\n<h2>NDT Reports by region</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports global overview</a></li><li><a href=\"/erp/apps/ndt-reports/usa\">NDT Reports in United States</a></li><li><a href=\"/erp/apps/ndt-reports/canada\">NDT Reports in Canada</a></li><li><a href=\"/erp/apps/ndt-reports/europe\">NDT Reports in UK &amp; Europe</a></li><li><a href=\"/erp/apps/ndt-reports/india\">NDT Reports in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(Middle%20East)\">Send an enquiry about NDT Reports</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/ndt-reports/india","publishedAt":"2026-09-27","title":"NDT Report Software in India | Atlantis NDT","description":"NDT report software for Indian inspection companies: IBR and PSU refinery work, ASNT and ISO 9712 sign-offs, offline field app. Request a quote.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Reports: NDT Report Software for Inspection Companies in India</h1>\n<p>Method-specific NDT inspection reports, captured in the field and issued from the ERP. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n<p><strong>Featured in NDT Reports:</strong> <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a></p>\n<h2>NDT reporting for Indian inspection companies</h2><p>Indian NDT companies serve a wide mix of clients in the same month: a PSU refinery shutdown, a boiler repair under IBR, a pressure vessel fabricator exporting to Europe or the Gulf, a cross-country pipeline, a thermal power plant overhaul and a shipyard. Each client has its own report format, its own witnessing inspector and its own idea of what counts as a complete record.</p><p>The usual result is a reporting office buried in Word and Excel files, technicians writing readings on paper at site and sending photos over WhatsApp, and reports reaching clients days after the work. When a client or third-party inspection agency queries a result, the evidence is spread across laptops and phones.</p><p>The NDT Reports app in <a href=\"/erp\">Atlantis NDT ERP</a> puts everything on one record. It covers 17 report types, including UT, RT, MT, PT, VT, PAUT, TOFD, PMI, hardness, UT thickness, ferrite, PWHT and computed radiography, each with its own fields and numbering. Every report moves from draft to in progress, review, approved and sent, with inspector, reviewer and approver signatures and a third-party inspector field, and comes out in your own template.</p><h2>ASNT and ISO 9712 certifications on one team</h2><p>Indian technicians commonly hold ASNT SNT-TC-1A-based certifications issued by their employer, ISO 9712 certificates through the Indian Society for Non-Destructive Testing's certification scheme, or both. Many also hold PCN or CSWIP for overseas and offshore work. Clients specify which they accept, and PSU tenders often list the required level and scheme.</p><p>The ERP's Certificates app records each technician's scheme, certifying body, level, method, issue and expiry dates, OJT and training hours, vision tests and attachments. Status is calculated automatically as active, expiring soon, expired or revoked, daily email alerts can go to your QA team, and timesheets warn when a technician's certificate is not valid.</p><p>On the report, the inspector, reviewer and approver sign, and those roles are set to match your written practice. That makes it much harder for a report to go out under the name of a technician whose certificate lapsed last month, because the lapse is visible in the same system.</p><p>Atlantis NDT's <a href=\"/training\">NDT training</a> is based on ASNT SNT-TC-1A for Level I, II and III. We do not train or certify for ISO 9712, PCN or CSWIP; the ERP simply records those certifications when your people hold them.</p><h2>From site to client: the report workflow</h2><p>On most Indian jobs, a report passes through more hands than the technician who made it. The contractor's Level II interprets, the QC engineer or Level III reviews, a TPI agency often witnesses, and the client's engineer accepts. NDT Reports follows that path in five stages:</p><ol><li><strong>Draft</strong>: the report is opened against the work order, with contract, drawing, WPS and procedure references already filled in</li><li><strong>In progress</strong>: the technician records readings, weld lines with defect type and orientation, and photos, usually in the offline field app</li><li><strong>Review</strong>: the reviewer checks technique, coverage, the acceptance standard and the result</li><li><strong>Approved</strong>: the approver signs, and the TPI or authorized inspector's name and signature are captured on the report</li><li><strong>Sent</strong>: the report is issued in the client's template, and the record shows it has gone</li></ol><p>Each report ends with an overall result of acceptable, not acceptable, or acceptable with remarks. The status of every report is visible to the office, so when a site-in-charge calls to ask whether the RT reports for yesterday's joints have gone out, the answer is on screen.</p><p>If a reviewer sends a report back, it returns to the technician with comments instead of getting lost in a phone call. Who may review and approve is set during implementation.</p><h2>IBR boiler work</h2><p>Boiler and steam piping work in India falls under the Indian Boiler Regulations, with inspection by state boiler inspectorates and recognised inspecting authorities. Radiography of boiler tube and header welds, hardness checks after heat treatment, and thickness surveys of tubes and drums are routine, and the inspecting authority's representative often witnesses the NDT or reviews the reports before acceptance.</p><p>NDT Reports suits this work well:</p><ul><li>RT reports record source, technique, and IQI type and placement, with each joint as a weld line carrying defect type and orientation</li><li>PWHT and hardness have their own report types, so heat treatment and hardness records are not squeezed into an RT form</li><li>UT thickness reports record readings by direction for tube and drum surveys during outages</li><li>The third-party or authorized inspector field records the witnessing inspector's name and signature</li><li>WPS, drawing, contract and work order references tie each report to the approved IBR documentation</li></ul><p>IBR documentation formats vary by state and by inspecting authority. Where a specific format is required, it is loaded as a versioned company template during implementation. The app records the data and sign-offs; acceptance under IBR remains with the inspecting authority.</p><h2>PESO, pressure vessels and fabrication for export</h2><p>Pressure vessels for compressed and liquefied gases come under PESO, the Petroleum and Explosives Safety Organisation, through rules such as the Static and Mobile Pressure Vessels (Unfired) Rules. Fabricators in Gujarat, Maharashtra and Tamil Nadu also build to ASME Section VIII and to EN standards for export to Europe and the Gulf.</p><p>For the NDT company, each of those jobs needs a report set that fits into the fabricator's final documentation dossier. NDT Reports records the references a dossier reviewer checks, including the drawing, WPS, procedure and standard, and produces reports in the fabricator's or end client's format using versioned templates. Excel registers, which many fabricators use to summarise every joint, are filled automatically by mapping fields to cells.</p><p>Report types typically used on fabrication jobs:</p><ul><li>RT and CR, UT, PAUT and TOFD for longitudinal and circumferential seams</li><li>MT and PT for nozzle welds, attachments and back-gouged roots</li><li>PMI and ferrite for stainless and alloy vessels</li><li>PWHT and hardness for heat-treated equipment</li></ul><p>The third-party inspector field records the TPI agency's or authorized inspector's name and signature where they witness the NDT, which is standard on export orders.</p><h2>AERB and radiography records</h2><p>Industrial radiography in India is licensed by the Atomic Energy Regulatory Board. Radiography institutions must have an approved radiological safety officer, qualified radiographers, personnel monitoring with TLD badges, and controls over source movement. Those obligations belong to your AERB licence and your radiation protection program.</p><p>NDT Reports makes the technical record complete: the RT report records source, technique, and IQI type and placement, and computed radiography has its own report type and numbering. Around the report, the ERP holds related records:</p><ul><li>Each technician's NDT profile records radiation safety training, radiation badge number and medical fitness expiry</li><li>The Fleet app records whether a vehicle can carry radioactive sources, with transport licence number and expiry</li><li>Project records carry safety induction and work permit fields, which refinery and power plant clients ask for before any exposure</li></ul><p>AERB-mandated registers such as source logs and dose records stay in the systems your licence requires. The value here is that the RT report and the radiographer's qualifications sit in the same place when a client audits you.</p><h2>Refineries, PSU tenders and third-party inspection</h2><p>Refinery and petrochemical work is the backbone of many Indian NDT businesses: Jamnagar, Panipat, Mathura, Kochi, Paradip, Vadinar, Mumbai and Visakhapatnam. PSU work usually comes through tenders from IOCL, BPCL, HPCL, ONGC and GAIL, often with Engineers India or another consultant as PMC, and those tenders set out documentation requirements in detail.</p><p>Tender documents often call for specific report formats, named signatories, witness by a TPI agency and a report register submitted with each bill. NDT Reports helps meet those requirements without adding clerical staff:</p><ul><li>Owner and PMC formats are loaded as versioned company templates</li><li>Each report carries the work order and contract references, so reports can be pulled per work order when billing</li><li>Inspector, reviewer, approver and TPI signatures are captured on the report</li><li>Separate numbering per method keeps registers clean and auditable</li></ul><p>Shutdowns at PSU refineries are intense. The offline field app, the review queue and the Team Assignments app, which blocks double-booking of technicians and equipment serials and warns about out-of-calibration equipment, keep reports moving through a turnaround without the office falling days behind.</p><h2>Power plants, pipelines and shipyards</h2><p>Thermal power stations run by NTPC and state utilities schedule annual and capital overhauls with heavy NDT content: boiler tube thickness surveys, weld RT on replacements, IRIS and eddy current on condenser and heat exchanger tubes, and hardness and PMI on high-temperature piping. Each of these has its own report type in the app.</p><p>Cross-country pipelines and city gas distribution networks generate long runs of weld reports on spreads with patchy coverage. The field app works offline, storing drafts and photos on the device and syncing later, so technicians do not need signal on the right-of-way. Offshore work on the western offshore fields raises the same connectivity issue, and the same answer applies.</p><p>Shipyards and ship repair yards at Kochi, Mumbai, Visakhapatnam and Goa work with class surveyors from the Indian Register of Shipping and international societies. Marine mode adds a vessel cover page with photo, location and dates, and merges the classification-society certificate from a library covering IRS, DNV, ABS, Lloyd's Register, Bureau Veritas, RINA and ClassNK, the inspector's Level II cert and the calibration certificate into the PDF. Photos go in a two-up grid.</p><h2>Connected to crews, equipment and billing</h2><p>In most Indian NDT companies, the report is only one of several records that must agree: the attendance sheet, the equipment issue register, the calibration certificate and the bill. In the ERP they live together:</p><ul><li><strong>Projects</strong> hold the job with site, client PO, contract, methods, codes, scope and acceptance criteria</li><li><strong>Asset Management</strong> tracks every instrument and probe by serial number, with issue and return approvals and calibration certificates with expiry alerts</li><li><strong>Team Assignments</strong> handle crew dispatch, mobilisation and demobilisation dates, and technician availability</li><li><strong>Procedures</strong> keep approved, revision-controlled procedures that reports reference</li><li><strong>Invoicing</strong> links bills to the NDT project, PO and site, with labour, equipment and consumable subtotals</li></ul><p>When a PSU client's billing engineer asks for the reports behind an invoice line, they come from the same job record.</p><h2>Personal data, GST and local setup</h2><p>India's Digital Personal Data Protection Act, 2023 applies to the personal data your company holds about technicians: names, signatures, certification documents, and vision test and medical fitness records. The ERP does not make you compliant on its own, but it helps you keep that data in one controlled place rather than on laptops and phones. Access to certificates, vision tests and reports is set by role during implementation, and hosting location is agreed with you.</p><p>If you also take the Invoicing app, GST is configured locally during implementation using standard Odoo tax settings. Invoice lines can reference the NDT project, job or PO number and site, which helps when a client wants reports and invoices matched line by line.</p><p>Atlantis NDT has a presence in Hyderabad, so implementation and support can run on Indian working hours.</p><h2>Featured: Digital Twin Reporting Software</h2><p>Large Indian refiners and power utilities are investing in digital programs for their plants, and inspection data is a natural fit. Engineers want to see findings on the equipment, not read them from a register.</p><p><a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> is Atlantis NDT's companion product. It places inspection results on a 3D model of the asset and works alongside the ERP's NDT Reports app. NDT Reports handles capture, workflow, sign-off and the formal report; the digital twin product shows the client where each result sits on the asset.</p><ul><li>Plant engineers can review shutdown findings in context</li><li>Results from successive outages are easier to compare</li><li>It helps an NDT company stand out in technical bid evaluation</li><li>Your signed reports still come from the ERP in the client's format</li></ul><p>The ERP app does not build digital twins itself. The 3D product is scoped separately and can be quoted together with NDT Reports.</p><h2>Implementation for Indian NDT companies</h2><p>Atlantis NDT deploys and configures the ERP for you. A typical rollout for an Indian inspection company:</p><ol><li>Collect your report formats by method, plus the formats demanded by your main PSU, IBR and fabrication clients</li><li>Load them as versioned templates, mapping Excel registers field by field</li><li>Set numbering per method, and reviewer and approver roles to match your written practice</li><li>Set up Certificates for ASNT and ISO 9712 records, with alert recipients</li><li>Roll out the field app on site tablets or phones and run a real job offline</li></ol><p>Anything specific to your clients that the standard app doesn't cover is agreed as customization scope. See the other <a href=\"/erp/apps\">ERP apps</a> that connect to reporting. The system is affordable, accessible and fully customizable, and pricing is quote on request: <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20India%20quote\">request an NDT Reports quote</a>.</p><h2>Frequently asked questions</h2><h3>Can the software produce reports in IBR or PSU formats?</h3><p>Yes. Required formats are loaded as versioned company templates during implementation, and Excel formats are filled automatically by mapping fields to cells. Acceptance of the reports remains with the inspecting authority or client.</p><h3>Can we record both ASNT and ISO 9712 certifications?</h3><p>Yes. The Certificates app records both, plus PCN and CSWIP, with level, method and expiry. Atlantis NDT's training covers ASNT SNT-TC-1A only.</p><h3>Does it work on sites without mobile data?</h3><p>Yes. The field app works offline, stores drafts and photos on the device and syncs when a connection is available.</p><h3>Can a TPI agency inspector sign the report?</h3><p>Yes. The third-party or authorized inspector field records their name and signature.</p><h3>Does it handle GST invoicing?</h3><p>If you take the Invoicing app, GST is configured locally during implementation using standard Odoo tax settings. We make no certification claims for any e-invoicing system.</p><h3>Does it manage AERB licensing records?</h3><p>No. AERB licensing, source logs and dose records stay in the systems your licence requires. The RT report records source, technique and IQI details, and employee profiles record radiation safety training and badge numbers.</p><h3>Is Digital Twin Reporting Software part of the ERP?</h3><p>No. It is a separate companion product that places results on a 3D model and works alongside NDT Reports.</p><h2>See your own report in it</h2><p>Send us a sample RT or UT report you issue for a refinery, IBR or fabrication client, and we will show you the same report produced in NDT Reports, from the field app to the signed PDF. <a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20India%20demo\">Book an NDT Reports demo</a>.</p>\n<h2>NDT Reports by region</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports global overview</a></li><li><a href=\"/erp/apps/ndt-reports/usa\">NDT Reports in United States</a></li><li><a href=\"/erp/apps/ndt-reports/canada\">NDT Reports in Canada</a></li><li><a href=\"/erp/apps/ndt-reports/europe\">NDT Reports in UK &amp; Europe</a></li><li><a href=\"/erp/apps/ndt-reports/middle-east\">NDT Reports in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/procedures\">Procedures</a>: Controlled NDT procedures and techniques with revisions and approvals.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=reporting&amp;subject=NDT%20Reports%20demo%20(India)\">Send an enquiry about NDT Reports</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/procedures","publishedAt":"2026-09-27","title":"NDT Procedure Management Software | Atlantis NDT","description":"Write, review, approve and revise NDT procedures in one controlled register with full revision history. Book a demo of the Atlantis NDT ERP Procedures app.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Procedure Management Software: Write, Approve and Control Procedures</h1>\n<p>Controlled NDT procedures and techniques with revisions and approvals. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why NDT procedures slip out of control</h2><p>Every NDT company runs on its procedures. The UT procedure for butt welds, the RT procedure for piping spools, the MT and PT procedures your technicians carry to every shutdown. Auditors ask for them, clients approve them before work starts, and your reports have to quote them by number and revision. Yet in most inspection companies the procedure library lives in a shared drive, a few email threads and the Level III’s laptop.</p><p>That is where the trouble starts. A technician on site opens Rev 3 of a procedure that was replaced by Rev 4 two months ago. A client asks who approved the current PAUT procedure and nobody can find the signed cover page. An auditor asks what changed between revisions and the answer is “let me check with the Level III”. A report goes out quoting a procedure number that no longer exists.</p><p>None of this is about careless people. It is about a document set that changes constantly — new client specifications, new code editions, new equipment, new materials — without one place that says which revision is current, who approved it, and when.</p><p>The Procedures app in the Atlantis NDT ERP gives you that place. It is a controlled procedure register with a proper approval workflow, locked approved revisions and a full revision history, built into the same system that runs your jobs, technicians, equipment and reports. It is affordable, accessible and fully customizable to the way your quality system already works, and Atlantis NDT sets it up for you.</p><h2>What the Procedures app holds</h2><p>Each procedure is a record in a single register, not a loose file. The record carries the information a reviewer, an auditor or a client needs at a glance:</p><ul><li><strong>Document number and revision</strong> — following your own numbering convention, so the procedure listed as UT-004 Rev 2 in the register is the same one quoted on your reports.</li><li><strong>Method</strong> — UT, RT, MT, PT, VT, ET, TOFD, PAUT, leak testing, acoustic emission, hardness, PMI, computed and digital radiography and more.</li><li><strong>Scope</strong> — what the procedure covers: product form, weld configuration, thickness range, new construction or in-service.</li><li><strong>Material</strong> — carbon steel, stainless, duplex, nickel alloys, aluminium, whatever the procedure is written for.</li><li><strong>Applicable standard</strong> — for example ASME Section V, or the client or national standard the procedure implements.</li><li><strong>Acceptance criteria</strong> — the reference for accept and reject, so nobody has to hunt through the body text to find it.</li><li><strong>Body text or uploaded file</strong> — write the procedure directly in the record, or attach the controlled document your Level III already produced.</li></ul><p>Because every procedure sits in one list, you can filter by method, standard or status in seconds. “Show me every approved RT procedure written to ASME Section V” becomes a search, not an afternoon of opening folders. When a client sends a pre-qualification questionnaire asking for your procedure list, you pull it from the register rather than building it by hand.</p><p>The register also answers the question that matters most on site: which revision is current. Only the published revision is the one people should be working to, and the status on the record says so plainly.</p><h2>The approval workflow, step by step</h2><p>A procedure is only worth something once the right people have reviewed and approved it. The app runs every procedure through a defined workflow:</p><ol><li><strong>Draft</strong> — the author writes or uploads the procedure. Nothing in draft is a working document.</li><li><strong>Submitted</strong> — the author submits it for review and the people who need to act are notified by email.</li><li><strong>Reviewed</strong> — the reviewer checks the technical content against the code and the client specification and records the review.</li><li><strong>Approved</strong> — the approver, normally your Level III for that method, approves it. The approved revision is locked.</li><li><strong>Published</strong> — the revision is released as the current working document.</li></ol><p>Two more states cover real life. <strong>Rejected</strong> sends a procedure back with a reason the author can see — “scanning sensitivity section does not reflect the client specification”, for example — instead of a vague comment in a corridor. <strong>Archived</strong> retires procedures you no longer use without deleting them, so the history is still there when an auditor asks about a job from three years ago.</p><p>At each step the record captures who prepared, reviewed and approved the procedure and on which dates. That is the evidence clients and certification auditors ask for: a clear line from author to approver, with dates, for every revision.</p><p>Pending approvals do not sit forgotten. The app sends email notifications and reminders to approvers, which matters when your Level III is on a plane, on a client audit or covering several offices. The procedure waits in the queue and the reminder keeps it visible until someone acts.</p><h2>Revision control that stands up to an audit</h2><p>Procedures change for good reasons. A client issues a new specification. A code edition changes a requirement. You buy a new phased array unit and the set-up changes. A technician finds on site that the scan plan does not work for a nozzle geometry. Each of those changes should produce a new revision, reviewed and approved like the first.</p><p>The Procedures app keeps a full revision history for every procedure, with a snapshot of each revision. When Rev 4 is approved, Rev 3 is not overwritten; it is kept exactly as it was approved. That gives you three things a shared drive cannot:</p><ul><li><strong>Proof of what was in force on a given date.</strong> If a client queries a report from last year, you can show the exact revision the technician worked to.</li><li><strong>A clear view of what changed.</strong> Reviewers and auditors can compare the snapshot of the old revision with the new one instead of trusting a change note.</li><li><strong>No silent edits.</strong> Approved revisions are locked. A change means a new revision going through the workflow, not someone quietly fixing an approved document that clients have already accepted.</li></ul><p>This is the part that usually breaks in small and mid-sized inspection companies. The first version of a procedure is often well controlled. By the fifth revision there are three copies with slightly different content and nobody is sure which one the client approved. Locking approved revisions and keeping snapshots removes that doubt from the start.</p><p>Your document control rules — revision letters or numbers, how a minor editorial change is handled, how long archived revisions are kept — are set up to match your quality manual during implementation.</p><h2>AI-assisted first drafts, with a Level III in charge</h2><p>Writing a procedure from a blank page is slow. The structure is always similar — scope, references, personnel qualification, equipment, calibration, technique, scanning or exposure details, evaluation, acceptance criteria, reporting — but getting all of it down for a new method, material or client specification still takes hours.</p><p>The Procedures app can produce an AI-assisted first draft of a procedure from the details you enter: method, scope, material, applicable standard and acceptance criteria. If the AI service is not available, it falls back to a built-in template, so the author still starts from a proper structure rather than an empty page.</p><p>Be clear about what this is. The AI draft is a starting point for a qualified author. It does not qualify a procedure, it does not approve anything, and it cannot know the details of your equipment, your client’s specification or the component on site. The draft goes through the same workflow as any other procedure: an author edits it, a reviewer checks it, and a Level III reviews and approves it before it is published. Nothing reaches technicians without that sign-off.</p><p>Used that way, the draft takes the typing out of the job and leaves the engineering to the people who carry the responsibility. Your Level III spends their time on the technical content — the technique, the sensitivity, the acceptance criteria — rather than on formatting headings and copying the reference list from the last procedure.</p><p>If you do not have a Level III in-house, or yours is overloaded, Atlantis NDT also offers procedure writing and review as part of its <a href=\"/consulting\">NDT consulting services</a>, carried out by ASNT Level III personnel.</p><h2>Who uses the Procedures app</h2><p>Different people touch procedures for different reasons. Access rights are set up to match those roles.</p><h3>Level III and technical managers</h3><p>They own the technical content. They author or review procedures, approve revisions, reject drafts with a reason, and see every procedure waiting for their decision. Email reminders keep that queue moving when they are travelling.</p><h3>QA/QC and document control</h3><p>They manage the register: numbering, revision rules, archiving and the procedure list sent to clients and auditors. They answer “which revision was in force” questions from the revision history rather than from memory.</p><h3>Operations and project managers</h3><p>They need to know that the procedure for a job is approved and published before the crew mobilises. They find it in the register by method and standard and reference it on the job.</p><h3>Technicians and Level IIs</h3><p>They need the current revision, and only the current revision. Published procedures are the working documents; drafts and archived revisions stay out of their way. Read access for field staff is configured to match how your company issues procedures.</p><h3>Owners and general managers</h3><p>They need confidence that the company will get through a client audit or an ISO 9001 surveillance visit without a scramble. A register with status, approvals and history on every procedure is the answer to that.</p><h2>How Procedures connects to the rest of the ERP</h2><p>A procedure register on its own is useful. Connected to the rest of your operation, it stops being a filing exercise and becomes part of how work gets done. The Procedures app sits inside the <a href=\"/erp\">Atlantis NDT ERP</a> alongside the other NDT apps:</p><ul><li><strong>Projects and tasks.</strong> NDT jobs in the Project app carry methods, codes, scope and acceptance criteria, and each inspection task carries its procedure and WPS references. The procedure the job was planned against is the one the crew works to.</li><li><strong>NDT Reports.</strong> Every report type in the NDT Reports app captures procedure and standard references alongside the work order, WPS and drawing numbers, so the report on the client’s desk quotes the procedure number and revision that was actually used.</li><li><strong>Certificates.</strong> The Certificates app records your technicians’ and Level IIIs’ certifications by scheme, level and method, so you can see who holds a current Level III in the method before you route a procedure to them for approval.</li><li><strong>Quotations.</strong> Quotes record the applicable codes for a job, which is often the first sign that a new or revised procedure is needed before work can start.</li><li><strong>Dashboards.</strong> Procedure status can sit next to calibration due dates and expiring certifications on the KPI dashboards your managers already watch; the exact views are agreed during implementation.</li></ul><p>For clients who want to see inspection results in context, Atlantis also offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model of the asset and works alongside the ERP’s NDT Reports app. You can see the full set of apps on the <a href=\"/erp/apps\">ERP apps overview</a>.</p><h2>Setting it up: what implementation looks like</h2><p>Most NDT companies already have procedures. The job is to bring them under control without stopping work. A typical Procedures implementation with Atlantis NDT runs like this:</p><ol><li><strong>Inventory your current library.</strong> We list what you have: procedure numbers, current revisions, methods, standards and who approved them. Gaps and duplicates usually show up here.</li><li><strong>Agree the rules.</strong> Numbering format, revision convention, who can author, who reviews, who approves for each method, and how archived revisions are kept. These reflect your quality manual and your written practice.</li><li><strong>Load the register.</strong> Existing procedures go in as records with their current revision, method, scope, material, standard and acceptance criteria, with the controlled file attached or the text entered.</li><li><strong>Set up access and notifications.</strong> Roles and approvers are configured, and email reminders are pointed at the right people.</li><li><strong>Run the first revision through the workflow.</strong> Pick a procedure that is due for update and take it from draft to published with your real team. That is where the settings get tested and adjusted.</li><li><strong>Connect it to jobs and reports.</strong> Project tasks and NDT reports reference procedures from the register, so the loop from quote to report is closed.</li></ol><p>Anything specific to your quality system — extra fields a client insists on, a particular cover-page layout, a read-and-acknowledge step for technicians, bilingual versions — is part of the customization scope agreed with you. Pricing is quote on request and depends on the apps and scope you choose.</p><p>If you would like to see the workflow with your own numbering, <a href=\"/contact?service=erp&amp;subject=Procedures%20demo\">book a Procedures demo</a> and bring one of your current procedures along.</p><h2>Procedures, written practice and technique sheets: keeping them straight</h2><p>One common source of audit findings is the difference between documents that all get called “procedures”.</p><ul><li><strong>The written practice</strong> is your company’s document for training, qualifying and certifying NDT personnel, for example under ASNT SNT-TC-1A or CP-189. It governs people, not techniques.</li><li><strong>NDT procedures</strong> describe how a method is applied to a class of work — technique, equipment, calibration, sensitivity, evaluation and acceptance — to meet a code or specification.</li><li><strong>Technique sheets or work instructions</strong> apply a procedure to a specific component or job, with the actual probe angles, exposure arrangement or scan plan.</li></ul><p>All three need control, and all three can be held in the Procedures register, distinguished by a numbering convention agreed during setup, so the relationship is visible: which technique sheets sit under which procedure, and which written practice applies to the people doing the work.</p><p>Keeping them apart matters because they have different approvers and different triggers for revision. A new client specification may force a procedure revision; a new component geometry may need only a new technique sheet; a change in your certification approach touches the written practice. A single register that shows all three, with status and history, lets your Level III see the whole picture. Technician certifications themselves live in the Certificates app, and Atlantis offers SNT-TC-1A-based <a href=\"/training\">NDT training</a> for companies building their Level I and Level II teams.</p><h2>Frequently asked questions</h2><h3>What is NDT procedure management software?</h3><p>It is a system for writing, reviewing, approving, publishing and revising NDT procedures in one controlled place. The Procedures app in the Atlantis NDT ERP holds each procedure with its number, revision, method, scope, material, standard and acceptance criteria, runs it through an approval workflow and keeps a snapshot of every revision.</p><h3>Can we load our existing procedures?</h3><p>Yes. Existing procedures are entered as records with their current revision and either the text or the controlled file attached. Loading your library is part of implementation, so you start with your real register, not an empty one.</p><h3>Does the AI write procedures for us?</h3><p>It writes a first draft only. The AI-assisted draft, or the built-in template if the AI service is unavailable, gives your author a structured starting point. A Level III still reviews and approves every procedure before it is published.</p><h3>Can an approved procedure be edited?</h3><p>No. Approved revisions are locked. Any change creates a new revision that goes through review and approval again, and the previous revision is kept as a snapshot in the history.</p><h3>Who gets told when a procedure needs approval?</h3><p>The approvers. The app sends email notifications and reminders for pending approvals, so a procedure does not sit unapproved while a job waits.</p><h3>We don’t have a Level III on staff. Can you help?</h3><p>Yes. Atlantis NDT offers procedure writing and review by ASNT Level III personnel through its consulting service. The procedures we write can then be loaded and controlled in the Procedures app.</p><h3>Is the Procedures app sold on its own?</h3><p>It is part of the Atlantis NDT ERP and is usually deployed with the other NDT apps, though the scope is up to you. Quotes are on request and based on the apps and customization you need.</p><h2>See it with your own procedures</h2><p>The quickest way to judge the Procedures app is to watch one of your own procedures go through it: loaded into the register, revised, rejected with a reason, corrected, approved, locked and published, with the old revision kept as a snapshot. That takes a short session, and it shows you exactly where your current process has gaps.</p><p>Send us your method mix, how many procedures you control today and who approves them, and we will shape the demo around that. <a href=\"/contact?service=erp&amp;subject=Procedures%20quote\">Request a quote for the Procedures app</a>, or ask for a walkthrough of the full ERP if you want to see how procedures tie into jobs, certificates, equipment and reports.</p>\n<h2>Procedures by region</h2><ul><li><a href=\"/erp/apps/procedures/usa\">Procedures in United States</a></li><li><a href=\"/erp/apps/procedures/canada\">Procedures in Canada</a></li><li><a href=\"/erp/apps/procedures/europe\">Procedures in UK &amp; Europe</a></li><li><a href=\"/erp/apps/procedures/middle-east\">Procedures in Middle East</a></li><li><a href=\"/erp/apps/procedures/india\">Procedures in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Procedures%20demo\">Send an enquiry about Procedures</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/procedures/usa","publishedAt":"2026-09-27","title":"NDT Procedure Management Software USA | Atlantis NDT","description":"Control ASME Section V, API and aerospace NDT procedures with Level III approval workflow and full revision history. Book a demo for your US inspection company.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Procedure Management Software in the USA</h1>\n<p>Controlled NDT procedures and techniques with revisions and approvals. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Procedure control for US inspection companies</h2><p>If you run an NDT company in the United States, your procedures are checked by more people than almost any other document you own. A refinery owner-user on the Houston Ship Channel wants them in the pre-job submittal package. The Authorized Inspector on a Section VIII shop job wants to see the one referenced on the traveller. A pipeline operator’s construction inspector wants the one your crew is actually using on the spread. An aerospace prime’s auditor wants to see who approved it, when, and what changed since the last audit.</p><p>Each of those people is asking the same three questions: is this the current revision, was it approved by someone qualified to approve it, and can you show me the history? When procedures live in a shared drive and email, the honest answer is often “give me an hour”.</p><p>The Procedures app in the Atlantis NDT ERP is built to make that answer immediate. It is a controlled procedure register with a draft, submitted, reviewed, approved and published workflow, locked approved revisions, a snapshot of every revision, and email reminders to approvers. It sits in the same system as your jobs, technician certifications, equipment and reports, so the procedure your Level III approves is the procedure your crews and reports reference.</p><p>This page looks at procedure control through a US lens: the ASME and API codes that dictate procedure content, how Gulf Coast owner-users approve contractor procedures, radiation safety procedures under the NRC and Agreement States, and the extra rigour of aerospace NAS 410 work. Atlantis NDT has its home base in Houston, so these are the conditions we know best.</p><h2>ASME Section V and the codes behind your procedures</h2><p>For most US NDT companies, ASME Boiler and Pressure Vessel Code Section V is the backbone of the procedure library. Article 1 makes the point directly: when the referencing code section requires a written procedure, the examination is performed to that procedure, and where the referencing code calls for it, the procedure is demonstrated to the satisfaction of the Inspector.</p><p>The method articles then set out what the procedure must contain. Article 4 for ultrasonic examination of welds lists procedure requirements as essential and nonessential variables — weld configuration, thickness range, angles, search unit characteristics, instrument, calibration, scanning technique and more. Change an essential variable and the procedure has to be revised and, where required, requalified. Article 2 for radiography, Article 6 for penetrant and Article 7 for magnetic particle each carry their own written procedure requirements.</p><p>The referencing code decides when those procedures are needed and what the acceptance criteria are: Section VIII Division 1 for pressure vessels, Section I for power boilers, ASME B31.3 for process piping, B31.1 for power piping. The same UT technique may carry different acceptance criteria depending on which book the client’s job falls under.</p><p>The Procedures app records exactly that on each procedure: the method, the scope and thickness range, the material, the applicable standard such as ASME Section V, and the acceptance criteria reference. When ASME issues a new edition on its regular publication cycle and a client moves to it, you can filter the register by standard, see every affected procedure, and push each through a new revision with the old one kept as a snapshot.</p><h2>In-service work: API 510, 570, 653 and pipelines</h2><p>A large share of US NDT work is in-service inspection for owner-users running refineries, chemical plants, terminals and pipelines. Here the API inspection codes set the frame: API 510 for pressure vessels, API 570 for piping systems and API 653 for aboveground storage tanks. The owner-user’s inspection programme decides what gets examined, and the NDT contractor supplies procedures that fit the owner’s specifications, which usually sit on top of ASME Section V.</p><p>Pipeline work adds its own layer. API 1104 governs welding of pipelines and related facilities and expects nondestructive testing to follow written procedures, with the operating company able to require the contractor to show that its procedures produce acceptable results. Federal pipeline safety regulations under PHMSA, in 49 CFR Part 192 for gas and Part 195 for hazardous liquids, require nondestructive testing of welds to be performed in accordance with written procedures and by people trained and qualified in those procedures.</p><p>That regulatory line matters. When a PHMSA inspector or an operator’s auditor looks at a weld record, the chain runs from the weld, to the report, to the procedure revision, to the person who performed it. If the procedure revision cannot be produced, the chain breaks.</p><p>The Procedures app keeps that chain intact. Each revision is locked on approval and preserved as a snapshot. The NDT Reports app captures the procedure and standard reference on every report. The Certificates app records the technician’s certification. Together they let you answer the question “which procedure, which revision, which technician” from records, not memory, for jobs on the Gulf Coast, in the Permian or anywhere else your crews travel.</p><h2>How Gulf Coast owner-users approve contractor procedures</h2><p>Anyone who has mobilised a crew into a refinery in Pasadena, Baytown, Beaumont, Lake Charles, Baton Rouge or Corpus Christi knows the routine. Before work starts, the owner-user or the EPC’s document control asks for your procedures. Their inspection group reviews them against the site’s own specifications. Comments come back. You revise and resubmit. Only then does the procedure get the client’s acceptance and your crew can start.</p><p>That routine creates three recurring headaches:</p><ul><li><strong>Client-specific variants.</strong> Your base RT procedure is fine for general work, but one refiner wants a specific IQI placement note and another wants its own acceptance table referenced. Soon you have several near-identical procedures and nobody is sure which one went to which client.</li><li><strong>Comment loops.</strong> Comments arrive in email, get fixed in a Word file, and the history of what was changed in response to which comment disappears.</li><li><strong>Turnaround pressure.</strong> Spring and fall turnaround seasons compress everything. Procedures submitted late hold up mobilisation.</li></ul><p>The app handles these with the features it has. Client variants are separate records with their own numbers, scopes and applicable standards, so the register shows which variant belongs to which client specification. Internal review comments are captured as rejection reasons, so the author sees exactly why a draft came back. Every resubmission is a new revision, and the snapshot of each revision shows what changed. Email reminders chase approvers so a procedure is not the thing holding up a turnaround crew. Tracking of the client’s own acceptance status, such as a transmittal number, can be added as part of the customization scope agreed with you.</p><h2>Radiography: NRC, Agreement States and operating procedures</h2><p>Radiography companies control two kinds of procedures. There are technique procedures for how radiographs are taken and interpreted, and there are radiation safety documents that the regulator requires before a source ever leaves the storage location.</p><p>Under NRC regulations in 10 CFR Part 34, industrial radiography licensees must have operating and emergency procedures covering how sources are handled, used, stored, transported and what happens in an emergency. Most Gulf Coast radiography companies are licensed by an Agreement State rather than by the NRC directly — Texas and Louisiana both run their own programmes with requirements compatible with the federal rules — but the principle is the same: written procedures, kept current, available to workers and inspectors.</p><p>Those documents belong under the same control as your technique procedures. In the Procedures app, radiation safety procedures sit in the register alongside RT and CR/DR technique procedures, with their own numbering, owner and approval chain, and the same locked revisions and history. When the Radiation Safety Officer revises the emergency procedure after a regulator inspection, the change goes through the workflow and the previous revision is preserved.</p><p>Related records live in the right places elsewhere in the ERP. The employee NDT profile in the Certificates app records radiation safety training and radiation badge number. The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry. The Procedures app keeps the written rules those people and vehicles work under.</p><h2>Aerospace: NAS 410 shops and prime specifications</h2><p>Aerospace NDT runs to a stricter rhythm. Personnel are qualified under NAS 410, and the NDT process standards used across the industry — ASTM E1444 for magnetic particle and ASTM E1417 for liquid penetrant are typical examples — require examinations to follow written procedures. Prime contractors layer their own process specifications on top, and some require their approval of a supplier’s procedures or technique sheets before use. Accreditation audits for special processes look hard at procedure control: approval authority, revision status and evidence that the shop floor is using the current revision.</p><p>In an aerospace shop the approver is typically the responsible Level 3 for the method. The Certificates app records that person’s qualification — NAS 410 can be recorded under the “other” scheme with level, method and expiry — so you can see before routing a procedure that the approver’s qualification is current.</p><p>The Procedures app then provides the control auditors want to see: a register with method, scope, material, applicable specification and acceptance criteria; a draft to published workflow with prepared, reviewed and approved by names and dates; approved revisions locked; and a snapshot of each earlier revision. Technique sheets for specific part numbers can be held in the same register under a numbering convention that ties them to the parent procedure.</p><p>Many US NDT companies straddle both worlds, with an industrial field division and an aerospace lab. One register with clear numbering keeps the two libraries apart while giving the quality manager a single view.</p><h2>How the workflow runs in a US shop: a worked example</h2><p>Take a common situation. A refinery client on a B31.3 project wants to use ultrasonic examination instead of radiography on a batch of girth welds to avoid clearing the unit for exposures, and asks for a PAUT procedure that meets its specification.</p><ol><li><strong>Draft.</strong> Your Level II author creates a new procedure record: method PAUT, scope girth welds in the client’s diameter and thickness range, carbon steel, ASME Section V as the applicable standard, with the client’s acceptance criteria referenced. The app produces an AI-assisted first draft from those details, or a built-in template if the AI service is unavailable. The author edits in the specifics of your equipment, focal laws, scan plan and calibration.</li><li><strong>Submitted and reviewed.</strong> The draft is submitted and the reviewer is notified by email. The reviewer finds the encoder and scan-overlap details thin and rejects it, with the reason recorded on the record.</li><li><strong>Revised and approved.</strong> The author fixes the gaps and resubmits. Your Level III for UT, whose current certification is on record in the Certificates app, approves it. The approved revision locks.</li><li><strong>Published.</strong> The procedure goes to the client package, and once the client accepts it, the crew works to it. Project tasks and NDT reports reference it by number and revision.</li></ol><p>Three months later the client revises its specification. The procedure goes through the workflow again as a new revision, and the original is kept as a snapshot, so any report issued under the first revision still points to a procedure you can produce exactly as approved.</p><h2>Connected to certifications, jobs and reports</h2><p>Procedure control is only half the story in a US audit. The other half is showing that the people using the procedure were qualified. The Certificates app records SNT-TC-1A and CP-189 certifications, and ISO 9712, PCN or CSWIP certificates held by technicians who trained elsewhere, with level, method, expiry, OJT and training hours. Expiring and expired certificates are flagged automatically, and timesheets warn when a technician’s certificate is not valid.</p><p>The Project app carries procedure and WPS references on each inspection task, and the NDT Reports app captures procedure and standard references on each of its report types, with inspector, reviewer and approver signatures and a place for the Authorized Inspector or third-party inspector’s name and signature. Put together, the ERP ties the job, the procedure revision, the technician’s certificate and the signed report into one traceable record set. See the full list on the <a href=\"/erp/apps\">ERP apps overview</a>.</p><p>For owner-users who want results in a spatial context, Atlantis offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model of the asset and works alongside the ERP’s NDT Reports app.</p><h2>Implementation and Level III support</h2><p>Implementation starts with your existing library. We list your procedures, revisions, methods and approvers, agree numbering and revision rules that match your quality manual and written practice, load the register, set up approvers and reminders, and run a live revision through the workflow with your team.</p><p>US-specific needs — fields for a client’s transmittal or acceptance status, separate sections for aerospace and industrial libraries, radiation safety documents with their own approval chain — are part of the customization scope agreed with you. The ERP is affordable, accessible and fully customizable, and pricing is quote on request.</p><p>If your procedures themselves need work — an ASME Section V gap review, a new PAUT or TOFD procedure for a client, or a full rewrite before an audit — Atlantis NDT provides procedure writing and review by ASNT Level III personnel through its <a href=\"/consulting\">NDT consulting services</a>. Those procedures can then be controlled in the app from day one. Atlantis also runs SNT-TC-1A-based <a href=\"/training\">NDT training</a> for Level I and Level II technicians.</p><p>Ready to see it? <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20USA\">Book a Procedures demo for your US team</a>.</p><h2>Frequently asked questions</h2><h3>Does the app make our procedures ASME compliant?</h3><p>No software makes a procedure compliant; the content does. The app records the applicable standard and acceptance criteria on each procedure, runs it through Level III review and approval, and keeps every revision, which is the control that code and client audits look for.</p><h3>Can we handle client-specific versions of the same procedure?</h3><p>Yes. Each client variant is its own record with its own number, scope and applicable standard, so the register shows exactly which version goes with which client specification.</p><h3>Where do NRC or state radiation safety procedures go?</h3><p>In the same register, with their own numbering and approval chain. They get the same workflow, locked approved revisions and revision history as technique procedures.</p><h3>Can we record NAS 410 qualifications for aerospace approvers?</h3><p>Yes. The Certificates app records schemes including SNT-TC-1A, CP-189 and ISO 9712, and NAS 410 can be recorded under the “other” scheme with level, method and expiry.</p><h3>How do approvers know something is waiting?</h3><p>They get email notifications and reminders for pending approvals, which helps when your Level III is travelling between sites.</p><h3>Can Atlantis write the procedures as well?</h3><p>Yes. Procedure writing and review by ASNT Level III personnel is available through Atlantis NDT consulting, and the finished procedures are loaded straight into the register.</p><h2>Talk to us</h2><p>Tell us which methods you run, which codes your clients work to and how many procedures you control today. We will show you the register, the approval workflow and the revision history using examples that look like your own library. <a href=\"/contact?service=erp&amp;subject=Procedures%20quote%20USA\">Request a quote for the Procedures app</a> and we will come back with a scope that fits your company.</p>\n<h2>Procedures by region</h2><ul><li><a href=\"/erp/apps/procedures\">Procedures global overview</a></li><li><a href=\"/erp/apps/procedures/canada\">Procedures in Canada</a></li><li><a href=\"/erp/apps/procedures/europe\">Procedures in UK &amp; Europe</a></li><li><a href=\"/erp/apps/procedures/middle-east\">Procedures in Middle East</a></li><li><a href=\"/erp/apps/procedures/india\">Procedures in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(United%20States)\">Send an enquiry about Procedures</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/procedures/canada","publishedAt":"2026-09-27","title":"NDT Procedure Management Software Canada | Atlantis NDT","description":"Control CSA, ABSA and CNSC-driven NDT procedures with Level 3 approval, locked revisions and full revision history. Book a demo for your Canadian NDT company.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Procedure Management Software in Canada</h1>\n<p>Controlled NDT procedures and techniques with revisions and approvals. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Procedure control for Canadian NDT companies</h2><p>Canadian NDT companies work across a patchwork of jurisdictions. A crew might spend spring on an oil sands turnaround north of Fort McMurray, summer on a pipeline spread in northern British Columbia, and autumn at an upgrader in Alberta’s Industrial Heartland or a petrochemical plant in Sarnia. Each owner has its own specifications, each province has its own pressure equipment regulator, and radiography falls under a federal regulator no matter where the job is.</p><p>Procedures sit at the centre of all of it. They have to reflect the right CSA standard and ASME code, satisfy the owner’s integrity or quality group, be approved by someone qualified to approve them, and be the current revision on the day the crew uses them. When procedures live in folders and email chains, that is a lot to hold in one Level 3’s head.</p><p>The Procedures app in the Atlantis NDT ERP gives you one controlled register. Each procedure carries its number, revision, method, scope, material, applicable standard and acceptance criteria. It moves through draft, submitted, reviewed, approved and published, with rejected and archived states, prepared, reviewed and approved by names and dates, approved revisions locked and a snapshot of every revision kept. Approvers get email notifications and reminders so nothing stalls while a crew waits.</p><p>This page looks at what shapes procedure work in Canada: ISO 9712 certification through the NRCan NDT Certification Body, CSA Z662 for pipelines, provincial pressure equipment regulators such as ABSA, CSA W59 structural work, CNSC radiography licensing and Ontario’s nuclear sector.</p><h2>Who writes and approves procedures under CAN/CGSB-48.9712</h2><p>Most Canadian NDT technicians are certified under CAN/CGSB-48.9712, the Canadian adoption of ISO 9712, through the NDT Certification Body at Natural Resources Canada. That scheme shapes who does what with procedures.</p><p>Under the ISO 9712 model, a Level 3 is competent to establish and validate NDT procedures and to take responsibility for them. A Level 2 can translate codes, standards, specifications and procedures into written NDT instructions adapted to the actual working conditions, and can carry out and supervise the work. A Level 1 works to written instructions under supervision. So a Canadian procedure library usually has two tiers: Level 3 procedures, and Level 2 written instructions or technique sheets that apply a procedure to a particular job.</p><p>The Procedures app handles both tiers in one register, separated by a numbering convention agreed during setup so every instruction points back to its parent procedure. The approval chain reflects the tier: a Level 3 approves procedures; instructions follow the review and approval route you define.</p><p>The Certificates app records each person’s certification by scheme, level, method, certifying body and expiry — CGSB/ISO 9712 alongside any ASNT SNT-TC-1A or CP-189 certifications held by staff who have worked for US-owned clients. You can see at a glance whether the Level 3 you are about to route a UT procedure to holds a current Level 3 in UT. Atlantis NDT does not train or certify for CGSB/ISO 9712; the app simply records those certificates. Atlantis’s own <a href=\"/training\">NDT training</a> is based on ASNT SNT-TC-1A.</p><h2>Pipelines: CSA Z662 and operator specifications</h2><p>Pipeline work is a large part of Canadian NDT. CSA Z662, Oil and gas pipeline systems, is the standard behind it, adopted by reference by the Canada Energy Regulator for federally regulated interprovincial lines and by provincial regulators such as the Alberta Energy Regulator for lines inside a province. Z662 requires nondestructive inspection of welds to written procedures by qualified personnel and sets out requirements for radiographic and ultrasonic inspection, including mechanised and automated ultrasonic techniques used on mainline girth welds.</p><p>On top of Z662, each operator has its own welding and NDE specifications. A contractor working for several operators often carries several versions of its radiographic and AUT procedures, each tied to one operator’s specification and qualified on that operator’s project. Operators generally review and accept the contractor’s procedures before production welding starts, and automated UT procedures are often qualified on the project before use.</p><p>That is exactly where uncontrolled copies cause trouble. The Procedures app keeps each operator variant as its own record with its own number, scope, applicable standard and acceptance criteria. Each resubmission after operator comments is a new revision, with the reason for any internal rejection captured on the record and a snapshot of every revision kept.</p><p>When CSA publishes a new edition of Z662 on its periodic cycle and operators adopt it, you filter the register by standard, list every procedure that cites it, and take each through a controlled revision. The procedure used on last year’s spread stays in the history exactly as it was approved, so any integrity query about those welds can be answered with the right document.</p><h2>Pressure equipment: ABSA, TSSA and provincial regulators</h2><p>Pressure equipment in Canada is regulated province by province. In Alberta, ABSA administers the pressure equipment safety legislation, oversees owner-user integrity management programmes and registers designs and quality programmes. In Ontario it is the TSSA; in British Columbia, Technical Safety BC. The national standard CSA B51 covers boilers, pressure vessels and pressure piping and brings the ASME codes into Canadian use, so ASME Section V and the referencing ASME construction codes remain central to NDT procedures for pressure equipment.</p><p>For an NDT company, the effect is layered. Your UT or RT procedure is written to ASME Section V. The acceptance criteria come from the ASME construction code or the owner’s inspection specification. The owner-user, operating under a pressure equipment integrity management programme accepted by the provincial regulator, often reviews your procedures as part of its own quality system, and its auditors expect to see your procedure control.</p><p>In Alberta’s oil sands and upgraders, that owner review usually happens on the way into a turnaround, when dozens of contractors are pushing documents through the same integrity group at once. Getting your procedure package in early, with current revisions and a clear approval record, is how you avoid being the contractor whose crew sits in the laydown yard.</p><p>The Procedures app gives the integrity group what it wants to see: each procedure with its applicable standard and acceptance criteria stated, the names and dates of preparer, reviewer and approver, a locked approved revision, and the history of earlier revisions on request. Tracking the owner’s own acceptance status for each procedure package can be added as part of the customization scope agreed with you.</p><h2>Structural and fabrication work: CSA W59 and CWB-certified shops</h2><p>Structural steel work in Canada runs on CSA W59, Welded steel construction, with fabricators certified by the Canadian Welding Bureau under CSA W47.1 and welding inspection organisations under CSA W178.1. When your technicians inspect welds in a fabrication shop or on a building, bridge or industrial structure, the acceptance criteria usually come from W59 rather than from the American structural code, even when the fabricator also works to US contracts.</p><p>That difference is easy to lose in a procedure library that grew from US templates. A UT procedure written for one structural code does not automatically carry the right acceptance criteria for W59 work, and an auditor will spot it.</p><p>In the Procedures app, the applicable standard and acceptance criteria are explicit fields on each procedure, so you can filter the register and see which procedures are written for W59 and which are not. Where you need a W59-specific version, it becomes its own record, drafted — with the AI-assisted first draft if you like — reviewed and approved by your Level 3, and published only when it is right.</p><p>Fabricators who carry CWB certification also value a supplier who can show procedure control. When the fabricator’s quality manager asks which revision of your MT procedure applies to their job, you can answer from the register in seconds.</p><h2>Radiography under the CNSC</h2><p>Industrial radiography in Canada is federally regulated by the Canadian Nuclear Safety Commission, regardless of province. Companies using exposure devices hold a CNSC licence, run a radiation protection programme, and use Certified Exposure Device Operators. The licence and programme rely on written procedures for the use, storage, transport and emergency handling of sources, and CNSC inspectors check that those procedures are current and followed. Transport also brings in the Packaging and Transport of Nuclear Substances Regulations and Transport Canada’s transportation of dangerous goods rules.</p><p>Radiation protection procedures deserve the same control as your technique procedures. In the Procedures app they sit in the same register with their own numbering and approval chain — typically the Radiation Safety Officer and management — and the same locked approved revisions and revision history. After a CNSC inspection leads to a change, the revision goes through the workflow and the old version is preserved as a snapshot.</p><p>Other records live where they belong. The employee NDT profile in the Certificates app records radiation safety training, radiation badge number and medical fitness expiry, and exposure device operator certification can be recorded as a certificate with its expiry so it is flagged before it lapses. The Fleet app records whether each vehicle can carry radioactive sources, with transport licence number and expiry. The Procedures app holds the written rules everyone works to.</p><h2>Nuclear work in Ontario</h2><p>Ontario’s CANDU stations and the supply chain around them set some of the strictest documentation expectations in Canadian NDT. Periodic inspection programmes for nuclear power plant components follow CSA N285.4, and suppliers work under nuclear quality assurance requirements such as CSA N299, which place firm expectations on document control, approval and revision.</p><p>Inspection procedures for nuclear work are commonly reviewed and accepted by the licensee before use, sometimes after technique qualification. Every revision, every reviewer comment and every approval date can become the subject of an audit question years later.</p><p>The Procedures app supports that discipline with the controls it has: a single register, a defined workflow with named preparer, reviewer and approver and dates, rejection with a recorded reason, approved revisions locked against edits, a full revision history with a snapshot of each revision, and archived procedures kept rather than deleted. Nuclear-specific extras — additional sign-off steps, fields for the licensee’s acceptance reference, stricter access rules — are part of the customization scope agreed with you.</p><h2>English and French procedure sets</h2><p>Companies working in Quebec, or for federally regulated clients who want documents in both official languages, often maintain procedures in English and French. The risk is obvious: the English version gets revised and the French one does not, and the two drift apart.</p><p>In the Procedures app, a French version can be held as its own controlled record, numbered so the pairing is clear, or attached as a controlled file to the same record. Either way it goes through review and approval, and the revision history shows whether both language versions were brought up to the same revision. The exact arrangement is agreed during implementation to match how your clients want bilingual documents handled.</p><h2>Connected to the rest of the ERP</h2><p>The Procedures app is one part of the <a href=\"/erp\">Atlantis NDT ERP</a>. Project tasks carry procedure and WPS references, so each job points to the procedure it runs under. The NDT Reports app captures procedure and standard references on every report type, alongside inspector, reviewer and approver signatures and the third-party inspector’s name. The Certificates app shows whether the people doing the work hold valid certifications, and timesheets warn when they do not.</p><p>For owners who want inspection results on the asset itself, Atlantis offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model and works alongside the ERP’s NDT Reports app.</p><h2>Implementation and Level 3 support</h2><p>Implementation starts with your current library: procedure numbers, revisions, methods, the standards each one cites, and who approved them. We agree numbering, revision rules and approval routes — by method, and separately for radiation protection documents — then load the register, set up approvers and reminders, and run one real revision through the workflow with your team. Anything specific to your clients or provinces is part of the agreed customization scope. The ERP is affordable, accessible and fully customizable, with pricing on request.</p><p>If your procedures need rewriting — a Z662 operator variant, a W59-specific UT procedure, or a gap review before an owner audit — Atlantis NDT offers procedure writing and review by ASNT Level III personnel through its <a href=\"/consulting\">NDT consulting services</a>. Where your client requires CGSB Level 3 approval, your own certified Level 3 stays the approver. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20Canada\">Book a Procedures demo for your Canadian team</a>.</p><h2>Frequently asked questions</h2><h3>Can the app record CGSB / ISO 9712 certifications?</h3><p>Yes. The Certificates app records ISO 9712 alongside SNT-TC-1A, CP-189, PCN and CSWIP, with level, method, certifying body and expiry. Atlantis records these certificates but does not train or certify for them.</p><h3>Can we keep separate procedures for each pipeline operator?</h3><p>Yes. Each operator variant is its own record with its own number, applicable standard and acceptance criteria, and its own revision history.</p><h3>Where do CNSC radiation protection procedures go?</h3><p>In the same register, with their own numbering and approval chain, locked approved revisions and full revision history.</p><h3>Does the AI draft replace our Level 3?</h3><p>No. The AI-assisted draft, or the built-in template if AI is unavailable, is only a starting point. Your Level 3 reviews and approves before anything is published.</p><h3>Can we run English and French versions?</h3><p>Yes, as paired records or controlled attachments, set up during implementation so both versions follow the same revision control.</p><h3>What happens to old revisions?</h3><p>They are kept as snapshots in the revision history, and retired procedures are archived, not deleted.</p><h2>Talk to us</h2><p>Tell us where your crews work, which owners and operators you serve and how many procedures you control today. We will show you the register and workflow using examples that look like your own library, from a Z662 AUT procedure to a CNSC emergency procedure. <a href=\"/contact?service=erp&amp;subject=Procedures%20quote%20Canada\">Request a quote for the Procedures app</a>.</p>\n<h2>Procedures by region</h2><ul><li><a href=\"/erp/apps/procedures\">Procedures global overview</a></li><li><a href=\"/erp/apps/procedures/usa\">Procedures in United States</a></li><li><a href=\"/erp/apps/procedures/europe\">Procedures in UK &amp; Europe</a></li><li><a href=\"/erp/apps/procedures/middle-east\">Procedures in Middle East</a></li><li><a href=\"/erp/apps/procedures/india\">Procedures in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(Canada)\">Send an enquiry about Procedures</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/procedures/europe","publishedAt":"2026-09-27","title":"NDT Procedure Management Software UK & Europe | Atlantis NDT","description":"Control EN ISO NDT procedures and written instructions with Level 3 approval, locked revisions and full history. Book a demo for your UK or EU NDT company.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Procedure Management Software for the UK and Europe</h1>\n<p>Controlled NDT procedures and techniques with revisions and approvals. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Procedure control for UK and European NDT companies</h2><p>NDT companies in the UK and Europe work under a dense layer of harmonised standards, third-party oversight and client technical authorities. A company in Aberdeen may be running inspection campaigns for North Sea duty holders one month and supporting a pressure vessel fabricator on Teesside the next. A Dutch or Belgian contractor may work in the Rotterdam and Antwerp petrochemical clusters for owners who expect procedures in English and the local language. A German shop may build equipment under the Pressure Equipment Directive with a notified body looking over its shoulder.</p><p>In every case the same questions come up. Which EN ISO standard does this procedure implement? Which acceptance level applies? Who approved it, and are they a certified Level 3 in that method? Is the written instruction the technician is holding derived from the current procedure revision? When the answers depend on searching network folders, audits get uncomfortable.</p><p>The Procedures app in the Atlantis NDT ERP gives you a single controlled register. Each procedure has a document number, revision, method, scope, material, applicable standard and acceptance criteria, with body text or an uploaded file. It moves through draft, submitted, reviewed, approved and published, with rejected and archived states; preparer, reviewer and approver names and dates are recorded; approved revisions are locked; and a snapshot of every revision is kept. Approvers receive email notifications and reminders for pending approvals.</p><p>This page looks at how that fits European practice: the EN ISO 9712 split between procedures and NDT instructions, the EN ISO technique and acceptance standards, the Pressure Equipment Directive, North Sea offshore work, UK radiation rules and GDPR.</p><h2>Procedures and NDT instructions under EN ISO 9712</h2><p>European certification under EN ISO 9712 — whether through a national scheme or PCN, run by BINDT in the UK — draws a clear line between two kinds of document. A Level 3 can establish and validate NDT procedures and interpret codes, standards and specifications. A Level 2 can translate those codes, standards, specifications and procedures into NDT instructions adapted to the actual working conditions. A Level 1 carries out work to written instructions under supervision.</p><p>That means a well-run European NDT library has two tiers. The procedure states how a method is applied to a class of work to meet a standard. The NDT instruction applies it to a specific component, weld or campaign: this probe, this scanning pattern, this exposure arrangement, these recording levels.</p><p>Auditors look at both, and at the link between them. An instruction derived from a superseded procedure is a finding even if the instruction itself looks fine.</p><p>The Procedures app holds both tiers in the same register, separated by a numbering convention agreed during setup so every instruction points to its parent procedure. Approval routes reflect the tier: procedures go to the Level 3 for the method; instructions follow the review and approval route you define for Level 2 authors.</p><p>The Certificates app records each person’s EN ISO 9712 or PCN certification by level, method, industry sector, certifying body and expiry, alongside any ASNT or CSWIP certificates. You can confirm the approver’s Level 3 is current before routing. Atlantis NDT does not provide EN ISO 9712 or PCN training or certification; the app records these certificates. Atlantis’s own training is based on ASNT SNT-TC-1A.</p><h2>The EN ISO standards stack behind your procedures</h2><p>European weld inspection procedures are built on a family of technique standards and a matching family of acceptance-level standards. Typical examples:</p><table><thead><tr><th>Method</th><th>Technique standard</th><th>Acceptance levels</th></tr></thead><tbody><tr><td>UT of welds</td><td>EN ISO 17640</td><td>EN ISO 11666</td></tr><tr><td>RT of welds</td><td>EN ISO 17636-1 (film), EN ISO 17636-2 (digital)</td><td>EN ISO 10675-1</td></tr><tr><td>MT of welds</td><td>EN ISO 17638</td><td>EN ISO 23278</td></tr><tr><td>PT</td><td>EN ISO 3452-1</td><td>EN ISO 23277</td></tr><tr><td>VT of welds</td><td>EN ISO 17637</td><td>EN ISO 5817 quality levels</td></tr><tr><td>PAUT of welds</td><td>EN ISO 13588</td><td>EN ISO 19285</td></tr><tr><td>TOFD</td><td>EN ISO 10863</td><td>EN ISO 15626</td></tr></tbody></table><p>The link runs through EN ISO 5817 quality levels: the design specifies a quality level for the weld, and that decides which testing level and acceptance level apply. Get the pairing wrong in a procedure and every report written under it is open to challenge.</p><p>The Procedures app makes the pairing explicit. Each procedure record carries the applicable standard and the acceptance criteria as separate fields, so a reviewer sees at once that a UT procedure cites EN ISO 17640 with EN ISO 11666 acceptance, and at which level. You can filter the register by standard to answer questions like “which procedures still cite the superseded edition?” When ISO or CEN revise one of these standards, each affected procedure goes through a controlled revision and the previous revision is kept as a snapshot.</p><h2>Pressure Equipment Directive and notified bodies</h2><p>For companies supporting manufacturers of pressure equipment, the Pressure Equipment Directive 2014/68/EU sets the frame. Its essential safety requirements expect non-destructive tests of permanent joints to be carried out by suitably qualified personnel, and for equipment in categories III and IV that personnel must be approved by a third-party organisation recognised by a member state. The harmonised product standards — EN 13445 for unfired pressure vessels and EN 13480 for metallic industrial piping, with their inspection and testing parts — specify the extent of NDT and point to the EN ISO technique and acceptance standards.</p><p>Notified bodies reviewing a manufacturer’s documentation, and witnessing tests, look at the NDT procedures used. They expect to see which standard each procedure implements, that it was approved by a competent Level 3, and that the version used on the equipment was the version approved.</p><p>In Great Britain the equivalent regime is the Pressure Equipment (Safety) Regulations 2016 with UK approved bodies, while CE marking under the Directive continues to matter for equipment shipped into the EU and, under the Windsor Framework arrangements, Northern Ireland. Many UK companies therefore keep procedures that must satisfy both routes.</p><p>The Procedures app keeps that manageable. The applicable standard field tells you which regime and product standard a procedure serves, the approval record shows who signed it off and when, approved revisions cannot be quietly edited, and the snapshot of each revision lets you show a notified body or approved body exactly what was in force when the equipment was tested. Fields for a notified body’s review reference can be added as part of the customization scope agreed with you.</p><h2>North Sea offshore and Aberdeen</h2><p>Offshore inspection in the UK and Norwegian sectors runs through duty holders’ technical authorities. Before a campaign, the NDT contractor’s procedures are normally reviewed by the operator’s inspection or materials technical authority against the operator’s own specifications, and on the Norwegian side often against NORSOK standards such as M-601 for welding and inspection of piping. The operator’s verification scheme and the UK HSE’s offshore safety case regime sit in the background, and both expect contractors to work to controlled, approved documents.</p><p>Offshore work also brings practical constraints. Bed space is tight, so the technician offshore may be the only NDT person on the installation. Communication with the onshore Level 3 happens by email or a call on a fixed schedule. Campaigns run to fixed windows, and a procedure waiting for approval can cost a campaign slot.</p><p>The Procedures app helps with the parts it controls. Each operator’s procedure variant is its own record, numbered so the pairing with the operator specification is obvious. Technical authority comments are addressed in a new revision, internal rejections carry their reason on the record, and the snapshot of every revision shows how the procedure evolved to meet the operator’s requirements. Email reminders keep approvals moving when the Level 3 is travelling between Aberdeen, Stavanger and client offices. When the campaign ends, the reports written offshore reference a procedure revision you can produce exactly as approved.</p><h2>UK radiography: IRR17 and local rules</h2><p>Site radiography in the UK sits under the Ionising Radiations Regulations 2017. Employers working with ionising radiation must register with or obtain consent from HSE depending on the risk, take advice from a Radiation Protection Adviser, appoint Radiation Protection Supervisors and have written local rules for the work, plus contingency plans for foreseeable incidents. Similar requirements apply across the EU through national rules implementing the Euratom Basic Safety Standards Directive.</p><p>Local rules and contingency plans are controlled documents in their own right. They change when the RPA advises, when a site’s arrangements change, or after an incident review, and inspectors will check that the version on site is current.</p><p>In the Procedures app, local rules and radiation contingency plans can sit in the same register as your RT and CR/DR technique procedures, with their own numbering and approval chain — typically the RPS, the RPA’s input and management approval — and the same locked revisions and history. Personnel records sit elsewhere: the employee NDT profile in the Certificates app records radiation safety training, radiation badge number and medical fitness expiry, and the Fleet app records which vehicles can carry radioactive sources, with transport licence number and expiry.</p><h2>GDPR and approval records</h2><p>Procedure control involves personal data, though less than people fear. The procedure record stores the names of the preparer, reviewer and approver and the dates they acted, which is exactly what your quality system requires you to keep. The heavier personal data — certificates, vision tests, medical fitness, radiation badge numbers — lives in the Certificates app and employee records, not in the procedure register.</p><p>GDPR still applies to both. During implementation we agree who can see what, so field technicians see published procedures without seeing colleagues’ certification or medical details, and we agree how long archived revisions and their approval records are kept, in line with your retention policy and client contract terms. Hosting arrangements for the ERP are also agreed as part of implementation. Your data protection responsibilities stay with you as controller; the setup is designed to support them.</p><h2>Multilingual procedure sets</h2><p>Across Europe, procedures often exist in more than one language: English for international operators and EPCs, plus German, Dutch, French, Norwegian or another language for local crews and national authorities. The classic failure is a revision made in one language and forgotten in the other.</p><p>In the Procedures app, each language version can be held as its own controlled record numbered to show the pairing, or attached as a controlled file to the same record. Either way it passes through review and approval, and the revision history makes a mismatch visible. The arrangement is agreed during implementation to fit how your clients and authorities want translated procedures handled.</p><h2>Connected to the rest of the ERP</h2><p>The Procedures app is part of the <a href=\"/erp\">Atlantis NDT ERP</a>. Project tasks carry procedure and WPS references. The NDT Reports app captures procedure and standard references on every report type, with inspector, reviewer and approver signatures and a field for the third-party inspector. In marine mode, reports can merge the classification society certificate, the inspector’s Level 2 certificate and the calibration certificate into the PDF. The <a href=\"/erp/apps\">full list of ERP apps</a> shows how certificates, equipment, assignments and invoicing link in.</p><p>For owners and duty holders who want results in context, Atlantis offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model of the asset and works alongside the ERP’s NDT Reports app.</p><h2>Implementation and Level 3 support</h2><p>We start from your current library: procedures, NDT instructions, the EN ISO standards they cite, their revisions and approvers. We agree numbering, revision and approval rules that match your quality manual and your certification scheme, load the register, configure approvers and reminders, and run a live revision through the workflow with your team. The ERP is affordable, accessible and fully customizable, with pricing on request.</p><p>Where procedures need writing or review — a gap review against the current EN ISO editions, a new PAUT procedure for an operator, or a clean-up before a notified body visit — Atlantis NDT offers procedure writing and review by ASNT Level III personnel through its <a href=\"/consulting\">NDT consulting services</a>. Where your client or scheme requires approval by an EN ISO 9712 or PCN Level 3, your certified Level 3 remains the approver. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20UK%20Europe\">Book a Procedures demo for your UK or European team</a>.</p><h2>Frequently asked questions</h2><h3>Can we hold both procedures and NDT instructions?</h3><p>Yes. Both sit in the same register, separated by a numbering convention that links each instruction to its parent procedure, with approval routes set per tier.</p><h3>Does the app record PCN and EN ISO 9712 certificates?</h3><p>Yes, in the Certificates app, with level, method, sector, certifying body and expiry. Atlantis records these certificates but does not train or certify for them.</p><h3>Can we see which procedures cite a superseded standard?</h3><p>Yes. The applicable standard is a field on every procedure, so you can filter the register and take each affected procedure through a controlled revision.</p><h3>Where do IRR17 local rules go?</h3><p>In the same register, with their own numbering, approval chain, locked approved revisions and revision history.</p><h3>How is GDPR handled?</h3><p>Access rights and retention periods are agreed during implementation so people see only what they need and approval records are kept only as long as your policy requires.</p><h3>Is the AI draft a substitute for a Level 3?</h3><p>No. It is a first draft, or a built-in template if the AI service is unavailable. A Level 3 reviews and approves before anything is published.</p><h2>Talk to us</h2><p>Tell us where you work — offshore, shop fabrication, petrochemical sites — which standards your clients specify and how many procedures and instructions you control. We will show you the register and workflow with examples that look like your own library. <a href=\"/contact?service=erp&amp;subject=Procedures%20quote%20UK%20Europe\">Request a quote for the Procedures app</a>.</p>\n<h2>Procedures by region</h2><ul><li><a href=\"/erp/apps/procedures\">Procedures global overview</a></li><li><a href=\"/erp/apps/procedures/usa\">Procedures in United States</a></li><li><a href=\"/erp/apps/procedures/canada\">Procedures in Canada</a></li><li><a href=\"/erp/apps/procedures/middle-east\">Procedures in Middle East</a></li><li><a href=\"/erp/apps/procedures/india\">Procedures in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(UK%20%26%20Europe)\">Send an enquiry about Procedures</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/procedures/middle-east","publishedAt":"2026-09-27","title":"NDT Procedure Management Software Middle East | Atlantis NDT","description":"Control Aramco, ADNOC and QatarEnergy-bound NDT procedures with Level III approval, locked revisions and full history. Book a demo for your Gulf NDT company.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Procedure Management Software in the Middle East</h1>\n<p>Controlled NDT procedures and techniques with revisions and approvals. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Procedure control for NDT companies in the Gulf</h2><p>NDT companies in the Gulf work for some of the most document-heavy clients in the industry. A contractor based in Dammam or Al Khobar may have crews in Jubail and Ras Tanura for Saudi Aramco-related work, a team on a turnaround in Ruwais, and another mobilising to Ras Laffan or Mesaieed in Qatar or to the Ahmadi refineries in Kuwait. Every one of those owners has its own engineering standards, its own contractor approval process and its own view of what a good NDT procedure looks like.</p><p>That makes the procedure library the hardest-working document set in the company. The same RT procedure may exist in three client versions. A PAUT procedure may be approved for one project and still under comment on another. The Level III who approves them may be on site, in another country or covering several companies’ work. And turnaround season compresses all of it into a few frantic weeks.</p><p>The Procedures app in the Atlantis NDT ERP gives you one controlled register for all of it. Each procedure carries its document number, revision, method, scope, material, applicable standard and acceptance criteria. It moves through draft, submitted, reviewed, approved and published, with rejected and archived states. Preparer, reviewer and approver names and dates are recorded, approved revisions are locked, a snapshot of every revision is kept, and approvers get email notifications and reminders.</p><p>This page looks at what drives procedure work in Saudi Arabia, the UAE, Qatar and Kuwait: client standards and contractor approval, the mix of ASME, API and EN ISO codes, radiation regulators, turnaround pressure and multinational crews. The owners and regulators named here are context for your work, not Atlantis customers.</p><h2>Saudi Aramco work: SAES standards and procedure review</h2><p>Work in the Saudi Aramco sphere runs on its engineering standards. The SAES-W welding standards define the NDT required for on-plot piping, pipelines, pressure vessels and other equipment, and they sit on top of the international codes rather than replacing them. Contractors and their NDT subcontractors typically submit NDT procedures for review by the client’s inspection organisation before use on a project, and the inspection checklists and report forms used on projects expect the procedure to be referenced.</p><p>In practice this means your Aramco-bound procedures look different from your general procedures. They cite the relevant SAES alongside ASME Section V, they carry the client’s acceptance criteria where these differ from the construction code, and they are revised whenever the client revises the standard they rely on. A procedure that was accepted two years ago may no longer match the current standard, and the reviewer will notice.</p><p>The Procedures app keeps those versions apart and under control. Each client-specific procedure is its own record, with the applicable standard and acceptance criteria stated in their own fields, so you can filter the register and see every procedure that cites a given SAES. When the standard changes, each affected procedure goes through a new revision, and the snapshot of the earlier revision shows exactly what the client accepted before.</p><p>Tracking the client’s own review status and transmittal reference for each submission is not built in, but it can be added as part of the customization scope agreed with you, so your document controller sees in one place what has been submitted, what came back with comments and what was accepted.</p><h2>ADNOC, QatarEnergy and KNPC projects</h2><p>Across the rest of the Gulf the pattern is similar with different details. ADNOC group companies in Abu Dhabi, QatarEnergy and its operating affiliates in Qatar, and KNPC in Kuwait each work to their own engineering specifications, maintain approved vendor or contractor lists and expect procedures to be submitted and accepted before work starts. Much of the capital project work is executed by international EPC contractors, so your procedures often travel through the EPC’s document control first, come back with comment codes, and are resubmitted before they ever reach the owner.</p><p>A typical NDT company in the region ends up with a base procedure per method plus a set of client and project variants. The variants differ in small but important ways: a specific IQI placement, a different acceptance table, a required extent of examination, an extra reporting requirement. Small differences are exactly what goes wrong when variants are managed as copies of a Word file.</p><p>In the Procedures app, each variant is its own record, numbered so its client or project is clear. Internal review comments become rejection reasons on the record, so the author knows exactly what to fix before the EPC sees it. Each resubmission is a new revision with a snapshot, so you can show the owner what changed in response to its comments. Email reminders keep internal approvals moving so your submission does not become the item holding up a project schedule.</p><h2>The codes underneath: ASME, API and EN ISO</h2><p>Under the client standards, Gulf procedures mostly rest on American codes. ASME Section V sets the procedure requirements for each method. ASME Section VIII and B31.3 provide acceptance criteria for pressure vessels and process piping. API 1104 governs pipeline welding and NDT. API 650 and API 653 cover storage tanks, and API 510 and 570 frame in-service inspection of vessels and piping. On projects designed by European EPCs, EN ISO technique and acceptance standards appear as well, sometimes on the same site.</p><p>That mix is why the applicable standard and acceptance criteria fields matter. A reviewer looking at a UT procedure needs to know immediately whether it is written to ASME Section V with B31.3 acceptance, to a client SAES with its own table, or to EN ISO 17640 with EN ISO 11666 acceptance. The register shows it on the record rather than on page six of the document.</p><p>Certification is mixed too. Gulf crews commonly hold ASNT-based certifications under an employer’s SNT-TC-1A written practice, ASNT central certifications, or ISO 9712 certifications from schemes in their home countries, and clients may have their own qualification or testing requirements for NDT personnel. The Certificates app records all of these by scheme, level, method, certifying body and expiry, so you can confirm that the Level III approving a procedure holds a current certificate in that method before you route it.</p><h2>Radiography regulators and radiation procedures</h2><p>Industrial radiography in the Gulf is licensed nationally. In Saudi Arabia the Nuclear and Radiological Regulatory Commission licenses radiation practices; in the UAE it is the Federal Authority for Nuclear Regulation; Qatar and Kuwait have their own national radiation protection authorities. Each expects licensees to operate under a radiation protection programme with written procedures for source use, storage, transport and emergencies, and each can inspect.</p><p>On Gulf sites radiography is often done at night or in restricted windows to keep congested plants working during the day, which raises the stakes on barrier, signage and emergency procedures being current and understood. Owners and EPCs frequently ask to see radiation procedures as part of the contractor’s submission as well.</p><p>In the Procedures app, radiation protection procedures sit in the same register as RT, CR and DR technique procedures, with their own numbering and approval chain — the radiation protection officer plus management — and the same locked revisions and revision history. When the regulator or a client audit leads to a change, the revision goes through the workflow and the previous version is preserved.</p><p>Supporting records live elsewhere in the ERP. The employee NDT profile records radiation safety training, radiation badge number and medical fitness expiry. The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry, which helps when sources move between Eastern Province sites or across borders.</p><h2>Turnaround and shutdown season</h2><p>Shutdown and turnaround seasons in the Gulf concentrate a year’s worth of procedure activity into a few weeks. Owners publish scopes late, EPCs and maintenance contractors ask for procedures for methods and components you did not quote for, and your Level III is suddenly the bottleneck for half the company.</p><p>The Procedures app cannot make the season quieter, but it removes the avoidable delays:</p><ul><li><strong>Faster first drafts.</strong> The AI-assisted first draft, or the built-in template if the AI service is unavailable, gives the author a structured starting point for a new method or component. The Level III still reviews and approves.</li><li><strong>Visible queues.</strong> Everything waiting for review or approval is visible in one place, and email reminders go to approvers until they act.</li><li><strong>No confusion about what is current.</strong> Only published revisions are working documents. Approved revisions are locked, so nobody edits an accepted procedure the night before mobilisation.</li><li><strong>Clean history afterwards.</strong> When the shutdown is over and a client queries a report, the snapshot of the revision used is there.</li></ul><p>Link that with the Team Assignments app, which blocks double-booking of technicians and equipment and warns when assigned equipment is out of calibration, and the crew that mobilises has the right people, the right kit and the right procedure revision.</p><h2>Multinational crews and bilingual documents</h2><p>Gulf NDT crews are multinational. A single team may include technicians from India, Pakistan, the Philippines, Egypt and elsewhere, with a Level III from yet another country. English is the working language of procedures, but clarity matters more than it does with a crew that shares a first language. Some clients and authorities also ask for Arabic versions of particular documents, especially radiation safety and emergency material.</p><p>Two things help. First, procedures that are clear and consistent across clients: the register makes it easy to compare variants and keep the base procedure clean. Second, controlled language versions: an Arabic version can be held as its own record, numbered to show the pairing, or as a controlled attachment, and it passes through review and approval like the English original. Whether you also want a step where technicians confirm they have read a procedure before mobilising is part of the customization scope agreed with you.</p><p>Personnel paperwork tied to residence permits and visas is handled in the employee records, not the procedure register, keeping the procedure library focused on technical content.</p><h2>Connected to the rest of the ERP</h2><p>The Procedures app is part of the <a href=\"/erp\">Atlantis NDT ERP</a>. Project tasks carry procedure and WPS references. The NDT Reports app captures procedure and standard references on each report type, with inspector, reviewer and approver signatures and the third-party inspector’s name and signature, so the report the client receives quotes the exact procedure revision used. The Certificates app flags expiring and expired certificates and timesheets warn when a technician’s certificate is not valid.</p><p>For owners who want inspection results on the asset itself, Atlantis offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model of the asset and works alongside the ERP’s NDT Reports app.</p><h2>Implementation and Level III support</h2><p>We start from your existing library and client list: base procedures, client and project variants, radiation procedures, the standards each cites and who approved them. We agree numbering that makes the client pairing obvious, set approval routes by method, load the register, configure reminders, and run a live revision with your team. VAT and other local invoicing settings in the wider ERP are configured for your country during implementation. The ERP is affordable, accessible and fully customizable, with pricing on request.</p><p>If your procedures need rewriting for a client standard, or you need a new PAUT or TOFD procedure ahead of a shutdown, Atlantis NDT offers procedure writing and review by ASNT Level III personnel through its <a href=\"/consulting\">NDT consulting services</a>. Atlantis also offers SNT-TC-1A-based <a href=\"/training\">NDT training</a> for companies building Level I and Level II capability. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20Middle%20East\">Book a Procedures demo for your Gulf team</a>.</p><h2>Frequently asked questions</h2><h3>Can we keep separate procedures for Aramco, ADNOC and other clients?</h3><p>Yes. Each client or project variant is its own record with its own number, applicable standard, acceptance criteria and revision history.</p><h3>Can we track client comments and resubmissions?</h3><p>Each resubmission is a new revision with a snapshot, and internal rejections carry their reason. Tracking the client’s review status and transmittal reference can be added in the agreed customization scope.</p><h3>Does the app record both ASNT and ISO 9712 certificates?</h3><p>Yes. The Certificates app records SNT-TC-1A, CP-189, ISO 9712, PCN, CSWIP and other schemes, with level, method and expiry.</p><h3>Where do radiation protection procedures go?</h3><p>In the same register, with their own numbering and approval chain, locked approved revisions and revision history.</p><h3>Can we hold Arabic versions?</h3><p>Yes, as paired records or controlled attachments, reviewed and approved like the English original.</p><h3>Does the AI draft replace our Level III?</h3><p>No. It is a starting point only. A Level III reviews and approves every procedure before publication.</p><h2>Talk to us</h2><p>Tell us which clients you work for, which methods you run and how many procedures and variants you control. We will show you the register and workflow using examples that look like your own library. <a href=\"/contact?service=erp&amp;subject=Procedures%20quote%20Middle%20East\">Request a quote for the Procedures app</a>.</p>\n<h2>Procedures by region</h2><ul><li><a href=\"/erp/apps/procedures\">Procedures global overview</a></li><li><a href=\"/erp/apps/procedures/usa\">Procedures in United States</a></li><li><a href=\"/erp/apps/procedures/canada\">Procedures in Canada</a></li><li><a href=\"/erp/apps/procedures/europe\">Procedures in UK &amp; Europe</a></li><li><a href=\"/erp/apps/procedures/india\">Procedures in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(Middle%20East)\">Send an enquiry about Procedures</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/procedures/india","publishedAt":"2026-09-27","title":"NDT Procedure Management Software India | Atlantis NDT","description":"Control IBR, PSU tender and ASME-driven NDT procedures with Level III approval, locked revisions and full history. Book a demo for your Indian NDT company.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Procedure Management Software in India</h1>\n<p>Controlled NDT procedures and techniques with revisions and approvals. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Procedure control for Indian NDT companies</h2><p>Indian NDT companies juggle more document regimes than most. A single company may inspect boiler tubes and steam piping under the Indian Boiler Regulations for a power plant, radiograph pressure vessel welds for a fabricator in Vadodara or Pune, support a turnaround at a refinery in Jamnagar, Mumbai, Visakhapatnam or Kochi, and bid for a PSU tender that asks for its complete procedure list before the technical bid is even opened.</p><p>Each of those clients reads your procedures with different eyes. The boiler inspecting authority wants to see that the procedure meets IBR. The PSU’s project management consultant wants it to match the tender specification and returns it with comments. The fabricator’s third-party inspector wants the revision referenced on the traveller. And radiography brings AERB’s requirements on top.</p><p>When the procedure library lives in email attachments and a shared folder, the same questions keep coming back: which revision did we submit, which one was accepted, who approved it, and is the site team using the right one?</p><p>The Procedures app in the Atlantis NDT ERP answers them from one controlled register. Each procedure carries its document number, revision, method, scope, material, applicable standard and acceptance criteria, with body text or an uploaded file. It moves through draft, submitted, reviewed, approved and published, with rejected and archived states. Preparer, reviewer and approver names and dates are recorded, approved revisions are locked, a snapshot of every revision is kept, and approvers get email notifications and reminders. Atlantis NDT has a team in Hyderabad and sets the app up for you.</p><h2>IBR work: boilers, steam piping and inspecting authorities</h2><p>Boilers and steam pipes in India are governed by the Indian Boiler Regulations, administered through the state Chief Inspectors of Boilers and the inspecting authorities recognised under the regulations. IBR sets requirements for the manufacture, erection and repair of boilers and steam piping, including radiographic and other examination of welds, and the inspecting authority reviews documents and witnesses work at the stages it chooses.</p><p>For an NDT company, IBR work means procedures that reflect IBR requirements specifically, not just a general ASME procedure with a new cover. The extent of radiography, the acceptance standards applied and the documentation the inspector expects can differ from what the same client asks for on non-IBR piping in the same plant.</p><p>The Procedures app keeps IBR procedures distinct. Each is its own record with IBR noted in the applicable standard and the acceptance criteria stated explicitly, so a document controller can filter the register and pull every procedure approved for IBR work in seconds when an inspecting authority or client asks. When the requirements change, each affected procedure goes through a controlled revision, and the previous revision is kept as a snapshot for any query about work already done.</p><p>That history matters for power plant owners and boiler makers, whose equipment and records stay in service for decades. Years after erection, a question about a weld radiographed under IBR can be answered with the exact procedure revision used, rather than a best guess from whoever still remembers the job.</p><h2>PSU tenders, PMCs and document review</h2><p>Much of India’s refinery, pipeline and petrochemical work comes through public sector undertakings such as IOCL, BPCL, HPCL, ONGC and GAIL, often with a project management consultant such as EIL reviewing contractor and vendor documents. Tender pre-qualification commonly asks for evidence of your quality system and a list of NDT procedures, and after award your procedures are submitted, reviewed against the project specification and returned with a review status and comments until they are accepted.</p><p>Refinery work also sits under Oil Industry Safety Directorate standards for inspection and safety, which shape what owners expect from inspection contractors on operating plants.</p><p>That review cycle is where document control breaks. The same UT procedure goes to three projects, each with slightly different specification clauses. Comments from one project get fixed in one copy and not another. Six months later nobody is sure which copy was finally accepted.</p><p>In the Procedures app, each project or client variant is its own record, numbered so the link to the tender or project is obvious. Internal review comments become rejection reasons on the record, so the author knows exactly why a draft came back before it goes to the PMC. Each resubmission is a new revision with a snapshot, so you can show the reviewer what changed in response to each round of comments. Tracking the PMC’s own review status and transmittal number for each submission can be added as part of the customization scope agreed with you. When the next tender asks for your procedure list, you pull it from the register by method and standard.</p><h2>The codes underneath: ASME, API and BIS</h2><p>Most Indian NDT procedures for pressure equipment and piping rest on ASME: Section V for procedure requirements, Section VIII and B31.3 for acceptance on vessels and process piping, B31.1 for power piping. API codes frame in-service work at refineries and tank farms, and API 1104 appears on pipeline projects. Bureau of Indian Standards documents such as IS 2595 for radiographic testing appear in some specifications, particularly older plants and government work, and EN ISO standards appear on projects designed by European licensors or EPCs.</p><p>That variety is why the applicable standard and acceptance criteria are separate fields on each procedure record. A reviewer can see at once whether a radiography procedure is written to ASME Section V with Section VIII acceptance, to IBR, or to a BIS standard, instead of hunting for it in the document. You can filter the register by standard when a code edition changes or a client moves to a new specification, then take each affected procedure through revision.</p><p>The AI-assisted first draft helps when a tender calls for a procedure you have never written — say a PAUT procedure for a client that has started accepting it in place of radiography on certain welds. The app produces a draft from the method, scope, material, standard and acceptance criteria you enter, or a built-in template if the AI service is unavailable. Your Level III then does the real work: reviewing, correcting and approving before anything is published.</p><h2>Who approves: ASNT and ISO 9712 in the same company</h2><p>Indian NDT companies commonly have both ASNT-based certifications under an employer’s SNT-TC-1A written practice and ISO 9712 certifications, including those issued through the Indian Society for NDT’s national scheme. Clients differ in what they ask for: some PSU and export projects specify ISO 9712, while US-linked clients and many EPCs accept or require ASNT-based qualification.</p><p>The Certificates app records both, along with CP-189, PCN and CSWIP where technicians hold them, with level, method, certifying body, issue and expiry dates, OJT and training hours and attachments. Status is computed automatically — active, expiring soon, expired or revoked — and warning tasks appear before expiry. Before you route a procedure for approval, you can confirm that the Level III holds a current certificate in that method under the scheme the client expects.</p><p>Atlantis NDT’s own <a href=\"/training\">NDT training</a> is based on ASNT SNT-TC-1A. Atlantis does not train or certify for ISO 9712; the app simply records those certificates alongside the rest.</p><h2>AERB and radiation protection procedures</h2><p>Industrial radiography in India is regulated by the Atomic Energy Regulatory Board. Companies must hold AERB licences for radiography exposure devices, applied for and managed through AERB’s online licensing system, with an approved Radiological Safety Officer and certified radiography personnel. AERB’s requirements for industrial radiography cover the use, storage, transport and emergency handling of sources, and licensees are expected to have written procedures for them.</p><p>These radiation protection procedures are controlled documents in their own right, and AERB inspections check that they are current. In the Procedures app they sit in the same register as RT, CR and DR technique procedures, with their own numbering and approval chain — typically the RSO and management — and the same locked approved revisions and revision history. After an inspection or incident review leads to a change, the revision goes through the workflow and the previous version is preserved.</p><p>Supporting records live elsewhere in the ERP. The employee NDT profile records radiation safety training, radiation badge number and medical fitness expiry, and RSO or radiographer certification can be recorded as a certificate with its expiry so it is flagged before it lapses. The Fleet app records whether a vehicle can carry radioactive sources and its transport licence number and expiry.</p><h2>PESO and gas storage equipment</h2><p>Fabricators and owners of vessels for compressed and liquefied gases work under the Petroleum and Explosives Safety Organisation, through rules such as the Static and Mobile Pressure Vessels (Unfired) Rules and the Gas Cylinders Rules. NDT companies supporting that work — radiography and ultrasonic examination of vessel welds, examination of storage installations — find that PESO-related projects bring their own documentation expectations, usually built on ASME or other recognised codes plus the requirements set in the approval.</p><p>As with IBR, the answer is to keep these procedures distinct and clearly labelled rather than mixing them into a general library. In the Procedures app, a PESO-related procedure is its own record with the applicable code and acceptance criteria stated, approved by your Level III, locked on approval and kept in the revision history. When a fabricator’s documentation package is assembled for approval, the procedure number and revision referenced in your reports point to a document you can produce exactly as approved.</p><h2>Personal data under the DPDP Act</h2><p>The Digital Personal Data Protection Act, 2023 applies to the personal data your company holds about employees and technicians. The procedure register itself holds little: the names of preparers, reviewers and approvers and the dates they acted, which your quality system requires you to keep. The more sensitive data — certificates, vision tests, medical fitness and radiation badge numbers — sits in the Certificates app and employee records.</p><p>During implementation we agree access rights so field staff see published procedures without seeing colleagues’ personal records, and we agree how long archived revisions and approval records are kept in line with your retention policy and client contracts. Your obligations under the Act stay with you; the setup is designed to support them.</p><h2>Connected to the rest of the ERP</h2><p>The Procedures app is part of the <a href=\"/erp\">Atlantis NDT ERP</a>. Project tasks carry procedure and WPS references. The NDT Reports app captures procedure and standard references on each report type, with inspector, reviewer and approver signatures and the third-party inspector’s name and signature, so the report your client receives quotes the procedure revision actually used. GST and other invoicing settings in the wider ERP are configured locally during implementation. See the <a href=\"/erp/apps\">full list of ERP apps</a> for how certificates, equipment and assignments connect.</p><p>For owners who want inspection results on the asset itself, Atlantis offers <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, a separate companion product that places inspection results on a 3D model of the asset and works alongside the ERP’s NDT Reports app.</p><h2>Implementation and Level III support</h2><p>We start from your existing library: base procedures, IBR, PESO and project variants, radiation procedures, the standards each cites and who approved them. We agree numbering that makes the client or regime obvious, set approval routes by method, load the register, configure reminders and run a live revision with your team. The ERP is affordable, accessible and fully customizable, with pricing on request.</p><p>If your procedures need rewriting for a tender or an audit, Atlantis NDT offers procedure writing and review by ASNT Level III personnel through its <a href=\"/consulting\">NDT consulting services</a>. <a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20India\">Book a Procedures demo for your Indian team</a>.</p><h2>Frequently asked questions</h2><h3>Can we keep IBR procedures separate from general procedures?</h3><p>Yes. Each IBR procedure is its own record with IBR noted in the applicable standard, so you can filter and produce them on request.</p><h3>Can we manage PMC comments on PSU projects?</h3><p>Each resubmission is a new revision with a snapshot, and internal rejections carry their reason. Tracking the PMC’s review status and transmittal number can be added in the agreed customization scope.</p><h3>Does the app record both ASNT and ISO 9712 certificates?</h3><p>Yes, with level, method, certifying body and expiry. Atlantis records ISO 9712 certificates but trains only to ASNT SNT-TC-1A.</p><h3>Where do AERB radiation procedures go?</h3><p>In the same register, with their own numbering and approval chain, locked approved revisions and full revision history.</p><h3>Does the AI draft replace our Level III?</h3><p>No. It is a first draft, or a built-in template if AI is unavailable. A Level III reviews and approves before publication.</p><h3>How is the Procedures app quoted?</h3><p>On request. The quote depends on the apps, number of users and customization you choose, and whether you want procedure writing support as well.</p><h2>Talk to us</h2><p>Tell us which regimes you work under — IBR, PESO, PSU projects, private fabrication — which methods you run and how many procedures you control. We will show you the register and workflow using examples that look like your own library. <a href=\"/contact?service=erp&amp;subject=Procedures%20quote%20India\">Request a quote for the Procedures app</a>.</p>\n<h2>Procedures by region</h2><ul><li><a href=\"/erp/apps/procedures\">Procedures global overview</a></li><li><a href=\"/erp/apps/procedures/usa\">Procedures in United States</a></li><li><a href=\"/erp/apps/procedures/canada\">Procedures in Canada</a></li><li><a href=\"/erp/apps/procedures/europe\">Procedures in UK &amp; Europe</a></li><li><a href=\"/erp/apps/procedures/middle-east\">Procedures in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/ndt-reports\">NDT Reports</a>: Method-specific NDT inspection reports, captured in the field and issued from the ERP.</li><li><a href=\"/erp/apps/certificates\">Certificates</a>: Technician certifications, eye tests and expiry tracking against your written practice.</li><li><a href=\"/erp/apps/dashboards\">Dashboards</a>: KPI dashboards across jobs, reports, certifications and revenue.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Procedures%20demo%20(India)\">Send an enquiry about Procedures</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/quotations","publishedAt":"2026-09-27","title":"NDT Quotation Software for Inspection Companies | Atlantis NDT","description":"Build NDT inspection quotes with methods, codes, site and dates, send a branded PDF and let clients accept online. Book a Quotations demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Quotation Software for Inspection Companies</h1>\n<p>Inspection quotes built from rates, crews and scope, sent for e-signature. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why NDT quotes go wrong when they live in spreadsheets</h2><p>Most NDT companies build quotes the same way. Someone opens last month's spreadsheet for a similar client, saves a copy, changes the name, adjusts the technician days and hopes the formulas still point at the right cells. The quote goes out as a PDF attached to an email, and the only record of what was promised sits in someone's sent folder.</p><p>That works until it doesn't. A radiography quote goes out without the night-shift premium because the old template was for a daytime MT job. A client accepts a quote that was superseded two days earlier. The operations manager mobilises a Level II crew when the client's specification called for a Level III to interpret. The invoice clerk has to hunt through email to find what mobilisation was agreed, and the client disputes the standby hours because the quote never said standby would be charged.</p><p>None of these are pricing mistakes in the usual sense. They are scope and record-keeping mistakes, and they cost margin, time and goodwill. The Quotations app in Atlantis NDT ERP is built to fix exactly that: one place where every NDT quote is built from the same structured fields, sent in your own format, accepted by the client online, and carried forward into the job and the invoice without being retyped.</p><p>It runs on Odoo's sales engine, pre-configured for inspection work by Atlantis NDT, so you are not starting from a generic retail quoting tool and trying to bend it to fit a turnaround, a shop radiography package or a resident inspector contract.</p><h2>What every NDT quote records</h2><p>An NDT quote is more than a list of line items. Clients want to know what, where, when and to which standard. The Quotations app adds these as proper fields on the quote header rather than free text buried in a notes box:</p><ul><li><strong>Job type</strong> - for example a shutdown or turnaround campaign, a new-construction weld inspection package, an in-service inspection, an emergency call-out or a long-term resident inspector arrangement. Your list of job types is agreed during implementation.</li><li><strong>Site</strong> - the plant, yard, shop or location where the work happens, so everyone reading the quote knows whether the work is in your facility or on the client's premises.</li><li><strong>Project dates</strong> - planned start and finish, which drive how your operations team plans crews and how the client reads your availability.</li><li><strong>Applicable codes</strong> - the construction codes, inspection codes and client specifications the work is performed to, such as ASME Section V, a client's own NDT specification or an EN ISO testing standard.</li></ul><p>Because these are fields and not paragraphs, you can search and filter on them. Pull up every open quote for a particular site. See which turnaround quotes are still waiting on client acceptance this month. Check which quotes referenced a client specification before it was revised. Sales managers get a pipeline view that means something for an inspection business, not just a list of totals.</p><p>The same fields flow onward when the quote is accepted, so the project team is not chasing sales to find out what the job actually was.</p><h2>Building a quote from NDT service products</h2><p>The lines on a quote come from your service catalogue. In the Quotations app, NDT service products are flagged with the inspection method and a category, so a line is not just 'inspection services' but, for example, phased array UT of butt welds, conventional radiography, computed radiography, magnetic particle testing, liquid penetrant testing, visual inspection, eddy current tube inspection or an ultrasonic thickness survey.</p><p>Categories separate the kinds of things NDT companies typically charge for: technician labour by level, equipment, consumables, mobilisation and demobilisation, travel and accommodation, reporting and documentation, and specialist services such as Level III review or procedure writing. How you split your catalogue is decided with you during implementation, based on how you actually quote today.</p><p>Having method and category on every product brings practical benefits:</p><ul><li>Quotes stay consistent. Two estimators quoting the same scope pick from the same catalogue rather than inventing their own wording.</li><li>You can report on what you are quoting by method: how much radiography versus advanced UT is in the pipeline. That is useful when you are deciding whether to buy another PAUT set or put more people through training.</li><li>Line descriptions carry through to the sales order and then to invoicing, so the invoice speaks the same language as the quote the client signed.</li></ul><p>Items specific to one quote, such as a one-off access allowance or a client-requested extra report format, can still be added as a note or a custom line. The catalogue does not have to anticipate everything; it just has to cover the work you do every week.</p><h2>Handling the way NDT work is actually charged</h2><p>Inspection companies rarely charge a single unit price. The same client can buy the same method under very different commercial structures depending on the job. Common patterns include:</p><ul><li>Day rate or shift rate per technician level, with trainee, Level I, Level II and Level III each priced separately, often with different figures for day and night shifts.</li><li>Hourly rates with a minimum call-out, typical for short shop jobs and emergency work.</li><li>Overtime, weekend and public holiday premiums applied as a multiplier on the base labour rate.</li><li>Unit rates, such as per weld joint, per radiographic exposure, per length of weld scanned or per thickness location.</li><li>Lump-sum prices for a defined package, where the risk of quantity changes sits with you.</li><li>Equipment charges per day or per week, separate from labour, for kit such as PAUT, TOFD or eddy current systems.</li><li>Consumables charged at cost plus handling, or included in the unit rate.</li><li>Standby rates when the crew is on site but cannot work because of permits, weather or access.</li><li>Mobilisation and demobilisation as fixed items, plus travel, accommodation and per diem.</li></ul><p>The Quotations app handles these through the product catalogue, units of measure and pricing set up during implementation. Standby and overtime appear as their own lines, so the client sees them before the job starts rather than for the first time on the invoice. A global discount can be applied across the whole quote when you agree a commercial concession, instead of editing every line by hand and losing track of the original figures.</p><p>The goal is simple: the quote the client signs describes, in writing, every way you intend to charge.</p><h2>Scope, acceptance criteria and exclusions: the part that protects your margin</h2><p>Experienced NDT managers know that disputes rarely start with the day rate. They start with scope. Who removes insulation? Who erects scaffolding? Who does surface preparation before MT? Is the client providing a radiation-controlled window at night, or are you expected to shoot around other trades? Is the reporting deliverable a signed report per joint or a summary register?</p><p>A good NDT quote answers these before mobilisation. In the Quotations app, the applicable codes field fixes the standards on the quote, and the quote's terms and notes hold your assumptions and exclusions. During implementation we set up your standard wording, so estimators start from an approved set of clauses rather than rewriting them each time. Typical items include:</p><ul><li>Extent of examination, and who selects the joints for spot or random inspection.</li><li>The source of acceptance criteria, and who makes the final call on borderline indications.</li><li>Access, lighting, power, scaffolding, surface preparation and insulation removal by the client.</li><li>Radiation safety arrangements, barrier areas and permitted shooting windows.</li><li>Permit-to-work delays and how standby is charged.</li><li>Reporting format, turnaround time and the number of copies or portal uploads required.</li><li>The validity period of the quote and what triggers a revision.</li></ul><p>When a Level III reviews a quote before it goes to a demanding client, they can check that the technique implied by the lines matches the codes listed on the header. That review is a human step. The app makes it easier by putting everything on one screen.</p><h2>A branded quotation PDF that looks like your company</h2><p>Clients judge an inspection company partly by its paperwork. A quote that arrives as a tidy, consistent document signals that the reports will be tidy too. The Quotations app produces a custom branded quotation PDF built around your identity: logo, company details, the accreditation statements you choose to include, and the layout your clients are used to seeing.</p><p>The PDF pulls the NDT header fields onto the page, so the client sees job type, site, project dates and applicable codes up front, followed by lines grouped the way you prefer, then totals, taxes, discount, terms, assumptions and exclusions. Because it is generated from the data, the PDF cannot say one thing while the system says another.</p><p>The layout is designed with you during implementation. Some companies want a one-page summary with a detailed schedule of rates attached. Others want a technical proposal style with a scope narrative at the front. Some clients require their own commercial form alongside your quote; in that case the branded PDF becomes your cover and technical submission.</p><p>If a client wants inspection results in 3D context, you can quote that deliverable too. Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places inspection results on a 3D model of the asset and works alongside the ERP's NDT Reports app. It is a separate product, and quoting it is a single line in your catalogue.</p><h2>Online acceptance and conversion to a sales order</h2><p>Chasing a signed quote is one of the slowest parts of NDT sales. The client says yes on the phone, the purchase order takes a week, and in the meantime you are holding a crew without anything in writing.</p><p>The Quotations app uses Odoo's standard online quote acceptance. Instead of only attaching a PDF, you send the client a link to their quote in a secure customer portal. They can read it, download the PDF, ask questions through the message thread on the quote, and accept it with an online signature. The acceptance is recorded against the quote with the signer's name and date, so there is no argument later about which version was agreed.</p><p>Once accepted, the quote converts to a sales order. That confirmation is the trigger for everything downstream: operations sees a confirmed job, the client's purchase order number can be recorded, and the commercial terms become the reference for invoicing.</p><p>Many large clients still issue purchase orders through their own procurement systems, and online acceptance does not replace that. What it gives you is a clear, dated record that the client's technical or site contact agreed the scope and rates, which you can point to while the formal PO is raised. For smaller clients and fabrication shops, the online signature is often the whole approval.</p><p>Every change is visible in the quote's history, so you can see what was sent, when, and what changed before acceptance.</p><h2>How Quotations connects to the rest of the ERP</h2><p>Quotations is one app in a connected system, and much of its value comes from what happens before and after the quote. Here is how it fits into <a href=\"/erp\">Atlantis NDT ERP</a>:</p><ul><li><strong>CRM</strong> - enquiries arrive with the service line, NDT service type, industry sector, site country, and estimated technicians and days. When the estimator opens a quote from the opportunity, that context is already there.</li><li><strong>Project</strong> - a confirmed order becomes the NDT job, holding job type, site, client PO, methods, codes, scope and acceptance criteria. How the order hands over to Project is configured during implementation to match your operations team.</li><li><strong>Team Assignments</strong> - operations plan crews against the dates on the quote, with double-booking of technicians and equipment serial numbers blocked, and warnings when assigned equipment is out of calibration.</li><li><strong>Certificates</strong> - if the quote promised a Level II in UT, the dispatcher can check who holds a current certification before assigning anyone.</li><li><strong>Timesheets and Invoicing</strong> - technician hours marked billable, with any rate multiplier, feed billing, and <a href=\"/erp/apps/invoicing\">the Invoicing app</a> carries labour, equipment and consumables subtotals so the invoice mirrors the quote.</li></ul><p>The benefit is plain: nobody retypes the job. What sales agreed is what operations planned, what the technicians booked time against, and what finance billed. When a client queries an invoice, you open the job and see the original accepted quote.</p><p>You can browse every connected module on the <a href=\"/erp/apps\">ERP apps overview</a>.</p><h2>Who uses the Quotations app</h2><p>Quotations is used by more people than sales, which is why the structure matters:</p><ul><li><strong>Business development and estimators</strong> build and send quotes, apply the global discount where agreed, and track which quotes are awaiting acceptance.</li><li><strong>Operations managers</strong> review large quotes before they go out, checking crew availability against the project dates and flagging scope they cannot staff.</li><li><strong>NDT Level III</strong> reviews technique, codes and acceptance criteria on technical quotes, especially for new clients or unusual scopes.</li><li><strong>QA/QC managers</strong> confirm that the codes and client specifications on the quote match the procedures the company holds and the qualifications it can offer.</li><li><strong>Finance</strong> checks payment terms, tax setup and currency before a quote is sent, and later uses the accepted quote as the reference for invoicing.</li><li><strong>Owners and general managers</strong> watch the pipeline by method, site and job type and decide where to invest in people and equipment.</li></ul><p>Access rights are set by role during implementation. Estimators can be allowed to create quotes but not change the catalogue; managers can be the ones who apply discounts; technicians do not need to see commercial information at all. Odoo's standard user groups handle this, configured to fit your team rather than a generic template.</p><p>In a small company one person may wear several of these hats. The app works the same way; there are simply fewer handovers.</p><h2>Setting up Quotations for your company</h2><p>Atlantis NDT deploys and sets up the ERP for you. For Quotations, implementation usually covers:</p><ol><li>A review of your current quotes, rate sheets and terms, so we understand how you charge today and where disputes tend to start.</li><li>Building your NDT service catalogue with method and category flags, units of measure and pricing structures.</li><li>Setting up job types, site records and your library of applicable codes and client specifications.</li><li>Designing the branded quotation PDF with your logo, layout, standard terms, assumptions and exclusions.</li><li>Configuring taxes, currencies and payment terms for the countries you work in.</li><li>Enabling online acceptance and signature, and deciding what happens when a quote converts to a sales order.</li><li>Importing open quotes and active clients, so you start with a live pipeline rather than an empty one.</li><li>Training your estimators and managers on the workflow.</li></ol><p>Anything beyond these features, such as a specific approval chain for large quotes or a client-mandated commercial format, is agreed as part of the customization scope. The ERP is affordable, accessible and fully customizable, and implementation is quote on request.</p><p>If you want to see how your own quote would look, <a href=\"/contact?service=erp&amp;subject=Quotations%20demo\">book a Quotations demo</a> and bring a recent quote with you.</p><h2>Frequently asked questions</h2><h3>Can one quote mix day rates, unit rates and lump sums?</h3><p>Yes. Each line is an NDT service product with its own unit of measure, so a single quote can combine day rates per technician level, unit rates per weld or exposure, fixed mobilisation and a lump-sum package. The catalogue and pricing structures are set up with you during implementation.</p><h3>Can clients accept a quote without printing and scanning it?</h3><p>Yes. The client receives a link to the quote in the customer portal and accepts it with an online signature. The acceptance is recorded on the quote, and the quote converts to a sales order.</p><h3>Does the quote show which codes and standards apply?</h3><p>Yes. Applicable codes are a field on the quote header, alongside job type, site and project dates, and they print on the branded PDF. Your library of codes and client specifications is set up during implementation.</p><h3>Can we apply a discount to the whole quote?</h3><p>Yes. A global discount applies across the quote, so you do not edit every line. Who may apply discounts is controlled through user access rights.</p><h3>Will the invoice match the quote?</h3><p>That is the design. The accepted quote becomes a sales order linked to the project, timesheets and the Invoicing app, so labour, equipment and consumables are billed against the lines the client agreed.</p><h3>How much does the Quotations app cost?</h3><p>Quote on request. Atlantis NDT ERP is affordable and priced according to your users, apps and customization scope. <a href=\"/contact?service=erp&amp;subject=Quotations%20quote%20request\">Request a quote</a> and we will come back with a proposal.</p><h2>See your own NDT quote in the system</h2><p>The fastest way to judge the Quotations app is to watch one of your real quotes being built in it. Send us a quote you issued recently, with its rate sheet and terms, and we will show you how it would be created, reviewed, sent and accepted in Atlantis NDT ERP, and how it would carry through to the job and the invoice. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo\">Book your Quotations demo</a> today.</p>\n<h2>Quotations by region</h2><ul><li><a href=\"/erp/apps/quotations/usa\">Quotations in United States</a></li><li><a href=\"/erp/apps/quotations/canada\">Quotations in Canada</a></li><li><a href=\"/erp/apps/quotations/europe\">Quotations in UK &amp; Europe</a></li><li><a href=\"/erp/apps/quotations/middle-east\">Quotations in Middle East</a></li><li><a href=\"/erp/apps/quotations/india\">Quotations in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Quotations%20demo\">Send an enquiry about Quotations</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/quotations/usa","publishedAt":"2026-09-27","title":"NDT Quotation Software for US Inspection Firms | Atlantis NDT","description":"Quote Gulf Coast turnarounds, MSA rate sheets and API/ASME work in one NDT quotation app with online acceptance. Book a demo for your US team.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Quotation Software for Inspection Companies in the USA</h1>\n<p>Inspection quotes built from rates, crews and scope, sent for e-signature. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work is quoted in the United States</h2><p>In the United States, most NDT work does not start with a one-off quote. It starts with a master service agreement. Refiners, chemical plants, pipeline operators and EPC contractors typically qualify a handful of inspection vendors, sign an MSA, and agree a rate sheet that governs every job for the life of the contract. After that, individual jobs are released as work orders, call-outs or turnaround scopes against those agreed rates.</p><p>That changes what a quotation system has to do. You still send standalone quotes to fabrication shops, smaller plants and new clients. But much of an estimator's week goes on building turnaround estimates against an existing rate sheet, pricing add-on scope the rate sheet does not cover, and answering bid invitations for the next MSA renewal.</p><p>The Quotations app in Atlantis NDT ERP is set up for both. Every quote carries the job type, site, project dates and applicable codes. Lines come from an NDT service catalogue flagged by method and category. Clients accept online, and the quote converts to a sales order. Where you work under an MSA, the agreed rate sheet is loaded as client pricing during implementation, so an estimator quoting that client starts from the right figures without opening a spreadsheet.</p><p>Atlantis NDT has a base in Houston, so the vocabulary on this page is the one Gulf Coast inspection managers use every day: MSAs, rate sheets, turnarounds, call-outs, portal-to-portal and per diem.</p><h2>Turnarounds, MSAs and bid invitations</h2><p>Spring and fall turnaround seasons dominate the calendar for Gulf Coast inspection companies. From Corpus Christi through Houston, Beaumont and Port Arthur, Lake Charles and Baton Rouge, owners plan unit outages months ahead and ask inspection vendors to bid crew sizes, durations and equipment against a defined work list. The same weeks are wanted by every other plant, so a quote that commits a crew you cannot staff is a real business risk.</p><p>The Quotations app helps in three ways. First, the job type and project dates on each quote let you filter every open turnaround bid by date range and see where commitments overlap. Second, lines are built from your catalogue, so Level II UT technicians, a Level III, PAUT equipment, radiography crews and consumables are priced the same way on every bid. Third, the CRM opportunity behind the quote already holds estimated technicians and days, so operations can sanity-check headcount before the bid goes in.</p><p>For MSA renewals and formal bid invitations, owners often send their own pricing forms. Your branded PDF becomes the technical and commercial cover letter, with scope, assumptions and exclusions, while the client's form carries the numbers in their format. Both come from the same data, so they agree.</p><p>Emergency call-outs are different again: short, urgent and often agreed by phone. Here the value is a quick quote from the MSA rates, sent for online acceptance, so the plant contact confirms scope in writing before your crew pulls up at the gate.</p><h2>Contractor prequalification and what owners check before they buy</h2><p>Before a US owner will issue a purchase order, your company usually has to be approved as a vendor. Many operators use contractor management platforms such as ISNetworld, Avetta or Veriforce to collect safety statistics, insurance certificates, written safety programs and training records. Pipeline operators add operator qualification requirements for covered tasks under PHMSA rules. Some owners also audit your written practice and quality manual directly.</p><p>The ERP does not connect to these platforms, and it does not need to. What it gives you is the evidence behind them in one place, and a quote that states clearly what you are offering. The Certificates app records company certifications with alert days before they lapse, and technician certifications with scheme, level, method and expiry. When a client asks whether the Level II named on a bid is current, the answer is in the system rather than in a binder in the office.</p><p>In the quote itself, standard clauses set up during implementation can state your qualification basis: for example, that personnel are qualified and certified to your written practice under ASNT SNT-TC-1A, or to ANSI/ASNT CP-189 where the client specifies it. Aerospace shops working to NAS 410 will want that referenced instead. The Level III reviewing the quote can confirm the stated basis matches what the client's specification demands.</p><p>Getting this right on the quote avoids a familiar problem: winning the work and then discovering the client wanted a qualification or a crew make-up you did not offer.</p><h2>Codes and specifications on US quotes</h2><p>The applicable codes field on each quote records what the work is performed to. Typical entries for US work include:</p><ul><li>ASME Section V for examination methods, with acceptance from ASME Section VIII for pressure vessels or ASME B31.3 for process piping.</li><li>ASME Section I for power boilers and ASME B31.1 for power piping in utility and cogeneration work.</li><li>API 510, API 570 and API 653 for in-service inspection of pressure vessels, piping and aboveground storage tanks, where the client's authorized inspector relies on your NDT data.</li><li>API 1104 for pipeline welding, with operator specifications and the PHMSA regulations in 49 CFR Parts 192 and 195 in the background.</li><li>AWS D1.1 for structural steel welding in fabrication shops.</li><li>Client specifications: most large owners have their own inspection and NDT specifications, which add to or override the codes.</li></ul><p>Recording these as structured data matters. When a client revises its NDT specification, you can find every open quote that referenced the old revision. When a Level III signs off a technical proposal, the codes sit next to the method lines. And when the job converts, the codes pass to the project, so technicians work to what the client actually bought.</p><p>The quote should also say which procedures you will use. The ERP's Procedures app keeps your procedure register by method, standard and revision, which makes citing the right document on a quote a lookup rather than a memory test.</p><h2>Rate structures common in US NDT work</h2><p>US rate sheets have their own conventions, and the catalogue is built around the way you already charge. Structures we typically configure, described in words rather than figures:</p><ul><li>Straight-time hourly or daily rates per technician level, with separate rates for helpers, assistants and trainees.</li><li>Overtime after the standard daily or weekly hours, and double time for Sundays and holidays, set as multipliers on the base rate in line with your MSA.</li><li>Portal-to-portal charging, where travel from your shop to the site is billable, or site-only charging where it is not.</li><li>Minimum call-out charges for short jobs and emergency work.</li><li>Per diem for out-of-town work, and mileage or truck charges for company vehicles.</li><li>Radiography crew rates, usually a two-person crew with source and film or CR equipment, often with a night premium when shooting is restricted to off-hours.</li><li>Equipment day rates for PAUT, TOFD and eddy current kit where the rate sheet separates labour from equipment.</li><li>Unit rates for fabrication shops, such as per weld radiographed or per foot of weld scanned.</li></ul><p>Overtime rules and the tax treatment of per diem sit with your payroll advisers. The quote simply needs to make each charge visible. Standby, mobilisation and per diem appear as their own lines, and a global discount is available when you agree a commercial concession on a large bid.</p><h2>Radiography, safety and site requirements in the quote</h2><p>Radiography scope in the US carries regulatory obligations that belong in the quote's assumptions. Industrial radiography licensing is handled by the Nuclear Regulatory Commission or, in Agreement States such as Texas and Louisiana, by the state radiation control program, and 10 CFR Part 34 sets requirements such as radiographer qualification and the presence of at least two qualified people at temporary job sites. Your quote should state that radiography is performed under your license, how barrier areas will be set up, and which shooting windows the client must provide.</p><p>OSHA requirements shape site work too. Confined space entry, fall protection, hot work permits and hazard communication all affect how long a job takes and who provides what. Plants require site-specific safety orientation, and facilities covered by maritime security rules along the ship channels require TWIC cards. Those hours are real, and your quote should say who pays for them.</p><p>In the ERP, the employee NDT profile holds radiation safety training, radiation badge number and medical fitness expiry, and the Certificates app sends alerts before technician certifications lapse. None of that prints on a quote, but when you promise a qualified radiography crew for a date, operations can check that the people they plan to send will be qualified on that date. Fleet records, including whether a truck can carry radioactive sources and its transport licence details, support the same check for the vehicle.</p><h2>Sales tax, payment terms and invoicing in the US</h2><p>The US has no national sales tax. Whether NDT and inspection services are taxable depends on the state, and sometimes on whether the work is classed as a service to real property, a repair or a testing service. Some states tax certain services and others do not. Your accountant makes those calls; during implementation we configure the tax rules and fiscal positions they give us, so the correct tax appears on the quote for each client and site. We make no tax certification claims.</p><p>Payment terms are configured the same way. Large operators often dictate long net terms through their MSAs, and many pay through supplier portals that require your invoice to quote their PO and line numbers exactly. Smaller fabrication clients may pay on shorter terms. Each customer carries its own default payment terms, which print on the quote so there is no surprise at invoice time.</p><p>When the quote is accepted and the job runs, technician timesheets marked billable, with any overtime multiplier, feed billing. <a href=\"/erp/apps/invoicing\">Invoicing</a> carries the NDT project, the client's PO number and the site on the invoice header, with labour, equipment and consumables subtotals, so the invoice reads like the quote the client signed. That consistency is what shortens the back-and-forth with accounts payable teams.</p><h2>Branded quotes, online acceptance and 3D deliverables</h2><p>The custom branded quotation PDF carries your logo, company details and the NDT header fields: job type, site, project dates and applicable codes. For owners who judge vendors partly on presentation, a consistent proposal document matters, particularly when you are bidding against national inspection firms with large proposal teams.</p><p>Online acceptance uses Odoo's standard customer portal. A plant maintenance contact can accept a call-out quote with an online signature from a phone, even while procurement is still raising the formal PO. The acceptance is logged against the quote and converts it to a sales order, so dispatch can move.</p><p>Some US owners now want inspection results in a form their reliability and integrity teams can read visually. Atlantis's companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, places inspection results on a 3D model of the asset and works alongside the ERP's NDT Reports app. It is a separate product; if a client wants that deliverable, it is one more line in your catalogue.</p><p>For the estimator, that means one place to price inspection, reporting and any 3D deliverable, and one document for the client to sign.</p><h2>From accepted quote to crew on site</h2><p>Once a quote converts, the rest of <a href=\"/erp\">Atlantis NDT ERP</a> picks it up. The project carries job type, site, client PO, methods, codes and scope. Team Assignments dispatches crews against the dates, records mobilisation and demobilisation, blocks double-booking of technicians and equipment serial numbers, and warns when assigned equipment is out of calibration. Timesheets record inspection, travel, standby and setup hours by method, and warn if a technician's certificate is not valid.</p><p>For a Gulf Coast company running several turnarounds at once, this is where a good quote pays off. The operations manager sees which crews are committed where, which jobs are still at quote stage, and which quotes are accepted but not yet staffed. Nothing is retyped, and the rate structure the client agreed is the one the invoice follows.</p><p>Reports tie back as well: the NDT Reports app captures work order, contract, drawing and procedure references, so the report a client's inspector reviews points to the same job that was quoted. The full list of connected modules is on the <a href=\"/erp/apps\">ERP apps</a> page.</p><h2>Setting up Quotations for a US NDT company</h2><p>Implementation covers loading your MSA rate sheets as client pricing; building the catalogue by method and category; setting up job types that match how you work, such as turnaround, call-out, shop, new construction and resident inspector; adding your codes and client specification library; designing the branded PDF with your standard terms and radiography assumptions; configuring state tax rules and payment terms; and enabling online acceptance.</p><p>We also import your open quotes and active clients, and train estimators and operations managers on the workflow, so the first turnaround season on the system is not the first time anyone has used it. Anything beyond the listed features, such as a client-specific approval chain, is agreed as part of the customization scope.</p><p>The ERP is affordable, accessible and fully customizable, and implementation is quote on request. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20USA\">Book a US Quotations demo</a> and bring a current rate sheet.</p><h2>Frequently asked questions</h2><h3>Can we load different rate sheets for different MSA clients?</h3><p>Yes. Each client's agreed rates are set up as pricing during implementation, so an estimator quoting that client gets the MSA rates by default. Rates come from the catalogue and pricing, not from figures typed onto each quote.</p><h3>Does the app calculate state sales tax on inspection services?</h3><p>It applies the tax rules configured for each client and site during implementation, based on your accountant's advice about which states tax your services. No tax certification is claimed; the setup follows your advisers.</p><h3>Can a plant contact accept a call-out quote from the field?</h3><p>Yes. The quote is sent as a link to the customer portal, where the contact signs online. The acceptance is recorded and the quote converts to a sales order, ready for dispatch.</p><h3>Can the quote state that we qualify personnel to SNT-TC-1A or CP-189?</h3><p>Yes. Your standard terms can state your qualification basis, and the Certificates app records each technician's scheme, level, method and expiry so you can back the statement up.</p><h3>Does it connect to ISNetworld or Avetta?</h3><p>No. The ERP does not integrate with contractor management platforms. It holds the certifications and records you upload to them, with expiry alerts, so the evidence stays current.</p><h3>What does the Quotations app cost?</h3><p>Quote on request. Pricing depends on users, apps and customization scope. <a href=\"/contact?service=erp&amp;subject=Quotations%20quote%20request%20USA\">Request a quote</a> for your company.</p><h2>Quote your next turnaround in the system</h2><p>If your turnaround bids still live in copied spreadsheets, the next season is a good time to change that. Show us one bid and one MSA rate sheet, and we will walk through how both would be built, sent, accepted and carried into dispatch and invoicing. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20USA\">Talk to us about a demo</a>.</p>\n<h2>Quotations by region</h2><ul><li><a href=\"/erp/apps/quotations\">Quotations global overview</a></li><li><a href=\"/erp/apps/quotations/canada\">Quotations in Canada</a></li><li><a href=\"/erp/apps/quotations/europe\">Quotations in UK &amp; Europe</a></li><li><a href=\"/erp/apps/quotations/middle-east\">Quotations in Middle East</a></li><li><a href=\"/erp/apps/quotations/india\">Quotations in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(United%20States)\">Send an enquiry about Quotations</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/quotations/canada","publishedAt":"2026-09-27","title":"NDT Quotation Software for Canadian NDT Firms | Atlantis NDT","description":"NDT quotation software for Canadian inspection firms: CSA and ABSA scopes, GST/HST set up locally, online client acceptance. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Quotation Software for Inspection Companies in Canada</h1>\n<p>Inspection quotes built from rates, crews and scope, sent for e-signature. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work is quoted in Canada</h2><p>Canadian NDT companies quote into a market shaped by distance and regulation. Work clusters around Alberta's oil sands, the upgraders and the Industrial Heartland near Edmonton, refining and petrochemicals in Sarnia and Montreal, Ontario's nuclear fleet, pipelines crossing several provinces, pulp and paper, mining, and the fabrication shops that build pressure equipment for all of them. Each client group buys inspection differently, and a single company may quote a camp-based oil sands shutdown, nuclear outage support and shop radiography in the same month.</p><p>Pressure equipment is regulated provincially. ABSA in Alberta, TSSA in Ontario and the equivalent authorities elsewhere set requirements that flow into what the owner asks you to inspect and to which standard. Radiography is licensed federally by the Canadian Nuclear Safety Commission. Technician certification to ISO 9712 is widely recognised through the national scheme administered by Natural Resources Canada. A Canadian NDT quote has to reflect all of that, and it often has to do it in two languages.</p><p>The Quotations app in Atlantis NDT ERP gives estimators one structure for all of it: job type, site, project dates and applicable codes on every quote, NDT service products flagged by method and category, a global discount when you agree a concession, a custom branded PDF, and Odoo's standard online acceptance with conversion to a sales order. The rest of this page covers how that works for Canadian inspection companies specifically.</p><h2>Tenders, MSAs and prequalification in Canada</h2><p>Large Canadian owners and EPCs usually prequalify inspection vendors before inviting them to bid. Safety prequalification is a big part of that. Many owners use contractor management platforms such as ISNetworld, ComplyWorks or Avetta, and many expect a Certificate of Recognition (COR) from a provincial safety association, which is especially common in Alberta. Public bodies, utilities and Crown corporations advertise work through federal and provincial tendering portals.</p><p>Once qualified, you usually work under a master services agreement with a schedule of rates, and individual jobs arrive as work orders or shutdown scopes. Oil sands operators plan major turnarounds well ahead, and inspection vendors bid crew sizes, durations, equipment and camp logistics against a defined work list.</p><p>The ERP does not connect to prequalification platforms. What it does is keep the evidence you submit to them current. The Certificates app records company certifications with alert days, and technician certifications with scheme, level, method and expiry. When an owner asks for the certificates of the crew named in a bid, you pull them from one place.</p><p>On the quote, the job type separates MSA call-outs, shutdown bids, nuclear outage support and shop work, so you can filter the pipeline the way your managers think about it. Estimated technicians and days from the CRM opportunity sit behind each quote, giving operations an early look at headcount before anything is committed to the owner.</p><h2>Recording Canadian qualifications behind the quote</h2><p>Canadian clients often specify the qualification basis for NDT personnel. Many require certification to CAN/CGSB-48.9712, the Canadian adoption of ISO 9712, through the NRCan certification body. Others, particularly US-owned operators and aerospace shops, accept or require an employer-based scheme under ASNT SNT-TC-1A or CP-189. Nuclear work may carry additional requirements set by the licensee.</p><p>The Certificates app records each of these as a scheme against the technician, with level, method, certifying body, and issue and expiry dates. Status is computed automatically as active, expiring soon, expired or revoked, and daily checks create warning tasks 90 days ahead. So an estimator promising ISO 9712 Level 2 UT technicians for a spring shutdown can have operations confirm who will be current on those dates before the bid goes in.</p><p>Your standard terms on the quote can state the certification basis you offer. To be clear on training: Atlantis NDT offers training based on ASNT SNT-TC-1A only. It does not train for or certify under the NRCan ISO 9712 scheme; the ERP simply records the certificates your technicians already hold.</p><p>Vision tests are recorded too, with near vision, colour perception, examiner and expiry, because an expired eye test can take a technician off a job just as surely as an expired certificate. It is far better to find that out while the quote is being built than on the first morning of a shutdown.</p><h2>Codes and standards on Canadian quotes</h2><p>The applicable codes field holds what the job is performed to. Common entries on Canadian quotes include:</p><ul><li>CSA B51 for boilers, pressure vessels and pressure piping, applied through the provincial authority such as ABSA or TSSA.</li><li>ASME Section V, Section VIII and B31.3, which CSA B51 references for design and examination in many applications.</li><li>CSA Z662 for oil and gas pipeline systems, including its requirements for weld inspection and NDT.</li><li>CSA W59 for welded steel construction, relevant to structural fabrication shops certified under CSA W47.1.</li><li>CSA N285.4 for periodic inspection of CANDU nuclear power plant components, for Ontario outage work.</li><li>API 510, API 570 and API 653 for in-service inspection at refineries and terminals, alongside owners' own inspection specifications.</li></ul><p>Keeping codes as structured data means you can find every open quote that references a given standard or a particular client specification revision. It also means the codes carried into the project and seen by technicians are the ones the client bought, not whatever was on the last similar job.</p><p>The ERP's Procedures app keeps your procedure register by method, standard and revision, so the quote's terms can cite the procedure you will actually use, and a Level III reviewing the quote can check that a current, approved revision exists for every method being offered.</p><h2>Rate structures and logistics common in Canada</h2><p>Canadian rate sheets reflect long distances, remote sites and winter. Structures we typically configure, described in words:</p><ul><li>Day or shift rates per technician level, with separate night-shift rates.</li><li>Overtime multipliers following provincial employment standards and your MSA, which differ from province to province.</li><li>Camp-based work, where the owner provides camp accommodation and the quote covers labour and equipment, versus a living-out allowance where the crew stays in town.</li><li>Rotation schedules for long shutdowns, with travel days and flights to fly-in, fly-out sites quoted separately.</li><li>Mobilisation and demobilisation charges that reflect the real distance to northern or remote sites.</li><li>Radiography crew rates, often with night work when shooting has to be separated from other trades.</li><li>Equipment day rates for PAUT, TOFD and eddy current kit, and winter items such as heating or hoarding where your terms make them the client's responsibility.</li><li>Unit rates for shop and pipeline work, such as per weld or per length of weld scanned.</li></ul><p>Each of these appears as its own line from the catalogue, so the client sees camp, travel and standby before work starts rather than on the invoice. A global discount can be applied across the quote when you agree a concession on a large package, without losing sight of the underlying rates.</p><h2>Radiography, safety and site access</h2><p>Radiography scope needs specific statements in a Canadian quote. Exposure devices are licensed by the CNSC, which requires certified exposure device operators and a radiation safety program, and moving sources between sites falls under CNSC packaging and transport regulations and Transport of Dangerous Goods rules. Your assumptions should state that radiography is performed under your CNSC licence, how controlled areas will be set up, and which shooting windows the client will provide.</p><p>Site safety is part of scope too. Oil sands and heavy industrial sites expect site-specific orientations, and many require safety tickets such as H2S Alive, fall protection and confined space entry. Nuclear sites add their own access, security screening and dosimetry processes. All of this takes time before productive work begins, and your quote should say who pays for it.</p><p>In the ERP, the employee NDT profile holds radiation safety training, radiation badge number and medical fitness expiry. Fleet records hold whether a vehicle can carry radioactive sources, with transport licence number and expiry. When a quote promises a radiography crew for particular dates, operations can check people and vehicles against those dates rather than finding the gap on the morning of mobilisation.</p><h2>GST, HST, PST and QST configured locally</h2><p>Sales tax in Canada depends on where the service is supplied. Some provinces use the harmonized HST, others charge GST alongside a provincial sales tax, Quebec has QST, and Alberta charges GST only. Place-of-supply rules decide which applies when your company is in one province and the site is in another. Your accountant gives us the rules; during implementation we configure taxes and fiscal positions so the right tax appears on the quote for each client and site. We make no tax certification claims.</p><p>Payment terms are set per customer. Large owners often pay through supplier portals on their own terms, and construction work in several provinces is subject to prompt payment and holdback rules under provincial construction legislation, such as Ontario's Construction Act. Where a holdback applies, your terms and invoicing need to reflect it, and how that is handled is agreed during implementation.</p><p>Quebec clients may expect documents in French. Odoo supports multiple languages, and a French version of your quotation layout and standard terms can be part of the customization scope. Quotes can also be issued in US dollars for cross-border clients, with currencies configured during implementation.</p><h2>Branded quotes, online acceptance and 3D deliverables</h2><p>The custom branded quotation PDF brings your logo, company details and NDT header fields onto one clean document, with lines grouped by labour, equipment, consumables and logistics, then tax, discount and your standard terms. For shutdown bids, it becomes the technical and commercial submission that accompanies any owner pricing form.</p><p>With Odoo's standard online acceptance, the client receives a link to the quote in your customer portal, can ask questions on the quote's message thread, and accepts with an online signature. The acceptance is recorded and the quote converts to a sales order. For a field supervisor at a remote site authorising extra scope, that beats waiting for a scanned signature to come back over a poor connection.</p><p>Where a client wants inspection results in 3D, Atlantis's companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places results on a 3D model of the asset and works alongside the ERP's NDT Reports app. It is a separate product and can be quoted as a line in your catalogue, which is useful for owners who want tank, vessel or piping inspection results visible to integrity engineers who never read a paper report.</p><h2>From accepted quote to job and invoice</h2><p>Once a quote converts, the rest of <a href=\"/erp\">Atlantis NDT ERP</a> takes over. The project carries job type, site, client PO, methods, codes and scope. Team Assignments dispatches crews against the project dates, records mobilisation and demobilisation dates and site coordinates, blocks technician and equipment double-booking, and warns when assigned equipment is out of calibration. The availability calendar records leave, training and unavailability, which matters when rotations and camp bookings have to line up.</p><p>Timesheets record inspection, travel, standby and setup hours with billable flags and rate multipliers, and warn when a technician's certificate is not valid. <a href=\"/erp/apps/invoicing\">Invoicing</a> then produces invoices carrying the project, client PO and site, with labour, equipment and consumables subtotals that mirror the accepted quote. Field expenses on living-out jobs can be recorded and re-billed to the job through Expenses.</p><p>The result is one record of the job from first enquiry to paid invoice. More detail on each module is on the <a href=\"/erp/apps\">ERP apps</a> page.</p><h2>Setting up Quotations for a Canadian NDT company</h2><p>Implementation usually covers loading MSA rate schedules as client pricing; building the service catalogue by method and category, including camp, rotation and remote mobilisation items; job types for shutdowns, call-outs, nuclear outages, pipeline and shop work; a codes library covering CSA, ASME, API and owner specifications; the branded PDF with your radiography, safety and access clauses; GST, HST, PST and QST setup following your accountant; payment terms and currencies; and online acceptance.</p><p>We also import open quotes and active clients and train your estimators and operations team. Additional needs, such as a French layout or holdback handling on invoices, are agreed as part of the customization scope. The ERP is affordable, accessible and fully customizable, and implementation is quote on request. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20Canada\">Book a Canadian Quotations demo</a>.</p><h2>Frequently asked questions</h2><h3>Can the ERP record NRCan ISO 9712 certifications?</h3><p>Yes. The Certificates app records ISO 9712 as a scheme with level, method, certifying body and expiry, alongside SNT-TC-1A and CP-189. Atlantis NDT does not train for or issue ISO 9712 certification; the app records certificates your technicians already hold.</p><h3>How does it handle GST, HST and provincial taxes?</h3><p>Taxes and fiscal positions are configured during implementation following your accountant's rules, so the right tax appears for each client and site province. No tax certification is claimed.</p><h3>Can we quote camp-based and living-out jobs differently?</h3><p>Yes. Camp, living-out allowance, travel and rotation items are separate products in your catalogue, so each quote carries the logistics that fit the job.</p><h3>Can quotes be issued in French?</h3><p>Odoo supports multiple languages. A French quotation layout and translated standard terms can be included in your customization scope.</p><h3>Can a remote site supervisor accept extra scope online?</h3><p>Yes. The quote goes to the customer portal, where the supervisor signs online. The acceptance is recorded and the quote converts to a sales order.</p><h3>What does it cost?</h3><p>Quote on request, based on users, apps and customization. <a href=\"/contact?service=erp&amp;subject=Quotations%20quote%20request%20Canada\">Request a quote</a> for your company.</p><h2>Bring a Canadian bid and see it rebuilt</h2><p>Send us a recent shutdown bid or MSA call-out quote, with its tax treatment and logistics, and we will show you how it would be built, sent and accepted in Atlantis NDT ERP, and how it would flow into dispatch and invoicing. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20Canada\">Arrange your demo</a>.</p>\n<h2>Quotations by region</h2><ul><li><a href=\"/erp/apps/quotations\">Quotations global overview</a></li><li><a href=\"/erp/apps/quotations/usa\">Quotations in United States</a></li><li><a href=\"/erp/apps/quotations/europe\">Quotations in UK &amp; Europe</a></li><li><a href=\"/erp/apps/quotations/middle-east\">Quotations in Middle East</a></li><li><a href=\"/erp/apps/quotations/india\">Quotations in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(Canada)\">Send an enquiry about Quotations</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/quotations/europe","publishedAt":"2026-09-27","title":"NDT Quotation Software for UK and Europe | Atlantis NDT","description":"Quote UK and European NDT work against EN ISO standards and PED scopes, with VAT set up locally and online acceptance. Request a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Quotation Software for Inspection Companies in the UK and Europe</h1>\n<p>Inspection quotes built from rates, crews and scope, sent for e-signature. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work is quoted across the UK and Europe</h2><p>The UK and European NDT market is fragmented in a way that makes quoting harder than it looks. One company might price offshore inspection for a North Sea duty holder out of Aberdeen, weld inspection for a pressure equipment fabricator working to the Pressure Equipment Directive, shutdown support at a refinery or chemical site, rail or aerospace component testing, and offshore wind fabrication, all in the same quarter. Each client works to different standards, buys through different procurement routes and pays in different ways.</p><p>Cross-border work adds more. A UK company quoting into the Netherlands or Norway deals with a different currency, different VAT treatment, different expectations about personnel certification and, sometimes, a client who wants documents in its own language. A continental company quoting UK work runs into UK-specific regulations that no longer follow EU law automatically.</p><p>The Quotations app in Atlantis NDT ERP gives estimators one structure for all of this. Every quote carries job type, site, project dates and applicable codes. Lines come from an NDT service catalogue flagged by method and category. A global discount handles agreed concessions, the custom branded PDF presents it all in your house style, and Odoo's standard online acceptance lets the client sign and convert the quote to a sales order. This page explains how that fits the way inspection is bought in the UK and Europe.</p><h2>Tendering: frameworks, public procurement and supplier registration</h2><p>Much UK and European NDT work is bought through frameworks and call-off contracts rather than individual quotes. A utility, operator or public body runs a tender, appoints a small number of inspection suppliers to a framework with a schedule of rates, and then calls off work against it for several years. In the UK, public contracts are advertised through Find a Tender under the Procurement Act 2023; across the EU, larger contracts appear on TED under the public procurement directives. Evaluation usually weighs quality alongside price, so your technical submission matters as much as your rates.</p><p>Supplier registration comes first. In UK and Norwegian energy, many operators use Achilles supplier qualification schemes; UK utilities often use Achilles UVDB; construction clients frequently expect Constructionline or a safety scheme such as SafeContractor or CHAS. Each asks for company certifications, insurances, policies and, often, personnel qualifications.</p><p>The ERP does not connect to these schemes. What it does is keep the evidence behind them current. The Certificates app records company certifications, such as your ISO management system certificates and accreditations, with alert days, and technician certifications with scheme, level, method and expiry. When a framework renewal asks for proof, it is in one place.</p><p>In the Quotations app, the job type distinguishes framework call-offs, tender submissions, offshore campaigns and shop work, so you can see your pipeline by route to market. For formal tenders, your branded PDF forms the technical and commercial response alongside any client pricing schedule, and both come from the same data.</p><h2>Personnel certification on the quote: EN ISO 9712, PCN and others</h2><p>European clients usually expect NDT personnel certified to EN ISO 9712 by an accredited third-party certification body. In the UK that most often means PCN, operated by BINDT. Elsewhere it may be a national scheme such as those run by DGZfP in Germany or COFREND in France. Welding inspection roles may call for CSWIP. Aerospace work typically follows EN 4179, and US-owned clients may still accept employer-based certification under ASNT SNT-TC-1A.</p><p>The PED adds a specific point for pressure equipment in the higher categories: personnel carrying out NDT of permanent joints must be approved by a third-party organisation recognised by a member state. A quote for that work should state the certification you will provide, and your Level 3 should confirm it matches the client's requirement.</p><p>The Certificates app records all of these schemes against each technician, with level, method, certifying body, issue and expiry dates and attachments. Status is computed automatically, and warnings are raised 90 days before expiry, along with vision test expiry. So when a quote promises a PCN Level 2 in PAUT for a June campaign, operations can check who will still be current in June.</p><p>A clear line on training: Atlantis NDT offers training based on ASNT SNT-TC-1A only. It does not train for or certify under EN ISO 9712, PCN or CSWIP. The ERP records those certificates for the people who already hold them.</p><h2>Codes and standards on UK and European quotes</h2><p>The applicable codes field holds what the work is performed to. Typical entries include:</p><ul><li>EN ISO 17640 for ultrasonic testing of welds, with acceptance levels from EN ISO 11666.</li><li>EN ISO 13588 for automated phased array UT and EN ISO 10863 for TOFD.</li><li>EN ISO 17636 for radiographic testing of welds, with acceptance from EN ISO 10675.</li><li>EN ISO 17638 for magnetic particle testing with EN ISO 23278, and EN ISO 3452 for penetrant testing with EN ISO 23277.</li><li>EN ISO 17637 for visual testing, with weld quality levels from EN ISO 5817.</li><li>EN 13445 for unfired pressure vessels and EN 13480 for industrial piping, under PED 2014/68/EU or, in Great Britain, the Pressure Equipment (Safety) Regulations 2016.</li><li>Written schemes of examination under the UK Pressure Systems Safety Regulations 2000 for in-service work.</li><li>Client and duty holder specifications, which often sit on top of all of the above.</li></ul><p>Recording these as structured fields lets you find every open quote referencing a standard or a client specification revision, and carries the right codes into the project. The ERP's Procedures app keeps your procedures by method, standard and revision, so the quote can cite the procedure that will be used.</p><h2>Rate structures common in UK and European work</h2><p>Rate structures vary by sector and country, and the catalogue is built around the way you already charge. Common structures, in words:</p><ul><li>Day rates per technician level, with separate onshore and offshore rates.</li><li>Offshore rotations, with travel days, heliport reporting and waiting-on-weather days quoted as their own items.</li><li>Pre-mobilisation requirements for offshore work, such as survival training and offshore medicals, treated as pass-through or excluded, as your terms state.</li><li>Framework schedules of rates with call-off orders, sometimes with rate reviews tied to an index.</li><li>Overtime, weekend and night premiums as multipliers on the base rate.</li><li>Subsistence, accommodation and mileage for onshore site work.</li><li>Unit rates for fabrication, such as per weld, per radiograph or per length of weld scanned.</li><li>Equipment rates for PAUT, TOFD and eddy current systems where the client wants them itemised.</li></ul><p>For cross-border assignments inside the EU, sending technicians to another member state brings posting of workers obligations and social security documentation. These affect lead times and cost, and your quote should state the assumptions. Each item appears as its own line, and a global discount is available for agreed concessions.</p><h2>Radiography and site safety obligations</h2><p>Radiography scope carries regulatory commitments that belong in your assumptions. In Great Britain, industrial radiography falls under the Ionising Radiations Regulations 2017, which require consent from the HSE for industrial radiography, local rules and advice from a Radiation Protection Adviser. Across the EU, the Basic Safety Standards Directive 2013/59/Euratom is implemented through national rules and regulators. Moving sources by road brings ADR dangerous goods requirements.</p><p>Your quote should state that radiography is performed under your authorisation, how controlled areas will be established, and which shooting windows the client will provide. Offshore, the duty holder's safety case and permit-to-work system set the pace of work, and your quote should be clear about standby when permits are delayed.</p><p>In the ERP, the employee NDT profile holds radiation safety training, radiation badge number and medical fitness expiry. Fleet records hold whether a vehicle can carry radioactive sources, with the transport licence number and expiry. When a quote promises a radiography crew on given dates, operations can check both people and vehicles before mobilisation rather than on the morning of the job.</p><h2>VAT, currencies and payment terms configured locally</h2><p>VAT treatment differs between the UK and each EU member state, and cross-border inspection work adds place-of-supply questions. Many business-to-business services supplied across borders fall under the reverse charge, while some services connected with land and buildings are taxed where the property is. Whether your inspection work falls under one rule or the other is a question for your tax adviser. During implementation we configure taxes and fiscal positions following their advice, so the right VAT treatment appears on each quote. We make no tax certification claims.</p><p>Currencies are configured per client, so a UK company can quote pounds sterling at home, euros into the eurozone and Norwegian kroner for Norwegian shelf work, with the currency printed on the branded PDF. Payment terms are set per customer, recognising that UK and EU late payment legislation sets a baseline while large operators often impose their own terms through supplier portals.</p><p>If clients expect quotes in their own language, Odoo supports multiple languages, and translated layouts and standard terms can form part of the customization scope.</p><h2>GDPR and technician data in tenders</h2><p>European tenders frequently ask for CVs and certificates of named personnel. That is personal data, and GDPR, or UK GDPR, applies to how you collect, store and share it. Sending technician CVs around by email and keeping copies in shared folders makes it hard to know who holds what.</p><p>Keeping certificates and technician records inside the ERP, with Odoo's standard access rights, means estimators can see what they need to support a tender while access to wider personal data is limited by role. Sharing only what the tender asks for, and knowing where the source record lives, is easier when there is one source. Hosting location and data handling arrangements are agreed with you during implementation. We do not claim that installing any software makes you compliant; your data protection responsibilities remain yours.</p><h2>Branded quotes, online acceptance and 3D deliverables</h2><p>The custom branded quotation PDF presents job type, site, project dates and applicable codes up front, then lines, VAT, discount and your standard terms, in your house style. For framework tenders it becomes the technical and commercial response; for fabricators it is the quote they sign.</p><p>Odoo's standard online acceptance sends clients a link to their quote in your customer portal. They can ask questions on the quote's message thread and accept with an online signature. The acceptance is recorded and the quote converts to a sales order, giving you a dated record of what was agreed while the client's purchase order is raised.</p><p>Where operators want inspection results in 3D, Atlantis's companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places results on a 3D model of the asset and works alongside the ERP's NDT Reports app. It is a separate product and can be quoted as a line in your catalogue.</p><h2>From accepted quote to job and invoice</h2><p>Once a quote converts, the rest of <a href=\"/erp\">Atlantis NDT ERP</a> picks it up. The project carries job type, site, client PO, methods, codes and scope. Team Assignments dispatches crews against the dates, blocks double-booking of technicians and equipment serial numbers, and warns when assigned equipment is out of calibration. Timesheets record inspection, travel, standby and setup hours and warn if a certificate is not valid. <a href=\"/erp/apps/invoicing\">Invoicing</a> then carries the project, PO and site, with labour, equipment and consumables subtotals that mirror the quote. The full module list is on the <a href=\"/erp/apps\">ERP apps</a> page.</p><h2>Setting up Quotations for a UK or European NDT company</h2><p>Implementation covers framework schedules of rates loaded as client pricing, the service catalogue by method and category including offshore and rotation items, job types by route to market, a codes library of EN ISO standards and client specifications, the branded PDF with your radiography and offshore clauses, VAT and currencies following your adviser, payment terms, and online acceptance. We import open quotes and train your team. Anything further, such as translated layouts, is agreed as customization scope. The ERP is affordable, accessible and fully customizable, and implementation is quote on request. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20Europe\">Book a UK and Europe Quotations demo</a>.</p><h2>Frequently asked questions</h2><h3>Can the ERP record PCN and other EN ISO 9712 certificates?</h3><p>Yes. The Certificates app records ISO 9712, PCN, CSWIP, SNT-TC-1A, CP-189 and other schemes with level, method, certifying body and expiry. Atlantis NDT does not train or certify for these third-party schemes; its training is based on SNT-TC-1A.</p><h3>Can one company quote in pounds, euros and kroner?</h3><p>Yes. Currencies are configured during implementation, and each quote uses the client's currency on the branded PDF.</p><h3>How is cross-border VAT handled?</h3><p>Taxes and fiscal positions, including reverse charge where your adviser says it applies, are configured during implementation. No tax certification is claimed.</p><h3>Does it connect to Achilles or Constructionline?</h3><p>No. The ERP holds the company and personnel certificates you submit to those schemes, with expiry alerts, so your registrations stay current.</p><h3>Can a client accept a quote online?</h3><p>Yes. Clients sign through the customer portal; the acceptance is recorded and the quote converts to a sales order.</p><h3>What does it cost?</h3><p>Quote on request, depending on users, apps and customization. <a href=\"/contact?service=erp&amp;subject=Quotations%20quote%20request%20Europe\">Request a quote</a>.</p><h2>See a framework call-off built in the system</h2><p>Send us a recent tender response or framework call-off, and we will show you how it would be priced, presented, accepted and carried into dispatch and invoicing in Atlantis NDT ERP. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20Europe\">Arrange a demo</a>.</p>\n<h2>Quotations by region</h2><ul><li><a href=\"/erp/apps/quotations\">Quotations global overview</a></li><li><a href=\"/erp/apps/quotations/usa\">Quotations in United States</a></li><li><a href=\"/erp/apps/quotations/canada\">Quotations in Canada</a></li><li><a href=\"/erp/apps/quotations/middle-east\">Quotations in Middle East</a></li><li><a href=\"/erp/apps/quotations/india\">Quotations in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(UK%20%26%20Europe)\">Send an enquiry about Quotations</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/quotations/middle-east","publishedAt":"2026-09-27","title":"NDT Quotation Software for the Middle East | Atlantis NDT","description":"NDT quotation software for Gulf contractors: Aramco and ADNOC scopes, turnaround crews, VAT set up per country, online acceptance. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Quotation Software for Inspection Companies in the Middle East</h1>\n<p>Inspection quotes built from rates, crews and scope, sent for e-signature. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work is quoted in the Gulf</h2><p>NDT companies in Saudi Arabia, the UAE, Qatar, Kuwait, Oman and Bahrain quote into a market dominated by national oil and gas companies, their petrochemical affiliates, and the EPC contractors building for them. Saudi Aramco, SABIC, ADNOC, QatarEnergy, KNPC and KOC and their peers set the specifications, approve the contractors and control the calendar. Much of the work comes through long-term inspection service contracts, call-off orders against a schedule of rates, EPC subcontracts on new construction, and short, intense shutdown and turnaround campaigns.</p><p>Crews are large and mostly expatriate. A single turnaround quote can commit dozens of technicians from several countries, each needing a visa or residency permit, site access approval, client personnel approval and accommodation. The quote is not just a price; it is a promise that all of that will be in place on a date the owner fixed months ago.</p><p>The Quotations app in Atlantis NDT ERP gives estimators one structure for that promise. Every quote carries job type, site, project dates and applicable codes. Lines come from an NDT service catalogue flagged by method and category. A global discount handles negotiated concessions, the custom branded PDF presents the offer in your house style, and Odoo's standard online acceptance lets the client sign and convert it to a sales order. This page explains how that fits Gulf contracting practice.</p><h2>Contractor approval and vendor registration</h2><p>Nothing gets quoted to a national oil company until you are registered. Saudi Aramco runs supplier registration and approves inspection contractors, and NDT technicians working on its facilities must also be qualified under Aramco's own personnel qualification procedures in the SAEP series before they can work. ADNOC, QatarEnergy, KNPC, KOC and others operate their own vendor registration, and Oman uses a joint supplier registration system for oil and gas buyers.</p><p>Local content now sits inside evaluation. Aramco's IKTVA programme and ADNOC's In-Country Value programme score suppliers on local spending, localisation and workforce, and Saudization requirements under Nitaqat affect how you staff. Your quote often has to reflect these commitments, not just the rates.</p><p>The ERP does not connect to any national oil company registration portal. What it does is keep the evidence behind your registration current. The Certificates app records company certifications, such as ISO management system certificates and client approvals, with alert days. Technician certifications are recorded with scheme, level, method, certifying body and expiry, and attachments can hold client-issued approval letters. Warnings are raised 90 days before expiry, so the technician you name in a bid is not quietly lapsing while the bid is under evaluation.</p><h2>Specifications and codes on Gulf quotes</h2><p>Gulf clients write detailed specifications, and the applicable codes field is where you record which ones apply. Common entries include:</p><ul><li>Saudi Aramco Engineering Standards (SAES), including the welding standards in the SAES-W series, with Saudi Aramco Engineering Procedures (SAEP), Typical Inspection Plans (SATIP) and Inspection Checklists (SAIC) governing how inspection is carried out and recorded.</li><li>ADNOC group engineering specifications, and the equivalent company standards at QatarEnergy, KNPC and KOC.</li><li>ASME Section V, Section VIII and B31.3, which most client specifications reference for methods and acceptance.</li><li>API 1104 for pipeline welding, and API 510, API 570 and API 653 for in-service inspection of vessels, piping and tanks.</li><li>Project specifications issued by the EPC contractor on new construction packages.</li></ul><p>Recording these as structured data means you can find every open quote that references a particular client standard, and you can check whether a newly issued revision affects bids still under evaluation. When the job converts, the codes pass to the project, so technicians work to what the client bought.</p><p>The ERP's Procedures app keeps your procedures by method, standard and revision, with an approval workflow. Gulf clients commonly require procedure submission and approval before work starts, so being able to cite an approved revision on the quote saves a round of questions.</p><h2>Qualifications behind the quote: ASNT and ISO 9712</h2><p>Gulf clients accept both employer-based certification under ASNT SNT-TC-1A or CP-189 and third-party certification under ISO 9712, and a crew often mixes the two, plus client-specific approvals layered on top. The Certificates app records each scheme separately against the technician, with level, method and expiry, alongside vision tests with near vision, colour perception and expiry.</p><p>Atlantis NDT offers training based on ASNT SNT-TC-1A. It does not train or certify for ISO 9712 or any client's own qualification process; the ERP records those certificates and approvals held by your technicians.</p><p>Where the quote names a crew, the Level III reviewing it can check each person's scheme and level against the client specification before submission. It is far cheaper to find a gap at quote stage than when the client's inspection department rejects a technician at the gate.</p><h2>Quoting large expatriate crews</h2><p>Mobilising expatriate technicians is often the longest lead item on a Gulf job. Visas, residency permits such as the Saudi iqama or the Emirates ID, work permits, medicals, site passes, client personnel approvals and camp accommodation all need time. A quote that promises a start date without stating these assumptions invites disputes.</p><p>Your standard terms, set up during implementation, can state mobilisation lead times, who arranges visas and site passes, whether accommodation and transport are provided by the client or by you, and what happens if the client's approval process delays a technician. Standard Odoo employee records include visa and work permit numbers and expiry dates, and the Certificates app holds certification and vision test expiry, so operations can check document validity for the people they plan to send.</p><p>The availability calendar in Team Assignments records leave, training and unavailability, which matters for crews on long rotations with home leave. Double-booking of technicians is blocked, so the same person cannot be promised to two turnarounds on overlapping dates.</p><h2>Rate structures in Gulf NDT contracts</h2><p>Gulf rate structures are distinctive. Common patterns we configure, described in words:</p><ul><li>Monthly rates per technician for long-term inspection service contracts and resident inspector arrangements.</li><li>Day rates per technician level for shutdowns and turnarounds, often with separate night-shift rates.</li><li>Call-off orders against a contracted schedule of rates.</li><li>Unit rates for EPC construction work, such as per weld joint radiographed or per length of weld scanned by PAUT or AUT.</li><li>Lump-sum packages for defined scopes.</li><li>Overtime beyond standard hours, plus premiums for weekends and public holidays, as multipliers on the base rate.</li><li>Mobilisation items covering visas, flights, medicals and site induction, and accommodation and transport where you provide them.</li><li>Equipment rates for PAUT, TOFD, eddy current and CR systems where the client wants them itemised.</li></ul><p>Commercial terms often include retention, performance bonds or bank guarantees, and long payment cycles. These belong in the quote's terms so finance can plan cash flow. A global discount is available for concessions agreed in negotiation.</p><h2>Turnaround season, summer rules and radiography</h2><p>Turnarounds and shutdowns tend to cluster in the cooler months, when every contractor in the region competes for the same technicians. Summer brings midday outdoor work restrictions in several Gulf states, and Ramadan brings reduced working hours. Each affects productivity and duration, and your quote should say how. Filtering open quotes by job type and project dates shows where your bids overlap before you commit crews twice.</p><p>Radiography is licensed by national regulators, such as the Nuclear and Radiological Regulatory Commission in Saudi Arabia and the Federal Authority for Nuclear Regulation in the UAE. On live plants it is frequently restricted to night shifts with barrier areas. Your assumptions should state the licence you work under, the shooting windows you need and how standby is charged when permits are late.</p><p>The employee NDT profile holds radiation safety training, radiation badge number and medical fitness expiry, and Fleet records whether a vehicle can carry radioactive sources, with its transport licence and expiry.</p><h2>VAT, currencies and bilingual quotes configured locally</h2><p>VAT differs across the region. Saudi Arabia, the UAE, Bahrain and Oman have introduced VAT; at the time of writing, Qatar and Kuwait have not. Your tax adviser tells us how each client and site should be treated, and during implementation we configure taxes and fiscal positions so the right VAT appears on each quote and invoice. National e-invoicing requirements are not among the app's built-in features and should be discussed with your tax advisers; we make no tax certification claims.</p><p>Currencies are configured per client, so you can quote Saudi riyals, UAE dirhams or US dollars as the contract requires. Many clients expect Arabic alongside English; Odoo supports Arabic, and a bilingual quotation layout can be part of the customization scope.</p><h2>Branded quotes, online acceptance and 3D deliverables</h2><p>The custom branded quotation PDF presents job type, site, dates and codes up front, then lines, VAT, discount and terms. For EPC subcontracts, it is often the whole offer; for national oil company tenders, it supports the client's own commercial format. Odoo's standard online acceptance lets a client representative sign through your customer portal, and the quote converts to a sales order while the formal purchase order is processed.</p><p>Where owners want inspection results visible in 3D, Atlantis's companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places results on a 3D model of the asset and works alongside the ERP's NDT Reports app. It is a separate product and can be quoted as a line in your catalogue.</p><h2>From accepted quote to crew on site</h2><p>Once the quote converts, the rest of <a href=\"/erp\">Atlantis NDT ERP</a> takes over. The project carries job type, site, client PO, methods, codes, scope, and safety induction and work permit fields. Team Assignments dispatches crews against the dates, records mobilisation and demobilisation, and warns when assigned equipment is out of calibration. Timesheets record inspection, travel, standby and setup hours and warn when a certificate is not valid. <a href=\"/erp/apps/invoicing\">Invoicing</a> carries project, PO and site, with labour, equipment and consumables subtotals matching the quote. See every module on the <a href=\"/erp/apps\">ERP apps</a> page.</p><h2>Setting up Quotations for a Gulf NDT company</h2><p>Implementation covers schedules of rates loaded as client pricing; the catalogue by method and category, including mobilisation, visa and accommodation items; job types for long-term contracts, call-offs, turnarounds and EPC work; a codes library of client standards and international codes; the branded PDF with your mobilisation, radiography and payment clauses; VAT and currencies per country following your adviser; and online acceptance. Bilingual layouts and other additions are agreed as customization scope. The ERP is affordable, accessible and fully customizable, and implementation is quote on request. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20Middle%20East\">Book a Middle East Quotations demo</a>.</p><h2>Quoting for EPC subcontracts and long-term inspection contracts</h2><p>Two contract types make up much of the Gulf NDT workload, and they need different quotes. The first is the EPC subcontract on a new-construction package: a refinery expansion, a gas processing train, a pipeline spread or a petrochemical plant. The EPC contractor, often headquartered in Korea, Europe, China or India, passes the owner's specifications down to you, adds its own project procedures, and expects a quote that fits its subcontract format. Weld volumes are high, the schedule is set by fabrication and erection progress, and your radiography and PAUT capacity has to rise and fall with it.</p><p>For these packages, unit rates dominate. Catalogue lines for radiography per joint, PAUT or AUT per length of weld, and MT and PT per joint let an estimator build the quote from the EPC's weld summary rather than guessing crew days. The applicable codes field records both the owner's standards and the EPC's project specification, so when the owner's inspection department audits a report, the codes on the job trace back to what was quoted. Your terms should state how changes in weld volume are handled, how repair shots and re-examination after repairs are charged, and how long the client has to release joints for inspection before standby applies.</p><p>The second type is the long-term inspection service contract with the owner directly, typically covering a plant or a group of facilities over several years. Here the quote is really a manpower and equipment proposal: which positions, at which levels, with which methods, supported by which equipment, and priced per month or per day. Owners evaluate these offers on technical strength as well as price, and the technical part often asks for organisation charts, key personnel, procedures and equipment lists.</p><p>The Quotations app handles both by letting job type separate EPC packages from service contracts and call-offs, so managers can see which kind of work fills the pipeline. When a long-term contract is awarded, individual call-off orders can be quoted and accepted against the same client pricing, keeping the contracted schedule of rates in one place. Supporting evidence for the technical part, such as equipment calibration status from the Asset Management app and technician certifications from the Certificates app, comes from the same system, so the proposal and the operational records agree when the client's auditors compare them.</p><h2>Frequently asked questions</h2><h3>Can the ERP record Aramco personnel approvals alongside ASNT and ISO 9712 certificates?</h3><p>Yes. Each certification is recorded with scheme, level, method, certifying body and expiry, and client approval letters can be attached. The ERP records these; it does not grant or process client approvals.</p><h3>Does it handle VAT in Saudi Arabia and the UAE?</h3><p>Taxes are configured per country during implementation, following your adviser. No e-invoicing or tax certification is claimed.</p><h3>Can we quote monthly rates for long-term manpower contracts?</h3><p>Yes. Monthly, daily and unit rates are separate products and units of measure in your catalogue.</p><h3>Can quotes be in Arabic and English?</h3><p>Odoo supports Arabic. A bilingual layout can be included in your customization scope.</p><h3>Can a client representative accept online?</h3><p>Yes, through the customer portal with an online signature; the quote then converts to a sales order.</p><h3>What does it cost?</h3><p>Quote on request, based on users, apps and customization. <a href=\"/contact?service=erp&amp;subject=Quotations%20quote%20request%20Middle%20East\">Request a quote</a>.</p><h2>Prepare for the next turnaround season</h2><p>Send us a recent turnaround bid or call-off quote, and we will show you how it would be built, sent, accepted and staffed in Atlantis NDT ERP. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20Middle%20East\">Arrange your demo</a>.</p>\n<h2>Quotations by region</h2><ul><li><a href=\"/erp/apps/quotations\">Quotations global overview</a></li><li><a href=\"/erp/apps/quotations/usa\">Quotations in United States</a></li><li><a href=\"/erp/apps/quotations/canada\">Quotations in Canada</a></li><li><a href=\"/erp/apps/quotations/europe\">Quotations in UK &amp; Europe</a></li><li><a href=\"/erp/apps/quotations/india\">Quotations in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(Middle%20East)\">Send an enquiry about Quotations</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/quotations/india","publishedAt":"2026-09-27","title":"NDT Quotation Software for India | Atlantis NDT","description":"Quote PSU tenders, IBR jobs and refinery shutdowns from one NDT quotation app with GST set up locally and online acceptance. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Quotation Software for Inspection Companies in India</h1>\n<p>Inspection quotes built from rates, crews and scope, sent for e-signature. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>How NDT work is quoted in India</h2><p>Indian NDT companies quote into two very different worlds. On one side are public sector undertakings: IOCL, BPCL, HPCL, ONGC, GAIL, NTPC, NPCIL and the state utilities, which buy almost everything through formal e-tenders. On the other are private refiners and petrochemical groups, fabrication shops, EPC contractors, shipyards, steel plants and power producers, who buy through enquiries, negotiation and purchase orders. Large refinery complexes such as Jamnagar, Panipat, Mathura, Kochi, Paradip and Visakhapatnam run both kinds of work, and fabrication hubs around Vadodara, Hazira, Pune and Chennai generate a steady flow of shop inspection.</p><p>Regulation shapes the scope. Boiler work falls under the Indian Boiler Regulations and the state boiler inspectorates. Pressure vessels for compressed gases fall under PESO. Industrial radiography is licensed by AERB. Oil and gas clients add OISD standards and their own specifications, and many projects are engineered by consultants such as EIL whose specifications travel with the enquiry.</p><p>The Quotations app in Atlantis NDT ERP gives estimators one structure for both worlds. Every quote carries job type, site, project dates and applicable codes. Lines come from an NDT service catalogue flagged by method and category. A global discount handles negotiated concessions, the custom branded PDF presents it in your format, and Odoo's standard online acceptance lets the client sign and convert it to a sales order. Atlantis NDT works from Hyderabad as well as Houston, so these are the realities we set the app up for.</p><h2>PSU tenders and e-procurement</h2><p>PSU work is won through e-tenders published on the Central Public Procurement Portal, the Government e-Marketplace and each company's own e-procurement portal. Most follow a two-bid system: a techno-commercial bid proving you meet the qualification criteria, and a separate price bid submitted in the tender's own schedule of rates. Qualification criteria usually test similar work experience, financial capacity and personnel qualifications, and evaluation of qualified bidders commonly goes to the lowest price, sometimes through a reverse auction.</p><p>Tenders ask for an earnest money deposit and, on award, a performance bank guarantee, with exemptions for eligible MSEs registered on Udyam. These tie up cash and belong in your internal costing.</p><p>Because the price bid goes into the portal in the client's format, the Quotations app plays a different role here. It is where you build and review the estimate using your standard catalogue, record the job type, site, dates and applicable codes, and keep a single internal record of what was bid. When you win, the same quote is confirmed as a sales order, so the job starts from what you actually bid rather than from a spreadsheet saved on someone's laptop.</p><p>Filtering quotes by job type and dates shows which tenders are open, which are under evaluation and which have been awarded, so your management can see the bid pipeline in one view.</p><h2>Vendor enlistment and client documentation</h2><p>Beyond individual tenders, PSUs and large private owners maintain approved vendor lists, and EPC consultants maintain their own. Enlistment asks for company registrations, ISO certificates, lists of equipment with calibration status, and personnel with their qualifications. Radiography contractors must show their AERB authorisations.</p><p>The ERP does not connect to any client's vendor portal. What it does is keep the evidence current. The Certificates app records company certifications with alert days, and technician certifications with scheme, level, method, certifying body and expiry, with warnings 90 days before expiry. Calibration certificates for your instruments sit in the Asset Management app with valid, expiring and expired status. When a client asks for your equipment list with calibration, or the certificates of the crew you proposed, you produce them from one place.</p><p>Many Indian jobs also involve a third-party inspection agency witnessing on behalf of the owner. Your quote should state how witness points will be scheduled and whether waiting time for the TPI is chargeable, because that is one of the most common sources of disputed standby.</p><h2>Personnel certification: ISO 9712 and ASNT</h2><p>Indian clients accept both certification routes. Third-party ISO 9712 certification is available through the ISNT national certification scheme, and employer-based certification under ASNT SNT-TC-1A is widespread, especially with private and export-oriented clients. Technicians who have worked in the Gulf or Europe may also hold PCN or other ISO 9712 certificates. Tenders usually specify which is acceptable, sometimes by method and level.</p><p>The Certificates app records each scheme separately against the technician, with level, method, issue and expiry dates and attachments, plus vision tests with near vision, colour perception and expiry. When a tender asks for a Level II in RT and a Level III to interpret, the Level III reviewing the bid can check the qualification of the people you intend to name.</p><p>On training: Atlantis NDT offers training based on ASNT SNT-TC-1A only. It does not train or certify under ISO 9712, ISNT or PCN schemes; the ERP simply records the certificates your technicians hold.</p><h2>Codes and regulations on Indian quotes</h2><p>The applicable codes field records what the work is performed to. Common entries include:</p><ul><li>The Indian Boiler Regulations for boiler and steam piping work, where inspectorate requirements shape the extent of radiography and the documentation you deliver.</li><li>PESO requirements under the Static and Mobile Pressure Vessels (Unfired) Rules for vessels storing compressed gases.</li><li>ASME Section V, Section VIII and B31.3, which most refinery and petrochemical specifications reference.</li><li>API 1104 for cross-country pipelines, and API 510, API 570 and API 653 for in-service inspection.</li><li>OISD standards for inspection in oil and gas installations.</li><li>Owner and consultant specifications, such as those issued by EIL or the PSU's own engineering department.</li></ul><p>Recording these as structured data lets you find every open bid that references a given specification, and carries the right codes into the project when the work is awarded. The ERP's Procedures app keeps your procedures by method, standard and revision, so the quote can cite an approved procedure, which clients and TPI agencies routinely ask to review.</p><h2>Rate structures common in Indian NDT work</h2><p>Indian rate structures have their own conventions, and the catalogue is set up with the units you already use. Common patterns, in words:</p><ul><li>Radiography unit rates per joint or per film, often varying by pipe size or film size, and rates per inch-dia on piping work.</li><li>Ultrasonic thickness gauging rates per point or per location.</li><li>Day rates per technician level for shutdowns, with separate Level III rates for interpretation and review.</li><li>Monthly manpower rates for resident technicians on long projects.</li><li>Lump-sum packages for defined fabrication or small plant jobs.</li><li>Night-shift premiums for radiography that has to be done outside working hours.</li><li>Mobilisation, travel, lodging and boarding, where commonly the client provides some items and the contractor others.</li><li>Consumables such as film, chemicals and CR plates, either included or charged separately.</li></ul><p>Odoo's units of measure let you define units such as inch-dia so the quote reads naturally to the client. Each item appears as its own line, and a global discount is available when you agree a concession in negotiation.</p><h2>Radiography, AERB and site safety</h2><p>Radiography in India needs AERB authorisation, managed through the e-LORA system, and each site radiography operation needs a Radiological Safety Officer and trained personnel. Moving sources between sites has its own transport requirements. Your quote should state the authorisation you work under, how cordons will be set up, which shooting windows the client will give, and how standby is charged when work permits are delayed.</p><p>Refinery and petrochemical sites add gate passes, safety induction, medical fitness and work permits, all of which take time before productive work. The ERP's employee NDT profile holds radiation safety training, radiation badge number and medical fitness expiry, and Fleet records whether a vehicle can carry radioactive sources, with transport licence and expiry. Operations can check both before committing a crew named in a quote.</p><h2>GST, TDS and payment terms configured locally</h2><p>NDT services attract GST, and the split between CGST and SGST or IGST depends on place of supply. For services connected with immovable property, such as work at a client's plant, the location of the site can determine place of supply, which matters when your registration is in one state and the job is in another. Your chartered accountant decides the treatment; during implementation we configure taxes, fiscal positions and the service classification codes they specify, so the right GST appears on each quote. GST e-invoicing is not among the app's built-in features, and we make no tax certification claims.</p><p>Clients commonly deduct TDS, and PSUs often have long payment cycles tied to bill certification by the engineer-in-charge. Payment terms, retention and bank guarantee conditions can be recorded in the quote's terms so finance knows what cash to expect and when.</p><h2>Technician data and the DPDP Act</h2><p>Tenders and vendor enlistments ask for personnel lists, CVs and certificates. The Digital Personal Data Protection Act, 2023 applies to how you handle that personal data. Keeping it in the ERP with Odoo's standard access rights limits who can see what, and means you share only what a tender asks for from one source record. Hosting and data handling arrangements are agreed during implementation; compliance obligations remain yours.</p><h2>Branded quotes, online acceptance and 3D deliverables</h2><p>For private clients and EPCs, the custom branded quotation PDF is the offer itself, presenting job type, site, dates and codes up front, then lines, GST, discount and terms. Odoo's standard online acceptance lets the client sign through your customer portal, and the quote converts to a sales order while the formal PO is raised.</p><p>Where owners want inspection results in 3D, Atlantis's companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places results on a 3D model of the asset and works alongside the ERP's NDT Reports app. It is a separate product and can be quoted as a line in your catalogue.</p><h2>From accepted quote to job and invoice</h2><p>Once the quote converts, the rest of <a href=\"/erp\">Atlantis NDT ERP</a> picks it up: the project with job type, site, PO, methods, codes and scope; Team Assignments with double-booking blocked and calibration warnings; timesheets that warn on invalid certificates; and <a href=\"/erp/apps/invoicing\">Invoicing</a> with labour, equipment and consumables subtotals that mirror the quote. See every module on the <a href=\"/erp/apps\">ERP apps</a> page.</p><h2>Setting up Quotations for an Indian NDT company</h2><p>Implementation covers your catalogue by method and category with Indian units such as per joint and inch-dia; job types for PSU tenders, private enquiries, shutdowns and shop work; a codes library covering IBR, PESO, ASME, API, OISD and client specifications; the branded PDF with your radiography, TPI and payment clauses; GST following your accountant; and online acceptance. Anything further is agreed as customization scope. The ERP is affordable, accessible and fully customizable, and implementation is quote on request. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20India\">Book an India Quotations demo</a>.</p><h2>Quoting private refiners, EPCs and fabrication shops</h2><p>Private-sector NDT work in India moves faster than PSU tenders and is won differently. A private refiner or petrochemical group may send an enquiry for a shutdown a few weeks out, ask several approved vendors for offers, and then negotiate on scope, crew and commercial terms before issuing a purchase order. EPC contractors building for PSUs or private owners send enquiries against a weld summary and a project specification. Fabrication shops making pressure vessels, heat exchangers, piping spools and structures for domestic and export orders want quick offers for radiography, UT, MT and PT, often with a tight delivery date driven by their own customer.</p><p>Each of these needs a quote that is fast to build and precise about scope. For shutdowns, the offer usually rests on crew make-up by level and method, shift pattern, equipment, and who provides lodging, boarding and local transport. For EPC packages, unit rates from your catalogue let the estimator work straight from the client's weld summary. For fabrication shops, the job type and site make it clear whether the work is done in the client's shop or at your facility, and whether the client's inspector or a third-party agency will witness.</p><p>Export fabrication brings another layer. A shop building to ASME for an overseas buyer may ask for personnel certified under ASNT SNT-TC-1A or under ISO 9712, depending on the buyer's specification, and for procedures that the buyer's inspector will review. The applicable codes field records the code and the buyer's specification, and your standard terms can state the certification basis you offer, so there is no confusion when the buyer's inspector arrives at the shop.</p><p>Negotiation is normal in the private sector, and revisions are common. Each change is visible in the quote's history, so you can see what moved between the first offer and the one accepted. The global discount handles a negotiated concession without rewriting every line, which keeps the underlying rates visible for the next enquiry from the same client. Once the client agrees, online acceptance gives you a dated confirmation while the purchase order is raised, and the confirmed quote becomes the sales order that operations and finance work from.</p><h2>Frequently asked questions</h2><h3>Can we use the app for PSU e-tenders?</h3><p>Yes, as your internal estimate and record. The price bid still goes into the tender portal in the client's format; on award, the quote converts to a sales order.</p><h3>Can it quote per inch-dia or per joint?</h3><p>Yes. Units of measure are configured during implementation, so lines can be priced per joint, per film, per point or per inch-dia.</p><h3>How is GST handled?</h3><p>CGST, SGST and IGST are configured following your accountant's rules. GST e-invoicing is not a built-in feature and no tax certification is claimed.</p><h3>Can the ERP record ISNT and ASNT certificates together?</h3><p>Yes. Each scheme is recorded with level, method and expiry. Atlantis NDT's own training is based on SNT-TC-1A only.</p><h3>Can a private client accept online?</h3><p>Yes, through the customer portal with an online signature; the quote then converts to a sales order.</p><h3>What does it cost?</h3><p>Quote on request, based on users, apps and customization. <a href=\"/contact?service=erp&amp;subject=Quotations%20quote%20request%20India\">Request a quote</a>.</p><h2>Bring your next tender or shutdown enquiry</h2><p>Send us a recent PSU bid or private enquiry, and we will show you how it would be estimated, presented, accepted and carried into dispatch and invoicing in Atlantis NDT ERP. <a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20India\">Arrange your demo</a>.</p>\n<h2>Quotations by region</h2><ul><li><a href=\"/erp/apps/quotations\">Quotations global overview</a></li><li><a href=\"/erp/apps/quotations/usa\">Quotations in United States</a></li><li><a href=\"/erp/apps/quotations/canada\">Quotations in Canada</a></li><li><a href=\"/erp/apps/quotations/europe\">Quotations in UK &amp; Europe</a></li><li><a href=\"/erp/apps/quotations/middle-east\">Quotations in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/crm\">CRM</a>: Leads and opportunities for inspection, training and consulting work.</li><li><a href=\"/erp/apps/contacts\">Contacts</a>: One address book for clients, sites, vendors and technicians.</li><li><a href=\"/erp/apps/ai-marketing\">AI Marketing</a>: AI-assisted outreach and campaign content for NDT buyers.</li><li><a href=\"/erp/apps/email-marketing\">Email Marketing</a>: Newsletters and campaigns to clients and prospects.</li><li><a href=\"/erp/apps/business-cards\">Business Cards</a>: Scan business cards from site visits and trade shows straight into CRM.</li><li><a href=\"/erp/apps/website\">Website</a>: Company website and enquiry forms connected to CRM.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Quotations%20demo%20(India)\">Send an enquiry about Quotations</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/team-assignments","publishedAt":"2026-09-27","title":"NDT Crew Dispatch & Technician Scheduling | Atlantis NDT","description":"Dispatch NDT crews without double-booking technicians or out-of-calibration kit. Availability, utilisation and job status in one ERP. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Crew Dispatch and Technician Scheduling Software</h1>\n<p>Assign qualified technicians and crews to jobs by method, level and availability. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>The scheduling problem every NDT company knows</h2><p>It is 4 p.m. on a Thursday. A client calls: they need two UT Level IIs and a PAUT technician on site on Monday for a weld campaign. Your operations manager opens the whiteboard, the shared spreadsheet and three WhatsApp groups, and starts ringing round. One technician looks free but is actually booked on a refresher course. Another is free, but the phased array set he usually takes is already promised to a different job. The third is available, and so is the flaw detector, until someone notices on Monday morning that its calibration lapsed last week.</p><p>None of this is unusual. NDT dispatch is hard because three things have to line up at once: the right people, holding the right certifications, carrying the right calibrated equipment, at the right site on the right dates. Most companies keep those three things in three different places, and the dispatcher is the only person who joins them together, usually in their head.</p><p>When that person is on leave, or when a turnaround pushes you to thirty jobs a week instead of ten, the gaps show. Technicians get double-booked. A probe goes to two sites on paper and one site in reality. A client audit asks who was on a job three months ago and nobody can say for sure. Team Assignments exists to take that joining-up out of people's heads and put it in one system that says no when something does not fit.</p><h2>What Team Assignments does</h2><p>Team Assignments is the dispatch and scheduling app inside <a href=\"/erp\">Atlantis NDT ERP</a>, our Odoo-based ERP pre-configured for inspection companies. Each job becomes a team assignment: a record that ties together the client work, the site, the dates, the technicians and the equipment serial numbers going with them.</p><p>Out of the box it gives you:</p><ul><li><strong>A dispatch workflow</strong> that moves every assignment through planned, dispatched, in field, submitted and closed, so anyone can see where a job stands.</li><li><strong>Site details</strong> including GPS coordinates and mobilisation and demobilisation dates, so travel and site time are planned, not guessed.</li><li><strong>A technician availability calendar</strong> with assigned, leave, training, sick and unavailable entries. Overlapping entries are blocked.</li><li><strong>Double-booking protection</strong> for both technicians and equipment serial numbers. If a person or an instrument is already committed for those dates, the system stops the second booking.</li><li><strong>A calibration warning</strong> when an assigned piece of equipment is out of calibration.</li><li><strong>Technician status at a glance</strong>: current assignment, utilisation percentage and next available date.</li><li><strong>Calendar, kanban and list views</strong> so dispatchers, managers and supervisors each see the jobs in the way that suits their work.</li></ul><p>It is not a separate tool bolted onto your ERP. The technicians are the same employee records your HR and certification data sits on, the equipment is the same serial-numbered inventory your calibration records sit on, and the hours booked on site flow into the same timesheets you invoice from. That is the point: one record of who went where, with what, and when.</p><h2>How a job moves from planned to closed</h2><p>Every NDT company has its own habits, but the path of a field job is broadly the same. Team Assignments follows it with five stages.</p><ol><li><strong>Planned.</strong> The job is won or scheduled. The coordinator creates the assignment, enters the site, its GPS coordinates and the mobilisation and demobilisation dates, and starts picking technicians and equipment. At this stage the availability calendar and the clash checks are doing their work: a technician on leave or already assigned cannot be added, and an instrument serial already out on another job cannot be booked twice.</li><li><strong>Dispatched.</strong> The crew is confirmed and told to go. Moving the job to dispatched is the signal that people and kit are committed, travel is arranged and the site has been informed.</li><li><strong>In field.</strong> The crew is on site doing the inspection. The assignment now shows as their current assignment and their status reflects it, so anyone asking where a technician is gets an answer without phoning round.</li><li><strong>Submitted.</strong> The field work is done and results and paperwork are handed in for review. For many companies this is where the NDT report goes to a Level II or Level III reviewer.</li><li><strong>Closed.</strong> Reports are approved, equipment is back, timesheets are in and the job is ready for billing. Closing the assignment gives you a clean history of who did the work and with which instruments.</li></ol><p>The kanban view shows these stages as columns, so on a Monday morning the operations manager can see at once how many jobs are still waiting to be dispatched, how many crews are in the field and which submitted jobs are holding up invoicing. Stuck jobs become visible, rather than sitting in someone's inbox.</p><h2>A technician availability calendar that tells the truth</h2><p>Most scheduling mistakes come from an availability picture that is out of date. The technician told the office about his leave, but it went into an email, not the plan. The training department booked three people onto a refresher week and nobody told dispatch.</p><p>Team Assignments keeps one availability calendar per technician with five kinds of entry: assigned, leave, training, sick and unavailable. Assignments add themselves to it. Leave approved in the standard Time Off app feeds the same picture, so an approved holiday blocks that person from being dispatched without anyone copying it across. Training weeks, sick days and general unavailability, such as a medical appointment or a visa renewal trip, go in the same place.</p><p>Overlaps are blocked. You cannot put a technician on a job for dates they are already on leave, and you cannot book leave over dates they are already committed to a site without dealing with the clash first. That sounds simple, and it is, but it removes a whole class of Monday-morning surprises.</p><p>The calendar view is where most coordinators live. It shows who is out, who is on which job, and where the gaps are. When a client asks whether you can put three more technicians on a turnaround next month, you can look at real availability instead of making a guess and hoping the crew agrees later.</p><h2>Equipment clash checks and calibration warnings</h2><p>Technicians are only half the booking. A UT crew without a calibrated flaw detector, or a PAUT technician without the right probe and wedge, cannot start work. And equipment is where many NDT companies lose track, because instruments move between sites, get borrowed between crews and come back to the store at odd hours.</p><p>In Team Assignments, equipment is booked by serial number, the same serial numbers held in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>. If a specific flaw detector, yoke, exposure device, probe or thickness gauge is already assigned to another job over the same dates, the second booking is blocked. You find out at planning time, not when two crews both turn up at the store asking for the same instrument.</p><p>The app also warns when an assigned piece of equipment is out of calibration. Calibration records live in Asset Management, with the provider, certificate number, next due date and certificate status. When a coordinator attaches an instrument whose calibration has lapsed, the assignment flags it. That gives the office a chance to swap the unit or send it for calibration before it leaves, instead of a client's inspector spotting an expired sticker on site and stopping the work.</p><p>For NDT companies audited against their own quality system, this matters. A report issued with an out-of-calibration instrument is a report you may have to withdraw, followed by a re-inspection you pay for yourself. Catching it at dispatch is far cheaper than catching it afterwards.</p><h2>Utilisation, status and next available date</h2><p>Owners and operations managers ask the same questions every week. Who is sitting idle? Who is being run into the ground? When is the next person free who holds RT Level II?</p><p>Each technician record in Team Assignments shows the current status, the current assignment, a utilisation percentage and the next available date. Utilisation tells you how much of each person's time is committed to jobs, so you can spot the technician who has been on standby for three weeks as easily as the one who has not had a day off in a month. Next available date answers the most common question a salesperson asks dispatch: when can we start?</p><p>This is useful beyond the daily plan. When utilisation is high across the whole team for weeks at a time, that is evidence for hiring or for bringing in subcontract technicians. When it is low for a particular method, it may be time to push that service harder in sales, or to cross-train people in a method that is in demand. And when a client asks for a named technician, you can see straight away whether that person is free or when they will be.</p><p>Because the data comes from real assignments and real leave, not from a spreadsheet someone forgot to update, it holds up when you use it to make decisions.</p><h2>Who uses it, and how</h2><p>Team Assignments is built for the people who actually move crews around, with views that suit each role.</p><ul><li><strong>Dispatchers and operations coordinators</strong> work mainly in the calendar and kanban views. They create assignments, pick technicians and equipment, and push jobs through the stages.</li><li><strong>Operations managers</strong> use the list and kanban views to see the whole week or month: jobs waiting for crews, jobs in the field, jobs submitted but not closed.</li><li><strong>Level IIIs and QA/QC managers</strong> care about who is qualified for what. They work alongside dispatch through the <a href=\"/erp/apps/certificates\">Certificates app</a>, which tracks each technician's scheme, level, method and expiry, and warns 90 days before a cert or vision test lapses.</li><li><strong>Sales and account managers</strong> check next available dates and utilisation before promising a start date to a client.</li><li><strong>Owners</strong> look at utilisation across the team to judge whether the business is over- or under-staffed.</li><li><strong>Technicians</strong> see their own assignments, and field staff using the NDT Reports offline app can pull the jobs and equipment assigned to them.</li></ul><p>Access rights are set during implementation, so a technician sees their own jobs, a supervisor sees their crew and management sees everything. You decide who can create assignments, who can dispatch and who can close.</p><h2>How Team Assignments connects to the rest of the ERP</h2><p>Dispatch is the middle of an NDT job. Before it come the quote and the project; after it come the report, the timesheet and the invoice. Team Assignments sits between them.</p><ul><li><strong>Project</strong> holds the NDT job type, site, client PO, methods, codes, acceptance criteria and the safety induction and work permit fields your clients ask about.</li><li><strong>Certificates</strong> tracks each technician's certifications and vision tests. Timesheets warn when a technician's certificate is not valid, so an expired cert does not quietly get billed.</li><li><strong>Asset Management</strong> holds equipment serial numbers, issue and return, and calibration records, which is where the calibration warning comes from.</li><li><strong>Timesheets</strong> record inspection, travel, standby and setup hours by method, site and equipment serial, with a billable flag and a rate multiplier.</li><li><strong>Fleet</strong> records which vehicles may carry radioactive sources, with transport licence expiry, and assigns vehicles to projects.</li><li><strong>Expenses</strong> captures field expenses and per diems for re-billing to the job.</li><li><strong>Invoicing</strong> picks up billable hours and splits labour, equipment and consumables.</li></ul><p>In the field, the NDT Reports app captures method-specific results, with an offline field app that works without signal. Many clients now want more than a PDF, and that is where our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, comes in: it places inspection results on a 3D model of the asset, so an asset owner sees where each finding is rather than reading a list of weld numbers. It is a separate product that works alongside the ERP.</p><p>For crews still building skills, our <a href=\"/practical-ndt\">Practical NDT</a> platform gives learners immersive 3D practice on virtual welds, pipes, vessels and castings across UT, PAUT, RT, MT, PT, VT, ET and TOFD, opened from the eLearning portal. Training weeks can be entered in the availability calendar as training, so dispatch always knows who is off the plan.</p><h2>What implementation looks like</h2><p>Atlantis NDT sets up the ERP for you. We do not hand you a blank system and a manual. For Team Assignments, implementation usually covers:</p><ol><li><strong>Loading your people.</strong> Technician records with their NDT profile, methods and levels, and current certifications in the Certificates app.</li><li><strong>Loading your equipment.</strong> Instruments, probes and other kit by serial number, with current calibration dates, so clash checks and calibration warnings work from day one.</li><li><strong>Agreeing your stages.</strong> The five dispatch stages cover most companies. If you need extra checkpoints, such as a site pre-qualification step or client approval of named personnel, that is part of the customization scope agreed with you.</li><li><strong>Setting access rights</strong> for dispatchers, supervisors, managers and technicians.</li><li><strong>Connecting Time Off</strong> so approved leave blocks dispatch automatically.</li><li><strong>Training your coordinators</strong> on the calendar, kanban and list views, using your own live jobs rather than demo data.</li></ol><p>Most companies run the old whiteboard alongside the new system for a short period, then drop it once the team trusts that the calendar is right. Because the ERP is fully customizable, views, fields and reports can be shaped around how your operation already works rather than forcing you into someone else's process.</p><p>Pricing depends on your team size, the apps you need and the customization involved. It is quote on request, and we keep it affordable for small and mid-sized inspection companies as well as larger ones. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo\">Book a Team Assignments demo</a> and we will show it working with a sample of your own crew.</p><h2>Frequently asked questions</h2><h3>Can Team Assignments stop me double-booking a technician?</h3><p>Yes. If a technician is already assigned, or has leave, training, sick or unavailable time on those dates, the overlap is blocked. The same applies to equipment serial numbers: one instrument cannot be booked on two jobs for the same dates.</p><h3>Does it check whether equipment is calibrated?</h3><p>It warns you. When you assign an instrument whose calibration is out of date according to its record in Asset Management, the assignment shows a warning so you can swap the unit or send it for calibration before the crew leaves.</p><h3>Does it check technician certifications?</h3><p>Certification data lives in the Certificates app, which flags certs and vision tests expiring within 90 days and sends configurable email alerts. Timesheets warn when a technician's certificate is not valid. If you want a certification check built directly into the assignment step, that can be configured as part of your implementation scope.</p><h3>Can technicians see their jobs on a phone?</h3><p>Yes, through the NDT Reports offline field app, which can pull the jobs and equipment assigned to the logged-in technician and works without signal on site. Supervisors and coordinators can also use the ERP in a mobile browser.</p><h3>Which views does it offer?</h3><p>Calendar, kanban and list. Coordinators usually plan in the calendar, operations managers watch job stages on the kanban board, and the list view is handy for filtering jobs by client, site or status.</p><h3>Can it handle subcontract technicians?</h3><p>Yes. Subcontract or freelance technicians can be set up as records so their availability and assignments are tracked the same way as staff. How you handle their certifications and billing is agreed during implementation.</p><h3>How is it priced?</h3><p>Quote on request. The price depends on the number of users, the apps you choose and the level of customization. We keep it affordable and accessible for inspection companies of every size.</p><h2>See your own crew in it</h2><p>The quickest way to judge a scheduling tool is to see your own jobs in it. Send us a rough picture of your team: how many technicians, which methods, how many jobs a week and where you work. We will set up a demo with a sample of that data and walk your operations manager through a real week of dispatch, from planned to closed.</p><p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20quote\">Request a quote for Team Assignments</a> or ask for a walkthrough of the full Atlantis NDT ERP.</p>\n<h2>Team Assignments by region</h2><ul><li><a href=\"/erp/apps/team-assignments/usa\">Team Assignments in United States</a></li><li><a href=\"/erp/apps/team-assignments/canada\">Team Assignments in Canada</a></li><li><a href=\"/erp/apps/team-assignments/europe\">Team Assignments in UK &amp; Europe</a></li><li><a href=\"/erp/apps/team-assignments/middle-east\">Team Assignments in Middle East</a></li><li><a href=\"/erp/apps/team-assignments/india\">Team Assignments in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo\">Send an enquiry about Team Assignments</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/team-assignments/usa","publishedAt":"2026-09-27","title":"NDT Crew Scheduling Software in the USA | Atlantis NDT","description":"Schedule NDT crews for Gulf Coast turnarounds, pipeline spreads and plant work without double-booking techs or kit. Book a Team Assignments demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Crew Dispatch and Technician Scheduling in the USA</h1>\n<p>Assign qualified technicians and crews to jobs by method, level and availability. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(United%20States)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why NDT dispatch in the US is its own problem</h2><p>Running NDT crews in the United States means working across huge distances with a workforce that travels. A Houston inspection company may have technicians on a refinery unit in Pasadena, a tank farm in Corpus Christi, a pipeline spread in West Texas and a fabrication shop job in Louisiana in the same week. Many of those technicians are travellers on per diem, some are local hands who go home every night, and some are contract Level IIs who will take the best offer on the day.</p><p>Clients add their own layer. Refiners and chemical plants want named, qualified personnel, current site orientations and contractor prequalification before anyone reaches the gate. Pipeline operators want operator qualification records and drug and alcohol testing under DOT rules. Radiography work brings NRC or Agreement State licensing into the picture. And almost everyone wants the crew there on Monday.</p><p>Most US inspection companies still run this on a whiteboard, a spreadsheet and a lot of phone calls. That works until a turnaround season arrives and the jobs double. Team Assignments, part of <a href=\"/erp\">Atlantis NDT ERP</a>, replaces that patchwork with one scheduling record: the job, the site, the dates, the crew and the equipment serial numbers, with the system blocking double-bookings and warning about out-of-calibration kit before anyone gets in a truck.</p><h2>What Team Assignments gives a US inspection company</h2><ul><li>A dispatch workflow for every job: planned, dispatched, in field, submitted, closed.</li><li>Site GPS coordinates plus mobilisation and demobilisation dates, useful when the site is a pipeline right-of-way or a remote compressor station with no street address.</li><li>A technician availability calendar with assigned, leave, training, sick and unavailable entries, with overlaps blocked.</li><li>Double-booking blocked for technicians and for equipment serial numbers.</li><li>A warning when assigned equipment is out of calibration.</li><li>Technician status, current assignment, utilisation percentage and next available date.</li><li>Calendar, kanban and list views for dispatch, operations and management.</li></ul><p>The rest of this page is about how those features meet the realities of US field work: turnaround peaks, pipeline hitches, radiography licensing, employer certification and the paperwork it takes to get through a plant gate.</p><h2>Spring and fall turnaround seasons on the Gulf Coast</h2><p>Gulf Coast refiners and petrochemical plants tend to schedule major turnarounds in two windows: late winter into spring, and early fall. Owners try to finish maintenance before the summer driving season pushes gasoline demand up, and many avoid the peak of hurricane season, which runs from June to November. The result is predictable. Between roughly February and May, and again from September into November, every inspection company from Beaumont and Port Arthur to Lake Charles, Baton Rouge and Corpus Christi is chasing the same pool of UT, RT and PAUT technicians.</p><p>That is exactly when scheduling breaks down. Turnaround contracts get awarded late, scopes grow once units are opened, and the owner asks for extra crews with a day's notice. A dispatcher who is holding availability in their head will overcommit.</p><p>Team Assignments helps in three ways. First, the availability calendar shows real commitments weeks ahead, so when a planner asks whether you can supply six more technicians for a unit that opens in April, you can see who is actually free, not who you hope is free. Second, the next available date on each technician tells sales when a named person can start. Third, the clash checks stop a coordinator from committing the same PAUT set or the same RT Level II to two plants in the same week, however frantic the phones get.</p><p>When a storm shuts a plant or delays a start, the mobilisation dates can be moved and the knock-on is visible: if the new dates overlap later jobs for the same people or instruments, the overlap is blocked, so you deal with it now rather than finding out when two clients expect the same crew.</p><h2>Pipeline spreads, PHMSA and long hitches</h2><p>Pipeline work runs to a different rhythm. On a construction spread the weld inspection crew moves with the welding crews along the right-of-way, often working long hitches of six or seven days a week on ten- or twelve-hour shifts, with a rotation home after several weeks. Integrity digs on existing lines are shorter, scattered and often in rural locations with no useful address.</p><p>Site GPS coordinates on each assignment solve a small but real problem: the crew and the office both know exactly which dig site, valve station or tie-in point the job refers to. Mobilisation and demobilisation dates put travel days in the plan, so the technician driving from Houston to the Permian Basin is not shown as available on the day he is on the road.</p><p>Pipeline operators regulated by PHMSA under 49 CFR Parts 192 and 195 also expect contractor staff to meet operator qualification requirements for covered tasks and to be in a DOT drug and alcohol testing programme under 49 CFR Part 199. Team Assignments does not manage those programmes, but it does give you one place to see who is on which pipeline job and when. Recording OQ evaluations and testing status against each technician, and checking them at dispatch, is something we configure as part of your implementation scope if you need it.</p><p>Because the utilisation figure counts real assignments, it also shows when a spread has tied up most of your RT crew for weeks, which is the moment to turn down other radiography work or bring in subcontract help rather than overcommit.</p><h2>Radiography crews, NRC licensing and the two-person rule</h2><p>Field radiography in the US is licensed by the Nuclear Regulatory Commission or, in Agreement States such as Texas and Louisiana, by the state radiation control programme. Under 10 CFR Part 34 and the state equivalents, radiography outside a permanent facility needs at least two qualified people present: a radiographer plus at least one other radiographer or radiographer's assistant. Personal dosimetry, radiation safety training and source security all come with it.</p><p>For dispatch, that means an RT job is never one person and one camera. It is a pair of qualified people, an exposure device with a specific serial number, survey meters, and a vehicle allowed to carry the source. Team Assignments lets you book all of them on the same assignment. Double-booking protection covers the exposure device and meters by serial number just as it covers technicians, so the same camera cannot be on two jobs at once, and a warning appears if a survey meter or other instrument on the job is out of calibration.</p><p>The employee NDT profile, held alongside the <a href=\"/erp/apps/certificates\">Certificates app</a>, records radiation safety training and the radiation badge number for each technician, so the coordinator can see who is set up for RT work. The Fleet app records whether a vehicle can carry radioactive sources, with its transport licence number and expiry, and assigns vehicles to projects. Making sure every RT assignment has two qualified people remains the coordinator's call; if you want the system to enforce it, that rule can be added during implementation.</p><h2>SNT-TC-1A, CP-189 and the certifications clients audit</h2><p>Most US NDT companies certify their own technicians under an employer written practice based on ASNT SNT-TC-1A, and some work to the stricter ANSI/ASNT CP-189 standard. ASME Section V points back to these documents for personnel qualification, so any job built to ASME Section VIII or B31.3 can have an owner's inspector or Authorized Inspector checking that the technicians on site hold current certs for the method they are using. On API 510, 570 and 653 work, the API-certified inspector relies on your technicians' qualifications being in order too.</p><p>A dispatcher who sends a UT Level II whose certification lapsed last month has created a problem that shows up in an audit, often after the report has been issued. That is why Team Assignments works hand-in-hand with the Certificates app. Certificates holds the scheme, level, method, certifying body and expiry for each technician, calculates status automatically as active, expiring soon, expired or revoked, and creates warning tasks 90 days before a cert or vision test expires. Daily email alerts go to the people you choose. Timesheets then warn when a technician's cert is not valid, so a lapse is caught when hours are booked, not when the client disputes the invoice.</p><p>Aerospace shops working to NAS 410 have similar needs, with an emphasis on documented examinations and regular vision checks; both are recorded in Certificates, with exam scores against a passing score and vision tests with their own expiry.</p><p>Atlantis NDT also runs training built on ASNT SNT-TC-1A. Training weeks go into the availability calendar as training, so dispatch always knows who is off the plan.</p><h2>TWIC cards, site orientations and contractor prequalification</h2><p>Getting through the gate at a US plant is its own job. Facilities regulated under the Maritime Transportation Security Act, including many Gulf Coast refineries, chemical plants and marine terminals, require a TWIC card for unescorted access. Plants in the Houston and Louisiana corridors commonly require a regional basic safety orientation plus a site-specific orientation. Most owners also require contractors to be prequalified through a third-party platform such as ISNetworld or Avetta, and they want OSHA training records for the crew.</p><p>These requirements change what available means. A technician who is free but has no TWIC is not available for a marine terminal job. One whose site orientation has expired needs time for orientation before starting, and that should show in the mobilisation date.</p><p>The Project app already carries safety induction and work permit fields for each job, so the requirements of a specific site are written down where the coordinator will see them. On the scheduling side, orientation days can be booked in the availability calendar so they are not lost. Tracking the expiry of TWIC cards and site orientations per technician, and flagging them at dispatch, is typical of the customization we agree during implementation for US clients, because every company's client mix and document list is different.</p><p>The aim is simple: the crew that turns up at 6 a.m. gets through the gate, rather than spending the morning in the badging office while the client's clock runs.</p><h2>Equipment across multiple yards and branches</h2><p>Many US NDT companies run more than one yard: a main shop in Houston, a branch in Baton Rouge or Lake Charles, maybe a satellite office in the Permian. Instruments drift between them. A PAUT unit goes out from Houston, comes back through Louisiana, and ends up on a truck that nobody has logged.</p><p>In Team Assignments every piece of equipment is booked by serial number, the same serial held in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>. If that serial is already committed to another job for the same dates, the booking is blocked. If its calibration has lapsed, the assignment shows a warning. Asset Management adds the issue and return workflow, with condition recorded both ways and supervisor or manager approval, plus calibration certificates with next due dates and expiry alerts.</p><p>Put together, the coordinator can answer three questions without leaving the screen: is this instrument free, is it in calibration, and who has it now. That matters when the owner's inspector asks for the calibration certificate of the unit used on a particular weld, and it matters more when the unit is needed for a job in two days and turns out to be at the lab.</p><h2>Hours, overtime, per diem and utilisation</h2><p>Field technicians in the US are usually paid hourly, and overtime on turnarounds is normal. Clients are billed on day rates, hourly rates, standby and travel, often with different multipliers for overtime and weekends. Getting the hours right is where margin is won or lost.</p><p>Team Assignments feeds that process. Once a crew is in the field, technicians record hours in Timesheets by work type (inspection, travel, standby, setup), method, site and equipment serial, with a billable flag and a rate multiplier for overtime or premium hours. Those hours flow into Invoicing, which splits labour, equipment and consumables, with sales tax configured for the states you work in during implementation. Per diems and field expenses go through Expenses and can be re-billed to the job.</p><p>Utilisation on each technician record gives owners a view of the business that most spreadsheets never do: who is fully booked, who has been on standby, and whether the RT crew is carrying the company while the MT and PT crew sits idle. When turnaround season ends, it shows how quickly the team is being redeployed, or not.</p><h2>Reports, digital twins and technician skills</h2><p>Once a job moves to submitted, the report takes over. The NDT Reports app captures method-specific data for UT, RT, MT, PT, PAUT, TOFD and more, and its offline field app lets technicians pull the jobs and equipment assigned to them and work with no signal, which matters inside a refinery unit or on a remote spread.</p><p>For owners who want more than PDFs, our companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places inspection results on a 3D model of the asset, so a plant engineer can see where findings sit on a column or tank rather than reading a table of locations. It is a separate product that works alongside the ERP.</p><p>For technicians building hands-on skill between jobs, <a href=\"/practical-ndt\">Practical NDT</a> offers immersive 3D practice across UT, PAUT, RT, MT, PT, VT, ET and TOFD on virtual welds, pipes, vessels and castings. It opens from the eLearning portal, so a quiet week on the availability calendar can become useful practice time.</p><h2>Setting it up for a US operation</h2><p>Atlantis NDT deploys and configures the ERP for you. For a US inspection company, a typical Team Assignments setup covers loading technicians with their SNT-TC-1A or CP-189 certifications, loading instruments and radiography equipment by serial with current calibration dates, connecting Time Off so approved leave blocks dispatch, setting up branches and access rights, and agreeing any extra checks you need, such as TWIC, OQ or site orientation tracking. We train your coordinators on your own live jobs.</p><p>The system is fully customizable and pricing is quote on request, kept affordable for small shops as well as multi-branch companies. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20USA\">Book a Team Assignments demo</a> and we will show it with a sample of your crew.</p><h2>Frequently asked questions</h2><h3>Can it stop me sending the same technician to two plants during a turnaround?</h3><p>Yes. Once a technician is assigned for a set of dates, any overlapping assignment or availability entry is blocked. The same applies to equipment serial numbers, so one PAUT set or exposure device cannot be booked on two jobs at the same time.</p><h3>Does it track SNT-TC-1A and CP-189 certifications?</h3><p>The Certificates app does. It records scheme, level, method, certifying body and expiry for each technician, flags certs expiring within 90 days and sends configurable daily email alerts. Timesheets warn if a technician's cert is not valid.</p><h3>Can it enforce the two-person rule for radiography?</h3><p>Not out of the box. You can book both people and the exposure device on the same assignment, and the employee profile shows radiation safety training and badge numbers. A rule that blocks a one-person RT assignment can be added during implementation.</p><h3>Can it track TWIC cards and site orientations?</h3><p>Site induction and work permit fields are on each project. Per-technician tracking of TWIC and orientation expiry is configured during implementation, as part of the customization scope agreed with you.</p><h3>Does it help with overtime billing?</h3><p>Yes, through Timesheets. Hours carry a work type, billable flag and rate multiplier, and they feed Invoicing, where labour, equipment and consumables are split out.</p><h3>What does it cost?</h3><p>Quote on request. Pricing depends on users, apps and customization. We keep it affordable and accessible for US inspection companies of all sizes.</p><h2>Plan your next turnaround in it</h2><p>If your next busy season is already filling up, now is the time to move dispatch off the whiteboard. Tell us how many technicians you run, which methods and which regions you cover, and we will show you a realistic week of Gulf Coast dispatch in Team Assignments. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20quote%20USA\">Request a quote</a> or book a walkthrough with our team.</p>\n<h2>Team Assignments by region</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments global overview</a></li><li><a href=\"/erp/apps/team-assignments/canada\">Team Assignments in Canada</a></li><li><a href=\"/erp/apps/team-assignments/europe\">Team Assignments in UK &amp; Europe</a></li><li><a href=\"/erp/apps/team-assignments/middle-east\">Team Assignments in Middle East</a></li><li><a href=\"/erp/apps/team-assignments/india\">Team Assignments in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(United%20States)\">Send an enquiry about Team Assignments</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/team-assignments/canada","publishedAt":"2026-09-27","title":"NDT Crew Scheduling Software in Canada | Atlantis NDT","description":"NDT crew scheduling for oil sands rotations, nuclear outages and pipeline work in Canada. Block double-bookings and flag out-of-cal kit. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Crew Dispatch and Technician Scheduling in Canada</h1>\n<p>Assign qualified technicians and crews to jobs by method, level and availability. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(Canada)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Why NDT scheduling in Canada is different</h2><p>An NDT company in Canada plans around three things that most other markets do not face all at once: distance, winter and rotation. A technician in Edmonton may fly north to a site camp for two weeks, fly home for two, and then drive to an upgrader in the Industrial Heartland for a spring turnaround. An Ontario crew may spend months preparing for a single nuclear outage window. A pipeline crew in northern Alberta or British Columbia may only be able to work some sections when the ground is frozen.</p><p>Add Canadian certification rules, where many clients expect technicians certified through the Natural Resources Canada scheme, and radiography licensed by the Canadian Nuclear Safety Commission, and the dispatcher's job becomes a matter of fitting qualified people, calibrated equipment and fixed rotation patterns into windows that do not move.</p><p>Team Assignments, part of <a href=\"/erp\">Atlantis NDT ERP</a>, is built for that kind of planning. Each job is a team assignment with a site, GPS coordinates, mobilisation and demobilisation dates, a crew and a list of equipment serial numbers. The technician availability calendar holds assigned, leave, training, sick and unavailable time, and blocks overlaps. Technicians and equipment cannot be double-booked, and the app warns when assigned equipment is out of calibration. Every technician shows a status, current assignment, utilisation percentage and next available date, and the whole plan can be viewed as a calendar, a kanban board or a list. Jobs move through five stages: planned, dispatched, in field, submitted and closed.</p><h2>Oil sands rotations and camp-based work</h2><p>Work in the Athabasca oil sands around Fort McMurray, and at in-situ projects further south, is built on rotations. Fly-in, fly-out schedules such as 14 days on and 14 off, 10 and 4, or 21 and 7 are common, with crews moving on charter flights from Edmonton, Calgary and other hubs and living in site camps. For an NDT company, a technician on rotation is committed for the whole hitch, and the days off are not available for another job in the city unless the technician agrees.</p><p>That makes the difference between leave and unavailable important. In Team Assignments, the hitch is the assignment, with mobilisation and demobilisation dates matching the charter days, so travel sits inside the booking. Rotational days off can be recorded as unavailable, which keeps them out of the dispatch pool without counting them as annual leave. Overlaps are blocked, so nobody accidentally books a technician for a Fort Saskatchewan job during the week they are supposed to be resting at home.</p><p>Camp work also means equipment leaves the yard for weeks at a time. Once an instrument is booked on a rotation job by serial number, it cannot be booked on another assignment for the same dates. The calibration warning matters more here than almost anywhere: a flaw detector whose calibration falls due mid-rotation is a problem you want to find before it goes north, not when a replacement has to be flown in. Calibration due dates come from the <a href=\"/erp/apps/asset-management\">Asset Management app</a>.</p><p>Utilisation shows how much of each technician's time is tied up in rotations, which helps when a client asks for extra crew on the next hitch and you need to know whether you can say yes.</p><h2>Turnaround windows and working through winter</h2><p>Refineries, upgraders and petrochemical plants in Alberta's Industrial Heartland north-east of Edmonton, and plants in Sarnia and elsewhere, usually schedule turnarounds for spring and fall. Few owners want to open major units in January at minus 30. That concentrates demand into a few months, and every NDT contractor in the province is looking for the same UT, PAUT and RT technicians at the same time.</p><p>Winter brings its own work. Some pipeline and northern projects are only accessible once muskeg and ice roads freeze, so construction and tie-in inspection shift into the cold months. Cold also affects the work itself: couplants, penetrants and magnetic particle media all have temperature limits, batteries run down faster, and set-up takes longer. Planners need to allow for that in the dates they promise.</p><p>Team Assignments helps a Canadian dispatcher in two ways. Ahead of turnaround season, the calendar and next available dates show real capacity months out, so commitments to owners are based on actual availability. During the season, the kanban view shows at a glance how many jobs are planned but not dispatched, how many crews are in the field and which submitted jobs are waiting on report review before they can be closed and invoiced. Mobilisation dates can be moved when a unit shutdown slips, and any new overlap with later jobs is blocked, not buried.</p><h2>CGSB and NRCan ISO 9712 certification</h2><p>In Canada, many owners and codes expect NDT personnel to be certified under the national scheme run by Natural Resources Canada to CAN/CGSB-48.9712, the Canadian adoption of ISO 9712. It is a third-party scheme: the certification belongs to the technician, is issued by NRCan, and must be renewed and recertified on a fixed cycle, with vision checks along the way. US-owned operators and some fabricators also ask for ASNT-based employer certification, so plenty of Canadian technicians hold both.</p><p>Atlantis NDT does not train or certify for the NRCan scheme, but the ERP records those certificates. The <a href=\"/erp/apps/certificates\">Certificates app</a> stores each certification with its scheme (ISO 9712, SNT-TC-1A, CP-189 and others), level, method, certifying body, issue, expiry and renewal dates, OJT and training hours, and attachments. Status is calculated automatically as active, expiring soon, expired or revoked, and warning tasks appear 90 days before a cert or vision test expires. Daily email alerts can go to the Level 3, the QA manager and the dispatcher.</p><p>That matters at dispatch time. The coordinator building a crew for a pressure vessel repair can check who holds current NRCan UT Level 2 before adding them, and Timesheets warn if a technician's certification is not valid when hours are booked. If you want Team Assignments itself to check a technician's certificate against the method on the job, that can be configured during implementation.</p><h2>Radiography under the CNSC</h2><p>Industrial radiography in Canada is regulated federally by the Canadian Nuclear Safety Commission. Anyone operating an exposure device must be a CNSC-certified exposure device operator, and trainees work under the direct supervision of a certified operator. Radiography crews are typically nuclear energy workers with dose monitoring, and sources moving by road fall under Transportation of Dangerous Goods rules as well as CNSC packaging and transport regulations.</p><p>For scheduling, an RT job needs a certified exposure device operator, often a trainee or second worker, a specific exposure device, survey meters and a vehicle cleared for sources. Team Assignments books the people and the equipment serials on the same assignment, blocks the camera or meter from being booked on two jobs at once, and warns if an assigned survey meter or other instrument is out of calibration.</p><p>Each technician's NDT profile records radiation safety training and radiation badge number, and exposure device operator certificates can be recorded in Certificates with their expiry, so they trigger the same 90-day warnings as NDT certs. The Fleet app flags whether a vehicle can carry radioactive sources and holds its transport licence number and expiry, and vehicles are assigned to projects with dates and mileage.</p><p>The app does not replace your radiation protection programme or your licence conditions. It makes sure the dispatcher sees the right information at the moment they are putting a crew together.</p><h2>ABSA, CSA standards and pipeline work</h2><p>In Alberta, pressure equipment is regulated by ABSA, and repairs, alterations and new construction follow quality programmes that ABSA has accepted. Across Canada, CSA B51 governs boilers and pressure vessels, CSA W59 covers welded steel construction, and CSA Z662 sets the rules for oil and gas pipeline systems, with provincial regulators such as the Alberta Energy Regulator and the federal Canada Energy Regulator overseeing pipelines in their jurisdictions.</p><p>These codes shape the job, and the job shapes the crew. A Z662 tie-in may need RT or AUT crews synchronised with welding; a pressure equipment repair may need NDT booked around an inspector's witness point. The Project app holds the codes, methods, scope and acceptance criteria for each NDT job, while Team Assignments holds when it happens and who does it.</p><p>Pipeline and well-site work in western Canada often happens at locations described by legal land descriptions rather than street addresses. Recording site GPS coordinates on each assignment means the crew and the office know exactly which lease, dig or valve site they are heading to, which saves a lot of driving around gravel roads in the dark.</p><h2>Ontario nuclear outages</h2><p>Ontario's nuclear fleet, including the Bruce, Darlington and Pickering stations, runs planned outages for maintenance and refurbishment. For NDT contractors, outage work means long lead times, security clearances, site-specific radiation protection and orientation training, dose limits for each worker and very little tolerance for crews arriving late or short.</p><p>The planning horizon is months, not days. Team Assignments supports that by letting you book the outage crew early and keep them blocked. Pre-outage training and orientation days go into the availability calendar as training, so the dispatcher cannot quietly send an outage technician on a short job that runs into their orientation week. Time waiting on clearance processing can be held as unavailable.</p><p>Because every assignment carries mobilisation and demobilisation dates, the office can see exactly when outage crews become free, and the next available date on each technician tells sales when they can promise that person to another client. Utilisation shows whether committing so much of the team to one outage leaves enough capacity for the rest of your clients.</p><h2>Site access, safety tickets and language</h2><p>Canadian owners expect more than NDT certs. Many require contractors to hold a Certificate of Recognition safety programme, and in the energy sector crews are often asked for orientations and tickets such as a basic safety orientation, H2S Alive and site-specific training, all with expiry dates that owners check at the gate.</p><p>The Project app records safety induction and work permit fields for each job, so site requirements live with the job. Per-technician tracking of tickets such as H2S Alive, and flagging a missing ticket at dispatch, is configured during implementation as part of the customization scope agreed with you.</p><p>For companies working in Quebec or with bilingual crews, the underlying Odoo platform supports French as a user language, so coordinators and technicians can work in the language they prefer. Client-facing documents can be set up to suit your clients during implementation.</p><h2>How it connects to the rest of the ERP</h2><p>Team Assignments sits between the sale and the invoice. Upstream, Quotations and Project hold the scope, codes and client PO. Downstream, technicians log hours in Timesheets by work type (inspection, travel, standby, setup), which is useful when a weather-delayed charter turns a travel day into standby. Hours carry a billable flag and rate multiplier and flow into Invoicing, where labour, equipment and consumables are split out and GST, HST or PST are configured for your provinces during implementation. Camp allowances and field expenses go through Expenses for re-billing.</p><p>In the field, the NDT Reports offline app lets technicians pull the jobs and equipment assigned to them and write reports without signal, which is normal up north. Owners who want to see results in context can use our companion product, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, which places inspection results on a 3D model of the asset. It is a separate product that works alongside the ERP.</p><p>For trainee technicians building hands-on skill, <a href=\"/practical-ndt\">Practical NDT</a> gives immersive 3D practice in UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings, opened from the eLearning portal. Quiet weeks between hitches can become useful practice time without anyone travelling.</p><h2>Setting it up in Canada</h2><p>Atlantis NDT deploys and configures the ERP for you. A Canadian setup usually covers loading technicians with their NRCan, ASNT and CNSC certificates, loading equipment by serial with calibration dates, defining how rotations and rotational days off are recorded, connecting Time Off so approved leave and statutory holidays affect availability, setting access rights for branches in, say, Edmonton, Calgary and the GTA, and agreeing extra checks such as safety tickets. Coordinators are trained on their own live jobs.</p><p>It is fully customizable, and pricing is quote on request, kept affordable for small and mid-sized Canadian inspection companies. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20Canada\">Book a Team Assignments demo</a> to see it with your own rotation.</p><h2>Frequently asked questions</h2><h3>Can it handle 14 and 14 rotations?</h3><p>Yes. Book the hitch as an assignment with mobilisation and demobilisation dates on the charter days, and record rotational days off as unavailable. Overlaps are blocked, so the technician cannot be dispatched elsewhere during the hitch or their rest days without the clash being dealt with.</p><h3>Does it record NRCan ISO 9712 certifications?</h3><p>Yes, in the Certificates app, with level, method, certifying body and expiry, plus 90-day warnings and daily email alerts. Atlantis NDT does not provide NRCan training or certification; the ERP only records certificates your technicians hold.</p><h3>Can it track CNSC exposure device operator certificates?</h3><p>Yes. They can be recorded in Certificates with their expiry so they trigger the same warnings, and each technician's profile holds radiation safety training and badge number.</p><h3>Will it stop an out-of-calibration instrument going north?</h3><p>It warns you when assigned equipment is out of calibration, based on the calibration records in Asset Management, so you can swap the unit before it leaves the yard.</p><h3>Does it support French?</h3><p>The Odoo platform supports French as a user language. Templates and client-facing documents are set up to suit you during implementation.</p><h3>How much does it cost?</h3><p>Quote on request, based on users, apps and customization. Affordable, accessible and fully customizable.</p><h2>Plan your next hitch in it</h2><p>Send us your rough numbers: technicians, methods, rotations and regions. We will set up a demo that shows a realistic Canadian week, from a spring turnaround to a northern rotation. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20quote%20Canada\">Request a quote</a> or book a walkthrough.</p>\n<h2>Team Assignments by region</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments global overview</a></li><li><a href=\"/erp/apps/team-assignments/usa\">Team Assignments in United States</a></li><li><a href=\"/erp/apps/team-assignments/europe\">Team Assignments in UK &amp; Europe</a></li><li><a href=\"/erp/apps/team-assignments/middle-east\">Team Assignments in Middle East</a></li><li><a href=\"/erp/apps/team-assignments/india\">Team Assignments in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(Canada)\">Send an enquiry about Team Assignments</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/team-assignments/europe","publishedAt":"2026-09-27","title":"NDT Crew Scheduling Software, UK & Europe | Atlantis NDT","description":"Plan NDT crews for North Sea rotations and European turnarounds with availability, clash checks and calibration warnings. Book a demo today.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Crew Dispatch and Technician Scheduling in the UK and Europe</h1>\n<p>Assign qualified technicians and crews to jobs by method, level and availability. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(UK%20%26%20Europe)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Scheduling NDT crews across the UK and Europe</h2><p>An NDT company working in the UK and Europe schedules across very different kinds of work. Offshore, crews run fixed rotations on North Sea installations and are at the mercy of helicopters and weather. Onshore, refineries, chemical parks and power stations pack their turnarounds into short spring and autumn windows. Fabrication shops building pressure equipment under the Pressure Equipment Directive need suitably approved personnel at specific inspection points. And across all of it sit third-party certification schemes, working time rules, cross-border paperwork and data protection law.</p><p>Most companies still hold the plan in a spreadsheet and a coordinator's memory. That works until a helicopter is cancelled for three days of fog and the whole next fortnight shifts, or until a technician's PCN certificate is found to have lapsed during a client audit.</p><p>Team Assignments, part of <a href=\"/erp\">Atlantis NDT ERP</a>, gives you one scheduling record for every job: site and GPS coordinates, mobilisation and demobilisation dates, the crew and the equipment serial numbers. Jobs move through planned, dispatched, in field, submitted and closed. A technician availability calendar records assigned, leave, training, sick and unavailable time and blocks overlaps. Technicians and equipment serials cannot be double-booked, and the app warns when assigned equipment is out of calibration. Each technician shows status, current assignment, utilisation percentage and next available date, in calendar, kanban and list views.</p><h2>North Sea rotations out of Aberdeen</h2><p>Offshore inspection on the UK Continental Shelf is organised around rotations such as two weeks on and three off, or three and three, with crews flying from Aberdeen, Sumburgh or Norwich, and in the Norwegian, Dutch and Danish sectors from hubs such as Stavanger, Bergen, Den Helder and Esbjerg. Every technician needs current offshore survival and emergency training, typically OPITO BOSIET or its FOET refresher, and a valid offshore medical before they can go on the manifest. Bed space is limited, so the operator often decides how many people you can send. Recording offshore training and medical expiry per technician, and checking them at dispatch, is typically configured during implementation; the employee NDT profile already holds medical fitness expiry.</p><p>In Team Assignments, each trip is an assignment with a mobilisation date on the flight day and a demobilisation date on the planned return. Installations can be pinned with GPS coordinates, which helps when an assignment covers a normally unattended installation visited from a nearby host. Rotational rest periods can be recorded as unavailable so they do not look like spare capacity.</p><p>The real value shows when weather intervenes. When fog or wind holds flights and a crew's return slips by three days, you move the demobilisation date. If that now overlaps the next job for any of those technicians, the overlap is blocked, and the coordinator sees exactly which later assignment has to be re-crewed. On a spreadsheet, that clash usually surfaces when the second client calls to ask where the crew is.</p><p>Equipment goes offshore for the whole trip. Once booked by serial number it cannot be booked elsewhere, and the calibration warning helps you avoid sending a gauge whose calibration lapses mid-trip, when replacing it means another helicopter seat.</p><h2>Onshore turnarounds in Europe's industrial clusters</h2><p>Onshore, the busiest NDT work follows turnaround calendars at refineries and chemical sites: the Rotterdam and Antwerp port clusters, German chemical parks along the Rhine, Teesside and the Humber in the UK, and sites around the Mediterranean. Operators plan major shutdowns years ahead but confirm scopes late, and many cluster them in spring and autumn to avoid winter weather and summer holiday staffing gaps. For contractors, that means peaks where every Level 2 in the region is in demand and cross-border crews are common.</p><p>When a Dutch contractor takes Belgian or German work, or a UK company sends crews to the continent, planning gets harder: travel days, accommodation, different site inductions and the paperwork of posting workers abroad. Mobilisation and demobilisation dates on each assignment keep travel inside the booking, and the next available date on each technician tells your sales team when a named person can start a new job.</p><p>The kanban view is where operations managers watch the season: planned jobs still waiting for crews, jobs dispatched, crews in field, and submitted jobs waiting for report review before they can be closed and invoiced. When a client asks for four more technicians at short notice, the calendar shows who is actually free, rather than who you think is free.</p><h2>EN ISO 9712, PCN and PED personnel requirements</h2><p>In Europe, NDT personnel are usually certified under EN ISO 9712 by an independent certification body. In the UK the best known is PCN, administered by BINDT; across the continent national schemes operate in most countries. Certification belongs to the individual, is valid for a fixed period, needs renewal and later recertification, and requires a regular near vision check. Some clients, particularly US-owned operators, also accept or ask for ASNT-based employer certification, and welding inspection staff may hold CSWIP.</p><p>The Pressure Equipment Directive 2014/68/EU adds a specific requirement: for permanent joints on pressure equipment in categories III and IV, NDT personnel must be approved by a third-party organisation recognised by a Member State. So the right certificate is not a nice-to-have on PED work. It decides whether the inspection counts.</p><p>Atlantis NDT does not provide ISO 9712, PCN or CSWIP training or certification. The ERP records them. The <a href=\"/erp/apps/certificates\">Certificates app</a> holds each technician's scheme, level, method, sector, certifying body and dates, calculates status as active, expiring soon, expired or revoked, and creates warnings 90 days before a cert or vision test expires, with configurable daily email alerts. Timesheets warn if a technician's cert is not valid. Coordinators use it alongside Team Assignments to confirm the right person is going to the right job; building a direct cert check into the assignment itself is available as part of the customization scope agreed with you.</p><h2>Standards on the job sheet</h2><p>The job itself is framed by European standards: EN ISO 17640 for ultrasonic testing of welds, EN ISO 17636 for radiographic testing of welds, EN ISO 17638 and EN ISO 23278 for magnetic particle testing and its acceptance levels, EN ISO 3452 for penetrant testing and EN ISO 17637 for visual testing, plus product standards and client specifications. Acceptance levels differ from job to job, and a technician qualified in one sector may not be what the client needs in another.</p><p>The Project app records methods, codes, scope and acceptance criteria for each NDT job, and tasks carry procedure and WPS references. Team Assignments then carries who goes and with what. Keeping both linked means the crew sent to a PED vessel job is picked while looking at the codes and sector on that job, not from memory.</p><h2>Working time, posted workers and cross-border crews</h2><p>European working time rules shape what a feasible schedule looks like. The EU Working Time Directive sets a 48-hour average weekly limit and minimum daily and weekly rest; in the UK, the Working Time Regulations apply the same principles, with an individual opt-out possible. Offshore work has its own arrangements. Turnarounds with long shifts need to be planned so crews get their rest and are not rolled straight from one shutdown into the next.</p><p>Team Assignments helps by making each technician's run of work visible. The calendar shows back-to-back assignments at a glance, and utilisation highlights the people being run hardest. Hours booked in Timesheets, with work types for inspection, travel, standby and setup, give you the record to check against. Automatic working time checks are not built in; if you need them, they can be configured during implementation.</p><p>Cross-border work brings its own admin: posted worker notifications in the host country and A1 certificates for social security within the EU, and since Brexit, visas or permits for some UK and EU movements. Recording these as part of a job's paperwork can be set up alongside the Project app's safety induction and work permit fields, and the time needed to arrange them can be held on the calendar as unavailable.</p><h2>Radiography under IRR17 and national regulators</h2><p>Site radiography in Great Britain falls under the Ionising Radiation Regulations 2017, enforced by the HSE, which require the employer to hold the appropriate consent for industrial radiography, appoint a Radiation Protection Adviser and Radiation Protection Supervisors, and monitor classified workers. Across the EU, the Basic Safety Standards Directive 2013/59/Euratom is implemented by national regulators. Sources travel by road under ADR. Radiography is often done at night or at weekends to keep plant areas clear.</p><p>For scheduling, every RT assignment needs qualified people, a specific exposure container, survey meters and a suitable vehicle. Team Assignments books them together and blocks the container or meters from being on two jobs at once. It warns if a survey meter or other assigned equipment is out of calibration, based on the records in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>.</p><p>The employee NDT profile records radiation safety training and badge number. The Fleet app flags vehicles that can carry radioactive sources, with their transport licence number and expiry. Night shifts can be planned as separate assignments so the calendar shows exactly who is on nights and needs rest before the next day shift.</p><h2>GDPR and technician personal data</h2><p>A scheduling system holds personal data: names, contact details, certifications, medical fitness dates, radiation badge numbers and, in the availability calendar, entries such as sick leave. Under the UK GDPR and the EU GDPR, health-related information is special category data and needs extra care. You, as the employer, are the data controller.</p><p>Team Assignments and the wider ERP give you controls to work with. Access rights are set by role during implementation, so a technician sees their own jobs, a supervisor sees their crew, and only the people who need it can see why someone is unavailable. Many companies choose to record sickness simply as sick in the scheduling calendar, with no medical detail, keeping any fuller records in HR. Certificates and vision test files can be restricted to QA and HR roles.</p><p>Where the system is hosted, how long records are kept and who can export them are decisions we agree with you during implementation. The ERP does not make you GDPR compliant on its own; it gives you a controlled place for the data instead of spreadsheets forwarded around by email, which is where most leaks begin.</p><h2>Who uses it day to day</h2><p>Offshore coordinators in Aberdeen or Stavanger live in the calendar view, building crews and moving dates when the weather bites. Onshore operations managers use the kanban board to watch turnaround jobs move from planned to closed. Level 3s and QA managers work from the Certificates app to confirm who is qualified for each sector and method. Sales teams check next available dates before promising a start. Owners watch utilisation to decide whether to hire, subcontract or push sales for a quiet method. Technicians see their own assignments, and access rights mean each person sees what their role needs and nothing more.</p><h2>How it connects: reports, digital twins and skills</h2><p>Once work is submitted, the NDT Reports app takes over, with method-specific reports and an offline field app that pulls the jobs and equipment assigned to each technician and works without signal, which is useful offshore and deep inside a plant. Hours flow from Timesheets into Invoicing, with VAT configured for your countries during implementation, and expenses and per diems go through Expenses.</p><p>For owners who want inspection data in context, <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a>, our companion product, places inspection results on a 3D model of the asset. It works alongside the ERP as a separate product.</p><p>For trainees building hands-on skill, <a href=\"/practical-ndt\">Practical NDT</a> offers immersive 3D practice in UT, PAUT, RT, MT, PT, VT, ET and TOFD scenarios on virtual welds, pipes, vessels and castings, opened from the eLearning portal. It is practice, not certification, and it fits well into the gaps between rotations.</p><h2>Setting it up for UK and European operations</h2><p>Atlantis NDT deploys and configures the ERP for you. A typical setup loads technicians with their ISO 9712, PCN and other certificates, loads equipment by serial with calibration dates, defines offshore rotation patterns, connects Time Off so leave and public holidays in each country affect availability, sets role-based access with GDPR in mind, and agrees any extra checks, such as offshore training and medical tracking. Coordinators are trained on their own live jobs.</p><p>It is fully customizable, and pricing is quote on request, kept affordable for small and mid-sized inspection companies. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20Europe\">Book a Team Assignments demo</a> to see your own rotation in it.</p><h2>Frequently asked questions</h2><h3>Can it cope when a helicopter delay pushes a crew's return?</h3><p>Yes. Move the demobilisation date and any overlap with later assignments for that crew is blocked, so the coordinator sees immediately which jobs need re-crewing.</p><h3>Does it record PCN and EN ISO 9712 certificates?</h3><p>Yes, in the Certificates app, with 90-day expiry warnings and daily email alerts. Atlantis NDT does not provide PCN or ISO 9712 training or certification; the ERP records certificates your technicians hold.</p><h3>Can it enforce Working Time rules?</h3><p>Not automatically out of the box. The calendar and utilisation make long runs of work visible, and Timesheets record hours. Automated working time checks can be configured during implementation.</p><h3>How does it handle GDPR?</h3><p>Access rights are set by role, sensitive entries such as sickness can be kept minimal, and hosting and retention are agreed with you. The ERP supports your compliance; it does not replace it.</p><h3>Will it flag equipment going offshore out of calibration?</h3><p>Yes. It warns when assigned equipment is out of calibration, based on the calibration records in Asset Management.</p><h3>What does it cost?</h3><p>Quote on request, depending on users, apps and customization. Affordable, accessible and fully customizable.</p><h2>See your next rotation in it</h2><p>Tell us how many technicians you run, which sectors and which countries, and we will set up a demo around a realistic fortnight of offshore and onshore work. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20quote%20Europe\">Request a quote</a> or book a walkthrough.</p>\n<h2>Team Assignments by region</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments global overview</a></li><li><a href=\"/erp/apps/team-assignments/usa\">Team Assignments in United States</a></li><li><a href=\"/erp/apps/team-assignments/canada\">Team Assignments in Canada</a></li><li><a href=\"/erp/apps/team-assignments/middle-east\">Team Assignments in Middle East</a></li><li><a href=\"/erp/apps/team-assignments/india\">Team Assignments in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(UK%20%26%20Europe)\">Send an enquiry about Team Assignments</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/team-assignments/middle-east","publishedAt":"2026-09-27","title":"NDT Crew Scheduling Software, Middle East | Atlantis NDT","description":"Dispatch NDT crews for Gulf shutdowns and turnarounds with clash-free technician and equipment scheduling. Request a quote or book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Crew Dispatch and Technician Scheduling in the Middle East</h1>\n<p>Assign qualified technicians and crews to jobs by method, level and availability. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(Middle%20East)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>What NDT dispatch looks like in the Gulf</h2><p>An NDT company in Saudi Arabia, the UAE, Qatar, Kuwait or Oman runs a very particular kind of operation. Crews are large and mostly expatriate, drawn from India, Pakistan, the Philippines and elsewhere, on employment visas tied to a sponsor. Work comes in huge waves around plant shutdowns. Sites are spread across hundreds of kilometres of desert and coast, from Jubail and Ras Tanura to Yanbu, Ruwais, Ras Laffan and Ahmadi. And each national oil company has its own approval processes, gate pass systems and standards.</p><p>The result is that a dispatcher has to check far more than who is free. Is the technician approved for this client? Is his residence permit valid, and is he in the right country? Does he have a gate pass for this plant? Is the source vehicle cleared? Is the PAUT unit back from the last shutdown and in calibration? On a spreadsheet, the answers live in five different files.</p><p>Team Assignments, part of <a href=\"/erp\">Atlantis NDT ERP</a>, gives you one scheduling record for every job: site with GPS coordinates, mobilisation and demobilisation dates, crew and equipment serial numbers. Jobs move from planned to dispatched, in field, submitted and closed. A technician availability calendar holds assigned, leave, training, sick and unavailable time and blocks overlaps. Technicians and equipment serials cannot be double-booked, and the app warns when assigned equipment is out of calibration. Each technician shows status, current assignment, utilisation percentage and next available date, in calendar, kanban and list views.</p><h2>Shutdown season and planning around the heat</h2><p>Across the Gulf, major shutdowns and test-and-inspection campaigns at refineries, gas plants and petrochemical complexes are usually planned for the cooler months, roughly October to April. Summer brings extreme heat, and Saudi Arabia, the UAE, Qatar, Kuwait and Oman all enforce midday outdoor work bans through the hottest months. Ramadan shortens working hours, and the Eid holidays take large parts of the workforce out for days. The practical effect is that the whole region competes for the same technicians in a few intense months.</p><p>Planning for that starts early. The calendar in Team Assignments shows real commitments months ahead, so when a plant's shutdown planner asks for forty technicians for a February T&amp;I, you can see who is genuinely available once existing jobs, annual leave and training are counted. The next available date on each technician tells your commercial team exactly when a named Level II can join.</p><p>During the shutdown itself, the kanban view shows how many jobs are still planned but not dispatched, how many crews are in field and which submitted jobs are waiting for report approval before closing. Night and day shifts can be set up as separate assignments, so the calendar shows who is on nights and should not be rostered onto a day job straight after. When a shutdown extends, as they often do, the demobilisation date moves, and any overlap with the crew's next job is blocked, so the clash is visible immediately rather than on the morning the next client expects them.</p><h2>Expatriate crews, iqamas and document-driven availability</h2><p>In the Gulf, a technician's availability depends on paperwork as much as on the diary. A residence permit such as the Saudi iqama must be valid. Leaving the country needs an exit and re-entry visa. A Saudi-sponsored technician cannot simply be sent to a job in Abu Dhabi or Doha without a work visa there. Passports get held for processing. Annual leave home is often three or four weeks at a stretch, tied to the contract anniversary, and flights get changed.</p><p>Team Assignments deals with the diary side directly. Annual vacation approved in Time Off blocks dispatch for those dates. Visa processing days, passport renewals and medicals can be entered as unavailable, so they stop the technician appearing as spare capacity. Overlaps are blocked, so a coordinator cannot book someone on a Ras Tanura job for the week he is flying home.</p><p>Tracking the documents themselves, such as iqama expiry, passport expiry and country-specific work visas, is set up during implementation as part of the customization scope agreed with you, because each company's sponsorship arrangements differ. The employee NDT profile already records medical fitness expiry, radiation safety training and radiation badge number.</p><p>During peak shutdowns, many Gulf contractors top up their crews with technicians hired from manpower suppliers for a few weeks. Those people can be set up as records so their availability, certificates and assignments are tracked like staff, and utilisation shows clearly when they can be released. How their certificates are verified and how they are billed is agreed during implementation.</p><p>Utilisation matters for your own staff too. Large expatriate crews are a fixed cost whether they are on site or in the accommodation. Utilisation per technician shows who has been sitting in camp for weeks and who has done back-to-back shutdowns without a break, which helps with both margin and retention.</p><h2>Client approvals: Saudi Aramco, ADNOC, QatarEnergy, KNPC</h2><p>Each national oil company sets its own rules. Saudi Aramco contractors work to Saudi Aramco Engineering Standards and inspection requirements, and Aramco expects contractors, and often individual NDT technicians, to be approved before they work on its facilities. ADNOC group companies in the UAE, QatarEnergy at Ras Laffan and Mesaieed, and KNPC at its Kuwaiti refineries each have their own contractor registration, personnel approval and site requirements. A technician approved for one client is not automatically approved for another.</p><p>This is exactly where checking by memory fails. In the ERP, the <a href=\"/erp/apps/certificates\">Certificates app</a> records certifications by scheme, including an other category, with level, method, issuing body, issue and expiry dates and attachments. You can use that to record client-specific approvals alongside the technician's ASNT or ISO 9712 certification, so they get the same automatic status and 90-day expiry warnings. Daily email alerts can go to the QA manager and the dispatcher.</p><p>At dispatch, the coordinator builds the crew for a client job while able to see who holds a current approval, and Timesheets warn if a technician's certification is not valid when hours are booked. If you want Team Assignments to block a technician who lacks the approval required for a given client, that rule can be added during implementation.</p><p>None of this implies that any of these companies endorse a particular system. It is simply how Gulf NDT contractors keep their own records straight against their clients' requirements.</p><h2>ASNT and ISO 9712 on the same crew</h2><p>Gulf crews are unusually mixed. Technicians from India may hold ISO 9712 certificates as well as employer certification under ASNT SNT-TC-1A. Others arrive with PCN or with ASNT-based certification from previous employers, which has to be re-established under your own written practice. Some clients specify ASNT, some accept ISO 9712, and some want both.</p><p>The Certificates app handles each certificate as its own record, so a technician can hold several at once, each with its own scheme, level, method and expiry. Vision tests are recorded separately, with near vision, colour perception, examiner and expiry, and they have their own 90-day warning. Examination sheets record general, specific and practical scores against a passing score. That gives your Level III the evidence for each employer certification, and it gives the dispatcher a single place to check before building a crew.</p><p>Atlantis NDT runs training based on ASNT SNT-TC-1A, and training weeks can be entered in the availability calendar as training so dispatch does not book those people.</p><h2>Gate passes, permits and remote desert sites</h2><p>Getting a crew onto a Gulf plant takes planning. Plants require gate passes or site IDs processed in advance, often with copies of residence permits, certificates and safety training records. Many sites require H2S training and site-specific inductions, and every job runs under a permit-to-work system. Lead times vary from days to weeks.</p><p>The Project app holds safety induction and work permit fields for each NDT job, so the requirements live with the job. In Team Assignments, the mobilisation date can allow for pass processing, and induction days can be booked on the calendar. Per-technician gate pass and site ID tracking can be configured during implementation.</p><p>Many jobs are nowhere near a street address: pipeline corridors, wellheads, gas-oil separation plants and desert pumping stations. Site GPS coordinates on each assignment tell the driver exactly where to go, which matters when the difference between two sites is a hundred kilometres of desert road.</p><h2>Radiography crews, night shots and source vehicles</h2><p>Radiography in the region is licensed by national regulators, such as the Nuclear and Radiological Regulatory Commission in Saudi Arabia and the Federal Authority for Nuclear Regulation in the UAE. Plants usually want radiography done at night, with barricades and area clearance, so the rest of the shutdown can carry on during the day. RT crews therefore work their own shifts, with dosimetry and radiation safety training required for everyone involved.</p><p>Team Assignments books the RT crew, the exposure device, survey meters and other equipment on one assignment, blocks any of those serial numbers from being booked on another job for the same dates, and warns if any instrument is out of calibration based on records in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>. The employee NDT profile shows radiation safety training and badge number. The Fleet app records which vehicles can carry radioactive sources, with transport licence number and expiry, and assigns vehicles to projects.</p><p>Equipment also moves long distances between cities and countries. Serial-number booking and the issue and return workflow in Asset Management mean the office knows whether the PAUT unit is in Jubail, in Yanbu or at the calibration lab, and the wear that heat and dust put on instruments shows up in maintenance and calibration records rather than as surprises on site.</p><h2>Who uses it in a Gulf NDT company</h2><p>Operations coordinators in Dammam, Jubail or Abu Dhabi build crews in the calendar view and move jobs through the kanban board. Camp and HR coordinators enter vacations, visa trips and medicals as leave or unavailable so the plan stays honest. QA managers and Level IIIs keep certificates, vision tests and client approvals current in the Certificates app. Equipment controllers issue and receive instruments through Asset Management and chase calibration. Sales and contracts teams check next available dates before committing crew numbers in a bid. Owners watch utilisation to judge whether to add manpower before the next shutdown season or release hired technicians when it ends. Access rights are set by role, so each person sees what they need and technicians see only their own jobs.</p><h2>Invoicing, Arabic and the rest of the ERP</h2><p>Once crews are in the field, hours go into Timesheets with work type, method, site and equipment serial, a billable flag and a rate multiplier for overtime or night shifts. Those hours feed Invoicing, which splits labour, equipment and consumables. VAT is configured for each country during implementation using standard Odoo tax features; we make no certification claim for any e-invoicing regime, and local requirements are handled as part of the implementation scope. The underlying Odoo platform supports Arabic, so users can work in Arabic or English.</p><p>In the field, the NDT Reports offline app lets technicians pull their assigned jobs and equipment and work without signal. For owners who want results in context, our companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places inspection results on a 3D model of the asset, working alongside the ERP as a separate product.</p><p>For trainees building hands-on skill, <a href=\"/practical-ndt\">Practical NDT</a> offers immersive 3D practice in UT, PAUT, RT, MT, PT, VT, ET and TOFD on virtual welds, pipes, vessels and castings, opened from the eLearning portal. It suits the summer months, when outdoor work slows and crews have time to practise.</p><h2>Setting it up in the Gulf</h2><p>Atlantis NDT deploys and configures the ERP for you, with a team that knows how Gulf NDT contractors operate. Setup typically covers loading technicians with ASNT, ISO 9712 and client approvals, loading equipment by serial with calibration dates, connecting Time Off for annual vacation, setting up branches in different cities or countries, access rights, VAT per country, and any extra checks you need, such as residence permit or gate pass tracking. Coordinators are trained on live jobs.</p><p>It is fully customizable, with pricing quote on request and kept affordable. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20Middle%20East\">Book a Team Assignments demo</a> to see your own shutdown crew in it.</p><h2>Frequently asked questions</h2><h3>Can it stop the same technician being booked on two shutdowns?</h3><p>Yes. Overlapping assignments and availability entries are blocked for technicians, and the same applies to equipment serial numbers.</p><h3>Can it track iqama and visa expiry?</h3><p>Visa processing and travel can be blocked on the calendar as unavailable. Document expiry tracking per technician is configured during implementation as part of the agreed scope.</p><h3>Can I record Saudi Aramco or ADNOC technician approvals?</h3><p>Yes. Client approvals can be recorded in the Certificates app under the other scheme, with expiry dates that trigger the same 90-day warnings as NDT certificates.</p><h3>Does it handle VAT?</h3><p>VAT is configured for your countries during implementation using standard Odoo tax features. We make no certification claims for any e-invoicing regime; local requirements are part of the implementation scope.</p><h3>Does it work in Arabic?</h3><p>Yes. The Odoo platform supports Arabic as a user language alongside English.</p><h3>What does it cost?</h3><p>Quote on request, based on users, apps and customization. Affordable, accessible and fully customizable.</p><h2>Plan your next shutdown in it</h2><p>Tell us your crew size, methods, countries and the kind of plants you work in, and we will build a demo around a realistic shutdown week. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20quote%20Middle%20East\">Request a quote</a> or book a walkthrough.</p>\n<h2>Team Assignments by region</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments global overview</a></li><li><a href=\"/erp/apps/team-assignments/usa\">Team Assignments in United States</a></li><li><a href=\"/erp/apps/team-assignments/canada\">Team Assignments in Canada</a></li><li><a href=\"/erp/apps/team-assignments/europe\">Team Assignments in UK &amp; Europe</a></li><li><a href=\"/erp/apps/team-assignments/india\">Team Assignments in India</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(Middle%20East)\">Send an enquiry about Team Assignments</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"},{"path":"/erp/apps/team-assignments/india","publishedAt":"2026-09-27","title":"NDT Crew Scheduling Software in India | Atlantis NDT","description":"NDT crew scheduling for refinery shutdowns, PSU contracts and offshore rotations in India. Stop double-booked techs and kit. Book a demo.","bodyContent":"<header><nav aria-label=\"Main Navigation\"><a href=\"/\">Home</a><a href=\"/erp\">ERP</a><a href=\"/erp/apps\">ERP Apps</a><a href=\"/digital-twin-reporting\">Digital Twin Reporting</a><a href=\"/practical-ndt\">Practical NDT</a><a href=\"/contact\">Contact</a></nav></header>\n<main>\n<h1>NDT Crew Dispatch and Technician Scheduling in India</h1>\n<p>Assign qualified technicians and crews to jobs by method, level and availability. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(India)\">Request a demo</a>. Affordable. Accessible. Fully customizable. Quote on request.</p>\n\n<h2>Scheduling NDT crews in India</h2><p>An Indian NDT company typically works for a mix of clients that could hardly be more different: public sector refineries and gas companies with tender-driven contracts, large private refining and petrochemical complexes, power utilities, fabrication shops building IBR boilers and PESO-regulated vessels, and offshore platforms off the west coast. Crews travel long distances by road, rail and air. Many technicians also go abroad on Gulf contracts for months at a time, then come back and expect work.</p><p>The dispatcher's job is to fit that together: the right certified people, with the right approvals, carrying calibrated equipment, to a site that may be two days' travel away, on dates that a client's shutdown plan fixes months ahead and then changes at a week's notice. Most companies still manage it with Excel, WhatsApp groups and the coordinator's memory.</p><p>Team Assignments, part of <a href=\"/erp\">Atlantis NDT ERP</a>, puts every job in one scheduling record: site and GPS coordinates, mobilisation and demobilisation dates, crew and equipment serial numbers. Jobs move from planned to dispatched, in field, submitted and closed. The technician availability calendar holds assigned, leave, training, sick and unavailable time, and overlaps are blocked. Technicians and equipment serials cannot be double-booked, and the app warns when assigned equipment is out of calibration. Each technician shows status, current assignment, utilisation percentage and next available date, in calendar, kanban and list views.</p><h2>Refinery shutdowns, the monsoon and festival season</h2><p>India's refineries and petrochemical complexes, from Jamnagar and Vadodara in Gujarat to Panipat, Mathura, Mumbai, Kochi, Visakhapatnam, Paradip and Bongaigaon, run planned shutdowns that bring sudden demand for large NDT crews. Owners generally avoid the south-west monsoon for major outdoor work, since heavy rain between June and September makes scaffolded, outdoor inspection slow and sometimes impossible, especially on the west coast. That pushes shutdowns into the drier months, when the whole industry is looking for UT, RT and PAUT technicians at once.</p><p>The festival season adds another constraint. Around Diwali and other major festivals, many technicians travel home, sometimes across the country, and a crew that looks full on paper can be half empty. Leave approved in Time Off feeds the availability calendar, so festival leave blocks dispatch for those dates instead of being discovered on the day.</p><p>Ahead of shutdown season, the calendar shows real commitments months ahead, and the next available date on each technician tells your commercial team when named people can join. During the shutdown, the kanban view shows jobs still planned, crews in field and submitted jobs waiting for report approval before closing and invoicing. When a shutdown extends, move the demobilisation date; any overlap with the crew's next job is blocked, so the clash is visible immediately.</p><p>Utilisation per technician shows who has been idle between shutdowns and who has done back-to-back jobs without a break, which helps with both margins and keeping good people.</p><h2>PSU tenders and named personnel</h2><p>Public sector undertakings such as IOCL, BPCL, HPCL, ONGC, GAIL and NTPC buy NDT services mostly through tenders. Tender documents commonly require contractors to name the technicians they will deploy and submit their CVs and certificates, and substituting a named person later often needs the client's approval. Some contracts include penalties for delay or for deploying unapproved staff.</p><p>That turns scheduling into a commercial issue. If the Level II you named in the bid is on another job when the work order arrives, you either delay or ask for a substitution. Team Assignments helps at both stages. At bid time, next available dates and the calendar show which qualified people you can realistically commit for the contract period. When the work order comes, the named technicians can be assigned and blocked, and nobody else can book them over those dates.</p><p>The <a href=\"/erp/apps/certificates\">Certificates app</a> holds the evidence: each technician's scheme, level, method, certifying body, dates and certificate files, ready to attach to a bid or show during a client audit. PSU work also generates a lot of documentation at closure, and moving a job from submitted to closed only once reports are approved gives you a clean record of who worked on which contract and when.</p><p>None of this implies that any PSU endorses a particular system. It is simply how contractors keep their own records straight against their clients' requirements.</p><h2>ONGC offshore and west coast rotations</h2><p>Offshore inspection on the western offshore fields, including the Mumbai High area, runs on rotations, commonly fourteen days on and fourteen off, with crews travelling by helicopter from Mumbai or by supply vessel. Offshore personnel need survival and safety training and medical fitness before mobilisation, and the monsoon affects flying and marine operations.</p><p>In Team Assignments each offshore trip is an assignment, with the mobilisation date on the day of travel and demobilisation on the planned return. Rotation days off can be recorded as unavailable so they do not appear as spare capacity. When weather delays a return, move the date; overlaps with the technician's next job are blocked, so the coordinator sees which job needs a replacement.</p><p>Equipment goes offshore for the whole trip. Once booked by serial number it cannot be booked elsewhere, and the calibration warning helps you avoid sending a gauge or flaw detector whose calibration falls due while it is on the platform. The employee NDT profile records medical fitness expiry, so the coordinator can see it before finalising the crew. Tracking offshore training expiry per technician can be configured during implementation.</p><h2>ISO 9712 and ASNT certificates side by side</h2><p>Indian technicians very often hold more than one certificate. Many have ISO 9712 certification from a third-party body, many are certified by their employer under an ASNT SNT-TC-1A written practice, and technicians with Gulf experience may bring further certificates from abroad. Clients differ in what they accept: some PSU tenders specify one scheme, international EPCs may want another, and foreign-owned plants often follow ASNT.</p><p>The Certificates app stores each certificate as its own record, with scheme, level, method, certifying body, issue, expiry and renewal dates, OJT and training hours, and attachments. Status is calculated automatically as active, expiring soon, expired or revoked, and warning tasks appear 90 days before expiry. Vision tests, with near vision, colour perception, examiner and clinic, have their own expiry and warnings. Daily email alerts go to the people you choose, and Timesheets warn when a technician's cert is not valid.</p><p>Atlantis NDT offers training based on ASNT SNT-TC-1A only; the ERP simply records ISO 9712 certificates your technicians already hold. Training weeks can be entered in the availability calendar as training so dispatch does not book those people.</p><h2>AERB licensing and radiography crews</h2><p>Industrial radiography in India is regulated by the Atomic Energy Regulatory Board. Radiography institutions need AERB licences, handled through its e-licensing system, with a Radiological Safety Officer designated, qualified radiographers operating the equipment, and personnel monitoring with dosimeter badges. Movement of sources between sites and their transport are controlled, and site radiography is often done at night to keep areas clear.</p><p>For the dispatcher, an RT job is a small package: qualified radiographers, the exposure device, survey meters and a vehicle suitable for carrying the source. Team Assignments books them together on one assignment and blocks the device or meters from being booked on another job for the same dates. It warns if any assigned instrument is out of calibration, based on the records in the <a href=\"/erp/apps/asset-management\">Asset Management app</a>.</p><p>The employee NDT profile records radiation safety training and radiation badge number for each technician. RSO and radiographer qualifications can be recorded in Certificates with expiry dates, so they trigger the same warnings as NDT certificates. The Fleet app records whether a vehicle can carry radioactive sources, with transport licence number and expiry, and assigns vehicles to projects with dates and mileage. The app supports your AERB compliance; it does not replace your licence conditions or your RSO's judgement.</p><h2>IBR, PESO and witness-driven schedules</h2><p>Much Indian NDT work is statutory. Boilers and boiler components fall under the Indian Boiler Regulations, with inspection by Inspecting Authorities or approved competent persons, and pressure vessels for compressed and liquefied gases fall under PESO's Static and Mobile Pressure Vessels (Unfired) Rules. On fabrication jobs, NDT often has to happen at stage inspections witnessed by a third party, and the witness date is fixed by someone else's diary.</p><p>That makes timing tight. A crew that arrives a day after the inspector has left has wasted a trip. With Team Assignments, the mobilisation and demobilisation dates can be set around the witness date, and the coordinator can see straight away which qualified technician is free that day and whether the right calibrated instrument is available. The Project app records codes, methods, scope and acceptance criteria for the job, so the crew goes in knowing what the inspector will expect.</p><p>For fabrication shops running NDT in their own yard alongside field jobs, the same calendar covers both, so the shop Level II is not double-booked between a vessel in the bay and a field job at a client's plant.</p><h2>Gate passes, contract labour records and site documents</h2><p>Indian plants, especially PSU refineries and power stations, have strict entry procedures. Gate passes need identity documents, police verification in many cases, medical fitness, safety induction and proof of statutory contract labour compliance such as provident fund and ESI registration. Passes can take days to process, and a technician without one waits outside while the client's clock runs.</p><p>The Project app holds safety induction and work permit fields for each NDT job. In Team Assignments, the mobilisation date can include pass processing time, and induction days can be booked on the calendar. The employee profile records medical fitness expiry. Per-technician tracking of gate passes, police verification and other documents is set up during implementation as part of the customization scope agreed with you, since every client's list is different.</p><p>Many sites, such as pipeline sections, compressor stations and power project sites, are far from a clean postal address. Recording site GPS coordinates on the assignment tells the crew exactly where to report.</p><h2>DPDP Act and technician personal data</h2><p>India's Digital Personal Data Protection Act, 2023 puts obligations on businesses that process personal data. A scheduling system holds plenty of it: names, phone numbers, identity documents, certificates, medical fitness dates and, in the availability calendar, sick leave. As the employer, you decide what is collected and why.</p><p>The ERP gives you controls. Access rights are set by role during implementation, so technicians see their own jobs, supervisors see their crew, and only HR and QA see personal documents. Sickness can be recorded simply as sick in the scheduling calendar, with any detail kept in HR. Hosting, retention and who can export data are agreed with you. The system supports your compliance; it does not deliver it on its own. Keeping technician data in one controlled place is still far safer than copies of identity cards and certificates circulating in WhatsApp groups.</p><h2>GST invoicing, reports and the rest of the ERP</h2><p>Once crews are in field, hours go into Timesheets with work type (inspection, travel, standby, setup), method, site and equipment serial, a billable flag and a rate multiplier. Hours feed Invoicing, which splits labour, equipment and consumables. GST is configured for your company during implementation using standard Odoo tax features; we make no certification claims for any e-invoicing regime, and local requirements are part of the implementation scope. Travel allowances and site expenses go through Expenses for re-billing to the job.</p><p>In the field, the NDT Reports offline app lets technicians pull their assigned jobs and equipment and work without signal. For owners who want results in context, our companion product <a href=\"/digital-twin-reporting\">Digital Twin Reporting Software</a> places inspection results on a 3D model of the asset and works alongside the ERP as a separate product.</p><p>For trainees building hands-on skill, <a href=\"/practical-ndt\">Practical NDT</a> offers immersive 3D practice in UT, PAUT, RT, MT, PT, VT, ET and TOFD on virtual welds, pipes, vessels and castings, opened from the eLearning portal. Monsoon weeks, when outdoor work slows, are a good time for it.</p><h2>Setting it up in India</h2><p>Atlantis NDT deploys and configures the ERP for you. Setup usually covers loading technicians with ISO 9712 and ASNT-based certificates, loading equipment by serial with calibration dates, connecting Time Off so festival and annual leave affect availability, setting up branches in different states, access rights, GST, and any extra checks you need, such as gate pass or offshore training tracking. Coordinators are trained on their own live jobs.</p><p>It is fully customizable, with pricing quote on request and kept affordable for Indian inspection companies of every size. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20India\">Book a Team Assignments demo</a> to see your own shutdown crew in it.</p><h2>Frequently asked questions</h2><h3>Can it stop named technicians from a PSU bid being booked elsewhere?</h3><p>Yes. Once assigned, a technician cannot be booked on another job or given overlapping leave or training for those dates without the clash being resolved.</p><h3>Does it record ISO 9712 and ASNT certificates?</h3><p>Yes, in the Certificates app, each as its own record with 90-day expiry warnings and daily email alerts. Atlantis NDT provides ASNT SNT-TC-1A-based training only; the ERP simply records ISO 9712 certificates your technicians hold.</p><h3>Can it help with AERB requirements?</h3><p>It records radiation safety training and badge numbers, books exposure devices by serial and flags source-capable vehicles in Fleet. It supports your AERB compliance but does not replace your licence conditions.</p><h3>Does it handle GST?</h3><p>GST is configured during implementation using standard Odoo tax features, with no certification claims for any e-invoicing regime.</p><h3>Can it track gate passes?</h3><p>Site induction and work permit fields are on each project. Per-technician gate pass tracking is configured during implementation.</p><h3>What does it cost?</h3><p>Quote on request, based on users, apps and customization. Affordable, accessible and fully customizable.</p><h2>Plan your next shutdown in it</h2><p>Tell us how many technicians you run, which methods, which states and which kinds of clients, and we will build a demo around a realistic shutdown fortnight. <a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20quote%20India\">Request a quote</a> or book a walkthrough.</p>\n<h2>Team Assignments by region</h2><ul><li><a href=\"/erp/apps/team-assignments\">Team Assignments global overview</a></li><li><a href=\"/erp/apps/team-assignments/usa\">Team Assignments in United States</a></li><li><a href=\"/erp/apps/team-assignments/canada\">Team Assignments in Canada</a></li><li><a href=\"/erp/apps/team-assignments/europe\">Team Assignments in UK &amp; Europe</a></li><li><a href=\"/erp/apps/team-assignments/middle-east\">Team Assignments in Middle East</a></li></ul>\n<h2>Works with</h2><ul><li><a href=\"/erp/apps/project\">Project</a>: Inspection projects, tasks and milestones from award to final report.</li><li><a href=\"/erp/apps/timesheets\">Timesheets</a>: Technician hours per job, feeding payroll and client invoicing.</li><li><a href=\"/erp/apps/asset-management\">Asset Management</a>: NDT equipment by serial number: issue and return, reservations, calibration and maintenance history.</li><li><a href=\"/erp/apps/maintenance\">Maintenance</a>: Preventive and corrective maintenance requests for instruments, vehicles and site equipment.</li><li><a href=\"/erp/apps/fleet\">Fleet</a>: Vehicles, drivers and service records for field crews.</li><li><a href=\"/erp/apps/calendar\">Calendar</a>: Shared schedules for jobs, audits and client meetings.</li><li><a href=\"/erp/apps/to-do\">To-do</a>: Personal and team task lists linked to jobs and records.</li></ul>\n<p><a href=\"/contact?service=erp&amp;subject=Team%20Assignments%20demo%20(India)\">Send an enquiry about Team Assignments</a> · <a href=\"/erp/apps\">All ERP apps</a> · <a href=\"/erp\">Atlantis NDT ERP</a></p>\n</main>"}];
